struct CalendarWorkspaceViewportSnapshot {
    var verticalScrollOffset: CGFloat = 0
    var topVisibleDayString: String?

    var hasSavedPosition: Bool {
        verticalScrollOffset > 0.5 || topVisibleDayString?.trimmedOrNil != nil
    }
}

/// A transient signal used to refresh the currently visible calendar immediately
/// after a calendar-owned record changes. It is deliberately not persisted.
struct CalendarContentUpdate: Identifiable, Equatable {
    let id = UUID()
    let source: CalendarWorkspaceEventSource?
    /// F44: false for a deletion; the calendar then updates the one record
    /// without the highlight pulse (the event is gone).
    var pulses: Bool = true
}

/// Round 17: internal (was private) so tests can check the counting rule;
/// withdrawn applications are their own group and never count as declined.
struct OrganizationApplicationSummary: Equatable {
    var submitted = 0
    var waiting = 0
    var granted = 0
    var rejected = 0
    var withdrawn = 0

    mutating func include(_ application: GrantApplication) {
        submitted += 1
        if application.resultLabel == "Väntar svar" {
            waiting += 1
        }
        if application.isGranted {
            granted += 1
        }
        if AppStatusTones.isDeclined(resultLabel: application.resultLabel) {
            rejected += 1
        } else if AppStatusTones.isWithdrawn(resultLabel: application.resultLabel) {
            withdrawn += 1
        }
    }
}

private extension AppRoute {
    var performanceLabel: String {
        "\(destination.performanceLabel):\(recordID)"
    }
}

private extension AppRoute.Destination {
    var performanceLabel: String {
        switch self {
        case .applications: return "applications"
        case .congresses: return "congresses"
        case .cv: return "cv"
        case .expertAssignments: return "expertAssignments"
        case .publications: return "publications"
        case .projects: return "projects"
        case .teaching: return "teaching"
        case .doctoralCandidates: return "doctoral"
        case .organizations: return "organizations"
        case .people: return "people"
        case .journals: return "journals"
        }
    }
}

