    enum ResearcherProjectRelationKind: String, Equatable {
        case explicitProjectCollaborator
        case publicationAuthor
        case applicationCoApplicant
        case applicationManager

        var countsAsResearchProject: Bool {
            switch self {
            case .explicitProjectCollaborator, .publicationAuthor:
                return true
            case .applicationCoApplicant, .applicationManager:
                return false
            }
        }

        func displayName(language: AppLanguage) -> String {
            switch self {
            case .explicitProjectCollaborator:
                return language.text("Project collaborator", "Projektmedarbetare")
            case .publicationAuthor:
                return language.text("Publication author", "Publikationsförfattare")
            case .applicationCoApplicant:
                return language.text("Application co-applicant", "Medsökande på ansökan")
            case .applicationManager:
                return language.text("Application manager", "Ansvarig på ansökan")
            }
        }
    }

