    struct OrganizationTimelineSnapshot {
        enum GrantStatus: Hashable {
            case rejected
            case withdrawn
            case waiting
            case granted
            case toApply
        }

        enum BarKind: Hashable {
            case congress
            case grantProviderGrant(GrantStatus)
            case fundManagerGrant(GrantStatus)
            case employment
        }

        enum MarkerKind: Hashable {
            case congressAbstractDeadline
            case congressLateAbstractDeadline
        }

        struct Marker: Identifiable {
            let id: String
            let date: Date
            let title: String
            let hoverText: String
            let kind: MarkerKind
            let hasUncertainOutline: Bool
        }

        struct Bar: Identifiable {
            let id: String
            let applicationID: String?
            let start: Date
            let end: Date
            let packingStart: Date
            let packingEnd: Date
            let title: String
            let hoverText: String
            let kind: BarKind
            let rowPackingKey: String?
            let hasUncertainOutline: Bool
            let fullySpentDate: Date?
            let markers: [Marker]

            init(
                id: String,
                applicationID: String?,
                start: Date,
                end: Date,
                title: String,
                hoverText: String,
                kind: BarKind,
                rowPackingKey: String?,
                hasUncertainOutline: Bool,
                fullySpentDate: Date? = nil,
                markers: [Marker] = [],
                packingStart: Date? = nil,
                packingEnd: Date? = nil
            ) {
                self.id = id
                self.applicationID = applicationID
                self.start = start
                self.end = end
                self.title = title
                self.hoverText = hoverText
                self.kind = kind
                self.rowPackingKey = rowPackingKey
                self.hasUncertainOutline = hasUncertainOutline
                self.fullySpentDate = fullySpentDate
                self.markers = markers

                let markerDates = markers.map(\.date)
                self.packingStart = packingStart ?? ([start] + markerDates).min() ?? start
                self.packingEnd = packingEnd ?? ([end] + markerDates).max() ?? end
            }
        }

        struct Group: Identifiable {
            let id: String
            let title: String
            let rows: [[Bar]]

            var bars: [Bar] {
                rows.flatMap { $0 }
            }
        }

        let years: [Int]
        let groups: [Group]

        var isEmpty: Bool {
            groups.allSatisfy { $0.rows.isEmpty }
        }

        static let empty = OrganizationTimelineSnapshot(
            years: [],
            groups: []
        )
    }

