    @Published private(set) var applications: [GrantApplication] {
        didSet {
            invalidateCalendarContentCaches()
            invalidateWorkspaceSearchCache()
            invalidateDataQualityCaches()
        }
    }
    @Published var currencyExchangeRateCache: CurrencyExchangeRateCache {
        didSet {
            rebuildApplicationRowSnapshots()
            rebuildProjectRowSnapshots()
            rebuildOrganizationRowSnapshots()
            markProjectViewCacheDirty()
        }
    }
    @Published private(set) var metadata: DataSourceMetadata {
        didSet {
            if Self.metadataCalendarContentAffectingFieldsDiffer(oldValue, metadata) {
                invalidateCalendarContentCaches()
                // Meetings and tasks live in the metadata and carry names.
                cachedUnlinkedPersonNames = nil
            }
            FixedDropdownTranslationRegistry.update(from: metadata)
            AppAppearanceRegistry.update(from: metadata)
            WorkflowDefaultSettingsRegistry.update(from: metadata)
            let previousLanguage = AppLanguage(rawValue: oldValue.interfaceLanguage ?? "") ?? .english
            let currentLanguage = AppLanguage(rawValue: metadata.interfaceLanguage ?? "") ?? .english
            let previousCurrentUserAuthorID = oldValue.currentUserAuthorID?.trimmedOrNil
            let currentCurrentUserAuthorID = metadata.currentUserAuthorID?.trimmedOrNil
            // Unchanged lists share storage, so this is constant time for
            // the many metadata writes that do not touch hidden warnings.
            let hiddenWarningListsMayDiffer = oldValue.hiddenDataQualityWarningKeys != metadata.hiddenDataQualityWarningKeys
                || oldValue.ignoredDuplicateWarningKeys != metadata.ignoredDuplicateWarningKeys
            if hiddenWarningListsMayDiffer,
               Set(oldValue.hiddenDataQualityWarningKeys ?? []) != Set(metadata.hiddenDataQualityWarningKeys ?? [])
                || Set(oldValue.ignoredDuplicateWarningKeys ?? []) != Set(metadata.ignoredDuplicateWarningKeys ?? []) {
                cachedHiddenDataQualityWarningKeySet = nil
                cachedHiddenDataQualityWarningKeySetSource = nil
                // Every Data view list is cached with its hidden rows
                // included and filtered when read, so hiding or showing a
                // warning changes none of them. Dropping them all here made
                // each click on Hide rebuild the translation and name lists
                // inside the next redraw (about half a second). Only the
                // navigation count, which counts visible warnings, is redone.
                invalidateDataQualityIssueCountCache()
            }
            if previousCurrentUserAuthorID != currentCurrentUserAuthorID {
                invalidateSQLitePrimaryReadCaches()
            }
            if previousLanguage != currentLanguage {
                invalidateWorkspaceSearchCache()
                rebuildLocalizedRowSnapshots()
                invalidatePublicationAuthorOrganizationOptionsCache()
                invalidateDataQualityCaches()
            }
            if previousCurrentUserAuthorID != currentCurrentUserAuthorID {
                rebuildApplicationRowSnapshots()
                rebuildPublicationAuthorRowSnapshots()
                rebuildProjectRowSnapshots()
            } else if oldValue.homeCountry != metadata.homeCountry {
                // Country flags in the researcher and project lists hide the home country.
                rebuildPublicationAuthorRowSnapshots()
                rebuildProjectRowSnapshots()
            }
        }
    }
    @Published private(set) var organizations: [OrganizationRecord] {
        didSet {
            invalidateCalendarContentCaches()
            // Clinic meetings take the home region's id from this list; the
            // per-meeting memo checks that id itself when it is next read
            // (see calendarMeetingNormalizationContext), so it is kept here.
            invalidateWorkspaceSearchCache()
            invalidatePublicationAuthorOrganizationOptionsCache()
            invalidateDataQualityCaches()
            // Keep the id and name lookups in step with the list, so
            // organization(id:) never returns a copy from before a change.
            organizationByID = organizations.reduce(into: [:]) { $0[$1.id] = $1 }
            organizationByName = organizations.reduce(into: [:]) { $0[$1.nameSv] = $1 }
        }
    }
