    var calendarWorkspaceLastFocusedDate: Date?

    enum PendingSelectionEntityKind {
        case organization
        case project
        case manager
        case author
        case journal
    }

    enum ChangeRefreshScope {
        case all
        case applications
        case organizations
        case projects
        case teaching
        case cv
        case publications
        case publicationAuthors
        // Adding an author that also becomes the current user's CV profile:
        // authors plus the metadata that stores currentUserAuthorID.
        case publicationAuthorsAndCurrentUser
        case publicationAuthorRename
        case publicationJournals
        // Journal save/delete: journals plus the collections a rename or
        // deletion cascades into. Previously these used .all - 24 documents
        // encoded three times per action.
        case publicationJournalReferences
        case publicationRecords
        // Calendar event deletion: metadata (owns central tasks and calendar
        // records) plus the hosts of legacy calendar-linked tasks. Previously
        // .all - the 8 MB journals document was encoded twice per deletion.
        case calendar
        // Meetings, travel and accommodation live entirely inside metadata and
        // feed no application, organization, project or publication cache, so
        // deleting one needs neither their re-derivation nor their re-encode.
        case calendarRecords
        // F21 organization tree: organizations (with their units) plus the
        // researchers whose affiliations, employments and education point
        // into the tree.
        case organizationTree
    }

    private enum ProjectCacheRefreshBehavior {
        case schedule
        case markDirty
        case skip
    }

    private enum PublicationIndexRefreshMode {
        case full
        case crossReferencesOnly
    }

    private struct PublicationIndexRefreshRequest {
        var mode: PublicationIndexRefreshMode
        var projectCacheBehavior: ProjectCacheRefreshBehavior

        mutating func merge(with other: PublicationIndexRefreshRequest) {
            if other.mode == .full {
                mode = .full
            }
            projectCacheBehavior = Self.mergedProjectCacheBehavior(
                lhs: projectCacheBehavior,
                rhs: other.projectCacheBehavior
            )
        }

        private static func mergedProjectCacheBehavior(
            lhs: ProjectCacheRefreshBehavior,
            rhs: ProjectCacheRefreshBehavior
        ) -> ProjectCacheRefreshBehavior {
            switch (lhs, rhs) {
            case (.schedule, _), (_, .schedule):
                return .schedule
            case (.markDirty, _), (_, .markDirty):
                return .markDirty
            case (.skip, .skip):
                return .skip
            }
        }
    }

