    // Persistence is whole-document overwrite, so a save issued after a failed
    // load would replace good on-disk data with the empty in-memory state.
    // Set only when a database exists on disk but could not be loaded.
    var storageWritesBlockedByLoadFailure = false

    var hasUnsupportedStorageSchema: Bool {
        (metadata.schemaVersion ?? 0) > DataSourceMetadata.currentSchemaVersion
    }

    private func requireSupportedStorageSchema() throws {
        guard !storageWritesBlockedByLoadFailure else {
            throw NSError(
                domain: "FootprintPersistence",
                code: 504,
                userInfo: [
                    NSLocalizedDescriptionKey:
                        "Storage writes are blocked because the existing database could not be loaded. Restore or repair the database and restart before editing data."
                ]
            )
        }
        guard !storageWritesBlockedByUnverifiedRollback else {
            throw NSError(
                domain: "FootprintPersistence",
                code: 503,
                userInfo: [
                    NSLocalizedDescriptionKey:
                        "Storage writes are blocked because a rollback could not be verified. Restart and verify storage health before editing data."
                ]
            )
        }
        guard let storedVersion = metadata.schemaVersion,
              storedVersion > DataSourceMetadata.currentSchemaVersion else {
            return
        }
        throw UnsupportedStorageSchemaError(storedVersion: storedVersion)
    }

    func handlePersistenceRollback(
        primaryError: Error,
        context: String,
        rollback: () throws -> Void
    ) {
        do {
            try rollback()
            loadError = primaryError.localizedDescription
        } catch {
            storageWritesBlockedByUnverifiedRollback = true
            persistenceStatus.isSaving = false
            loadError =
                "\(primaryError.localizedDescription) \(context) rollback failed and storage consistency could not be verified: \(error.localizedDescription)"
        }
    }

