    init(
        applications: [GrantApplication] = [],
        metadata: DataSourceMetadata = .bundledDefault,
        organizations: [OrganizationRecord] = [],
        managers: [ManagerOption] = [],
        projects: [ProjectRecord] = [],
        teachingCourses: [TeachingCourse] = [],
        teachingComponents: [TeachingComponent] = [],
        teachingFormats: [TeachingFormatOption] = [],
        teachingAssignments: [TeachingAssignment] = [],
        doctoralCandidates: [DoctoralCandidateRecord] = [],
        cvPersonalResume: CVPersonalResume = CVPersonalResume(),
        cvConferenceContributions: [CVConferenceContribution] = [],
        cvMediaAppearances: [CVMediaAppearance] = [],
        cvReviewEntries: [CVReviewEntry] = [],
        cvOtherPublications: [CVOtherPublicationEntry] = [],
        publicationAuthors: [PublicationAuthor] = [],
        publicationJournals: [PublicationJournal] = [],
        publicationRecords: [PublicationRecord] = [],
        loadError: String? = nil,
        skipInitialMigration: Bool = true,
        createStorageIfMissing: Bool = true
    ) {
        let initStartedAt = CFAbsoluteTimeGetCurrent()
        let sanitizedMetadata = Self.sanitizedMetadata(metadata)
        let sqliteOpenStartedAt = CFAbsoluteTimeGetCurrent()
        let loadedSQLiteStore = try? SQLiteDocumentStore(
            url: Self.databaseURL,
            createIfMissing: createStorageIfMissing
        )
        let sqliteOpenDuration = (CFAbsoluteTimeGetCurrent() - sqliteOpenStartedAt) * 1000
        self.applications = applications
        self.sqliteStore = loadedSQLiteStore
        self.currencyExchangeRateCache = Self.loadCurrencyExchangeRateCache(from: loadedSQLiteStore)
        self.metadata = sanitizedMetadata
        self.organizations = organizations
        self.managers = managers
        self.projects = projects
        self.teachingCourses = teachingCourses
        self.teachingComponents = teachingComponents
        self.teachingFormats = teachingFormats
        self.teachingAssignments = teachingAssignments
        self.doctoralCandidates = doctoralCandidates
        self.cvPersonalResume = cvPersonalResume
        self.cvConferenceContributions = cvConferenceContributions
        self.cvMediaAppearances = cvMediaAppearances
        self.cvReviewEntries = cvReviewEntries
        self.cvOtherPublications = cvOtherPublications
        self.publicationAuthors = publicationAuthors
        self.publicationJournals = publicationJournals
        self.publicationRecords = publicationRecords
        self.loadError = loadError
        undoManager.levelsOfUndo = 20
        undoManager.groupsByEvent = false
        FixedDropdownTranslationRegistry.update(from: sanitizedMetadata)
        AppAppearanceRegistry.update(from: sanitizedMetadata)
        WorkflowDefaultSettingsRegistry.update(from: sanitizedMetadata)
        synchronizeOrganizationsAndManagers(preserveCustomLists: true)
        if !skipInitialMigration {
            _ = migrateRecordsIfNeeded()
        }
        refreshPublicationIndexesInternal(mode: .full, projectCacheBehavior: .skip)
        appendPerformanceDiagnostic(
            String(
                format: "store-init sqlite=%@ sqlite_open_ms=%.2f total_ms=%.2f applications=%ld projects=%ld organizations=%ld publications=%ld authors=%ld",
                loadedSQLiteStore == nil ? "unavailable" : "available",
                sqliteOpenDuration,
                (CFAbsoluteTimeGetCurrent() - initStartedAt) * 1000,
                applications.count,
                projects.count,
                organizations.count,
                publicationRecords.count,
                publicationAuthors.count
            )
        )
    }

    static func loadFromBundle() -> GrantDataStore {
        let store = GrantDataStore(createStorageIfMissing: false)
        store.bootstrap()
        return store
    }

    var isShareModeEnabled: Bool {
        Self.isShareMode
    }

    func applyLoadedPersistentState(_ state: LoadedPersistentState) {
        applications = state.applications
        metadata = state.metadata
        organizations = state.organizations
        managers = derivedManagers(from: state.organizations)
        projects = state.projects
        teachingCourses = state.teachingCourses
        teachingComponents = state.teachingComponents
        teachingFormats = state.teachingFormats
        teachingAssignments = state.teachingAssignments
        doctoralCandidates = state.doctoralCandidates
        cvPersonalResume = state.cvPersonalResume
        cvConferenceContributions = state.cvConferenceContributions
        cvMediaAppearances = state.cvMediaAppearances
        cvReviewEntries = state.cvReviewEntries
        cvOtherPublications = state.cvOtherPublications
    }

    nonisolated static func metadataByApplyingCalendarDocuments(
        _ metadata: DataSourceMetadata,
        travelRecords: [CalendarTravelRecord]?,
        accommodationRecords: [CalendarAccommodationRecord]?,
        meetingRecords: [CalendarMeetingRecord]?,
        verticalNoteRecords: [CalendarVerticalNoteRecord]?
    ) -> DataSourceMetadata {
        var updated = sanitizedMetadata(metadata)
        if let travelRecords {
            updated.calendarTravelRecords = travelRecords
        }
        if let accommodationRecords {
            updated.calendarAccommodationRecords = accommodationRecords
        }
        if let meetingRecords {
            updated.calendarMeetingRecords = meetingRecords
        }
        if let verticalNoteRecords {
            updated.calendarVerticalNoteRecords = verticalNoteRecords
        }
        return sanitizedMetadata(updated)
    }

    nonisolated static func metadataByApplyingAppSettings(
        _ metadata: DataSourceMetadata,
        settings: AppSettingsSnapshot?
    ) -> DataSourceMetadata {
        guard let settings else { return sanitizedMetadata(metadata) }
        return sanitizedMetadata(settings.applying(to: metadata))
    }

    nonisolated private static func metadataCalendarContentAffectingFieldsDiffer(
        _ lhs: DataSourceMetadata,
        _ rhs: DataSourceMetadata
    ) -> Bool {
        lhs.taskItems != rhs.taskItems
            || lhs.teachingWorkspaceTasks != rhs.teachingWorkspaceTasks
            || lhs.calendarTravelRecords != rhs.calendarTravelRecords
            || lhs.calendarAccommodationRecords != rhs.calendarAccommodationRecords
            || lhs.calendarMeetingRecords != rhs.calendarMeetingRecords
            || lhs.calendarVerticalNoteRecords != rhs.calendarVerticalNoteRecords
            || lhs.calendarMeetingTypeOptions != rhs.calendarMeetingTypeOptions
            // Presentation preferences the calendar renders from. Without
            // them, hiding an automatic event from the calendar's own context
            // menu (or changing holidays/week start/country display in
            // Settings) was invisible until a tab switch.
            || lhs.calendarHiddenAutomaticEventKeys != rhs.calendarHiddenAutomaticEventKeys
            || lhs.calendarHolidayCountries != rhs.calendarHolidayCountries
            || lhs.calendarFirstWeekday != rhs.calendarFirstWeekday
            || lhs.calendarCountryDisplayMode != rhs.calendarCountryDisplayMode
            || lhs.calendarHiddenColumnKeys != rhs.calendarHiddenColumnKeys
            || lhs.calendarUsesCompactEventColorBands != rhs.calendarUsesCompactEventColorBands
            || lhs.calendarUsesCompactDayHighlightBands != rhs.calendarUsesCompactDayHighlightBands
            || lhs.calendarDayHighlightColors != rhs.calendarDayHighlightColors
            || lhs.calendarDayHighlightColorPresets != rhs.calendarDayHighlightColorPresets
            || lhs.calendarCategoryColors != rhs.calendarCategoryColors
            || lhs.calendarCategoryColorPresets != rhs.calendarCategoryColorPresets
            // Settings that change how activities are normalized and counted.
            || lhs.calendarCategoryBehaviors != rhs.calendarCategoryBehaviors
            || lhs.homeCountry != rhs.homeCountry
            || lhs.homeRegionOrganizationID != rhs.homeRegionOrganizationID
            || lhs.calendarReminderSettings != rhs.calendarReminderSettings
    }

    nonisolated static func storedCongressRecords(from organizations: [OrganizationRecord]) -> [StoredCongressRecord] {
        organizations.flatMap { organization in
            persistedOrganizationCongresses(from: organization.congresses).map { congress in
                StoredCongressRecord(organization: organization, congress: congress)
            }
        }
        .sorted {
            if $0.organizationName != $1.organizationName {
                return $0.organizationName.localizedStandardCompare($1.organizationName) == .orderedAscending
            }
            let leftDate = DateParsers.isoDay.date(from: $0.congress.from) ?? .distantFuture
            let rightDate = DateParsers.isoDay.date(from: $1.congress.from) ?? .distantFuture
            if leftDate != rightDate {
                return leftDate < rightDate
            }
            return $0.congress.title.localizedStandardCompare($1.congress.title) == .orderedAscending
        }
    }

    nonisolated static func organizationsByMergingStoredCongressRecords(
        _ storedCongresses: [StoredCongressRecord]?,
        into organizations: [OrganizationRecord]
    ) -> [OrganizationRecord] {
        guard let storedCongresses, !storedCongresses.isEmpty else { return organizations }
        var updatedOrganizations = organizations
        var indexesByID = Dictionary(firstWinsKeysWithValues: updatedOrganizations.enumerated().map { ($0.element.id, $0.offset) })
        let congressesByOrganizationID = Dictionary(grouping: storedCongresses) { $0.organizationID }

        for (organizationID, storedRecords) in congressesByOrganizationID {
            guard let index = indexesByID[organizationID] else { continue }
            let topLevelCongresses = storedRecords.map(\.congress)
            let normalizedTopLevelCongresses = persistedOrganizationCongresses(from: topLevelCongresses)
            guard !normalizedTopLevelCongresses.isEmpty || !updatedOrganizations[index].congresses.isEmpty else {
                continue
            }
            updatedOrganizations[index].congresses = normalizedTopLevelCongresses
            indexesByID[updatedOrganizations[index].id] = index
        }
        return updatedOrganizations
    }

    func relationalCoreSnapshot(generatedAt date: Date = Date()) -> RelationalCoreSnapshot {
        Self.relationalCoreSnapshot(
            generatedAt: date,
            metadata: editableMetadataSnapshot,
            organizations: organizations,
            cvConferenceContributions: cvConferenceContributions
        )
    }

    func relationalSQLiteSnapshot(generatedAt date: Date = Date()) -> RelationalSQLiteSnapshot {
        Self.relationalSQLiteSnapshot(
            generatedAt: date,
            applications: applications,
            metadata: editableMetadataSnapshot,
            organizations: organizations,
            projects: projects,
            publicationAuthors: publicationAuthors,
            publicationRecords: publicationRecords,
            cvConferenceContributions: cvConferenceContributions
        )
    }

    nonisolated static func relationalCoreSnapshot(
        generatedAt date: Date = Date(),
        metadata: DataSourceMetadata,
        organizations: [OrganizationRecord],
        cvConferenceContributions: [CVConferenceContribution]
    ) -> RelationalCoreSnapshot {
        let generatedAt = ISO8601DateFormatter().string(from: date)
        var congresses: [RelationalCongressRecord] = []
        var congressParticipants: [RelationalCongressParticipant] = []
        var congressFunding: [RelationalCongressFunding] = []
        var congressTravel: [RelationalCongressTravel] = []
        var congressAccommodation: [RelationalCongressAccommodation] = []
        var conferenceContributionCongresses: [RelationalConferenceContributionCongress] = []
        var conferenceContributionAuthors: [RelationalConferenceContributionAuthor] = []
        var calendarMeetingProjects: [RelationalCalendarMeetingProject] = []
        var calendarMeetingOrganizations: [RelationalCalendarMeetingOrganization] = []
        var calendarMeetingApplications: [RelationalCalendarMeetingApplication] = []
        var calendarMeetingPublications: [RelationalCalendarMeetingPublication] = []

        func uniqueStrings(_ values: [String]) -> [String] {
            let trimmed = values.compactMap(\.trimmedOrNil)
            return Array(NSOrderedSet(array: trimmed)) as? [String] ?? trimmed
        }

        for organization in organizations {
            for congress in persistedOrganizationCongresses(from: organization.congresses) {
                congresses.append(
                    RelationalCongressRecord(
                        id: congress.id,
                        organizationID: organization.id,
                        title: congress.title,
                        from: congress.from,
                        to: congress.to
                    )
                )
                for authorID in uniqueStrings(congress.participantAuthorIDs) {
                    congressParticipants.append(
                        RelationalCongressParticipant(
                            id: "\(organization.id)#\(congress.id)#\(authorID)",
                            organizationID: organization.id,
                            congressID: congress.id,
                            authorID: authorID
                        )
                    )
                }
                for applicationID in uniqueStrings(congress.fundingApplicationIDs) {
                    congressFunding.append(
                        RelationalCongressFunding(
                            id: "\(organization.id)#\(congress.id)#\(applicationID)",
                            organizationID: organization.id,
                            congressID: congress.id,
                            applicationID: applicationID
                        )
                    )
                }
            }
        }

        for travel in metadata.calendarTravelRecords ?? [] {
            guard let organizationID = travel.congressOrganizationID.trimmedOrNil,
                  let congressID = travel.congressID.trimmedOrNil else { continue }
            congressTravel.append(
                RelationalCongressTravel(
                    id: "\(organizationID)#\(congressID)#\(travel.id)",
                    organizationID: organizationID,
                    congressID: congressID,
                    travelID: travel.id
                )
            )
        }

        for accommodation in metadata.calendarAccommodationRecords ?? [] {
            guard let organizationID = accommodation.congressOrganizationID.trimmedOrNil,
                  let congressID = accommodation.congressID.trimmedOrNil else { continue }
            congressAccommodation.append(
                RelationalCongressAccommodation(
                    id: "\(organizationID)#\(congressID)#\(accommodation.id)",
                    organizationID: organizationID,
                    congressID: congressID,
                    accommodationID: accommodation.id
                )
            )
        }

        for contribution in cvConferenceContributions {
            if let organizationID = contribution.congressOrganizationID?.trimmedOrNil,
               let congressID = contribution.congressID?.trimmedOrNil {
                conferenceContributionCongresses.append(
                    RelationalConferenceContributionCongress(
                        id: "\(contribution.id)#\(organizationID)#\(congressID)",
                        contributionID: contribution.id,
                        organizationID: organizationID,
                        congressID: congressID
                    )
                )
            }
            for authorID in uniqueStrings(contribution.contributorAuthorIDs) {
                conferenceContributionAuthors.append(
                    RelationalConferenceContributionAuthor(
                        id: "\(contribution.id)#contributor#\(authorID)",
                        contributionID: contribution.id,
                        authorID: authorID,
                        role: "contributor"
                    )
                )
            }
            if let authorID = contribution.presentedByAuthorID?.trimmedOrNil {
                conferenceContributionAuthors.append(
                    RelationalConferenceContributionAuthor(
                        id: "\(contribution.id)#presenter#\(authorID)",
                        contributionID: contribution.id,
                        authorID: authorID,
                        role: "presenter"
                    )
                )
            }
        }

        for meeting in metadata.calendarMeetingRecords ?? [] {
            for projectID in uniqueStrings(meeting.projectIDs + [meeting.projectID].compactMap { $0 }) {
                calendarMeetingProjects.append(
                    RelationalCalendarMeetingProject(id: "\(meeting.id)#project#\(projectID)", meetingID: meeting.id, projectID: projectID)
                )
            }
            for organizationID in uniqueStrings(meeting.organizationIDs + [meeting.organizationID].compactMap { $0 }) {
                calendarMeetingOrganizations.append(
                    RelationalCalendarMeetingOrganization(id: "\(meeting.id)#organization#\(organizationID)", meetingID: meeting.id, organizationID: organizationID)
                )
            }
            for applicationID in uniqueStrings(meeting.applicationIDs) {
                calendarMeetingApplications.append(
                    RelationalCalendarMeetingApplication(id: "\(meeting.id)#application#\(applicationID)", meetingID: meeting.id, applicationID: applicationID)
                )
            }
            for publicationID in uniqueStrings(meeting.publicationIDs) {
                calendarMeetingPublications.append(
                    RelationalCalendarMeetingPublication(id: "\(meeting.id)#publication#\(publicationID)", meetingID: meeting.id, publicationID: publicationID)
                )
            }
        }

        return RelationalCoreSnapshot(
            schemaVersion: RelationalCoreSnapshot.currentSchemaVersion,
            generatedAt: generatedAt,
            congresses: congresses.sorted { $0.id < $1.id },
            congressParticipants: congressParticipants.sorted { $0.id < $1.id },
            congressFunding: congressFunding.sorted { $0.id < $1.id },
            congressTravel: congressTravel.sorted { $0.id < $1.id },
            congressAccommodation: congressAccommodation.sorted { $0.id < $1.id },
            conferenceContributionCongresses: conferenceContributionCongresses.sorted { $0.id < $1.id },
            conferenceContributionAuthors: conferenceContributionAuthors.sorted { $0.id < $1.id },
            calendarMeetingProjects: calendarMeetingProjects.sorted { $0.id < $1.id },
            calendarMeetingOrganizations: calendarMeetingOrganizations.sorted { $0.id < $1.id },
            calendarMeetingApplications: calendarMeetingApplications.sorted { $0.id < $1.id },
            calendarMeetingPublications: calendarMeetingPublications.sorted { $0.id < $1.id }
        )
    }

    nonisolated static func relationalSQLiteSnapshot(
        generatedAt date: Date = Date(),
        applications: [GrantApplication],
        metadata: DataSourceMetadata,
        organizations: [OrganizationRecord],
        projects: [ProjectRecord],
        publicationAuthors: [PublicationAuthor],
        publicationRecords: [PublicationRecord],
        cvConferenceContributions: [CVConferenceContribution]
    ) -> RelationalSQLiteSnapshot {
        let sanitizedMetadata = sanitizedMetadata(metadata)
        let relations = relationalCoreSnapshot(
            generatedAt: date,
            metadata: sanitizedMetadata,
            organizations: organizations,
            cvConferenceContributions: cvConferenceContributions
        )
        let generatedAt = ISO8601DateFormatter().string(from: date)

        return RelationalSQLiteSnapshot(
            schemaVersion: RelationalSQLiteSnapshot.currentSchemaVersion,
            generatedAt: generatedAt,
            organizations: organizations.map {
                RelationalSQLiteOrganizationRecord(id: $0.id, nameSv: $0.nameSv, nameEn: $0.nameEn)
            }.sorted { $0.id < $1.id },
            projects: projects.map {
                RelationalSQLiteProjectRecord(id: $0.id, nameSv: $0.nameSv, nameEn: $0.nameEn)
            }.sorted { $0.id < $1.id },
            applications: applications.map {
                RelationalSQLiteApplicationRecord(
                    id: $0.id,
                    title: $0.applicationTitle?.trimmedOrNil ?? $0.grantName,
                    organizationID: $0.organizationID?.trimmedOrNil,
                    projectID: $0.projectID?.trimmedOrNil,
                    status: $0.resultLabel
                )
            }.sorted { $0.id < $1.id },
            authors: publicationAuthors.map {
                RelationalSQLiteAuthorRecord(id: $0.id, displayName: $0.displayName)
            }.sorted { $0.id < $1.id },
            publications: publicationRecords.map {
                RelationalSQLitePublicationRecord(
                    id: $0.id,
                    title: $0.title,
                    projectID: $0.projectID?.trimmedOrNil,
                    journal: $0.journal,
                    year: $0.year
                )
            }.sorted { $0.id < $1.id },
            calendarTravel: (sanitizedMetadata.calendarTravelRecords ?? []).map {
                RelationalSQLiteCalendarTravelRecord(
                    id: $0.id,
                    date: $0.date,
                    arrivalDate: $0.arrivalDate,
                    departureTime: $0.departureTime,
                    arrivalTime: $0.arrivalTime,
                    mode: $0.mode.rawValue,
                    fromCity: $0.fromCity,
                    fromCountry: $0.fromCountry,
                    toCity: $0.toCity,
                    toCountry: $0.toCountry,
                    congressOrganizationID: $0.congressOrganizationID.trimmedOrNil,
                    congressID: $0.congressID.trimmedOrNil
                )
            }.sorted { $0.id < $1.id },
            calendarAccommodation: (sanitizedMetadata.calendarAccommodationRecords ?? []).map {
                RelationalSQLiteCalendarAccommodationRecord(
                    id: $0.id,
                    hotelName: $0.hotelName,
                    checkInDate: $0.checkInDate,
                    checkInTime: $0.checkInTime,
                    checkOutDate: $0.checkOutDate,
                    checkOutTime: $0.checkOutTime,
                    city: $0.city,
                    country: $0.country,
                    congressOrganizationID: $0.congressOrganizationID.trimmedOrNil,
                    congressID: $0.congressID.trimmedOrNil
                )
            }.sorted { $0.id < $1.id },
            calendarMeetings: (sanitizedMetadata.calendarMeetingRecords ?? []).map {
                RelationalSQLiteCalendarMeetingRecord(
                    id: $0.id,
                    date: $0.date,
                    startTime: $0.startTime,
                    endTime: $0.endTime,
                    title: $0.title,
                    meetingType: $0.meetingType
                )
            }.sorted { $0.id < $1.id },
            conferenceContributions: cvConferenceContributions.map {
                RelationalSQLiteConferenceContributionRecord(
                    id: $0.id,
                    title: $0.displayTitle,
                    status: $0.status.rawValue,
                    from: $0.from,
                    to: $0.to,
                    congressOrganizationID: $0.congressOrganizationID?.trimmedOrNil,
                    congressID: $0.congressID?.trimmedOrNil
                )
            }.sorted { $0.id < $1.id },
            relations: relations
        )
    }

    func relationshipMetrics() -> DataRelationshipMetrics {
        let validProjectIDs = Set(projects.map(\.id))
        let validAuthorIDs = Set(publicationAuthors.map(\.id))
        let validCongressIDsByOrganizationID = organizations.reduce(into: [String: Set<String>]()) { partialResult, organization in
            partialResult[organization.id, default: []].formUnion(
                persistedOrganizationCongresses(from: organization.congresses).map(\.id)
            )
        }

        var brokenCalendarProjectReferences = 0
        for meeting in calendarMeetingRecords {
            let projectIDs = uniquedNonEmptyStrings(meeting.projectIDs + [meeting.projectID].compactMap { $0 })
            brokenCalendarProjectReferences += projectIDs.filter { !validProjectIDs.contains($0) }.count
        }

        var brokenCongressReferences = 0
        for contribution in cvConferenceContributions {
            if let organizationID = contribution.congressOrganizationID?.trimmedOrNil {
                guard let congressIDs = validCongressIDsByOrganizationID[organizationID] else {
                    brokenCongressReferences += 1
                    continue
                }
                if let congressID = contribution.congressID?.trimmedOrNil,
                   !congressIDs.contains(congressID) {
                    brokenCongressReferences += 1
                }
            }
        }
        for travel in calendarTravelRecords {
            guard let organizationID = travel.congressOrganizationID.trimmedOrNil,
                  let congressID = travel.congressID.trimmedOrNil else { continue }
            if validCongressIDsByOrganizationID[organizationID]?.contains(congressID) != true {
                brokenCongressReferences += 1
            }
        }
        for accommodation in calendarAccommodationRecords {
            guard let organizationID = accommodation.congressOrganizationID.trimmedOrNil,
                  let congressID = accommodation.congressID.trimmedOrNil else { continue }
            if validCongressIDsByOrganizationID[organizationID]?.contains(congressID) != true {
                brokenCongressReferences += 1
            }
        }

        var unresolvedCongressParticipantNames = 0
        var congressCount = 0
        for organization in organizations {
            for congress in persistedOrganizationCongresses(from: organization.congresses) {
                congressCount += 1
                unresolvedCongressParticipantNames += congress.participantNames
                    .compactMap(\.trimmedOrNil)
                    .filter { publicationAuthor(matchingPresentedName: $0) == nil }
                    .count
                unresolvedCongressParticipantNames += congress.participantAuthorIDs
                    .compactMap(\.trimmedOrNil)
                    .filter { !validAuthorIDs.contains($0) }
                    .count
            }
        }

        var unresolvedConferenceContributorNames = 0
        for contribution in cvConferenceContributions {
            if let presentedBy = contribution.presentedBy.trimmedOrNil,
               publicationAuthor(matchingPresentedName: presentedBy) == nil {
                unresolvedConferenceContributorNames += 1
            }
            if let presentedByAuthorID = contribution.presentedByAuthorID?.trimmedOrNil,
               !validAuthorIDs.contains(presentedByAuthorID) {
                unresolvedConferenceContributorNames += 1
            }
            unresolvedConferenceContributorNames += contribution.contributorNames
                .compactMap(\.trimmedOrNil)
                .filter { publicationAuthor(matchingPresentedName: $0) == nil }
                .count
            unresolvedConferenceContributorNames += contribution.contributorAuthorIDs
                .compactMap(\.trimmedOrNil)
                .filter { !validAuthorIDs.contains($0) }
                .count
        }

        return DataRelationshipMetrics(
            applicationCount: applications.count,
            projectCount: projects.count,
            organizationCount: organizations.count,
            authorCount: publicationAuthors.count,
            congressCount: congressCount,
            calendarMeetingCount: calendarMeetingRecords.count,
            calendarTravelCount: calendarTravelRecords.count,
            calendarAccommodationCount: calendarAccommodationRecords.count,
            conferenceContributionCount: cvConferenceContributions.count,
            brokenCalendarProjectReferences: brokenCalendarProjectReferences,
            brokenCongressReferences: brokenCongressReferences,
            unresolvedCongressParticipantNames: unresolvedCongressParticipantNames,
            unresolvedConferenceContributorNames: unresolvedConferenceContributorNames
        )
    }

    private func storedCongressPlanningRowCount() -> Int {
        organizations.reduce(0) { total, organization in
            total + organization.congresses.reduce(0) { congressTotal, congress in
                congressTotal
                    + congress.travelFlights.filter { !$0.isEmpty }.count
                    + organizationCongressHotelsForPersistence(congress).count
            }
        }
    }

    func migrationVerificationReport(
        before: DataRelationshipMetrics,
        phase: String,
        generatedAt date: Date = Date()
    ) -> DataMigrationVerificationReport {
        let after = relationshipMetrics()
        let generatedAt = ISO8601DateFormatter().string(from: date)
        var checks: [DataMigrationVerificationCheck] = []

        func appendCheck(_ id: String, _ title: String, passed: Bool, details: String) {
            checks.append(
                DataMigrationVerificationCheck(
                    id: id,
                    title: title,
                    passed: passed,
                    details: details
                )
            )
        }

        let preservedCounts = before.applicationCount == after.applicationCount
            && before.projectCount == after.projectCount
            && before.organizationCount == after.organizationCount
            && before.authorCount == after.authorCount
            && before.congressCount == after.congressCount
            && before.calendarMeetingCount == after.calendarMeetingCount
            && after.calendarTravelCount >= before.calendarTravelCount
            && after.calendarAccommodationCount >= before.calendarAccommodationCount
            && before.conferenceContributionCount == after.conferenceContributionCount
        appendCheck(
            "record-counts-preserved",
            "Core record counts preserved",
            passed: preservedCounts,
            details: "before applications/projects/organizations/congresses/meetings/travel/accommodation/contributions \(before.applicationCount)/\(before.projectCount)/\(before.organizationCount)/\(before.congressCount)/\(before.calendarMeetingCount)/\(before.calendarTravelCount)/\(before.calendarAccommodationCount)/\(before.conferenceContributionCount), after \(after.applicationCount)/\(after.projectCount)/\(after.organizationCount)/\(after.congressCount)/\(after.calendarMeetingCount)/\(after.calendarTravelCount)/\(after.calendarAccommodationCount)/\(after.conferenceContributionCount)"
        )
        appendCheck(
            "calendar-project-links-not-worse",
            "Calendar project links not worse",
            passed: after.brokenCalendarProjectReferences <= before.brokenCalendarProjectReferences,
            details: "before \(before.brokenCalendarProjectReferences), after \(after.brokenCalendarProjectReferences)"
        )
        appendCheck(
            "congress-links-not-worse",
            "Congress links not worse",
            passed: after.brokenCongressReferences <= before.brokenCongressReferences,
            details: "before \(before.brokenCongressReferences), after \(after.brokenCongressReferences)"
        )
        appendCheck(
            "congress-participants-not-worse",
            "Congress participant links not worse",
            passed: after.unresolvedCongressParticipantNames <= before.unresolvedCongressParticipantNames,
            details: "before \(before.unresolvedCongressParticipantNames), after \(after.unresolvedCongressParticipantNames)"
        )
        appendCheck(
            "conference-contributors-not-worse",
            "Conference contributor links not worse",
            passed: after.unresolvedConferenceContributorNames <= before.unresolvedConferenceContributorNames,
            details: "before \(before.unresolvedConferenceContributorNames), after \(after.unresolvedConferenceContributorNames)"
        )
        let storedPlanningRows = storedCongressPlanningRowCount()
        appendCheck(
            "calendar-owned-congress-planning-migrated",
            "Calendar-owned congress planning rows migrated",
            passed: storedPlanningRows == 0,
            details: "stored congress travel/accommodation rows after migration \(storedPlanningRows)"
        )

        return DataMigrationVerificationReport(
            id: "migration-verification-\(generatedAt)",
            generatedAt: generatedAt,
            phase: phase,
            passed: checks.allSatisfy(\.passed),
            before: before,
            after: after,
            checks: checks
        )
    }

    @discardableResult
    func updateLastMigrationVerificationReport(_ report: DataMigrationVerificationReport) -> Bool {
        var updated = metadata
        let original = updated
        updated.lastMigrationVerificationReport = report
        updated = Self.sanitizedMetadata(updated)
        guard updated != original else { return false }
        metadata = updated
        return true
    }

    func clearRetiredCalendarVerticalNotesFromMetadata() {
        var updated = metadata
        updated.calendarVerticalNoteRecords = nil
        metadata = Self.sanitizedMetadata(updated)
    }

    func applyLoadedPublicationState(
        _ state: LoadedPublicationState,
        refresh: Bool = true,
        normalizeLoadedCollections: Bool = true,
        deferExpensiveRefreshWork: Bool = true
    ) {
        publicationAuthors = state.authors
        publicationJournals = state.journals
        publicationRecords = state.records
        if refresh {
            refreshPublicationRecords(
                normalizeLoadedCollections: normalizeLoadedCollections,
                deferExpensiveRefreshWork: deferExpensiveRefreshWork
            )
        }
    }

    func appendStartupDiagnostic(_ message: String) {
        // Resolve the destination now: the async write may run after a test's
        // FOOTPRINT_STORAGE_DIRECTORY override has been cleared, which used to
        // leak test log lines into the real storage directory.
        let destinationURL = Self.startupDiagnosticsURL
        diagnosticsQueue.async {
            let redacted = Self.redactedStartupDiagnosticMessage(message)
            let timestamp = Self.diagnosticsTimestamp(for: Date())
            guard let data = "[\(timestamp)] \(redacted)\n".data(using: .utf8) else { return }
            Self.appendDiagnosticData(data, to: destinationURL)
        }
    }

    /// Startup diagnostics may be attached to support reports. Paths under the
    /// storage root or the user's home would leak the username, so they are
    /// relativized before the standard redaction pass runs over the rest.
    nonisolated static func redactedStartupDiagnosticMessage(_ message: String) -> String {
        var sanitized = message
        sanitized = sanitized.replacingOccurrences(of: storageDirectory.path, with: "<storage>")
        let homePath = NSHomeDirectory()
        if homePath.count > 1 {
            sanitized = sanitized.replacingOccurrences(of: homePath, with: "~")
        }
        return PerformanceDiagnosticPrivacy.redact(sanitized)
    }

    func appendPerformanceDiagnostic(_ message: String) {
        let now = CFAbsoluteTimeGetCurrent()
        let key = Self.performanceDiagnosticThrottleKey(for: message)
        if let state = recentPerformanceDiagnosticStateByKey[key],
           now - state.lastTimestamp < Self.performanceDiagnosticThrottleInterval {
            recentPerformanceDiagnosticStateByKey[key] = (now, state.suppressedCount + 1)
            return
        }
        if let state = recentPerformanceDiagnosticStateByKey[key],
           state.suppressedCount > 0 {
            enqueuePerformanceDiagnosticMessage(
                "diagnostic-throttle key=\(key) suppressed=\(state.suppressedCount)"
            )
        }
        recentPerformanceDiagnosticStateByKey[key] = (now, 0)
        if recentPerformanceDiagnosticStateByKey.count > Self.maxDiagnosticThrottleKeys {
            pruneDiagnosticThrottleState(keepingMostRecent: Self.trimmedDiagnosticThrottleKeys)
        }
        enqueuePerformanceDiagnosticMessage(message)
    }

    private func appendPerformanceDiagnosticIfSlow(
        _ message: (Double) -> String,
        startedAt: CFAbsoluteTime,
        thresholdMs: Double = 12
    ) {
        let duration = (CFAbsoluteTimeGetCurrent() - startedAt) * 1000
        guard duration >= thresholdMs else { return }
        appendPerformanceDiagnostic(message(duration))
    }

    func recordCacheProfile(scope: String, cacheName: String, itemCount: Int, startedAt: CFAbsoluteTime, detail: String = "") {
        let duration = (CFAbsoluteTimeGetCurrent() - startedAt) * 1000
        let suffix = detail.isEmpty ? "" : " \(detail)"
        appendPerformanceDiagnostic(
            String(
                format: "cache-profile scope=%@ cache=%@ items=%ld duration_ms=%.2f%@",
                scope,
                cacheName,
                itemCount,
                duration,
                suffix
            )
        )
    }

    func performanceDiagnosticsSummary() -> String {
        do {
            let data = try Data(contentsOf: Self.performanceDiagnosticsURL)
            let text = String(decoding: data, as: UTF8.self)
            return Self.performanceDiagnosticsSummaryText(language: language, logText: text)
        } catch {
            return language.text("No performance log is available yet.", "Ingen prestandalogg finns ännu.")
        }
    }

    struct PerformanceDiagnosticsStatusItem: Identifiable, Equatable {
        let id: String
        let title: String
        let value: String
        let detail: String
        let tone: String
    }

    func performanceDiagnosticsStatusItems() -> [PerformanceDiagnosticsStatusItem] {
        do {
            let data = try Data(contentsOf: Self.performanceDiagnosticsURL)
            let text = String(decoding: data, as: UTF8.self)
            return Self.performanceDiagnosticsStatusItems(language: language, logText: text)
        } catch {
            return [
                PerformanceDiagnosticsStatusItem(
                    id: "missing-log",
                    title: language.text("Performance log", "Prestandalogg"),
                    value: language.text("No log", "Ingen logg"),
                    detail: language.text("Open a few views and summarize again.", "Öppna några vyer och sammanfatta igen."),
                    tone: "info"
                )
            ]
        }
    }

    nonisolated static func performanceDiagnosticsStatusItems(language: AppLanguage, logText: String, recentLineLimit: Int = 800) -> [PerformanceDiagnosticsStatusItem] {
        let lines = logText
            .split(separator: "\n", omittingEmptySubsequences: true)
            .suffix(recentLineLimit)
            .map(String.init)
        guard !lines.isEmpty else {
            return [
                PerformanceDiagnosticsStatusItem(
                    id: "empty-log",
                    title: language.text("Performance log", "Prestandalogg"),
                    value: language.text("No rows", "Inga rader"),
                    detail: language.text("No performance rows were found.", "Inga prestandarader hittades."),
                    tone: "info"
                )
            ]
        }

        func maxMetric(prefix: String, metric: String) -> Double {
            lines.compactMap { line -> Double? in
                guard line.contains(prefix) else { return nil }
                return performanceDiagnosticMetric(metric, in: line)
            }
            .max() ?? 0
        }

        func tone(value: Double, warning: Double, critical: Double) -> String {
            if value >= critical { return "critical" }
            if value >= warning { return "warning" }
            return "ok"
        }

        func ms(_ value: Double) -> String {
            value == 0 ? "0 ms" : String(format: "%.0f ms", value)
        }

        let slowestView = maxMetric(prefix: "view-ready", metric: "ready_ms")
        let slowestCache = maxMetric(prefix: "cache-profile", metric: "duration_ms")
        let worstLag = max(
            maxMetric(prefix: "main-thread-lag", metric: "delay_ms"),
            maxMetric(prefix: "main-thread-freeze", metric: "duration_ms")
        )
        let slowestPersistence = max(
            maxMetric(prefix: "persist", metric: "total_ms"),
            maxMetric(prefix: "publication-index-refresh", metric: "total_ms")
        )

        return [
            PerformanceDiagnosticsStatusItem(
                id: "rows",
                title: language.text("Rows analyzed", "Analyserade rader"),
                value: "\(lines.count)",
                detail: language.text("Latest performance entries", "Senaste prestandaraderna"),
                tone: "info"
            ),
            PerformanceDiagnosticsStatusItem(
                id: "views",
                title: language.text("Slowest view", "Långsammaste vy"),
                value: ms(slowestView),
                detail: language.text("Ready time", "Tid till klar vy"),
                tone: tone(value: slowestView, warning: 750, critical: 1_500)
            ),
            PerformanceDiagnosticsStatusItem(
                id: "caches",
                title: language.text("Slowest cache", "Långsammaste cache"),
                value: ms(slowestCache),
                detail: language.text("Cache/index rebuild", "Cache-/indexombyggnad"),
                tone: tone(value: slowestCache, warning: 250, critical: 750)
            ),
            PerformanceDiagnosticsStatusItem(
                id: "lag",
                title: language.text("Worst main-thread pause", "Värsta huvudtrådspaus"),
                value: ms(worstLag),
                detail: language.text("UI responsiveness", "UI-responsivitet"),
                tone: tone(value: worstLag, warning: 120, critical: 500)
            ),
            PerformanceDiagnosticsStatusItem(
                id: "persistence",
                title: language.text("Slowest persistence", "Långsammaste persistens"),
                value: ms(slowestPersistence),
                detail: language.text("Save/index operation", "Spar-/indexoperation"),
                tone: tone(value: slowestPersistence, warning: 600, critical: 1_500)
            )
        ]
    }

    nonisolated static func performanceDiagnosticsSummaryText(language: AppLanguage, logText: String, recentLineLimit: Int = 800) -> String {
        let lines = logText
            .split(separator: "\n", omittingEmptySubsequences: true)
            .suffix(recentLineLimit)
            .map(String.init)
        guard !lines.isEmpty else {
            return language.text("No performance log entries were found.", "Inga prestandarader hittades.")
        }

        func metricRows(prefix: String, metric: String, limit: Int = 6) -> [String] {
            lines.compactMap { line -> (String, Double)? in
                guard line.contains(prefix),
                      let value = Self.performanceDiagnosticMetric(metric, in: line) else {
                    return nil
                }
                return (line, value)
            }
            .sorted { $0.1 > $1.1 }
            .prefix(limit)
            .map { row, value in
                let compact = row.replacingOccurrences(of: #"^\[[^\]]+\]\s*"#, with: "", options: .regularExpression)
                if prefix == "cache-profile",
                   let scope = Self.performanceDiagnosticToken("scope", in: compact),
                   let cache = Self.performanceDiagnosticToken("cache", in: compact) {
                    return String(format: "%.1f ms  %@/%@  %@", value, scope, cache, compact)
                }
                return String(format: "%.1f ms  %@", value, compact)
            }
        }

        func countRows(containing token: String, limit: Int = 6) -> [String] {
            let counts = lines.reduce(into: [String: Int]()) { partialResult, line in
                guard line.contains(token) else { return }
                let compact = line
                    .replacingOccurrences(of: #"^\[[^\]]+\]\s*"#, with: "", options: .regularExpression)
                    .replacingOccurrences(of: #" delay_ms=[0-9.]+"#, with: "", options: .regularExpression)
                    .replacingOccurrences(of: #" ready_ms=[0-9.]+"#, with: "", options: .regularExpression)
                    .replacingOccurrences(of: #" settle_ms=[0-9.]+"#, with: "", options: .regularExpression)
                    .replacingOccurrences(of: #" visible_ms=[0-9.]+"#, with: "", options: .regularExpression)
                partialResult[compact, default: 0] += 1
            }
            return counts
                .sorted {
                    if $0.value != $1.value { return $0.value > $1.value }
                    return $0.key.localizedStandardCompare($1.key) == .orderedAscending
                }
                .prefix(limit)
                .map { "\($0.value)x  \($0.key)" }
        }

        let sections: [(String, [String])] = [
            (
                language.text("Slowest views", "Långsammaste vyer"),
                metricRows(prefix: "view-ready", metric: "ready_ms")
            ),
            (
                language.text("Slowest caches", "Långsammaste cachear"),
                metricRows(prefix: "cache-profile", metric: "duration_ms")
            ),
            (
                language.text("Main-thread freezes", "Huvudtrådslåsningar"),
                metricRows(prefix: "main-thread-lag", metric: "delay_ms")
                    + metricRows(prefix: "main-thread-freeze", metric: "duration_ms")
            ),
            (
                language.text("Most common freeze contexts", "Vanligaste låsningskontexter"),
                countRows(containing: "main-thread-lag") + countRows(containing: "main-thread-freeze")
            ),
            (
                language.text("Slow persistence/index operations", "Långsam persistens/indexering"),
                metricRows(prefix: "persist", metric: "total_ms") + metricRows(prefix: "publication-index-refresh", metric: "total_ms")
            )
        ]

        var output = [
            language.text("Performance summary from the latest log entries", "Prestandasammanfattning från de senaste loggraderna"),
            language.text("Lines analyzed", "Analyserade rader") + ": \(lines.count)"
        ]
        for (title, rows) in sections {
            output.append("")
            output.append(title + ":")
            output.append(contentsOf: rows.isEmpty ? [language.text("No entries", "Inga rader")] : rows)
        }
        return output.joined(separator: "\n")
    }

    nonisolated private static func performanceDiagnosticMetric(_ metric: String, in line: String) -> Double? {
        let pattern = #"\b\#(metric)=([0-9]+(?:\.[0-9]+)?)"#
        guard let expression = try? NSRegularExpression(pattern: pattern),
              let match = expression.firstMatch(in: line, range: NSRange(line.startIndex..., in: line)),
              let range = Range(match.range(at: 1), in: line) else {
            return nil
        }
        return Double(line[range])
    }

    nonisolated private static func performanceDiagnosticToken(_ token: String, in line: String) -> String? {
        let pattern = #"\b\#(token)=([^ ]+)"#
        guard let expression = try? NSRegularExpression(pattern: pattern),
              let match = expression.firstMatch(in: line, range: NSRange(line.startIndex..., in: line)),
              let range = Range(match.range(at: 1), in: line) else {
            return nil
        }
        return String(line[range])
    }

    func startMainThreadLagMonitorIfNeeded() {
        guard !hasStartedMainThreadLagMonitor else { return }
        hasStartedMainThreadLagMonitor = true
        MainRunLoopModeProbe.shared.installOnMainRunLoop()

        mainThreadLagMonitorTask = Task.detached(priority: .utility) { [weak self] in
            while !Task.isCancelled {
                let scheduledAt = CFAbsoluteTimeGetCurrent()
                // Sampled off-main right before the main-queue hop lands, so
                // it reflects the run loop's state DURING the delay window,
                // not after the queue drained.
                let runLoopBeforeHop = MainRunLoopModeProbe.shared.snapshot()
                await MainActor.run {
                    guard let self else { return }
                    let delay = (CFAbsoluteTimeGetCurrent() - scheduledAt) * 1000
                    if delay > 80 {
                        // tracking_gap_ms <= delay_ms means the run loop ran
                        // in event-tracking/modal mode during the delay
                        // window: the app was responsive and only the main
                        // QUEUE was starved (a phantom stall). A large gap in
                        // every mode means the main thread was truly blocked.
                        let runLoopAtDelivery = MainRunLoopModeProbe.shared.snapshot()
                        self.appendPerformanceDiagnostic(
                            String(
                                format: "main-thread-lag delay_ms=%.2f runloop_mode=%@ runloop_idle_ms=%.0f tracking_gap_ms=%.0f context=%@",
                                delay,
                                runLoopBeforeHop.mode,
                                runLoopBeforeHop.idleMs,
                                runLoopAtDelivery.trackingGapMs,
                                self.performanceContextSummary()
                            )
                        )
                    }
                }
                try? await Task.sleep(nanoseconds: 200_000_000)
            }
        }
    }

    @discardableResult
    func beginMainThreadActivity(_ label: String) -> CFAbsoluteTime {
        let startedAt = CFAbsoluteTimeGetCurrent()
        currentMainThreadActivity = label
        currentMainThreadActivityStartedAt = startedAt
        lastMainThreadActivity = label
        return startedAt
    }

    func endMainThreadActivity(_ label: String, startedAt: CFAbsoluteTime) {
        let duration = (CFAbsoluteTimeGetCurrent() - startedAt) * 1000
        lastMainThreadActivity = label
        lastMainThreadActivityDurationMs = duration
        lastMainThreadActivityCompletedAt = CFAbsoluteTimeGetCurrent()
        if currentMainThreadActivity == label {
            currentMainThreadActivity = "idle"
            currentMainThreadActivityStartedAt = nil
        }
    }

    private func performanceContextSummary() -> String {
        let now = CFAbsoluteTimeGetCurrent()
        let currentActivityAge = currentMainThreadActivityStartedAt.map { (now - $0) * 1000 } ?? 0
        let lastActivityAge = max((now - lastMainThreadActivityCompletedAt) * 1000, 0)
        return [
            "route=\(route?.performanceLabel ?? "none")",
            "tab=\(lastSelectedTabOverride ?? metadata.lastSelectedTab ?? "-")",
            "projectCacheDirty=\(isProjectViewCacheDirty ? "yes" : "no")",
            "projectCachePending=\(projectViewCacheTask == nil ? "no" : "yes")",
            "publicationIndexPending=\(pendingPublicationIndexRefreshRequest == nil ? "no" : "yes")",
            "deferredPersist=\(pendingDeferredPersistedStatesByKey.count)",
            "metadataPersist=\(pendingMetadataSnapshot == nil ? "no" : "yes")",
            String(format: "activity=%@/%.0fms", currentMainThreadActivity, currentActivityAge),
            String(format: "lastActivity=%@/%.0fms/%.0fmsAgo", lastMainThreadActivity, lastMainThreadActivityDurationMs, lastActivityAge),
            "apps=\(applications.count)",
            "projects=\(projects.count)",
            "authors=\(publicationAuthors.count)",
            "pubs=\(publicationRecords.count)"
        ]
        .joined(separator: ",")
    }

    nonisolated private static func diagnosticsTimestamp(for date: Date) -> String {
        let formatter = ISO8601DateFormatter()
        formatter.formatOptions = [.withInternetDateTime, .withFractionalSeconds]
        return formatter.string(from: date)
    }

    private func pruneDiagnosticThrottleState(keepingMostRecent limit: Int) {
        let sorted = recentPerformanceDiagnosticStateByKey.sorted { $0.value.lastTimestamp > $1.value.lastTimestamp }
        recentPerformanceDiagnosticStateByKey = Dictionary(firstWinsKeysWithValues: sorted.prefix(limit).map { ($0.key, $0.value) })
    }

    /// Privacy filtering, timestamp formatting and file I/O all run on the
    /// utility queue. Performance probes are often called from SwiftUI body or
    /// selection paths and must remain effectively constant-time there.
    private func enqueuePerformanceDiagnosticMessage(_ message: String) {
        // Resolved now for the same reason as in appendStartupDiagnostic.
        let destinationURL = Self.performanceDiagnosticsURL
        diagnosticsQueue.async {
            let redacted = Self.redactedPerformanceDiagnosticMessage(message)
            let timestamp = Self.diagnosticsTimestamp(for: Date())
            guard let data = "[\(timestamp)] \(redacted)\n".data(using: .utf8) else { return }
            Self.appendDiagnosticData(data, to: destinationURL)
        }
    }

    nonisolated private static func appendDiagnosticData(_ data: Data, to url: URL) {
        trimDiagnosticsFileIfNeeded(at: url, maximumBytes: maxDiagnosticsLogBytes)
        if FileManager.default.fileExists(atPath: url.path),
           let handle = try? FileHandle(forWritingTo: url) {
            defer { try? handle.close() }
            _ = try? handle.seekToEnd()
            try? handle.write(contentsOf: data)
        } else {
            try? data.write(to: url, options: .atomic)
        }
    }

    nonisolated private static func performanceDiagnosticThrottleKey(for message: String) -> String {
        let tokens = message.split(separator: " ")
        guard let first = tokens.first else { return message }
        // Values such as record IDs and author names are intentionally omitted:
        // the throttle key only needs to distinguish operational event classes.
        let retainedKeys = ["scope=", "reason=", "kind=", "phase=", "panel="]
        let retained = tokens.dropFirst().filter { token in
            retainedKeys.contains { token.hasPrefix($0) }
        }
        return ([String(first)] + retained.map(String.init)).joined(separator: " ")
    }

    /// Performance diagnostics are persisted outside the database and may be
    /// attached to support reports. Keep operational tokens and timings, but
    /// never persist user-provided names, titles, identifiers or contact data.
    /// A short one-way digest preserves correlation across repeated events
    /// without exposing the original value.
    nonisolated static func redactedPerformanceDiagnosticMessage(_ message: String) -> String {
        PerformanceDiagnosticPrivacy.redact(message)
    }

    var summary: DashboardSummary {
        let granted = applications.filter(\.isGranted)
        // Round 17: withdrawn applications are counted on their own.
        let rejected = applications.filter {
            $0.resultLabel.trimmingCharacters(in: .whitespacesAndNewlines).localizedCaseInsensitiveContains("Avslag")
        }
        let withdrawn = applications.filter { AppStatusTones.isWithdrawn(resultLabel: $0.resultLabel) }
        let pending = applications.filter { Self.isPendingStatus($0.resultLabel) }
        let requested = applications.reduce(0) { total, application in
            total + grantStatisticsAmountInSEK(for: application, amount: application.appliedAmountValue)
        }
        let awarded = granted.reduce(0) { total, application in
            total + grantStatisticsAmountInSEK(for: application, amount: application.grantedAmountValue)
        }

        return DashboardSummary(
            applicationCount: applications.count,
            grantedCount: granted.count,
            rejectedCount: rejected.count,
            pendingCount: pending.count,
            totalRequested: requested,
            totalAwarded: awarded,
            withdrawnCount: withdrawn.count
        )
    }

