    private struct SQLitePrimaryReadProbe<Record> {
        var records: [Record]
        var isPrimary: Bool
        var reason: String?
    }

    private func cachedSQLitePrimaryCalendarTravelProbe() -> SQLitePrimaryReadProbe<CalendarTravelRecord> {
        if let sqlitePrimaryCalendarTravelProbeCache { return sqlitePrimaryCalendarTravelProbeCache }
        let probe = sqlitePrimaryCalendarTravelProbe()
        sqlitePrimaryCalendarTravelProbeCache = probe
        return probe
    }

