    private func sqlitePrimaryCalendarTravelProbe() -> SQLitePrimaryReadProbe<CalendarTravelRecord> {
        guard !blocksSQLitePrimaryReads else {
            return SQLitePrimaryReadProbe(records: [], isPrimary: false, reason: "startup-sqlite-load-failed")
        }
        let canonicalRecords = calendarTravelRecords
        guard let sqliteStore else {
            return SQLitePrimaryReadProbe(records: [], isPrimary: false, reason: "sqlite-store-unavailable")
        }
        do {
            guard let relationalRecords = try sqliteStore.loadRelationalCalendarTravelRecords() else {
                return SQLitePrimaryReadProbe(records: [], isPrimary: false, reason: "rel_calendar_travel-missing")
            }
            let relationalIDs = relationalRecords.map(\.id)
            guard Set(relationalIDs).count == relationalIDs.count else {
                return SQLitePrimaryReadProbe(records: [], isPrimary: false, reason: "calendar-travel-duplicate-id")
            }
            let idsMatch = Set(relationalIDs) == Set(canonicalRecords.map(\.id))
            let canonicalByID = Dictionary(canonicalRecords.map { ($0.id, $0) }, uniquingKeysWith: { first, _ in first })
            let merged = relationalRecords
                .map { record in
                    guard let canonical = canonicalByID[record.id] else { return record }
                    var merged = record
                    merged.dateUncertain = canonical.dateUncertain
                    merged.departureTimeUncertain = canonical.departureTimeUncertain
                    merged.arrivalTimeUncertain = canonical.arrivalTimeUncertain
                    merged.reference = canonical.reference
                    return merged
                }
                .sorted {
                    let leftDate = DateParsers.isoDay.date(from: $0.date) ?? .distantFuture
                    let rightDate = DateParsers.isoDay.date(from: $1.date) ?? .distantFuture
                    if leftDate != rightDate {
                        return leftDate < rightDate
                    }
                    if $0.departureTime != $1.departureTime {
                        return $0.departureTime.localizedStandardCompare($1.departureTime) == .orderedAscending
                    }
                    return $0.id < $1.id
                }
            return SQLitePrimaryReadProbe(
                records: merged,
                isPrimary: true,
                reason: idsMatch ? nil : "calendar-travel-id-mismatch"
            )
        } catch {
            return SQLitePrimaryReadProbe(records: [], isPrimary: false, reason: error.localizedDescription)
        }
    }

    private func sqlitePrimaryCoreDocumentProbe<Record: Decodable & Hashable & Identifiable>(
        named documentName: String,
        canonicalRecords: [Record]
    ) -> SQLitePrimaryReadProbe<Record> where Record.ID == String {
        guard !blocksSQLitePrimaryReads else {
            return SQLitePrimaryReadProbe(records: [], isPrimary: false, reason: "startup-sqlite-load-failed")
        }
        guard let sqliteStore else {
            return SQLitePrimaryReadProbe(records: [], isPrimary: false, reason: "sqlite-store-unavailable")
        }
        do {
            guard let storedRecords = try sqliteStore.load([Record].self, named: documentName) else {
                return SQLitePrimaryReadProbe(records: [], isPrimary: false, reason: "\(documentName)-document-missing")
            }
            let canonicalIDs = canonicalRecords.map(\.id)
            let storedIDs = storedRecords.map(\.id)
            guard Set(storedIDs).count == storedIDs.count else {
                return SQLitePrimaryReadProbe(records: [], isPrimary: false, reason: "\(documentName)-duplicate-id")
            }
            let canonicalIDsMatch = Set(canonicalIDs).count == canonicalIDs.count
                && Set(canonicalIDs) == Set(storedIDs)
            let canonicalByID = Dictionary(canonicalRecords.map { ($0.id, $0) }, uniquingKeysWith: { first, _ in first })
            let contentMatches = canonicalIDsMatch && storedRecords.allSatisfy { record in
                canonicalByID[record.id] == record
            }
            return SQLitePrimaryReadProbe(
                records: storedRecords,
                isPrimary: true,
                reason: canonicalIDsMatch
                    ? (contentMatches ? nil : "\(documentName)-content-mismatch")
                    : "\(documentName)-id-mismatch"
            )
        } catch {
            return SQLitePrimaryReadProbe(records: [], isPrimary: false, reason: error.localizedDescription)
        }
    }

    private func sqlitePrimaryPublicationAuthorProbe() -> SQLitePrimaryReadProbe<PublicationAuthor> {
        guard !blocksSQLitePrimaryReads else {
            return SQLitePrimaryReadProbe(records: [], isPrimary: false, reason: "startup-sqlite-load-failed")
        }
        let canonicalRecords = publicationAuthorsForPrimaryReadComparison(publicationAuthors)
        guard let sqliteStore else {
            return SQLitePrimaryReadProbe(records: [], isPrimary: false, reason: "sqlite-store-unavailable")
        }
        do {
            guard let storedRecords = try sqliteStore.load([PublicationAuthor].self, named: "publication_authors") else {
                return SQLitePrimaryReadProbe(records: [], isPrimary: false, reason: "publication_authors-document-missing")
            }
            let normalizedStoredRecords = publicationAuthorsForPrimaryReadComparison(storedRecords)
            let canonicalIDs = canonicalRecords.map(\.id)
            let storedIDs = normalizedStoredRecords.map(\.id)
            guard Set(storedIDs).count == storedIDs.count else {
                return SQLitePrimaryReadProbe(records: [], isPrimary: false, reason: "publication_authors-duplicate-id")
            }
            let canonicalIDsMatch = Set(canonicalIDs).count == canonicalIDs.count
                && Set(canonicalIDs) == Set(storedIDs)
            let canonicalByID = Dictionary(canonicalRecords.map { ($0.id, $0) }, uniquingKeysWith: { first, _ in first })
            let contentMatches = canonicalIDsMatch && normalizedStoredRecords.allSatisfy { record in
                canonicalByID[record.id] == record
            }
            return SQLitePrimaryReadProbe(
                records: normalizedStoredRecords,
                isPrimary: true,
                reason: canonicalIDsMatch
                    ? (contentMatches ? nil : "publication_authors-content-mismatch")
                    : "publication_authors-id-mismatch"
            )
        } catch {
            return SQLitePrimaryReadProbe(records: [], isPrimary: false, reason: error.localizedDescription)
        }
    }

    private func publicationAuthorsForPrimaryReadComparison(_ authors: [PublicationAuthor]) -> [PublicationAuthor] {
        let records = publicationRecordsForRead
        var recordIndexesByAuthorKey: [String: Set<Int>] = [:]
        for (recordIndex, record) in records.enumerated() {
            for key in Set(record.authorNames.map(normalizedPersonLookupName).filter { !$0.isEmpty }) {
                recordIndexesByAuthorKey[key, default: []].insert(recordIndex)
            }
        }
        var normalizedAuthors = authors
        for index in normalizedAuthors.indices {
            normalizedAuthors[index].normalize()
            let variantKeys = Set(
                normalizedAuthors[index].presentedNameCandidates
                    .compactMap(\.trimmedOrNil)
                    .map(normalizedPersonLookupName)
                    .filter { !$0.isEmpty }
            )
            let matchingRecordIndexes = variantKeys.reduce(into: Set<Int>()) { indexes, key in
                indexes.formUnion(recordIndexesByAuthorKey[key] ?? [])
            }
            let titles = matchingRecordIndexes.sorted().map { records[$0].title }
            let counts = Dictionary(grouping: titles, by: { $0 }).mapValues(\.count)
            normalizedAuthors[index].publications = counts.keys.sorted { $0.localizedStandardCompare($1) == .orderedAscending }.map { title in
                PublicationAuthorContribution(id: "derived:\(title)", title: title, count: counts[title] ?? 0)
            }
        }
        let currentAuthorID = metadata.currentUserAuthorID?.trimmedOrNil
            ?? (normalizedAuthors.count == 1 ? normalizedAuthors.first?.id : nil)
        normalizedAuthors.sort {
            let lhsIsCurrent = $0.id == currentAuthorID
            let rhsIsCurrent = $1.id == currentAuthorID
            if lhsIsCurrent != rhsIsCurrent {
                return lhsIsCurrent && !rhsIsCurrent
            }
            return $0.sortName.localizedStandardCompare($1.sortName) == .orderedAscending
        }
        return normalizedAuthors
    }

    private func sqlitePrimaryCongressProbe() -> SQLitePrimaryReadProbe<StoredCongressRecord> {
        guard !blocksSQLitePrimaryReads else {
            return SQLitePrimaryReadProbe(records: [], isPrimary: false, reason: "startup-sqlite-load-failed")
        }
        let canonicalRecords = Self.storedCongressRecords(from: organizations)
        guard let sqliteStore else {
            return SQLitePrimaryReadProbe(records: [], isPrimary: false, reason: "sqlite-store-unavailable")
        }
        do {
            guard let storedRecords = try sqliteStore.load([StoredCongressRecord].self, named: "congresses") else {
                return SQLitePrimaryReadProbe(records: [], isPrimary: false, reason: "congresses-document-missing")
            }
            let storedIDs = storedRecords.map(\.id)
            guard Set(storedIDs).count == storedIDs.count else {
                return SQLitePrimaryReadProbe(records: [], isPrimary: false, reason: "congress-duplicate-id")
            }
            let canonicalIDs = canonicalRecords.map(\.id)
            let canonicalIDsMatch = Set(canonicalIDs).count == canonicalIDs.count
                && Set(canonicalIDs) == Set(storedIDs)
            let canonicalByID = Dictionary(canonicalRecords.map { ($0.id, $0) }, uniquingKeysWith: { first, _ in first })
            let contentMatches = canonicalIDsMatch && storedRecords.allSatisfy { record in
                guard let canonical = canonicalByID[record.id] else { return false }
                return canonical.organizationID == record.organizationID
                    && canonical.congress == record.congress
            }
            return SQLitePrimaryReadProbe(
                records: storedRecords,
                isPrimary: true,
                reason: canonicalIDsMatch
                    ? (contentMatches ? nil : "congress-content-mismatch")
                    : "congress-id-mismatch"
            )
        } catch {
            return SQLitePrimaryReadProbe(records: [], isPrimary: false, reason: error.localizedDescription)
        }
    }

    private func sqlitePrimaryCalendarAccommodationProbe() -> SQLitePrimaryReadProbe<CalendarAccommodationRecord> {
        guard !blocksSQLitePrimaryReads else {
            return SQLitePrimaryReadProbe(records: [], isPrimary: false, reason: "startup-sqlite-load-failed")
        }
        let canonicalRecords = calendarAccommodationRecords
        guard let sqliteStore else {
            return SQLitePrimaryReadProbe(records: [], isPrimary: false, reason: "sqlite-store-unavailable")
        }
        do {
            guard let relationalRecords = try sqliteStore.loadRelationalCalendarAccommodationRecords() else {
                return SQLitePrimaryReadProbe(records: [], isPrimary: false, reason: "rel_calendar_accommodation-missing")
            }
            let relationalIDs = relationalRecords.map(\.id)
            guard Set(relationalIDs).count == relationalIDs.count else {
                return SQLitePrimaryReadProbe(records: [], isPrimary: false, reason: "calendar-accommodation-duplicate-id")
            }
            let idsMatch = Set(relationalIDs) == Set(canonicalRecords.map(\.id))
            let canonicalByID = Dictionary(canonicalRecords.map { ($0.id, $0) }, uniquingKeysWith: { first, _ in first })
            let merged = relationalRecords
                .map { record in
                    guard let canonical = canonicalByID[record.id] else { return record }
                    var merged = record
                    merged.reference = canonical.reference
                    return merged
                }
                .sorted(by: calendarAccommodationSort)
            return SQLitePrimaryReadProbe(
                records: merged,
                isPrimary: true,
                reason: idsMatch ? nil : "calendar-accommodation-id-mismatch"
            )
        } catch {
            return SQLitePrimaryReadProbe(records: [], isPrimary: false, reason: error.localizedDescription)
        }
    }

    var calendarMeetingRecords: [CalendarMeetingRecord] {
        if let normalizedCalendarMeetingRecordsCache {
            return normalizedCalendarMeetingRecordsCache
        }
        // After one meeting is saved or deleted every other meeting is still
        // the same stored value, so its normalized form and sort key are
        // taken from the previous build instead of being redone (two
        // normalize passes with regex date checks per meeting, and a sort
        // that re-parsed dates in every comparison: ~200 ms for 1,800
        // meetings). A stored meeting that differs in any field is rebuilt.
        let startedAt = CFAbsoluteTimeGetCurrent()
        let rawRecords = metadata.calendarMeetingRecords ?? []
        // A changed home region, home country or clinical-time setting can
        // change any clinic meeting, so the memo is only used while these
        // are what they were when it was built. A renamed or edited
        // organization that is not the home region changes nothing here.
        let context = calendarMeetingNormalizationContext
        let memoContextChanged = normalizedCalendarMeetingRecordMemoContext != context
        if memoContextChanged {
            normalizedCalendarMeetingRecordMemo.removeAll()
        }
        var nextMemo: [String: NormalizedCalendarMeetingMemoEntry] = [:]
        nextMemo.reserveCapacity(rawRecords.count)
        var keyed: [(record: CalendarMeetingRecord, key: CalendarMeetingSortKey)] = []
        keyed.reserveCapacity(rawRecords.count)
        var reusedCount = 0
        for raw in rawRecords {
            let entry: NormalizedCalendarMeetingMemoEntry
            if let memo = normalizedCalendarMeetingRecordMemo[raw.id], memo.raw == raw {
                entry = memo
                reusedCount += 1
            } else {
                var copy = raw
                copy.normalize()
                let normalized = normalizedCalendarMeetingRecord(copy)
                entry = NormalizedCalendarMeetingMemoEntry(
                    raw: raw,
                    normalized: normalized,
                    isEmpty: normalized.isEmpty,
                    sortKey: CalendarMeetingSortKey(record: normalized)
                )
            }
            // Duplicate ids keep the first entry as memo; each still counts.
            if nextMemo[raw.id] == nil {
                nextMemo[raw.id] = entry
            }
            guard !entry.isEmpty else { continue }
            keyed.append((record: entry.normalized, key: entry.sortKey))
        }
        let afterNormalize = CFAbsoluteTimeGetCurrent()
        let records = calendarMeetingRecordsSortedChronologically(keyed: keyed)
        normalizedCalendarMeetingRecordMemo = nextMemo
        normalizedCalendarMeetingRecordMemoContext = context
        normalizedCalendarMeetingRecordsCache = records
        calendarMeetingRecordMemoReuseCount &+= reusedCount
        appendPerformanceDiagnosticIfSlow(
            { duration in
                String(
                    format: "calendar-meeting-records-build records=%ld reused=%ld context_changed=%@ normalize_ms=%.2f sort_ms=%.2f total_ms=%.2f",
                    rawRecords.count,
                    reusedCount,
                    memoContextChanged ? "yes" : "no",
                    (afterNormalize - startedAt) * 1000,
                    (CFAbsoluteTimeGetCurrent() - afterNormalize) * 1000,
                    duration
                )
            },
            startedAt: startedAt,
            thresholdMs: 8
        )
        return records
    }

    /// `CalendarMeetingRecord.normalize()` for every meeting a calendar save
    /// hands over, dropping empty ones, in the given order. A save passes
    /// the whole list (~1,800 meetings) to change one; meetings identical to
    /// the ones the previous save normalized reuse that result.
    func calendarMeetingRecordsNormalizedForSave(
        _ records: [CalendarMeetingRecord]
    ) -> (records: [CalendarMeetingRecord], reused: Int) {
        var nextMemo: [String: (input: CalendarMeetingRecord, output: CalendarMeetingRecord)] = [:]
        nextMemo.reserveCapacity(records.count)
        var result: [CalendarMeetingRecord] = []
        result.reserveCapacity(records.count)
        var reused = 0
        for record in records {
            let output: CalendarMeetingRecord
            if let memo = calendarMeetingSaveNormalizationMemo[record.id], memo.input == record {
                output = memo.output
                reused += 1
            } else {
                var copy = record
                copy.normalize()
                output = copy
            }
            if nextMemo[record.id] == nil {
                nextMemo[record.id] = (input: record, output: output)
            }
            if !output.isEmpty {
                result.append(output)
            }
        }
        calendarMeetingSaveNormalizationMemo = nextMemo
        return (records: result, reused: reused)
    }

    func normalizedCalendarMeetingRecord(_ record: CalendarMeetingRecord) -> CalendarMeetingRecord {
        var copy = record
        copy.normalize()

        // Categories marked "Clinical time" in Settings > Calendar categories.
        guard calendarCategoryIsClinicalTime(named: copy.meetingType) else { return copy }

        if copy.meetingMode.trimmedOrNil == nil {
            copy.meetingMode = CalendarMeetingMode.physical.rawValue
        }

        // Clinical work abroad is not done for the home region, so a clinical
        // activity in another country than the home country keeps no organization.
        let canonicalCountry = GrantParsing.canonicalCountryName(copy.country)
        if !canonicalCountry.isEmpty, !isHomeCountry(canonicalCountry) {
            copy.organizationID = nil
            return copy
        }

        // Settings > Home organization > Home region.
        if let regionID = homeRegionOrganizationID {
            copy.organizationID = regionID
        }

        return copy
    }

