        Self.normalizedCalendarCategoryColorSettings(metadata.calendarCategoryColors ?? [])
    }

    var calendarCategoryColorPresets: [CalendarCategoryColorPreset] {
        let overrides = Dictionary(firstWinsKeysWithValues: Self.normalizedCalendarCategoryColorPresets(metadata.calendarCategoryColorPresets ?? [])
            .filter { Self.isEditableCalendarCategoryColorPresetID($0.id) }
            .map { ($0.id, $0) })

        return Self.standardCalendarCategoryColorPresets().map { preset in
            guard let override = overrides[preset.id] else { return preset }
            return CalendarCategoryColorPreset(
                id: preset.id,
                name: preset.name,
                settings: Self.resolvedCalendarFixedCategoryPresetSettings(
                    override.settings,
                    fallback: preset.settings
                )
            )
        }
    }

    var calendarKnownMeetingCategories: [String] {
        if let calendarKnownMeetingCategoriesCache {
            return calendarKnownMeetingCategoriesCache
        }
        let configured = calendarMeetingTypeOptions
        let configuredKeys = Set(configured.map(normalizedCalendarCategoryLookupKey))
        let used = Self.normalizedCalendarMeetingTypeOptions(calendarMeetingRecords.map(\.meetingType))
        let missingUsed = used
            .filter { !configuredKeys.contains(normalizedCalendarCategoryLookupKey($0)) }
            .sorted { $0.localizedStandardCompare($1) == .orderedAscending }
        let categories = configured + missingUsed
        calendarKnownMeetingCategoriesCache = categories
        return categories
    }

    func calendarMeetingCategoryColorSetting(named name: String) -> CalendarCategoryColorSetting? {
        let settingsByID = Dictionary(firstWinsKeysWithValues: calendarCategoryColorSettings.map { ($0.id, $0) })
        let lookupID = CalendarCategoryColorSetting.meetingColorID(for: name)
        if let exact = settingsByID[lookupID] {
            return exact
        }

        // A category without its own color borrows the color of another
        // category with the same role (clinical time or leave) in Settings >
        // Calendar categories, instead of fixed category names.
        let behavior = calendarCategoryBehavior(named: name)
        guard behavior.isClinicalTime || behavior.isLeave else { return nil }
        let ownKey = normalizedCalendarCategoryLookupKey(name)
        for candidate in calendarCategoryNamesWithBehaviors() {
            let candidateKey = normalizedCalendarCategoryLookupKey(candidate)
            guard candidateKey != ownKey else { continue }
            let candidateBehavior = calendarCategoryBehavior(named: candidate)
            let sharesRole = (behavior.isClinicalTime && candidateBehavior.isClinicalTime)
                || (behavior.isLeave && candidateBehavior.isLeave)
            guard sharesRole,
                  let fallback = settingsByID[CalendarCategoryColorSetting.meetingColorID(for: candidate)] else {
                continue
            }
            return fallback
        }
        return nil
    }

    // MARK: Calendar category behaviour (Settings > Calendar categories)

    /// What the category means to the app. Before the categories' settings
    /// have been stored, the old fixed category names apply.
    func calendarCategoryBehavior(named name: String) -> CalendarCategoryBehaviorSetting {
        let key = normalizedCalendarCategoryLookupKey(name)
        guard let stored = metadata.calendarCategoryBehaviors else {
            return CalendarCategoryBehaviorSetting.legacyDefault(forCategoryNamed: name)
        }
        if calendarCategoryBehaviorCache == nil {
            var cache: [String: CalendarCategoryBehaviorSetting] = [:]
            for setting in stored where cache[setting.lookupKey] == nil {
                cache[setting.lookupKey] = setting
            }
            calendarCategoryBehaviorCache = cache
        }
        return calendarCategoryBehaviorCache?[key] ?? CalendarCategoryBehaviorSetting(categoryName: name)
    }

    func calendarCategoryIsExcludedFromMeetingStatistics(named name: String) -> Bool {
        calendarCategoryBehavior(named: name).excludedFromMeetingStatistics
    }

    func calendarCategoryIsClinicalTime(named name: String) -> Bool {
        calendarCategoryBehavior(named: name).isClinicalTime
    }

    func calendarCategoryIsLeave(named name: String) -> Bool {
        calendarCategoryBehavior(named: name).isLeave
    }

    /// The first category marked as clinical time (used for the clinic color
    /// in the salary view), or nil when no category is.
    var firstClinicalCalendarCategoryName: String? {
        calendarCategoryNamesWithBehaviors().first { calendarCategoryIsClinicalTime(named: $0) }
    }

    /// Known categories plus the categories that have stored settings.
    func calendarCategoryNamesWithBehaviors() -> [String] {
        var names = calendarKnownMeetingCategories
        var keys = Set(names.map(normalizedCalendarCategoryLookupKey))
        for setting in metadata.calendarCategoryBehaviors ?? [] where keys.insert(setting.lookupKey).inserted {
            names.append(setting.categoryName)
        }
        if metadata.calendarCategoryBehaviors == nil {
            // Before the settings are stored the old names count, also when
            // the category is not in the list (e.g. "Clinic" next to "Klinik").
            for legacyName in ["Klinik", "Clinic", "Semester", "Vacation", "Resa", "Travel"]
            where keys.insert(normalizedCalendarCategoryLookupKey(legacyName)).inserted {
                names.append(legacyName)
            }
        }
        return names
    }

