    private func defaultCalendarSemanticColorHex(for tone: AppSemanticTone, usesDarkAppearance: Bool) -> String {
        let settings = usesDarkAppearance ? appSemanticColorSettingsDark : appSemanticColorSettingsLight
        switch tone {
        case .negative:
            return normalizedCalendarCategoryHexColor(settings.negative.solidHex)
        case .inProgress:
            return normalizedCalendarCategoryHexColor(settings.inProgress.solidHex)
        case .positive:
            return normalizedCalendarCategoryHexColor(settings.positive.solidHex)
        case .neutral:
            return normalizedCalendarCategoryHexColor(settings.neutral.solidHex)
        }
    }

    private func defaultCalendarDayHighlightTextHex(for kind: CalendarDayHighlightKind, usesDarkAppearance: Bool) -> String {
        switch kind {
        case .holiday, .saturday, .sunday:
            return defaultCalendarSemanticColorHex(for: .negative, usesDarkAppearance: usesDarkAppearance)
        }
    }

    private func defaultCalendarDayHighlightBackgroundHex(for kind: CalendarDayHighlightKind, usesDarkAppearance: Bool) -> String {
        switch kind {
        case .holiday, .saturday, .sunday:
            return defaultCalendarSemanticColorHex(for: .negative, usesDarkAppearance: usesDarkAppearance)
        }
    }

    private func defaultCalendarFixedCategoryColorHex(for category: CalendarFixedCategory, usesDarkAppearance: Bool) -> String {
        switch category {
        case .travel:
            return defaultCalendarSemanticColorHex(for: .positive, usesDarkAppearance: usesDarkAppearance)
        case .task:
            return defaultCalendarSemanticColorHex(for: .inProgress, usesDarkAppearance: usesDarkAppearance)
        case .deadline:
            return defaultCalendarSemanticColorHex(for: .negative, usesDarkAppearance: usesDarkAppearance)
        case .uncategorized:
            return defaultCalendarSemanticColorHex(for: .neutral, usesDarkAppearance: usesDarkAppearance)
        }
    }

