    private func currentCalendarDayHighlightColorPreset(named name: String) -> CalendarDayHighlightColorPreset {
        CalendarDayHighlightColorPreset(
            id: "default",
            name: name,
            settings: CalendarDayHighlightKind.allCases.map { kind in
                CalendarDayHighlightColorSetting(
                    id: CalendarDayHighlightColorSetting.id(for: kind),
                    lightTextHexColor: calendarDayHighlightTextHex(kind, usesDarkAppearance: false)
                        ?? defaultCalendarDayHighlightTextHex(for: kind, usesDarkAppearance: false),
                    lightBackgroundHexColor: calendarDayHighlightBackgroundHex(kind, usesDarkAppearance: false)
                        ?? defaultCalendarDayHighlightBackgroundHex(for: kind, usesDarkAppearance: false),
                    darkTextHexColor: calendarDayHighlightTextHex(kind, usesDarkAppearance: true)
                        ?? defaultCalendarDayHighlightTextHex(for: kind, usesDarkAppearance: true),
                    darkBackgroundHexColor: calendarDayHighlightBackgroundHex(kind, usesDarkAppearance: true)
                        ?? defaultCalendarDayHighlightBackgroundHex(for: kind, usesDarkAppearance: true)
                )
            }
        )
    }

    private func currentCalendarCategoryColorPreset(named name: String) -> CalendarCategoryColorPreset {
        var settings = CalendarFixedCategory.allCases.map { category in
            CalendarCategoryColorSetting(
                id: CalendarCategoryColorSetting.fixedColorID(for: category),
                lightHexColor: calendarFixedCategoryColorHex(category, usesDarkAppearance: false)
                    ?? defaultCalendarFixedCategoryColorHex(for: category, usesDarkAppearance: false),
                darkHexColor: calendarFixedCategoryColorHex(category, usesDarkAppearance: true)
                    ?? defaultCalendarFixedCategoryColorHex(for: category, usesDarkAppearance: true)
            )
        }
        let settingsByID = Dictionary(firstWinsKeysWithValues: calendarCategoryColorSettings.map { ($0.id, $0) })
        settings.append(contentsOf: CalendarActivityColorRole.allCases.map { role in
            let id = CalendarCategoryColorSetting.activityColorID(for: role)
            let setting = settingsByID[id]
            return CalendarCategoryColorSetting(
                id: id,
                lightHexColor: setting?.lightHexColor ?? defaultCalendarNewActivityCategoryColorHex(usesDarkAppearance: false),
                darkHexColor: setting?.darkHexColor ?? defaultCalendarNewActivityCategoryColorHex(usesDarkAppearance: true)
            )
        })
        settings.append(
            CalendarCategoryColorSetting(
                id: CalendarCategoryColorSetting.newActivityCategoryDefaultColorID,
                lightHexColor: calendarNewActivityCategoryDefaultColorHex(usesDarkAppearance: false)
                    ?? defaultCalendarNewActivityCategoryColorHex(usesDarkAppearance: false),
                darkHexColor: calendarNewActivityCategoryDefaultColorHex(usesDarkAppearance: true)
                    ?? defaultCalendarNewActivityCategoryColorHex(usesDarkAppearance: true),
                colorSourceID: CalendarCategoryColorSetting.activityColorID(for: .activity1)
            )
        )
        return CalendarCategoryColorPreset(
            id: "default",
            name: name,
            settings: Self.normalizedCalendarCategoryColorSettings(settings)
        )
    }

    nonisolated static func standardCalendarCategoryColorPresets() -> [CalendarCategoryColorPreset] {
        [
            CalendarCategoryColorPreset(
                id: "default",
                name: "Standard",
                settings: calendarFixedCategoryPresetSettings(
                    light: .default,
                    dark: .darkDefault
                )
            )
        ] + builtInCalendarCategoryColorPresets()
    }

