    private nonisolated static func builtInCalendarCategoryColorPresets() -> [CalendarCategoryColorPreset] {
        builtInSemanticColorThemes.map { theme in
            CalendarCategoryColorPreset(
                id: theme.id,
                name: theme.name,
                settings: calendarFixedCategoryPresetSettings(
                    light: theme.light,
                    dark: theme.dark
                )
            )
        }
