    private nonisolated static func calendarFixedCategoryPresetSettings(
        light: AppSemanticColorSettings,
        dark: AppSemanticColorSettings
    ) -> [CalendarCategoryColorSetting] {
        var settings = CalendarFixedCategory.allCases.map { category in
            CalendarCategoryColorSetting(
                id: CalendarCategoryColorSetting.fixedColorID(for: category),
                lightHexColor: semanticSolidHex(
                    for: semanticTone(for: category),
                    in: light
                ),
                darkHexColor: semanticSolidHex(
                    for: semanticTone(for: category),
                    in: dark
                )
            )
        }

        settings.append(contentsOf: CalendarActivityColorRole.allCases.map { role in
            CalendarCategoryColorSetting(
                id: CalendarCategoryColorSetting.activityColorID(for: role),
                lightHexColor: semanticSolidHex(for: semanticTone(for: role), in: light),
                darkHexColor: semanticSolidHex(for: semanticTone(for: role), in: dark)
            )
        })

        settings.append(
            CalendarCategoryColorSetting(
                id: CalendarCategoryColorSetting.newActivityCategoryDefaultColorID,
                lightHexColor: semanticSolidHex(for: semanticTone(for: .activity1), in: light),
                darkHexColor: semanticSolidHex(for: semanticTone(for: .activity1), in: dark),
                colorSourceID: CalendarCategoryColorSetting.activityColorID(for: .activity1)
            )
        )

        return normalizedCalendarCategoryColorSettings(settings)
    }

    private nonisolated static let calendarFixedCategoryPresetSettingIDs: [String] =
        CalendarFixedCategory.allCases.map { CalendarCategoryColorSetting.fixedColorID(for: $0) }
        + CalendarActivityColorRole.allCases.map { CalendarCategoryColorSetting.activityColorID(for: $0) }
        + [CalendarCategoryColorSetting.newActivityCategoryDefaultColorID]

    nonisolated static func resolvedCalendarFixedCategoryPresetSettings(
        _ settings: [CalendarCategoryColorSetting],
        fallback: [CalendarCategoryColorSetting]
    ) -> [CalendarCategoryColorSetting] {
        let fallbackByID = Dictionary(firstWinsKeysWithValues: normalizedCalendarCategoryColorSettings(fallback).map { ($0.id, $0) })
        let overridesByID = Dictionary(firstWinsKeysWithValues: normalizedCalendarCategoryColorSettings(settings).map { ($0.id, $0) })

        return normalizedCalendarCategoryColorSettings(
            calendarFixedCategoryPresetSettingIDs.compactMap { id in
                overridesByID[id] ?? fallbackByID[id]
            }
        )
    }

