    private static func appSemanticColorPresets(
        stored: [AppSemanticColorPreset],
        useDarkAppearance: Bool
    ) -> [AppSemanticColorPreset] {
        let overrides = Dictionary(firstWinsKeysWithValues: normalizedAppSemanticColorPresets(stored, fallbackName: "Standard")
            .filter { isEditableAppSemanticColorPresetID($0.id) }
            .map { ($0.id, $0) })

        return standardAppSemanticColorPresets(useDarkAppearance: useDarkAppearance).map { preset in
            guard let override = overrides[preset.id] else { return preset }
            return AppSemanticColorPreset(
                id: preset.id,
                name: preset.name,
                colors: override.colors
            )
        }
    }

