    private nonisolated static func semanticTone(for category: CalendarFixedCategory) -> AppSemanticTone {
        switch category {
        case .travel:
            return .positive
        case .task:
            return .inProgress
        case .deadline:
            return .negative
        case .uncategorized:
            return .neutral
        }
    }

    private nonisolated static func semanticTone(for role: CalendarActivityColorRole) -> AppSemanticTone {
        switch role {
        case .activity1:
            return .neutral
        case .activity2:
            return .positive
        case .activity3:
            return .inProgress
        case .activity4:
            return .negative
        }
    }

    private nonisolated static func semanticSolidHex(for tone: AppSemanticTone, in settings: AppSemanticColorSettings) -> String {
        switch tone {
        case .negative:
            return settings.negative.solidHex
        case .inProgress:
            return settings.inProgress.solidHex
        case .positive:
            return settings.positive.solidHex
        case .neutral:
            return settings.neutral.solidHex
        }
    }

    private nonisolated static func semanticShadeHex(for tone: AppSemanticTone, in settings: AppSemanticColorSettings) -> String {
        switch tone {
        case .negative:
            return settings.negative.shadeHex
        case .inProgress:
            return settings.inProgress.shadeHex
        case .positive:
            return settings.positive.shadeHex
        case .neutral:
            return settings.neutral.shadeHex
        }
    }

