    func preparePublicationJournalRowSnapshots(reason: String) {
        guard publicationJournalRowSnapshotsAreStale || publicationJournalRowSnapshotsCache.isEmpty else { return }
        publicationJournalRowSnapshotBuildToken &+= 1
        let token = publicationJournalRowSnapshotBuildToken
        let journalsSnapshot = publicationJournals
        let derivedMetricsSnapshot = journalDerivedMetricsByIDCache
        let acceptanceStatsSnapshot = journalAcceptanceStatsByNameCache
        publicationJournalRowSnapshotTask?.cancel()
        publicationJournalRowSnapshotTask = Task.detached(priority: .userInitiated) { [weak self] in
            let startedAt = CFAbsoluteTimeGetCurrent()
            let snapshots = Self.publicationJournalRowSnapshots(
                journals: journalsSnapshot,
                derivedMetricsByID: derivedMetricsSnapshot,
                acceptanceStatsByName: acceptanceStatsSnapshot
            )
            let computeFinishedAt = CFAbsoluteTimeGetCurrent()
            let computeDuration = (computeFinishedAt - startedAt) * 1000
            guard !Task.isCancelled else { return }
            await MainActor.run {
                guard let self, token == self.publicationJournalRowSnapshotBuildToken else { return }
                let applyStartedAt = CFAbsoluteTimeGetCurrent()
                let mainActorWaitDuration = (applyStartedAt - computeFinishedAt) * 1000
                let changed = snapshots != self.publicationJournalRowSnapshotsCache
                if changed {
                    self.publicationJournalRowSnapshotsCache = snapshots
                    self.publicationJournalRowSnapshotGeneration &+= 1
                }
                self.publicationJournalRowSnapshotsAreStale = false
                self.publicationJournalRowSnapshotTask = nil
                let applyDuration = (CFAbsoluteTimeGetCurrent() - applyStartedAt) * 1000
                self.appendPerformanceDiagnostic(
                    String(
                        format: "publication-journal-row-snapshots-async reason=%@ rows=%ld changed=%@ compute_ms=%.2f main_wait_ms=%.2f apply_ms=%.2f total_ms=%.2f",
                        reason,
                        snapshots.count,
                        changed ? "yes" : "no",
                        computeDuration,
                        mainActorWaitDuration,
                        applyDuration,
                        (CFAbsoluteTimeGetCurrent() - startedAt) * 1000
                    )
                )
            }
        }
    }

    /// Warms read-only presentation caches after the first app frame. Both
    /// builders use immutable snapshots off the main actor, so launch remains
    /// responsive and the first Projects/Journals visit does not pay a cold cost.
    func scheduleLaunchPresentationCachePrewarm(delay: TimeInterval = 1.75) {
        DispatchQueue.main.asyncAfter(deadline: .now() + delay) { [weak self] in
            guard let self else { return }
            self.appendPerformanceDiagnostic("launch-presentation-prewarm start")
            self.scheduleProjectViewCacheRebuild()
            self.preparePublicationJournalRowSnapshots(reason: "launch-prewarm")
            Task.detached(priority: .utility) {
                PublicationLTWA.prewarmSharedStore()
            }
        }
    }

