    func publicationAuthor(matchingPresentedName name: String, includeNameVariants: Bool = true) -> PublicationAuthor? {
        let normalizedTarget = normalizedPersonLookupName(name)
        guard !normalizedTarget.isEmpty else { return nil }
        if includeNameVariants, let cached = publicationAuthorByPresentedName[normalizedTarget] {
            return cached
        }
        // Names that resolve to no researcher (external co-applicants, meeting
        // participants) recur across records; without a negative cache every
        // occurrence re-ran the full authors × name-variants scan below.
        if includeNameVariants, publicationAuthorPresentedNameMissCache.contains(normalizedTarget) {
            return nil
        }

        let match = publicationAuthors.first { author in
            let candidateNames: [String]
            if includeNameVariants {
                candidateNames = author.presentedNameCandidates
            } else {
                candidateNames = normalizedPublicationAuthorNameVariants([
                    author.name,
                    author.displayName,
                    [author.firstName.nonEmpty, author.lastName.nonEmpty].compactMap { $0 }.joined(separator: " ")
                ])
            }
            let candidates = candidateNames.map(normalizedPersonLookupName)

            return candidates.contains(normalizedTarget)
        }
        if includeNameVariants, match == nil {
            publicationAuthorPresentedNameMissCache.insert(normalizedTarget)
        }
        return match
    }

    func publicationJournal(named name: String) -> PublicationJournal? {
        let trimmed = name.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return nil }
        let normalizedISSN = Self.normalizedPublicationJournalISSNKey(trimmed)
        if let exactISSNMatch = publicationJournalByNormalizedISSN[normalizedISSN] {
            return exactISSNMatch
        }
        let canonicalName = Self.canonicalPublicationJournalLookupName(trimmed)
        if let exact = publicationJournalByName[canonicalName] {
            return exact
        }
        if let exact = publicationJournalByName[trimmed] {
            return exact
        }
        return publicationJournalByNormalizedName[Self.normalizedPublicationJournalLookupKey(canonicalName)]
    }

    private func publicationAuthorID(forPresentedName name: String?) -> String? {
        guard let trimmed = name?.trimmedOrNil else { return nil }
        if let exact = publicationAuthor(named: trimmed) {
            return exact.id
        }
        return publicationAuthor(matchingPresentedName: trimmed)?.id
    }

    var statisticsBlocks: [StatisticsYearBlock] {
        let grouped = Dictionary(grouping: applications, by: \.statsYear)
        return grouped.keys.sorted(by: >).map { year in
            let yearApplications = grouped[year] ?? []
            let rows = allResultOptions.map { result in
                let matching = yearApplications.filter { $0.resultLabel == result }
                return StatisticsResultRow(
                    result: result,
                    total: matching.count,
                    below250k: matching.filter { $0.amountBucket == .below }.count,
                    between250kAnd1m: matching.filter { $0.amountBucket == .between }.count,
                    above1m: matching.filter { $0.amountBucket == .above }.count
                )
            }
            return StatisticsYearBlock(id: year, year: year, resultRows: rows)
        }
    }

