    nonisolated private static let applicationSelectionScopePrefix = "application-scope:"
    nonisolated private static let applicationSelectionSeparator = "\u{1F}"

    nonisolated private static func scopedApplicationSelectionID(for application: GrantApplication) -> String {
        let separator = Self.applicationSelectionSeparator
        let components = [
            application.id,
            application.projectID ?? "",
            application.projectType ?? "",
            application.organization,
            application.appliedCaseNumber ?? "",
            application.receivedProjectNumber ?? "",
            application.receivedDisplayName ?? "",
            application.grantName,
            application.grantNameSv,
            application.grantNameEn,
            application.resultLabel
        ]
        .map { $0.replacingOccurrences(of: separator, with: " ") }
        return Self.applicationSelectionScopePrefix + components.joined(separator: separator)
    }

