    func derivedOrganizationCategory(city: String, country: String, fallback: String? = nil) -> String? {
        let normalizedCountry = normalizedOrganizationScopeValue(country)
        let normalizedCity = normalizedOrganizationScopeValue(city)
        let userCountry = currentUserOrganizationCountry()
        let userCities = currentUserOrganizationCities()

        if let normalizedCity, userCities.contains(normalizedCity) {
            return "Regional"
        }

        if let normalizedCountry, let userCountry {
            if normalizedCountry != userCountry {
                return "International"
            }
            return "National"
        }

        if let fallback = fallback?.trimmedOrNil {
            switch fallback {
            case "Local":
                return "Regional"
            case "National", "Regional", "International":
                return fallback
            default:
                break
            }
        }

        return nil
    }

