        return updatedName?.trimmedOrNil != previousName?.trimmedOrNil
    }

    private func synchronizedApplicationRelations(
        _ application: GrantApplication,
        previous: GrantApplication? = nil
    ) -> GrantApplication {
        var resolved = application
        let organization = resolvedOrganization(id: resolved.organizationID, name: resolved.organization)
        if let organization {
            resolved.organizationID = organization.id
            resolved.organization = organization.nameSv
        } else {
            resolved.organizationID = nil
            resolved.organization = resolved.organization.trimmingCharacters(in: .whitespacesAndNewlines)
        }

        let projectNameChanged = previous.map {
            applicationRelationNameDidChange(
                updatedName: resolved.projectType,
                previousName: $0.projectType,
                updatedID: resolved.projectID,
                previousID: $0.projectID
            )
        } ?? false
        let project = if projectNameChanged {
            if resolved.projectType?.trimmedOrNil == nil {
                Optional<ProjectRecord>.none
            } else {
                uniqueProject(named: resolved.projectType)
                    ?? resolvedProject(id: resolved.projectID, name: resolved.projectType)
            }
        } else {
            resolvedProject(id: resolved.projectID, name: resolved.projectType)
        }
        if let project {
            resolved.projectID = project.id
            resolved.projectType = project.nameSv
        } else {
            resolved.projectID = nil
            resolved.projectType = resolved.projectType?.trimmedOrNil
        }

        let manager = resolvedManager(id: resolved.applicationManagerID, name: resolved.applicationManager)
        if let manager {
            resolved.applicationManagerID = manager.id
            resolved.applicationManager = manager.nameSv
        } else {
            resolved.applicationManagerID = nil
            resolved.applicationManager = resolved.applicationManager?.trimmedOrNil
        }

        // F13b: the co-applicants by id; the names stay as display text.
        resolved.coApplicantAuthorIDs = synchronizedPersonAuthorIDs(
            existingIDs: resolved.coApplicantAuthorIDs,
            names: resolved.coApplicants
        )
        return resolved
    }

