    func projectViewData(forProjectName name: String?, language: AppLanguage) -> ProjectViewData? {
        guard let key = name?.trimmedOrNil else { return nil }
        if let resolved = resolvedProjectViewDataByLanguage[language.rawValue]?[key] {
            if isProjectViewCacheDirty {
                scheduleProjectViewCacheRebuild()
            }
            return resolved
        }
        var cached = projectViewCachesByLanguage[language.rawValue]?[key] ?? projectViewCachesByLanguage[AppLanguage.swedish.rawValue]?[key]
        if isProjectViewCacheDirty || projectViewCachesByLanguage.isEmpty {
            scheduleProjectViewCacheRebuild()
            if let cached {
                appendPerformanceDiagnostic(
                    String(
                        format: "project-cache-stale-hit project=%@ applications=%ld publications=%ld",
                        key,
                        cached.relatedApplicationIDs.count,
                        cached.relatedPublicationIDs.count
                    )
                )
            }
            // Build the selected project's current snapshot directly so the UI
            // never publishes stale related records while the prewarm catches up.
            cached = nil
        }
        if cached == nil {
            let projectApplications = applications(forProjectName: key)
            let projectPublications = publications(forProjectName: key)
            let project = project(named: key)
            let organizationLabels = organizations.reduce(into: [String: String]()) { labels, organization in
                let label = language == .swedish
                    ? organization.nameSv
                    : (organization.nameEn.nonEmpty ?? organization.nameSv)
                labels[organization.nameSv] = label
                // "Alla kopplingar via id": also findable by the organization's id.
                labels[Self.organizationLabelIDKeyPrefix + organization.id] = label
            }
            let applicationTitlesByID = Dictionary(
                projectApplications.map { ($0.id, displayTitle(for: $0, language: language)) },
                uniquingKeysWith: { first, _ in first }
            )
            let ownedApplicationIDs = Set(
                projectApplications.lazy.filter { self.isCurrentUserFirstApplicant($0) }.map(\.id)
            )
            let effectiveFullySpentDates = Dictionary(
                firstWinsKeysWithValues: projectApplications.compactMap { application -> (String, Date)? in
                    guard isEffectivelyFullySpent(application),
                          !application.isFullySpent,
                          let lastDispositionDate = application.lastDispositionDate else { return nil }
                    return (application.id, lastDispositionDate)
                }
            )
            let effectiveRemainingAmounts = Dictionary(
                firstWinsKeysWithValues: projectApplications.compactMap { application -> (String, Double)? in
                    guard let remaining = effectiveRemainingGrantedAmountValue(for: application) else { return nil }
                    return (application.id, remaining)
                }
            )
            let builtCache = Self.buildProjectViewCache(
                project: project,
                applications: projectApplications,
                publications: projectPublications,
                applicationTitlesByID: applicationTitlesByID,
                organizationLabels: organizationLabels,
                language: language,
                duplicateApplicationIDs: duplicateApplicationIDs(),
                ownedApplicationIDs: ownedApplicationIDs,
                effectiveFullySpentDates: effectiveFullySpentDates,
                effectiveRemainingAmounts: effectiveRemainingAmounts
            )
            projectViewCachesByLanguage[language.rawValue, default: [:]][key] = builtCache
            cached = builtCache
        }
        guard let cache = cached else {
            return nil
        }

        let projectApplications = applications(forProjectName: key)
        let resolved = ProjectViewData(
            relatedApplications: records(for: cache.relatedApplicationIDs, in: projectApplications),
            relatedPublications: cache.relatedPublicationIDs.compactMap { publicationByID[$0] },
            grantedApplications: records(for: cache.grantedApplicationIDs, in: projectApplications),
            awaitingDecisionApplications: records(for: cache.awaitingDecisionApplicationIDs, in: projectApplications),
            rejectedApplications: records(for: cache.rejectedApplicationIDs, in: projectApplications),
            projectApplicationsForList: records(for: cache.projectApplicationsForListIDs, in: projectApplications),
            projectPublications: cache.projectPublicationIDs.compactMap { publicationByID[$0] },
            orderedTimelineApplications: records(for: cache.orderedTimelineApplicationIDs, in: projectApplications),
            timelineSnapshot: cache.timelineSnapshot,
            ownedTimelineSnapshot: cache.ownedTimelineSnapshot
        )
        resolvedProjectViewDataByLanguage[language.rawValue, default: [:]][key] = resolved
        return resolved
    }

