        if let cached = publishedConferenceContributionsByProjectIDCache[targetProject.id] {
            return cached
        }
        return cvConferenceContributions
            .filter { contribution in
                guard isPublishedConferenceContribution(contribution) else { return false }
                return contributionBelongs(contribution, to: targetProject)
            }
            .sorted(by: conferenceContributionSortOrder)
    }

    func benchmarkProjectOpen(projectName: String, language: AppLanguage) -> String {
        let startedAt = CFAbsoluteTimeGetCurrent()
        let projectLookupStart = CFAbsoluteTimeGetCurrent()
        let project = self.project(named: projectName)
        let projectLookupDuration = (CFAbsoluteTimeGetCurrent() - projectLookupStart) * 1000

        let cacheBuildStart = CFAbsoluteTimeGetCurrent()
        let rebuiltCaches = Self.buildProjectViewCaches(
            applications: applications,
            publications: publicationRecords,
            organizations: organizations,
            projects: projects,
            ownedApplicationIDs: Set(applications.lazy.filter { self.isCurrentUserFirstApplicant($0) }.map(\.id)),
            effectiveFullySpentDates: effectiveProjectTimelineFullySpentDates(for: applications),
            effectiveRemainingAmounts: effectiveProjectTimelineRemainingAmounts(for: applications)
        )
        let cacheBuildDuration = (CFAbsoluteTimeGetCurrent() - cacheBuildStart) * 1000

        let rebuiltLookupStart = CFAbsoluteTimeGetCurrent()
        let rebuiltCache = rebuiltCaches[language.rawValue]?[projectName] ?? rebuiltCaches[AppLanguage.swedish.rawValue]?[projectName]
        let rebuiltLookupDuration = (CFAbsoluteTimeGetCurrent() - rebuiltLookupStart) * 1000

        let liveLookupStart = CFAbsoluteTimeGetCurrent()
        _ = projectViewCachesByLanguage[language.rawValue]?[projectName] ?? projectViewCachesByLanguage[AppLanguage.swedish.rawValue]?[projectName]
        let liveLookupDuration = (CFAbsoluteTimeGetCurrent() - liveLookupStart) * 1000

        let totalDuration = (CFAbsoluteTimeGetCurrent() - startedAt) * 1000
        let snapshot = rebuiltCache?.timelineSnapshot ?? .empty

        return [
            "project=\(projectName)",
            "project_exists=\(project != nil)",
            String(format: "project_lookup_ms=%.2f", projectLookupDuration),
            String(format: "cache_rebuild_ms=%.2f", cacheBuildDuration),
            String(format: "rebuilt_cache_lookup_ms=%.4f", rebuiltLookupDuration),
            String(format: "live_cache_lookup_ms=%.4f", liveLookupDuration),
            "timeline_years=\(snapshot.years.count)",
            "timeline_grant_bars=\(snapshot.grantBars.count)",
            "timeline_ethics_rows=\(snapshot.ethicsRows.count)",
            "timeline_data_rows=\(snapshot.dataCollectionRows.count)",
            "related_application_count=\(rebuiltCache?.relatedApplicationIDs.count ?? 0)",
            "related_publication_count=\(rebuiltCache?.relatedPublicationIDs.count ?? 0)",
            String(format: "total_ms=%.2f", totalDuration),
        ].joined(separator: "\n")
    }

    func benchmarkApplicationsView(searchText: String = "", language: AppLanguage) -> String {
        let startedAt = CFAbsoluteTimeGetCurrent()
        let query = SearchFilterQuery(raw: searchText)
        let snapshotBuildStart = CFAbsoluteTimeGetCurrent()
        let snapshots = applicationRowSnapshots()
        let snapshotBuildDuration = (CFAbsoluteTimeGetCurrent() - snapshotBuildStart) * 1000
        let filterStart = CFAbsoluteTimeGetCurrent()
        let filtered = query.isEmpty ? snapshots : snapshots.filter { query.matches(normalizedHaystack: $0.normalizedSearchBlob) }
        let filterDuration = (CFAbsoluteTimeGetCurrent() - filterStart) * 1000
        let sortStart = CFAbsoluteTimeGetCurrent()
        let sorted = filtered.sorted {
            if $0.sortClosesOn != $1.sortClosesOn {
                return $0.sortClosesOn > $1.sortClosesOn
            }
            return $0.sortGrantName.localizedStandardCompare($1.sortGrantName) == .orderedAscending
        }
        let sortDuration = (CFAbsoluteTimeGetCurrent() - sortStart) * 1000
        let totalDuration = (CFAbsoluteTimeGetCurrent() - startedAt) * 1000
        return [
            "query=\(searchText)",
            "rows=\(snapshots.count)",
            "filtered_rows=\(sorted.count)",
            String(format: "snapshot_lookup_ms=%.2f", snapshotBuildDuration),
            String(format: "filter_ms=%.2f", filterDuration),
            String(format: "sort_ms=%.2f", sortDuration),
            String(format: "total_ms=%.2f", totalDuration)
        ].joined(separator: "\n")
    }

