    func trimTransientCachesForBackgrounding() {
        backupSnapshotsCache = nil
        if localizedCountryNameCache.count > 256 {
            localizedCountryNameCache.removeAll(keepingCapacity: true)
        }
        if projectViewCachesByLanguage.count > 2 {
            projectViewCachesByLanguage.removeAll(keepingCapacity: false)
            resolvedProjectViewDataByLanguage.removeAll(keepingCapacity: false)
            isProjectViewCacheDirty = true
            pendingProjectViewCacheSnapshotSignature = nil
            projectViewCacheTask?.cancel()
            projectViewCacheTask = nil
        }
        if publicationSubmissionRowsByID.count > max(512, publicationRecords.count * 2) {
            publicationSubmissionRowsByID.removeAll(keepingCapacity: false)
        }
        if journalLinkedEntriesByName.count > 512 {
            journalLinkedEntriesByName.removeAll(keepingCapacity: false)
            journalLinkedEntriesByIDCache.removeAll(keepingCapacity: false)
        }
        if publishedConferenceContributionsByJournalNameCache.count > 512 {
            publishedConferenceContributionsByJournalNameCache.removeAll(keepingCapacity: false)
            publishedConferenceContributionsByJournalIDCache.removeAll(keepingCapacity: false)
            publishedConferenceContributionsByAuthorIDCache.removeAll(keepingCapacity: false)
            publishedConferenceContributionsByProjectIDCache.removeAll(keepingCapacity: false)
        }
        if mediaAppearancesByAuthorIDCache.count > 512 {
            mediaAppearancesByAuthorIDCache.removeAll(keepingCapacity: false)
        }
        if reviewEntriesByAuthorIDCache.count > 512 {
            reviewEntriesByAuthorIDCache.removeAll(keepingCapacity: false)
        }
        if teachingAssignmentsByAuthorIDCache.count > 512 {
            teachingAssignmentsByAuthorIDCache.removeAll(keepingCapacity: false)
        }
        if doctoralCandidatesBySupervisorAuthorIDCache.count > 512 {
            doctoralCandidatesBySupervisorAuthorIDCache.removeAll(keepingCapacity: false)
        }
        if recentPerformanceDiagnosticStateByKey.count > Self.trimmedDiagnosticThrottleKeys {
            pruneDiagnosticThrottleState(keepingMostRecent: Self.trimmedDiagnosticThrottleKeys)
        }
    }

