    private func refreshResearcherSupplementalCaches() {
        var mediaByAuthorID: [String: [CVMediaAppearance]] = [:]
        for appearance in cvMediaAppearances {
            let authorIDs = Set(appearance.authorIDs + [appearance.authorID].compactMap { $0 })
            for authorID in authorIDs.compactMap(\.trimmedOrNil) {
                mediaByAuthorID[authorID, default: []].append(appearance)
            }
        }
        mediaAppearancesByAuthorIDCache = mediaByAuthorID.mapValues { entries in
            entries.sorted {
                let leftDate = DateParsers.isoDay.date(from: $0.date) ?? .distantPast
                let rightDate = DateParsers.isoDay.date(from: $1.date) ?? .distantPast
                if leftDate != rightDate {
                    return leftDate > rightDate
                }
                return $0.displayTitle.localizedStandardCompare($1.displayTitle) == .orderedAscending
            }
        }

        var reviewsByAuthorID: [String: [CVReviewEntry]] = [:]
        for review in cvReviewEntries {
            guard let authorID = review.authorID?.trimmedOrNil else { continue }
            reviewsByAuthorID[authorID, default: []].append(review)
        }
        reviewEntriesByAuthorIDCache = reviewsByAuthorID.mapValues { entries in
            entries.sorted {
                let leftDate = DateParsers.isoDay.date(from: $0.date) ?? .distantPast
                let rightDate = DateParsers.isoDay.date(from: $1.date) ?? .distantPast
                if leftDate != rightDate {
                    return leftDate > rightDate
                }
                return $0.displayTitle.localizedStandardCompare($1.displayTitle) == .orderedAscending
            }
        }

        var assignmentsByAuthorID: [String: [TeachingAssignment]] = [:]
        for assignment in teachingAssignments {
            guard let authorID = assignment.authorID?.trimmedOrNil else { continue }
            assignmentsByAuthorID[authorID, default: []].append(assignment)
        }
        teachingAssignmentsByAuthorIDCache = assignmentsByAuthorID.mapValues { entries in
            entries.sorted { lhs, rhs in
                let leftDate = DateParsers.isoDay.date(from: teachingAssignmentFirstDate(lhs)) ?? .distantPast
                let rightDate = DateParsers.isoDay.date(from: teachingAssignmentFirstDate(rhs)) ?? .distantPast
                if leftDate != rightDate {
                    return leftDate < rightDate
                }
                let leftName = teachingCourses.first(where: { $0.id == lhs.contextID })?.name ?? lhs.activityName
                let rightName = teachingCourses.first(where: { $0.id == rhs.contextID })?.name ?? rhs.activityName
                return leftName.localizedStandardCompare(rightName) == .orderedAscending
            }
        }

        var candidatesBySupervisorID: [String: [DoctoralCandidateRecord]] = [:]
        for candidate in doctoralCandidates {
            for supervisor in candidate.supervisors {
                guard let authorID = supervisor.authorID?.trimmedOrNil else { continue }
                candidatesBySupervisorID[authorID, default: []].append(candidate)
            }
        }
        doctoralCandidatesBySupervisorAuthorIDCache = candidatesBySupervisorID.mapValues { entries in
            entries.sorted { lhs, rhs in
                let leftName = lhs.candidateName.nonEmpty ?? ""
                let rightName = rhs.candidateName.nonEmpty ?? ""
                if leftName != rightName {
                    return leftName.localizedStandardCompare(rightName) == .orderedAscending
                }
                let leftDate = DateParsers.isoDay.date(from: lhs.plannedDisputationDate) ?? .distantFuture
                let rightDate = DateParsers.isoDay.date(from: rhs.plannedDisputationDate) ?? .distantFuture
                if leftDate != rightDate {
                    return leftDate < rightDate
                }
                return lhs.id < rhs.id
            }
        }
    }

