    func publicationAuthorOrganizationOptions(language: AppLanguage) -> PublicationAuthorOrganizationOptions {
        if let cached = publicationAuthorOrganizationOptionsCacheByLanguage[language.rawValue] {
            return cached
        }

        let labeledOrganizations = organizations.map { organization in
            (
                roles: organization.roles,
                label: organizationLabel(for: organization.nameSv, language: language)
            )
        }

        let options = PublicationAuthorOrganizationOptions(
            employerOptions: labeledOrganizations
                .filter { $0.roles.contains(.employer) }
                .map(\.label)
                .sorted { $0.localizedStandardCompare($1) == .orderedAscending },
            institutionOptions: labeledOrganizations
                .filter { $0.roles.contains(.institution) }
                .map(\.label)
                .sorted { $0.localizedStandardCompare($1) == .orderedAscending },
            affiliationOptions: labeledOrganizations
                .map(\.label)
                .sorted { $0.localizedStandardCompare($1) == .orderedAscending }
        )
        publicationAuthorOrganizationOptionsCacheByLanguage[language.rawValue] = options
        return options
    }

