    func displayTitle(for application: GrantApplication, language: AppLanguage) -> String {
        let organizationName = organizationLabel(for: application, language: language).nonEmpty
        let grantName = application.localizedGrantName(language: language).nonEmpty

        switch (organizationName, grantName) {
        case let (.some(organization), .some(grant)):
            return "\(organization), \(grant)"
        case let (.some(organization), nil):
            return organization
        case let (nil, .some(grant)):
            return grant
        default:
            return language.text("Untitled grant", "Namnlöst anslag")
        }
