    func save(application updated: GrantApplication, selectionID: String? = nil) {
        guard let index = applicationIndex(for: updated, selectionID: selectionID) else { return }
        let actionName = language.text("Edit application", "Redigera ansökan")
        let successMessage = language.text("Saved application changes.", "Sparade ändringar i ansökan.")
        let failureMessage = language.text("Could not save application changes.", "Kunde inte spara ändringar i ansökan.")
        let previousSnapshot = currentSnapshot()
        let previous = applications[index]

        do {
            let normalized = normalizedApplicationForPersistence(updated, previous: previous)
            let fundsProjects = projectsByApplyingNewFundsReceivedTasks(
                projects,
                application: normalized,
                previousApplication: previous
            )
            let updatedProjects = projectsByApplyingFundsRunOutTasks(
                fundsProjects ?? projects,
                application: normalized,
                previousApplication: previous
            ) ?? fundsProjects
            guard previous != normalized || updatedProjects != nil else { return }
            applications[index] = normalized
            if let updatedProjects {
                projects = updatedProjects
                refreshProjectIndexesAndCaches()
            }
            refreshApplicationsState(afterUpdating: normalized, previous: previous, at: index)
            try persistScope(.applications)
            if updatedProjects != nil {
                // The project tasks that followed the grant are saved too.
                try persistScope(.projects)
            }
            registerUndo(snapshot: previousSnapshot, actionName: actionName)
            appendRecentRecordRevision(actionName: actionName)
            notice = StoreNotice(message: successMessage, tone: .success)
            loadError = nil
            refreshCurrencyExchangeRatesIfNeeded()
            evaluateOngoingQuestion(previousApplication: previous, application: normalized)
        } catch {
            restoreSnapshotWithoutUndo(previousSnapshot)
            persistenceStatus.isSaving = false
            loadError = error.localizedDescription
            notice = StoreNotice(message: failureMessage, tone: .error)
        }
    }

    func autosave(application updated: GrantApplication, selectionID: String? = nil) {
        guard let index = applicationIndex(for: updated, selectionID: selectionID) else { return }
        let previous = applications[index]
        let previousProjects = projects
        do {
            let normalized = normalizedApplicationForPersistence(updated, previous: previous)
            let fundsProjects = projectsByApplyingNewFundsReceivedTasks(
                projects,
                application: normalized,
                previousApplication: previous
            )
            let updatedProjects = projectsByApplyingFundsRunOutTasks(
                fundsProjects ?? projects,
                application: normalized,
                previousApplication: previous
            ) ?? fundsProjects
            guard previous != normalized || updatedProjects != nil else { return }
            let affectedSet: PersistenceSet = updatedProjects == nil ? [.applications] : [.applications, .projects]
            let previousStates = try persistedBaselineDocumentStates(for: affectedSet)
            applications[index] = normalized
            if let updatedProjects {
                projects = updatedProjects
                refreshProjectIndexesAndCaches()
            }
            refreshApplicationsState(afterUpdating: normalized, previous: previous, at: index)
            try enqueueAutosavePersistence(
                affectedSet,
                actionName: language.text("Edit application", "Redigera ansökan"),
                previousStates: previousStates
            )
            refreshCurrencyExchangeRatesIfNeeded()
            evaluateOngoingQuestion(previousApplication: previous, application: normalized)
        } catch {
            applications[index] = previous
            projects = previousProjects
            refreshProjectIndexesAndCaches()
            refreshApplicationsState()
            persistenceStatus.isSaving = false
            loadError = error.localizedDescription
        }
    }

    private func normalizedApplicationForPersistence(
        _ updated: GrantApplication,
        previous: GrantApplication
    ) -> GrantApplication {
        var normalized = updated
        normalized.refreshDerivedValues()
        normalized = synchronizedApplicationRelations(normalized, previous: previous)
        normalized.coApplicants = Array(
            NSOrderedSet(array: normalized.coApplicants.compactMap(\.trimmedOrNil))
        ) as? [String] ?? normalized.coApplicants

        return normalized
    }

    /// Round 12: an event happened for a project ("Publikation tillagd",
    /// "Publikation publicerad", "Medlen tar slut"): its open tasks waiting for
    /// that event are due today, as tasks waiting for "Datainsamling klar"
    /// already were. Nil when nothing changes.
    private func projectsByTriggeringEventTasks(
        _ projectRecords: [ProjectRecord],
        projectID: String?,
        reminder: ProjectTaskReminder
    ) -> [ProjectRecord]? {
        guard let projectID = projectID?.trimmedOrNil,
              let projectIndex = projectRecords.firstIndex(where: { $0.id == projectID }) else { return nil }
        let todayString = DateParsers.isoDay.string(from: Calendar.current.startOfDay(for: Date()))
        var changed = false
        let tasks = projectRecords[projectIndex].projectTasks.map { task -> ProjectTaskItem in
            guard task.reminder == reminder,
                  !task.isEmpty,
                  !task.isCompleted,
                  DateParsers.canonicalizedDayInput(task.deadline).trimmingCharacters(in: .whitespacesAndNewlines) != todayString else {
                return task
            }
            var copy = task
            if copy.createdOn.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                copy.createdOn = todayString
            }
            copy.deadline = todayString
            copy.updatedOn = todayString
            changed = true
            return copy
        }
        guard changed else { return nil }
        var updated = projectRecords
        updated[projectIndex].projectTasks = tasks
        return updated
    }

    /// Round 12: "Medlen tar slut" when a grant becomes fully spent.
    private func projectsByApplyingFundsRunOutTasks(
        _ projectRecords: [ProjectRecord],
        application: GrantApplication,
        previousApplication: GrantApplication
    ) -> [ProjectRecord]? {
        guard application.isFullySpent, !previousApplication.isFullySpent else { return nil }
        return projectsByTriggeringEventTasks(projectRecords, projectID: application.projectID, reminder: .fundsRunOut)
    }

    /// Round 12: "Publikation tillagd" when a publication is linked to a
    /// project, and "Publikation publicerad" when a linked one is published.
    private func projectsByApplyingPublicationEventTasks(
        _ projectRecords: [ProjectRecord],
        publication: PublicationRecord,
        previousPublication: PublicationRecord
    ) -> [ProjectRecord]? {
        var result: [ProjectRecord]?
        let projectID = publication.projectID?.trimmedOrNil
        if let projectID, projectID != previousPublication.projectID?.trimmedOrNil {
            result = projectsByTriggeringEventTasks(result ?? projectRecords, projectID: projectID, reminder: .publicationAdded) ?? result
        }
        if projectID != nil,
           PublicationStatus.fromStored(publication.statusLabel) == .published,
           PublicationStatus.fromStored(previousPublication.statusLabel) != .published {
            result = projectsByTriggeringEventTasks(result ?? projectRecords, projectID: projectID, reminder: .publicationPublished) ?? result
        }
        return result
    }

    private func projectsByApplyingNewFundsReceivedTasks(
        _ projectRecords: [ProjectRecord],
        application: GrantApplication,
        previousApplication: GrantApplication
    ) -> [ProjectRecord]? {
        guard application.isGranted,
              let applicationID = application.id.trimmedOrNil,
              let projectID = application.projectID?.trimmedOrNil,
              let projectIndex = projectRecords.firstIndex(where: { $0.id == projectID }) else {
            return nil
        }

        let calendar = Calendar.current
        let today = calendar.startOfDay(for: Date())
        let todayString = DateParsers.isoDay.string(from: today)
        let taskDeadline = application.grantedOn?.trimmedOrNil
            ?? application.decisionOn?.trimmedOrNil
            ?? application.resolvedDecisionDateString
            ?? todayString
        let previousTaskDeadline = previousApplication.grantedOn?.trimmedOrNil
            ?? previousApplication.decisionOn?.trimmedOrNil
            ?? previousApplication.resolvedDecisionDateString

        let templates = projectRecords[projectIndex].projectTasks.compactMap { task -> (ProjectTaskItem, String)? in
            var normalizedTask = task
            normalizedTask.normalize()
            guard normalizedTask.reminder == .newFundsReceived,
                  normalizedTask.applicationID?.trimmedOrNil == nil,
                  normalizedTask.completedOn?.trimmedOrNil == nil,
                  !normalizedTask.isEmpty,
                  let commentKey = normalizedProjectTaskCommentKey(normalizedTask.comment) else {
                return nil
            }
            return (normalizedTask, commentKey)
        }
        guard !templates.isEmpty else { return nil }

        var tasks = projectRecords[projectIndex].projectTasks.map { task -> ProjectTaskItem in
            var normalizedTask = task
            normalizedTask.normalize()
            return normalizedTask
        }
        var changed = false

        for (template, commentKey) in templates {
            if let existingIndex = tasks.firstIndex(where: { task in
                task.reminder == .newFundsReceived
                    && task.applicationID?.trimmedOrNil == applicationID
                    && normalizedProjectTaskCommentKey(task.comment) == commentKey
            }) {
                var existing = tasks[existingIndex]
                var existingChanged = false
                let currentDeadline = existing.deadline.trimmedOrNil
                let shouldUpdateDeadline = currentDeadline == nil
                    || currentDeadline == taskDeadline
                    || currentDeadline == previousTaskDeadline
                if shouldUpdateDeadline, currentDeadline != taskDeadline {
                    existing.deadline = taskDeadline
                    existingChanged = true
                }
                if existing.createdOn.trimmedOrNil == nil {
                    existing.createdOn = todayString
                    existingChanged = true
                }
                if existingChanged {
                    existing.updatedOn = todayString
                    existing.normalize()
                    tasks[existingIndex] = existing
                    changed = true
                }
            } else {
                var newTask = template
                newTask.id = UUID().uuidString
                newTask.createdOn = todayString
                newTask.updatedOn = todayString
                newTask.deadline = taskDeadline
                newTask.applicationID = applicationID
                newTask.completedOn = nil
                newTask.normalize()
                tasks.append(newTask)
                changed = true
            }
        }

        guard changed else { return nil }
        var updatedProjects = projectRecords
        updatedProjects[projectIndex].projectTasks = tasks.filter { !$0.isEmpty }
        return updatedProjects
    }

    func addApplication() -> String {
        let newID = UUID().uuidString
        let nextRow = (applications.map(\.rowNumber).max() ?? 0) + 1
        let organization = ""
        let calendar = Calendar.current
        let today = calendar.startOfDay(for: Date())
        let defaults = workflowDefaultSettings
        let opensDate = calendar.date(byAdding: .month, value: defaults.resolvedOpensAfterMonths, to: today)
        let closesDate = calendar.date(byAdding: .month, value: defaults.resolvedClosesAfterMonths, to: today)

        let newApplication = GrantApplication(
            id: newID,
            rowNumber: nextRow,
            organization: organization,
            grantName: language.text("New grant", "Nytt bidrag"),
            grantCategory: nil,
            currency: defaults.resolvedCurrency,
            opensOn: opensDate.map(DateParsers.isoDay.string(from:)),
            closesOn: closesDate.map(DateParsers.isoDay.string(from:)),
            projectType: nil,
            result: defaults.resolvedStatus
        )

        performUndoableChange(
            actionName: language.text("Add application", "Lägg till ansökan"),
            successMessage: language.text("Added application record.", "Lade till ansökningspost."),
            failureMessage: language.text("Could not add application record.", "Kunde inte lägga till ansökningspost."),
            scope: .applications
        ) {
            applications.insert(newApplication, at: 0)
        }

        return newID
    }

    /// "Kopiera till nästa år": adds next year's record for the call and
    /// returns its id. Nil when the record is not found.
    @discardableResult
    func copyApplicationToNextYear(id: String) -> String? {
        guard let source = applications.first(where: { $0.id == id }) else { return nil }
        let newID = UUID().uuidString
        let nextRow = (applications.map(\.rowNumber).max() ?? 0) + 1
        let copy = source.copiedToNextYear(
            newID: newID,
            rowNumber: nextRow,
            status: workflowDefaultSettings.resolvedStatus
        )
        performUndoableChange(
            actionName: language.text("Copy to next year", "Kopiera till nästa år"),
            successMessage: language.text("Created next year's record.", "Skapade nästa års post."),
            failureMessage: language.text("Could not copy the record.", "Kunde inte kopiera posten."),
            scope: .applications
        ) {
            applications.insert(copy, at: 0)
        }
        return newID
    }

    func deleteApplication(id: String) {
        performUndoableChange(
            actionName: language.text("Archive application", "Arkivera ansökan"),
            successMessage: language.text("Archived application record.", "Arkiverade ansökningspost."),
            failureMessage: language.text("Could not archive application record.", "Kunde inte arkivera ansökningspost."),
            scope: .applications
        ) {
            if let application = applications.first(where: { $0.id == id }) {
                try archiveDeletion(kind: "application", title: application.grantName.nonEmpty ?? application.id, payload: application)
            }
            applications.removeAll { $0.id == id }
        }
    }

    private func deletionImpactDetailsForOrganization(name: String, id: String?) -> [String] {
        // "Alla kopplingar via id": a row with a link counts when the link
        // points here; a row without one counts when its text is the name.
        func pointsHere(_ rowID: String?, _ rowName: String?) -> Bool {
            if let rowID = rowID?.trimmedOrNil {
                return rowID == id
            }
            return rowName == name
        }
        let applicationsAsFunder = applications.filter { pointsHere($0.organizationID, $0.organization) }.count
        let applicationsAsManager = applications.filter { pointsHere($0.applicationManagerID, $0.applicationManager) }.count
        let teachingInstitutions = teachingCourses.filter { pointsHere($0.institutionID, $0.institution) }.count
        let affiliationCount = publicationAuthors.reduce(0) { partial, author in
            partial + author.affiliations.filter { pointsHere($0.organizationID, $0.organization) }.count
        }
        let employmentCount = publicationAuthors.reduce(0) { partial, author in
            partial + author.employments.filter { pointsHere($0.organizationID, $0.organization) }.count
        }
        let educationCount = publicationAuthors.reduce(0) { partial, author in
            partial + author.educationEntries.filter { pointsHere($0.organizationID, $0.organization) }.count
        }
        let conferenceCongressLinks = id.map { targetID in
            cvConferenceContributions.filter { $0.congressOrganizationID == targetID }.count
        } ?? 0

        return [
            deletionImpactLine(applicationsAsFunder, english: "linked grant applications as funder", swedish: "kopplade anslag som anslagsgivare"),
            deletionImpactLine(applicationsAsManager, english: "linked grant applications as fund manager", swedish: "kopplade anslag som medelsförvaltare"),
            deletionImpactLine(teachingInstitutions, english: "linked teaching contexts", swedish: "kopplade undervisningskontexter"),
            deletionImpactLine(affiliationCount, english: "researcher affiliations", swedish: "forskaraffiliationer"),
            deletionImpactLine(employmentCount, english: "researcher employments", swedish: "forskaranställningar"),
            deletionImpactLine(educationCount, english: "researcher education entries", swedish: "forskarutbildningar"),
            deletionImpactLine(conferenceCongressLinks, english: "conference congress links", swedish: "kongresskopplingar i konferensbidrag")
        ].compactMap { $0 }
    }

    private func deletionImpactDetailsForManager(name: String) -> [String] {
        // "Alla kopplingar via id": linked rows by id, older rows by name.
        let managerID = manager(matchingName: name)?.id
        return [
