    private func deletionImpactDetailsForPublicationAuthor(id: String) -> [String] {
        guard let author = publicationAuthors.first(where: { $0.id == id }) else { return [] }
        let variants = authorNameVariants(for: author)
        let publicationCount = publicationRecords.reduce(0) { $0 + ($1.authorNames.filter { variants.contains($0) }.isEmpty ? 0 : 1) }
        let applicationCount = applications.reduce(0) { $0 + ($1.coApplicants.filter { variants.contains($0) }.isEmpty ? 0 : 1) }
        let projectCount = projects.reduce(0) { $0 + ($1.collaboratorNames.filter { variants.contains($0) }.isEmpty ? 0 : 1) }
        let teachingCount = teachingAssignments.filter { variants.contains($0.studentName) }.count
        let doctoralCount = doctoralCandidates.reduce(0) { partial, candidate in
            let candidateMatches = variants.contains(candidate.candidateName)
            let supervisorMatches = candidate.supervisors.contains { variants.contains($0.name) }
            return partial + ((candidateMatches || supervisorMatches) ? 1 : 0)
        }
        let conferenceCount = cvConferenceContributions.reduce(0) { partial, contribution in
            partial + ((variants.contains(contribution.presentedBy) || !contribution.contributorNames.filter { variants.contains($0) }.isEmpty) ? 1 : 0)
        }
        return [
            deletionImpactLine(publicationCount, english: "linked publications", swedish: "kopplade publikationer"),
            deletionImpactLine(applicationCount, english: "linked grant applications", swedish: "kopplade anslag"),
            deletionImpactLine(projectCount, english: "linked projects", swedish: "kopplade projekt"),
            deletionImpactLine(teachingCount, english: "linked teaching assignments", swedish: "kopplade undervisningsuppdrag"),
            deletionImpactLine(doctoralCount, english: "linked doctoral candidates", swedish: "kopplade doktorander"),
            deletionImpactLine(conferenceCount, english: "linked conference contributions", swedish: "kopplade konferensbidrag")
        ].compactMap { $0 }
    }

    private func deletionImpactDetailsForPublicationJournal(id: String, name: String?) -> [String] {
        let journalName = name ?? ""
        // "Alla kopplingar via id": linked rows by id, older rows by name.
        let publicationCount = publicationRecords.filter {
