        return [
            deletionImpactLine(publicationCount, english: "linked publications", swedish: "kopplade publikationer"),
            deletionImpactLine(conferenceCount, english: "linked conference contributions", swedish: "kopplade konferensbidrag"),
            deletionImpactLine(reviewCount, english: "linked review assignments", swedish: "kopplade sakkunniguppdrag")
        ].compactMap { $0 }
    }

    func amaCitation(for publication: PublicationRecord) -> String {
        amaCitationItem(for: publication, options: PublicationExportOptions()).plain
    }

    func amaCitationItem(for publication: PublicationRecord, options: PublicationExportOptions = PublicationExportOptions()) -> PublicationAMAItem {
        let authorEntries = amaAuthorEntries(for: publication)
        let visibleAuthorIndices = amaVisibleAuthorIndices(for: authorEntries, options: options)
        let authorText = amaAuthorList(from: authorEntries, visibleAuthorIndices: visibleAuthorIndices, options: options)
        let exportLanguage = options.exportLanguage ?? language
        let titleText = publication.title.nonEmpty ?? exportLanguage.text("Untitled", "Utan titel")
        let journal = linkedJournal(of: publication)
        let journalText: String = {
            switch options.journalNameMode {
            case .abbreviated:
                return publicationJournalShortName(journal, style: options.journalShortNameStyle)
                    ?? journal?.name.nonEmpty
                    ?? publication.journal.nonEmpty
                    ?? ""
            case .full:
                return journal?.name.nonEmpty
                    ?? publicationJournalShortName(journal, style: options.journalShortNameStyle)
                    ?? publication.journal.nonEmpty
                    ?? ""
            }
        }()
        let status = PublicationStatus.fromStored(publication.statusLabel)
        let note = amaSharedAuthorshipNote(for: publication, visibleAuthorIndices: visibleAuthorIndices)

        if status == .published {
            var tailSegments: [String] = []
            let bibliographicDateText = publicationBibliographicDateText(for: publication, options: options)
            var bibliographic = bibliographicDateText ?? ""
            if let volume = publication.volume.nonEmpty {
                bibliographic += bibliographic.isEmpty ? volume : ";\(volume)"
                if let issue = publication.issue.nonEmpty {
                    bibliographic += "(\(issue))"
                }
                if let pageRange = publication.pageRange.nonEmpty {
                    bibliographic += ":\(pageRange)"
                } else if let articleNumber = publication.articleNumber.nonEmpty {
                    bibliographic += ":\(articleNumber)"
                }
            } else if let bibliographicDateText, let articleNumber = publication.articleNumber.nonEmpty {
                bibliographic = "\(bibliographicDateText):\(articleNumber)"
            }
            if let bibliographic = bibliographic.nonEmpty {
                tailSegments.append(bibliographic)
            }
            if options.includeDOI, let doi = publication.doi.trimmedOrNil {
                tailSegments.append("doi:\(normalizedDOI(doi))")
            }
            if options.includeEpubDate, let epubDate = formattedPublicationEpubDate(publication.epubDate) {
                tailSegments.append(epubDate)
            }
            if options.includePMID, let pmid = publication.pmid.trimmedOrNil {
                tailSegments.append("PMID: \(pmid)")
            }
            if let metrics = amaPublicationMetricsText(for: publication, options: options) {
                tailSegments.append("(\(metrics))")
            }
            let tail = tailSegments.joined(separator: ". ")
            let citation = PublicationCitationFormatting.terminated(
                PublicationCitationFormatting.joinedSegments([authorText, titleText, journalText, tail])
            )
            let plain = citation + (note.isEmpty ? "" : " \(note)")
            return PublicationAMAItem(
                authors: authorText,
                title: titleText,
                journal: journalText,
                tail: tail,
                note: note,
                plain: plain,
                sourceID: "publication-\(publication.id)"
            )
        }

        // Round 12: the status in the export's language; an accepted article
        // says so in the citation itself.
        let statusPhrase: String
        switch status {
        case .submitted:
            statusPhrase = exportLanguage.text("In review", "Under granskning")
        case .planned, .inPreparation:
            statusPhrase = exportLanguage.text("In preparation", "Under arbete")
        case .accepted:
            statusPhrase = exportLanguage.text("Accepted for publication", "Accepterad för publicering")
        case .rejected:
            statusPhrase = exportLanguage.text("Rejected", "Refuserad")
        case .published:
            statusPhrase = ""
        }

        var tailSegments: [String] = []
        if let year = publication.year.nonEmpty {
            tailSegments.append(year)
        }
        if !statusPhrase.isEmpty {
            tailSegments.append(statusPhrase)
        }
        if options.includeDOI, let doi = publication.doi.trimmedOrNil {
            tailSegments.append("doi:\(normalizedDOI(doi))")
        }
        if options.includeEpubDate, let epubDate = formattedPublicationEpubDate(publication.epubDate) {
            tailSegments.append(epubDate)
        }
        if options.includePMID, let pmid = publication.pmid.trimmedOrNil {
            tailSegments.append("PMID: \(pmid)")
        }
        if let metrics = amaPublicationMetricsText(for: publication, options: options) {
            tailSegments.append("(\(metrics))")
        }
        let tail = tailSegments.joined(separator: ". ")
        let finalNote: String = note
        let citation = PublicationCitationFormatting.terminated(
            PublicationCitationFormatting.joinedSegments([authorText, titleText, journalText, tail])
        )
        let plain = citation + (finalNote.isEmpty ? "" : " \(finalNote)")
        return PublicationAMAItem(
            authors: authorText,
            title: titleText,
            journal: journalText,
            tail: tail,
            note: finalNote,
            plain: plain,
            sourceID: "publication-\(publication.id)"
        )
    }

    private func publicationJournalShortName(
        _ journal: PublicationJournal?,
        style: PublicationJournalShortNameStyle
    ) -> String? {
        guard let journal else { return nil }
        switch style {
        case .nlm:
            return journal.abbreviatedName.nonEmpty
        case .issnLTWA:
            return journal.resolvedISSNLTWAAbbreviatedName.nonEmpty
        }
    }

    func copyAMACitation(for publication: PublicationRecord) {
        copyAMACitation(for: publication, options: PublicationExportOptions())
    }

    func copyAMACitation(for publication: PublicationRecord, options: PublicationExportOptions) {
        let item = amaCitationItem(for: publication, options: options)
        let attributedCitation = amaAttributedCitation(for: item)
        let pasteboard = NSPasteboard.general
        pasteboard.clearContents()
        pasteboard.setString(item.plain, forType: .string)
        if let rtfData = try? attributedCitation.data(
            from: NSRange(location: 0, length: attributedCitation.length),
            documentAttributes: [.documentType: NSAttributedString.DocumentType.rtf]
        ) {
            pasteboard.setData(rtfData, forType: .rtf)
        }
        showClipboardPreview(item.plain)
        notice = StoreNotice(message: language.text("Copied AMA reference.", "Kopierade AMA-referens."), tone: .success)
        loadError = nil
    }

    func publicationJournalListExportText(
        journalNames: [String],
        publicationYear: Int?,
        language exportLanguage: AppLanguage? = nil
    ) -> String {
        let resolvedLanguage = exportLanguage ?? language
        let segments = publicationJournalListExportSegments(
            journalNames: journalNames,
            publicationYear: publicationYear,
            language: resolvedLanguage
        )
        return segments.enumerated().map { index, segment in
            let separator = publicationJournalListSeparator(
                before: index,
                count: segments.count,
                language: resolvedLanguage
            )
            return separator + segment.text
        }
        .joined()
    }

    func copyPublicationJournalList(
        journalNames: [String],
        publicationYear: Int?,
        languageMode: FundingStatementLanguageMode
    ) {
        let exportLanguage: AppLanguage = languageMode == .english ? .english : .swedish
        let segments = publicationJournalListExportSegments(
            journalNames: journalNames,
            publicationYear: publicationYear,
            language: exportLanguage
        )
        guard !segments.isEmpty else { return }

        let attributed = NSMutableAttributedString()
        let baseFont = NSFont.systemFont(ofSize: NSFont.systemFontSize)
        let italicFont = NSFontManager.shared.convert(baseFont, toHaveTrait: .italicFontMask)
        for (index, segment) in segments.enumerated() {
            attributed.append(
                NSAttributedString(
                    string: publicationJournalListSeparator(before: index, count: segments.count, language: exportLanguage),
                    attributes: [.font: baseFont]
                )
            )
            attributed.append(NSAttributedString(string: segment.name, attributes: [.font: italicFont]))
            attributed.append(NSAttributedString(string: segment.metrics, attributes: [.font: baseFont]))
        }

        let pasteboard = NSPasteboard.general
        pasteboard.clearContents()
        pasteboard.setString(attributed.string, forType: .string)
        if let rtfData = try? attributed.data(
            from: NSRange(location: 0, length: attributed.length),
            documentAttributes: [.documentType: NSAttributedString.DocumentType.rtf]
        ) {
            pasteboard.setData(rtfData, forType: .rtf)
        }
        showClipboardPreview(attributed.string)
        notice = StoreNotice(
            message: language.text("Copied journal list.", "Kopierade tidskriftslista."),
            tone: .success
        )
        loadError = nil
    }

    private func publicationJournalListExportSegments(
        journalNames: [String],
        publicationYear: Int?,
        language exportLanguage: AppLanguage
    ) -> [(name: String, metrics: String, text: String)] {
        var seen = Set<String>()
        return journalNames.compactMap { rawName in
            guard let name = rawName.trimmedOrNil else { return nil }
            let journal = publicationJournal(named: name)
            let key = journal?.id ?? name.folding(
                options: [.diacriticInsensitive, .caseInsensitive],
                locale: .current
            )
            guard seen.insert(key).inserted else { return nil }

            let jifMetric = journal?
                .preferredMetric(for: [.clarivateScieJIF, .clarivateEsciJIF], publicationYear: publicationYear)
            let jif = jifMetric.map(publicationJournalListMetricText) ?? "–"
            let quartile = jifMetric.map(publicationJournalListQuartileText) ?? "–"
            let norwegian = journal?
                .preferredMetric(for: [.norwegianList], publicationYear: publicationYear)
                .map { formattedRankingMetricValue($0) } ?? "–"
            let metrics = exportLanguage.text(
                " (IF \(jif), \(quartile), Norwegian list \(norwegian))",
                " (IF \(jif), \(quartile), norska listan \(norwegian))"
            )
            return (journal?.name ?? name, metrics, (journal?.name ?? name) + metrics)
        }
    }

    private func publicationJournalListMetricText(_ metric: PublicationMetricValue) -> String {
        let value = formattedRankingMetricValue(metric)
        return metric.kind == .clarivateEsciJIF || metric.flagsUncertainty ? "\(value)?" : value
    }

    private func publicationJournalListQuartileText(_ metric: PublicationMetricValue) -> String {
        guard let quartile = metric.quartile.trimmedOrNil else { return "–" }
        let uppercased = quartile.uppercased()
        return uppercased.hasPrefix("Q") ? uppercased : "Q\(uppercased)"
    }

    private func publicationJournalListSeparator(before index: Int, count: Int, language: AppLanguage) -> String {
        guard index > 0 else { return "" }
        if index == count - 1 {
            return language.text(" and ", " och ")
        }
        return ", "
    }

    func salaryCoverageExportRows(language targetLanguage: AppLanguage? = nil) -> [SalaryCoverageExportRow] {
        let exportLanguage = targetLanguage ?? language
        let sourcesByID = Dictionary(firstWinsKeysWithValues: salarySources.map { ($0.id, $0) })
        return salaryCoveragePeriods
            .sorted {
                let lhsFrom = DateParsers.isoDay.date(from: salaryNormalizedDateInput($0.from)) ?? .distantFuture
                let rhsFrom = DateParsers.isoDay.date(from: salaryNormalizedDateInput($1.from)) ?? .distantFuture
                if lhsFrom != rhsFrom { return lhsFrom < rhsFrom }
                let lhsTo = DateParsers.isoDay.date(from: salaryNormalizedDateInput($0.to)) ?? .distantFuture
                let rhsTo = DateParsers.isoDay.date(from: salaryNormalizedDateInput($1.to)) ?? .distantFuture
                if lhsTo != rhsTo { return lhsTo < rhsTo }
                let lhsPercent = GrantParsing.numericValue(from: $0.percentage) ?? 0
                let rhsPercent = GrantParsing.numericValue(from: $1.percentage) ?? 0
                return lhsPercent > rhsPercent
            }
            .compactMap { period in
                let from = salaryNormalizedDateInput(period.from)
                let to = salaryNormalizedDateInput(period.to)
                let percentage = salaryFormattedPercentageInput(period.percentage)
                if period.sourceReference.hasPrefix("custom:") {
                    let id = String(period.sourceReference.dropFirst("custom:".count))
                    guard let source = sourcesByID[id],
                          let label = salarySourceProjectLabel(for: source, language: exportLanguage) else { return nil }
                    return SalaryCoverageExportRow(
                        source: label,
                        projectNumber: source.projectNumber ?? "",
                        peoe: source.peoe ?? "",
                        percentage: percentage,
                        period: "\(from) – \(to)",
                        from: from,
                        to: to
                    )
                }
                if period.sourceReference.hasPrefix("grant:") {
                    let id = String(period.sourceReference.dropFirst("grant:".count))
                    guard let application = application(id: id) else { return nil }
                    return SalaryCoverageExportRow(
                        source: salaryGrantSourceLabel(for: application, language: exportLanguage),
                        projectNumber: application.receivedProjectNumber ?? "",
                        peoe: application.receivedPEOE ?? "",
                        percentage: percentage,
                        period: "\(from) – \(to)",
                        from: from,
                        to: to
                    )
                }
                return nil
            }
    }

    private func salarySourceProjectLabel(for source: SalarySource, language targetLanguage: AppLanguage) -> String? {
        switch targetLanguage {
        case .swedish:
            return source.projectSv?.nonEmpty
                ?? source.projectEn?.nonEmpty
                ?? source.project.nonEmpty
        case .english:
            return source.projectEn?.nonEmpty
                ?? source.projectSv?.nonEmpty
                ?? source.project.nonEmpty
        }
    }

    private func salaryGrantSourceLabel(for application: GrantApplication, language targetLanguage: AppLanguage) -> String {
        let funder = organizationLabel(for: application, language: targetLanguage)
        let project = projectLabel(for: application, language: targetLanguage)?.nonEmpty ?? targetLanguage.text("No project", "Saknar projekt")
        let grantNumber = application.appliedCaseNumber?.nonEmpty ?? targetLanguage.text("No number", "Saknar nummer")
        return "\(funder), \(project), \(grantNumber)"
    }

