    private func prefixedWorkbookSheets(prefix: String, sheets: [WorkbookExportSheet]) -> [WorkbookExportSheet] {
        sheets.map { sheet in
            let normalizedPrefix = prefix.trimmingCharacters(in: .whitespacesAndNewlines)
            let normalizedName = sheet.name.trimmingCharacters(in: .whitespacesAndNewlines)
            let combinedName = normalizedName == normalizedPrefix ? normalizedName : "\(normalizedPrefix) - \(normalizedName)"
            return WorkbookExportSheet(
                name: combinedName,
                rows: sheet.rows,
                style: sheet.style,
                currencyCells: sheet.currencyCells,
                hyperlinks: sheet.hyperlinks
            )
        }
    }

