    private static let workbookCellCharacterLimit = 30_000

    private func dataWorkbookSheetName(_ english: String, _ swedish: String) -> String {
        language.text("Data - \(english)", "Data - \(swedish)")
    }

    private func completeDataWorkbookSheet<T: Encodable>(
        name: String,
        records: [T],
        style: String? = nil
    ) -> WorkbookExportSheet {
        guard !records.isEmpty else {
            return WorkbookExportSheet(
                name: name,
                rows: [[language.text("No records", "Inga poster")]],
                style: style
            )
        }

        let flattenedRows = records.map { flattenedWorkbookFields(for: $0) }
        let headers = orderedWorkbookHeaders(from: flattenedRows)
        let rows = [headers] + flattenedRows.map { row in
            headers.map { row[$0] ?? "" }
        }
        return WorkbookExportSheet(name: name, rows: rows, style: style)
    }

    private func completeDataWorkbookSheet<T: Encodable>(
        name: String,
        record: T,
        style: String? = nil
    ) -> WorkbookExportSheet {
        completeDataWorkbookSheet(name: name, records: [record], style: style)
    }

    private func flattenedWorkbookFields<T: Encodable>(for record: T) -> [String: String] {
        do {
            let encoder = JSONEncoder()
            encoder.outputFormatting = [.sortedKeys]
            let data = try encoder.encode(record)
            let object = try JSONSerialization.jsonObject(with: data, options: [.fragmentsAllowed])
            var fields: [String: String] = [:]
            flattenWorkbookJSONObject(object, prefix: "", into: &fields)
            return fields
        } catch {
            return [
                "exportError": error.localizedDescription
            ]
        }
    }

    private func flattenWorkbookJSONObject(_ value: Any, prefix: String, into fields: inout [String: String]) {
        let fieldName = prefix.isEmpty ? "value" : prefix

        switch value {
        case let dictionary as [String: Any]:
            if dictionary.isEmpty {
                assignWorkbookField(fieldName, value: "{}", into: &fields)
                return
            }
            for key in dictionary.keys.sorted(by: { $0.localizedStandardCompare($1) == .orderedAscending }) {
                let childPrefix = prefix.isEmpty ? key : "\(prefix).\(key)"
                flattenWorkbookJSONObject(dictionary[key] as Any, prefix: childPrefix, into: &fields)
            }
        case let array as [Any]:
            assignWorkbookField(fieldName, value: workbookJSONString(array), into: &fields)
        case _ as NSNull:
            assignWorkbookField(fieldName, value: "", into: &fields)
        case let string as String:
            assignWorkbookField(fieldName, value: string, into: &fields)
        case let number as NSNumber:
            let value = CFGetTypeID(number) == CFBooleanGetTypeID()
                ? (number.boolValue ? "true" : "false")
                : number.stringValue
            assignWorkbookField(fieldName, value: value, into: &fields)
        default:
            assignWorkbookField(fieldName, value: "\(value)", into: &fields)
        }
    }

    private func assignWorkbookField(_ name: String, value: String, into fields: inout [String: String]) {
        let normalizedName = name.trimmingCharacters(in: .whitespacesAndNewlines).nonEmpty ?? "value"
        guard value.count > Self.workbookCellCharacterLimit else {
            fields[normalizedName] = value
            return
        }

        let chunks = workbookChunks(value, maximumCharacters: Self.workbookCellCharacterLimit)
        fields["\(normalizedName)__part_count"] = "\(chunks.count)"
        for (index, chunk) in chunks.enumerated() {
            let suffix = String(format: "%03d", index + 1)
            fields["\(normalizedName)__part_\(suffix)"] = chunk
        }
    }

    private func workbookChunks(_ value: String, maximumCharacters: Int) -> [String] {
        guard maximumCharacters > 0 else { return [value] }
        var chunks: [String] = []
        var start = value.startIndex
        while start < value.endIndex {
            let end = value.index(start, offsetBy: maximumCharacters, limitedBy: value.endIndex) ?? value.endIndex
            chunks.append(String(value[start..<end]))
            start = end
        }
        return chunks
    }

    private func workbookJSONString(_ value: Any) -> String {
        guard JSONSerialization.isValidJSONObject(value),
              let data = try? JSONSerialization.data(withJSONObject: value, options: [.sortedKeys]),
              let string = String(data: data, encoding: .utf8) else {
            return "\(value)"
        }
        return string
    }

    private func orderedWorkbookHeaders(from rows: [[String: String]]) -> [String] {
        let allHeaders = Set(rows.flatMap { $0.keys })
        let preferred = [
            "id",
            "value",
            "name",
            "title",
            "date",
            "from",
            "to",
        ]
        let leading = preferred.filter { allHeaders.contains($0) }
        let trailing = allHeaders
            .subtracting(leading)
            .sorted { $0.localizedStandardCompare($1) == .orderedAscending }
        return leading + trailing
    }

    private func homeWorkbookSheets() -> [WorkbookExportSheet] {
        let summaryRows = [
            [language.text("Metric", "Mått"), language.text("Value", "Värde")],
            [language.text("Applications", "Ansökningar"), "\(applications.count)"],
            [language.text("Granted applications", "Beviljade ansökningar"), "\(applications.filter(\.isGranted).count)"],
            [language.text("Projects", "Projekt"), "\(projects.count)"],
            [language.text("Researchers", "Forskare"), "\(publicationAuthors.count)"],
            [language.text("Organizations", "Organisationer"), "\(organizations.count)"],
            [language.text("Journals", "Tidskrifter"), "\(publicationJournals.count)"],
            [language.text("Publications", "Publikationer"), "\(publicationRecords.count)"],
        ]

        let upcomingClosing = applications
            .compactMap { application -> (GrantApplication, Date)? in
                guard let raw = application.closesOn?.nonEmpty, let date = DateParsers.isoDay.date(from: raw) else { return nil }
                return (application, date)
            }
            .sorted { $0.1 < $1.1 }
            .prefix(10)
            .map { application, date in
                [
                    organizationLabel(for: application, language: language),
                    application.grantName,
                    projectLabel(for: application, language: language) ?? "",
                    language.localizedStatus(application.resultLabel),
                    DateParsers.isoDay.string(from: date),
                ]
            }

        let tasks = homeTaskWorkbookRows()

        return [
            WorkbookExportSheet(name: language.text("Home summary", "Hemöversikt"), rows: summaryRows),
            WorkbookExportSheet(
                name: language.text("Closing soon", "Stänger snart"),
                rows: [[
                    language.text("Funder", "Anslagsgivare"),
                    language.text("Grant", "Anslag"),
                    language.text("Project", "Projekt"),
                    language.text("Status", "Status"),
                    language.text("Date", "Datum"),
                ]] + upcomingClosing
            ),
            WorkbookExportSheet(name: language.text("Tasks", "Uppgifter"), rows: tasks)
        ] + taskDataWorkbookSheets()
    }

    private func calendarWorkbookSheets() -> [WorkbookExportSheet] {
        let settingsRecord = CalendarSettingsWorkbookRecord(
            holidayCountries: holidayCountries.map(\.rawValue),
            firstWeekday: calendarWeekdayChoice.rawValue,
            countryDisplayMode: calendarCountryDisplayMode.rawValue,
            usesCompactEventColorBands: calendarUsesCompactEventColorBands,
            usesCompactDayHighlightBands: calendarUsesCompactDayHighlightBands,
            meetingTypeOptions: calendarMeetingTypeOptions
        )
        let deadlineRecords = applications
            .filter(calendarShowsApplicationDeadline)
            .compactMap { application -> ApplicationDeadlineWorkbookRecord? in
                guard let closesOn = application.closesOn?.nonEmpty else { return nil }
                return ApplicationDeadlineWorkbookRecord(displayDate: closesOn, application: application)
            }

        return [
            completeDataWorkbookSheet(
                name: dataWorkbookSheetName("Calendar settings", "Kalenderinställningar"),
                record: settingsRecord
            ),
            completeDataWorkbookSheet(
                name: dataWorkbookSheetName("Calendar travels", "Kalenderresor"),
                records: calendarTravelRecords
            ),
            completeDataWorkbookSheet(
                name: dataWorkbookSheetName("Calendar accommodation", "Kalenderboende"),
                records: calendarAccommodationRecords
            ),
            completeDataWorkbookSheet(
                name: dataWorkbookSheetName("Calendar activities", "Kalenderaktiviteter"),
                records: calendarMeetingRecords
            ),
            completeDataWorkbookSheet(
                name: dataWorkbookSheetName("Calendar application deadlines", "Kalenderansökningsdeadlines"),
                records: deadlineRecords
            ),
        ] + taskDataWorkbookSheets()
            + calendarAppearanceWorkbookSheets()
    }

    private func taskDataWorkbookSheets() -> [WorkbookExportSheet] {
        let projectTaskRecords = projects.flatMap { project in
            project.projectTasks
                .filter { !$0.isEmpty }
                .map {
                    ProjectTaskWorkbookRecord(
                        projectID: project.id,
                        projectName: project.displayName(for: language),
                        task: $0
                    )
                }
        }
        let publicationTaskRecords = publicationRecords.flatMap { publication in
            publication.publicationTasks
                .filter { !$0.isEmpty }
                .map {
                    PublicationTaskWorkbookRecord(
                        publicationID: publication.id,
                        publicationTitle: publication.title,
                        task: $0
                    )
                }
        }
        let teachingTaskRecords = teachingWorkspaceTasks
            .filter { !$0.isEmpty }
            .map {
                TeachingTaskWorkbookRecord(
                    source: language.text("Teaching", "Undervisning"),
                    task: $0
                )
            }

        return [
            completeDataWorkbookSheet(
                name: dataWorkbookSheetName("Project tasks", "Projektuppgifter"),
                records: projectTaskRecords
            ),
            completeDataWorkbookSheet(
                name: dataWorkbookSheetName("Publication tasks", "Publikationsuppgifter"),
                records: publicationTaskRecords
            ),
            completeDataWorkbookSheet(
                name: dataWorkbookSheetName("Teaching tasks", "Undervisningsuppgifter"),
                records: teachingTaskRecords
            ),
        ]
    }

    private func applicationWorkbookSheets(includeCompleteData: Bool = true) -> [WorkbookExportSheet] {
        let headers = [[
            language.text("Funder", "Anslagsgivare"),
            language.text("Grant", "Anslag"),
            language.text("Category", "Kategori"),
            language.text("Project", "Projekt"),
            language.text("Status", "Status"),
            language.text("Applied amount", "Sökt belopp"),
            language.text("Granted amount", "Beviljat belopp"),
            language.text("Applied on", "Ansökningsdatum"),
            language.text("Granted", "Beviljandedatum"),
            language.text("Declined", "Avslagsdatum"),
            language.text("Withdrawn", "Återdragningsdatum"),
            language.text("Decision expected", "Förväntat beslutsdatum"),
            language.text("Case number", "Ansökningsnummer"),
        ]]

        let listRows = applications.map { applicationWorkbookRow($0) }
        var sheets = [WorkbookExportSheet(name: language.text("Applications", "Ansökningar"), rows: headers + listRows)]
        if let selectedID = metadata.lastSelectedApplicationID,
           let selected = application(id: selectedID) {
            sheets.append(
                WorkbookExportSheet(
                    name: language.text("Selected application", "Vald ansökan"),
                    rows: headers + [applicationWorkbookRow(selected)]
                )
            )
        }
        if includeCompleteData {
            sheets.append(
                completeDataWorkbookSheet(
                    name: dataWorkbookSheetName("Applications", "Ansökningar"),
                    records: applications
                )
            )
        }
        return sheets
    }

    private func projectWorkbookSheets(includeCompleteData: Bool = true) -> [WorkbookExportSheet] {
        let headers = [[
            language.text("Project (SV)", "Projekt (SV)"),
            language.text("Project (EN)", "Projekt (EN)"),
            language.text("Status", "Status"),
            language.text("Collaborators", "Medarbetare"),
            language.text("Data collection", "Datainsamling"),
            language.text("Ethics case numbers", "Etikdiarienummer"),
            language.text("ClinicalTrials.gov", "ClinicalTrials.gov"),
            language.text("Task count", "Antal uppgifter"),
        ]]
        let rows = projects.map { project in
            [
                project.nameSv,
                project.nameEn,
                localizedProjectStatus(project.projectStatus),
                project.collaboratorNames.joined(separator: ", "),
                project.hasDataCollection ? language.text("Yes", "Ja") : language.text("No", "Nej"),
                ([project.ethicsBaseApplication] + project.ethicsAmendments)
                    .map(\.caseNumber)
                    .filter { !$0.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty }
                    .joined(separator: ", "),
                project.clinicalTrialRegistrations.map(\.trialID).joined(separator: ", "),
                "\(project.projectTasks.filter { !$0.isEmpty }.count)",
