        }
        return sheets
    }

    func projectWorkbookSheets(for project: ProjectRecord) -> [WorkbookExportSheet] {
        projectWorkbookSheets(for: project, language: language)
    }

    func projectWorkbookSheets(for project: ProjectRecord, language exportLanguage: AppLanguage) -> [WorkbookExportSheet] {
        let viewData = projectViewData(forProjectName: project.nameSv, language: exportLanguage)
        let relatedApplications = viewData?.relatedApplications
            ?? applications.filter { $0.projectID?.trimmedOrNil == project.id }
        let relatedPublications = viewData?.relatedPublications
            ?? publicationRecords.filter { $0.projectID?.trimmedOrNil == project.id }
        let conferenceContributions = cvConferenceContributions
            .filter { contributionBelongs($0, to: project) }
            .sorted(by: conferenceContributionSortOrder)
        let meetings = calendarMeetingRecords.filter {
            calendarMeetingProjectIDs(for: $0, store: self).contains(project.id)
        }
        let taskRecords = projectTaskWorkbookRecords(
            project: project,
            applications: relatedApplications,
            publications: relatedPublications,
            conferenceContributions: conferenceContributions,
            language: exportLanguage
        )
        let applicationRows = projectApplicationWorkbookRows(relatedApplications, language: exportLanguage)

        return [
            WorkbookExportSheet(
                name: exportLanguage.text("Summary", "Sammanfattning"),
                rows: projectWorkbookSummaryRows(
                    project: project,
                    applications: relatedApplications,
                    publications: relatedPublications,
                    conferenceContributions: conferenceContributions,
                    meetings: meetings,
                    taskRecords: taskRecords,
                    language: exportLanguage
                ),
                style: "projectSummary",
                currencyCells: [WorkbookExportCellReference(row: 14, column: 3)]
            ),
            WorkbookExportSheet(
                name: exportLanguage.text("Ethics & trials", "Etik och studieregistrering"),
                rows: projectEthicsAndTrialsWorkbookRows(project: project, language: exportLanguage),
                style: "projectTable",
                hyperlinks: projectEthicsAndTrialsWorkbookHyperlinks(project: project)
            ),
            WorkbookExportSheet(
                name: exportLanguage.text("Collaborators", "Medarbetare"),
                rows: projectCollaboratorWorkbookRows(
                    project.collaboratorNames,
                    publications: relatedPublications,
                    conferenceContributions: conferenceContributions,
                    language: exportLanguage
                ),
                style: "projectTable"
            ),
            WorkbookExportSheet(
                name: exportLanguage.text("Applications", "Ansökningar"),
                rows: applicationRows,
                style: "projectTable",
                currencyCells: relatedApplications.indices.flatMap { rowIndex in
                    [7, 8, 21, 22, 41].map { columnIndex in
                        WorkbookExportCellReference(row: rowIndex + 1, column: columnIndex)
                    }
                },
                hyperlinks: projectApplicationWorkbookHyperlinks(relatedApplications)
            ),
            WorkbookExportSheet(
                name: exportLanguage.text("Publications", "Publikationer"),
                rows: projectPublicationWorkbookRows(
                    publications: relatedPublications,
                    conferenceContributions: conferenceContributions,
                    language: exportLanguage
                ),
                style: "projectTable"
            ),
            WorkbookExportSheet(
                name: exportLanguage.text("Calendar events", "Kalenderhändelser"),
                rows: projectCalendarMeetingWorkbookRows(meetings, language: exportLanguage),
                style: "projectTable"
            ),
            WorkbookExportSheet(
                name: exportLanguage.text("Tasks", "Uppgifter"),
                rows: projectTaskWorkbookRows(taskRecords, language: exportLanguage),
                style: "projectTable"
            ),
        ]
    }

    /// Ethics approvals and ClinicalTrials.gov registrations for one project, as a
    /// single filterable table. Row 0 is the header, ethics rows come first, then
    /// trial registrations - `projectEthicsAndTrialsWorkbookHyperlinks` relies on
    /// that order to place the trial-ID links.
    private func projectEthicsAndTrialsWorkbookRows(
        project: ProjectRecord,
        language: AppLanguage
    ) -> [[String]] {
        let headers = [[
            language.text("Type", "Typ"),
            language.text("Status", "Status"),
            language.text("Applied / registered", "Ansökt/registrerad"),
            language.text("Approved / last updated", "Godkänd/senast uppdaterad"),
            language.text("Case number / trial ID", "Diarienummer/studie-ID"),
        ]]

        let rows = projectEthicsWorkbookRows(project: project, language: language)
            + projectClinicalTrialWorkbookRows(project: project, language: language)

        guard !rows.isEmpty else {
            return headers + [[
                language.text(
                    "No ethics approvals or trial registrations are recorded for this project.",
                    "Inga etiktillstånd eller studieregistreringar är registrerade för projektet."
                ),
                "",
                "",
                "",
                "",
            ]]
        }
        return headers + rows
    }

    private func projectEthicsWorkbookRows(project: ProjectRecord, language: AppLanguage) -> [[String]] {
        let applications = [project.ethicsBaseApplication] + project.ethicsAmendments
        return applications.indices.compactMap { index -> [String]? in
            let application = applications[index]
            guard !application.isEmpty else { return nil }
            return [
                index == 0
                    ? language.text("Ethics approval, base application", "Etiktillstånd, grundansökan")
                    : language.text("Ethics approval, amendment", "Etiktillstånd, tilläggsansökan"),
                application.ethicsStatusLabel(language: language),
                projectWorkbookDate(application.appliedOn, language: language),
                projectWorkbookDate(application.grantedOn, language: language),
                application.caseNumber.trimmingCharacters(in: .whitespacesAndNewlines),
            ]
        }
    }

    private func projectClinicalTrialWorkbookRows(project: ProjectRecord, language: AppLanguage) -> [[String]] {
        project.clinicalTrialRegistrations
            .filter { !$0.isEmpty }
            .map { registration in
                [
                    "ClinicalTrials.gov",
                    "",
                    projectWorkbookDate(registration.registeredOn, language: language),
                    projectWorkbookDate(registration.updatedOn, language: language),
                    registration.trialID.trimmingCharacters(in: .whitespacesAndNewlines),
                ]
            }
    }

    /// Links each trial-ID cell to the public ClinicalTrials.gov record, matching
    /// the link the project detail view offers.
    private func projectEthicsAndTrialsWorkbookHyperlinks(project: ProjectRecord) -> [WorkbookExportHyperlink] {
        let ethicsRowCount = ([project.ethicsBaseApplication] + project.ethicsAmendments)
            .filter { !$0.isEmpty }
            .count
        let registrations = project.clinicalTrialRegistrations.filter { !$0.isEmpty }
        let identifierColumn = 4
        return registrations.indices.compactMap { index -> WorkbookExportHyperlink? in
            let trialID = registrations[index].trialID.trimmingCharacters(in: .whitespacesAndNewlines)
            guard !trialID.isEmpty,
                  let url = URL(string: "https://clinicaltrials.gov/study/\(trialID)") else {
                return nil
            }
            return WorkbookExportHyperlink(
                row: 1 + ethicsRowCount + index,
                column: identifierColumn,
                target: url.absoluteString
            )
        }
    }

    private func projectWorkbookYesNo(_ value: Bool, language: AppLanguage) -> String {
        value ? language.text("Yes", "Ja") : language.text("No", "Nej")
    }

    private func projectWorkbookDate(_ value: String?, uncertain: Bool = false, language: AppLanguage) -> String {
        guard let value = value?.trimmedOrNil else { return "" }
        return uncertain ? value + language.text(" (uncertain)", " (osäkert)") : value
    }

    private func projectWorkbookList(_ values: [String]) -> String {
        values.compactMap(\.trimmedOrNil).joined(separator: "; ")
    }

    private func projectCollaboratorWorkbookRows(
        _ collaboratorNames: [String],
        publications: [PublicationRecord],
        conferenceContributions: [CVConferenceContribution],
        language: AppLanguage
    ) -> [[String]] {
        let headers = [[
            language.text("First name", "Förnamn"),
            language.text("Last name", "Efternamn"),
            language.text("Title", "Titel"),
            language.text("Position", "Befattning"),
            language.text("Degree", "Examen"),
            language.text("Career stage (Frascati 2015)", "Karriärsteg (Frascati 2015)"),
            language.text("PhD", "Doktorsexamen"),
            language.text("Gender", "Kön"),
            language.text("Primary organization", "Primär organisation"),
            language.text("Department", "Avdelning"),
            language.text("City", "Ort"),
            language.text("Country", "Land"),
            language.text("Email", "E-post"),
            "ORCID",
            language.text("Scopus ID", "Scopus-ID"),
            "ResearcherID",
            language.text("Website", "Webbplats"),
            language.text("Name variants", "Namnvarianter"),
            language.text("Other affiliations", "Övriga anknytningar"),
            language.text("Publication contributions", "Publikationsbidrag"),
        ]]

        let rows = collaboratorNames.compactMap(\.trimmedOrNil).map { presentedName -> [String] in
            guard let author = publicationAuthor(matchingPresentedName: presentedName) else {
                let parsed = parseName(presentedName)
                return [parsed.firstName, parsed.lastName] + Array(repeating: "", count: headers[0].count - 2)
            }
            let parsed = parseName(author.displayName.nonEmpty ?? presentedName)
            let firstName = author.firstName.nonEmpty ?? parsed.firstName
            let lastName = author.lastName.nonEmpty ?? parsed.lastName
            let primary = author.primaryAffiliation
            let otherAffiliations = author.affiliations.filter { $0.id != primary?.id }.map { affiliation in
                [
                    affiliation.localizedOrganization(language: language).nonEmpty,
                    affiliation.localizedDepartment(language: language).nonEmpty,
                    affiliation.city.nonEmpty,
                    localizedCountryName(affiliation.country, language: language).nonEmpty,
                    affiliation.email.nonEmpty,
                ].compactMap { $0 }.joined(separator: ", ")
            }
            let authorNameKeys = Set(author.presentedNameCandidates.map(normalizedPersonLookupName).filter { !$0.isEmpty })
            var seenContributionTitles = Set<String>()
            let contributions = (publications.compactMap { publication -> String? in
                guard publication.authorNames.contains(where: { authorNameKeys.contains(normalizedPersonLookupName($0)) }) else {
                    return nil
                }
                return publication.title.trimmedOrNil
            } + conferenceContributions.compactMap { contribution -> String? in
                guard contribution.contributorNames.contains(where: { authorNameKeys.contains(normalizedPersonLookupName($0)) }) else {
                    return nil
                }
                return contribution.localizedTitle(language: language).trimmedOrNil
            }).filter { seenContributionTitles.insert($0).inserted }
            return [
                firstName,
                lastName,
                language == .swedish ? (author.titleSv.nonEmpty ?? author.titleEn) : (author.titleEn.nonEmpty ?? author.titleSv),
                language == .swedish ? (author.positionSv.nonEmpty ?? author.positionEn) : (author.positionEn.nonEmpty ?? author.positionSv),
                language == .swedish ? (author.degreeSv.nonEmpty ?? author.degreeEn) : (author.degreeEn.nonEmpty ?? author.degreeSv),
                author.careerStage.rawValue,
                projectWorkbookYesNo(author.hasPhD, language: language),
                author.gender.displayName(language: language),
                primary?.localizedOrganization(language: language) ?? "",
                primary?.localizedDepartment(language: language) ?? "",
                primary?.city ?? "",
                primary.map { localizedCountryName($0.country, language: language) } ?? "",
                primary?.email ?? "",
                author.orcid,
                author.scopus,
                author.researcherID,
                author.institutionWebsite,
                projectWorkbookList(author.nameVariantRows.map(\.displayName)),
                projectWorkbookList(otherAffiliations),
                projectWorkbookList(contributions),
            ]
        }
        return headers + rows
    }

    private func projectWorkbookSEKAmount(_ value: Double?, application: GrantApplication) -> String {
        guard let value else { return "" }
        return String(Int(grantStatisticsAmountInSEK(for: application, amount: value).rounded()))
    }

    private func projectWorkbookLink(_ value: String?) -> (display: String, target: String)? {
        guard let raw = value?.trimmedOrNil else { return nil }
        // Same allowlist as every in-app open: an exported workbook must not
        // carry file://, smb:// or other non-web schemes as click targets.
        guard let normalized = normalizedWebLinkURL(raw),
              let safeURL = safeExternalURL(normalized) else { return nil }
        let target = safeURL.absoluteString
        let lowercased = target.lowercased()
        let display: String
        if lowercased.hasPrefix("https://www.") || lowercased.hasPrefix("http://www.") {
            display = target.replacingOccurrences(of: #"^https?://"#, with: "", options: [.regularExpression, .caseInsensitive])
        } else {
            display = raw
        }
        return (display, target)
    }

    private func projectApplicationWorkbookHyperlinks(_ applications: [GrantApplication]) -> [WorkbookExportHyperlink] {
        applications.enumerated().flatMap { rowIndex, application in
            [(33, application.primaryLink), (34, application.secondaryLink)].compactMap { pair in
                guard let link = projectWorkbookLink(pair.1) else { return nil }
                return WorkbookExportHyperlink(row: rowIndex + 1, column: pair.0, target: link.target)
            }
        }
    }

