            language.text("Decision", "Beslut"), language.text("Meeting location", "Mötesplats"),
            language.text("Publication details or comments", "Publikationsuppgifter eller kommentarer"), "CRediT",
            language.text("PDF file", "PDF-fil"),
        ]]
        let publicationRows = publications.map { publication in
            let reviewRegistration = [publication.reviewRegistrationRegistry.nonEmpty, publication.reviewRegistrationID.nonEmpty, publication.reviewRegistrationDate.nonEmpty]
                .compactMap { $0 }.joined(separator: ", ")
            let credit = publication.creditRoleAssignments.map { assignment in
