                return roles.isEmpty ? assignment.authorName : "\(assignment.authorName): \(roles)"
            }
            return [
                language.text("Publication", "Publikation"), publication.title,
                PublicationStatus.fromStored(publication.statusLabel).displayName(language: language), publication.statusDate ?? "",
                projectWorkbookList(publication.authorNames), publication.journal, publication.year, publication.publicationType,
                publication.workflowStatus?.displayName(language: language) ?? "", publication.currentSubmissionDate ?? "", "",
                publication.correspondingAuthorName ?? "", projectWorkbookYesNo(publication.sharedFirstAuthorship, language: language), projectWorkbookYesNo(publication.sharedLastAuthorship, language: language),
                projectWorkbookYesNo(publication.isPeerReviewed, language: language), publication.doi, publication.pmid, publication.volume, publication.issue,
                publication.pageRange, publication.articleNumber, publication.citations, publication.sjrCurrent, publication.jifCurrent,
                publication.jifQuartileCurrent, publication.norwegianCurrent, publication.position, publication.independence, publication.geography,
                publication.phdStage, publication.category, reviewRegistration, "", "", "", "", "", "",
                projectWorkbookList(credit), publication.finalPDFFilename ?? "",
            ]
        }
        let contributionRows = conferenceContributions.map { contribution in
            let location = [
                contribution.meetingCity.nonEmpty,
                localizedCountryName(contribution.meetingCountry, language: language).nonEmpty,
            ].compactMap { $0 }.joined(separator: ", ")
            let journalDetails = [
                contribution.journalName.nonEmpty,
                contribution.localizedMeeting(language: language).nonEmpty,
            ].compactMap { $0 }.joined(separator: " / ")
            return [
                language.text("Conference contribution", "Konferensbidrag"),
                contribution.localizedTitle(language: language),
                contribution.status.displayName(language: language),
                contribution.to.nonEmpty ?? contribution.from,
                projectWorkbookList(contribution.contributorNames),
                journalDetails,
                contribution.publicationYear,
                language.text("Conference contribution", "Konferensbidrag"),
                "",
                contribution.submissionAppliedOn,
                contribution.presentedBy,
                "",
                "",
                "",
                "",
                contribution.journalDOI,
                contribution.journalPMID,
                contribution.journalVolume,
                contribution.journalIssue,
                contribution.journalPages,
                contribution.journalArticleNumber,
                "",
                "",
                "",
                "",
                "",
                "",
                "",
                "",
                "",
                "",
                "",
                contribution.submissionClosesOn,
                contribution.submissionDecisionExpectedOn,
                contribution.submissionDecisionOn,
                contribution.submissionOutcome?.displayName(language: language) ?? "",
                location,
                contribution.localizedPublicationData(language: language),
                "",
                contribution.pdfFilename ?? "",
            ]
        }
        return headers + publicationRows + contributionRows
    }

    private func projectCalendarMeetingWorkbookRows(_ meetings: [CalendarMeetingRecord], language: AppLanguage) -> [[String]] {
        let headers = [[
            language.text("Date", "Datum"), language.text("Start", "Start"), language.text("End", "Slut"), language.text("Title", "Titel"),
            language.text("Activity type", "Aktivitetstyp"), language.text("Meeting format", "Mötesform"), language.text("Place", "Plats"),
            language.text("Country", "Land"), language.text("Participants", "Deltagare"), language.text("Details", "Detaljer"),
            language.text("Organizations", "Organisationer"), language.text("Applications", "Ansökningar"), language.text("Publications", "Publikationer"),
            language.text("Researchers", "Forskare"), language.text("Teaching assignments", "Undervisningsuppdrag"),
            language.text("Doctoral candidates", "Doktorander"), language.text("Media appearances", "Medieframträdanden"),
        ]]
        let rows = meetings.sorted {
            ($0.date, $0.startTime, $0.title) < ($1.date, $1.startTime, $1.title)
        }.map { meeting in
            let organizationNames = meeting.organizationIDs.compactMap { organization(id: $0) }.map {
                language == .swedish ? $0.nameSv : ($0.nameEn.nonEmpty ?? $0.nameSv)
            }
            let applicationNames = meeting.applicationIDs.compactMap { application(id: $0) }.map {
                localizedGrantName(for: $0, language: language)
            }
            let publicationNames = meeting.publicationIDs.compactMap { publication(id: $0)?.title }
            let researcherNames = [meeting.researcherID].compactMap { publicationAuthor(id: $0)?.displayName }
            let teachingNames = meeting.teachingAssignmentIDs.compactMap { id in
                teachingAssignments.first(where: { $0.id == id }).map {
                    [$0.activityName.nonEmpty, $0.studentName.nonEmpty, $0.programName.nonEmpty].compactMap { $0 }.joined(separator: " – ")
                }
            }
            let doctoralNames = meeting.doctoralCandidateIDs.compactMap { id in
                doctoralCandidates.first(where: { $0.id == id }).map { $0.candidateName.nonEmpty ?? $0.doctoralProjectName }
            }
            let mediaNames = meeting.mediaAppearanceIDs.compactMap { id in
                cvMediaAppearances.first(where: { $0.id == id })?.localizedTitle(language: language)
            }
            return [
                meeting.date, meeting.startTime, meeting.endTime, meeting.title, meeting.meetingType,
                CalendarMeetingMode(rawValue: meeting.meetingMode)?.localizedName(language: language) ?? meeting.meetingMode,
                meeting.place, localizedCountryName(meeting.country, language: language), projectWorkbookList(meeting.participantNames), meeting.detail,
                projectWorkbookList(organizationNames), projectWorkbookList(applicationNames), projectWorkbookList(publicationNames),
                projectWorkbookList(researcherNames), projectWorkbookList(teachingNames), projectWorkbookList(doctoralNames), projectWorkbookList(mediaNames),
            ]
        }
        return headers + rows
    }

    private func projectTaskWorkbookRows(_ records: [ProjectTaskWorkbookExportRecord], language: AppLanguage) -> [[String]] {
        let headers = [[
            language.text("Task", "Uppgift"), language.text("Status", "Status"), language.text("Deadline", "Tidsfrist"),
            language.text("Completed", "Slutförd"), language.text("Source", "Källa"), language.text("Linked to", "Kopplad till"),
            language.text("Participants", "Deltagare"), language.text("Reminder", "Påminnelse"), language.text("Notes", "Anteckningar"),
            language.text("Created", "Skapad"), language.text("Updated", "Uppdaterad"),
        ]]
        return headers + records.map { record in
            let comment = record.centralTask?.comment ?? record.projectTask?.comment ?? record.publicationTask?.comment ?? ""
            let completedOn = record.centralTask?.completedOn ?? record.projectTask?.completedOn ?? record.publicationTask?.completedOn
            let deadline = record.centralTask?.deadline ?? record.projectTask?.deadline ?? record.publicationTask?.deadline ?? ""
            let note = record.centralTask?.note ?? record.projectTask?.note ?? record.publicationTask?.note ?? ""
            let participants = record.centralTask?.participantNames ?? record.projectTask?.participantNames ?? record.publicationTask?.participantNames ?? []
            let createdOn = record.centralTask?.createdOn ?? record.projectTask?.createdOn ?? record.publicationTask?.createdOn ?? ""
            let updatedOn = record.centralTask?.updatedOn ?? record.projectTask?.updatedOn ?? record.publicationTask?.updatedOn ?? ""
            let reminder = record.centralTask.map { localizedProjectTaskReminder($0.reminder, language: language) }
                ?? record.projectTask.map { localizedProjectTaskReminder($0.reminder, language: language) }
                ?? ""
            return [
                comment,
                completedOn?.trimmedOrNil == nil ? language.text("Active", "Aktiv") : language.text("Completed", "Slutförd"),
                deadline, completedOn ?? "", record.source, record.context, projectWorkbookList(participants), reminder, note, createdOn, updatedOn,
            ]
        }
    }

    private func projectWorkbookSummaryRows(
        project: ProjectRecord,
        applications: [GrantApplication],
        publications: [PublicationRecord],
        conferenceContributions: [CVConferenceContribution],
        meetings: [CalendarMeetingRecord],
        taskRecords: [ProjectTaskWorkbookExportRecord],
        language: AppLanguage
    ) -> [[String]] {
        let projectName = project.displayName(for: language)
        let fullName = language == .swedish
            ? (project.fullNameSv.nonEmpty ?? project.fullNameEn)
            : (project.fullNameEn.nonEmpty ?? project.fullNameSv)
        let grantedApplications = applications.filter(\.isGranted)
        let grantedSEK = grantedApplications.reduce(0) { total, application in
            total + grantStatisticsAmountInSEK(for: application, amount: application.grantedAmountValue)
        }
        let publishedCount = publications.filter { PublicationStatus.fromStored($0.statusLabel) == .published }.count
        let activePublicationCount = publications.count - publishedCount
        let completedTaskCount = taskRecords.filter(projectTaskWorkbookRecordIsCompleted).count
        let activeTaskCount = taskRecords.count - completedTaskCount
        let meetingSummary = calendarMeetingHoursSummary(
            meetings: meetings,
            matchingMeeting: { _ in true }
        )
        let ethicsCaseCount = ([project.ethicsBaseApplication] + project.ethicsAmendments)
            .filter { $0.caseNumber.trimmedOrNil != nil }.count

        return [
            [projectName],
            [fullName],
            [],
            [language.text("Project", "Projekt")],
            [language.text("Status", "Status"), localizedProjectStatus(project.projectStatus, language: language), language.text("Data collection", "Datainsamling"), project.hasDataCollection ? language.text("Yes", "Ja") : language.text("No", "Nej")],
            [language.text("Short name (SV)", "Kortnamn (SV)"), project.nameSv, language.text("Short name (EN)", "Kortnamn (EN)"), project.nameEn],
            [language.text("Full name (SV)", "Fullständigt namn (SV)"), project.fullNameSv, language.text("Full name (EN)", "Fullständigt namn (EN)"), project.fullNameEn],
            [],
            [language.text("Overview", "Översikt")],
            [language.text("Collaborators", "Medarbetare"), "\(project.collaboratorNames.compactMap(\.trimmedOrNil).count)", language.text("Applications", "Ansökningar"), "\(applications.count)"],
            [language.text("Publications", "Publikationer"), "\(publications.count + conferenceContributions.count)", language.text("Calendar events", "Kalenderhändelser"), "\(meetings.count)"],
            [language.text("Active tasks", "Aktiva uppgifter"), "\(activeTaskCount)", language.text("Completed tasks", "Slutförda uppgifter"), "\(completedTaskCount)"],
            [],
            [language.text("Applications and funding", "Ansökningar och finansiering")],
            [language.text("Granted applications", "Beviljade ansökningar"), "\(grantedApplications.count)", language.text("Granted amount (SEK)", "Beviljat belopp (SEK)"), "\(Int(grantedSEK.rounded()))"],
            [ApplicationOutcome.awaitingDecision.heading(language), "\(applications.filter { $0.resultLabel == "Väntar svar" }.count)", language.text("Other applications", "Övriga ansökningar"), "\(applications.count - grantedApplications.count - applications.filter { $0.resultLabel == "Väntar svar" }.count)"],
            [],
            [language.text("Publications", "Publikationer")],
            [language.text("Published", "Publicerade"), "\(publishedCount)", language.text("In progress", "Pågående"), "\(activePublicationCount)"],
            [language.text("Conference contributions", "Konferensbidrag"), "\(conferenceContributions.count)"],
            [],
            [language.text("Activities", "Aktiviteter")],
            [language.text("Completed activities", "Genomförda aktiviteter"), "\(meetingSummary.completedMeetingCount)", language.text("Hours", "Timmar"), "\(Double(meetingSummary.completedMinutes) / 60)"],
            [language.text("Planned activities", "Planerade aktiviteter"), "\(meetingSummary.plannedMeetingCount)", language.text("Hours", "Timmar"), "\(Double(meetingSummary.plannedMinutes) / 60)"],
            [],
            [language.text("Compliance and data", "Regelefterlevnad och data")],
            [language.text("Ethics case numbers", "Etikdiarienummer"), "\(ethicsCaseCount)", "ClinicalTrials.gov", "\(project.clinicalTrialRegistrations.filter { !$0.isEmpty }.count)"],
            [language.text("Data collections", "Datainsamlingar"), "\(project.dataCollections.filter { !$0.isEmpty }.count)", language.text("Principal organizations", "Huvudansvariga organisationer"), "\(project.principalOrganizations.filter { !$0.isEmpty }.count)"],
        ]
    }

    func projectTaskWorkbookRecords(
        project: ProjectRecord,
        applications: [GrantApplication],
        publications: [PublicationRecord],
        conferenceContributions: [CVConferenceContribution],
        language: AppLanguage
    ) -> [ProjectTaskWorkbookExportRecord] {
        let applicationIDs = Set(applications.map(\.id))
        let publicationIDs = Set(publications.map(\.id))
        var seenIDs = Set<String>()
        var records: [ProjectTaskWorkbookExportRecord] = []

        func append(
            source: String,
            context: String,
            id: String,
            projectTask: ProjectTaskItem? = nil,
            publicationTask: PublicationTaskItem? = nil,
            centralTask: TaskItem? = nil
        ) {
            guard seenIDs.insert(id).inserted else { return }
            records.append(
                ProjectTaskWorkbookExportRecord(
                    source: source,
                    context: context,
                    projectTask: projectTask,
                    publicationTask: publicationTask,
                    centralTask: centralTask
                )
            )
        }

        for task in taskItems where task.links.contains(where: { link in
            (link.kind == .project && link.targetID == project.id)
                || (link.kind == .application && applicationIDs.contains(link.targetID))
                || (link.kind == .publication && publicationIDs.contains(link.targetID))
        }) {
            let contexts = documentTaskContexts(for: task, language: language)
            append(
                source: language.text("Central task", "Central uppgift"),
                context: projectWorkbookList(contexts),
                id: task.id,
                centralTask: task
            )
        }
        for task in project.projectTasks where !task.isEmpty {
            append(source: language.text("Project", "Projekt"), context: project.displayName(for: language), id: task.id, projectTask: task)
        }
        for publication in publications {
            for task in publication.publicationTasks where !task.isEmpty {
                append(source: language.text("Publication", "Publikation"), context: publication.title, id: task.id, publicationTask: task)
            }
        }
        for contribution in conferenceContributions {
            for task in contribution.tasks where !task.isEmpty {
                append(
                    source: language.text("Conference contribution", "Konferensbidrag"),
                    context: contribution.localizedTitle(language: language),
                    id: task.id,
                    publicationTask: task
                )
            }
        }
        for organization in organizations {
            for task in organization.projectTasks where !task.isEmpty {
                guard task.applicationID.map(applicationIDs.contains) == true
                    || task.publicationID.map(publicationIDs.contains) == true else { continue }
                let organizationName = language == .swedish ? organization.nameSv : (organization.nameEn.nonEmpty ?? organization.nameSv)
                append(source: language.text("Organization", "Organisation"), context: organizationName, id: task.id, projectTask: task)
            }
        }
        for task in teachingWorkspaceTasks where !task.isEmpty {
            guard task.projectID?.trimmedOrNil == project.id
                || task.applicationID.map(applicationIDs.contains) == true
                || task.publicationID.map(publicationIDs.contains) == true else { continue }
            append(source: language.text("Teaching", "Undervisning"), context: project.displayName(for: language), id: task.id, publicationTask: task)
        }

        return records.sorted {
            let lhsDeadline = $0.centralTask?.deadline ?? $0.projectTask?.deadline ?? $0.publicationTask?.deadline ?? ""
            let rhsDeadline = $1.centralTask?.deadline ?? $1.projectTask?.deadline ?? $1.publicationTask?.deadline ?? ""
            return lhsDeadline == rhsDeadline
                ? $0.source.localizedStandardCompare($1.source) == .orderedAscending
                : lhsDeadline.localizedStandardCompare(rhsDeadline) == .orderedAscending
        }
    }

    private func projectTaskWorkbookRecordIsCompleted(_ record: ProjectTaskWorkbookExportRecord) -> Bool {
        record.centralTask?.isCompleted
            ?? record.projectTask?.isCompleted
            ?? record.publicationTask?.isCompleted
            ?? false
    }

