    /// Doctoral supervision hours are summed from the candidate's supervision
    /// periods (hours per term times the terms supervised up to today or the
    /// period's end date). The cell is empty only when no hours per term are entered.
    func teachingMeritsExportDocument(referenceDate: Date = Date()) -> TeachingMeritsExportDocument {
        let standardSummaryRows: [(TeachingReportCategory, String)] = [
            (.groupTeaching, "Total undervisningstid schemalagd grupphandledning och/eller praktisk undervisning"),
            (.lecture, "Total undervisningstid schemalagda föreläsningar"),
            (.doctoralCourseTeaching, "Total undervisningstid på forskarutbildningskurs"),
            (.thesisSupervision, "Total undervisningstid handledning av examensarbeten"),
            (.doctoralPrincipalSupervision, "Total tid handledning av studerande på forskarnivå som huvudhandledare"),
            (.doctoralAssistantSupervision, "Total tid handledning av studerande på forskarnivå som bihandledare"),
            (.courseAdministration, "Total tid kursansvar, kursadministration och/eller kursutveckling"),
        ]

        let groups: [TeachingMeritsExportGroup] = [
            TeachingMeritsExportGroup(
                title: "Gruppundervisning",
                tables: [
                    teachingMeritsPeriodTable(
                        title: "Schemalagd grupphandledning och/eller praktisk undervisning på grund- och/eller avancerad nivå",
                        category: .groupTeaching,
                        headers: ["Termin", "Tid (timmar)", "Kurs / Titel, antal hp", "Lärosäte", "Undervisningsspråk", "Lärarinsats", "Undervisningsform"]
                    ),
                    teachingMeritsPeriodTable(
                        title: "Schemalagda föreläsningar inom utbildning på grund- och/ eller avancerad nivå (fysiskt och/eller online)",
                        category: .lecture,
                        headers: ["Termin", "Antal timmar", "Kurs/studentgrupp, antal hp", "Lärosäte", "Undervisningsspråk", "Lärarinsats", "Undervisningsformer/aktiviteter"]
                    ),
                    teachingMeritsPeriodTable(
                        title: "Schemalagd undervisning på forskarutbildningskurs",
                        category: .doctoralCourseTeaching,
                        headers: ["Termin", "Antal timmar", "Kurs/studentgrupp, antal hp", "Lärosäte", "Undervisningsspråk", "Lärarinsats", "Undervisningsformer/aktiviteter"]
                    ),
                ]
            ),
            TeachingMeritsExportGroup(
                title: "Handledning",
                tables: [
                    teachingMeritsAssignmentTable(
                        title: "Handledning av examensarbeten /fördjupningsarbete (60 timmar per avslutat arbete som huvudhandledare)",
                        category: .thesisSupervision,
                        headers: ["Termin", "Antal timmar", "Antal hp", "Lärosäte", "Program, Kursnamn", "Studentens namn"]
                    ),
                    teachingMeritsAssignmentTable(
                        title: workflowDefaultSettings.doctoralSupervisionTitle(principal: true),
                        category: .doctoralPrincipalSupervision,
                        headers: ["Examensår", "Antal timmar", "% av heltid", "I vilka steg har du medverkat från initial antagning till doktorsexamen?", "Lärosäte", "Doktorandens namn"],
                        referenceDate: referenceDate
                    ),
                    teachingMeritsAssignmentTable(
                        title: workflowDefaultSettings.doctoralSupervisionTitle(principal: false),
                        category: .doctoralAssistantSupervision,
                        headers: ["Examensår", "Antal timmar", "% av heltid", "I vilka steg har du medverkat från initial antagning till doktorsexamen?", "Lärosäte", "Doktorandens namn"],
                        referenceDate: referenceDate
                    )
                ]
            ),
            TeachingMeritsExportGroup(
                title: "Kursadministration",
                tables: [
                    teachingMeritsAssignmentTable(
                        title: "Kursansvar, kursadministration och/eller kursutveckling (Ange omfattning i % av heltid, och räkna ut timmar utifrån 100 % (heltid) = 1700 timmar/år)",
                        category: .courseAdministration,
                        headers: ["Termin", "Antal timmar", "% av heltid", "Beskriv innehåll i kursansvar/administration", "Lärosäte", "Kurs, antal studenter"]
                    )
                ]
            ),
        ]
        let summaryRows = standardSummaryRows.map { category, label in
            [label, formattedTeachingMeritsHours(totalHours(for: category, referenceDate: referenceDate))]
        }
        let summaryTotalValue = standardSummaryRows.reduce(0.0) { $0 + totalHours(for: $1.0, referenceDate: referenceDate) }

        return TeachingMeritsExportDocument(
            title: "Redovisning av pedagogiska meriter",
            groups: groups,
            summaryHeaders: ["Total undervisningstid", "Tid (timmar)"],
            summaryRows: summaryRows + [["Summa", formattedTeachingMeritsHours(summaryTotalValue)]],
            facultyName: workflowDefaultSettings.resolvedTeachingMeritsFacultyName
        )
    }

    private func localizedPublicationStatus(_ value: String) -> String {
        switch PublicationStatus.fromStored(value) {
        case .planned:
            return language.text("Planned", "Planerad")
        case .inPreparation:
            return language.text("In preparation", "Under arbete")
        case .submitted:
            return language.text("Submitted", "Inskickad")
        case .accepted:
            return language.text("Accepted", "Accepterad")
        case .rejected:
            return PublicationOutcomeWording.rejectedLabel(language)
        case .published:
            return language.text("Published", "Publicerad")
        }
    }

    private func preferredGrantAmountText(_ application: GrantApplication) -> String {
        application.grantedAmount?.nonEmpty
            ?? application.appliedAmount?.nonEmpty
            ?? application.approximateAmount?.nonEmpty
            ?? ""
    }

    func currentUserAuthor() -> PublicationAuthor? {
        if let authorID = metadata.currentUserAuthorID?.trimmedOrNil,
           let selected = publicationAuthor(id: authorID) {
            return selected
        }
        return publicationAuthors.count == 1 ? publicationAuthors.first : nil
    }

    func isCurrentUserAuthor(_ author: PublicationAuthor) -> Bool {
        currentUserAuthor()?.id == author.id
    }

    func isCurrentUserPresentedName(_ name: String) -> Bool {
        let key = normalizedPersonLookupName(name)
        guard !key.isEmpty else { return false }
        if let currentUser = currentUserAuthor() {
            return currentUserNameKeys(for: currentUser).contains(key)
                || publicationAuthor(matchingPresentedName: name)?.id == currentUser.id
        }
        return false
    }

    /// Produces the autocomplete list without repeating current-user lookup
    /// from inside the sort comparator. These names are rendered in several
    /// fields at once, so the former comparator performed the same author and
    /// normalization work hundreds of times during a single SwiftUI layout.
    func orderedCoauthorPresentedNames() -> [String] {
        let currentUser = currentUserAuthor()
        let currentUserID = currentUser?.id
        let currentUserKeys = currentUser.map(currentUserNameKeys(for:)) ?? []
        let candidates = coauthors.compactMap { coauthor -> (name: String, isCurrentUser: Bool)? in
            guard let name = coauthor.name.trimmedOrNil else { return nil }
            let key = normalizedPersonLookupName(name)
            let isCurrentUser = currentUserKeys.contains(key)
                || (currentUserID != nil && publicationAuthor(matchingPresentedName: name)?.id == currentUserID)
            return (name, isCurrentUser)
        }
        return candidates.sorted {
            if $0.isCurrentUser != $1.isCurrentUser { return $0.isCurrentUser }
            return $0.name.localizedStandardCompare($1.name) == .orderedAscending
        }
        .map(\.name)
    }

    func setCurrentUserAuthor(id: String) {
        guard publicationAuthor(id: id) != nil else { return }
        performUndoableMetadataChange(
            actionName: language.text("Change CV profile", "Byt CV-profil"),
            successMessage: language.text("Changed CV profile.", "Bytte CV-profil."),
            failureMessage: language.text("Could not change CV profile.", "Kunde inte byta CV-profil.")
        ) {
            var updated = self.editableMetadataSnapshot
            updated.currentUserAuthorID = id
            metadata = updated
        }
        rebuildApplicationRowSnapshots()
        rebuildPublicationAuthorRowSnapshots()
        markProjectViewCacheDirty()
    }

    private func currentUserNameKeys(for author: PublicationAuthor) -> Set<String> {
        Set(author.presentedNameCandidates.map(normalizedPersonLookupName).filter { !$0.isEmpty })
    }

    private func currentUserPresentedNameKeys() -> Set<String> {
        if let currentUser = currentUserAuthor() {
            return currentUserNameKeys(for: currentUser)
        }
        return []
    }

    private func currentUserPresentedNames() -> Set<String> {
        Set(currentUserAuthor()?.presentedNameCandidates.compactMap(\.trimmedOrNil) ?? [])
    }

    private func currentUserFormerSupervisorNames() -> Set<String> {
        Set(
            cvOtherPublications
                .filter(\.isDoctoralThesis)
                .flatMap { [$0.mainSupervisor, $0.coSupervisor] }
                .compactMap(\.trimmedOrNil)
        )
    }

    private func currentUserDoctoralCompletionDate() -> Date? {
        let educationDates = currentUserAuthor()?.educationEntries
            .filter { $0.level == .doctoral }
            .flatMap { [$0.to, $0.from] }
            .compactMap { $0.trimmedOrNil.flatMap(DateParsers.isoDay.date(from:)) } ?? []
        let thesisDates = cvOtherPublications
            .filter(\.isDoctoralThesis)
            .compactMap { $0.date.trimmedOrNil.flatMap(DateParsers.isoDay.date(from:)) }
        return (educationDates + thesisDates).max()
    }

    private func normalizedOrganizationScopeValue(_ value: String?) -> String? {
        value?
            .trimmingCharacters(in: .whitespacesAndNewlines)
            .nonEmpty?
            .folding(options: [.caseInsensitive, .diacriticInsensitive], locale: Locale(identifier: "sv_SE"))
    }

    private func currentUserOrganizationCountry() -> String? {
        normalizedOrganizationScopeValue(currentUserAuthor()?.primaryAffiliation?.country)
    }

    private func currentUserOrganizationCities() -> Set<String> {
        Set(
            currentUserAuthor()?
                .affiliations
                .compactMap { normalizedOrganizationScopeValue($0.city) } ?? []
        )
    }

    private func currentUserPublications(sortOrder: PublicationExportSortOrder = .newestFirst) -> [PublicationRecord] {
        let currentUserKeys = currentUserPresentedNameKeys()
        let currentUserID = currentUserAuthor()?.id
        return publicationRecords
            .filter { record in
                // F13d: the id link first, the written name as fallback.
                if let currentUserID, record.authorIDs.contains(currentUserID) {
                    return true
                }
                return record.authorNames.contains { currentUserKeys.contains(normalizedPersonLookupName($0)) }
            }
            .sorted {
                amaSortOrder($0, $1, oldestFirst: sortOrder == .oldestFirst)
            }
    }

    private func currentUserGrants() -> [GrantApplication] {
        let currentUserKeys = currentUserPresentedNameKeys()
        let currentUserID = currentUserAuthor()?.id
        return applications
            .filter { application in
                // F13b: the id link first, the written name as fallback.
                if let currentUserID, application.coApplicantAuthorIDs.contains(currentUserID) {
                    return true
                }
                return application.coApplicants.contains { currentUserKeys.contains(normalizedPersonLookupName($0)) }
            }
            .sorted {
                let leftDate = $0.grantedOn ?? $0.appliedOn ?? ""
                let rightDate = $1.grantedOn ?? $1.appliedOn ?? ""
                let left = DateParsers.isoDay.date(from: leftDate) ?? .distantPast
                let right = DateParsers.isoDay.date(from: rightDate) ?? .distantPast
                if left != right {
                    return left > right
                }
                return $0.grantName.localizedStandardCompare($1.grantName) == .orderedAscending
            }
    }

    func isCurrentUserFirstApplicant(_ application: GrantApplication) -> Bool {
        guard let firstApplicant = application.coApplicants.first else { return false }
        // F13b: the main applicant by id first, the written name as fallback.
        if let currentUserID = currentUserAuthor()?.id,
           let firstID = firstPersonAuthorID(ids: application.coApplicantAuthorIDs, names: application.coApplicants) {
            return firstID == currentUserID
        }
        return currentUserPresentedNameKeys().contains(normalizedPersonLookupName(firstApplicant))
    }

    func isEffectivelyFullySpent(_ application: GrantApplication, today: Date = Date()) -> Bool {
        application.isFullySpent || collaboratorGrantDispositionHasPassed(application, today: today)
    }

    func effectiveRemainingGrantedAmountValue(for application: GrantApplication, today: Date = Date()) -> Double? {
        guard application.grantedAmountValue != nil else { return nil }
        return isEffectivelyFullySpent(application, today: today) ? 0 : application.remainingGrantedAmountValue
    }

    private func collaboratorGrantDispositionHasPassed(_ application: GrantApplication, today: Date) -> Bool {
        guard application.isGranted,
              !isCurrentUserFirstApplicant(application),
              let lastDispositionDate = application.lastDispositionDate else {
            return false
        }
        let calendar = Calendar.current
        return calendar.startOfDay(for: lastDispositionDate) < calendar.startOfDay(for: today)
    }

    func isCurrentUserProjectLeader(_ project: ProjectRecord) -> Bool {
        guard let leaderName = project.collaboratorNames.first?.trimmedOrNil else { return false }
        // F13b: the project leader by id first, the written name as fallback.
        if let currentUserID = currentUserAuthor()?.id,
           let leaderID = firstPersonAuthorID(ids: project.collaboratorAuthorIDs, names: project.collaboratorNames) {
            return leaderID == currentUserID
        }
        return isCurrentUserPresentedName(leaderName)
    }

    func includesCollaboratorGrantsInProjectTimelineByDefault(for project: ProjectRecord) -> Bool {
        !isCurrentUserProjectLeader(project)
    }

    private func currentUserGrantedGrants(includeCollaboratorGrants: Bool = false) -> [GrantApplication] {
        currentUserGrants()
            .filter(\.isGranted)
            .filter { includeCollaboratorGrants || isCurrentUserFirstApplicant($0) }
    }

    private func cvPersonalResumeExportParagraphs(language: AppLanguage) -> [CVExportRichTextParagraph] {
        cvPersonalResume
            .localizedContent(language: language)
            .paragraphs
            .filter { !$0.isEmpty }
            .map { paragraph in
                CVExportRichTextParagraph(
                    runs: paragraph.runs.map {
                        CVExportRichTextRun(
                            text: $0.text,
                            bold: $0.bold,
                            italic: $0.italic,
                            underline: $0.underline
                        )
                    }
                )
            }
    }

    func vetenskapsradetOutputCandidates() -> [CVVROutputCandidate] {
        vrOutputCandidates(language: language)
    }

    private func vrOutputCandidates(language: AppLanguage) -> [CVVROutputCandidate] {
        let publicationCandidates = currentUserPublications()
            .filter(vrIsEligiblePublication)
            .map { vrPublicationCandidate(for: $0, language: language) }
        let conferenceCandidates = cvConferenceContributions
            .filter(vrIsEligibleConferenceContribution)
            .map { vrConferenceCandidate(for: $0, language: language) }
        let otherPublicationCandidates = cvOtherPublications
            .filter { !$0.isEmpty }
            .map { vrOtherPublicationCandidate(for: $0, language: language) }

        return (publicationCandidates + conferenceCandidates + otherPublicationCandidates)
            .sorted(by: vrCandidateSortOrder)
    }

    private func vrCandidateSortOrder(_ lhs: CVVROutputCandidate, _ rhs: CVVROutputCandidate) -> Bool {
        if lhs.sortDate != rhs.sortDate {
            return lhs.sortDate > rhs.sortDate
        }
        if lhs.category.sortOrder != rhs.category.sortOrder {
            return lhs.category.sortOrder < rhs.category.sortOrder
        }
        return lhs.title.localizedStandardCompare(rhs.title) == .orderedAscending
    }

    private func cvVRLinkedTextItem(for candidate: CVVROutputCandidate) -> CVLinkedTextItem {
        CVLinkedTextItem(
            text: candidate.citation,
            sourceID: cvVRSourceLinkID(for: candidate)
        )
    }

    private func cvVRSourceLinkID(for candidate: CVVROutputCandidate) -> String {
        switch candidate.sourceKind {
        case .publication:
            return "publication-\(candidate.sourceID)"
        case .conferenceContribution:
            return "conference-\(candidate.sourceID)"
        case .otherPublication:
            return "other-publication-\(candidate.sourceID)"
        }
    }

    private func vrIsEligiblePublication(_ publication: PublicationRecord) -> Bool {
        switch PublicationStatus.fromStored(publication.statusLabel) {
        case .accepted, .published:
            return true
        default:
            return false
        }
    }

    private func vrPublicationCandidate(for publication: PublicationRecord, language: AppLanguage) -> CVVROutputCandidate {
        let status = PublicationStatus.fromStored(publication.statusLabel)
        var citationOptions = PublicationExportOptions()
        citationOptions.boldOwnName = true
        let journal = linkedJournal(of: publication)
        let impactFactorMetric = journal?.preferredMetric(
            for: [.clarivateScieJIF, .clarivateEsciJIF],
            publicationYear: publication.yearValue
        )
        let norwegianMetric = journal?.preferredMetric(
            for: [.norwegianList],
            publicationYear: publication.yearValue
        )
        let derivedPosition = PublicationDerivation.position(
            for: publication.authorNames,
            currentUserNames: currentUserPresentedNames(),
            sharedFirstAuthorship: publication.sharedFirstAuthorship,
            sharedLastAuthorship: publication.sharedLastAuthorship
        )
        let position = publication.position.nonEmpty ?? derivedPosition
        let roles = publication.creditRoles(forAuthorName: currentUserAuthor()?.name ?? "")
            .sorted { $0.sortIndex < $1.sortIndex }
            .map(\.rawValue)
        let contributionText: String? = {
            let roleText = roles.prefix(3).joined(separator: ", ").nonEmpty
            guard position.nonEmpty != nil || roleText != nil else { return nil }
            let value = [position.nonEmpty, roleText].compactMap { $0 }.joined(separator: "; ")
            return language == .swedish ? "Bidrag: \(value)." : "Contribution: \(value)."
        }()
        let relevanceText = publication.projectName?.trimmedOrNil.map {
            language == .swedish ? "Relevans: kopplad till projektet \($0)." : "Relevance: linked to the project \($0)."
        }

        return CVVROutputCandidate(
            id: "publication:\(publication.id)",
            sourceKind: .publication,
            sourceID: publication.id,
            category: vrCategory(for: publication),
            authorsText: publication.authorNames.joined(separator: ", "),
            title: publication.title.nonEmpty ?? publication.journal.nonEmpty ?? publication.id,
            journalText: journal?.name.nonEmpty
                ?? publicationJournalShortName(journal, style: citationOptions.journalShortNameStyle)
                ?? publication.journal,
            citation: vrPublicationCitation(for: publication, options: citationOptions),
            noteSuggestion: [contributionText, relevanceText].compactMap { $0 }.joined(separator: " "),
            yearText: vrPublicationYearText(for: publication),
            sortDate: vrPublicationSortDate(for: publication, status: status),
            latestImpactFactorValue: impactFactorMetric?.numericValue ?? journal?.latestImpactFactorValue ?? 0,
            latestNorwegianLevelValue: norwegianMetric.map { PublicationJournal.norwegianRankValue(for: $0.value) }
                ?? journal?.latestNorwegianLevelValue
                ?? 0,
            impactFactorText: impactFactorMetric?.value ?? journal?.latestImpactFactor ?? "",
            norwegianLevelText: norwegianMetric?.value ?? journal?.latestNorwegianLevel ?? ""
        )
    }

    private func vrPublicationCitation(
        for publication: PublicationRecord,
        options: PublicationExportOptions
    ) -> String {
        let item = amaCitationItem(for: publication, options: options)
        let italicJournal = item.journal.nonEmpty.map(vrItalicText)
        let parts = [item.authors.nonEmpty, item.title.nonEmpty, italicJournal, item.tail.nonEmpty]
            .compactMap { $0 }
        let body = parts.joined(separator: ". ")
        if body.isEmpty {
            return item.plain
        }
        return body + "." + (item.note.isEmpty ? "" : " \(item.note)")
    }

    private func vrCategory(for publication: PublicationRecord) -> CVVROutputCategory {
        if publication.isPeerReviewed {
            switch publicationTypeBucket(for: publication) {
            case "original":
                return .peerReviewedOriginalArticle
            case "review":
                return .peerReviewedResearchReviewArticle
            default:
                return .peerReviewedOther
            }
        }

        let normalizedType = publication.publicationType
            .folding(options: [.caseInsensitive, .diacriticInsensitive], locale: Locale(identifier: "sv_SE"))
            .lowercased()
        if normalizedType.contains("preprint") {
            return .nonPeerReviewedPreprint
        }
        return .nonPeerReviewedPublication
    }

    private func vrPublicationYearText(for publication: PublicationRecord) -> String {
        if let year = publication.year.nonEmpty {
            return year
        }
        if let statusDate = publication.statusDate,
           let year = yearComponent(from: statusDate) {
            return String(year)
        }
        return ""
    }

    private func vrPublicationSortDate(for publication: PublicationRecord, status: PublicationStatus) -> String {
        if let date = publication.statusDate?.trimmedOrNil {
            if DateParsers.isoDay.date(from: date) != nil {
                return date
            }
            if let year = yearComponent(from: date) {
                return String(format: "%04d-12-31", year)
            }
        }
        if let year = Int(publication.year) {
            let suffix = status == .accepted ? "06-30" : "12-31"
            return String(format: "%04d-%@", year, suffix)
        }
        return "0000-01-01"
    }

    private func vrIsEligibleConferenceContribution(_ contribution: CVConferenceContribution) -> Bool {
        isPublishedConferenceContribution(contribution)
            || contribution.submissionOutcome == .granted
            || contribution.status == .presented
    }

    private func vrConferenceCandidate(for contribution: CVConferenceContribution, language: AppLanguage) -> CVVROutputCandidate {
        let contributionText = contribution.localizedComments(language: language).nonEmpty
        let relevanceText = contribution.localizedProjectName(language: language).nonEmpty.map {
            language == .swedish ? "Relevans: kopplad till projektet \($0)." : "Relevance: linked to the project \($0)."
        }
        return CVVROutputCandidate(
            id: "conference:\(contribution.id)",
            sourceKind: .conferenceContribution,
            sourceID: contribution.id,
            category: .peerReviewedConferenceContribution,
            authorsText: contribution.contributorNames.joined(separator: ", "),
            title: contribution.localizedTitle(language: language).nonEmpty ?? contribution.displayTitle,
            journalText: contribution.journalName,
            citation: vrConferenceCitation(for: contribution, language: language),
            noteSuggestion: [contributionText, relevanceText].compactMap { $0 }.joined(separator: " "),
            yearText: vrConferenceYearText(for: contribution),
            sortDate: vrConferenceSortDate(for: contribution)
        )
    }

    private func vrConferenceCitation(for contribution: CVConferenceContribution, language: AppLanguage) -> String {
        let publicationData = vrConferencePublicationData(for: contribution, language: language)
        let details = [
            contribution.localizedName(language: language).nonEmpty,
            contribution.localizedTitle(language: language).nonEmpty,
            contribution.localizedMeeting(language: language).nonEmpty,
            publicationData.nonEmpty
        ]
        .compactMap { $0 }
        .joined(separator: ". ")
        return details.isEmpty ? (contribution.displayTitle) : details + "."
    }

    private func vrConferencePublicationData(for contribution: CVConferenceContribution, language: AppLanguage) -> String {
        let journalName = contribution.journalName.nonEmpty.map(vrItalicText)
        let publicationYear = contribution.publicationYear.nonEmpty
        let citationTail: String? = {
            var bits: [String] = []
            var leading = ""
            if let year = publicationYear {
                leading = year
            }
            if let volume = contribution.journalVolume.nonEmpty {
                var volumePart = volume
                if let issue = contribution.journalIssue.nonEmpty {
                    volumePart += "(\(issue))"
                }
                if leading.isEmpty {
                    bits.append(volumePart)
                } else {
                    bits.append("\(leading);\(volumePart)")
                    leading = ""
                }
            } else if let issue = contribution.journalIssue.nonEmpty {
                let issueText = language == .swedish ? "nr \(issue)" : "no. \(issue)"
                if leading.isEmpty {
                    bits.append(issueText)
                } else {
                    bits.append("\(leading); \(issueText)")
                    leading = ""
                }
            }

            if let pages = contribution.journalPages.nonEmpty {
                bits.append(pages)
            } else if let articleNumber = contribution.journalArticleNumber.nonEmpty {
                bits.append(articleNumber)
            }

            if !leading.isEmpty {
                bits.insert(leading, at: 0)
            }

            var tail = bits.joined(separator: ":")
            if let doi = contribution.journalDOI.nonEmpty {
                tail += tail.isEmpty ? "doi:\(doi)" : ". doi:\(doi)"
            }
            if let pmid = contribution.journalPMID.nonEmpty {
                tail += tail.isEmpty ? "PMID:\(pmid)" : ". PMID:\(pmid)"
            }
            return tail.nonEmpty
        }()

        let structured = [journalName, citationTail]
            .compactMap { $0 }
            .joined(separator: journalName != nil && citationTail != nil ? ". " : "")

        let freeText = contribution.localizedPublicationData(language: language).nonEmpty
        return [structured.nonEmpty, freeText]
            .compactMap { $0 }
            .joined(separator: structured.nonEmpty != nil && freeText != nil ? ". " : "")
    }

    private func vrConferenceYearText(for contribution: CVConferenceContribution) -> String {
        if let year = contribution.publicationYear.nonEmpty {
            return year
        }
        if let year = yearComponent(from: contribution.to.nonEmpty ?? contribution.from.nonEmpty ?? "") {
            return String(year)
        }
        return ""
    }

    private func vrConferenceSortDate(for contribution: CVConferenceContribution) -> String {
        if let to = contribution.to.nonEmpty, DateParsers.isoDay.date(from: to) != nil {
            return to
        }
        if let from = contribution.from.nonEmpty, DateParsers.isoDay.date(from: from) != nil {
            return from
        }
        if let year = Int(contribution.publicationYear) {
            return String(format: "%04d-12-31", year)
        }
        return "0000-01-01"
    }

    private func vrOtherPublicationCandidate(for entry: CVOtherPublicationEntry, language: AppLanguage) -> CVVROutputCandidate {
        let category = vrCategory(for: entry)
        return CVVROutputCandidate(
            id: "otherPublication:\(entry.id)",
            sourceKind: .otherPublication,
            sourceID: entry.id,
            category: category,
            authorsText: entry.authors,
            title: entry.localizedTitle(language: language).nonEmpty ?? entry.displayTitle,
            journalText: entry.localizedOutlet(language: language),
            citation: vrOtherPublicationCitation(for: entry, language: language),
            noteSuggestion: "",
            yearText: yearString(from: entry.date).nonEmpty ?? entry.date.nonEmpty ?? "",
            sortDate: vrOtherPublicationSortDate(for: entry),
        )
    }

    private func vrOtherPublicationCitation(for entry: CVOtherPublicationEntry, language: AppLanguage) -> String {
        let outlet = entry.localizedOutlet(language: language).nonEmpty.map(vrItalicText)
        let publicationData = entry.localizedPublicationData(language: language).nonEmpty
        let details = [
            entry.authors.nonEmpty,
            entry.localizedTitle(language: language).nonEmpty,
            [outlet, publicationData].compactMap { $0 }.joined(separator: outlet != nil && publicationData != nil ? ". " : "")
                .nonEmpty
        ]
        .compactMap { $0 }
        .joined(separator: ". ")
        return details.isEmpty ? entry.displayTitle : details + "."
    }

    private func vrItalicText(_ text: String) -> String {
        "[[ITALIC]]\(text)[[/ITALIC]]"
    }

    private func vrOtherPublicationSortDate(for entry: CVOtherPublicationEntry) -> String {
        if let date = entry.date.nonEmpty {
            if DateParsers.isoDay.date(from: date) != nil {
                return date
            }
            if let year = yearComponent(from: date) {
                return String(format: "%04d-12-31", year)
            }
        }
        return "0000-01-01"
    }

    private func vrCategory(for entry: CVOtherPublicationEntry) -> CVVROutputCategory {
        let normalized = ([entry.categorySv, entry.categoryEn].joined(separator: " "))
            .folding(options: [.diacriticInsensitive, .caseInsensitive], locale: Locale(identifier: "sv_SE"))
            .lowercased()

        let isExplicitlyNonPeerReviewed = [
            "ej peer", "non peer", "non-peer", "icke sakkunnig", "icke-sakkunnig", "popular science", "popular", "popul"
        ].contains(where: normalized.contains)
        let isExplicitlyPeerReviewed = [
            "peer review", "peer-reviewed", "peer reviewed", "sakkunnig", "referee"
        ].contains(where: normalized.contains)

        let typeCategory: CVVROutputCategory = {
            if normalized.contains("preprint") {
                return .nonPeerReviewedPreprint
            }
            if normalized.contains("artistic") || normalized.contains("konst") {
                return isExplicitlyPeerReviewed ? .peerReviewedArtisticWork : .nonPeerReviewedArtisticWork
            }
            if normalized.contains("edited volume") || normalized.contains("samlingsverk") {
                return isExplicitlyPeerReviewed ? .peerReviewedEditedVolume : .nonPeerReviewedOther
            }
            if normalized.contains("review article") || normalized.contains("research review") || normalized.contains("forskningsoversikt") || normalized.contains("forskningsöversikt") {
                return isExplicitlyPeerReviewed ? .peerReviewedResearchReviewArticle : .nonPeerReviewedPublication
            }
            if normalized.contains("book chapter") || normalized.contains("bokkapitel") || normalized.contains("chapter") || normalized.contains("book") || normalized.contains("bok") {
                return isExplicitlyPeerReviewed ? .peerReviewedBookOrBookChapter : .nonPeerReviewedPublication
            }
            if normalized.contains("conference") || normalized.contains("konferens") {
                return isExplicitlyPeerReviewed ? .peerReviewedConferenceContribution : .nonPeerReviewedOther
            }
            if isExplicitlyPeerReviewed {
                return .peerReviewedOther
            }
            if entry.isDoctoralThesis {
                return .nonPeerReviewedOther
            }
            return .nonPeerReviewedOther
        }()

        if isExplicitlyNonPeerReviewed {
            switch typeCategory {
            case .peerReviewedArtisticWork:
                return .nonPeerReviewedArtisticWork
            case .peerReviewedBookOrBookChapter:
                return .nonPeerReviewedPublication
            case .peerReviewedConferenceContribution:
                return .nonPeerReviewedOther
            case .peerReviewedEditedVolume:
                return .nonPeerReviewedOther
            case .peerReviewedResearchReviewArticle:
                return .nonPeerReviewedPublication
            case .peerReviewedOriginalArticle:
                return .nonPeerReviewedPublication
            case .peerReviewedOther:
                return .nonPeerReviewedOther
            case .nonPeerReviewedArtisticWork,
                    .nonPeerReviewedPublication,
                    .nonPeerReviewedPreprint,
                    .nonPeerReviewedOther:
                return typeCategory
            }
        }

        return typeCategory
    }

    private func vrSelectedOutputs(
        from selectedOutputs: [CVVRSelectedOutput]
    ) -> [CVVRSelectedOutput] {
        selectedOutputs
            .map {
                CVVRSelectedOutput(
                    candidate: $0.candidate,
                    note: $0.note.trimmingCharacters(in: .whitespacesAndNewlines)
                )
            }
            .sorted { vrCandidateSortOrder($0.candidate, $1.candidate) }
    }

    func cvVetenskapsradetExportDocument(
        language exportLanguage: AppLanguage,
        selectedOutputs: [CVVRSelectedOutput]
    ) -> CVExportDocument {
        let selected = vrSelectedOutputs(from: selectedOutputs)
        let allOutputs = vrOutputCandidates(language: exportLanguage)
        let periodOutputs = allOutputs.filter { candidate in
            guard let year = Int(candidate.yearText) else { return false }
            return (2018...2026).contains(year)
        }

        let groupedPeerReviewed = Dictionary(grouping: periodOutputs.filter { $0.category.isPeerReviewed }, by: \.category)
        let groupedNonPeerReviewed = Dictionary(grouping: periodOutputs.filter { !$0.category.isPeerReviewed }, by: \.category)

        let peerReviewedSubsections = CVVROutputCategory.allCases
            .filter(\.isPeerReviewed)
            .sorted { $0.sortOrder < $1.sortOrder }
            .compactMap { category -> CVExportSubsection? in
                let linkedItems = groupedPeerReviewed[category, default: []]
                    .sorted { vrCandidateSortOrder($0, $1) }
                    .map(cvVRLinkedTextItem)
                guard !linkedItems.isEmpty else { return nil }
                return CVExportSubsection(
                    title: category.vetenskapsradetHeading,
                    items: cvLinkedItemTexts(linkedItems),
                    itemSourceIDs: cvLinkedItemSourceIDs(linkedItems)
                )
            }

        let nonPeerReviewedSubsections = CVVROutputCategory.allCases
            .filter { !$0.isPeerReviewed }
            .sorted { $0.sortOrder < $1.sortOrder }
            .compactMap { category -> CVExportSubsection? in
                let linkedItems = groupedNonPeerReviewed[category, default: []]
                    .sorted { vrCandidateSortOrder($0, $1) }
                    .map(cvVRLinkedTextItem)
                guard !linkedItems.isEmpty else { return nil }
                return CVExportSubsection(
                    title: category.vetenskapsradetHeading,
                    items: cvLinkedItemTexts(linkedItems),
                    itemSourceIDs: cvLinkedItemSourceIDs(linkedItems)
                )
            }

        let totalPeerReviewedOriginals = allOutputs.filter { $0.category == .peerReviewedOriginalArticle }.count
        let totalPeerReviewedReviews = allOutputs.filter { $0.category == .peerReviewedResearchReviewArticle }.count
        let totalOther = allOutputs.count - totalPeerReviewedOriginals - totalPeerReviewedReviews
        let periodPeerReviewedOriginals = periodOutputs.filter { $0.category == .peerReviewedOriginalArticle }.count
        let periodPeerReviewedReviews = periodOutputs.filter { $0.category == .peerReviewedResearchReviewArticle }.count
        let periodOther = periodOutputs.count - periodPeerReviewedOriginals - periodPeerReviewedReviews

        let sections: [CVExportSection] = [
            CVExportSection(
                title: "1. Urval av forskningsoutputs (Selection of research outputs)",
                subsections: [
                    CVExportSubsection(
                        title: "",
                        vrItems: selected.enumerated().map { index, item in
                            CVExportVRItem(
                                citation: "\(index + 1).\t\(item.candidate.citation)",
                                note: item.note,
                                sourceID: cvVRSourceLinkID(for: item.candidate)
                            )
                        }
                    )
                ]
            ),
            CVExportSection(
                title: "2. Relevanta sakkunnigbedömda forskningsoutputs från 2018-2026 (Relevant peer-reviewed research outputs from 2018-2026)",
                subsections: peerReviewedSubsections
            ),
            CVExportSection(
                title: "3. Relevanta icke-sakkunnigbedömda forskningsoutputs från 2018-2026 (Relevant non peer-reviewed research outputs from 2018-2026)",
                subsections: nonPeerReviewedSubsections
            ),
            CVExportSection(
                title: "4. Antal publikationer (Number of publications)",
                paragraphs: [
                    "Totalt antal sakkunnigbedömda originalartiklar (Total number of peer-reviewed original articles): \(totalPeerReviewedOriginals)",
                    "Totalt antal sakkunnigbedömda forskningsöversiktsartiklar (Total number of peer-reviewed research review articles): \(totalPeerReviewedReviews)",
                    "Totalt antal andra publikationer inklusive patent (Total number of other publications including patents): \(max(0, totalOther))",
                    "Antal sakkunnigbedömda originalartiklar från 2018-2026 (Number of peer-reviewed original articles): \(periodPeerReviewedOriginals)",
                    "Antal sakkunnigbedömda forskningsöversiktsartiklar från 2018-2026 (Number of peer-reviewed research review articles): \(periodPeerReviewedReviews)",
                    "Antal andra publikationer inklusive patent från 2018-2026 (Number of other publications including patents): \(max(0, periodOther))"
                ]
            ),
        ]
        .filter { !$0.subsections.isEmpty || !$0.paragraphs.isEmpty }

        let name = currentUserAuthor()?.name.nonEmpty ?? cvText(exportLanguage, english: "Curriculum vitae", swedish: "CV")

        return CVExportDocument(
            style: CVDocumentExportStyle.vetenskapsradet.rawValue,
            exportLanguage: exportLanguage.rawValue,
            highlightName: currentUserAuthor()?.name ?? "",
            title: "Vetenskapsrådet",
            subtitle: name,
            summaryLines: [],
            summaryRichParagraphs: [],
            sections: sections
        )
    }

    func cvExportDocument(
        style: CVDocumentExportStyle,
        exportLanguage: AppLanguage,
        includedSections: Set<CVExportSectionKey> = CVExportSectionKey.defaultIncludedSections,
        publicationOptions: PublicationExportOptions = PublicationExportOptions(),
        includeCollaboratorGrants: Bool = false,
        underlineDoctoralMainSupervisor: Bool = false,
        underlineDoctoralCoSupervisor: Bool = false
    ) -> CVExportDocument {
        switch style {
        case .own:
            return cvOwnExportDocument(
                language: exportLanguage,
                includedSections: includedSections,
                publicationOptions: publicationOptions,
                includeCollaboratorGrants: includeCollaboratorGrants,
                underlineDoctoralMainSupervisor: underlineDoctoralMainSupervisor,
                underlineDoctoralCoSupervisor: underlineDoctoralCoSupervisor
            )
        case .liu:
            return cvLiUExportDocument(
                language: exportLanguage,
                includedSections: includedSections,
                publicationOptions: publicationOptions,
                includeCollaboratorGrants: includeCollaboratorGrants,
                underlineDoctoralMainSupervisor: underlineDoctoralMainSupervisor,
                underlineDoctoralCoSupervisor: underlineDoctoralCoSupervisor
            )
        case .vetenskapsradet:
            return cvVetenskapsradetExportDocument(
                language: exportLanguage,
                selectedOutputs: []
            )
        }
    }

    private func cvOwnExportDocument(
        language exportLanguage: AppLanguage,
        includedSections: Set<CVExportSectionKey>,
        publicationOptions: PublicationExportOptions,
        includeCollaboratorGrants: Bool,
        underlineDoctoralMainSupervisor: Bool,
        underlineDoctoralCoSupervisor: Bool
    ) -> CVExportDocument {
        var effectivePublicationOptions = publicationExportOptions(
            from: publicationOptions,
            underlineDoctoralMainSupervisor: underlineDoctoralMainSupervisor,
            underlineDoctoralCoSupervisor: underlineDoctoralCoSupervisor
        )
        effectivePublicationOptions.exportLanguage = exportLanguage
        let currentAuthor = currentUserAuthor()
        let userPublications = currentUserPublications(sortOrder: effectivePublicationOptions.sortOrder)
        let name = currentAuthor?.name.nonEmpty ?? cvText(exportLanguage, english: "Curriculum vitae", swedish: "CV")
        let contactItems = cvContactLinkedItems(for: currentAuthor, language: exportLanguage)
        let manuscriptsInWriting = userPublications.filter { PublicationStatus.fromStored($0.statusLabel) == .inPreparation }
        let submittedManuscripts = userPublications.filter { PublicationStatus.fromStored($0.statusLabel) == .submitted }
        let acceptedManuscripts = userPublications.filter { PublicationStatus.fromStored($0.statusLabel) == .accepted }
        // Round 12: research letters are listed with the original articles
        // (as in the AMA publication list); they fell out of the CV before.
        let publishedOriginals = userPublications.filter {
            isPeerReviewedPublishedPublication($0)
                && (publicationTypeBucket(for: $0) == "original" || normalizedPublicationType(for: $0) == "research letter")
        }
        let publishedReviews = userPublications.filter {
            isPeerReviewedPublishedPublication($0) && publicationTypeBucket(for: $0) == "review"
        }
        let publishedProtocols = userPublications.filter {
            isPeerReviewedPublishedPublication($0) && isProtocolPublicationType($0)
        }
        let publishedOther = userPublications.filter { publication in
            let status = PublicationStatus.fromStored(publication.statusLabel)
            return status == .published && !isPeerReviewedPublishedPublication(publication)
        }
        let teachingItems = cvTeachingLinkedItems(language: exportLanguage)
        let reviewItems = cvOwnReviewLinkedItems(language: exportLanguage)
        let doctoralThesisItems = cvDoctoralThesisEntries().map { entry in
            CVLinkedTextItem(
                text: cvOwnDoctoralThesisLine(
                    for: entry,
                    language: exportLanguage,
                    publicationOptions: effectivePublicationOptions,
                    underlineMainSupervisor: underlineDoctoralMainSupervisor,
                    underlineCoSupervisor: underlineDoctoralCoSupervisor
                ),
                sourceID: "other-publication-\(entry.id)"
            )
        }
        let grantItems = currentUserGrantedGrants(includeCollaboratorGrants: includeCollaboratorGrants).map { application in
            CVLinkedTextItem(
                text: cvOwnGrantLine(for: application, language: exportLanguage),
                sourceID: "application-\(application.id)"
            )
        }
        let conferenceItems = cvNumberedLinkedItems(
            cvConferenceContributions.filter(\.isCVReportable).map { contribution in
                CVLinkedTextItem(
                    text: cvOwnConferenceLine(for: contribution, language: exportLanguage),
                    sourceID: "conference-\(contribution.id)"
                )
            }
        )
        let mediaItems = cvMediaAppearances.filter(mediaAppearanceIncludesCurrentUser).map { appearance in
            CVLinkedTextItem(
                text: cvOwnMediaLine(for: appearance, language: exportLanguage),
                sourceID: "media-\(appearance.id)"
            )
        }
        let degreeItems = cvProfileEditorLinkedItems(cvOwnDegreeItems(for: currentAuthor, language: exportLanguage))
        let courseItems = cvProfileEditorLinkedItems(cvOwnCourseItems(for: currentAuthor, language: exportLanguage))
        let currentEmploymentItems = cvProfileEditorLinkedItems(cvOwnCurrentEmploymentItems(for: currentAuthor, language: exportLanguage))
        let pastEmploymentItems = cvProfileEditorLinkedItems(cvOwnPastEmploymentItems(for: currentAuthor, language: exportLanguage))
        let associationMembershipItems = cvCurrentAssociationMembershipLinkedItems(language: exportLanguage)

        let sections: [CVExportSection] = [
            (CVExportSectionKey.contactDetails, CVExportSection(
                title: cvText(exportLanguage, english: "Contact details", swedish: "Kontaktuppgifter"),
                items: cvLinkedItemTexts(contactItems),
                itemSourceIDs: cvLinkedItemSourceIDs(contactItems)
            )),
            (CVExportSectionKey.personalResume, CVExportSection(
                title: cvText(exportLanguage, english: "Personal resume", swedish: "Personlig resumé"),
                richParagraphs: cvPersonalResumeExportParagraphs(language: exportLanguage)
            )),
            (CVExportSectionKey.doctoralThesis, CVExportSection(
                title: cvText(exportLanguage, english: "Doctoral thesis", swedish: "Doktorsavhandling"),
                layoutKind: "publicationList",
                items: cvLinkedItemTexts(doctoralThesisItems),
                itemSourceIDs: cvLinkedItemSourceIDs(doctoralThesisItems)
            )),
            (CVExportSectionKey.degreesAndLicenses, CVExportSection(
                title: cvText(exportLanguage, english: "Degrees and licenses", swedish: "Examina och legitimationer"),
                items: cvLinkedItemTexts(degreeItems),
                itemSourceIDs: cvLinkedItemSourceIDs(degreeItems)
            )),
            (CVExportSectionKey.courses, CVExportSection(
                title: cvText(exportLanguage, english: "Courses", swedish: "Kurser"),
                items: cvLinkedItemTexts(courseItems),
                itemSourceIDs: cvLinkedItemSourceIDs(courseItems)
            )),
            (CVExportSectionKey.currentPositions, CVExportSection(
                title: cvText(exportLanguage, english: "Current positions", swedish: "Nuvarande anställningar"),
                items: cvLinkedItemTexts(currentEmploymentItems),
                itemSourceIDs: cvLinkedItemSourceIDs(currentEmploymentItems)
            )),
            (CVExportSectionKey.pastPositions, CVExportSection(
                title: cvText(exportLanguage, english: "Past positions (selected)", swedish: "Tidigare anställningar (urval)"),
                items: cvLinkedItemTexts(pastEmploymentItems),
                itemSourceIDs: cvLinkedItemSourceIDs(pastEmploymentItems)
            )),
            (CVExportSectionKey.teaching, CVExportSection(
                title: cvText(exportLanguage, english: "Supervision and teaching activities", swedish: "Handledning och undervisning"),
                items: cvLinkedItemTexts(teachingItems),
                itemSourceIDs: cvLinkedItemSourceIDs(teachingItems)
            )),
            (CVExportSectionKey.grants, CVExportSection(
                title: cvText(exportLanguage, english: "Grants", swedish: "Anslag"),
                layoutKind: "grants",
                items: cvLinkedItemTexts(grantItems),
                itemSourceIDs: cvLinkedItemSourceIDs(grantItems)
            )),
            (CVExportSectionKey.originalArticles, CVExportSection(
                title: cvText(exportLanguage, english: "Original articles", swedish: "Originalartiklar"),
                layoutKind: "publicationList",
                subsections: [
                    CVExportSubsection(
                        title: "",
                        amaItems: numberedAMAItems(publishedOriginals.map { amaCitationItem(for: $0, options: effectivePublicationOptions) })
                    )
                ]
            )),
            (CVExportSectionKey.reviewArticles, CVExportSection(
                title: cvText(exportLanguage, english: "Review articles", swedish: "Översiktsartiklar"),
                layoutKind: "publicationList",
                subsections: [
                    CVExportSubsection(
                        title: "",
                        amaItems: numberedAMAItems(publishedReviews.map { amaCitationItem(for: $0, options: effectivePublicationOptions) })
                    )
                ]
            )),
            (CVExportSectionKey.protocolArticles, CVExportSection(
                title: cvText(exportLanguage, english: "Protocol articles", swedish: "Protokollartiklar"),
                layoutKind: "publicationList",
                subsections: [
                    CVExportSubsection(
                        title: "",
                        amaItems: numberedAMAItems(publishedProtocols.map { amaCitationItem(for: $0, options: effectivePublicationOptions) })
                    )
                ]
            )),
            (CVExportSectionKey.manuscriptsInWriting, CVExportSection(
                title: cvText(exportLanguage, english: "Manuscripts in writing", swedish: "Manuskript under skrivande"),
                layoutKind: "publicationList",
                subsections: [CVExportSubsection(title: "", amaItems: numberedAMAItems(manuscriptsInWriting.map { amaCitationItem(for: $0, options: effectivePublicationOptions) }))]
            )),
            (CVExportSectionKey.submittedManuscripts, CVExportSection(
                title: cvText(exportLanguage, english: "Submitted manuscripts", swedish: "Inskickade manuskript"),
                layoutKind: "publicationList",
                subsections: [CVExportSubsection(title: "", amaItems: numberedAMAItems(submittedManuscripts.map { amaCitationItem(for: $0, options: effectivePublicationOptions) }))]
            )),
            (CVExportSectionKey.acceptedManuscripts, CVExportSection(
                title: cvText(exportLanguage, english: "Accepted manuscripts", swedish: "Accepterade manuskript"),
                layoutKind: "publicationList",
                subsections: [CVExportSubsection(title: "", amaItems: numberedAMAItems(acceptedManuscripts.map { amaCitationItem(for: $0, options: effectivePublicationOptions) }))]
            )),
            (CVExportSectionKey.otherPublications, cvOwnOtherPublicationsSection(
                publishedOther: publishedOther,
                language: exportLanguage,
                publicationOptions: effectivePublicationOptions
            )),
            (CVExportSectionKey.conferenceContributions, CVExportSection(
                title: cvText(exportLanguage, english: "Conference contributions", swedish: "Konferensbidrag"),
                layoutKind: "conferenceContributions",
                items: cvLinkedItemTexts(conferenceItems),
                itemSourceIDs: cvLinkedItemSourceIDs(conferenceItems)
            )),
            (CVExportSectionKey.media, CVExportSection(
                title: cvText(exportLanguage, english: "Media", swedish: "Media"),
                layoutKind: "media",
                items: cvLinkedItemTexts(mediaItems),
                itemSourceIDs: cvLinkedItemSourceIDs(mediaItems)
            )),
            (CVExportSectionKey.reviews, CVExportSection(
                title: cvText(exportLanguage, english: "Reviews", swedish: "Reviews"),
                layoutKind: "reviews",
                items: cvLinkedItemTexts(reviewItems),
                itemSourceIDs: cvLinkedItemSourceIDs(reviewItems)
            )),
            (CVExportSectionKey.currentAssociationMemberships, CVExportSection(
                title: cvText(exportLanguage, english: "Current association memberships", swedish: "Aktuella föreningsmedlemskap"),
                items: cvLinkedItemTexts(associationMembershipItems),
                itemSourceIDs: cvLinkedItemSourceIDs(associationMembershipItems)
            )),
        ]
        .filter { includedSections.contains($0.0) }
        .map(\.1)
        .filter {
            !$0.items.isEmpty || !$0.rows.isEmpty || !$0.paragraphs.isEmpty || !$0.richParagraphs.isEmpty || !$0.subsections.isEmpty
        }

        return CVExportDocument(
            style: CVDocumentExportStyle.own.rawValue,
            exportLanguage: exportLanguage.rawValue,
            highlightName: publicationOptions.boldOwnName ? (currentAuthor?.name ?? "") : "",
            title: cvText(exportLanguage, english: "CURRICULUM VITAE", swedish: "CURRICULUM VITAE"),
            subtitle: name,
            summaryLines: [],
            summaryRichParagraphs: [],
            sections: sections
        )
    }

    private func cvLiUExportDocument(
        language exportLanguage: AppLanguage,
        includedSections: Set<CVExportSectionKey>,
        publicationOptions: PublicationExportOptions,
        includeCollaboratorGrants: Bool,
        underlineDoctoralMainSupervisor: Bool,
        underlineDoctoralCoSupervisor: Bool
    ) -> CVExportDocument {
        var effectivePublicationOptions = publicationExportOptions(
            from: publicationOptions,
            underlineDoctoralMainSupervisor: underlineDoctoralMainSupervisor,
            underlineDoctoralCoSupervisor: underlineDoctoralCoSupervisor
        )
        effectivePublicationOptions.exportLanguage = exportLanguage
        let currentAuthor = currentUserAuthor()
        let userPublications = currentUserPublications(sortOrder: effectivePublicationOptions.sortOrder)
        let peerReviewedPublications = numberedAMAItems(userPublications.filter(isPeerReviewedPublishedPublication).map { amaCitationItem(for: $0, options: effectivePublicationOptions) })
        let publishedOtherPublicationRecords = userPublications.filter {
            let status = PublicationStatus.fromStored($0.statusLabel)
            return status == .published && !isPeerReviewedPublishedPublication($0)
        }
        let otherPublicationTitleKeys = Set(
            publishedOtherPublicationRecords.map { liuDuplicatePublicationTitleKey($0.title) }
        )
        let otherPublications = numberedAMAItems(
            publishedOtherPublicationRecords.map { amaCitationItem(for: $0, options: effectivePublicationOptions) }
        )
        let doctoralThesisItems = cvDoctoralThesisEntries().map { entry in
            CVLinkedTextItem(
                text: cvOwnDoctoralThesisLine(
                    for: entry,
                    language: exportLanguage,
                    publicationOptions: effectivePublicationOptions,
                    underlineMainSupervisor: underlineDoctoralMainSupervisor,
                    underlineCoSupervisor: underlineDoctoralCoSupervisor
                ),
                sourceID: "other-publication-\(entry.id)"
            )
        }
        let manualOtherPublications = cvNumberedLinkedItems(
            cvOtherPublications
                .filter {
                    !$0.isEmpty && !isDoctoralThesisCategory($0)
                        && !otherPublicationTitleKeys.contains(
                            liuDuplicatePublicationTitleKey($0.localizedTitle(language: exportLanguage))
                        )
                }
                .sorted {
                    if $0.date != $1.date { return $0.date > $1.date }
                    return ($0.localizedTitle(language: exportLanguage).nonEmpty ?? $0.displayTitle)
                        .localizedStandardCompare($1.localizedTitle(language: exportLanguage).nonEmpty ?? $1.displayTitle) == .orderedAscending
                }
                .map { entry in
                    CVLinkedTextItem(
                        text: cvOwnOtherPublicationLine(for: entry, language: exportLanguage),
                        sourceID: "other-publication-\(entry.id)"
                    )
                }
        )
        let teachingItems = cvTeachingLinkedItems(language: exportLanguage)
        let reviewItems = cvLiUReviewLinkedItems(language: exportLanguage)
        let grantItems = currentUserGrantedGrants(includeCollaboratorGrants: includeCollaboratorGrants).map { application in
            CVLinkedTextItem(
                text: cvLiUGrantLine(for: application, language: exportLanguage),
                sourceID: "application-\(application.id)"
            )
        }
        let conferenceItems = cvConferenceContributions.filter(\.isCVReportable).map { contribution in
            CVLinkedTextItem(
                text: cvLiUConferenceLine(for: contribution, language: exportLanguage),
                sourceID: "conference-\(contribution.id)"
            )
        }
        let mediaItems = cvMediaAppearances.filter(mediaAppearanceIncludesCurrentUser).map { appearance in
            CVLinkedTextItem(
                text: cvLiUMediaLine(for: appearance, language: exportLanguage),
                sourceID: "media-\(appearance.id)"
            )
        }

        let sections = liuPrunedSections([
            CVExportSection(
                title: "1.0 Personuppgifter",
                subsections: [
                    CVExportSubsection(title: "1.1 Namn", items: includedSections.contains(.contactDetails) ? [currentAuthor?.name ?? ""] : []),
                    CVExportSubsection(title: "1.2 Personnummer", items: includedSections.contains(.contactDetails) ? [liuPersonalNumber(from: currentAuthor?.birthDate ?? "")] : []),
                    CVExportSubsection(title: "1.3 Bostadsadress och telefonnummer", items: includedSections.contains(.contactDetails) ? cvLiUHomeContactItems(for: currentAuthor, language: exportLanguage) : []),
                    CVExportSubsection(title: "1.4 Adress och telefonnummer arbete", items: includedSections.contains(.contactDetails) ? cvLiUWorkContactItems(for: currentAuthor, language: exportLanguage) : []),
                    CVExportSubsection(title: "1.4.1 Epostadress", items: includedSections.contains(.contactDetails) ? [currentAuthor?.primaryAffiliation?.email ?? ""] : []),
                    CVExportSubsection(
                        title: "1.5 Nuvarande anställning med exakt benämning och anställningsdatum. Vid ansökan om befordran: Bifoga anställningsbeslut för anställning som biträdande professor/universitetslektor/junior universitetslektor/biträdande universitetslektor/universitetsadjunkt.",
                        items: includedSections.contains(.currentPositions) ? cvLiUCurrentEmploymentItems(for: currentAuthor, language: exportLanguage) : []
                    ),
                    CVExportSubsection(
                        title: "1.6 Tidigare anställningar. Tjänstledigheter och typ av tjänstledighet, t. ex. föräldraledighet",
                        items: includedSections.contains(.pastPositions) ? cvLiUPastEmploymentItems(for: currentAuthor, language: exportLanguage) : []
                    ),
                    CVExportSubsection(
                        title: "1.7 Vistelse som gästforskare/lärare, postdoc etc",
                        items: includedSections.contains(.pastPositions) ? cvLiUVisitingPositionItems(for: currentAuthor, language: exportLanguage) : []
                    ),
                ]
            ),
            CVExportSection(
                title: "2.0 Examina",
                subsections: [
                    CVExportSubsection(
                        title: "2.1 Högskoleexamina med år. Bifoga betyg",
                        items: includedSections.contains(.degreesAndLicenses) ? cvLiUDegreeItems(for: currentAuthor, language: exportLanguage) : []
                    )
                ]
            ),
            CVExportSection(
                title: "3.0 Vetenskapliga meriter",
                subsections: [
                    CVExportSubsection(title: "3.3 Publikationslista"),
                    CVExportSubsection(
                        title: "3.3.1 Vetenskapliga publikationer i vetenskapliga tidskrifter. (Markera de arbeten som ingår i doktorsavhandlingen)",
                        amaItems: includedSections.contains(.originalArticles) || includedSections.contains(.reviewArticles) || includedSections.contains(.protocolArticles) ? peerReviewedPublications : []
                    ),
                    CVExportSubsection(
                        title: "3.3.2 Övriga publikationer",
                        items: cvLinkedItemTexts((includedSections.contains(.doctoralThesis) ? doctoralThesisItems : [])
                            + (includedSections.contains(.otherPublications) ? manualOtherPublications : []),
                        ),
                        itemSourceIDs: cvLinkedItemSourceIDs((includedSections.contains(.doctoralThesis) ? doctoralThesisItems : [])
                            + (includedSections.contains(.otherPublications) ? manualOtherPublications : [])
                        ),
                        amaItems: includedSections.contains(.otherPublications) ? otherPublications : []
                    ),
                    CVExportSubsection(
                        title: "3.4 Beviljade anslag. Större anslag som erhållits som huvudman eller medsökande (ange huvudman samt övriga medsökande) de senaste fem åren",
                        items: includedSections.contains(.grants) ? cvLinkedItemTexts(grantItems) : [],
                        itemSourceIDs: includedSections.contains(.grants) ? cvLinkedItemSourceIDs(grantItems) : nil
                    ),
                    CVExportSubsection(
                        title: "3.5 Aktivt deltagande i konferenser",
                        items: includedSections.contains(.conferenceContributions) ? cvLinkedItemTexts(conferenceItems) : [],
                        itemSourceIDs: includedSections.contains(.conferenceContributions) ? cvLinkedItemSourceIDs(conferenceItems) : nil
                    ),
                    CVExportSubsection(
                        title: "3.5.4 Refereeuppdrag för tidskrifter. Ange vilka tidskrifter och genomsnittligt antal uppdrag per år",
                        items: includedSections.contains(.reviews) ? cvLinkedItemTexts(reviewItems) : [],
                        itemSourceIDs: includedSections.contains(.reviews) ? cvLinkedItemSourceIDs(reviewItems) : nil
                    ),
                    CVExportSubsection(
                        title: "3.6 Övrig vetenskaplig meritering",
                        items: includedSections.contains(.media) ? cvLinkedItemTexts(mediaItems) : [],
                        itemSourceIDs: includedSections.contains(.media) ? cvLinkedItemSourceIDs(mediaItems) : nil
                    ),
                ]
            ),
            CVExportSection(
                title: "4.0 Pedagogiska meriter",
                subsections: [
                    CVExportSubsection(
                        title: "4.1 Beskrivning av egen pedagogisk verksamhet på grundläggande/avancerad/forskarnivå",
                        paragraphs: liuTeachingInstructionLines(),
                        items: includedSections.contains(.teaching) ? cvLinkedItemTexts(teachingItems) : [],
                        itemSourceIDs: includedSections.contains(.teaching) ? cvLinkedItemSourceIDs(teachingItems) : nil
                    )
                ]
            ),
            CVExportSection(
                title: "5.0 Annan relevant yrkesskicklighet"
            ),
            CVExportSection(
                title: "6.0 Administrativ skicklighet - chefs- och/eller ledarskapsuppdrag"
            ),
        ])

        return CVExportDocument(
            style: CVDocumentExportStyle.liu.rawValue,
            exportLanguage: exportLanguage.rawValue,
            highlightName: "",
            title: currentAuthor?.name.nonEmpty ?? "CV",
            subtitle: "",
            summaryLines: [],
            summaryRichParagraphs: [],
            sections: sections
        )
    }

    private func cvText(_ exportLanguage: AppLanguage, english: String, swedish: String) -> String {
        exportLanguage == .swedish ? swedish : english
    }

    private func liuPrunedSections(_ sections: [CVExportSection]) -> [CVExportSection] {
        sections.compactMap(liuPrunedSection)
    }

    private func liuPrunedSection(_ section: CVExportSection) -> CVExportSection? {
        var pruned = section
        let hasPublicationListContent = section.subsections.contains {
            $0.title.hasPrefix("3.3.") && liuSubsectionHasContent($0)
        }
        pruned.subsections = section.subsections.filter {
            liuSubsectionHasContent($0)
                || ($0.title == "3.3 Publikationslista" && hasPublicationListContent)
        }
        return liuSectionHasContent(pruned) ? pruned : nil
    }

    private func liuSectionHasContent(_ section: CVExportSection) -> Bool {
        liuContainsContent(section.headers)
            || section.rows.contains { liuContainsContent($0) }
            || liuContainsContent(section.paragraphs)
            || section.richParagraphs.contains { liuRichParagraphHasContent($0) }
            || liuContainsContent(section.items)
            || !section.subsections.isEmpty
    }

    private func liuSubsectionHasContent(_ subsection: CVExportSubsection) -> Bool {
        liuContainsContent(subsection.paragraphs)
            || liuContainsContent(subsection.items)
            || subsection.amaItems.contains(where: liuAMAItemHasContent)
            || subsection.vrItems.contains { liuContainsContent([$0.citation, $0.note]) }
    }

    private func liuContainsContent(_ values: [String]) -> Bool {
        values.contains { $0.nonEmpty != nil }
    }

    private func liuRichParagraphHasContent(_ paragraph: CVExportRichTextParagraph) -> Bool {
        paragraph.runs.contains { $0.text.nonEmpty != nil }
    }

    private func liuAMAItemHasContent(_ item: PublicationAMAItem) -> Bool {
        liuContainsContent([item.authors, item.title, item.journal, item.tail, item.note, item.plain])
    }

    private func liuTeachingInstructionLines() -> [String] {
        [
            "Vid omfattande verksamhet kan dokumentationen bestå av en sammanfattning av den sökandes totala pedagogiska verksamhet samt en precisering av aktiviteterna de senaste fem åren.",
            "Universitet/högskola",
            "Omfattning och nivå",
            "Olika former och metoder i undervisning/examinationer",
            "Erfarenhet av IT-stödd undervisning",
            "Internationell undervisningserfarenhet/undervisning på engelska",
            "Kursansvar/examinator",
            "Handledning av uppsatser/avhandlingar",
            "Din erfarenhet av verksamhetsförlagd undervisning",
            "Ange huvud- eller biträdande handledare, studentens namn, titel på arbetet, nivå och ev poäng samt examensår",
        ]
    }

    private func liuDuplicatePublicationTitleKey(_ title: String) -> String {
        title
            .folding(options: [.caseInsensitive, .diacriticInsensitive], locale: .current)
            .lowercased()
            .replacingOccurrences(of: #"[^a-z0-9]+"#, with: " ", options: .regularExpression)
            .trimmingCharacters(in: .whitespacesAndNewlines)
    }

    func numberedAMAItems(_ items: [PublicationAMAItem]) -> [PublicationAMAItem] {
        items.enumerated().map { index, item in
            PublicationAMAItem(
                authors: "\(index + 1).\t\(item.authors)",
                title: item.title,
                journal: item.journal,
                tail: item.tail,
                note: item.note,
                plain: "\(index + 1).\t\(item.plain)",
                sourceID: item.sourceID
            )
        }
    }

    private func cvSummaryLines(for author: PublicationAuthor?) -> [String] {
        guard let author else { return [] }
        var lines: [String] = []
        if let title = author.localizedTitle(language: language).nonEmpty {
            lines.append(title)
        }
        if let affiliation = author.primaryAffiliation?.displayLine.nonEmpty {
            lines.append(affiliation)
        }
        if let email = author.primaryAffiliation?.email.nonEmpty {
            lines.append(email)
        }
        if let address = author.localizedHomeAddress(language: language).nonEmpty {
            lines.append(address)
        }
        return lines
    }

    private func cvEmploymentRows(for author: PublicationAuthor?) -> [[String]] {
        guard let author else { return [] }
        return author.employments.map {
            [
                formattedDateRange(from: $0.from, to: $0.to),
                $0.localizedTitle(language: language),
                $0.organization,
                $0.localizedDepartment(language: language),
            ]
        }
    }

    private func cvEducationRows(for author: PublicationAuthor?) -> [[String]] {
        guard let author else { return [] }
        return author.educationEntries.map {
            [
                formattedDateRange(from: $0.from, to: $0.to),
                localizedEducationLevel($0.level),
                $0.localizedDegree(language: language),
                $0.organization,
            ]
        }
    }

    private func cvContactLinkedItems(for author: PublicationAuthor?, language: AppLanguage) -> [CVLinkedTextItem] {
        guard let author else { return [] }
        var items: [CVLinkedTextItem] = []
        let authorSourceID = "author-\(author.id)"
        if let address = author.localizedHomeAddress(language: language).nonEmpty {
            items.append(
                CVLinkedTextItem(
                    text: "\(cvText(language, english: "Home address", swedish: "Hemadress"))\t\(address)",
                    sourceID: "profile-editor"
                )
            )
        }
        if let affiliationAddress = firstAffiliationAddress(for: author, language: language).nonEmpty {
            items.append(
                CVLinkedTextItem(
                    text: "\(cvText(language, english: "Work address", swedish: "Arbetsadress"))\t\(affiliationAddress)",
                    sourceID: authorSourceID
                )
            )
        }
        if let phone = author.phoneNumber.nonEmpty {
            let label = author.phoneLabel.nonEmpty ?? cvText(language, english: "Phone", swedish: "Telefon")
            items.append(CVLinkedTextItem(text: "\(label)\t\(phone)", sourceID: authorSourceID))
        }
        if let phone = author.phoneNumberSecondary.nonEmpty {
            let label = author.phoneLabelSecondary.nonEmpty ?? cvText(language, english: "Phone 2", swedish: "Telefon 2")
            items.append(CVLinkedTextItem(text: "\(label)\t\(phone)", sourceID: authorSourceID))
        }
        if let email = author.primaryAffiliation?.email.nonEmpty {
            items.append(CVLinkedTextItem(text: "E-mail\t\(email)", sourceID: authorSourceID))
        }
        return items
    }

    private func cvDegreeItems(for author: PublicationAuthor?) -> [String] {
        guard let author else { return [] }
        return author.educationEntries
            .filter { $0.level != .standaloneCourse }
            .sorted(by: cvEducationSortOrder)
            .map { cvEducationLine(for: $0) }
    }

    private func cvOwnDegreeItems(for author: PublicationAuthor?, language: AppLanguage) -> [String] {
        guard let author else { return [] }
        return author.educationEntries
            .filter { $0.level != .standaloneCourse }
            .sorted(by: cvEducationSortOrder)
            .map { entry in
                let location = [entry.localizedOrganization(language: language).nonEmpty, entry.city.nonEmpty, localizedCountryName(entry.country, language: language).nonEmpty]
                    .compactMap { $0 }
                    .joined(separator: ", ")
                let date = entry.to.nonEmpty ?? entry.from
                let details = [entry.localizedDegree(language: language).nonEmpty, location.nonEmpty]
                    .compactMap { $0 }
                    .joined(separator: ", ")
                return [date.nonEmpty, details.nonEmpty]
                    .compactMap { $0 }
                    .joined(separator: "\t")
            }
    }

    private func cvCourseItems(for author: PublicationAuthor?) -> [String] {
        guard let author else { return [] }
        return author.educationEntries
            .filter { $0.level == .standaloneCourse }
            .sorted(by: cvEducationSortOrder)
            .map { cvEducationLine(for: $0) }
    }

    private func cvOwnCourseItems(for author: PublicationAuthor?, language: AppLanguage) -> [String] {
        guard let author else { return [] }
        return author.educationEntries
            .filter { $0.level == .standaloneCourse }
            .sorted(by: cvEducationSortOrder)
            .map { entry in
                let details = [entry.localizedDegree(language: language).nonEmpty, entry.localizedOrganization(language: language).nonEmpty]
                    .compactMap { $0 }
                    .joined(separator: ", ")
                return [entry.to.nonEmpty ?? entry.from, details.nonEmpty]
                    .compactMap { $0 }
                    .joined(separator: "\t")
            }
    }

    private func cvCurrentEmploymentItems(for author: PublicationAuthor?) -> [String] {
        guard let author else { return [] }
        return author.employments
            .filter { $0.to.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty }
            .sorted(by: cvEmploymentSortOrder)
            .map { cvEmploymentLine(for: $0) }
    }

    private func cvOwnCurrentEmploymentItems(for author: PublicationAuthor?, language: AppLanguage) -> [String] {
        guard let author else { return [] }
        return author.employments
            .filter { $0.to.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty }
            .sorted(by: cvEmploymentSortOrder)
            .map { employment in
                [ownEmploymentPeriodLabel(employment), cvOwnEmploymentDescription(employment, language: language).nonEmpty]
                    .compactMap { $0 }
                    .joined(separator: "\t")
            }
    }

    private func cvPastEmploymentItems(for author: PublicationAuthor?) -> [String] {
        guard let author else { return [] }
        return author.employments
            .filter { !$0.to.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty }
            .sorted(by: cvEmploymentSortOrder)
            .map { cvEmploymentLine(for: $0) }
    }

    private func cvOwnPastEmploymentItems(for author: PublicationAuthor?, language: AppLanguage) -> [String] {
