    private struct CVLinkedTextItem {
        let text: String
        let sourceID: String?
    }

    private func cvLinkedItemTexts(_ items: [CVLinkedTextItem]) -> [String] {
        items.map(\.text)
    }

    private func cvLinkedItemSourceIDs(_ items: [CVLinkedTextItem]) -> [String]? {
        let sourceIDs = items.map { $0.sourceID ?? "" }
        return sourceIDs.contains { !$0.isEmpty } ? sourceIDs : nil
    }

    private func cvProfileEditorLinkedItems(_ items: [String]) -> [CVLinkedTextItem] {
