    }

    private func cvNumberedLinkedItems(_ items: [CVLinkedTextItem], startingAt startIndex: Int = 1) -> [CVLinkedTextItem] {
        items.enumerated().map { index, item in
            CVLinkedTextItem(
                text: "\(startIndex + index).\t\(item.text)",
                sourceID: item.sourceID
            )
        }
    }

    private func cvTeachingItems(language: AppLanguage) -> [String] {
        cvLinkedItemTexts(cvTeachingLinkedItems(language: language))
    }

    private func cvTeachingLinkedItems(language: AppLanguage) -> [CVLinkedTextItem] {
        struct CVTeachingEntry {
            let isOngoing: Bool
            let sortDate: Date
            let activityLabel: String
            let line: String
            let sourceID: String
        }

        let doctoralSourceAssignmentIDs = Set(doctoralCandidates.flatMap(\.sourceAssignmentIDs))
        let currentUser = currentUserAuthor()
        let normalizedCurrentUserNameKeys: Set<String> = currentUser.map {
            Set($0.presentedNameCandidates.map(PublicationDerivation.normalizedName).filter { !$0.isEmpty })
        } ?? []

        var entries: [CVTeachingEntry] = teachingAssignments
            .filter { !doctoralSourceAssignmentIDs.contains($0.id) }
            .map { assignment in
                let context = teachingCourses.first(where: { $0.id == assignment.contextID })
                let period = cvTeachingPeriodLabel(assignment).nonEmpty
                let roles = assignment.roles.map { localizedTeachingAssignmentRole($0, language: language) }.joined(separator: ", ").nonEmpty
                let activity = teachingComponent(for: assignment)?.localizedName(language: language).nonEmpty
                    ?? assignment.activityName.nonEmpty
                let contextLabel = context.map { teachingMeritsContextLabel($0, activity: activity, language: language) }.nonEmpty
                let student = assignment.studentName.nonEmpty.map { "(\($0))" }
                let activityAndContext = [activity, contextLabel].compactMap { $0 }.joined(separator: ", ").nonEmpty
                var trailingParts: [String] = []
                if let roles {
                    trailingParts.append(roles)
                }
                if let activityAndContext {
                    trailingParts.append(activityAndContext)
                }
                var trailing = trailingParts.joined(separator: ", ")
                if let student {
                    trailing += trailing.isEmpty ? student : " \(student)"
                }
                let line: String
                if let period, !period.isEmpty {
                    line = [period, trailing.nonEmpty].compactMap { $0 }.joined(separator: "\t")
                } else {
                    line = trailing
                }
                let lastDate = teachingAssignmentLastDate(assignment)
                let firstDate = teachingAssignmentFirstDate(assignment)
                let isOngoing = lastDate.isEmpty
                let sortKeyText = (isOngoing ? firstDate : lastDate).nonEmpty ?? ""
                return CVTeachingEntry(
                    isOngoing: isOngoing,
                    sortDate: DateParsers.isoDay.date(from: sortKeyText) ?? .distantPast,
                    activityLabel: activity ?? assignment.activityName,
                    line: line,
                    sourceID: "teaching-\(assignment.id)"
                )
            }

        let doctoralActivityLabel = cvText(language, english: "Doctoral supervision", swedish: "Doktorandhandledning")
        let doctoralEntries = doctoralCandidates.flatMap { candidate -> [CVTeachingEntry] in
            guard doctoralCandidateIncludesCurrentUser(
                candidate,
                currentUserID: currentUser?.id,
                normalizedCurrentUserNameKeys: normalizedCurrentUserNameKeys
            ) else {
                return []
            }
            let role = localizedDoctoralCandidateCurrentUserRoleLabel(candidate, language: language).nonEmpty
            let institution = organizationLabel(for: candidate, language: language).nonEmpty
                ?? candidate.institution.nonEmpty
            let doctoralProject = candidate.doctoralProjectName.nonEmpty
            let student = candidate.candidateName.nonEmpty.map { "(\($0))" }
            return candidate.supervisionPeriods
                .filter { !$0.isEmpty }
                .map { period in
                    let periodLabel = cvYearOnlyPeriodLabel(from: period.from, to: period.to).nonEmpty
                    let activityAndContext = [doctoralActivityLabel, doctoralProject, institution]
                        .compactMap { $0 }
                        .joined(separator: ", ")
                        .nonEmpty
                    var trailingParts: [String] = []
                    if let role {
                        trailingParts.append(role)
                    }
                    if let activityAndContext {
                        trailingParts.append(activityAndContext)
                    }
                    var trailing = trailingParts.joined(separator: ", ")
                    if let student {
                        trailing += trailing.isEmpty ? student : " \(student)"
                    }
                    let line: String
                    if let periodLabel, !periodLabel.isEmpty {
                        line = [periodLabel, trailing.nonEmpty].compactMap { $0 }.joined(separator: "\t")
                    } else {
                        line = trailing
                    }
                    let to = period.to.nonEmpty
                    let from = period.from.nonEmpty
                    let isOngoing = to == nil
                    let sortDateText = to ?? from ?? ""
                    return CVTeachingEntry(
                        isOngoing: isOngoing,
                        sortDate: DateParsers.isoDay.date(from: sortDateText) ?? .distantPast,
                        activityLabel: doctoralProject ?? doctoralActivityLabel,
                        line: line,
                        sourceID: "doctoral-\(candidate.id)"
                    )
                }
        }
        entries.append(contentsOf: doctoralEntries)

        return entries
            .sorted { lhs, rhs in
                if lhs.isOngoing != rhs.isOngoing {
                    return lhs.isOngoing && !rhs.isOngoing
                }
                if lhs.sortDate != rhs.sortDate {
                    return lhs.sortDate > rhs.sortDate
                }
                return lhs.activityLabel.localizedStandardCompare(rhs.activityLabel) == .orderedAscending
            }
            .map { CVLinkedTextItem(text: $0.line, sourceID: $0.sourceID) }
            .filter { !$0.text.isEmpty }
    }

    private func cvConferenceLine(for contribution: CVConferenceContribution) -> String {
        let meetingPlace = [contribution.meetingCity.nonEmpty, localizedCountryName(contribution.meetingCountry, language: language).nonEmpty]
            .compactMap { $0 }
            .joined(separator: ", ")
        return [
            formattedDateRange(from: contribution.from, to: contribution.to).nonEmpty,
            contribution.localizedName(language: language).nonEmpty,
            contribution.localizedTitle(language: language).nonEmpty,
            [contribution.localizedMeeting(language: language).nonEmpty, meetingPlace.nonEmpty].compactMap { $0 }.joined(separator: ", ").nonEmpty,
            cvConferencePublicationData(for: contribution, language: language).nonEmpty,
            contribution.localizedComments(language: language).nonEmpty,
        ]
        .compactMap { $0 }
        .joined(separator: ". ")
    }

    private func cvOwnConferenceLine(for contribution: CVConferenceContribution, language: AppLanguage) -> String {
        let dateText = ownConferenceDateLabel(from: contribution.from, to: contribution.to, language: language).nonEmpty
        let meeting = [
            contribution.localizedMeeting(language: language).nonEmpty,
            contribution.meetingCity.nonEmpty,
            localizedCountryName(contribution.meetingCountry, language: language).nonEmpty,
        ]
        .compactMap { $0 }
        .joined(separator: ", ")
        .nonEmpty
        let publication = cvConferencePublicationData(for: contribution, language: language).nonEmpty
        let presentedBy = contribution.presentedBy.nonEmpty.map {
            language == .swedish ? "Presenterat av \($0)" : "Presented by \($0)"
        }
        let comments = contribution.localizedComments(language: language).nonEmpty
        let presented = [meeting, dateText].compactMap { $0 }.joined(separator: ", ")
        var line = [
            contribution.localizedName(language: language).nonEmpty,
            contribution.localizedTitle(language: language).nonEmpty,
            contribution.localizedProjectName(language: language).nonEmpty,
            publication.map { "[[PUBDATA]]\($0)[[/PUBDATA]]" },
            presented.nonEmpty,
            presentedBy,
            comments,
        ]
        .compactMap { $0 }
        .joined(separator: ". ")
        if presentedBy != nil, comments == nil, !line.hasSuffix(".") {
            line += "."
        }
        return line
    }

    private func cvLiUConferenceLine(for contribution: CVConferenceContribution, language: AppLanguage) -> String {
        cvOwnConferenceLine(for: contribution, language: language)
    }

    private func isPublishedConferenceContribution(_ contribution: CVConferenceContribution) -> Bool {
        guard !contribution.isRejected else { return false }
        return contribution.journalName.nonEmpty != nil ||
            contribution.journalDOI.nonEmpty != nil ||
            contribution.journalPMID.nonEmpty != nil ||
            contribution.journalVolume.nonEmpty != nil ||
            contribution.journalIssue.nonEmpty != nil ||
            contribution.journalPages.nonEmpty != nil ||
            contribution.journalArticleNumber.nonEmpty != nil
    }

    private func conferenceContributionSortOrder(_ lhs: CVConferenceContribution, _ rhs: CVConferenceContribution) -> Bool {
        let leftDate = DateParsers.isoDay.date(from: lhs.to.nonEmpty ?? lhs.from.nonEmpty ?? "") ?? .distantPast
        let rightDate = DateParsers.isoDay.date(from: rhs.to.nonEmpty ?? rhs.from.nonEmpty ?? "") ?? .distantPast
        if leftDate != rightDate {
            return leftDate > rightDate
        }
        let leftYear = Int(lhs.publicationYear) ?? 0
        let rightYear = Int(rhs.publicationYear) ?? 0
        if leftYear != rightYear {
            return leftYear > rightYear
        }
        return (lhs.localizedTitle(language: language).nonEmpty ?? lhs.displayTitle)
            .localizedStandardCompare(rhs.localizedTitle(language: language).nonEmpty ?? rhs.displayTitle) == .orderedAscending
    }

    private func cvConferencePublicationData(for contribution: CVConferenceContribution, language: AppLanguage) -> String {
        let journalName = contribution.journalName.nonEmpty
        let publicationYear = contribution.publicationYear.nonEmpty
        let citationTail: String? = {
            var bits: [String] = []
            var leading = ""
            if let year = publicationYear {
                leading = year
            }
            if let volume = contribution.journalVolume.nonEmpty {
                var volumePart = volume
                if let issue = contribution.journalIssue.nonEmpty {
                    volumePart += "(\(issue))"
                }
                if leading.isEmpty {
                    bits.append(volumePart)
                } else {
                    bits.append("\(leading);\(volumePart)")
                    leading = ""
                }
            } else if let issue = contribution.journalIssue.nonEmpty {
                let issueText = language == .swedish ? "nr \(issue)" : "no. \(issue)"
                if leading.isEmpty {
                    bits.append(issueText)
                } else {
                    bits.append("\(leading); \(issueText)")
                    leading = ""
                }
            }

            if let pages = contribution.journalPages.nonEmpty {
                bits.append(pages)
            } else if let articleNumber = contribution.journalArticleNumber.nonEmpty {
                bits.append(articleNumber)
            }

            if !leading.isEmpty {
                bits.insert(leading, at: 0)
            }

            var tail = bits.joined(separator: ":")
            if let doi = contribution.journalDOI.nonEmpty {
                tail += tail.isEmpty ? "doi:\(doi)" : ". doi:\(doi)"
            }
            if let pmid = contribution.journalPMID.nonEmpty {
                tail += tail.isEmpty ? "PMID:\(pmid)" : ". PMID:\(pmid)"
            }
            return tail.nonEmpty
        }()

        let structured = [journalName, citationTail]
            .compactMap { $0 }
            .joined(separator: journalName != nil && citationTail != nil ? ". " : "")

        let freeText = contribution.localizedPublicationData(language: language).nonEmpty
        return [structured.nonEmpty, freeText]
            .compactMap { $0 }
            .joined(separator: structured.nonEmpty != nil && freeText != nil ? ". " : "")
    }

