    private func cvReviewAssignmentTitle(for review: CVReviewEntry) -> String {
        switch review.category {
        case .journalReview:
            return review.journalName.nonEmpty ?? review.reference.nonEmpty ?? review.id
        case .grantProposalReview:
            return [review.organizationName.nonEmpty, review.programName.nonEmpty]
                .compactMap { $0 }
                .joined(separator: ", ")
                .nonEmpty ?? review.reference.nonEmpty ?? review.id
        case .doctoralExamination:
            return [review.personName.nonEmpty, review.organizationName.nonEmpty, review.roleName.nonEmpty]
                .compactMap { $0 }
                .joined(separator: ", ")
                .nonEmpty ?? review.reference.nonEmpty ?? review.id
        case .otherExpertAssignment:
            return [review.organizationName.nonEmpty, review.roleName.nonEmpty]
                .compactMap { $0 }
                .joined(separator: ", ")
                .nonEmpty ?? review.reference.nonEmpty ?? review.id
        }
    }

    private func cvGrantLine(for application: GrantApplication) -> String {
        let funder = organizationLabel(for: application, language: language).nonEmpty
        let grantName = application.grantName.nonEmpty
        let caseNumber = application.appliedCaseNumber.nonEmpty.map { "(\($0))" }
        let amount = preferredGrantAmountText(application).nonEmpty
        let period = formattedDateRange(
            from: application.appliedOn ?? "",
            to: application.grantedOn ?? application.deniedOn ?? application.withdrawnOn ?? ""
        ).nonEmpty
        return [funder, grantName, caseNumber, amount, period].compactMap { $0 }.joined(separator: ", ")
    }

    private func cvOwnGrantLine(for application: GrantApplication, language: AppLanguage) -> String {
        let year = yearString(from: application.grantedOn ?? application.appliedOn ?? "")
        let funder = organizationLabel(for: application, language: language).nonEmpty
        let caseNumber = application.appliedCaseNumber.nonEmpty.map { "(\($0))" }
        let amount = cvGrantAmountText(application)
        let label = funder
        let details = [[label, caseNumber].compactMap { $0 }.joined(separator: " "), amount]
            .compactMap { $0?.nonEmpty }
            .joined(separator: ", ")
        return [year.nonEmpty, details.nonEmpty]
            .compactMap { $0 }
            .joined(separator: "\t")
    }

