    private func cvCurrentAssociationMembershipLinkedItems(language: AppLanguage) -> [CVLinkedTextItem] {
        let currentYear = Calendar(identifier: .gregorian).component(.year, from: Date())

        return organizations
            .filter { $0.roles.contains(.association) }
            .compactMap { organization -> (id: String, name: String, startYear: Int, line: String)? in
                let fromRaw = organization.membershipFrom.trimmingCharacters(in: .whitespacesAndNewlines)
                guard !fromRaw.isEmpty, let startYear = membershipYearComponent(from: fromRaw) else { return nil }

                let toRaw = organization.membershipTo.trimmingCharacters(in: .whitespacesAndNewlines)
                if !toRaw.isEmpty, let toYear = membershipYearComponent(from: toRaw), toYear < currentYear {
                    return nil
                }

                let name = language == .swedish
                    ? organization.nameSv
                    : (organization.nameEn.nonEmpty ?? organization.nameSv)
                let fromPrefix = cvText(language, english: "from", swedish: "från")
                let line = "\(name) (\(fromPrefix) \(startYear)–)"
                return (organization.id, name, startYear, line)
            }
            .sorted {
                if $0.startYear != $1.startYear {
                    return $0.startYear > $1.startYear
                }
                return $0.name.localizedStandardCompare($1.name) == .orderedAscending
            }
            .map { item in
                CVLinkedTextItem(text: item.line, sourceID: "organization-\(item.id)")
            }
    }

    private func membershipYearComponent(from text: String) -> Int? {
        let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
        if let value = Int(trimmed) {
            return value
        }
        guard let range = trimmed.range(of: #"\d{4}"#, options: .regularExpression) else {
            return nil
        }
        return Int(trimmed[range])
    }

    private func cvOwnOtherPublicationSubsections(
        publishedOther: [PublicationRecord],
        language: AppLanguage,
        publicationOptions: PublicationExportOptions
    ) -> [CVExportSubsection] {
        var subsections: [CVExportSubsection] = []
        let nonPeerReviewedTitle = standardizedNonPeerReviewedOtherPublicationsTitle(language: language)
        let publishedItems = numberedAMAItems(publishedOther.map { amaCitationItem(for: $0, options: publicationOptions) })
        let publishedKeys = Set(publishedOther.map(migrationKey(for:)))
        var renderedNonPeerReviewedKeys: Set<String> = []

        let grouped = Dictionary(grouping: cvOtherPublications.filter {
            !$0.isEmpty && !isDoctoralThesisCategory($0)
        }) { entry in
            normalizedOtherPublicationCategoryTitle(for: entry, language: language)
        }

        for category in grouped.keys.sorted(by: { $0.localizedStandardCompare($1) == .orderedAscending }) {
            let hidesLeadingYear = isNonPeerReviewedOtherPublicationCategory(category)
            let items = grouped[category, default: []]
                .filter { entry in
                    guard hidesLeadingYear else { return true }
                    guard let key = migrationKey(for: entry) else { return true }
                    guard !publishedKeys.contains(key) else { return false }
                    guard !renderedNonPeerReviewedKeys.contains(key) else { return false }
                    renderedNonPeerReviewedKeys.insert(key)
                    return true
                }
                .sorted { lhs, rhs in
                    if lhs.date != rhs.date {
                        return lhs.date > rhs.date
                    }
                    let left = lhs.localizedTitle(language: language).nonEmpty ?? lhs.displayTitle
                    let right = rhs.localizedTitle(language: language).nonEmpty ?? rhs.displayTitle
                    return left.localizedStandardCompare(right) == .orderedAscending
                }
                .map { entry in
                    CVLinkedTextItem(
                        text: cvOwnOtherPublicationLine(for: entry, language: language, includeLeadingYear: !hidesLeadingYear),
                        sourceID: "other-publication-\(entry.id)"
                    )
                }
                .filter { !$0.text.isEmpty }

            if !items.isEmpty || (hidesLeadingYear && !publishedItems.isEmpty) {
                if hidesLeadingYear {
                    let numberedItems = cvNumberedLinkedItems(items, startingAt: publishedItems.count + 1)
                    subsections.append(
                        CVExportSubsection(
                            title: nonPeerReviewedTitle,
                            items: items.isEmpty ? [] : cvLinkedItemTexts(numberedItems),
                            itemSourceIDs: cvLinkedItemSourceIDs(numberedItems),
                            amaItems: publishedItems
                        )
                    )
                    continue
                }

                let useYearAsLeadingColumn = category == cvText(language, english: "Other", swedish: "Övrigt")
                let renderedItems = useYearAsLeadingColumn ? items : cvNumberedLinkedItems(items)
                subsections.append(
                    CVExportSubsection(
                        title: category,
                        items: cvLinkedItemTexts(renderedItems),
                        itemSourceIDs: cvLinkedItemSourceIDs(renderedItems)
                    )
                )
            }
        }

        if !publishedItems.isEmpty && !subsections.contains(where: { $0.title == nonPeerReviewedTitle }) {
            subsections.append(CVExportSubsection(title: nonPeerReviewedTitle, amaItems: publishedItems))
        }

        return subsections
    }

    private func cvOwnOtherPublicationsSectionTitle(
        publishedOther: [PublicationRecord],
        language: AppLanguage,
        publicationOptions: PublicationExportOptions
    ) -> String {
        let subsections = cvOwnOtherPublicationSubsections(
            publishedOther: publishedOther,
            language: language,
            publicationOptions: publicationOptions
        )
        let nonPeerReviewedTitle = standardizedNonPeerReviewedOtherPublicationsTitle(language: language)
        if subsections.count == 1 && subsections.first?.title == nonPeerReviewedTitle {
            return nonPeerReviewedTitle
        }
        return cvText(language, english: "Other publications", swedish: "Övriga publikationer")
    }

    private func cvOwnOtherPublicationsSection(
        publishedOther: [PublicationRecord],
        language: AppLanguage,
        publicationOptions: PublicationExportOptions
    ) -> CVExportSection {
        var subsections = cvOwnOtherPublicationSubsections(
            publishedOther: publishedOther,
            language: language,
            publicationOptions: publicationOptions
        )
        let nonPeerReviewedTitle = standardizedNonPeerReviewedOtherPublicationsTitle(language: language)
        let title = cvOwnOtherPublicationsSectionTitle(
            publishedOther: publishedOther,
            language: language,
            publicationOptions: publicationOptions
        )
        if subsections.count == 1 && subsections.first?.title == nonPeerReviewedTitle {
            subsections[0].title = ""
        }
        return CVExportSection(
            title: title,
            layoutKind: "publicationList",
            subsections: subsections
        )
    }

    private func standardizedNonPeerReviewedOtherPublicationsTitle(language: AppLanguage) -> String {
        cvText(
            language,
            english: "Other publications, not peer reviewed",
            swedish: "Övriga publikationer, ej expertgranskade"
        )
    }

    private func normalizedOtherPublicationCategoryTitle(
        for entry: CVOtherPublicationEntry,
        language: AppLanguage
    ) -> String {
        let categoryCandidates = [
            entry.localizedCategory(language: language),
            entry.localizedCategory(language: language == .swedish ? .english : .swedish),
            entry.categorySv,
            entry.categoryEn,
        ]
        if categoryCandidates.contains(where: isNonPeerReviewedOtherPublicationCategory) {
            return standardizedNonPeerReviewedOtherPublicationsTitle(language: language)
        }
        return entry.localizedCategory(language: language).nonEmpty
            ?? cvText(language, english: "Other publications", swedish: "Övriga publikationer")
    }

    private func isNonPeerReviewedOtherPublicationCategory(_ category: String) -> Bool {
        let normalized = category
            .folding(options: [.caseInsensitive, .diacriticInsensitive], locale: .current)
            .lowercased()
        return normalized.contains("ej peer")
            || normalized.contains("non peer")
            || normalized.contains("non-peer")
            || normalized.contains("not peer")
    }

    private func cvOwnOtherPublicationLine(
        for entry: CVOtherPublicationEntry,
        language: AppLanguage,
        includeLeadingYear: Bool = true
    ) -> String {
        let date = yearString(from: entry.date).nonEmpty ?? entry.date.nonEmpty
        let outlet = entry.localizedOutlet(language: language).nonEmpty
        let publicationData = entry.localizedPublicationData(language: language).nonEmpty
        let outletAndPublicationData: String? = {
            switch (outlet, publicationData, date?.nonEmpty) {
            case let (outlet?, publicationData?, year?):
                let trimmedPublicationData = publicationData.trimmingCharacters(in: .whitespacesAndNewlines)
                if trimmedPublicationData.hasPrefix(year) {
                    return [outlet, trimmedPublicationData].joined(separator: ". ")
                }
                return [outlet, "\(year);\(trimmedPublicationData)"].joined(separator: ". ")
            case let (outlet?, publicationData?, _):
                return [outlet, publicationData].joined(separator: ". ")
            case let (outlet?, nil, _):
                return outlet
            case let (nil, publicationData?, _):
                return publicationData
            default:
                return nil
            }
        }()

        let details = [
            entry.authors.nonEmpty,
            entry.localizedTitle(language: language).nonEmpty,
            outletAndPublicationData,
        ]
        .compactMap { $0 }
        .joined(separator: ". ")

        if includeLeadingYear {
            return [date, details.nonEmpty]
                .compactMap { $0 }
                .joined(separator: "\t")
        }

        return details.nonEmpty ?? ""
    }

    private func isDoctoralThesisCategory(_ entry: CVOtherPublicationEntry) -> Bool {
        entry.isDoctoralThesis
    }

    private func cvDoctoralThesisEntries() -> [CVOtherPublicationEntry] {
        cvOtherPublications.filter(isDoctoralThesisCategory)
    }

    private func cvOwnDoctoralThesisLine(
        for entry: CVOtherPublicationEntry,
        language: AppLanguage,
        publicationOptions: PublicationExportOptions,
        underlineMainSupervisor: Bool = false,
        underlineCoSupervisor: Bool = false
    ) -> String {
        let outletLine = [
            doctoralThesisOutletName(for: entry, language: language, publicationOptions: publicationOptions),
            entry.city.nonEmpty
        ]
        .compactMap { $0 }
        .joined(separator: ", ")
        .nonEmpty

        let supervisorDetails = [
            entry.mainSupervisor.nonEmpty.map {
                cvText(language, english: "Main supervisor: \($0)", swedish: "Huvudhandledare: \($0)")
            },
            entry.coSupervisor.nonEmpty.map {
                cvText(language, english: "Co-supervisor: \($0)", swedish: "Bihandledare: \($0)")
            }
        ]
        .compactMap { $0 }
        .joined(separator: ". ")
        .nonEmpty

        let filteredPublicationData = filteredDoctoralThesisPublicationData(
            for: entry,
            language: language,
            explicitDetails: [
                yearString(from: entry.date).nonEmpty ?? entry.date.nonEmpty,
                entry.localizedLanguage(language: language).nonEmpty,
                supervisorDetails
            ]
            .compactMap { $0 }
        )

        var details = [
            entry.localizedTitle(language: language).nonEmpty,
            outletLine,
            yearString(from: entry.date).nonEmpty ?? entry.date.nonEmpty,
            entry.localizedLanguage(language: language).nonEmpty,
            supervisorDetails,
            filteredPublicationData,
            entry.doi.nonEmpty.map { "DOI: \($0)" }
        ]
        .compactMap { $0 }

        if underlineMainSupervisor {
            let names = doctoralSupervisorUnderlineNames(primaryName: entry.mainSupervisor)
            details = details.map { underliningNameVariants(in: $0, fullNames: names) }
        }
        if underlineCoSupervisor {
            let names = doctoralSupervisorUnderlineNames(primaryName: entry.coSupervisor)
            details = details.map { underliningNameVariants(in: $0, fullNames: names) }
        }

        return details.joined(separator: ". ").nonEmpty ?? ""
    }

    private func doctoralSupervisorUnderlineNames(primaryName: String?) -> [String] {
        var seen: Set<String> = []
        return [primaryName].compactMap { $0 }.compactMap { rawName in
            let name = rawName
                .trimmingCharacters(in: .whitespacesAndNewlines)
                .replacingOccurrences(of: "\\s+", with: " ", options: .regularExpression)
            guard !name.isEmpty else { return nil }
            let key = name
                .replacingOccurrences(of: ".", with: "")
                .folding(options: [.caseInsensitive, .diacriticInsensitive], locale: Locale(identifier: "sv_SE"))
            guard !seen.contains(key) else { return nil }
            seen.insert(key)
            return name
        }
    }

    private func doctoralThesisOutletName(
        for entry: CVOtherPublicationEntry,
        language: AppLanguage,
        publicationOptions: PublicationExportOptions
    ) -> String? {
        let fullName = entry.localizedOutlet(language: language).nonEmpty
        let shortName = entry.publisherShortName.nonEmpty

            switch publicationOptions.journalNameMode {
            case .abbreviated:
                return shortName ?? fullName
        case .full:
            return fullName ?? shortName
        }
    }

    private func filteredDoctoralThesisPublicationData(
        for entry: CVOtherPublicationEntry,
        language: AppLanguage,
        explicitDetails: [String]
    ) -> String? {
        let source = entry.localizedPublicationData(language: language).nonEmpty ?? ""
        guard !source.isEmpty else { return nil }

        var explicitSentences = explicitDetails
        if let doi = entry.doi.nonEmpty {
            explicitSentences.append("DOI: \(doi)")
        }

        var cleaned = source
        for explicit in explicitSentences
            .map({ $0.trimmingCharacters(in: .whitespacesAndNewlines) })
            .filter({ !$0.isEmpty })
            .sorted(by: { $0.count > $1.count }) {
            cleaned = removingCaseInsensitiveOccurrences(of: explicit, in: cleaned)
        }

        let remaining = cleaned
            .split(separator: ".")
            .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
            .filter { sentence in
                let normalized = normalizedDoctoralExportSentence(sentence)
                return !normalized.isEmpty && !isDoctoralSupervisorSentence(normalized)
            }
        var seen: Set<String> = []
        let deduplicated = remaining.filter { sentence in
            let normalized = normalizedDoctoralExportSentence(sentence)
            guard !seen.contains(normalized) else { return false }
            seen.insert(normalized)
            return true
        }

        guard !deduplicated.isEmpty else { return nil }
        return deduplicated.joined(separator: ". ")
    }

    private func isDoctoralSupervisorSentence(_ normalizedSentence: String) -> Bool {
        let sentence = normalizedSentence
        return sentence.hasPrefix("main supervisor")
            || sentence.hasPrefix("huvudhandledare")
            || sentence.hasPrefix("co-supervisor")
            || sentence.hasPrefix("co supervisor")
            || sentence.hasPrefix("bihandledare")
    }

    private func normalizedDoctoralExportSentence(_ text: String) -> String {
        text
            .replacingOccurrences(of: "\u{00A0}", with: " ")
            .trimmingCharacters(in: CharacterSet.whitespacesAndNewlines.union(CharacterSet(charactersIn: ".:;,")))
            .replacingOccurrences(of: "\\s+", with: " ", options: .regularExpression)
            .lowercased()
    }

    private func removingCaseInsensitiveOccurrences(of phrase: String, in text: String) -> String {
        guard !phrase.isEmpty else { return text }
        let pattern = NSRegularExpression.escapedPattern(for: phrase)
        guard let regex = try? NSRegularExpression(pattern: pattern, options: [.caseInsensitive]) else {
            return text
        }
        let range = NSRange(text.startIndex..<text.endIndex, in: text)
        return regex.stringByReplacingMatches(in: text, options: [], range: range, withTemplate: "")
    }

    private func underliningNameVariants(in text: String, fullName: String) -> String {
        supervisorUnderlineVariants(for: fullName).reduce(text) { partial, variant in
            partial.replacingOccurrences(of: variant, with: "[[UNDERLINE]]\(variant)[[/UNDERLINE]]")
        }
    }

    private func underliningNameVariants(in text: String, fullNames: [String]) -> String {
        fullNames.reduce(text) { partial, fullName in
            underliningNameVariants(in: partial, fullName: fullName)
        }
    }

    private func supervisorUnderlineVariants(for fullName: String) -> [String] {
        let normalizedFullName = fullName
            .trimmingCharacters(in: .whitespacesAndNewlines)
            .replacingOccurrences(of: "\\s+", with: " ", options: .regularExpression)
        let pieces = normalizedFullName.split(separator: " ").map(String.init)
        guard !pieces.isEmpty else { return [] }
        guard pieces.count > 1, let surname = pieces.last else { return [normalizedFullName] }

        let givenNames = Array(pieces.dropLast())
        let initials = givenNames
            .map { $0.trimmingCharacters(in: CharacterSet(charactersIn: ".")) }
            .compactMap { $0.nonEmpty.map { String($0.prefix(1)) } }
        let compactInitials = initials.joined()
        let spacedInitials = initials.joined(separator: " ")
        let dottedCompactInitials = initials.map { "\($0)." }.joined()
        let dottedSpacedInitials = initials.map { "\($0)." }.joined(separator: " ")
        let fullNameWithoutPeriods = normalizedFullName
            .replacingOccurrences(of: ".", with: "")
            .replacingOccurrences(of: "\\s+", with: " ", options: .regularExpression)
        let fullNameWithDottedLastInitial: String? = {
            guard givenNames.count > 1, let lastInitial = initials.last else { return nil }
            let leadingNames = givenNames
                .dropLast()
                .map { $0.trimmingCharacters(in: CharacterSet(charactersIn: ".")) }
                .filter { !$0.isEmpty }
                .joined(separator: " ")
            guard !leadingNames.isEmpty else { return nil }
            return "\(leadingNames) \(lastInitial). \(surname)"
        }()

        var variants = [
            normalizedFullName,
            fullNameWithoutPeriods,
            fullNameWithDottedLastInitial,
            "\(surname) \(compactInitials)",
            "\(surname) \(spacedInitials)",
            "\(surname), \(compactInitials)",
            "\(surname), \(spacedInitials)",
            "\(surname) \(dottedCompactInitials)",
            "\(surname) \(dottedSpacedInitials)",
            "\(surname), \(dottedCompactInitials)",
            "\(surname), \(dottedSpacedInitials)"
        ]
        .compactMap { $0?.trimmingCharacters(in: .whitespacesAndNewlines) }
        .filter { !$0.isEmpty }

        var seen: Set<String> = []
        variants = variants.filter { variant in
            guard !seen.contains(variant) else { return false }
            seen.insert(variant)
            return true
        }
        return variants.sorted { $0.count > $1.count }
    }

    private func cvEducationLine(for entry: PublicationAuthorEducation, language: AppLanguage? = nil) -> String {
        let targetLanguage = language ?? self.language
        let location = [entry.localizedOrganization(language: targetLanguage).nonEmpty, entry.city.nonEmpty, localizedCountryName(entry.country, language: targetLanguage).nonEmpty]
            .compactMap { $0 }
            .joined(separator: ", ")
        let degree = entry.localizedDegree(language: targetLanguage).nonEmpty
        let period = formattedDateRange(from: entry.from, to: entry.to).nonEmpty
        return [period, degree, location.nonEmpty].compactMap { $0 }.joined(separator: ", ")
    }

    private func cvEmploymentLine(for employment: PublicationAuthorEmployment, language: AppLanguage? = nil) -> String {
        let targetLanguage = language ?? self.language
        let location = [employment.localizedOrganization(language: targetLanguage).nonEmpty, employment.city.nonEmpty, localizedCountryName(employment.country, language: targetLanguage).nonEmpty]
            .compactMap { $0 }
            .joined(separator: ", ")
