    private func cvOwnEmploymentDescription(_ employment: PublicationAuthorEmployment, language: AppLanguage) -> String {
        let workplace = [
            employment.localizedDepartment(language: language).nonEmpty,
            employment.localizedOrganization(language: language).nonEmpty
        ]
        .compactMap { $0 }
        .joined(separator: ", ")
        let location = [employment.city.nonEmpty, localizedCountryName(employment.country, language: language).nonEmpty]
            .compactMap { $0 }
            .joined(separator: ", ")
        let base = [employment.localizedTitle(language: language).nonEmpty, workplace.nonEmpty, location.nonEmpty]
            .compactMap { $0 }
            .joined(separator: ", ")
        if let monthQualifier = ownEmploymentMonthQualifier(employment, language: language) {
            return "\(base) (\(monthQualifier))"
        }
        return base
    }

    private func cvLiUEmploymentDescription(_ employment: PublicationAuthorEmployment, language: AppLanguage) -> String {
        let workplace = [
            employment.localizedDepartment(language: language).nonEmpty,
            employment.localizedOrganization(language: language).nonEmpty
        ]
        .compactMap { $0 }
        .joined(separator: ", ")
        let city = employment.city.nonEmpty
        return [employment.localizedTitle(language: language).nonEmpty, workplace.nonEmpty, city]
            .compactMap { $0 }
            .joined(separator: ", ")
    }

    private func ownEmploymentPeriodLabel(_ employment: PublicationAuthorEmployment) -> String {
        let startYear = yearString(from: employment.from)
        let endYear = yearString(from: employment.to)
        if employment.to.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            return startYear.isEmpty ? "" : "\(startYear) –"
        }
        if shouldHideFutureEndYear(endYear) {
            return startYear.isEmpty ? "" : "\(startYear) –"
        }
        if startYear == endYear {
            return startYear
        }
        return [startYear.nonEmpty, endYear.nonEmpty].compactMap { $0 }.joined(separator: " – ")
    }

    private func ownEmploymentMonthQualifier(_ employment: PublicationAuthorEmployment, language: AppLanguage) -> String? {
        guard
            let start = DateParsers.isoDay.date(from: employment.from),
            let end = DateParsers.isoDay.date(from: employment.to)
        else {
            return nil
        }

        let calendar = Calendar(identifier: .gregorian)
        let startMonthStart = calendar.date(from: calendar.dateComponents([.year, .month], from: start))
        let endMonthStart = calendar.date(from: calendar.dateComponents([.year, .month], from: end))
        guard
            let normalizedStart = startMonthStart,
            let normalizedEnd = endMonthStart,
            let monthDifference = calendar.dateComponents([.month], from: normalizedStart, to: normalizedEnd).month
        else {
            return nil
        }

        let inclusiveMonths = monthDifference + 1
        guard inclusiveMonths < 6 else { return nil }

        let formatter = DateFormatter()
        formatter.locale = Locale(identifier: language == .swedish ? "sv_SE" : "en_US_POSIX")
        formatter.dateFormat = "MMMM"

        let startMonth = formatter.string(from: start)
        let endMonth = formatter.string(from: end)
        let startYear = calendar.component(.year, from: start)
        let endYear = calendar.component(.year, from: end)

        if startYear == endYear {
            if startMonth == endMonth {
                return capitalizedMonthLabel(startMonth)
            }
            return "\(capitalizedMonthLabel(startMonth)) – \(capitalizedMonthLabel(endMonth))"
        }

        return "\(capitalizedMonthLabel(startMonth)) \(startYear) – \(capitalizedMonthLabel(endMonth)) \(endYear)"
    }

    private func capitalizedMonthLabel(_ value: String) -> String {
        guard let first = value.first else { return value }
        return String(first).uppercased() + value.dropFirst()
    }

    private func liuEmploymentPeriodLabel(_ employment: PublicationAuthorEmployment) -> String {
        let startYear = yearString(from: employment.from)
        let endYear = yearString(from: employment.to)
        if employment.to.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            return employment.from
        }
        if shouldHideFutureEndYear(endYear) {
            return startYear.isEmpty ? employment.from : "\(startYear) –"
        }
        if startYear == endYear {
            return startYear
        }
        return [startYear.nonEmpty, endYear.nonEmpty].compactMap { $0 }.joined(separator: " – ")
    }

    private func liuVisitingPeriodLabel(_ employment: PublicationAuthorEmployment) -> String {
        guard
            let start = DateParsers.isoDay.date(from: employment.from),
            let end = DateParsers.isoDay.date(from: employment.to)
        else {
            return liuEmploymentPeriodLabel(employment)
        }
        let monthFormatter = DateFormatter()
        monthFormatter.locale = Locale(identifier: "en_US_POSIX")
        monthFormatter.dateFormat = "MMM"
        let startMonth = monthFormatter.string(from: start)
        let endFormatter = DateFormatter()
        endFormatter.locale = Locale(identifier: "en_US_POSIX")
        endFormatter.dateFormat = "MMM"
        var endMonth = endFormatter.string(from: end)
        if endMonth == "Sep" || endMonth == "Nov" || endMonth == "Oct" {
            endMonth += "."
        }
        let year = yearString(from: employment.to.nonEmpty ?? employment.from)
        return "\(startMonth) - \(endMonth) \(year)"
    }

    private func isVisitingEmployment(_ employment: PublicationAuthorEmployment) -> Bool {
        let haystack = [
            employment.localizedTitle(language: .english),
            employment.localizedTitle(language: .swedish),
            employment.organization,
        ]
        .joined(separator: " ")
        .lowercased()
        return haystack.contains("visit") || haystack.contains("gäst") || haystack.contains("postdoc")
    }

    private func cvEmploymentSortOrder(_ lhs: PublicationAuthorEmployment, _ rhs: PublicationAuthorEmployment) -> Bool {
        let leftDate = DateParsers.isoDay.date(from: lhs.to.nonEmpty ?? lhs.from) ?? .distantPast
        let rightDate = DateParsers.isoDay.date(from: rhs.to.nonEmpty ?? rhs.from) ?? .distantPast
        if leftDate != rightDate {
            return leftDate > rightDate
        }
        return lhs.organization.localizedStandardCompare(rhs.organization) == .orderedAscending
    }

    private func cvEducationSortOrder(_ lhs: PublicationAuthorEducation, _ rhs: PublicationAuthorEducation) -> Bool {
        let leftDate = DateParsers.isoDay.date(from: lhs.to.nonEmpty ?? lhs.from) ?? .distantPast
        let rightDate = DateParsers.isoDay.date(from: rhs.to.nonEmpty ?? rhs.from) ?? .distantPast
        if leftDate != rightDate {
            return leftDate > rightDate
        }
        return lhs.organization.localizedStandardCompare(rhs.organization) == .orderedAscending
    }

    private func numbered(_ lines: [String], startingAt startIndex: Int = 1) -> [String] {
        lines.enumerated().map { index, line in
            "\(startIndex + index).\t\(line)"
        }
    }

    private func cvTeachingPeriodLabel(_ assignment: TeachingAssignment) -> String {
        cvYearOnlyPeriodLabel(
            from: teachingAssignmentFirstDate(assignment),
            to: teachingAssignmentLastDate(assignment)
        )
    }

    private func cvYearOnlyPeriodLabel(from fromText: String, to toText: String) -> String {
        let startYear = yearString(from: fromText)
        let endYear = yearString(from: toText)
        if startYear.isEmpty && endYear.isEmpty { return "" }
        if toText.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            return startYear.isEmpty ? "" : "\(startYear) –"
        }
        if shouldHideFutureEndYear(endYear) {
            return startYear.isEmpty ? "" : "\(startYear) –"
        }
        if startYear == endYear || endYear.isEmpty {
            return startYear.nonEmpty ?? endYear
        }
        return [startYear.nonEmpty, endYear.nonEmpty].compactMap { $0 }.joined(separator: " – ")
    }

    private func shouldHideFutureEndYear(_ yearText: String) -> Bool {
        guard
            let year = Int(yearText),
            let currentYear = Calendar(identifier: .gregorian).dateComponents([.year], from: Date()).year
        else {
            return false
        }
        return year > currentYear
    }

    private func yearString(from value: String) -> String {
        guard let year = yearComponent(from: value) else { return "" }
        return String(year)
    }

    private func ownConferenceDateLabel(from fromText: String, to toText: String, language: AppLanguage = .english) -> String {
        guard
            let start = DateParsers.isoDay.date(from: fromText),
            let end = DateParsers.isoDay.date(from: toText)
        else {
            return fromText
        }
        let monthFormatter = DateFormatter()
        monthFormatter.locale = Locale(identifier: language == .swedish ? "sv_SE" : "en_US_POSIX")
        monthFormatter.dateFormat = "MMMM"
        let startMonth = monthFormatter.string(from: start)
        let endMonth = monthFormatter.string(from: end)
        let calendar = Calendar(identifier: .gregorian)
        let startDay = calendar.component(.day, from: start)
        let endDay = calendar.component(.day, from: end)
        let year = calendar.component(.year, from: end)
        if startMonth == endMonth {
            return "\(startMonth) \(startDay)–\(endDay), \(year)"
        }
        return "\(startMonth) \(startDay) – \(endMonth) \(endDay), \(year)"
    }

    private func isPeerReviewedPublishedPublication(_ publication: PublicationRecord) -> Bool {
        PublicationStatus.fromStored(publication.statusLabel) == .published && publication.isPeerReviewed
    }

    private func localizedCountryName(_ country: String, language: AppLanguage? = nil) -> String {
        let trimmed = country.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return "" }
        let targetLanguage = language ?? self.language
        let cacheKey = "\(targetLanguage.rawValue)|\(trimmed)"
        if let cached = localizedCountryNameCache[cacheKey] {
            return cached
        }
        let englishLocale = Locale(identifier: "en_US")
        let swedishLocale = Locale(identifier: "sv_SE")
        let normalizedInput = trimmed
            .folding(options: [.diacriticInsensitive, .caseInsensitive], locale: Locale(identifier: "sv_SE"))
            .trimmingCharacters(in: .whitespacesAndNewlines)

        if let region = GrantParsing.countryRegions.first(where: {
            let codeMatch = $0.identifier.caseInsensitiveCompare(trimmed) == .orderedSame
            let englishMatch = (englishLocale.localizedString(forRegionCode: $0.identifier) ?? "")
                .folding(options: [.diacriticInsensitive, .caseInsensitive], locale: englishLocale)
                .trimmingCharacters(in: .whitespacesAndNewlines) == normalizedInput
            let swedishMatch = (swedishLocale.localizedString(forRegionCode: $0.identifier) ?? "")
                .folding(options: [.diacriticInsensitive, .caseInsensitive], locale: swedishLocale)
                .trimmingCharacters(in: .whitespacesAndNewlines) == normalizedInput
            return codeMatch || englishMatch || swedishMatch
        }) {
            let localized = targetLanguage.localizedCountry(englishLocale.localizedString(forRegionCode: region.identifier) ?? trimmed)
            localizedCountryNameCache[cacheKey] = localized
            return localized
        }
        localizedCountryNameCache[cacheKey] = trimmed
        return trimmed
    }

    private func liuPersonalNumber(from birthDate: String) -> String {
        birthDate.replacingOccurrences(of: "-", with: "")
    }

    private func cvLiUHomeContactItems(for author: PublicationAuthor?, language: AppLanguage) -> [String] {
        guard let author else { return [] }
        var items: [String] = []
        if let address = author.localizedHomeAddress(language: language).nonEmpty {
            items.append(address)
        }
        if let phone = author.phoneNumber.nonEmpty {
            items.append((author.phoneLabel.nonEmpty ?? cvText(language, english: "Phone", swedish: "Telefon")) + ": " + phone)
        }
        if let phone = author.phoneNumberSecondary.nonEmpty {
            items.append((author.phoneLabelSecondary.nonEmpty ?? cvText(language, english: "Phone 2", swedish: "Telefon 2")) + ": " + phone)
        }
        return items
    }

    private func cvLiUWorkContactItems(for author: PublicationAuthor?, language: AppLanguage) -> [String] {
        guard let author else { return [] }
        let address = firstAffiliationAddress(for: author, language: language)
        return [address.nonEmpty].compactMap { $0 }
    }

    private func firstAffiliationAddress(for author: PublicationAuthor?, language: AppLanguage) -> String {
        guard let affiliation = author?.primaryAffiliation else { return "" }
        let organization = linkedOrganization(id: affiliation.organizationID, name: affiliation.organization)
        let postalAndCity = [
            organization?.postalCode.nonEmpty,
            affiliation.city.nonEmpty
        ]
        .compactMap { $0 }
        .joined(separator: " ")
        return [
            affiliation.localizedDepartment(language: language).nonEmpty,
            affiliation.localizedOrganization(language: language).nonEmpty,
            organization?.addressLine.nonEmpty,
            postalAndCity.nonEmpty,
            localizedCountryName(affiliation.country, language: language).nonEmpty
        ]
        .compactMap { $0 }
        .joined(separator: ", ")
    }

    private func formattedDateRange(from: String, to: String) -> String {
        let start = from.trimmingCharacters(in: .whitespacesAndNewlines)
        let end = to.trimmingCharacters(in: .whitespacesAndNewlines)
        if start.isEmpty && end.isEmpty {
            return ""
        }
        if end.isEmpty {
            return "\(start) –"
        }
        if start.isEmpty {
            return end
        }
        if start == end {
            return start
        }
        return "\(start) – \(end)"
    }

    private func localizedEducationLevel(_ level: PublicationAuthorEducationLevel?) -> String {
        guard let level else { return "" }
        switch level {
        case .basicEducation:
            return language.text("Basic education", "Grundutbildning")
        case .standaloneCourse:
            return language.text("Standalone course", "Fristående kurs")
        case .bachelor:
            return language.text("Bachelor", "Kandidat")
        case .master:
            return language.text("Master", "Magister")
        case .doctoral:
            return language.text("Doctoral education", "Forskarutbildning")
        case .other:
            return language.text("Other", "Övrigt")
        }
    }

    private struct TeachingMeritsTermKey: Hashable {
        let year: Int
        let half: Int

        var sortValue: Int { year * 10 + half }
    }

    private struct TeachingMeritsTermSlice {
        let label: String
        let hoursText: String
        let hoursValue: Double
        let sortValue: Int
    }

    private func teachingMeritsPeriodTable(title: String, category: TeachingReportCategory, headers: [String]) -> TeachingMeritsExportTable {
        let assignments = teachingAssignmentsForTeachingMerits(category: category)
        let rows = assignments.flatMap { assignment in
            assignment.periods
                .filter { !$0.isEmpty }
                .sorted(by: teachingPeriodSortOrder)
                .reversed()
                .flatMap { period in
                    let context = teachingCourses.first(where: { $0.id == assignment.contextID })
                    return teachingMeritsTermSlices(for: period).map { term in
                        [
                            term.label,
                            term.hoursText,
                            teachingMeritsCourseActivityCreditsLabel(context: context, assignment: assignment),
                            organizationLabel(forCourse: context, language: language),
                            teachingMeritsLanguageLabel(context?.teachingLanguage ?? ""),
                            assignment.roles.map { localizedTeachingAssignmentRole($0) }.joined(separator: ", "),
                            teachingMeritsTeachingFormatLabel(assignment)
                        ]
                    }
                }
        }
        let total = assignments.reduce(0) { $0 + teachingMeritsAssignmentTotalHoursValue($1) }
        return TeachingMeritsExportTable(
            title: title,
            headers: headers,
            rows: rows,
            sumLabel: "Summa:",
            sumValue: formattedTeachingMeritsHours(total)
        )
    }

    private func teachingMeritsCourseActivityCreditsLabel(context: TeachingCourse?, assignment: TeachingAssignment) -> String {
        let courseName = context?.localizedName(language: language).nonEmpty
        let activityTitle = teachingMeritsActivityTitle(assignment)
        let credits = teachingMeritsCreditsLabel(context?.credits ?? "")
        return uniqueTeachingMeritsParts([courseName, activityTitle, credits]).joined(separator: ", ")
    }

    private func teachingMeritsCourseAdministrationContextLabel(context: TeachingCourse?, assignment: TeachingAssignment) -> String {
        let courseName = context?.localizedName(language: language).nonEmpty
        let program = assignment.programName.nonEmpty ?? context?.localizedProgram(language: language).nonEmpty
        return uniqueTeachingMeritsParts([courseName, program]).joined(separator: ", ")
    }

    private func teachingMeritsProgramCourseLabel(context: TeachingCourse?, assignment: TeachingAssignment) -> String {
        let program = assignment.programName.nonEmpty ?? context?.localizedProgram(language: language).nonEmpty
        let courseName = context?.localizedName(language: language).nonEmpty
        return uniqueTeachingMeritsParts([program, courseName]).joined(separator: ", ")
    }

    private func teachingMeritsActivityTitle(_ assignment: TeachingAssignment) -> String? {
        let title = teachingComponent(for: assignment)?.localizedName(language: language).nonEmpty
            ?? assignment.activityName.nonEmpty
        let format = teachingMeritsTeachingFormatLabel(assignment).nonEmpty
        if normalizedTeachingExportText(title) == normalizedTeachingExportText(format) {
            return nil
        }
        return title
    }

    private func teachingMeritsCreditsLabel(_ value: String) -> String? {
        guard let trimmed = value.trimmedOrNil else { return nil }
        let normalized = normalizedTeachingExportText(trimmed)
        if normalized.contains("hp") || normalized.contains("ects") || normalized.contains("credit") {
            return trimmed
        }
        return "\(trimmed) hp"
    }

    private func teachingMeritsTeachingFormatLabel(_ assignment: TeachingAssignment) -> String {
        let rawFormat = localizedTeachingFormatName(effectiveTeachingActivityTypeName(assignment)).trimmingCharacters(in: .whitespacesAndNewlines)
        switch normalizedTeachingExportText(rawFormat) {
        case "doktorandhandledning", "handledning doktorandarbete", "doctoral supervision":
            return fixedDropdownText("teachingDefaultFormat.supervision", language: language, english: "Supervision", swedish: "Handledning")
        default:
            return rawFormat
        }
    }

    private func uniqueTeachingMeritsParts(_ parts: [String?]) -> [String] {
        var seen: Set<String> = []
        var result: [String] = []
        for part in parts {
            guard let value = part?.trimmedOrNil else { continue }
            let normalized = normalizedTeachingExportText(value)
            guard !seen.contains(normalized) else { continue }
            seen.insert(normalized)
            result.append(value)
        }
        return result
    }

    private func teachingMeritsAssignmentTermSlices(_ assignment: TeachingAssignment) -> [TeachingMeritsTermSlice] {
        assignment.periods
            .filter { !$0.isEmpty }
            .sorted(by: teachingPeriodSortOrder)
            .reversed()
            .flatMap { teachingMeritsTermSlices(for: $0) }
    }

    private func teachingMeritsTermSlices(for period: TeachingAssignmentPeriod) -> [TeachingMeritsTermSlice] {
        let hoursText = period.hoursPerTerm.trimmingCharacters(in: .whitespacesAndNewlines)
        let hoursValue = GrantParsing.numericValue(from: hoursText) ?? 0
        let keys = teachingMeritsTermKeys(from: period.from, to: period.to)

        guard !keys.isEmpty else {
            return [
                TeachingMeritsTermSlice(
                    label: "",
                    hoursText: hoursText,
                    hoursValue: hoursValue,
                    sortValue: 0
                )
            ]
        }

        return keys
            .sorted { $0.sortValue > $1.sortValue }
            .map {
                TeachingMeritsTermSlice(
                    label: teachingMeritsTermLabel($0),
                    hoursText: hoursText,
                    hoursValue: hoursValue,
                    sortValue: $0.sortValue
                )
            }
    }

    private func teachingMeritsTermKeys(from rawFrom: String, to rawTo: String) -> [TeachingMeritsTermKey] {
        let fromDate = rawFrom.nonEmpty.flatMap(DateParsers.isoDay.date(from:))
        let toDate = rawTo.nonEmpty.flatMap(DateParsers.isoDay.date(from:))

        guard let start = fromDate ?? toDate else { return [] }
        let end = toDate ?? fromDate ?? start
        let lower = min(start, end)
        let upper = max(start, end)
        var cursor = lower
        var keys: Set<TeachingMeritsTermKey> = []

        while cursor <= upper {
            keys.insert(teachingMeritsTermKey(for: cursor))
            guard let nextMonth = Calendar.current.date(byAdding: .month, value: 1, to: cursor) else { break }
            cursor = nextMonth
        }

        keys.insert(teachingMeritsTermKey(for: upper))
        return Array(keys)
    }

    private func teachingMeritsTermKey(for date: Date) -> TeachingMeritsTermKey {
        let calendar = Calendar.current
        let year = calendar.component(.year, from: date)
        let month = calendar.component(.month, from: date)
        return TeachingMeritsTermKey(year: year, half: month <= 6 ? 1 : 2)
    }

    private func teachingMeritsTermLabel(_ key: TeachingMeritsTermKey) -> String {
        "\(key.half == 1 ? "VT" : "HT") \(key.year)"
    }

    private func teachingMeritsAssignmentTable(
        title: String,
        category: TeachingReportCategory,
        headers: [String],
        referenceDate: Date = Date()
    ) -> TeachingMeritsExportTable {
        let assignments = teachingAssignmentsForTeachingMerits(category: category)
        let assignmentRows = assignments.flatMap { assignment -> [[String]] in
            let context = teachingCourses.first(where: { $0.id == assignment.contextID })
            let termSlices = teachingMeritsAssignmentTermSlices(assignment)
            switch category {
            case .thesisSupervision:
                return termSlices.map { term in
                    [
                        term.label,
                        term.hoursText,
                        context?.credits ?? "",
                        organizationLabel(forCourse: context, language: language),
                        teachingMeritsProgramCourseLabel(context: context, assignment: assignment),
                        assignment.studentName
                    ]
                }
            case .doctoralPrincipalSupervision, .doctoralAssistantSupervision:
                return []
            case .courseAdministration:
                return termSlices.map { term in
                    [
                        term.label,
                        term.hoursText,
                        "",
                        teachingMeritsAdministrationDescription(assignment),
                        organizationLabel(forCourse: context, language: language),
                        teachingMeritsCourseAdministrationContextLabel(context: context, assignment: assignment)
                    ]
                }
            case .otherPedagogicalWork:
                return termSlices.map { term in
                    [
                        term.label,
                        term.hoursText,
                        assignment.activityName,
                        organizationLabel(forCourse: context, language: language),
                        context?.localizedName(language: language) ?? "",
                        assignment.comment
                    ]
                }
            default:
                return []
            }
        }
        let doctoralRows = teachingMeritsDoctoralCandidateRows(for: category, referenceDate: referenceDate)
        let rows = assignmentRows + doctoralRows
        let total = assignments.reduce(0) { $0 + teachingMeritsAssignmentTotalHoursValue($1) }
            + teachingMeritsDoctoralCandidateTotalHours(for: category, referenceDate: referenceDate)
        return TeachingMeritsExportTable(
            title: title,
            headers: headers,
            rows: rows,
            sumLabel: "Summa:",
            sumValue: formattedTeachingMeritsHours(total)
        )
    }

    /// The supervision hours so far for the teaching merits export: each period's
    /// hours per term times the terms from its start to its end date (or today).
    private func doctoralCandidateTotalHours(_ candidate: DoctoralCandidateRecord, referenceDate: Date) -> Double {
        candidate.accruedSupervisionHours(referenceDate: referenceDate) ?? 0
    }

    /// The hours cell for a doctoral candidate in the teaching merits export.
    /// Empty only when no hours per term are entered on any period.
    func teachingMeritsDoctoralCandidateHoursCell(
        _ candidate: DoctoralCandidateRecord,
        referenceDate: Date = Date()
    ) -> String {
        guard let hours = candidate.accruedSupervisionHours(referenceDate: referenceDate) else { return "" }
        return formattedTeachingMeritsHours(hours)
    }

    private func teachingMeritsDoctoralCandidateRows(
        for category: TeachingReportCategory,
        referenceDate: Date
    ) -> [[String]] {
        doctoralCandidatesForTeachingMerits(category: category).map { candidate in
            [
                teachingMeritsDoctoralCandidateExamYearLabel(candidate),
                teachingMeritsDoctoralCandidateHoursCell(candidate, referenceDate: referenceDate),
                "",
                teachingMeritsDoctoralCandidateStageLabel(candidate),
                organizationLabel(for: candidate, language: language),
                candidate.candidateName
            ]
        }
    }

    private func teachingMeritsDoctoralCandidateTotalHours(for category: TeachingReportCategory, referenceDate: Date = Date()) -> Double {
        doctoralCandidatesForTeachingMerits(category: category).reduce(0.0) { partial, candidate in
            partial + doctoralCandidateTotalHours(candidate, referenceDate: referenceDate)
        }
    }

    private func doctoralCandidatesForTeachingMerits(category: TeachingReportCategory) -> [DoctoralCandidateRecord] {
        switch category {
        case .doctoralPrincipalSupervision:
            return doctoralCandidates.filter(teachingMeritsCurrentUserIsPrincipalSupervisor)
        case .doctoralAssistantSupervision:
            return doctoralCandidates.filter(teachingMeritsCurrentUserIsAssistantSupervisor)
        default:
            return []
        }
    }

    private func teachingMeritsCurrentUserIsPrincipalSupervisor(_ candidate: DoctoralCandidateRecord) -> Bool {
        guard let first = candidate.supervisors.first else { return false }
        let currentUser = currentUserAuthor()
        let normalizedCurrentUserName = currentUser.map { PublicationDerivation.normalizedName($0.name) }
        // "Alla kopplingar via id": a linked supervisor is decided by the link;
        // the written name only for a supervisor without one.
        if let firstAuthorID = first.authorID?.trimmedOrNil {
            return firstAuthorID == currentUser?.id
        }
        if let normalizedCurrentUserName {
            return PublicationDerivation.normalizedName(first.name) == normalizedCurrentUserName
        }
        return false
    }

    private func teachingMeritsCurrentUserIsAssistantSupervisor(_ candidate: DoctoralCandidateRecord) -> Bool {
        let currentUser = currentUserAuthor()
        let normalizedCurrentUserName = currentUser.map { PublicationDerivation.normalizedName($0.name) }
        return !teachingMeritsCurrentUserIsPrincipalSupervisor(candidate)
            && doctoralCandidateIncludesCurrentUser(
                candidate,
                currentUserID: currentUser?.id,
                normalizedCurrentUserName: normalizedCurrentUserName
            )
    }

    private func teachingMeritsDoctoralCandidateExamYearLabel(_ candidate: DoctoralCandidateRecord) -> String {
        let source = candidate.plannedDisputationDate.nonEmpty
            ?? candidate.halftimeDate.nonEmpty
            ?? candidate.planningSeminarDate.nonEmpty
            ?? candidate.admissionDate.nonEmpty
            ?? ""
        return String(source.prefix(4))
    }

    private func teachingMeritsDoctoralCandidateStageLabel(_ candidate: DoctoralCandidateRecord) -> String {
        guard let admissionDate = candidate.admissionDate.nonEmpty.flatMap(DateParsers.isoDay.date(from:)),
              let supervisionStartDate = teachingMeritsDoctoralCandidateSupervisionStartDate(candidate) else {
            return teachingMeritsDoctoralCandidateFallbackStageLabel(candidate)
        }

        var label: String
        if Calendar.current.isDate(admissionDate, inSameDayAs: supervisionStartDate) {
            label = "Från antagning"
        } else {
            label = teachingMeritsDoctoralCandidateStartOffsetLabel(from: admissionDate, to: supervisionStartDate)
        }

        if let halftimeDate = candidate.halftimeDate.nonEmpty.flatMap(DateParsers.isoDay.date(from:)) {
            label += supervisionStartDate <= halftimeDate ? ", innan halvtid" : ", efter halvtid"
        }
        return label
    }

    private func teachingMeritsDoctoralCandidateFallbackStageLabel(_ candidate: DoctoralCandidateRecord) -> String {
        let hasAdmission = candidate.admissionDate.nonEmpty != nil
        let hasPlanning = candidate.planningSeminarDate.nonEmpty != nil
        let hasHalftime = candidate.halftimeDate.nonEmpty != nil
        let hasDisputation = candidate.plannedDisputationDate.nonEmpty != nil

        if hasAdmission && hasDisputation { return "Antagning till examen" }
        if hasPlanning && hasDisputation { return "Planeringsseminarium till examen" }
        if hasHalftime && hasDisputation { return "Halvtid till examen" }
        if hasAdmission && hasHalftime { return "Antagning till halvtid" }
        if hasAdmission && hasPlanning { return "Antagning till planeringsseminarium" }
        if hasPlanning && hasHalftime { return "Planeringsseminarium till halvtid" }
        if hasAdmission { return "Antagning" }
        if hasPlanning { return "Planeringsseminarium" }
        if hasHalftime { return "Halvtid" }
        if hasDisputation { return "Examen" }
        return ""
    }

    private func teachingMeritsDoctoralCandidateSupervisionStartDate(_ candidate: DoctoralCandidateRecord) -> Date? {
        candidate.supervisionPeriods
            .compactMap { period in
                period.from.nonEmpty.flatMap(DateParsers.isoDay.date(from:))
                    ?? period.to.nonEmpty.flatMap(DateParsers.isoDay.date(from:))
            }
            .min()
    }

    private func teachingMeritsDoctoralCandidateStartOffsetLabel(from admissionDate: Date, to supervisionStartDate: Date) -> String {
        let calendar = Calendar.current
        let lower = min(admissionDate, supervisionStartDate)
        let upper = max(admissionDate, supervisionStartDate)
        let components = calendar.dateComponents([.year, .month], from: lower, to: upper)
        let years = max(0, components.year ?? 0)
        let months = max(0, components.month ?? 0)

        if years == 0 && months < 6 {
            return "Från mindre än ett halvår in på studierna"
        }
        if months >= 6 {
            return "Från nästan \(years + 1) år in på studierna"
        }
        return "Från drygt \(years) år in på studierna"
    }

    private func doctoralCandidateIncludesCurrentUser(
        _ candidate: DoctoralCandidateRecord,
        currentUserID: String?,
        normalizedCurrentUserName: String?
    ) -> Bool {
        let nameKeys = normalizedCurrentUserName.map { Set([$0]) } ?? []
        return doctoralCandidateIncludesCurrentUser(
            candidate,
            currentUserID: currentUserID,
            normalizedCurrentUserNameKeys: nameKeys
        )
    }

    private func doctoralCandidateIncludesCurrentUser(
        _ candidate: DoctoralCandidateRecord,
        currentUserID: String?,
        normalizedCurrentUserNameKeys: Set<String>
    ) -> Bool {
        candidate.supervisors.contains { supervisor in
            if let currentUserID, supervisor.authorID == currentUserID {
                return true
            }
            let supervisorNameKey = PublicationDerivation.normalizedName(supervisor.name)
            return !supervisorNameKey.isEmpty && normalizedCurrentUserNameKeys.contains(supervisorNameKey)
        }
    }

    private func localizedDoctoralCandidateCurrentUserRoleLabel(
        _ candidate: DoctoralCandidateRecord,
        language: AppLanguage? = nil
    ) -> String {
        let targetLanguage = language ?? self.language
        guard !candidate.supervisors.isEmpty else {
            return cvText(targetLanguage, english: "Supervisor", swedish: "Handledare")
        }
        let currentUser = currentUserAuthor()
        let normalizedCurrentUserName = currentUser.map { PublicationDerivation.normalizedName($0.name) }
        let first = candidate.supervisors.first
        // "Alla kopplingar via id": the link decides; the name only without one.
        let firstIsCurrentUser: Bool
        if let firstAuthorID = first?.authorID?.trimmedOrNil {
            firstIsCurrentUser = firstAuthorID == currentUser?.id
        } else {
            firstIsCurrentUser = normalizedCurrentUserName != nil
                && PublicationDerivation.normalizedName(first?.name ?? "") == normalizedCurrentUserName
        }
        if currentUser != nil, firstIsCurrentUser {
            return cvText(targetLanguage, english: "Principal supervisor", swedish: "Huvudhandledare")
        }
        let containsCurrentUser = doctoralCandidateIncludesCurrentUser(
            candidate,
            currentUserID: currentUser?.id,
            normalizedCurrentUserName: normalizedCurrentUserName
        )
        if containsCurrentUser {
            return cvText(targetLanguage, english: "Co-supervisor", swedish: "Bihandledare")
        }
        return cvText(targetLanguage, english: "Supervisor", swedish: "Handledare")
    }

    private func doctoralCandidateCurrentUserRoleLabel(_ candidate: DoctoralCandidateRecord) -> String {
        localizedDoctoralCandidateCurrentUserRoleLabel(candidate, language: .swedish)
    }

    private func doctoralCandidateRetendoLabel(_ candidate: DoctoralCandidateRecord) -> String {
        let periods = candidate.supervisionPeriods.filter { !$0.isEmpty }
        guard !periods.isEmpty else { return "" }
        let confirmedCount = periods.filter(\.confirmedInRetendo).count
        if confirmedCount == periods.count {
            return "Ja"
        }
        if confirmedCount > 0 {
            return "Delvis"
        }
        return "Nej"
    }

