    private func statisticsWorkbookSheets() -> [WorkbookExportSheet] {
        // Round 12: the user's own grants as main applicant (as the default
        // elsewhere), not every grant in the app.
        let applications = self.applications.filter { isCurrentUserFirstApplicant($0) }
        let grantYears = Array(Set(applications.map(\.statsYear))).sorted()
        let grantRows = [[
            language.text("Year", "År"),
            ApplicationOutcome.granted.heading(language),
            ApplicationOutcome.awaitingDecision.heading(language),
            ApplicationOutcome.declined.heading(language),
            language.text("Granted sum (kSEK)", "Summa beviljat (tkr)"),
        ]] + grantYears.map { year in
            let awarded = applications.filter { $0.statsYear == year && $0.resultLabel == "Beviljat" }
            let pending = applications.filter { $0.statsYear == year && $0.resultLabel == "Väntar svar" }
            let declined = applications.filter { $0.statsYear == year && $0.resultLabel == "Avslag" }
            return [
                year,
                "\(awarded.count)",
                "\(pending.count)",
                "\(declined.count)",
                "\(Int((awarded.reduce(0) { $0 + grantStatisticsAmountInSEK(for: $1, amount: $1.grantedAmountValue) } / 1000).rounded()))",
            ]
        }

        // Round 12: the user's own publications, and the citations each year
        // to all of them (before, only citations to papers from the same year
        // counted, which is almost none).
        let ownPublications = currentUserPublications()
        let ownCitationEntries = ownPublications.flatMap(\.citationYears)
        let publicationYears = Array(Set(
            ownPublications.compactMap { $0.year.nonEmpty } + ownCitationEntries.compactMap { $0.year.nonEmpty }
        )).sorted()
        let publicationRows = [[
            language.text("Year", "År"),
            language.text("Original", "Original"),
            language.text("Review articles", "Översiktsartiklar"),
            language.text("Others", "Övrigt"),
            language.text("External citations", "Externa citeringar"),
            language.text("Self-citations", "Självciteringar"),
            language.text("Total citations", "Citeringar totalt"),
        ]] + publicationYears.map { year in
            let publicationsForYear = ownPublications.filter { $0.year == year && $0.isPublished && $0.isPeerReviewed }
            let citationEntriesForYear = ownCitationEntries.filter { $0.year == year }
            let externalCitations = citationEntriesForYear.map(\.countValue).reduce(0, +)
            let selfCitations = citationEntriesForYear.map(\.selfCitationCountValue).reduce(0, +)
            return [
                year,
                "\(publicationsForYear.filter { publicationTypeBucket(for: $0) == "original" }.count)",
                "\(publicationsForYear.filter { publicationTypeBucket(for: $0) == "review" }.count)",
                "\(publicationsForYear.filter { publicationTypeBucket(for: $0) == "other" }.count)",
                "\(externalCitations)",
                "\(selfCitations)",
                "\(externalCitations + selfCitations)",
            ]
        }

        return [
            WorkbookExportSheet(name: language.text("Grant statistics", "Anslagsstatistik"), rows: grantRows),
            WorkbookExportSheet(name: language.text("Publication statistics", "Publikationsstatistik"), rows: publicationRows),
        ]
    }

