    private func homeTaskWorkbookRows() -> [[String]] {
        let headers = [[
            language.text("Task", "Uppgift"),
            language.text("Source", "Källa"),
            language.text("Deadline", "Tidsfrist"),
            language.text("Reminder", "Påminn när"),
        ]]

        // Central tasks are the source of truth; superseded legacy copies
        // are skipped so rescheduled tasks export once, with current data.
        let centralIDs = Set(taskItems.map(\.id))
        let projectTasks = projects.flatMap { project in
            project.projectTasks
                .filter { !$0.isEmpty && !centralIDs.contains($0.id) }
                .map { [$0.comment, project.nameSv, $0.deadline, localizedProjectTaskReminder($0.reminder)] }
        }
        let publicationTasks = publicationRecords.flatMap { publication in
            publication.publicationTasks
                .filter { !$0.isEmpty && !centralIDs.contains($0.id) }
                .map { [$0.comment, publication.title, $0.deadline, ""] }
        }
        let teachingTasks = teachingWorkspaceTasks
            .filter { !$0.isEmpty && !centralIDs.contains($0.id) }
            .map { [$0.comment, language.text("Teaching", "Undervisning"), $0.deadline, ""] }
        let centralTasks = taskItems
            .filter { !$0.isEmpty }
            .map { task in
                let context = task.links
                    .first(where: { $0.kind == .project })
                    .flatMap { link in projects.first(where: { $0.id == link.targetID })?.nameSv }
                    ?? language.text("General", "Allmänt")
                return [task.comment, context, task.deadline, localizedProjectTaskReminder(task.reminder)]
            }
        return headers + projectTasks + publicationTasks + teachingTasks + centralTasks
    }

