    private func teachingFormat(named name: String) -> TeachingFormatOption? {
        let trimmed = name.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return nil }
        return teachingFormats.first(where: { $0.nameSv == trimmed || $0.nameEn == trimmed })
    }

    /// F13: a teaching moment's organization and format by id. The id decides;
    /// the stored names are rewritten from it, so a rename follows through.
    /// A name that matches nothing stays as text with no id.
    private func synchronizedTeachingComponentRelations(_ component: TeachingComponent) -> TeachingComponent {
        var resolved = component
        if let organization = resolvedOrganization(id: resolved.institutionID, name: resolved.institution) {
            resolved.institutionID = organization.id
            resolved.institution = organization.nameSv
        } else {
            resolved.institutionID = nil
        }
        if let format = teachingFormat(id: resolved.activityTypeID) ?? teachingFormat(named: resolved.activityTypeName) {
            resolved.activityTypeID = format.id
            resolved.activityTypeName = format.name
        } else {
            resolved.activityTypeID = nil
        }
        return resolved
    }

    /// "Alla kopplingar via id": the same rule for a course's institution. When
    /// the institution text was edited but the link was not, the person wrote
    /// another organization, so the link is found again from the new text.
    private func clearingStaleTeachingReferenceIDs(
        _ updated: TeachingCourse,
        previous: TeachingCourse
    ) -> TeachingCourse {
        var result = updated
        if result.institutionID == previous.institutionID,
           result.institution.trimmingCharacters(in: .whitespacesAndNewlines)
            != previous.institution.trimmingCharacters(in: .whitespacesAndNewlines) {
            result.institutionID = nil
        }
        return result
    }

    /// F13: when an edit changes a name but keeps the old id, the person picked
    /// something else by name, so the id is dropped and found again from the name.
    private func clearingStaleTeachingReferenceIDs(
        _ updated: TeachingComponent,
        previous: TeachingComponent
    ) -> TeachingComponent {
        var result = updated
        if result.institutionID == previous.institutionID, result.institution != previous.institution {
            result.institutionID = nil
        }
        if result.activityTypeID == previous.activityTypeID, result.activityTypeName != previous.activityTypeName {
            result.activityTypeID = nil
        }
        return result
    }

    private func clearingStaleTeachingReferenceIDs(
        _ updated: TeachingAssignment,
        previous: TeachingAssignment
    ) -> TeachingAssignment {
        var result = updated
        if result.activityTypeID == previous.activityTypeID, result.activityTypeName != previous.activityTypeName {
            result.activityTypeID = nil
        }
        if result.studentAuthorID == previous.studentAuthorID, result.studentName != previous.studentName {
            result.studentAuthorID = nil
        }
        return result
    }

    /// F13: an assignment's format and student by id, and its programme from its course.
    private func synchronizeTeachingAssignmentReferences(_ assignment: inout TeachingAssignment) {
        if let format = teachingFormat(id: assignment.activityTypeID) ?? teachingFormat(named: assignment.activityTypeName) {
            assignment.activityTypeID = format.id
            assignment.activityTypeName = format.name
        } else {
            assignment.activityTypeID = nil
        }

        let student = publicationAuthor(id: assignment.studentAuthorID)
            ?? assignment.studentName.nonEmpty.flatMap { publicationAuthor(matchingPresentedName: $0) }
        if let student {
            assignment.studentAuthorID = student.id
            // Keep the form of the name that was written, as long as it is still
            // one of the researcher's names; after a rename it no longer is.
            let written = normalizedPersonLookupName(assignment.studentName)
            if written.isEmpty || !student.presentedNameCandidates.map(normalizedPersonLookupName).contains(written) {
                assignment.studentName = student.name
            }
        } else {
            assignment.studentAuthorID = nil
        }

        if let context = teachingCourses.first(where: { $0.id == assignment.contextID }),
           let programme = context.programSv.nonEmpty ?? context.programEn.nonEmpty {
            assignment.programName = programme
        }
    }

