    private func teachingAssignmentStatusKind(_ assignment: TeachingAssignment) -> TeachingAssignmentStatusKind {
        let relevantPeriods = assignment.periods.filter { !$0.isEmpty }
        guard !relevantPeriods.isEmpty else { return .none }

        let today = Calendar.current.startOfDay(for: Date())
        for period in relevantPeriods {
            guard let startDate = period.from.nonEmpty.flatMap(DateParsers.isoDay.date(from:)) else { continue }
            let endDate = period.to.nonEmpty.flatMap(DateParsers.isoDay.date(from:))
            if startDate <= today && endDate.map({ $0 >= today }) ?? true {
                return .ongoing
            }
            if startDate > today {
                return .ongoing
            }
            if endDate == nil {
                return .ongoing
            }
        }
        return .completed
    }

    private func teachingAssignmentTermCount(_ assignment: TeachingAssignment) -> Int {
        var terms = Set<String>()
        let relevantPeriods = assignment.periods.filter { !$0.isEmpty }
        guard !relevantPeriods.isEmpty else { return 0 }

        for period in relevantPeriods {
            guard let startDate = period.from.nonEmpty.flatMap(DateParsers.isoDay.date(from:)) else { continue }
            let endDate = period.to.nonEmpty.flatMap(DateParsers.isoDay.date(from:)) ?? Calendar.current.startOfDay(for: Date())
            collectTerms(from: startDate, to: endDate, into: &terms)
        }
        return terms.count
    }

    private func teachingAssignmentHoursSummary(_ assignment: TeachingAssignment) -> String {
        let relevantPeriods = assignment.periods.filter { !$0.isEmpty }
        guard !relevantPeriods.isEmpty else { return "" }

        let distinctHours = Array(NSOrderedSet(array: relevantPeriods.compactMap(\.hoursPerTerm.nonEmpty))) as? [String] ?? []
        if distinctHours.count == 1 {
            return distinctHours.first ?? ""
        }

        return relevantPeriods.compactMap { period in
            guard let hours = period.hoursPerTerm.nonEmpty else { return nil }
            let from = period.from.nonEmpty ?? "?"
            let to = period.to.nonEmpty ?? "?"
            return "\(from)–\(to): \(hours)"
        }
        .joined(separator: "; ")
    }

    private func teachingAssignmentFirstDate(_ assignment: TeachingAssignment) -> String {
        let dates = assignment.periods.compactMap { $0.from.nonEmpty }
        return dates.sorted().first ?? ""
    }

    private func teachingAssignmentLastDate(_ assignment: TeachingAssignment) -> String {
        let dates = assignment.periods.compactMap { $0.to.nonEmpty }
        return dates.sorted().last ?? ""
    }

    private func teachingAssignmentsForTeachingMerits(category: TeachingReportCategory) -> [TeachingAssignment] {
        let doctoralSourceAssignmentIDs = Set(doctoralCandidates.flatMap(\.sourceAssignmentIDs))
        return teachingAssignments
            .filter { assignment in
                guard !doctoralSourceAssignmentIDs.contains(assignment.id) else { return false }
                let context = teachingCourses.first(where: { $0.id == assignment.contextID })
                let resolvedCategory = assignment.reportCategory ?? inferredTeachingReportCategory(assignment: assignment, context: context)
                switch category {
                case .thesisSupervision:
                    return resolvedCategory == .thesisSupervision ||
                        resolvedCategory == .doctoralPrincipalSupervision ||
                        resolvedCategory == .doctoralAssistantSupervision
                case .doctoralPrincipalSupervision, .doctoralAssistantSupervision:
                    return false
                default:
                    return resolvedCategory == category
                }
            }
            .sorted { lhs, rhs in
                let leftDate = teachingMeritsSortDate(for: lhs)
                let rightDate = teachingMeritsSortDate(for: rhs)
                if leftDate != rightDate {
                    return leftDate > rightDate
                }
                return (lhs.activityName.nonEmpty ?? "").localizedStandardCompare(rhs.activityName.nonEmpty ?? "") == .orderedAscending
            }
    }

    private func teachingMeritsSortDate(for assignment: TeachingAssignment) -> Date {
        let endText = teachingAssignmentLastDate(assignment).nonEmpty ?? teachingAssignmentFirstDate(assignment)
        return DateParsers.isoDay.date(from: endText) ?? .distantPast
    }

    private func totalHours(for category: TeachingReportCategory, referenceDate: Date = Date()) -> Double {
        teachingAssignmentsForTeachingMerits(category: category).reduce(0) { $0 + teachingMeritsAssignmentTotalHoursValue($1) }
            + teachingMeritsDoctoralCandidateTotalHours(for: category, referenceDate: referenceDate)
    }

    private func assignmentTotalHoursText(_ assignment: TeachingAssignment) -> String {
        formattedTeachingMeritsHours(teachingMeritsAssignmentTotalHoursValue(assignment))
    }

    private func formattedTeachingMeritsHours(_ value: Double) -> String {
        if value.rounded() == value {
            return String(Int(value))
        }
        return String(format: "%.1f", value)
    }

    private func teachingMeritsContextLabel(_ context: TeachingCourse?, activity: String? = nil, language: AppLanguage? = nil) -> String {
        guard let context else { return "" }
        let targetLanguage = language ?? self.language
        let activityKey = normalizedTeachingExportText(activity)
        var primaryContext: String? = teachingMeritsPrimaryContextLabel(context, language: targetLanguage).nonEmpty
        if let primaryContextValue = primaryContext,
           shouldOmitTeachingContextLabel(primaryContextValue, language: targetLanguage) ||
            normalizedTeachingExportText(primaryContextValue) == activityKey {
            primaryContext = nil
        }
        var program: String? = context.localizedProgram(language: targetLanguage).nonEmpty
        if let programValue = program,
           normalizedTeachingExportText(programValue) == activityKey ||
            normalizedTeachingExportText(programValue) == normalizedTeachingExportText(primaryContext) {
            program = nil
        }
        let institution = organizationLabel(for: context, language: targetLanguage).nonEmpty
        return [primaryContext, program, institution].compactMap { $0 }.joined(separator: ", ")
    }

    private func shouldOmitTeachingContextLabel(_ value: String, language: AppLanguage) -> Bool {
        let normalized = normalizedTeachingExportText(value)
        switch language {
        case .english:
            return normalized == normalizedTeachingExportText("Doctoral Education")
                || normalized == normalizedTeachingExportText("Clinical practice")
        case .swedish:
            return normalized == normalizedTeachingExportText("Forskarutbildning")
                || normalized == normalizedTeachingExportText("Klinisk praktik")
        }
    }

    private func normalizedTeachingExportText(_ value: String?) -> String {
        guard let value else { return "" }
        return value
            .replacingOccurrences(of: "[[SUP]]", with: "")
            .replacingOccurrences(of: "[[/SUP]]", with: "")
            .trimmingCharacters(in: .whitespacesAndNewlines)
            .folding(options: [.caseInsensitive, .diacriticInsensitive], locale: Locale(identifier: "en_US_POSIX"))
    }

    private func teachingMeritsPrimaryContextLabel(_ context: TeachingCourse, language: AppLanguage) -> String {
        if let semester = teachingMeritsSemesterContextLabel(context, language: language) {
            return semester
        }
        return context.localizedName(language: language)
    }

    private func teachingMeritsSemesterContextLabel(_ context: TeachingCourse, language: AppLanguage) -> String? {
        let rawTerm = context.localizedTerm(language: language).nonEmpty ?? context.localizedTermFallback.nonEmpty
        guard let rawTerm, let semesterNumber = firstInteger(in: rawTerm) else { return nil }
        if language == .english {
            return englishOrdinalSemesterLabel(semesterNumber, useSuperscriptMarkers: true)
        }
        return rawTerm
    }

    private func firstInteger(in text: String) -> Int? {
        let digits = text.unicodeScalars
            .split(whereSeparator: { !CharacterSet.decimalDigits.contains($0) })
            .compactMap { Int(String($0)) }
        return digits.first
    }

    private func englishOrdinalSemesterLabel(_ number: Int, useSuperscriptMarkers: Bool) -> String {
        let suffix: String
        let lastTwo = number % 100
        if (11...13).contains(lastTwo) {
            suffix = "th"
        } else {
            switch number % 10 {
            case 1: suffix = "st"
            case 2: suffix = "nd"
            case 3: suffix = "rd"
            default: suffix = "th"
            }
        }
        if useSuperscriptMarkers {
            return "\(number)[[SUP]]\(suffix)[[/SUP]] semester"
        }
        return "\(number)\(suffix) semester"
    }

    private func teachingMeritsLanguageLabel(_ value: String) -> String {
        switch canonicalTeachingLanguage(value) {
        case "sv":
            return "Svenska"
        case "en":
            return "Engelska"
        default:
            return value
        }
    }

    private func teachingMeritsActivityLabel(_ assignment: TeachingAssignment, language: AppLanguage? = nil) -> String {
        let targetLanguage = language ?? self.language
        let activityType = localizedTeachingFormatName(effectiveTeachingActivityTypeName(assignment), language: targetLanguage).nonEmpty
        let activity = teachingComponent(for: assignment)?.localizedName(language: targetLanguage).nonEmpty
            ?? assignment.activityName.nonEmpty
        if activityType == activity {
            return activityType ?? ""
        }
        return [activityType, activity].compactMap { $0 }.joined(separator: ", ")
    }

    private func teachingMeritsPeriodLabel(from fromText: String, to toText: String) -> String {
        teachingMeritsTermKeys(from: fromText, to: toText)
            .sorted { $0.sortValue < $1.sortValue }
            .map { teachingMeritsTermLabel($0) }
            .joined(separator: ", ")
    }

    private func teachingMeritsAssignmentSpanLabel(_ assignment: TeachingAssignment) -> String {
        teachingMeritsPeriodLabel(from: teachingAssignmentFirstDate(assignment), to: teachingAssignmentLastDate(assignment))
    }

    private func teachingMeritsExamYearLabel(_ assignment: TeachingAssignment) -> String {
        if let last = teachingAssignmentLastDate(assignment).nonEmpty, let year = yearComponent(from: last) {
            return String(year)
        }
        return ""
    }

    private func teachingMeritsAdministrationDescription(_ assignment: TeachingAssignment) -> String {
        [assignment.activityName.nonEmpty, assignment.comment.nonEmpty].compactMap { $0 }.joined(separator: ": ")
    }

    private func teachingMeritsPeriodHoursText(_ period: TeachingAssignmentPeriod) -> String {
        let terms = teachingTermCountForPeriod(period)
        let raw = period.hoursPerTerm.trimmingCharacters(in: .whitespacesAndNewlines)
        if terms <= 1 {
            return raw
        }
        if let value = GrantParsing.numericValue(from: raw) {
            return formattedTeachingMeritsHours(Double(terms) * value)
        }
        if raw.isEmpty {
            return ""
        }
        return "\(raw) × \(terms)"
    }

    private func teachingTermCountForPeriod(_ period: TeachingAssignmentPeriod) -> Int {
        guard let startDate = period.from.nonEmpty.flatMap(DateParsers.isoDay.date(from:)) else { return 0 }
        let endDate = period.to.nonEmpty.flatMap(DateParsers.isoDay.date(from:)) ?? Calendar.current.startOfDay(for: Date())
        var terms = Set<String>()
        collectTerms(from: startDate, to: endDate, into: &terms)
        return terms.count
    }

    private func teachingMeritsAssignmentTotalHoursValue(_ assignment: TeachingAssignment) -> Double {
        teachingMeritsAssignmentTermSlices(assignment).reduce(0) { $0 + $1.hoursValue }
    }

    private func semesterLabel(from startText: String, to endText: String) -> String? {
        guard let startDate = DateParsers.isoDay.date(from: startText),
              let endDate = DateParsers.isoDay.date(from: endText) else { return nil }
        let calendar = Calendar.current
        let startYear = calendar.component(.year, from: startDate)
        let endYear = calendar.component(.year, from: endDate)
        guard startYear == endYear else { return nil }
        let springStart = calendar.date(from: DateComponents(year: startYear, month: 1, day: 1))
        let springEnd = calendar.date(from: DateComponents(year: startYear, month: 6, day: 30))
        let autumnStart = calendar.date(from: DateComponents(year: startYear, month: 7, day: 1))
        let autumnEnd = calendar.date(from: DateComponents(year: startYear, month: 12, day: 31))
        let shortYear = String(format: "%02d", startYear % 100)
        if startDate == springStart && endDate == springEnd {
            return "VT \(shortYear)"
        }
        if startDate == autumnStart && endDate == autumnEnd {
            return "HT \(shortYear)"
        }
        return nil
    }

    private func isFullYear(from startText: String, to endText: String) -> Bool {
        guard let startDate = DateParsers.isoDay.date(from: startText),
              let endDate = DateParsers.isoDay.date(from: endText) else { return false }
        let calendar = Calendar.current
        let year = calendar.component(.year, from: startDate)
        guard year == calendar.component(.year, from: endDate) else { return false }
        return startDate == calendar.date(from: DateComponents(year: year, month: 1, day: 1))
            && endDate == calendar.date(from: DateComponents(year: year, month: 12, day: 31))
    }

    private func yearComponent(from text: String) -> Int? {
        guard let date = DateParsers.isoDay.date(from: text) else { return nil }
        return Calendar.current.component(.year, from: date)
    }

    private func inferredTeachingReportCategory(
        assignment: TeachingAssignment,
        context: TeachingCourse?
    ) -> TeachingReportCategory {
        let activityType = effectiveTeachingActivityTypeName(assignment).lowercased()
        let activity = assignment.activityName.lowercased()
        let contextName = (context?.localizedName(language: language) ?? "").lowercased()
        let contextType = context?.contextType

        if contextType == .courseAdministration || activityType.contains("utvecklingsarbete") || activity.contains("utvecklingsarbete") {
            return .courseAdministration
        }
        if assignment.roles.contains(.principalSupervisor) && (contextType == .doctoralEducation || activityType.contains("doktorand")) {
            return .doctoralPrincipalSupervision
        }
        if assignment.roles.contains(.assistantSupervisor) && (contextType == .doctoralEducation || activityType.contains("doktorand")) {
            return .doctoralAssistantSupervision
        }
        if contextType == .doctoralEducation && (assignment.roles.contains(.lecturer) || assignment.roles.contains(.invitedSpeaker) || assignment.roles.contains(.seminarLeader) || activityType.contains("föreläs") || activityType.contains("semin")) {
            return .doctoralCourseTeaching
        }
        if activity.contains("examensarbete") || contextName.contains("examensarbete") || contextName.contains("forskar-at-projekt") || contextName.contains("forskningslinjen") {
            return .thesisSupervision
        }
        if assignment.roles.contains(.lecturer) || activityType.contains("föreläs") {
            return .lecture
        }
        if assignment.roles.contains(.seminarLeader) || assignment.roles.contains(.supervisor) || assignment.roles.contains(.examiner) || activityType.contains("semin") || activityType.contains("handled") || activityType.contains("examin") {
            return .groupTeaching
        }
        return .otherPedagogicalWork
    }

    private func collectTerms(from startDate: Date, to endDate: Date, into terms: inout Set<String>) {
        let start = min(startDate, endDate)
        let end = max(startDate, endDate)
        var cursor = start
        while cursor <= end {
            let year = Calendar.current.component(.year, from: cursor)
            let month = Calendar.current.component(.month, from: cursor)
            let half = month <= 6 ? 1 : 2
            terms.insert("\(year)-\(half)")
            guard let nextMonth = Calendar.current.date(byAdding: .month, value: 1, to: cursor) else { break }
            cursor = nextMonth
        }
    }

    private func uniqueTeachingCourseName(base: String, institution: String = "") -> String {
        let existing = Set(
            teachingCourses
                .filter { institution.isEmpty || $0.institution == institution }
                .map(\.name)
        )
        guard !existing.contains(base) else {
            var index = 2
            while existing.contains("\(base) \(index)") {
                index += 1
            }
            return "\(base) \(index)"
        }
        return base
    }

    private func uniqueTeachingComponentName(base: String, institution: String = "") -> String {
        let existing = Set(
            teachingComponents
                .filter { institution.isEmpty || $0.institution == institution }
                .map(\.name)
        )
        guard !existing.contains(base) else {
            var index = 2
            while existing.contains("\(base) \(index)") {
                index += 1
            }
            return "\(base) \(index)"
        }
        return base
    }

    private func uniqueTeachingFormatName(base: String) -> String {
        let existing = Set(teachingFormats.map(\.name))
        guard !existing.contains(base) else {
            var index = 2
            while existing.contains("\(base) \(index)") {
                index += 1
            }
            return "\(base) \(index)"
        }
        return base
    }

