    private func normalizedPublicationType(for publication: PublicationRecord) -> String {
        publication.publicationType
            .trimmingCharacters(in: .whitespacesAndNewlines)
            .lowercased()
    }

    private func isProtocolPublicationType(_ publication: PublicationRecord) -> Bool {
        let type = normalizedPublicationType(for: publication)
        return type == "protocol" || type == "protocol article"
    }

    private func publicationTypeBucket(for publication: PublicationRecord) -> String {
        let type = normalizedPublicationType(for: publication)
        if isProtocolPublicationType(publication) || type == "research letter" {
            return "other"
        }
        if type.contains("review") {
            return "review"
        }
        return "original"
    }

    private func salaryNormalizedDateInput(_ raw: String) -> String {
        let trimmed = raw.trimmingCharacters(in: .whitespacesAndNewlines)
        let digits = trimmed.replacingOccurrences(of: "-", with: "")
        if digits.count == 8, digits.allSatisfy(\.isNumber) {
            let year = digits.prefix(4)
            let month = digits.dropFirst(4).prefix(2)
            let day = digits.suffix(2)
            return "\(year)-\(month)-\(day)"
        }
        return trimmed
    }

    private func salaryFormattedPercentageInput(_ raw: String) -> String {
        guard let value = GrantParsing.numericValue(from: raw) else {
            return raw.trimmingCharacters(in: .whitespacesAndNewlines)
        }
        let formatter = NumberFormatter()
        formatter.locale = Locale(identifier: "sv_SE")
        formatter.numberStyle = .decimal
        formatter.minimumFractionDigits = value.rounded() == value ? 0 : 1
        formatter.maximumFractionDigits = 1
        return "\(formatter.string(from: NSNumber(value: value)) ?? "\(value)") %"
    }

    /// Regex patterns matching the current user's name as it appears in an
    /// AMA author list ("Lastname Initials", optionally followed by the
    /// shared-authorship asterisk). Built from the user's stored name and name
    /// variants; with no current user nothing is bolded.
    func currentUserAMAAuthorBoldPatterns() -> [String] {
        guard let author = currentUserAuthor() else { return [] }
        var forms = Set<String>()
        for variant in author.presentedNameVariantRows {
            let formatted: String
            if variant.lastName.trimmedOrNil != nil {
                formatted = amaFormattedAuthor(
                    lastName: variant.lastName,
                    firstName: variant.firstName,
                    fallbackName: variant.displayName
                )
            } else if let fullName = variant.displayName.trimmedOrNil {
                formatted = amaFormattedAuthorFromName(fullName)
            } else {
                continue
            }
            if let trimmed = formatted.trimmedOrNil {
                forms.insert(trimmed)
            }
        }
        return forms
            .sorted { $0.count != $1.count ? $0.count > $1.count : $0 < $1 }
            .map { "(?<![\\p{L}])" + NSRegularExpression.escapedPattern(for: $0) + "\\*?(?![\\p{L}])" }
    }

    private func amaAttributedCitation(for item: PublicationAMAItem) -> NSAttributedString {
        let baseFont = NSFont.systemFont(ofSize: NSFont.systemFontSize)
        let boldFont = NSFont.boldSystemFont(ofSize: NSFont.systemFontSize)
        let italicFont = NSFontManager.shared.convert(baseFont, toHaveTrait: .italicFontMask)

        func segment(_ text: String, font: NSFont) -> NSAttributedString {
            NSAttributedString(string: text, attributes: [.font: font])
        }

        let result = NSMutableAttributedString()
        var lastSegment: String?

        func appendSeparatorIfNeeded() {
            guard let lastSegment else { return }
            result.append(segment(PublicationCitationFormatting.separator(after: lastSegment), font: baseFont))
        }

        func appendFinalPeriodIfNeeded() {
            guard let lastSegment,
                  !PublicationCitationFormatting.hasTerminalPunctuation(lastSegment) else {
                return
            }
            result.append(segment(".", font: baseFont))
        }

        if !item.authors.isEmpty {
            let authors = NSMutableAttributedString(attributedString: segment(item.authors, font: baseFont))
            for pattern in currentUserAMAAuthorBoldPatterns() {
                if let regex = try? NSRegularExpression(pattern: pattern, options: [.caseInsensitive]) {
                    let range = NSRange(location: 0, length: authors.length)
                    regex.enumerateMatches(in: authors.string, range: range) { match, _, _ in
                        guard let match else { return }
                        authors.addAttribute(.font, value: boldFont, range: match.range)
                    }
                }
            }
            result.append(authors)
            lastSegment = item.authors
        }
        if !item.title.isEmpty {
            appendSeparatorIfNeeded()
            result.append(segment(item.title, font: baseFont))
            lastSegment = item.title
        }
        if !item.journal.isEmpty {
            appendSeparatorIfNeeded()
            result.append(segment(item.journal, font: italicFont))
            lastSegment = item.journal
        }
        if !item.tail.isEmpty {
            appendSeparatorIfNeeded()
            result.append(segment(item.tail, font: baseFont))
            lastSegment = item.tail
        }
        appendFinalPeriodIfNeeded()
        if !item.note.isEmpty {
            result.append(segment(" \(item.note)", font: baseFont))
        }
        return result
    }

    func copyFundingStatement(
        for applications: [GrantApplication],
        languageMode: FundingStatementLanguageMode = .english,
        sortMode: FundingStatementSortMode = .firstFundingFirst
    ) {
        let grantedApplications = applications
            .filter(\.isGranted)
            .sorted { fundingStatementSortPrecedes($0, $1, sortMode: sortMode) }

        guard !grantedApplications.isEmpty else {
            notice = StoreNotice(message: language.text("No granted applications available for a funding statement.", "Det finns inga beviljade ansökningar att skapa funding statement från."), tone: .info)
            loadError = nil
            return
        }

        let parts = grantedApplications.map { application in
            let caseNumber = application.appliedCaseNumber?.trimmedOrNil
            switch languageMode {
            case .english:
                if let displayName = application.receivedDisplayName?.trimmedOrNil {
                    return fundingStatementPartText(displayName)
                }
                let organization = englishFundingSourceName(for: funderName(for: application))
                if let caseNumber {
                    return "\(organization) (\(caseNumber))"
                }
                return organization
            case .swedish:
                let organization = organizationLabel(for: application, language: .swedish)
                if let caseNumber {
                    return "\(organization) (\(caseNumber))"
                }
                return organization
            }
        }

        let statement: String
        switch languageMode {
        case .english:
            statement = workflowDefaultSettings.fundingStatement(
                fundersText: naturalLanguageList(parts, conjunction: "and"),
                english: true
            )
        case .swedish:
            statement = workflowDefaultSettings.fundingStatement(
                fundersText: naturalLanguageList(parts, conjunction: "och"),
                english: false
            )
        }
        let pasteboard = NSPasteboard.general
        pasteboard.clearContents()
        pasteboard.setString(statement, forType: .string)
        showClipboardPreview(statement)
        notice = StoreNotice(message: language.text("Copied funding statement.", "Kopierade finansieringstext."), tone: .success)
        loadError = nil
    }

    private func fundingStatementSortPrecedes(
        _ lhs: GrantApplication,
        _ rhs: GrantApplication,
        sortMode: FundingStatementSortMode
    ) -> Bool {
        switch sortMode {
        case .firstFundingFirst:
            let lhsDate = fundingStatementFirstFundingDate(for: lhs)
            let rhsDate = fundingStatementFirstFundingDate(for: rhs)
            if lhsDate != rhsDate {
                return lhsDate < rhsDate
            }
        case .largestFundingFirst:
            let lhsAmount = grantStatisticsAmountInSEK(for: lhs, amount: lhs.grantedAmountValue)
            let rhsAmount = grantStatisticsAmountInSEK(for: rhs, amount: rhs.grantedAmountValue)
            if lhsAmount != rhsAmount {
                return lhsAmount > rhsAmount
            }
            let lhsDate = fundingStatementFirstFundingDate(for: lhs)
            let rhsDate = fundingStatementFirstFundingDate(for: rhs)
            if lhsDate != rhsDate {
                return lhsDate < rhsDate
            }
        }

        let lhsOrganization = organizationLabel(for: lhs, language: .english)
        let rhsOrganization = organizationLabel(for: rhs, language: .english)
        if lhsOrganization != rhsOrganization {
            return lhsOrganization.localizedStandardCompare(rhsOrganization) == .orderedAscending
        }
        return (lhs.appliedCaseNumber ?? "").localizedStandardCompare(rhs.appliedCaseNumber ?? "") == .orderedAscending
    }

    private func fundingStatementFirstFundingDate(for application: GrantApplication) -> Date {
        application.firstDispositionDate
            ?? application.receivedUsageFrom.flatMap { DateParsers.isoDay.date(from: $0) }
            ?? application.grantedDate
            ?? application.decisionDate
            ?? application.applicationDate
            ?? .distantFuture
    }

    private func showClipboardPreview(_ text: String) {
        clipboardPreviewTask?.cancel()
        let payload = ClipboardPreviewPayload(text: text)
        clipboardPreview = payload
        clipboardPreviewTask = Task { @MainActor in
            try? await Task.sleep(nanoseconds: 2_500_000_000)
            guard !Task.isCancelled, clipboardPreview?.id == payload.id else { return }
            clipboardPreview = nil
        }
    }

    func copyFundingStatement(for publication: PublicationRecord) {
        copyFundingStatement(for: publication, languageMode: .english)
    }

    func copyFundingStatement(
        for publication: PublicationRecord,
        languageMode: FundingStatementLanguageMode,
        sortMode: FundingStatementSortMode = .firstFundingFirst
    ) {
        if !confirmProceedingAfterValidation(
            title: language.text("Funding statement export", "Export av funding statement"),
            issues: publicationFundingValidationIssues(for: publication)
        ) {
            notice = StoreNotice(message: language.text("Cancelled export.", "Export avbröts."), tone: .info)
            loadError = nil
            return
        }
        guard publication.projectName?.trimmedOrNil != nil || publication.projectID?.trimmedOrNil != nil else {
            notice = StoreNotice(message: language.text("This publication is not linked to a project.", "Den här publikationen är inte kopplad till något projekt."), tone: .info)
            loadError = nil
            return
        }

        // "Alla kopplingar via id": the applications of the publication's
        // project, decided by the links on both sides.
        let linkedApplications: [GrantApplication]
        if let publicationProject = linkedProject(of: publication) {
            linkedApplications = applications.filter { applicationBelongs($0, to: publicationProject) }
        } else {
            let projectName = publication.projectName?.trimmedOrNil
            linkedApplications = applications.filter { $0.projectID == nil && $0.projectType == projectName }
        }
        copyFundingStatement(for: linkedApplications, languageMode: languageMode, sortMode: sortMode)
    }

    func canExportFundingStatement(for publication: PublicationRecord) -> Bool {
        !grantedApplications(for: publication).isEmpty
    }

    private func publicationEthicsValidationIssues(for publication: PublicationRecord) -> [String] {
        var issues: [String] = []
        guard let project = linkedProject(of: publication) else {
            return [language.text("The publication is not linked to a project.", "Publikationen är inte kopplad till något projekt.")]
        }
        if approvedEthicsCaseNumbers(for: project).isEmpty {
            issues.append(language.text("No approved ethics case number is registered for the linked project.", "Inget beviljat etikdiarienummer är registrerat för det kopplade projektet."))
        }
        if project.clinicalTrialRegistrations.allSatisfy({ $0.trialID.trimmedOrNil == nil }) {
            issues.append(language.text("No ClinicalTrials.gov registration is registered for the linked project.", "Ingen ClinicalTrials.gov-registrering är registrerad för det kopplade projektet."))
        }
        return issues
    }

    private func publicationFundingValidationIssues(for publication: PublicationRecord) -> [String] {
        let linkedApplications = grantedApplications(for: publication)
        guard !linkedApplications.isEmpty else {
            return [language.text("No granted applications are linked to this publication.", "Det finns inga beviljade ansökningar kopplade till den här publikationen.")]
        }

        let missingOrganizationCount = linkedApplications.filter { organizationLabel(for: $0, language: .swedish).trimmedOrNil == nil }.count
        let missingCaseNumberCount = linkedApplications.filter { $0.appliedCaseNumber?.trimmedOrNil == nil }.count
        var issues: [String] = []
        if missingOrganizationCount > 0 {
            issues.append(language.text(
                "\(missingOrganizationCount) linked grants are missing grant-giver name.",
                "\(missingOrganizationCount) kopplade anslag saknar anslagsgivarnamn."
            ))
        }
        if missingCaseNumberCount > 0 {
            issues.append(language.text(
                "\(missingCaseNumberCount) linked grants are missing application number/case number.",
                "\(missingCaseNumberCount) kopplade anslag saknar ansökningsnummer/diarienummer."
            ))
        }
        return issues
    }

    func copyPublicationFundingDetails(for publication: PublicationRecord) {
        if !confirmProceedingAfterValidation(
            title: language.text("Funding details export", "Export av finansieringsuppgifter"),
            issues: publicationFundingValidationIssues(for: publication)
        ) {
            notice = StoreNotice(message: language.text("Cancelled export.", "Export avbröts."), tone: .info)
            loadError = nil
            return
        }
        let linkedApplications = grantedApplications(for: publication)
        guard !linkedApplications.isEmpty else {
            notice = StoreNotice(message: language.text("No granted applications are linked to this publication.", "Det finns inga beviljade ansökningar kopplade till den här publikationen."), tone: .info)
            loadError = nil
            return
        }

        let parts = linkedApplications.compactMap { application -> String? in
            let organization = organizationLabel(for: application, language: .swedish).trimmingCharacters(in: .whitespacesAndNewlines)
            guard !organization.isEmpty else { return nil }
            if let caseNumber = application.appliedCaseNumber?.trimmedOrNil {
                return "\(organization) (\(caseNumber))"
            }
            return organization
        }

        let statement = workflowDefaultSettings.fundingStatement(
            fundersText: naturalLanguageList(parts, conjunction: "och"),
            english: false
        )
        let pasteboard = NSPasteboard.general
        pasteboard.clearContents()
        pasteboard.setString(statement, forType: .string)
        showClipboardPreview(statement)
        notice = StoreNotice(message: language.text("Copied funding details.", "Kopierade finansieringsuppgifter."), tone: .success)
        loadError = nil
    }

    func copyPublicationCreditStatement(for publication: PublicationRecord) {
        copyPublicationCreditStatement(for: publication, options: PublicationCreditStatementOptions())
    }

    func copyPublicationCreditStatement(
        for publication: PublicationRecord,
        options: PublicationCreditStatementOptions
    ) {
        guard publication.hasDefinedCreditRoles else {
            notice = StoreNotice(message: language.text("No CRediT roles are defined for this publication.", "Inga CRediT-roller är definierade för publikationen."), tone: .info)
            loadError = nil
            return
        }

        let statement = publicationCreditStatement(for: publication, options: options)
        let pasteboard = NSPasteboard.general
        pasteboard.clearContents()
        pasteboard.setString(statement, forType: .string)
        showClipboardPreview(statement)
        notice = StoreNotice(message: language.text("Copied CRediT statement.", "Kopierade CRediT-text."), tone: .success)
        loadError = nil
    }

    func copyPublicationEthicsStatement(for publication: PublicationRecord) {
        copyPublicationEthicsStatement(for: publication, languageMode: .english)
    }

    func copyPublicationEthicsStatement(
        for publication: PublicationRecord,
        languageMode: FundingStatementLanguageMode
    ) {
        if !confirmProceedingAfterValidation(
            title: language.text("Ethics approval export", "Export av etiktillstånd"),
            issues: publicationEthicsValidationIssues(for: publication)
