    // MARK: F21 organization tree editing
    //
    // Units are written only through these methods, never through the
    // organization editor's autosave (which carries the stored units over
    // unchanged). Each call is one undoable change.

    /// F21: adds a unit directly under the organization (`parentUnitID` nil)
    /// or under one of its units. Returns the new unit's id, or nil when the
    /// organization or the parent is missing or saving failed.
    @discardableResult
    func addOrganizationUnit(organizationID: String, parentUnitID: String? = nil, nameSv: String? = nil) -> String? {
        guard let index = organizations.firstIndex(where: { $0.id == organizationID }) else { return nil }
        if let parentUnitID, organizations[index].unit(withID: parentUnitID) == nil {
            return nil
        }
        var unit = OrganizationUnit(
            parentUnitID: parentUnitID,
            nameSv: nameSv?.trimmedOrNil ?? language.text("New unit", "Ny enhet")
        )
        unit.normalize()
        let didSave = performUndoableChange(
            actionName: language.text("Add unit", "Lägg till enhet"),
            successMessage: language.text("Added the unit.", "Enheten lades till."),
            failureMessage: language.text("Could not add the unit.", "Kunde inte lägga till enheten."),
            scope: .organizations
        ) {
            organizations[index].units.append(unit)
        }
        return didSave ? unit.id : nil
    }

    /// F21: saves a unit's names, address settings and validity. The unit's
    /// place in the tree is kept (use `moveOrganizationUnit`). A unit must
    /// keep a Swedish or an English name. Returns false when nothing was saved.
    /// Round 7: researcher rows linked to the organization get the new
    /// official names in the same undoable change.
    @discardableResult
    func updateOrganizationUnit(organizationID: String, unit: OrganizationUnit) -> Bool {
        guard let index = organizations.firstIndex(where: { $0.id == organizationID }),
              let unitIndex = organizations[index].units.firstIndex(where: { $0.id == unit.id }) else { return false }
        let previous = organizations[index].units[unitIndex]
        var updated = unit
        updated.parentUnitID = previous.parentUnitID
        updated.normalize()
        guard updated.nameSv.nonEmpty != nil || updated.nameEn.nonEmpty != nil else { return false }
        guard updated != previous else { return false }
        var prospectiveOrganizations = organizations
        prospectiveOrganizations[index].units[unitIndex] = updated
        let officialNames = OrganizationTree.applyingOfficialNames(
            to: publicationAuthors,
            organizations: prospectiveOrganizations,
            onlyOrganizationIDs: [organizationID]
        )
        let rewritesRows = !officialNames.report.isEmpty
        return performUndoableChange(
            actionName: language.text("Edit unit", "Redigera enhet"),
            successMessage: language.text("Saved the unit.", "Enheten sparades."),
            failureMessage: language.text("Could not save the unit.", "Kunde inte spara enheten."),
            scope: rewritesRows ? .organizationTree : .organizations
        ) {
            organizations[index].units[unitIndex] = updated
            if rewritesRows {
                publicationAuthors = officialNames.authors
            }
        }
    }

    /// F21: moves a unit (with the units below it) to a new parent in the
    /// same organization; nil = directly under the organization. A unit
    /// cannot be moved under itself or under one of its own units.
    @discardableResult
    func moveOrganizationUnit(organizationID: String, unitID: String, toParentUnitID: String?) -> Bool {
        guard let index = organizations.firstIndex(where: { $0.id == organizationID }),
              let unitIndex = organizations[index].units.firstIndex(where: { $0.id == unitID }) else { return false }
        let organization = organizations[index]
        if let toParentUnitID {
            guard organization.unit(withID: toParentUnitID) != nil,
                  !organization.unitIsInSubtree(toParentUnitID, of: unitID) else { return false }
        }
        guard organization.units[unitIndex].parentUnitID != toParentUnitID else { return false }
        return performUndoableChange(
            actionName: language.text("Move unit", "Flytta enhet"),
            successMessage: language.text("Moved the unit.", "Enheten flyttades."),
            failureMessage: language.text("Could not move the unit.", "Kunde inte flytta enheten."),
            scope: .organizations
        ) {
            organizations[index].units[unitIndex].parentUnitID = toParentUnitID
        }
    }

    /// F21: removes a unit that no researcher row points to and that has
    /// no units below it. Returns false (and changes nothing) otherwise.
    /// The organization page uses `removeOrganizationUnit(organizationID:unitID:keepsChildren:)`,
    /// which also handles used units and units with units below them.
    @discardableResult
    func removeOrganizationUnit(organizationID: String, unitID: String) -> Bool {
        guard let index = organizations.firstIndex(where: { $0.id == organizationID }),
              organizations[index].unit(withID: unitID) != nil else { return false }
        guard organizationUnitUsageCount(organizationID: organizationID, unitID: unitID) == 0 else { return false }
        guard organizations[index].childUnits(of: unitID).isEmpty else { return false }
        return performUndoableChange(
            actionName: language.text("Remove unit", "Ta bort enhet"),
            successMessage: language.text(
                "Removed the unit. You can undo this action.",
                "Enheten togs bort. Du kan ångra åtgärden."
            ),
            failureMessage: language.text("Could not remove the unit.", "Kunde inte ta bort enheten."),
            scope: .organizations
        ) {
            organizations[index].units.removeAll { $0.id == unitID }
        }
    }

    /// F21: removes a unit even when researcher rows use it or units sit
    /// below it (the "Ta bort enheten" confirmation on the organization page).
    ///  - `keepsChildren == true`: only this unit goes; the units directly
    ///    below it move up one level (to this unit's parent, or directly
    ///    under the organization).
    ///  - `keepsChildren == false`: the unit and every unit below it go.
    /// Affiliation, employment and education rows of this organization that
    /// pointed to a removed unit keep the organization (and their text) but
    /// lose the unit. One undoable change. Returns false when nothing was done.
    @discardableResult
    func removeOrganizationUnit(organizationID: String, unitID: String, keepsChildren: Bool) -> Bool {
        guard let index = organizations.firstIndex(where: { $0.id == organizationID }),
              let removedUnit = organizations[index].unit(withID: unitID) else { return false }
        let organization = organizations[index]
        var removedIDs = Set<String>()
        removedIDs.insert(removedUnit.id)
        if !keepsChildren {
            removedIDs.formUnion(organization.descendantUnitIDs(of: removedUnit.id))
        }
        // The level the units below move up to. A parent that is missing or
        // sits below the removed unit (a loop of parents) means the top level.
        var newParentUnitID: String? = nil
        if let parentUnitID = removedUnit.parentUnitID,
           organization.unit(withID: parentUnitID) != nil,
           !organization.unitIsInSubtree(parentUnitID, of: removedUnit.id) {
            newParentUnitID = parentUnitID
        }

        var updatedUnits = organization.units.filter { !removedIDs.contains($0.id) }
        if keepsChildren {
            for unitIndex in updatedUnits.indices where updatedUnits[unitIndex].parentUnitID == removedUnit.id {
                updatedUnits[unitIndex].parentUnitID = newParentUnitID
            }
        }

        func pointsToRemovedUnit(_ rowOrganizationID: String?, _ rowUnitID: String?) -> Bool {
            guard rowOrganizationID == organizationID, let rowUnitID else { return false }
            return removedIDs.contains(rowUnitID)
        }
        var updatedAuthors = publicationAuthors
        var authorsChanged = false
        for authorIndex in updatedAuthors.indices {
            for rowIndex in updatedAuthors[authorIndex].affiliations.indices {
                let row = updatedAuthors[authorIndex].affiliations[rowIndex]
                if pointsToRemovedUnit(row.organizationID, row.unitID) {
                    updatedAuthors[authorIndex].affiliations[rowIndex].unitID = nil
                    authorsChanged = true
                }
            }
            for rowIndex in updatedAuthors[authorIndex].employments.indices {
                let row = updatedAuthors[authorIndex].employments[rowIndex]
                if pointsToRemovedUnit(row.organizationID, row.unitID) {
                    updatedAuthors[authorIndex].employments[rowIndex].unitID = nil
                    authorsChanged = true
                }
            }
            for rowIndex in updatedAuthors[authorIndex].educationEntries.indices {
                let row = updatedAuthors[authorIndex].educationEntries[rowIndex]
                if pointsToRemovedUnit(row.organizationID, row.unitID) {
                    updatedAuthors[authorIndex].educationEntries[rowIndex].unitID = nil
                    authorsChanged = true
                }
            }
        }

        let actionName = removedIDs.count > 1
            ? language.text("Remove units", "Ta bort enheter")
            : language.text("Remove unit", "Ta bort enhet")
        return performUndoableChange(
            actionName: actionName,
            successMessage: removedIDs.count > 1
                ? language.text(
                    "Removed the unit and the units below it. You can undo this action.",
                    "Enheten och underenheterna togs bort. Du kan ångra åtgärden."
                )
                : language.text(
                    "Removed the unit. You can undo this action.",
                    "Enheten togs bort. Du kan ångra åtgärden."
                ),
            failureMessage: language.text("Could not remove the unit.", "Kunde inte ta bort enheten."),
            scope: authorsChanged ? .organizationTree : .organizations
        ) {
            organizations[index].units = updatedUnits
            if authorsChanged {
                publicationAuthors = updatedAuthors
            }
        }
    }

    /// F21: the organization's English name in publication addresses and
    /// the order of its address line (nil = after the others).
    @discardableResult
    func updateOrganizationAddressSettings(organizationID: String, addressNameEn: String, addressOrder: Int?) -> Bool {
        guard let index = organizations.firstIndex(where: { $0.id == organizationID }) else { return false }
        let trimmedName = addressNameEn.trimmingCharacters(in: .whitespacesAndNewlines)
        let previous = organizations[index]
        guard previous.addressNameEn != trimmedName || previous.addressOrder != addressOrder else { return false }
        return performUndoableChange(
            actionName: language.text("Edit publication address", "Redigera publikationsadress"),
            successMessage: language.text("Saved the publication address.", "Publikationsadressen sparades."),
            failureMessage: language.text("Could not save the publication address.", "Kunde inte spara publikationsadressen."),
            scope: .organizations
        ) {
            organizations[index].addressNameEn = trimmedName
            organizations[index].addressOrder = addressOrder
        }
    }

    /// "Use as salary calculator for applications" on one organization. Only
    /// one organization can have it: ticking it clears it on the others.
    @discardableResult
    func setOrganizationUsesAsApplicationSalaryCalculator(organizationID: String, enabled: Bool) -> Bool {
        guard let index = organizations.firstIndex(where: { $0.id == organizationID }) else { return false }
        let otherIndices = enabled
            ? organizations.indices.filter { $0 != index && organizations[$0].usesAsApplicationSalaryCalculator }
            : []
        guard organizations[index].usesAsApplicationSalaryCalculator != enabled || !otherIndices.isEmpty else { return false }
        return performUndoableChange(
            actionName: language.text("Edit salary calculator for applications", "Redigera lönekalkyl för ansökningar"),
            successMessage: language.text("Saved the salary calculator choice.", "Valet av lönekalkyl sparades."),
            failureMessage: language.text("Could not save the salary calculator choice.", "Kunde inte spara valet av lönekalkyl."),
            scope: .organizations
        ) {
            for otherIndex in otherIndices {
                organizations[otherIndex].usesAsApplicationSalaryCalculator = false
            }
            organizations[index].usesAsApplicationSalaryCalculator = enabled
        }
    }

    /// The earlier "Max OH (%)" on a grant provider, kept for older callers:
    /// it now sets the "OH-regel". nil = the fund manager's full OH, 0 = no
    /// OH, any other value = at most that percent (kept between 0 and 100).
    /// The "Taket inkluderar lokalkostnad" box and the exceptions are kept.
    @discardableResult
    func setOrganizationMaxOverheadPercent(organizationID: String, percent: Double?) -> Bool {
        guard let index = organizations.firstIndex(where: { $0.id == organizationID }) else { return false }
        let includesPremises = organizations[index].overheadRule?.capIncludesPremises ?? false
        var rule = FunderOverheadRule.migrated(fromLegacyMaxOverheadPercent: percent) ?? FunderOverheadRule()
        rule.capIncludesPremises = includesPremises
        return setOrganizationOverheadRule(organizationID: organizationID, rule: rule)
    }

    /// "OH-regel" on a grant provider. The standard (the fund manager's full
    /// OH, no number, box not ticked) is stored as nothing. The cap is kept
    /// between 0 and 100.
    @discardableResult
    func setOrganizationOverheadRule(organizationID: String, rule: FunderOverheadRule?) -> Bool {
        guard let index = organizations.firstIndex(where: { $0.id == organizationID }) else { return false }
        let normalized = rule.map { $0.normalized() }
        let stored: FunderOverheadRule? = (normalized?.isStandard ?? true) ? nil : normalized
        guard organizations[index].overheadRule != stored else { return false }
        return performUndoableChange(
            actionName: language.text("Edit OH rule", "Redigera OH-regel"),
            successMessage: language.text("Saved the OH rule.", "OH-regeln sparades."),
            failureMessage: language.text("Could not save the OH rule.", "Kunde inte spara OH-regeln."),
            scope: .organizations
        ) {
            organizations[index].overheadRule = stored
        }
    }

    /// The exceptions "När [medelsförvaltare] förvaltar: …" on a grant
    /// provider. Rows without a chosen fund manager are kept so a new row
    /// can be filled in; an empty list is stored as nothing.
    @discardableResult
    func setOrganizationOverheadRuleExceptions(organizationID: String, exceptions: [FunderOverheadRuleException]) -> Bool {
        guard let index = organizations.firstIndex(where: { $0.id == organizationID }) else { return false }
        let normalized = exceptions.map { exception -> FunderOverheadRuleException in
            var copy = exception
            copy.managerOrganizationID = exception.managerOrganizationID.trimmingCharacters(in: .whitespacesAndNewlines)
            copy.rule = exception.rule.normalized()
            return copy
        }
        let stored: [FunderOverheadRuleException]? = normalized.isEmpty ? nil : normalized
        guard organizations[index].overheadRuleExceptions != stored else { return false }
        return performUndoableChange(
            actionName: language.text("Edit OH exceptions", "Redigera OH-undantag"),
            successMessage: language.text("Saved the OH exceptions.", "OH-undantagen sparades."),
            failureMessage: language.text("Could not save the OH exceptions.", "Kunde inte spara OH-undantagen."),
            scope: .organizations
        ) {
            organizations[index].overheadRuleExceptions = stored
        }
    }

    /// "Förvaltarens fulla OH (%)" on a fund manager. nil = not set. The
    /// value is kept between 0 and 100.
    @discardableResult
    func setOrganizationManagerOverheadPercent(organizationID: String, percent: Double?) -> Bool {
        guard let index = organizations.firstIndex(where: { $0.id == organizationID }) else { return false }
        let clamped = percent.map { min(100, max(0, $0)) }
        guard organizations[index].managerOverheadPercent != clamped else { return false }
        return performUndoableChange(
            actionName: language.text("Edit fund manager's OH", "Redigera förvaltarens OH"),
            successMessage: language.text("Saved the fund manager's OH.", "Förvaltarens OH sparades."),
            failureMessage: language.text("Could not save the fund manager's OH.", "Kunde inte spara förvaltarens OH."),
            scope: .organizations
        ) {
            organizations[index].managerOverheadPercent = clamped
        }
    }

    /// Round 10, "Prioriterad förvaltare" on a grant provider: the fund
    /// manager organization (by id) chosen for new records. nil or "" = the
    /// default fund manager in Settings.
    @discardableResult
    func setOrganizationPreferredFundManager(organizationID: String, managerID: String?) -> Bool {
        guard let index = organizations.firstIndex(where: { $0.id == organizationID }) else { return false }
        let stored = managerID?.trimmedOrNil
        guard organizations[index].preferredFundManagerID != stored else { return false }
        return performUndoableChange(
            actionName: language.text("Edit preferred fund manager", "Redigera prioriterad förvaltare"),
            successMessage: language.text("Saved the preferred fund manager.", "Prioriterad förvaltare sparades."),
            failureMessage: language.text("Could not save the preferred fund manager.", "Kunde inte spara prioriterad förvaltare."),
            scope: .organizations
        ) {
            organizations[index].preferredFundManagerID = stored
        }
    }

    /// One-time startup step for the settings that replaced fixed names:
    /// the old fixed calendar category names (Klinik/Clinic, Resa/Travel,
    /// Semester/Vacation) are stored as settings on the existing categories.
    /// The home region and the organization used for the salary calculator
    /// are never chosen by name; the user picks them (an earlier version
    /// stored them in the data). Nothing is removed; only settings are written.
    @discardableResult
    func migrateHomeOrganizationSettingsIfNeeded() -> Bool {
        var updated = metadata

        if updated.calendarCategoryBehaviors == nil {
            updated.calendarCategoryBehaviors = CalendarCategoryBehaviorSetting.normalizedList(
                calendarKnownMeetingCategories
                    .map(CalendarCategoryBehaviorSetting.legacyDefault(forCategoryNamed:))
                    .filter(\.hasAnyFlag)
            )
        }

        let before = Self.sanitizedMetadata(metadata)
        updated = Self.sanitizedMetadata(updated)
        let metadataChanged = updated != before
        if metadataChanged {
            metadata = updated
        }
        return metadataChanged
    }

    func addOrganization(defaultRoles: [OrganizationRole] = [.grantProvider]) -> String {
        let option = uniqueOption(
            baseSv: "Ny organisation",
            baseEn: "New organization",
            within: organizations,
            roles: defaultRoles
        )
        performUndoableChange(
            actionName: language.text("Add organization", "Lägg till organisation"),
            successMessage: language.text("Added organization.", "Lade till organisation."),
            failureMessage: language.text("Could not add organization.", "Kunde inte lägga till organisation."),
            scope: .applications
        ) {
            organizations.append(option)
            managers = derivedManagers(from: organizations)
        }
        return option.id
    }

    func amaSections(
        exportLanguage: AppLanguage,
        options: PublicationExportOptions = PublicationExportOptions(),
        includedSections: Set<PublicationExportSectionKey> = Set(PublicationExportSectionKey.allCases)
    ) -> [PublicationAMASection] {
        var options = options
        options.exportLanguage = exportLanguage
        let orderedPeerReviewed = publicationRecords
            .filter(\.isPeerReviewed)
            .sorted { lhs, rhs in
                amaSortOrder(lhs, rhs, oldestFirst: options.sortOrder == .oldestFirst)
            }
        let orderedNonPeerReviewed = publicationRecords
            .filter { !$0.isPeerReviewed }
            .sorted { lhs, rhs in
                amaSortOrder(lhs, rhs, oldestFirst: options.sortOrder == .oldestFirst)
            }
        let groups: [(PublicationExportSectionKey, String, String, [PublicationRecord], (PublicationRecord) -> Bool)] = [
            (.publishedOriginalArticles, "Published original articles", "Publicerade originalartiklar", orderedPeerReviewed, { publication in
                let status = PublicationStatus.fromStored(publication.statusLabel)
                guard status == .published else { return false }
                let type = self.normalizedPublicationType(for: publication)
                return type.isEmpty || (!type.contains("review") && !self.isProtocolPublicationType(publication))
            }),
            (.publishedReviewArticles, "Published review articles", "Publicerade översiktsartiklar", orderedPeerReviewed, { publication in
                let status = PublicationStatus.fromStored(publication.statusLabel)
                guard status == .published else { return false }
                return self.normalizedPublicationType(for: publication).contains("review")
            }),
            (.publishedProtocolArticles, "Published protocol articles", "Publicerade protokollartiklar", orderedPeerReviewed, { publication in
                let status = PublicationStatus.fromStored(publication.statusLabel)
                return status == .published && self.isProtocolPublicationType(publication)
            }),
            (.publishedNonPeerReviewedPublications, "Other publications, non-peer-reviewed", "Övriga publikationer, ej expertgranskade", orderedNonPeerReviewed, { publication in
                PublicationStatus.fromStored(publication.statusLabel) == .published
            }),
            // Round 12: accepted articles belong here too (they fell out of
            // every group before).
            (.articlesInReview, "Articles accepted or in review", "Artiklar accepterade eller under granskning", orderedPeerReviewed, { publication in
                let status = PublicationStatus.fromStored(publication.statusLabel)
                return status.isSubmittedFamily || status == .accepted
            }),
            (.articlesInWriting, "Articles in writing", "Artiklar under arbete", orderedPeerReviewed, { publication in
                let status = PublicationStatus.fromStored(publication.statusLabel)
                return status == .planned || status == .inPreparation
            }),
        ]
        let sections = groups.compactMap { group -> PublicationAMASection? in
            let (key, englishTitle, swedishTitle, source, predicate) = group
            let includeSection = if key == .publishedNonPeerReviewedPublications {
                includedSections.contains(key) || options.includeNonPeerReviewedPublications
            } else {
                includedSections.contains(key)
            }
            guard includeSection else { return nil }
            return PublicationAMASection(
                title: exportLanguage == .swedish ? swedishTitle : englishTitle,
                items: source.filter(predicate).map { amaCitationItem(for: $0, options: options) }
            )
        }

        return sections
    }

    private func amaSortOrder(_ lhs: PublicationRecord, _ rhs: PublicationRecord, oldestFirst: Bool = false) -> Bool {
        if lhs.sortYear != rhs.sortYear {
            return oldestFirst ? (lhs.sortYear < rhs.sortYear) : (lhs.sortYear > rhs.sortYear)
        }
        let lhsDate = amaReferenceDate(for: lhs) ?? .distantPast
        let rhsDate = amaReferenceDate(for: rhs) ?? .distantPast
        if lhsDate != rhsDate {
            return oldestFirst ? (lhsDate < rhsDate) : (lhsDate > rhsDate)
        }
        return lhs.title.localizedStandardCompare(rhs.title) == .orderedAscending
    }

    private func amaReferenceDate(for publication: PublicationRecord) -> Date? {
        [
            publication.statusDate,
            publication.currentSubmissionDate,
        ]
        .compactMap { $0 }
        .compactMap { DateParsers.isoDay.date(from: $0) }
        .first
    }

    private func amaAuthorEntries(for publication: PublicationRecord) -> [(index: Int, text: String, isCurrentUser: Bool)] {
        let currentAuthor = currentUserAuthor()
        let currentAuthorID = currentAuthor?.id
        let currentUserKeys = currentUserPresentedNameKeys()

        return publication.authorNames.enumerated().compactMap { index, authorName in
            let authorKey = normalizedPersonLookupName(authorName)
            if let author = publicationAuthor(matchingPresentedName: authorName),
               let presentedName = author.presentedNameVariant(matching: authorName) {
                let text = amaFormattedAuthor(
                    lastName: presentedName.lastName,
                    firstName: presentedName.firstName,
                    fallbackName: presentedName.displayName
                ) + sharedAuthorshipMarker(for: publication, at: index)
                let isCurrent = author.id == currentAuthorID || currentUserKeys.contains(authorKey)
                return (index, text, isCurrent)
            }
            let text = amaFormattedAuthorFromName(authorName) + sharedAuthorshipMarker(for: publication, at: index)
            let isCurrent = currentUserKeys.contains(authorKey)
            return (index, text, isCurrent)
        }
    }

    private func amaVisibleAuthorIndices(
        for authors: [(index: Int, text: String, isCurrentUser: Bool)],
        options: PublicationExportOptions
    ) -> Set<Int> {
        let cutoff = max(1, options.authorCountBeforeEtAl)
        guard authors.count > cutoff else {
            return Set(authors.map(\.index))
        }

        guard options.alwaysShowOwnName else {
            return Set(authors.prefix(cutoff).map(\.index))
        }
        let currentIndex = authors.firstIndex(where: \.isCurrentUser)
        let visibleCount = max(cutoff, (currentIndex.map { $0 + 1 } ?? 0))
        return Set(authors.prefix(visibleCount).map(\.index))
    }

    private func amaAuthorList(
        from authors: [(index: Int, text: String, isCurrentUser: Bool)],
        visibleAuthorIndices: Set<Int>,
        options: PublicationExportOptions
    ) -> String {
        let names = authors.map(\.text)
        let underlinedNames = resolvedUnderlinedPublicationNames(options: options)
        guard visibleAuthorIndices.count < authors.count else {
            return underliningNameVariants(in: names.joined(separator: ", "), fullNames: underlinedNames)
        }
        let visibleNames = authors
            .filter { visibleAuthorIndices.contains($0.index) }
            .map(\.text)
        return underliningNameVariants(in: visibleNames.joined(separator: ", ") + ", et al", fullNames: underlinedNames)
    }

    func resolvedUnderlinedPublicationNames(options: PublicationExportOptions) -> [String] {
        var names = options.underlinedNames
        if options.underlineDoctoralMainSupervisor {
            for supervisor in cvOtherPublications
                .filter(\.isDoctoralThesis)
                .compactMap({ $0.mainSupervisor.trimmedOrNil })
                where !names.contains(supervisor) {
                names.append(supervisor)
            }
        }
        return names
    }

    func publicationExportOptions(
        from options: PublicationExportOptions,
        underlineDoctoralMainSupervisor: Bool,
        underlineDoctoralCoSupervisor: Bool
    ) -> PublicationExportOptions {
        var effectiveOptions = options
        if underlineDoctoralMainSupervisor {
            effectiveOptions.underlineDoctoralMainSupervisor = true
            for supervisor in cvOtherPublications
                .filter(\.isDoctoralThesis)
                .compactMap({ $0.mainSupervisor.trimmedOrNil })
                where !effectiveOptions.underlinedNames.contains(supervisor) {
                effectiveOptions.underlinedNames.append(supervisor)
            }
        }
        if underlineDoctoralCoSupervisor {
            for supervisor in cvOtherPublications
                .filter(\.isDoctoralThesis)
                .compactMap({ $0.coSupervisor.trimmedOrNil })
                where !effectiveOptions.underlinedNames.contains(supervisor) {
                effectiveOptions.underlinedNames.append(supervisor)
            }
        }
        return effectiveOptions
    }

    private func amaPublicationMetricsText(for publication: PublicationRecord, options: PublicationExportOptions) -> String? {
        guard
            options.includeClarivateSCIEJIF
                || options.includeQuartile
                || options.includeNorwegianList
                || options.includeCitations
        else {
            return nil
        }

        let journal = linkedJournal(of: publication)
        let impactFactorYear = metricPublicationYear(for: publication, mode: options.impactFactorYearMode)
        let quartileYear = metricPublicationYear(for: publication, mode: options.quartileYearMode)
        let norwegianYear = metricPublicationYear(for: publication, mode: options.norwegianListYearMode)
        let jifMetric = journal?.preferredMetric(
            for: [.clarivateScieJIF, .clarivateEsciJIF],
            publicationYear: impactFactorYear
        )
        let quartileMetric = journal?.preferredMetric(
            for: [.clarivateScieJIF, .clarivateEsciJIF],
            publicationYear: quartileYear
        )
        let norwegianMetric = journal?.metric(for: .norwegianList, publicationYear: norwegianYear)

        var parts: [String] = []
        if options.includeClarivateSCIEJIF, let jif = jifMetric?.value.nonEmpty {
            parts.append("IF \(jif)")
        }
        if options.includeQuartile, let quartile = quartileMetric?.quartile.nonEmpty {
            parts.append(quartile)
        }
        let exportLanguage = options.exportLanguage ?? language
        if options.includeNorwegianList, let norwegian = norwegianMetric?.value.nonEmpty {
            parts.append(exportLanguage.text("Norwegian list \(norwegian)", "Norska listan \(norwegian)"))
        }
        if options.includeCitations {
            parts.append(exportLanguage.text("\(publication.citationsValue) citations", "\(publication.citationsValue) citeringar"))
        }
        guard !parts.isEmpty else { return nil }
        return parts.joined(separator: ", ")
    }

    private func metricPublicationYear(
        for publication: PublicationRecord,
        mode: PublicationMetricYearMode
    ) -> Int? {
        switch mode {
        case .publicationYear:
            return publication.yearValue
        case .latestAvailable:
            return nil
        }
    }

    private func publicationCreditStatement(
        for publication: PublicationRecord,
        options: PublicationCreditStatementOptions
    ) -> String {
        let parts = PublicationCreditRole.allCases.compactMap { role -> String? in
            let authors = publication.authorNames
                .filter { publication.creditRoles(forAuthorName: $0).contains(role) }
                .map { authorName in
                    creditStatementAuthorLabel(
                        authorName,
                        publication: publication,
                        role: role,
                        options: options
                    )
                }
            guard !authors.isEmpty else { return nil }
            return "\(role.rawValue): \(naturalLanguageList(authors, conjunction: "and"))"
        }

        if parts.isEmpty {
            return "CRediT author statement."
        }
        return "CRediT author statement: \(parts.joined(separator: "; "))."
    }

    private func creditStatementAuthorLabel(
        _ authorName: String,
        publication: PublicationRecord,
        role: PublicationCreditRole,
        options: PublicationCreditStatementOptions
    ) -> String {
        let base = formattedCreditStatementAuthorName(
            authorName,
            nameFormat: options.nameFormat
        )
        guard options.includeContributionParentheses,
              let contribution = publication.creditRoleContribution(forAuthorName: authorName, role: role)
        else {
            return base
        }
        return "\(base) (\(contribution.statementValue))"
    }

    private func formattedCreditStatementAuthorName(
        _ authorName: String,
        nameFormat: PublicationCreditStatementNameFormat
    ) -> String {
        let normalized = authorName.trimmingCharacters(in: .whitespacesAndNewlines)
        let author = publicationAuthor(matchingPresentedName: normalized)
        let presentedName = author?.presentedNameVariant(matching: normalized)

        let fullName: String = {
            if let presentedName, let value = presentedName.displayName.trimmedOrNil {
                return value
            }
            return normalized
        }()

        let firstName: String = {
            if let presentedName, let value = presentedName.firstName.trimmedOrNil {
                return value
            }
            return parseName(fullName).firstName
        }()

        let lastName: String = {
            if let presentedName, let value = presentedName.lastName.trimmedOrNil {
                return value
            }
            let parsed = parseName(fullName).lastName
            return parsed.isEmpty ? fullName : parsed
        }()

        switch nameFormat {
        case .fullName:
            return fullName
        case .initials:
            let initials = initialsString(from: fullName)
            return initials.nonEmpty ?? fullName
        case .firstInitialAndLastName:
            let initial = initialsString(from: firstName).nonEmpty ?? initialsString(from: fullName)
            guard !initial.isEmpty else { return fullName }
            return "\(initial) \(lastName)"
        }
    }

    private func initialsString(from value: String) -> String {
        let tokens = value
            .split(whereSeparator: { !$0.isLetter })
            .compactMap { $0.first }
            .map { String($0).uppercased() + "." }
        return tokens.joined()
    }

    private func sharedAuthorshipMarker(for publication: PublicationRecord, at index: Int) -> String {
        if publication.sharedFirstAuthorship && index < min(2, publication.authorNames.count) {
            return "*"
        }
        if publication.sharedLastAuthorship && index >= max(0, publication.authorNames.count - 2) {
            return "*"
        }
        return ""
    }

    private func amaSharedAuthorshipNote(for publication: PublicationRecord, visibleAuthorIndices: Set<Int>? = nil) -> String {
        var notes: [String] = []
        let firstAuthorIndices = Set(0..<min(2, publication.authorNames.count))
        let lastAuthorStart = max(0, publication.authorNames.count - 2)
        let lastAuthorIndices = Set(lastAuthorStart..<publication.authorNames.count)
        let firstAuthorshipMarkerIsVisible = visibleAuthorIndices.map { !$0.isDisjoint(with: firstAuthorIndices) } ?? true
        let lastAuthorshipMarkerIsVisible = visibleAuthorIndices.map { !$0.isDisjoint(with: lastAuthorIndices) } ?? true

        if publication.sharedFirstAuthorship && firstAuthorshipMarkerIsVisible {
            notes.append("*Shared first authorship")
        }
        if publication.sharedLastAuthorship && lastAuthorshipMarkerIsVisible {
            notes.append("*Shared last authorship")
        }
        return notes.joined(separator: " ")
    }

    private func amaFormattedAuthorFromName(_ fullName: String) -> String {
        let particles = ["af", "al", "da", "de", "del", "der", "di", "du", "la", "le", "van", "von"]
        let parts = fullName.split(separator: " ").map(String.init)
        guard let last = parts.last else { return fullName }
        var lastNameParts = [last]
        var index = parts.count - 2
        while index >= 0 {
            let candidate = parts[index].lowercased()
            if particles.contains(candidate) {
                lastNameParts.insert(parts[index], at: 0)
                index -= 1
            } else {
                break
            }
        }
        let firstNameParts = Array(parts.prefix(index + 1))
        return amaFormattedAuthor(lastName: lastNameParts.joined(separator: " "), firstName: firstNameParts.joined(separator: " "), fallbackName: fullName)
    }

    private func amaFormattedAuthor(lastName: String, firstName: String, fallbackName: String) -> String {
        let last = lastName.trimmedOrNil ?? fallbackName
        let initials = firstName
            .split(whereSeparator: { !$0.isLetter })
            .compactMap { $0.first }
            .map { String($0).uppercased() }
            .joined()
        return initials.isEmpty ? last : "\(last) \(initials)"
    }

    private func normalizedDOI(_ raw: String) -> String {
        raw
            .replacingOccurrences(of: "https://doi.org/", with: "")
            .replacingOccurrences(of: "http://doi.org/", with: "")
            .replacingOccurrences(of: "doi.org/", with: "")
            .trimmingCharacters(in: .whitespacesAndNewlines)
    }

    private func publicationBibliographicDateText(
        for publication: PublicationRecord,
        options: PublicationExportOptions
    ) -> String? {
        if options.includePublicationDate,
           let publishedDate = publishedStatusDate(for: publication) {
            return formattedPublicationDate(publishedDate)
        }
        return publication.year.nonEmpty
    }

    private func publishedStatusDate(for publication: PublicationRecord) -> Date? {
        let timelineDates = publication.statusTimeline.compactMap { entry -> Date? in
            guard PublicationStatus.fromStored(entry.status) == .published,
                  let rawDate = entry.date?.trimmedOrNil else {
                return nil
            }
            return DateParsers.isoDay.date(from: rawDate)
        }
        if let latestTimelineDate = timelineDates.max() {
            return latestTimelineDate
        }

        guard PublicationStatus.fromStored(publication.statusLabel) == .published,
              let rawDate = publication.statusDate?.trimmedOrNil else {
            return nil
        }
        return DateParsers.isoDay.date(from: rawDate)
    }

    private func formattedPublicationDate(_ date: Date) -> String {
        let formatter = DateFormatter()
        formatter.calendar = Calendar(identifier: .gregorian)
        formatter.locale = Locale(identifier: "en_US_POSIX")
        formatter.dateFormat = "yyyy MMM d"
        return formatter.string(from: date)
    }

    private func formattedPublicationEpubDate(_ raw: String) -> String? {
        guard let date = raw.trimmedOrNil.flatMap(DateParsers.isoDay.date(from:)) else { return nil }
        return "Epub \(formattedPublicationDate(date))"
    }

    private func submissionAuthorRow(
        fallbackName: String,
        resolvedAuthor: PublicationAuthor?,
        creditRoles: [String],
        creditRoleContributions: [String: String]
    ) -> SubmissionAuthorExportRow {
        if let author = resolvedAuthor {
            let affiliation = author.primaryAffiliation
            return SubmissionAuthorExportRow(
                firstName: author.firstName,
                lastName: author.lastName,
                titleSv: author.titleSv,
                titleEn: author.titleEn,
                orcid: author.orcid,
                organizationSv: affiliation?.organizationSv ?? "",
                organizationEn: affiliation?.organizationEn ?? "",
                departmentSv: affiliation?.departmentSv ?? "",
                departmentEn: affiliation?.departmentEn ?? "",
                city: affiliation?.city ?? "",
                country: affiliation?.country ?? "",
                email: affiliation?.email ?? "",
                phoneLabel: author.phoneLabel,
                phoneNumber: author.phoneNumber,
                phoneLabelSecondary: author.phoneLabelSecondary,
                phoneNumberSecondary: author.phoneNumberSecondary,
                creditRoles: creditRoles,
                creditRoleContributions: creditRoleContributions
            )
        }

        let parsed = parseName(fallbackName)
        return SubmissionAuthorExportRow(
            firstName: parsed.firstName,
            lastName: parsed.lastName,
            titleSv: "",
            titleEn: "",
            orcid: "",
            organizationSv: "",
            organizationEn: "",
            departmentSv: "",
            departmentEn: "",
            city: "",
            country: "",
            email: "",
            phoneLabel: "",
            phoneNumber: "",
            phoneLabelSecondary: "",
            phoneNumberSecondary: "",
            creditRoles: creditRoles,
            creditRoleContributions: creditRoleContributions
        )
    }

    func normalizedProjectSubmissionCollaboratorNames(for project: ProjectRecord) -> [String] {
        Array(NSOrderedSet(array: project.collaboratorNames.compactMap(\.trimmedOrNil))) as? [String]
            ?? project.collaboratorNames.compactMap(\.trimmedOrNil)
    }

    func submissionAuthorRows(for publication: PublicationRecord) -> [SubmissionAuthorExportRow] {
        publication.authorNames.map { authorName in
            let creditRoles = publication.creditRoles(forAuthorName: authorName)
                .sorted { $0.sortIndex < $1.sortIndex }
                .map(\.rawValue)
            let creditRoleContributions = publication.creditRoleContributionMap(forAuthorName: authorName)
                .reduce(into: [String: String]()) { partialResult, entry in
                    partialResult[entry.key.rawValue] = entry.value.exportValue
                }
            return submissionAuthorRow(
                fallbackName: authorName,
                resolvedAuthor: publicationAuthor(named: authorName) ?? publicationAuthor(matchingPresentedName: authorName),
                creditRoles: creditRoles,
                creditRoleContributions: creditRoleContributions
            )
        }
    }

    func submissionAuthorRows(for project: ProjectRecord) -> [SubmissionAuthorExportRow] {
        normalizedProjectSubmissionCollaboratorNames(for: project).map { collaboratorName in
            submissionAuthorRow(
                fallbackName: collaboratorName,
                resolvedAuthor: publicationAuthor(matchingPresentedName: collaboratorName),
                creditRoles: [],
                creditRoleContributions: [:]
            )
        }
    }

    func submissionAuthorRows(for publications: [PublicationRecord]) -> [SubmissionAuthorExportRow] {
        struct Accumulator {
            var displayName: String
            var creditRoles: Set<String>
            var creditRoleContributions: [String: PublicationCreditRoleContribution]
        }

        var order: [String] = []
        var accumulators: [String: Accumulator] = [:]

        for publication in publications {
            for authorName in publication.authorNames {
                let matchedAuthor = publicationAuthor(matchingPresentedName: authorName)
                let key = matchedAuthor?.id ?? normalizedSearchFilterText(authorName)
                let roles = Set(publication.creditRoles(forAuthorName: authorName).map { $0.rawValue })
                let contributionsForAuthor = publication.creditRoleContributionMap(forAuthorName: authorName)
                    .reduce(into: [String: PublicationCreditRoleContribution]()) { partialResult, entry in
                        partialResult[entry.key.rawValue] = entry.value
                    }
                if var existing = accumulators[key] {
                    existing.creditRoles.formUnion(roles)
                    for (roleKey, contribution) in contributionsForAuthor {
                        if let current = existing.creditRoleContributions[roleKey] {
                            if contribution.sortPriority < current.sortPriority {
                                existing.creditRoleContributions[roleKey] = contribution
                            }
                        } else {
                            existing.creditRoleContributions[roleKey] = contribution
                        }
                    }
                    accumulators[key] = existing
                } else {
                    order.append(key)
                    accumulators[key] = Accumulator(
                        displayName: authorName,
                        creditRoles: roles,
                        creditRoleContributions: contributionsForAuthor
                    )
                }
            }
        }

        return order.compactMap { key in
            guard let accumulator = accumulators[key] else { return nil }
            let authorName = accumulator.displayName
            let creditRoles = accumulator.creditRoles.sorted()
            let creditRoleContributions = accumulator.creditRoleContributions
                .reduce(into: [String: String]()) { partialResult, entry in
                    partialResult[entry.key] = entry.value.exportValue
                }
            return submissionAuthorRow(
                fallbackName: authorName,
                resolvedAuthor: publicationAuthor(matchingPresentedName: authorName),
                creditRoles: creditRoles,
                creditRoleContributions: creditRoleContributions
            )
        }
    }

    func submissionAuthorWorkbookPayload(
        from rows: [SubmissionAuthorExportRow],
        configuration: SubmissionAuthorExportConfiguration
    ) -> SubmissionAuthorWorkbookPayload {
        let exportLanguage = configuration.effectiveExportLanguage
        switch configuration.mode {
        case .standard:
            return SubmissionAuthorWorkbookPayload(
                headers: standardSubmissionAuthorHeaders(language: exportLanguage),
                rows: rows.map { standardSubmissionAuthorRowValues($0, language: exportLanguage) }
            )
        case .editorialManager:
            return SubmissionAuthorWorkbookPayload(
                headers: [
                    "Title",
                    "First name",
                    "Last name",
                    "E-mail",
                    "ORCID",
                    "Institution",
                    "Country",
                    "CRediT",
                ],
                rows: rows.map {
                    [
                        $0.localizedTitle(language: .english),
                        $0.firstName,
                        $0.lastName,
                        $0.email,
                        $0.orcid,
                        $0.localizedOrganization(language: .english),
                        $0.country,
                        creditSummaryValue(for: $0),
                    ]
                }
            )
        case .custom:
            let order = configuration.columnOrder.isEmpty
                ? SubmissionAuthorExportColumn.customSelectableColumns
                : configuration.columnOrder
            let columns = order.filter { configuration.includedColumns.contains($0) }
            let resolvedColumns = columns.isEmpty ? SubmissionAuthorExportColumn.customSelectableColumns : columns
            return SubmissionAuthorWorkbookPayload(
                headers: resolvedColumns.map { submissionAuthorColumnHeader($0, language: exportLanguage) },
                rows: rows.map { row in
                    resolvedColumns.map { customSubmissionAuthorValue(for: $0, row: row, language: exportLanguage) }
                }
            )
        }
    }

    private func standardSubmissionAuthorHeaders(language: AppLanguage) -> [String] {
        [
            language == .swedish ? "Förnamn" : "First name",
            language == .swedish ? "Efternamn" : "Last name",
            language == .swedish ? "Titel" : "Title",
            "ORCID",
            language == .swedish ? "Organisation" : "Institution",
            language == .swedish ? "Avdelning" : "Department",
            language == .swedish ? "Ort" : "City",
            language == .swedish ? "Land" : "Country",
            "E-mail",
            language == .swedish ? "Telefonetikett" : "Phone label",
            language == .swedish ? "Telefon" : "Phone",
            language == .swedish ? "Telefonetikett 2" : "Phone label 2",
            language == .swedish ? "Telefon 2" : "Phone 2",
        ] + PublicationCreditRole.allCases.map(\.rawValue)
    }

    private func standardSubmissionAuthorRowValues(
        _ row: SubmissionAuthorExportRow,
        language: AppLanguage
    ) -> [String] {
        [
            row.firstName,
            row.lastName,
            row.localizedTitle(language: language),
            row.orcid,
            row.localizedOrganization(language: language),
            row.localizedDepartment(language: language),
            row.city,
            row.country,
            row.email,
            row.phoneLabel,
            row.phoneNumber,
            row.phoneLabelSecondary,
            row.phoneNumberSecondary,
        ] + PublicationCreditRole.allCases.map { role in
            creditRoleMatrixValue(for: role, row: row)
        }
    }

    private func creditRoleMatrixValue(
        for role: PublicationCreditRole,
        row: SubmissionAuthorExportRow
    ) -> String {
        guard row.creditRoles.contains(role.rawValue) else { return "" }
        return row.creditRoleContributions[role.rawValue] ?? "X"
    }

    private func creditSummaryValue(for row: SubmissionAuthorExportRow) -> String {
        PublicationCreditRole.allCases.compactMap { role in
            guard row.creditRoles.contains(role.rawValue) else { return nil }
            if let contribution = row.creditRoleContributions[role.rawValue]?.trimmedOrNil {
                return "\(role.rawValue) (\(contribution))"
            }
            return role.rawValue
        }
        .joined(separator: "; ")
    }

