        case .supervision:
            return PublicationCreditRole.supervision.rawValue
        case .validation:
            return PublicationCreditRole.validation.rawValue
        case .visualization:
            return PublicationCreditRole.visualization.rawValue
        case .writingOriginalDraft:
            return PublicationCreditRole.writingOriginalDraft.rawValue
        case .writingReviewEditing:
            return PublicationCreditRole.writingReviewEditing.rawValue
        }
    }

    private func customSubmissionAuthorValue(
        for column: SubmissionAuthorExportColumn,
        row: SubmissionAuthorExportRow,
        language: AppLanguage
    ) -> String {
        if let role = column.creditRole {
            return creditRoleMatrixValue(for: role, row: row)
        }
        switch column {
        case .title:
            return row.localizedTitle(language: language)
        case .firstName:
            return row.firstName
        case .lastName:
            return row.lastName
        case .email:
            return row.email
        case .orcid:
            return row.orcid
        case .organization:
            return row.localizedOrganization(language: language)
        case .department:
            return row.localizedDepartment(language: language)
        case .city:
            return row.city
        case .country:
            return row.country
        case .phoneLabel:
            return row.phoneLabel
        case .phoneNumber:
            return row.phoneNumber
        case .phoneLabelSecondary:
            return row.phoneLabelSecondary
        case .phoneNumberSecondary:
            return row.phoneNumberSecondary
        case .creditSummary:
            return creditSummaryValue(for: row)
        case .conceptualization, .dataCuration, .formalAnalysis, .fundingAcquisition,
            .investigation, .methodology, .projectAdministration, .resources,
            .software, .supervision, .validation, .visualization,
            .writingOriginalDraft, .writingReviewEditing:
            return ""
        }
    }

    func parseName(_ fullName: String) -> (firstName: String, lastName: String) {
        let trimmed = fullName.trimmingCharacters(in: .whitespacesAndNewlines)
        let parts = trimmed.split(separator: " ", omittingEmptySubsequences: true).map(String.init)
        guard parts.count > 1 else {
            return (trimmed, "")
        }
        return (parts.dropLast().joined(separator: " "), parts.last ?? "")
    }

    private func authorNameVariants(for author: PublicationAuthor) -> Set<String> {
        Set(author.presentedNameCandidates.compactMap { $0.trimmedOrNil })
    }

    private func preservedAuthorNameVariantsAfterRename(
        from previousAuthor: PublicationAuthor,
        to newName: String
    ) -> [String] {
        guard authorHasCompletePrimaryName(previousAuthor) else { return [] }
        let newNameKey = normalizedPersonLookupName(newName)
        let placeholderNames = ["New author", "Ny författare"]
        let placeholderKeys = Set(placeholderNames.map(normalizedPersonLookupName))
        let placeholderLastNameKeys = Set(placeholderNames.map { normalizedPersonLookupName(parseName($0).lastName) })
            .filter { !$0.isEmpty }
        let previousLastNameKey = normalizedPersonLookupName(previousAuthor.lastName)

        return authorNameVariants(for: previousAuthor)
            .filter { candidate in
                let key = normalizedPersonLookupName(candidate)
                let candidateLastNameKey = normalizedPersonLookupName(parseName(candidate).lastName)
                return !key.isEmpty
                    && key != newNameKey
                    && !placeholderKeys.contains(key)
                    && !(candidateLastNameKey == previousLastNameKey && placeholderLastNameKeys.contains(candidateLastNameKey))
            }
            .sorted { $0.localizedStandardCompare($1) == .orderedAscending }
    }

    private func authorHasCompletePrimaryName(_ author: PublicationAuthor) -> Bool {
        author.firstName.trimmedOrNil != nil && author.lastName.trimmedOrNil != nil
    }

    private func canonicalAuthorDisplayName(for author: PublicationAuthor) -> String {
        author.displayName.trimmedOrNil
            ?? author.name.trimmedOrNil
            ?? [author.firstName.nonEmpty, author.lastName.nonEmpty].compactMap { $0 }.joined(separator: " ").trimmedOrNil
            ?? author.id
    }

    private func synchronizedAuthorIDs(
        existingIDs: [String],
        names: [String],
        preserveUnknownIDs: Bool = false
    ) -> [String] {
        let knownAuthorIDs = Set(publicationAuthors.map(\.id))
        var ids: [String] = []
        for id in existingIDs.compactMap(\.trimmedOrNil) where preserveUnknownIDs || knownAuthorIDs.isEmpty || knownAuthorIDs.contains(id) {
            ids.append(id)
        }
        for name in names.compactMap(\.trimmedOrNil) {
            guard let authorID = publicationAuthor(matchingPresentedName: name)?.id else { continue }
            ids.append(authorID)
        }
        return uniquedNonEmptyStrings(ids)
    }

    /// F13b: the id links for a list of people that is edited by name
    /// (co-applicants, project members, publication authors, task and meeting
    /// participants). Each name that matches a researcher gets that
    /// researcher's id, in the same order as the names; a name that matches
    /// nobody gets no id, and a name that is removed takes its id with it. The
    /// names themselves are display text and are never changed here.
    /// Until researchers are loaded the stored ids are kept as they are.
    func synchronizedPersonAuthorIDs(existingIDs: [String], names: [String]) -> [String] {
        guard !publicationAuthors.isEmpty else {
            return uniquedNonEmptyStrings(existingIDs)
        }
        var ids: [String] = []
        for name in names {
            guard let authorID = publicationAuthorID(forPresentedName: name) else { continue }
            ids.append(authorID)
        }
        return uniquedNonEmptyStrings(ids)
    }

    /// F13b: the id of the first person in a name list (main applicant,
    /// project leader). The stored first id is used when the first name still
    /// belongs to that researcher; an unsaved edit that reorders the names
    /// therefore never picks up a stale id. Nil when the first person has no id.
    /// F13d: when the first name no longer matches any researcher (the old
    /// spelling was removed after a rename) but every name got an id when the
    /// record was saved, the ids still line up with the names and the stored
    /// first id is used.
    func firstPersonAuthorID(ids: [String], names: [String]) -> String? {
        guard let firstID = ids.first?.trimmedOrNil,
              let firstName = names.first?.trimmedOrNil else {
            return nil
        }
        let firstNameID = publicationAuthorID(forPresentedName: firstName)
        if firstNameID == firstID {
            return firstID
        }
        if firstNameID == nil,
           ids.count == names.count,
           publicationAuthor(id: firstID) != nil {
            return firstID
        }
        return nil
    }

    private func synchronizedCongressParticipantAuthorIDs(_ congress: inout OrganizationCongress) {
        congress.participantNames = uniquedNonEmptyStrings(congress.participantNames)
        congress.participantAuthorIDs = synchronizedAuthorIDs(
            existingIDs: congress.participantAuthorIDs,
            names: congress.participantNames
        )
        let existingNameKeys = Set(congress.participantNames.map(normalizedPersonLookupName).filter { !$0.isEmpty })
        for authorID in congress.participantAuthorIDs {
            guard let author = publicationAuthor(id: authorID) else { continue }
            let displayName = canonicalAuthorDisplayName(for: author)
            let key = normalizedPersonLookupName(displayName)
            guard !key.isEmpty, !existingNameKeys.contains(key) else { continue }
            congress.participantNames.append(displayName)
        }
        congress.participantNames = uniquedNonEmptyStrings(congress.participantNames)
    }

    private func synchronizedConferenceContributionAuthorIDs(_ contribution: inout CVConferenceContribution) {
        contribution.contributorNames = uniquedNonEmptyStrings(contribution.contributorNames)
        contribution.contributorAuthorIDs = synchronizedAuthorIDs(
            existingIDs: contribution.contributorAuthorIDs,
            names: contribution.contributorNames
        )
        if let presentedBy = contribution.presentedBy.trimmedOrNil,
           let author = publicationAuthor(matchingPresentedName: presentedBy) {
            contribution.presentedByAuthorID = author.id
        } else if let authorID = contribution.presentedByAuthorID?.trimmedOrNil,
                  publicationAuthor(id: authorID) == nil,
                  !publicationAuthors.isEmpty {
            contribution.presentedByAuthorID = nil
        }

        if contribution.presentedBy.trimmedOrNil == nil,
           let presentedByAuthorID = contribution.presentedByAuthorID?.trimmedOrNil,
           let author = publicationAuthor(id: presentedByAuthorID) {
            contribution.presentedBy = canonicalAuthorDisplayName(for: author)
        }

        let existingNameKeys = Set(contribution.contributorNames.map(normalizedPersonLookupName).filter { !$0.isEmpty })
        for authorID in contribution.contributorAuthorIDs {
            guard let author = publicationAuthor(id: authorID) else { continue }
            let displayName = canonicalAuthorDisplayName(for: author)
            let key = normalizedPersonLookupName(displayName)
            guard !key.isEmpty, !existingNameKeys.contains(key) else { continue }
            contribution.contributorNames.append(displayName)
        }
        contribution.contributorNames = uniquedNonEmptyStrings(contribution.contributorNames)
    }

    private func canonicalizedConferenceContribution(_ contribution: CVConferenceContribution) -> CVConferenceContribution {
        var normalized = contribution
        normalized.normalize()

        if let canonicalPresentedBy = publicationAuthor(
            matchingPresentedName: normalized.presentedBy,
            includeNameVariants: false
        )?.name {
            normalized.presentedBy = canonicalPresentedBy
        }
        normalized.contributorNames = normalized.contributorNames.map { contributor in
            publicationAuthor(
                matchingPresentedName: contributor,
                includeNameVariants: false
            )?.name ?? contributor
        }
        synchronizedConferenceContributionAuthorIDs(&normalized)

        // F13 / "Alla kopplingar via id": the project by id. The id decides;
        // the written name only moves the link when it clearly names another
        // project, and an empty name clears it.
        let writtenProjectNames = [normalized.projectNameSv, normalized.projectNameEn].compactMap(\.trimmedOrNil)
        let canonicalProject: ProjectRecord?
        if writtenProjectNames.isEmpty {
            canonicalProject = nil
        } else if let linked = project(id: normalized.projectID) {
            let linkedNames = Set([linked.nameSv, linked.nameEn].map(Self.normalizedIDLinkName))
            let namedProject = writtenProjectNames.compactMap { project(named: $0) }.first
            if let namedProject, namedProject.id == linked.id {
                canonicalProject = namedProject
            } else if writtenProjectNames.contains(where: { linkedNames.contains(Self.normalizedIDLinkName($0)) }) {
                canonicalProject = linked
            } else if let namedProject, namedProject.id != linked.id {
                canonicalProject = namedProject
            } else {
                canonicalProject = linked
            }
        } else {
            canonicalProject = writtenProjectNames.compactMap { project(named: $0) }.first
        }
        if let canonicalProject {
            normalized.projectID = canonicalProject.id
            normalized.projectNameSv = canonicalProject.nameSv
            normalized.projectNameEn = canonicalProject.nameEn.nonEmpty ?? canonicalProject.nameSv
        } else {
            normalized.projectID = nil
        }

        if let organizationID = normalized.congressOrganizationID,
           organization(id: organizationID) == nil {
            normalized.congressOrganizationID = nil
            normalized.congressID = nil
            normalized.congressLink = ""
        }
        if let organization = organization(id: normalized.congressOrganizationID),
           let congressID = normalized.congressID,
           organization.congresses.contains(where: { $0.id == congressID }) == false {
            normalized.congressID = nil
            normalized.congressLink = ""
        }

        if let resolvedJournal = publicationJournal(id: normalized.journalID) ?? publicationJournal(named: normalized.journalName) {
            normalized.journalID = resolvedJournal.id
            normalized.journalName = resolvedJournal.name
        } else if normalized.journalID != nil {
            normalized.journalID = nil
        }

        normalized.normalize()
        return normalized
    }

    private func canonicalizedReviewEntry(_ entry: CVReviewEntry) -> CVReviewEntry {
        var normalized = entry
        normalized.normalize()
        if normalized.category == .journalReview {
            // "Alla kopplingar via id": the id decides; the written name only
            // moves the link when it names another journal.
            if let resolvedJournal = Self.idFirstLinkedRecord(
                id: normalized.journalID,
                name: normalized.journalName,
                byID: { publicationJournal(id: $0) },
                byName: { publicationJournal(named: $0) },
                recordID: { $0.id },
                recordNames: { [$0.name, $0.abbreviatedName, $0.issnLTWAAbbreviatedName] }
            ) {
                normalized.journalID = resolvedJournal.id
                normalized.journalName = resolvedJournal.name
            } else {
                normalized.journalID = nil
            }
        } else {
            normalized.journalName = ""
            normalized.journalID = nil
        }
        // "Alla kopplingar via id": the organization by id. The written name
        // stays as it is (it is shown in the language it was written in)
        // unless it no longer names the linked organization, for example
        // after a rename; then it becomes the organization's name.
        if let resolvedOrganization = Self.idFirstLinkedRecord(
            id: normalized.organizationID,
            name: normalized.organizationName,
            byID: { organization(id: $0) },
            byName: { uniqueOrganization(matchingName: $0) },
            recordID: { $0.id },
            recordNames: { [$0.nameSv, $0.nameEn] }
        ) {
            normalized.organizationID = resolvedOrganization.id
            let writtenKey = Self.normalizedIDLinkName(normalized.organizationName)
            if ![resolvedOrganization.nameSv, resolvedOrganization.nameEn]
                .contains(where: { Self.normalizedIDLinkName($0) == writtenKey }) {
                normalized.organizationName = resolvedOrganization.nameSv
            }
        } else {
            normalized.organizationID = nil
        }
        normalized.normalize()
        return normalized
    }

    private func defaultCurrentUserAuthorID() -> String? {
        currentUserAuthor()?.id
    }

    private func synchronizedTeachingAssignmentAuthorID(_ assignment: inout TeachingAssignment) {
        if assignment.authorID?.trimmedOrNil == nil {
            assignment.authorID = defaultCurrentUserAuthorID()
        }
    }

    private func synchronizedMediaAppearanceAuthorID(_ appearance: inout CVMediaAppearance) {
        if appearance.authorIDs.isEmpty, let legacyAuthorID = appearance.authorID?.trimmedOrNil {
            appearance.authorIDs = [legacyAuthorID]
        }
        appearance.authorID = appearance.authorIDs.first
    }

    private func synchronizedReviewEntryAuthorID(_ entry: inout CVReviewEntry) {
        if entry.authorID?.trimmedOrNil == nil {
            entry.authorID = defaultCurrentUserAuthorID()
        }
    }

    private func propagateAuthorRename(from oldVariants: Set<String>, to newName: String) {
        for recordIndex in publicationRecords.indices {
            publicationRecords[recordIndex].authorNames = uniquedNonEmptyStrings(publicationRecords[recordIndex].authorNames.map {
                oldVariants.contains($0) ? newName : $0
            })
            if let correspondingAuthorName = publicationRecords[recordIndex].correspondingAuthorName,
               oldVariants.contains(correspondingAuthorName) {
                publicationRecords[recordIndex].correspondingAuthorName = newName
            }
            for assignmentIndex in publicationRecords[recordIndex].creditRoleAssignments.indices where oldVariants.contains(publicationRecords[recordIndex].creditRoleAssignments[assignmentIndex].authorName) {
                publicationRecords[recordIndex].creditRoleAssignments[assignmentIndex].authorName = newName
            }
            replaceTaskParticipantNames(&publicationRecords[recordIndex].publicationTasks, from: oldVariants, to: newName)
            publicationRecords[recordIndex].normalize()
        }
        for applicationIndex in applications.indices {
            applications[applicationIndex].coApplicants = uniquedNonEmptyStrings(applications[applicationIndex].coApplicants.map {
                oldVariants.contains($0) ? newName : $0
            })
        }
        for projectIndex in projects.indices {
            projects[projectIndex].collaboratorNames = uniquedNonEmptyStrings(projects[projectIndex].collaboratorNames.map {
                oldVariants.contains($0) ? newName : $0
            })
            replaceTaskParticipantNames(&projects[projectIndex].projectTasks, from: oldVariants, to: newName)
        }
        for assignmentIndex in teachingAssignments.indices where oldVariants.contains(teachingAssignments[assignmentIndex].studentName) {
            teachingAssignments[assignmentIndex].studentName = newName
        }
        for candidateIndex in doctoralCandidates.indices {
            if oldVariants.contains(doctoralCandidates[candidateIndex].candidateName) {
                doctoralCandidates[candidateIndex].candidateName = newName
            }
            for supervisorIndex in doctoralCandidates[candidateIndex].supervisors.indices where oldVariants.contains(doctoralCandidates[candidateIndex].supervisors[supervisorIndex].name) {
                doctoralCandidates[candidateIndex].supervisors[supervisorIndex].name = newName
            }
        }
        for contributionIndex in cvConferenceContributions.indices {
            if oldVariants.contains(cvConferenceContributions[contributionIndex].presentedBy) {
                cvConferenceContributions[contributionIndex].presentedBy = newName
            }
            cvConferenceContributions[contributionIndex].contributorNames = uniquedNonEmptyStrings(cvConferenceContributions[contributionIndex].contributorNames.map {
                oldVariants.contains($0) ? newName : $0
            })
            replaceTaskParticipantNames(&cvConferenceContributions[contributionIndex].tasks, from: oldVariants, to: newName)
            cvConferenceContributions[contributionIndex] = canonicalizedConferenceContribution(cvConferenceContributions[contributionIndex])
        }
    }

    private func propagateProjectRename(from oldName: String, to project: ProjectRecord) {
        // "Alla kopplingar via id": the id lookup knows the new name before
        // the linked records are tidied below, so they keep their link.
        projectByID[project.id] = project
        if projectByName[oldName]?.id == project.id {
            projectByName[oldName] = nil
        }
        projectByName[project.nameSv] = project
        for appIndex in applications.indices where applications[appIndex].projectID == project.id || (applications[appIndex].projectID == nil && applications[appIndex].projectType == oldName) {
            applications[appIndex].projectID = project.id
            applications[appIndex].projectType = project.nameSv
        }
        for recordIndex in publicationRecords.indices where publicationRecords[recordIndex].projectID == project.id || (publicationRecords[recordIndex].projectID == nil && publicationRecords[recordIndex].projectName == oldName) {
            publicationRecords[recordIndex].projectID = project.id
            publicationRecords[recordIndex].projectName = project.nameSv
        }
        for contributionIndex in cvConferenceContributions.indices {
            if cvConferenceContributions[contributionIndex].projectID == project.id ||
                (cvConferenceContributions[contributionIndex].projectID == nil
                    && (cvConferenceContributions[contributionIndex].projectNameSv == oldName
                        || cvConferenceContributions[contributionIndex].projectNameEn == oldName)) {
                cvConferenceContributions[contributionIndex].projectID = project.id
                cvConferenceContributions[contributionIndex].projectNameSv = project.nameSv
                cvConferenceContributions[contributionIndex].projectNameEn = project.nameEn.nonEmpty ?? project.nameSv
            }
            cvConferenceContributions[contributionIndex] = canonicalizedConferenceContribution(cvConferenceContributions[contributionIndex])
        }
    }

    private func propagateJournalRename(from oldName: String, to journal: PublicationJournal) {
        // "Alla kopplingar via id": the id lookup knows the new name before
        // the linked records are tidied below, so they keep their link.
        publicationJournalByID[journal.id] = journal
        for recordIndex in publicationRecords.indices {
            if publicationRecords[recordIndex].journalID == journal.id || (publicationRecords[recordIndex].journalID == nil && publicationRecords[recordIndex].journal == oldName) {
                publicationRecords[recordIndex].journalID = journal.id
                publicationRecords[recordIndex].journal = journal.name
            }
            for attemptIndex in publicationRecords[recordIndex].previousAttempts.indices
            where publicationRecords[recordIndex].previousAttempts[attemptIndex].journalID == journal.id
                || (publicationRecords[recordIndex].previousAttempts[attemptIndex].journalID == nil
                    && publicationRecords[recordIndex].previousAttempts[attemptIndex].journal == oldName) {
                publicationRecords[recordIndex].previousAttempts[attemptIndex].journalID = journal.id
                publicationRecords[recordIndex].previousAttempts[attemptIndex].journal = journal.name
            }
            // "Alla kopplingar via id": the dated submission steps show the
            // renamed journal too, so the journal's page keeps finding them.
            let recordPointsToJournal = publicationRecords[recordIndex].journalID == journal.id
                || publicationRecords[recordIndex].previousAttempts.contains { $0.journalID == journal.id }
            for entryIndex in publicationRecords[recordIndex].statusTimeline.indices
            where recordPointsToJournal && publicationRecords[recordIndex].statusTimeline[entryIndex].journal == oldName {
                publicationRecords[recordIndex].statusTimeline[entryIndex].journal = journal.name
            }
        }
        for contributionIndex in cvConferenceContributions.indices {
            if cvConferenceContributions[contributionIndex].journalID == journal.id ||
                (cvConferenceContributions[contributionIndex].journalID == nil
                    && cvConferenceContributions[contributionIndex].journalName == oldName) {
                cvConferenceContributions[contributionIndex].journalID = journal.id
                cvConferenceContributions[contributionIndex].journalName = journal.name
            }
            cvConferenceContributions[contributionIndex] = canonicalizedConferenceContribution(cvConferenceContributions[contributionIndex])
        }
        for reviewIndex in cvReviewEntries.indices
        where cvReviewEntries[reviewIndex].journalID == journal.id || (cvReviewEntries[reviewIndex].journalID == nil && cvReviewEntries[reviewIndex].journalName == oldName) {
            cvReviewEntries[reviewIndex].journalID = journal.id
            cvReviewEntries[reviewIndex].journalName = journal.name
            cvReviewEntries[reviewIndex] = canonicalizedReviewEntry(cvReviewEntries[reviewIndex])
        }
    }

    private func pendingSelectionPersistenceSet(for kind: PendingSelectionEntityKind, entityID: String) -> PersistenceSet {
        guard let pending = pendingSelectionReturn,
              pending.entityKind == kind,
              pending.entityID == entityID
        else {
            return []
        }

        switch pending.destination {
        case .application:
            return [.applications]
        case .publication:
            return [.publicationRecords]
        case .project:
            return [.projects]
        }
    }

    @discardableResult
    func finalizePendingSelectionIfNeeded(for kind: PendingSelectionEntityKind, entityID: String, canonicalValue: String) -> PersistenceSet {
        let affectedSet = pendingSelectionPersistenceSet(for: kind, entityID: entityID)
        guard let pending = pendingSelectionReturn,
              pending.entityKind == kind,
              pending.entityID == entityID
        else {
            return []
        }

        switch pending.destination {
        case let .application(recordID, field):
            guard let index = applications.firstIndex(where: { $0.id == recordID }) else {
                pendingSelectionReturn = nil
                return []
            }
            var updated = applications[index]
            switch field {
            // "Alla kopplingar via id": the record that was just created is
            // linked by its id.
            case .organization:
                updated.organizationID = resolvedOrganization(id: entityID, name: canonicalValue)?.id
                updated.organization = canonicalValue
            case .project:
                updated.projectID = resolvedProject(id: entityID, name: canonicalValue)?.id
                updated.projectType = canonicalValue
                if updated.coApplicants.isEmpty,
                   let collaborators = project(named: canonicalValue)?.collaboratorNames,
                   !collaborators.isEmpty {
                    updated.coApplicants = collaborators
                }
            case .manager:
                updated.applicationManagerID = resolvedManager(id: entityID, name: canonicalValue)?.id
                updated.applicationManager = canonicalValue
            case let .coApplicant(applicantIndex):
                if applicantIndex < updated.coApplicants.count {
                    updated.coApplicants[applicantIndex] = canonicalValue
                } else {
                    updated.coApplicants.append(canonicalValue)
                }
                var seen = Set<String>()
                updated.coApplicants = updated.coApplicants.filter { seen.insert($0).inserted }
            }
            updated.refreshDerivedValues()
            updated.coApplicantAuthorIDs = synchronizedPersonAuthorIDs(
                existingIDs: updated.coApplicantAuthorIDs,
                names: updated.coApplicants
            )
            applications[index] = updated
            route = AppRoute(recordID: recordID, destination: .applications)
        case let .publication(recordID, field):
            guard let index = publicationRecords.firstIndex(where: { $0.id == recordID }) else {
                pendingSelectionReturn = nil
                return []
            }
            let previous = publicationRecords[index]
            var updated = previous
            switch field {
            case .project:
                updated.projectID = resolvedProject(id: entityID, name: canonicalValue)?.id
                updated.projectName = canonicalValue
                if updated.authorNames.isEmpty,
                   let collaborators = project(named: canonicalValue)?.collaboratorNames,
                   !collaborators.isEmpty {
                    updated.authorNames = collaborators
                }
            case let .author(authorIndex):
                if authorIndex < updated.authorNames.count {
                    updated.authorNames[authorIndex] = canonicalValue
                } else {
                    updated.authorNames.append(canonicalValue)
                }
                var seen = Set<String>()
                updated.authorNames = updated.authorNames.filter { seen.insert($0).inserted }
            case let .journalStatus(statusIndex):
                while updated.statusTimeline.count <= statusIndex {
                    updated.statusTimeline.append(PublicationStatusEntry(status: "", journal: "", date: nil))
                }
                updated.statusTimeline[statusIndex].journal = canonicalValue
                updated.journal = canonicalValue
                updated.journalID = publicationJournal(id: entityID)?.id ?? publicationJournal(named: canonicalValue)?.id
            }
            updated.normalize()
            updated = derivePublicationFields(for: updated, previous: previous)
            publicationRecords[index] = updated
            route = AppRoute(recordID: recordID, destination: .publications)
        case let .project(recordID, field):
            guard let index = projects.firstIndex(where: { $0.id == recordID }) else {
                pendingSelectionReturn = nil
                return []
            }
            var updated = projects[index]
            switch field {
            case let .collaborator(collaboratorIndex):
                if collaboratorIndex < updated.collaboratorNames.count {
                    updated.collaboratorNames[collaboratorIndex] = canonicalValue
                } else {
                    updated.collaboratorNames.append(canonicalValue)
                }
                var seen = Set<String>()
                updated.collaboratorNames = updated.collaboratorNames.filter { seen.insert($0).inserted }
            }
            updated.collaboratorAuthorIDs = synchronizedPersonAuthorIDs(
                existingIDs: updated.collaboratorAuthorIDs,
                names: updated.collaboratorNames
            )
            projects[index] = updated
            route = AppRoute(recordID: recordID, destination: .projects)
        }

        pendingSelectionReturn = nil
        return affectedSet
    }

    func updateOrganization(
        id: String,
        nameSv: String,
        nameEn: String,
        addressLine: String,
        postalCode: String,
        city: String,
        country: String,
        category: String?,
        roles: [OrganizationRole],
        note: String?,
        websiteURL: String,
        phoneNumber: String,
        organizationNumber: String,
        vatNumber: String,
        employerContacts: [OrganizationEmployerContact],
        flag: String,
        membershipFrom: String,
        membershipTo: String,
        congresses: [OrganizationCongress],
        projectTasks: [ProjectTaskItem],
        salaryCalculator: ManagerSalaryCalculator?,
        actionName: String? = nil,
        completePendingSelection: Bool = false
    ) {
        guard let index = organizations.firstIndex(where: { $0.id == id }) else { return }
        let previousOrganization = organizations[index]
        let oldValue = previousOrganization.nameSv
        // Round 7: researcher rows linked to the organization follow a rename.
        let hasLinkedResearcherRows = OrganizationTree.hasRows(linkedTo: id, in: publicationAuthors)

        performUndoableChange(
            actionName: language.text("Edit organization", "Redigera organisation"),
            successMessage: language.text("Updated organizations.", "Uppdaterade organisationer."),
            failureMessage: language.text("Could not update organizations.", "Kunde inte uppdatera organisationer."),
            scope: hasLinkedResearcherRows ? .organizationTree : .organizations
        ) {
            var updated = normalizedOption(
                nameSv: nameSv,
                nameEn: nameEn,
                addressLine: addressLine,
                postalCode: postalCode,
                city: city,
                country: country,
                category: category,
                roles: roles,
                note: note,
                websiteURL: websiteURL,
                phoneNumber: phoneNumber,
                organizationNumber: organizationNumber,
                vatNumber: vatNumber,
                employerContacts: employerContacts,
                flag: flag,
                membershipFrom: membershipFrom,
                membershipTo: membershipTo,
                congresses: congresses,
                salaryCalculator: salaryCalculator,
                projectTasks: projectTasks,
                fallback: oldValue,
                excluding: oldValue,
                within: organizations
            )
            updated.id = previousOrganization.id
            updated.units = previousOrganization.units
            updated.addressNameEn = previousOrganization.addressNameEn
            updated.addressOrder = previousOrganization.addressOrder
            updated.usesAsApplicationSalaryCalculator = previousOrganization.usesAsApplicationSalaryCalculator
            updated.legacyMaxOverheadPercent = previousOrganization.legacyMaxOverheadPercent
            updated.overheadRule = previousOrganization.overheadRule
            updated.overheadRuleExceptions = previousOrganization.overheadRuleExceptions
            updated.managerOverheadPercent = previousOrganization.managerOverheadPercent
            let congressesChanged = previousOrganization.congresses != updated.congresses
            organizations[index] = updated
            if hasLinkedResearcherRows {
                let officialNames = OrganizationTree.applyingOfficialNames(
                    to: publicationAuthors,
                    organizations: organizations,
                    onlyOrganizationIDs: [updated.id]
                )
                if !officialNames.report.isEmpty {
                    publicationAuthors = officialNames.authors
                }
            }
            invalidateSQLitePrimaryCongressReadCache()
            forceOrganizationRowSnapshotGenerationIfNeeded(congressesChanged: congressesChanged)
            migrateRememberedSelectionID(from: previousOrganization.id, to: updated.id, destinations: [.organizations])
            for appIndex in applications.indices where applications[appIndex].organizationID == updated.id || (applications[appIndex].organizationID == nil && applications[appIndex].organization == oldValue) {
                applications[appIndex].organizationID = updated.id
                applications[appIndex].organization = updated.nameSv
            }
            for appIndex in applications.indices where applications[appIndex].applicationManagerID == updated.id || (applications[appIndex].applicationManagerID == nil && applications[appIndex].applicationManager == oldValue) {
                applications[appIndex].applicationManagerID = updated.id
                applications[appIndex].applicationManager = updated.nameSv
            }
            for courseIndex in teachingCourses.indices where teachingCourses[courseIndex].institutionID == updated.id || (teachingCourses[courseIndex].institutionID == nil && teachingCourses[courseIndex].institution == oldValue) {
                teachingCourses[courseIndex].institutionID = updated.id
                teachingCourses[courseIndex].institution = updated.nameSv
            }
            for componentIndex in teachingComponents.indices where teachingComponents[componentIndex].institutionID == updated.id || (teachingComponents[componentIndex].institutionID == nil && teachingComponents[componentIndex].institution == oldValue) {
                teachingComponents[componentIndex].institutionID = updated.id
                teachingComponents[componentIndex].institution = updated.nameSv
            }
            managers = derivedManagers(from: organizations)
            if completePendingSelection {
                finalizePendingSelectionIfNeeded(for: .organization, entityID: updated.id, canonicalValue: updated.nameSv)
                finalizePendingSelectionIfNeeded(for: .manager, entityID: updated.id, canonicalValue: updated.nameSv)
            }
        }
    }

    func autosaveOrganization(
        id: String,
        nameSv: String,
        nameEn: String,
        addressLine: String,
        postalCode: String,
        city: String,
        country: String,
        category: String?,
        roles: [OrganizationRole],
        note: String?,
        websiteURL: String,
        phoneNumber: String,
        organizationNumber: String,
        vatNumber: String,
        employerContacts: [OrganizationEmployerContact],
        flag: String,
        membershipFrom: String,
        membershipTo: String,
        congresses: [OrganizationCongress],
        projectTasks: [ProjectTaskItem],
        salaryCalculator: ManagerSalaryCalculator?,
        actionName: String? = nil,
        completePendingSelection: Bool = false
    ) {
        guard let index = organizations.firstIndex(where: { $0.id == id }) else { return }
        let previousOrganization = organizations[index]
        let oldValue = previousOrganization.nameSv
        let previousOrganizations = organizations
        let previousApplications = applications
        let previousManagers = managers
        let previousTeachingCourses = teachingCourses
        let previousPublicationAuthors = publicationAuthors
        let previousReviewEntries = cvReviewEntries
        let previousDoctoralCandidates = doctoralCandidates

            do {
                var updated = normalizedOption(
                nameSv: nameSv,
                nameEn: nameEn,
                addressLine: addressLine,
                postalCode: postalCode,
                city: city,
                country: country,
                category: category,
                roles: roles,
                note: note,
                websiteURL: websiteURL,
                phoneNumber: phoneNumber,
                organizationNumber: organizationNumber,
                vatNumber: vatNumber,
                employerContacts: employerContacts,
                flag: flag,
                membershipFrom: membershipFrom,
                membershipTo: membershipTo,
                congresses: congresses,
                salaryCalculator: salaryCalculator,
                projectTasks: projectTasks,
                fallback: oldValue,
                excluding: oldValue,
                within: organizations
            )
            updated.id = previousOrganization.id
            updated.units = previousOrganization.units
            updated.addressNameEn = previousOrganization.addressNameEn
            updated.addressOrder = previousOrganization.addressOrder
            updated.usesAsApplicationSalaryCalculator = previousOrganization.usesAsApplicationSalaryCalculator
            updated.legacyMaxOverheadPercent = previousOrganization.legacyMaxOverheadPercent
            updated.overheadRule = previousOrganization.overheadRule
            updated.overheadRuleExceptions = previousOrganization.overheadRuleExceptions
            updated.managerOverheadPercent = previousOrganization.managerOverheadPercent
            let pendingSelectionAffectedSet: PersistenceSet = completePendingSelection
                ? pendingSelectionPersistenceSet(for: .organization, entityID: updated.id)
                    .union(pendingSelectionPersistenceSet(for: .manager, entityID: updated.id))
                : []
            var prospectiveOrganizations = organizations
            prospectiveOrganizations[index] = updated
            let calendarMirrorResult = metadataByMirroringCongressPlanRowsIntoCalendar(
                metadata,
                organizations: prospectiveOrganizations
            )
            updated.congresses = organizationCongressesClearingCalendarOwnedPlanning(updated.congresses)
            guard updated != organizations[index] || calendarMirrorResult.didChange else {
                if !pendingSelectionAffectedSet.isEmpty {
                    let previousStates = try persistedBaselineDocumentStates(for: pendingSelectionAffectedSet)
                    finalizePendingSelectionIfNeeded(for: .organization, entityID: updated.id, canonicalValue: updated.nameSv)
                    finalizePendingSelectionIfNeeded(for: .manager, entityID: updated.id, canonicalValue: updated.nameSv)
                    try enqueueAutosavePersistence(
                        pendingSelectionAffectedSet,
                        actionName: actionName ?? language.text("Edit organization", "Redigera organisation"),
                        previousStates: previousStates
                    )
                }
                loadError = nil
                return
            }
            let didRename = updated.nameSv != oldValue
            let affectsManagers =
                previousOrganization.roles.contains(.fundManager)
                || updated.roles.contains(.fundManager)
                || previousOrganization.roles != updated.roles
                || previousOrganization.nameSv != updated.nameSv
                || previousOrganization.nameEn != updated.nameEn
                || previousOrganization.note != updated.note
                || previousOrganization.salaryCalculator != updated.salaryCalculator

            var affectedSet: PersistenceSet = [.organizations]
            if didRename {
                affectedSet.formUnion([.applications, .teachingCourses, .teachingComponents])
                affectedSet.formUnion(idLinkedOrganizationTextPersistenceSet(organizationID: updated.id))
            }
            // Round 7: researcher rows linked to the organization follow a rename.
            var prospectiveOfficialNameOrganizations = organizations
            prospectiveOfficialNameOrganizations[index] = updated
            let officialNames = OrganizationTree.applyingOfficialNames(
                to: publicationAuthors,
                organizations: prospectiveOfficialNameOrganizations,
                onlyOrganizationIDs: [updated.id]
            )
            let rewritesResearcherRows = !officialNames.report.isEmpty
            if rewritesResearcherRows {
                affectedSet.insert(.publicationAuthors)
            }
            if calendarMirrorResult.didChange {
                affectedSet.formUnion([.metadata, .calendarTravelRecords, .calendarAccommodationRecords])
            }
            affectedSet.formUnion(pendingSelectionAffectedSet)
            let previousStates = try persistedBaselineDocumentStates(for: affectedSet)

            let congressesChanged = previousOrganization.congresses != updated.congresses
            organizations[index] = updated
            if rewritesResearcherRows {
                publicationAuthors = officialNames.authors
            }
            invalidateSQLitePrimaryCongressReadCache()
            if calendarMirrorResult.didChange {
                metadata = calendarMirrorResult.metadata
            }
            migrateRememberedSelectionID(from: previousOrganization.id, to: updated.id, destinations: [.organizations])
            if didRename {
                for appIndex in applications.indices where applications[appIndex].organizationID == updated.id || (applications[appIndex].organizationID == nil && applications[appIndex].organization == oldValue) {
                    applications[appIndex].organizationID = updated.id
                    applications[appIndex].organization = updated.nameSv
                }
                for appIndex in applications.indices where applications[appIndex].applicationManagerID == updated.id || (applications[appIndex].applicationManagerID == nil && applications[appIndex].applicationManager == oldValue) {
                    applications[appIndex].applicationManagerID = updated.id
                    applications[appIndex].applicationManager = updated.nameSv
                }
                for courseIndex in teachingCourses.indices where teachingCourses[courseIndex].institutionID == updated.id || (teachingCourses[courseIndex].institutionID == nil && teachingCourses[courseIndex].institution == oldValue) {
                    teachingCourses[courseIndex].institutionID = updated.id
                    teachingCourses[courseIndex].institution = updated.nameSv
                }
                for componentIndex in teachingComponents.indices where teachingComponents[componentIndex].institutionID == updated.id || (teachingComponents[componentIndex].institutionID == nil && teachingComponents[componentIndex].institution == oldValue) {
                    teachingComponents[componentIndex].institutionID = updated.id
                    teachingComponents[componentIndex].institution = updated.nameSv
                }
                propagateOrganizationRenameToIDLinkedTexts(from: previousOrganization, to: updated)
            }
            if affectsManagers {
                managers = derivedManagers(from: organizations)
            }
            refreshOrganizationLookupCaches()
            rebuildOrganizationRowSnapshots()
            forceOrganizationRowSnapshotGenerationIfNeeded(congressesChanged: congressesChanged)
            if rewritesResearcherRows {
                refreshPublicationAuthorsOnly()
            }
            try enqueueAutosavePersistence(
                affectedSet,
                actionName: actionName ?? language.text("Edit organization", "Redigera organisation"),
                previousStates: previousStates
            )
            if completePendingSelection {
                finalizePendingSelectionIfNeeded(for: .organization, entityID: updated.id, canonicalValue: updated.nameSv)
                finalizePendingSelectionIfNeeded(for: .manager, entityID: updated.id, canonicalValue: updated.nameSv)
            }
            loadError = nil
        } catch {
            organizations = previousOrganizations
            applications = previousApplications
            managers = previousManagers
            teachingCourses = previousTeachingCourses
            cvReviewEntries = previousReviewEntries
            doctoralCandidates = previousDoctoralCandidates
            if publicationAuthors != previousPublicationAuthors {
                publicationAuthors = previousPublicationAuthors
                refreshPublicationAuthorsOnly()
            }
            refreshOrganizationsState()
            persistenceStatus.isSaving = false
            loadError = error.localizedDescription
        }
    }

    /// "Alla kopplingar via id": the kinds of records whose written
    /// organization text follows a rename because they point to the
    /// organization by id (review assignments and doctoral students).
    private func idLinkedOrganizationTextPersistenceSet(organizationID: String) -> PersistenceSet {
        var set: PersistenceSet = []
        if cvReviewEntries.contains(where: { $0.organizationID == organizationID }) {
            set.insert(.cvReviewEntries)
        }
        if doctoralCandidates.contains(where: { $0.institutionID == organizationID }) {
            set.insert(.doctoralCandidates)
        }
        return set
    }

    /// "Alla kopplingar via id": after an organization is renamed, rows that
    /// point to it by id and still show one of its old names show the new
    /// name (in the same language as before). Rows written with some other
    /// text keep it.
    private func propagateOrganizationRenameToIDLinkedTexts(from previous: OrganizationRecord, to updated: OrganizationRecord) {
        func renamedText(_ text: String) -> String? {
            let key = Self.normalizedIDLinkName(text)
            if key == Self.normalizedIDLinkName(previous.nameSv) {
                return updated.nameSv
            }
            if !previous.nameEn.isEmpty, key == Self.normalizedIDLinkName(previous.nameEn) {
                return updated.nameEn.nonEmpty ?? updated.nameSv
            }
            return nil
        }
        for reviewIndex in cvReviewEntries.indices where cvReviewEntries[reviewIndex].organizationID == updated.id {
            if let renamed = renamedText(cvReviewEntries[reviewIndex].organizationName) {
                cvReviewEntries[reviewIndex].organizationName = renamed
            }
        }
        for candidateIndex in doctoralCandidates.indices where doctoralCandidates[candidateIndex].institutionID == updated.id {
            if let renamed = renamedText(doctoralCandidates[candidateIndex].institution) {
                doctoralCandidates[candidateIndex].institution = renamed
            }
        }
    }

    func deleteOrganization(id: String) {
        guard let organization = organizations.first(where: { $0.id == id }) else { return }
        let details = deletionImpactDetailsForOrganization(name: organization.nameSv, id: organization.id)
        if requestDeletionConfirmationIfNeeded(
            title: language.text("Delete organization?", "Ta bort organisation?"),
            details: details,
            action: { [weak self] in self?.deleteOrganizationConfirmed(id: id) }
        ) {
            return
        }
        deleteOrganizationConfirmed(id: id)
    }

    private func deleteOrganizationConfirmed(id: String) {
        performUndoableChange(
            actionName: language.text("Archive funder", "Arkivera anslagsgivare"),
            successMessage: language.text("Archived funder.", "Arkiverade anslagsgivare."),
            failureMessage: language.text("Could not archive funder.", "Kunde inte arkivera anslagsgivare."),
            scope: .all
        ) {
            guard let organization = organizations.first(where: { $0.id == id }) else { return }
            let canonicalName = organization.nameSv
            try archiveDeletion(
                kind: "organization",
                title: organization.nameSv,
                payload: organization,
                relatedDocumentStates: try archivedRelatedStatesForOrganizationDeletion()
            )
            organizations.removeAll { $0.id == id }
            managers = derivedManagers(from: organizations)
            // Round 11 (user decision 2026-09-30): records that pointed to
            // the organization lose the link but keep the written name, so a
            // funder, fund manager or institution never turns blank. Rows
            // without a link keep their text as it is.
            for appIndex in applications.indices where applications[appIndex].organizationID == id {
                applications[appIndex].organizationID = nil
                if applications[appIndex].organization.trimmedOrNil == nil {
                    applications[appIndex].organization = canonicalName
                }
            }
            for appIndex in applications.indices where applications[appIndex].applicationManagerID == id {
                applications[appIndex].applicationManagerID = nil
                if applications[appIndex].applicationManager?.trimmedOrNil == nil {
                    applications[appIndex].applicationManager = canonicalName
                }
            }
            for courseIndex in teachingCourses.indices where teachingCourses[courseIndex].institutionID == id {
                teachingCourses[courseIndex].institutionID = nil
                if teachingCourses[courseIndex].institution.trimmedOrNil == nil {
                    teachingCourses[courseIndex].institution = canonicalName
                }
            }
            for componentIndex in teachingComponents.indices where teachingComponents[componentIndex].institutionID == id {
                teachingComponents[componentIndex].institutionID = nil
                if teachingComponents[componentIndex].institution.trimmedOrNil == nil {
                    teachingComponents[componentIndex].institution = canonicalName
                }
            }
            // "Alla kopplingar via id": rows that point to the organization
            // lose the link; their text stays (round 11: also rows without
            // a link keep their text).
            for authorIndex in publicationAuthors.indices {
                for affiliationIndex in publicationAuthors[authorIndex].affiliations.indices {
                    if publicationAuthors[authorIndex].affiliations[affiliationIndex].organizationID == id {
                        publicationAuthors[authorIndex].affiliations[affiliationIndex].organizationID = nil
                        publicationAuthors[authorIndex].affiliations[affiliationIndex].unitID = nil
                    }
                }
                for employmentIndex in publicationAuthors[authorIndex].employments.indices {
                    if publicationAuthors[authorIndex].employments[employmentIndex].organizationID == id {
                        publicationAuthors[authorIndex].employments[employmentIndex].organizationID = nil
                        publicationAuthors[authorIndex].employments[employmentIndex].unitID = nil
                    }
                }
                for educationIndex in publicationAuthors[authorIndex].educationEntries.indices {
                    if publicationAuthors[authorIndex].educationEntries[educationIndex].organizationID == id {
                        publicationAuthors[authorIndex].educationEntries[educationIndex].organizationID = nil
                        publicationAuthors[authorIndex].educationEntries[educationIndex].unitID = nil
                    }
                }
                publicationAuthors[authorIndex].normalize()
            }
            for reviewIndex in cvReviewEntries.indices where cvReviewEntries[reviewIndex].organizationID == id {
                cvReviewEntries[reviewIndex].organizationID = nil
            }
            for candidateIndex in doctoralCandidates.indices where doctoralCandidates[candidateIndex].institutionID == id {
                doctoralCandidates[candidateIndex].institutionID = nil
            }
            for projectIndex in projects.indices {
                for principalIndex in projects[projectIndex].principalOrganizations.indices
                where projects[projectIndex].principalOrganizations[principalIndex].organizationID == id {
                    projects[projectIndex].principalOrganizations[principalIndex].organizationID = nil
                }
            }
            for contributionIndex in cvConferenceContributions.indices {
                if cvConferenceContributions[contributionIndex].congressOrganizationID == id {
                    cvConferenceContributions[contributionIndex].congressOrganizationID = nil
                    cvConferenceContributions[contributionIndex].congressID = nil
                    cvConferenceContributions[contributionIndex].congressLink = ""
                }
            }
        }
    }

