    func deleteManager(_ canonicalName: String) {
        let details = deletionImpactDetailsForManager(name: canonicalName)
        if requestDeletionConfirmationIfNeeded(
            title: language.text("Delete fund manager?", "Ta bort medelsförvaltare?"),
            details: details,
            action: { [weak self] in self?.deleteManagerConfirmed(canonicalName) }
        ) {
            return
        }
        deleteManagerConfirmed(canonicalName)
    }

    private func deleteManagerConfirmed(_ canonicalName: String) {
        performUndoableChange(
            actionName: language.text("Archive fund manager", "Arkivera medelsförvaltare"),
            successMessage: language.text("Archived fund manager.", "Arkiverade medelsförvaltare."),
            failureMessage: language.text("Could not archive fund manager.", "Kunde inte arkivera medelsförvaltare."),
            scope: .applications
        ) {
            guard let index = organizations.firstIndex(where: { $0.nameSv == canonicalName }) else { return }
            var organization = organizations[index]
            if organization.roles.count > 1 {
                organization.roles.removeAll { $0 == .fundManager || $0 == .employer || $0 == .institution }
                organization.note = nil
                organization.salaryCalculator = nil
                organizations[index] = organization
                managers = derivedManagers(from: organizations)
            } else {
                try archiveDeletion(
                    // A fund manager is an organization role. Archive the underlying
                    // organization so restoration never depends on a derived list.
                    kind: "organization",
                    title: organization.nameSv,
                    payload: organization,
                    relatedDocumentStates: try archivedRelatedStatesForOrganizationDeletion()
                )
                organizations.removeAll { $0.nameSv == canonicalName }
                managers = derivedManagers(from: organizations)
            }
            for appIndex in applications.indices where applications[appIndex].applicationManagerID == organization.id || applications[appIndex].applicationManager == canonicalName {
                applications[appIndex].applicationManagerID = nil
                applications[appIndex].applicationManager = nil
            }
        }
    }

    func addProject() -> String {
        var project = uniqueOption(baseSv: "Nytt projekt", baseEn: "New project", within: projects)
        project.projectStatus = .planned
        project.isArchived = false
        performUndoableChange(
            actionName: language.text("Add project", "Lägg till projekt"),
            successMessage: language.text("Added project.", "Lade till projekt."),
            failureMessage: language.text("Could not add project.", "Kunde inte lägga till projekt."),
            scope: .projects
        ) {
            projects.append(project)
        }
        return project.id
    }

    func updateProject(id: String, nameSv: String, nameEn: String, collaboratorNames: [String], isArchived: Bool, completePendingSelection: Bool = false) {
        guard let existing = projects.first(where: { $0.id == id }) else { return }
        var updated = existing
        updated.nameSv = nameSv
        updated.nameEn = nameEn
        updated.collaboratorNames = collaboratorNames
        updated.projectStatus = isArchived ? .completed : (existing.projectStatus == .completed ? .ongoing : existing.projectStatus)
        updated.isArchived = updated.projectStatus == .completed
        updateProjectRecord(updated, previousID: id, completePendingSelection: completePendingSelection)
    }

    func updateProjectRecord(_ draft: ProjectRecord, previousID: String, completePendingSelection: Bool = false) {
        guard let index = projects.firstIndex(where: { $0.id == previousID }) else { return }
        var draft = draft
        if draft.nameEn.hasPrefix("New project"), !draft.nameSv.hasPrefix("Nytt projekt") {
            // F9: the placeholder is never kept once the Swedish name is set.
            draft.nameEn = draft.nameSv
        }
        let oldValue = projects[index].nameSv
        let projectBeforeSave = projects[index]
        defer {
            // Round 16: ask "Ska projektet ändras till Pågående?" for new events.
            if let saved = project(id: projectBeforeSave.id), saved != projectBeforeSave {
                evaluateOngoingQuestion(previous: projectBeforeSave, current: saved)
            }
        }

        performUndoableChange(
            actionName: language.text("Edit project", "Redigera projekt"),
            successMessage: language.text("Updated projects.", "Uppdaterade projekt."),
            failureMessage: language.text("Could not update projects.", "Kunde inte uppdatera projekt."),
            scope: .projects
        ) {
            let previousProject = projects[index]
            let suppressedSeedProjectTaskComments = resolvedSuppressedSeedProjectTaskComments(
                previous: previousProject,
                updatedTasks: draft.projectTasks
            )
            let normalizedProjectTasks = normalizedDefaultProjectFundingTasks(
                collaboratorNames: draft.collaboratorNames,
                projectStatus: draft.projectStatus,
                projectTasks: draft.projectTasks,
                suppressedSeedProjectTaskComments: suppressedSeedProjectTaskComments
            )
            let updatedDataCollections = draft.dataCollections.filter { !$0.isEmpty }
            let projectTasks = projectTasksByApplyingDataCollectionCompletionDeadline(
                normalizedProjectTasks,
                previousDataCollections: previousProject.dataCollections,
                updatedDataCollections: updatedDataCollections,
                hasDataCollection: draft.hasDataCollection
            )
            let updated = normalizedOption(
                id: projects[index].id,
                nameSv: draft.nameSv,
                nameEn: draft.nameEn,
                fullNameSv: draft.fullNameSv,
                fullNameEn: draft.fullNameEn,
                collaboratorNames: draft.collaboratorNames,
                collaboratorAuthorIDs: draft.collaboratorAuthorIDs,
                note: draft.note,
                websiteURL: draft.websiteURL,
                projectStatus: draft.projectStatus,
                hasDataCollection: draft.hasDataCollection,
                ethicsBaseApplication: draft.ethicsBaseApplication,
                ethicsAmendments: draft.ethicsAmendments,
                ethicsLink: draft.ethicsLink,
                clinicalTrialRegistrations: draft.clinicalTrialRegistrations,
                principalOrganizations: draft.principalOrganizations,
                dataCollections: updatedDataCollections,
                projectTasks: projectTasks,
                suppressedSeedProjectTaskComments: suppressedSeedProjectTaskComments,
                fallback: oldValue,
                excluding: oldValue,
                within: projects,
                isArchived: draft.projectStatus == .completed,
                isEditingLocked: draft.isEditingLocked,
                dismissedOngoingPromptKeys: ProjectOngoingPrompt.mergedDismissedKeys(previousProject, draft)
            )
            projects[index] = updated
            propagateProjectRename(from: oldValue, to: updated)
            refreshProjectDerivedState(afterUpdating: updated, previous: previousProject, didRenameProject: updated.nameSv != oldValue)
            if completePendingSelection {
                finalizePendingSelectionIfNeeded(for: .project, entityID: updated.id, canonicalValue: updated.nameSv)
            }
        }
    }

    func autosaveProjectRecord(_ draft: ProjectRecord, previousID: String, completePendingSelection: Bool = false) {
        guard let index = projects.firstIndex(where: { $0.id == previousID }) else { return }
        let oldValue = projects[index].nameSv
        let previousProject = projects[index]
        let previousApplications = applications
        let previousPublications = publicationRecords
        let previousConferenceContributions = cvConferenceContributions

        do {
            let suppressedSeedProjectTaskComments = resolvedSuppressedSeedProjectTaskComments(
                previous: previousProject,
                updatedTasks: draft.projectTasks
            )
            let normalizedProjectTasks = normalizedDefaultProjectFundingTasks(
                collaboratorNames: draft.collaboratorNames,
                projectStatus: draft.projectStatus,
                projectTasks: draft.projectTasks,
                suppressedSeedProjectTaskComments: suppressedSeedProjectTaskComments
            )
            let updatedDataCollections = draft.dataCollections.filter { !$0.isEmpty }
            let projectTasks = projectTasksByApplyingDataCollectionCompletionDeadline(
                normalizedProjectTasks,
                previousDataCollections: previousProject.dataCollections,
                updatedDataCollections: updatedDataCollections,
                hasDataCollection: draft.hasDataCollection
            )
            let updated = normalizedOption(
                id: previousProject.id,
                nameSv: draft.nameSv,
                nameEn: draft.nameEn,
                fullNameSv: draft.fullNameSv,
                fullNameEn: draft.fullNameEn,
                collaboratorNames: draft.collaboratorNames,
                collaboratorAuthorIDs: draft.collaboratorAuthorIDs,
                note: draft.note,
                websiteURL: draft.websiteURL,
                projectStatus: draft.projectStatus,
                hasDataCollection: draft.hasDataCollection,
                ethicsBaseApplication: draft.ethicsBaseApplication,
                ethicsAmendments: draft.ethicsAmendments,
                ethicsLink: draft.ethicsLink,
                clinicalTrialRegistrations: draft.clinicalTrialRegistrations,
                principalOrganizations: draft.principalOrganizations,
                dataCollections: updatedDataCollections,
                projectTasks: projectTasks,
                suppressedSeedProjectTaskComments: suppressedSeedProjectTaskComments,
                fallback: oldValue,
                excluding: oldValue,
                within: projects,
                isArchived: draft.projectStatus == .completed,
                isEditingLocked: draft.isEditingLocked,
                dismissedOngoingPromptKeys: ProjectOngoingPrompt.mergedDismissedKeys(previousProject, draft)
            )
            let pendingSelectionAffectedSet: PersistenceSet = completePendingSelection
                ? pendingSelectionPersistenceSet(for: .project, entityID: updated.id)
                : []
            if updated == previousProject {
                if !pendingSelectionAffectedSet.isEmpty {
                    let previousStates = try persistedBaselineDocumentStates(for: pendingSelectionAffectedSet)
                    finalizePendingSelectionIfNeeded(for: .project, entityID: updated.id, canonicalValue: updated.nameSv)
                    try enqueueAutosavePersistence(
                        pendingSelectionAffectedSet,
                        actionName: language.text("Edit project", "Redigera projekt"),
                        previousStates: previousStates
                    )
                }
                loadError = nil
                return
            }
            let didRenameProject = updated.nameSv != oldValue
            var affectedSet: PersistenceSet = didRenameProject ? [.projects, .applications, .publicationRecords, .cvConferenceContributions] : [.projects]
            affectedSet.formUnion(pendingSelectionAffectedSet)
            let previousStates = try persistedBaselineDocumentStates(for: affectedSet)
            projects[index] = updated

            if didRenameProject {
                propagateProjectRename(from: oldValue, to: updated)
            }

            if completePendingSelection {
                finalizePendingSelectionIfNeeded(for: .project, entityID: updated.id, canonicalValue: updated.nameSv)
            }

            refreshProjectDerivedState(afterUpdating: updated, previous: previousProject, didRenameProject: didRenameProject)
            try enqueueAutosavePersistence(
                affectedSet,
                actionName: language.text("Edit project", "Redigera projekt"),
                previousStates: previousStates
            )
            evaluateOngoingQuestion(previous: previousProject, current: updated)
        } catch {
            projects[index] = previousProject
            applications = previousApplications
            publicationRecords = previousPublications
            cvConferenceContributions = previousConferenceContributions
            refreshPublicationIndexes(mode: .crossReferencesOnly, projectCacheBehavior: .markDirty)
            persistenceStatus.isSaving = false
            loadError = error.localizedDescription
        }
    }

    private func refreshProjectDerivedState(
        afterUpdating updated: ProjectRecord,
        previous: ProjectRecord,
        didRenameProject: Bool
    ) {
        let collaboratorsChanged = previous.collaboratorNames != updated.collaboratorNames
        if didRenameProject || collaboratorsChanged {
            appendPerformanceDiagnostic(
                "dirty-graph entity=project id=\(updated.id) rename=\(didRenameProject ? "yes" : "no") collaborators=\(collaboratorsChanged ? "yes" : "no") action=publication-crossrefs"
            )
            refreshPublicationIndexes(mode: .crossReferencesOnly, projectCacheBehavior: .markDirty)
            return
        }

        let projectDirectoryChanged =
            previous.nameEn != updated.nameEn
            || previous.fullNameSv != updated.fullNameSv
            || previous.fullNameEn != updated.fullNameEn
            || previous.projectStatus != updated.projectStatus
            || previous.hasDataCollection != updated.hasDataCollection
        let projectTimelineChanged =
            previous.hasDataCollection != updated.hasDataCollection
            || previous.ethicsBaseApplication != updated.ethicsBaseApplication
            || previous.ethicsAmendments != updated.ethicsAmendments
            || previous.dataCollections != updated.dataCollections

        if projectDirectoryChanged || projectTimelineChanged {
            appendPerformanceDiagnostic(
                "dirty-graph entity=project id=\(updated.id) directory=\(projectDirectoryChanged ? "yes" : "no") timeline=\(projectTimelineChanged ? "yes" : "no") action=project-cache"
            )
            refreshProjectIndexesAndCaches()
        }
    }

    private func projectTasksByApplyingDataCollectionCompletionDeadline(
        _ tasks: [ProjectTaskItem],
        previousDataCollections: [ProjectDataCollection],
        updatedDataCollections: [ProjectDataCollection],
        hasDataCollection: Bool
    ) -> [ProjectTaskItem] {
        let calendar = Calendar.current
        let today = calendar.startOfDay(for: Date())
        guard hasDataCollection,
              dataCollectionCompletionReached(in: updatedDataCollections, today: today, calendar: calendar) else {
            return tasks
        }

        let completionJustReached = !dataCollectionCompletionReached(
            in: previousDataCollections,
            today: today,
            calendar: calendar
        )
        let todayString = DateParsers.isoDay.string(from: today)
        var didChange = false

        let updatedTasks = tasks.map { task -> ProjectTaskItem in
            guard task.reminder == .dataCollectionCompleted,
                  !task.isEmpty,
                  !task.isCompleted else {
                return task
            }

            let deadline = DateParsers.canonicalizedDayInput(task.deadline)
                .trimmingCharacters(in: .whitespacesAndNewlines)
            guard deadline != todayString else { return task }

            let shouldMoveDeadline: Bool
            if deadline.isEmpty {
                shouldMoveDeadline = true
            } else if let deadlineDate = DateParsers.isoDay.date(from: deadline) {
                let deadlineDay = calendar.startOfDay(for: deadlineDate)
                shouldMoveDeadline = completionJustReached || deadlineDay < today
            } else {
                shouldMoveDeadline = false
            }

            guard shouldMoveDeadline else { return task }

            var copy = task
            if copy.createdOn.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                copy.createdOn = todayString
            }
            copy.deadline = todayString
            copy.updatedOn = todayString
            didChange = true
            return copy
        }

        return didChange ? updatedTasks : tasks
    }

    private func dataCollectionCompletionReached(
        in dataCollections: [ProjectDataCollection],
        today: Date,
        calendar: Calendar
    ) -> Bool {
        let activeCollections = dataCollections.filter { !$0.isEmpty }
        guard !activeCollections.isEmpty else { return false }

        return activeCollections.allSatisfy { dataCollection in
            guard let toText = dataCollection.to.trimmedOrNil,
                  let toDate = DateParsers.isoDay.date(from: toText) else {
                return false
            }
            return calendar.startOfDay(for: toDate) <= today
        }
    }

    func deleteProject(id: String) {
        guard let project = projects.first(where: { $0.id == id }) else { return }
        let details = deletionImpactDetailsForProject(name: project.nameSv, id: project.id)
        if requestDeletionConfirmationIfNeeded(
            title: language.text("Delete project?", "Ta bort projekt?"),
            details: details,
            action: { [weak self] in self?.deleteProjectConfirmed(id: id) }
        ) {
            return
        }
        deleteProjectConfirmed(id: id)
    }

    private func deleteProjectConfirmed(id: String) {
        performUndoableChange(
            actionName: language.text("Archive project", "Arkivera projekt"),
            successMessage: language.text("Archived project.", "Arkiverade projekt."),
            failureMessage: language.text("Could not archive project.", "Kunde inte arkivera projekt."),
            scope: .projects
        ) {
            guard let project = projects.first(where: { $0.id == id }) else { return }
            let canonicalName = project.nameSv
            let hasAmbiguousLegacyName = projects.lazy.filter { $0.nameSv == canonicalName }.prefix(2).count > 1
            try archiveDeletion(
                kind: "project",
                title: project.nameSv,
                payload: project,
                relatedDocumentStates: try archivedRelatedStatesForProjectDeletion()
            )
            projects.removeAll { $0.id == id }
            for appIndex in applications.indices where applications[appIndex].projectID == id ||
                (!hasAmbiguousLegacyName && applications[appIndex].projectID == nil && applications[appIndex].projectType == canonicalName) {
                applications[appIndex].projectID = nil
                applications[appIndex].projectType = nil
            }
            for publicationIndex in publicationRecords.indices where publicationRecords[publicationIndex].projectID == id ||
                (!hasAmbiguousLegacyName && publicationRecords[publicationIndex].projectID == nil && publicationRecords[publicationIndex].projectName == canonicalName) {
                publicationRecords[publicationIndex].projectID = nil
                publicationRecords[publicationIndex].projectName = nil
            }
            for contributionIndex in cvConferenceContributions.indices {
                let contribution = cvConferenceContributions[contributionIndex]
                let pointsToDeletedProject = contribution.projectID == id
                    || (!hasAmbiguousLegacyName && contribution.projectID == nil
                        && (contribution.projectNameSv == canonicalName || contribution.projectNameEn == canonicalName))
                if pointsToDeletedProject {
                    cvConferenceContributions[contributionIndex].projectID = nil
                    cvConferenceContributions[contributionIndex].projectNameSv = ""
                    cvConferenceContributions[contributionIndex].projectNameEn = ""
                }
                if pointsToDeletedProject || !hasAmbiguousLegacyName {
                    cvConferenceContributions[contributionIndex] = canonicalizedConferenceContribution(cvConferenceContributions[contributionIndex])
                }
            }
        }
    }

