    /// F13: moments and assignments linked to the format by id, or still only
    /// by its old name, get the new name.
    private func applyTeachingFormatRename(_ format: TeachingFormatOption, previousName: String) {
        for assignmentIndex in teachingAssignments.indices
        where teachingAssignments[assignmentIndex].activityTypeID == format.id
            || (teachingAssignments[assignmentIndex].activityTypeID == nil && teachingAssignments[assignmentIndex].activityTypeName == previousName) {
            teachingAssignments[assignmentIndex].activityTypeID = format.id
            teachingAssignments[assignmentIndex].activityTypeName = format.name
        }
        for componentIndex in teachingComponents.indices
        where teachingComponents[componentIndex].activityTypeID == format.id
            || (teachingComponents[componentIndex].activityTypeID == nil && teachingComponents[componentIndex].activityTypeName == previousName) {
            teachingComponents[componentIndex].activityTypeID = format.id
            teachingComponents[componentIndex].activityTypeName = format.name
        }
    }

