    func autosaveTeachingCourse(_ updated: TeachingCourse) {
        guard let index = teachingCourses.firstIndex(where: { $0.id == updated.id }) else { return }
        let previous = teachingCourses[index]
        do {
            let affectedSet: PersistenceSet = [.teachingCourses]
            let previousStates = try persistedBaselineDocumentStates(for: affectedSet)
            var normalized = clearingStaleTeachingReferenceIDs(updated, previous: previous)
            normalized.normalize()
            normalized = synchronizedTeachingCourseRelations(normalized)
            guard normalized != previous else { return }
            teachingCourses[index] = normalized
            refreshTeachingCoursesOnly()
            try enqueueAutosavePersistence(
                affectedSet,
                actionName: language.text("Edit teaching context", "Redigera undervisningskontext"),
                previousStates: previousStates
            )
        } catch {
            teachingCourses[index] = previous
            refreshTeachingCoursesOnly()
            persistenceStatus.isSaving = false
            loadError = error.localizedDescription
        }
    }

    func autosaveTeachingComponent(_ updated: TeachingComponent) {
        guard let index = teachingComponents.firstIndex(where: { $0.id == updated.id }) else { return }
        let previous = teachingComponents[index]
        do {
            var normalized = clearingStaleTeachingReferenceIDs(updated, previous: previous)
            normalized.normalize()
            normalized = synchronizedTeachingComponentRelations(normalized)
            let previousName = teachingComponents[index].name
            var updatedAssignments = teachingAssignments
            for assignmentIndex in updatedAssignments.indices {
                if updatedAssignments[assignmentIndex].activityID == normalized.id ||
                    (updatedAssignments[assignmentIndex].activityID == nil && updatedAssignments[assignmentIndex].activityName == previousName) {
                    updatedAssignments[assignmentIndex].activityID = normalized.id
                    updatedAssignments[assignmentIndex].activityName = normalized.nameSv
                }
            }
            guard normalized != previous || updatedAssignments != teachingAssignments else { return }
            let affectedSet: PersistenceSet = [.teachingComponents, .teachingAssignments]
            let previousStates = try persistedBaselineDocumentStates(for: affectedSet)
            teachingComponents[index] = normalized
            teachingAssignments = updatedAssignments
            refreshTeachingComponentsOnly()
            refreshTeachingAssignmentsOnly()
            try enqueueAutosavePersistence(
                affectedSet,
                actionName: language.text("Edit teaching activity", "Redigera undervisningsaktivitet"),
                previousStates: previousStates
            )
        } catch {
            teachingComponents[index] = previous
            refreshTeachingComponentsOnly()
            refreshTeachingAssignmentsOnly()
            persistenceStatus.isSaving = false
            loadError = error.localizedDescription
        }
    }

    func autosaveTeachingFormat(_ updated: TeachingFormatOption) {
        guard let index = teachingFormats.firstIndex(where: { $0.id == updated.id }) else { return }
        let previous = teachingFormats[index]
        do {
            var normalized = updated
            normalized.normalize()
            guard normalized != previous else { return }
            let isRename = previous.name != normalized.name
            // F13: a renamed format carries its new name to the moments and
            // assignments that use it.
            let affectedSet: PersistenceSet = isRename
                ? [.teachingFormats, .teachingComponents, .teachingAssignments]
                : [.teachingFormats]
            let previousStates = try persistedBaselineDocumentStates(for: affectedSet)
            teachingFormats[index] = normalized
            if isRename {
                applyTeachingFormatRename(normalized, previousName: previous.name)
                refreshTeachingComponentsOnly()
                refreshTeachingAssignmentsOnly()
            }
            refreshTeachingFormatsOnly()
            try enqueueAutosavePersistence(
                affectedSet,
