            var normalized = clearingStaleTeachingReferenceIDs(updated, previous: previous)
            normalized.normalize()
            synchronizedTeachingAssignmentAuthorID(&normalized)
            synchronizeTeachingAssignmentReferences(&normalized)
            let teachingPeriodsCount = normalized.periods.filter { !$0.isEmpty }.count
            appendPerformanceDiagnostic(
                "teaching-assignment-autosave has_context=\(normalized.contextID != nil) has_activity=\(normalized.activityID != nil) roles=\(normalized.roles.count) periods=\(teachingPeriodsCount)"
            )
            guard normalized != previous else { return }
            let affectedSet: PersistenceSet = [.teachingAssignments]
            let previousStates = try persistedBaselineDocumentStates(for: affectedSet)
            teachingAssignments[index] = normalized
            refreshTeachingAssignmentsOnly()
            try enqueueAutosavePersistence(
                affectedSet,
                actionName: language.text("Edit teaching assignment", "Redigera undervisningsuppdrag"),
                previousStates: previousStates
            )
        } catch {
            teachingAssignments[index] = previous
            refreshTeachingAssignmentsOnly()
            persistenceStatus.isSaving = false
            loadError = error.localizedDescription
        }
    }

