    func autosaveDoctoralCandidate(_ updated: DoctoralCandidateRecord, resolveDerivedLinks: Bool = true) {
        guard let index = doctoralCandidates.firstIndex(where: { $0.id == updated.id }) else { return }
        let previous = doctoralCandidates[index]
        do {
            var normalized = updated
            normalized.normalize()
            normalized = synchronizedDoctoralCandidateInstitution(normalized)
            appendPerformanceDiagnostic(
                "doctoral-autosave has_project=\(normalized.linkedProjectID != nil) supervisors=\(normalized.supervisors.count)"
            )
            var affectedSet: PersistenceSet = [.doctoralCandidates]
            if resolveDerivedLinks {
                affectedSet.formUnion(applyDoctoralCandidateDerivedLinks(&normalized))
                appendPerformanceDiagnostic(
                    "doctoral-derived has_project=\(normalized.linkedProjectID != nil) linked_publications=\(normalized.linkedPublicationIDs.count)"
                )
            }
            guard normalized != previous || affectedSet != [.doctoralCandidates] else { return }
            let previousStates = try persistedBaselineDocumentStates(for: affectedSet)
            doctoralCandidates[index] = normalized
            if affectedSet.contains(.projects) {
                refreshOrganizationsState()
                refreshDoctoralCandidatesOnly()
            } else {
                refreshDoctoralCandidatesOnly()
            }
            try enqueueAutosavePersistence(
                affectedSet,
                actionName: language.text("Edit doctoral candidate", "Redigera doktorand"),
                previousStates: previousStates
            )
        } catch {
            doctoralCandidates[index] = previous
            refreshDoctoralCandidatesOnly()
            persistenceStatus.isSaving = false
            loadError = error.localizedDescription
        }
    }

    private func applyDoctoralCandidateDerivedLinks(_ candidate: inout DoctoralCandidateRecord) -> PersistenceSet {
        let normalizedCandidateName = PublicationDerivation.normalizedName(candidate.candidateName)
        // "Alla kopplingar via id": a link to a researcher who still answers
        // to the written name is kept, even when another researcher has the
        // same name.
        func linkedAuthorAnswers(_ authorID: String?, to normalizedName: String) -> Bool {
            guard !normalizedName.isEmpty, let author = publicationAuthor(id: authorID) else { return false }
            return ([author.name] + author.presentedNameCandidates).contains {
                PublicationDerivation.normalizedName($0) == normalizedName
            }
        }
        if linkedAuthorAnswers(candidate.candidateAuthorID, to: normalizedCandidateName) {
            // Keep the link.
        } else if let matchedAuthor = publicationAuthors.first(where: {
            PublicationDerivation.normalizedName($0.name) == normalizedCandidateName
        }) {
            candidate.candidateAuthorID = matchedAuthor.id
            if candidate.candidateName.nonEmpty == nil {
                candidate.candidateName = matchedAuthor.name
            }
        } else if candidate.candidateName.nonEmpty == nil {
            candidate.candidateAuthorID = nil
        }

        for index in candidate.supervisors.indices {
            let supervisorName = candidate.supervisors[index].name
            let normalizedSupervisorName = PublicationDerivation.normalizedName(supervisorName)
            if linkedAuthorAnswers(candidate.supervisors[index].authorID, to: normalizedSupervisorName) {
                // Keep the link.
            } else if let matchedAuthor = publicationAuthors.first(where: {
                PublicationDerivation.normalizedName($0.name) == normalizedSupervisorName
            }) {
                candidate.supervisors[index].authorID = matchedAuthor.id
            } else if supervisorName.nonEmpty == nil {
                candidate.supervisors[index].authorID = nil
            }
        }

        candidate.linkedProjectID = nil

        let allowedPublicationIDs = Set(publicationRecords.compactMap { publication -> String? in
            // "Alla kopplingar via id": the publication's author links first.
            if let candidateAuthorID = candidate.candidateAuthorID?.trimmedOrNil,
               publication.authorIDs.contains(candidateAuthorID) {
                return publication.id
            }
            let matchesCandidate = publication.authorNames.contains { authorName in
                if let candidateAuthorID = candidate.candidateAuthorID,
                   let matchedAuthor = publicationAuthor(matchingPresentedName: authorName),
                   matchedAuthor.id == candidateAuthorID {
                    return true
                }
                return PublicationDerivation.normalizedName(authorName) == normalizedCandidateName
            }
            return matchesCandidate ? publication.id : nil
        })

        let filtered = candidate.linkedPublicationIDs.filter { allowedPublicationIDs.contains($0) }
        if filtered != candidate.linkedPublicationIDs {
            candidate.linkedPublicationIDs = filtered
        }

        return []
    }

