    /// Removes doctoral candidates created from teaching rows that hold no
    /// doctoral data of their own. Round 11 (user decision 2026-09-30):
    /// nothing calls this automatically any more; candidates are only
    /// removed when the user deletes them.
    func removeAutoMigratedTeachingOnlyDoctoralCandidatesIfNeeded() {
        let removableIDs = doctoralCandidates.compactMap { candidate -> String? in
            guard !candidate.sourceAssignmentIDs.isEmpty else { return nil }

            let hasManualDoctoralData =
                candidate.planningSeminarDate.trimmedOrNil != nil ||
                candidate.halftimeDate.trimmedOrNil != nil ||
                candidate.plannedDisputationDate.trimmedOrNil != nil ||
                candidate.linkedProjectID?.trimmedOrNil != nil ||
                !candidate.linkedPublicationIDs.isEmpty ||
                !candidate.tasks.isEmpty ||
                candidate.supervisors.count > 1

            guard !hasManualDoctoralData else { return nil }
            return candidate.id
        }

        guard !removableIDs.isEmpty else { return }
        let removableSet = Set(removableIDs)

        performUndoableChange(
            actionName: language.text("Remove auto-created doctoral candidates", "Ta bort automatiskt skapade doktorander"),
            successMessage: language.text("Removed auto-created doctoral candidates.", "Tog bort automatiskt skapade doktorander."),
            failureMessage: language.text("Could not remove auto-created doctoral candidates.", "Kunde inte ta bort automatiskt skapade doktorander."),
            scope: .teaching
        ) {
            doctoralCandidates.removeAll { removableSet.contains($0.id) }
        }
    }

    func ensureDoctoralCandidatesMigratedFromTeaching() {
        let normalizedCurrentUser = currentUserAuthor()
        var recordsByKey: [String: DoctoralCandidateRecord] = [:]
        for existing in doctoralCandidates {
            var normalized = existing
            normalized.normalize()
            recordsByKey[doctoralCandidateMergeKey(for: normalized)] = normalized
        }

        var migratedAssignmentIDs: Set<String> = []
        var migrationAffectedSet: PersistenceSet = [.doctoralCandidates, .teachingAssignments]

        for assignment in teachingAssignments {
            guard let candidateName = assignment.studentName.trimmedOrNil else { continue }
            let context = teachingCourses.first(where: { $0.id == assignment.contextID })
            let reportCategoryRaw = assignment.reportCategory?.rawValue.lowercased() ?? ""
            let activityNameRaw = assignment.activityName.lowercased()
            let activityTypeRaw = assignment.activityTypeName.lowercased()
            let contextNameRaw = context?.name.lowercased() ?? ""
            let hasDoctoralKeyword =
                reportCategoryRaw.contains("doctoral supervision") ||
                reportCategoryRaw.contains("doktorandhandled") ||
                activityNameRaw.contains("doktorandhandled") ||
                activityNameRaw.contains("doctoral supervision") ||
                activityTypeRaw.contains("doktorandhandled") ||
                activityTypeRaw.contains("doctoral supervision") ||
                contextNameRaw.contains("doktorandhandled") ||
                contextNameRaw.contains("doctoral supervision")
            let hasDoctoralSupervisorCategory =
                assignment.reportCategory == .doctoralPrincipalSupervision ||
                assignment.reportCategory == .doctoralAssistantSupervision
            let hasDoctoralSupervisorRole =
                assignment.roles.contains(.principalSupervisor) ||
                assignment.roles.contains(.assistantSupervisor)
            let contextLooksDoctoral =
                context?.contextType == .doctoralEducation ||
                context?.level == .doctoral
            let isDoctoralAssignment =
                hasDoctoralSupervisorCategory ||
                hasDoctoralKeyword ||
                (hasDoctoralSupervisorRole && contextLooksDoctoral && hasDoctoralKeyword)
            guard isDoctoralAssignment else { continue }

            let normalizedCandidateName = PublicationDerivation.normalizedName(candidateName)
            let candidateAuthor = publicationAuthors.first {
                PublicationDerivation.normalizedName($0.name) == normalizedCandidateName
            }
            let mergeKey = candidateAuthor?.id.nonEmpty ?? normalizedCandidateName

            var record = recordsByKey[mergeKey] ?? DoctoralCandidateRecord(
                candidateAuthorID: candidateAuthor?.id,
                candidateName: candidateAuthor?.name ?? candidateName,
                institution: context?.institution ?? ""
            )

            if record.candidateAuthorID == nil {
                record.candidateAuthorID = candidateAuthor?.id
            }
            if record.candidateName.nonEmpty == nil {
                record.candidateName = candidateAuthor?.name ?? candidateName
            }
            if record.institution.nonEmpty == nil {
                record.institution = context?.institution ?? ""
            }

            if record.admissionDate.nonEmpty == nil {
                let earliestFrom = assignment.periods
                    .compactMap { $0.from.trimmedOrNil }
                    .sorted()
                    .first
                record.admissionDate = earliestFrom ?? ""
            }

            if record.linkedProjectID == nil, let context {
                if let matchingProject = project(named: context.nameSv) ?? project(named: context.nameEn) {
                    record.linkedProjectID = matchingProject.id
                }
            }

            let assignmentFrom = assignment.periods
                .compactMap { $0.from.trimmedOrNil }
                .sorted()
                .first ?? ""
            let assignmentTo = assignment.periods
                .compactMap { $0.to.trimmedOrNil }
                .sorted()
                .last ?? ""

            if let currentUser = normalizedCurrentUser {
                let currentUserNormalized = PublicationDerivation.normalizedName(currentUser.name)
                if !record.supervisors.contains(where: {
                    $0.authorID == currentUser.id ||
                    PublicationDerivation.normalizedName($0.name) == currentUserNormalized
                }) {
                    record.supervisors.append(
                        DoctoralSupervisorLink(
                            authorID: currentUser.id,
                            name: currentUser.name,
                            from: assignmentFrom,
                            to: assignmentTo
                        )
                    )
                }
                if assignment.roles.contains(.principalSupervisor),
                   let currentUserIndex = record.supervisors.firstIndex(where: {
                       $0.authorID == currentUser.id ||
                       PublicationDerivation.normalizedName($0.name) == currentUserNormalized
                   }) {
                    let currentUserSupervisor = record.supervisors.remove(at: currentUserIndex)
                    record.supervisors.insert(currentUserSupervisor, at: 0)
                }
                if let currentUserIndex = record.supervisors.firstIndex(where: {
                    $0.authorID == currentUser.id ||
                    PublicationDerivation.normalizedName($0.name) == currentUserNormalized
                }) {
                    if record.supervisors[currentUserIndex].from.trimmedOrNil == nil {
                        record.supervisors[currentUserIndex].from = assignmentFrom
                    }
                    if record.supervisors[currentUserIndex].to.trimmedOrNil == nil {
                        record.supervisors[currentUserIndex].to = assignmentTo
                    }
                }
            }

            for period in assignment.periods where !period.isEmpty {
                var migratedPeriod = DoctoralSupervisionPeriod(
                    semesterLabel: doctoralSemesterLabel(from: period.from, to: period.to),
                    from: period.from,
                    to: period.to,
                    hoursPerSemester: period.hoursPerTerm,
                    confirmedInRetendo: period.confirmedInRetendo
                )
                migratedPeriod.normalize()
                let isDuplicate = record.supervisionPeriods.contains {
                    ($0.semesterLabel == migratedPeriod.semesterLabel) &&
                    ($0.from == migratedPeriod.from) &&
                    ($0.to == migratedPeriod.to) &&
                    ($0.hoursPerSemester == migratedPeriod.hoursPerSemester) &&
                    ($0.confirmedInRetendo == migratedPeriod.confirmedInRetendo)
                }
                if !isDuplicate {
                    record.supervisionPeriods.append(migratedPeriod)
                }
            }

            let linkedPublicationIDs = publicationRecords
                .filter { publication in
                    publication.authorNames.contains { authorName in
                        PublicationDerivation.normalizedName(authorName) == normalizedCandidateName
                    }
                }
                .map(\.id)
            record.linkedPublicationIDs.append(contentsOf: linkedPublicationIDs)
            record.sourceAssignmentIDs.append(assignment.id)
            record.normalize()
            migrationAffectedSet.formUnion(applyDoctoralCandidateDerivedLinks(&record))
            record.normalize()
            recordsByKey[mergeKey] = record
            migratedAssignmentIDs.insert(assignment.id)
        }

        guard !migratedAssignmentIDs.isEmpty else { return }

        do {
            doctoralCandidates = Array(recordsByKey.values)
            refreshDoctoralCandidatesOnly()
            if migrationAffectedSet.contains(.projects) {
                refreshOrganizationsState()
            }
            try persist(migrationAffectedSet, includeBackup: false)
            notice = StoreNotice(
                message: language.text(
                    "Migrated doctoral supervision records to the Doctoral Candidates module.",
                    "Migrerade doktorandhandledning till modulen Doktorander."
                ),
                tone: .info
            )
            loadError = nil
        } catch {
            loadError = error.localizedDescription
        }
    }

