    func runDeferredLaunchMaintenanceIfNeeded() {
        guard !Self.hasCurrentDeferredLaunchMaintenanceMarker() else { return }

        let launchMaintenanceStartedAt = CFAbsoluteTimeGetCurrent()
        appendPerformanceDiagnostic("launch-maintenance start")

        func performLaunchMaintenanceStep(_ name: String, action: () -> Void) {
            let startedAt = CFAbsoluteTimeGetCurrent()
            action()
            appendPerformanceDiagnosticIfSlow(
                { duration in
                    String(format: "launch-maintenance-step name=%@ duration_ms=%.2f", name, duration)
                },
                startedAt: startedAt,
                thresholdMs: 4
            )
        }

        if !isShareModeEnabled {
            performLaunchMaintenanceStep("invalid-publication-journals") {
                ensureInvalidPublicationJournalsRemoved()
            }
        }
        performLaunchMaintenanceStep("central-task-legacy-dedup") {
            removeLegacyTaskCopiesSupersededByCentral()
        }
        performLaunchMaintenanceStep("central-task-migration") {
            migrateLegacyTasksToCentral()
        }
        performLaunchMaintenanceStep("teaching-assignment-kinds") {
            ensureTeachingAssignmentKindsStored()
        }
        // Round 11 (user decision 2026-09-30): doctoral candidates are never
        // removed automatically, at launch or anywhere else.

        try? Self.writeCurrentDeferredLaunchMaintenanceMarker()
        appendPerformanceDiagnostic(
            String(
                format: "launch-maintenance complete total_ms=%.2f",
                (CFAbsoluteTimeGetCurrent() - launchMaintenanceStartedAt) * 1000
            )
        )
    }

