    /// Promotes every remaining host-owned legacy task to the central
    /// collection, preserving task identifiers. Editors only render central
    /// tasks, so a legacy-only task was visible in the calendar and in
    /// reminders but impossible to see, edit or complete on its own record.
    /// The host record becomes a task link instead.
    func migrateLegacyTasksToCentral() {
        var centralIDs = Set(taskItems.map(\.id))
        var promoted: [TaskItem] = []
        var changedSet: PersistenceSet = []

        func promote(_ task: TaskItem) {
            var normalized = task
            normalized.normalize()
            guard !normalized.isEmpty, !centralIDs.contains(normalized.id) else { return }
            centralIDs.insert(normalized.id)
            promoted.append(normalized)
        }

        for index in projects.indices {
            let hostLink = TaskLink(kind: .project, targetID: projects[index].id)
            for task in projects[index].projectTasks {
                promote(Self.centralTaskItem(fromLegacy: task, hostLink: hostLink))
            }
            if !projects[index].projectTasks.isEmpty {
                projects[index].projectTasks = []
                changedSet.insert(.projects)
            }
        }
        for index in organizations.indices {
            let hostLink = TaskLink(kind: .organization, targetID: organizations[index].id)
            for task in organizations[index].projectTasks {
                promote(Self.centralTaskItem(fromLegacy: task, hostLink: hostLink))
            }
            if !organizations[index].projectTasks.isEmpty {
                organizations[index].projectTasks = []
                changedSet.insert(.organizations)
            }
            for congressIndex in organizations[index].congresses.indices {
                let congress = organizations[index].congresses[congressIndex]
                let congressLink = TaskLink(
                    kind: .congress,
                    targetID: congress.id,
                    ownerID: organizations[index].id
                )
                for task in congress.tasks {
                    promote(Self.centralTaskItem(fromLegacy: task, hostLink: congressLink))
                }
                if !congress.tasks.isEmpty {
                    organizations[index].congresses[congressIndex].tasks = []
                    changedSet.insert([.organizations, .congresses])
                }
            }
        }
        for index in publicationRecords.indices {
            let hostLink = TaskLink(kind: .publication, targetID: publicationRecords[index].id)
            for task in publicationRecords[index].publicationTasks {
                promote(Self.centralTaskItem(fromLegacy: task, hostLink: hostLink))
            }
            if !publicationRecords[index].publicationTasks.isEmpty {
                publicationRecords[index].publicationTasks = []
                changedSet.insert(.publicationRecords)
            }
        }
        for index in teachingCourses.indices {
            let hostLink = TaskLink(kind: .teachingCourse, targetID: teachingCourses[index].id)
            for task in teachingCourses[index].tasks {
                promote(Self.centralTaskItem(fromLegacy: task, hostLink: hostLink))
            }
            if !teachingCourses[index].tasks.isEmpty {
                teachingCourses[index].tasks = []
                changedSet.insert(.teachingCourses)
            }
        }
        for index in teachingAssignments.indices {
            let hostLink = TaskLink(kind: .teachingAssignment, targetID: teachingAssignments[index].id)
            for task in teachingAssignments[index].tasks {
                promote(Self.centralTaskItem(fromLegacy: task, hostLink: hostLink))
            }
            if !teachingAssignments[index].tasks.isEmpty {
                teachingAssignments[index].tasks = []
                changedSet.insert(.teachingAssignments)
            }
        }
        for index in doctoralCandidates.indices {
            let hostLink = TaskLink(kind: .doctoralCandidate, targetID: doctoralCandidates[index].id)
            for task in doctoralCandidates[index].tasks {
                promote(Self.centralTaskItem(fromLegacy: task, hostLink: hostLink))
            }
            if !doctoralCandidates[index].tasks.isEmpty {
                doctoralCandidates[index].tasks = []
                changedSet.insert(.doctoralCandidates)
            }
        }
        for index in cvConferenceContributions.indices {
            let hostLink = TaskLink(kind: .conferenceContribution, targetID: cvConferenceContributions[index].id)
            for task in cvConferenceContributions[index].tasks {
                promote(Self.centralTaskItem(fromLegacy: task, hostLink: hostLink))
            }
            if !cvConferenceContributions[index].tasks.isEmpty {
                cvConferenceContributions[index].tasks = []
                changedSet.insert(.cvConferenceContributions)
            }
        }

        var updatedMetadata = editableMetadataSnapshot
        for task in updatedMetadata.teachingWorkspaceTasks ?? [] {
            promote(Self.centralTaskItem(fromLegacy: task, hostLink: nil))
        }
        let hadTeachingWorkspaceTasks = !(updatedMetadata.teachingWorkspaceTasks ?? []).isEmpty
        let metadataChanged = hadTeachingWorkspaceTasks || !promoted.isEmpty
        if hadTeachingWorkspaceTasks {
            updatedMetadata.teachingWorkspaceTasks = []
        }
        if !promoted.isEmpty {
            updatedMetadata.taskItems = (updatedMetadata.taskItems ?? []) + promoted
        }
        guard metadataChanged || !changedSet.isEmpty else { return }
        if metadataChanged {
            metadata = Self.sanitizedMetadata(updatedMetadata)
            changedSet.insert(.metadata)
        }
        do {
            try persist(changedSet, includeBackup: false)
            loadError = nil
            appendStartupDiagnostic(
                "launch-maintenance:migrateLegacyTasksToCentral promoted=\(promoted.count)"
            )
            publishCalendarContentUpdate(source: nil)
        } catch {
            loadError = error.localizedDescription
        }
    }

