    nonisolated private static func centralTaskLinks(
        hostLink: TaskLink?,
        projectID: String?,
        publicationID: String?,
        applicationID: String?
    ) -> [TaskLink] {
        var links: [TaskLink] = []
        if let hostLink {
            links.append(hostLink)
        }
        if let projectID = projectID?.trimmedOrNil {
            links.append(TaskLink(kind: .project, targetID: projectID))
        }
        if let publicationID = publicationID?.trimmedOrNil {
            links.append(TaskLink(kind: .publication, targetID: publicationID))
        }
        if let applicationID = applicationID?.trimmedOrNil {
            links.append(TaskLink(kind: .application, targetID: applicationID))
        }
        return links
    }

    /// A task that exists in the central collection supersedes any legacy
    /// copy left on project/organization records; stale copies produced
    /// phantom overdue warnings after the central task was rescheduled.
    func removeLegacyTaskCopiesSupersededByCentral() {
        let centralIDs = Set(taskItems.map(\.id))
        guard !centralIDs.isEmpty else { return }
        var changedSet: PersistenceSet = []
        for index in projects.indices {
            let filtered = projects[index].projectTasks.filter { !centralIDs.contains($0.id) }
            if filtered.count != projects[index].projectTasks.count {
                projects[index].projectTasks = filtered
                changedSet.insert(.projects)
            }
        }
        for index in organizations.indices {
            let filtered = organizations[index].projectTasks.filter { !centralIDs.contains($0.id) }
            if filtered.count != organizations[index].projectTasks.count {
                organizations[index].projectTasks = filtered
                changedSet.insert(.organizations)
            }
            for congressIndex in organizations[index].congresses.indices {
                let filteredCongressTasks = organizations[index].congresses[congressIndex].tasks
                    .filter { !centralIDs.contains($0.id) }
                if filteredCongressTasks.count != organizations[index].congresses[congressIndex].tasks.count {
                    organizations[index].congresses[congressIndex].tasks = filteredCongressTasks
                    changedSet.insert([.organizations, .congresses])
                }
            }
        }
        for index in publicationRecords.indices {
            let filtered = publicationRecords[index].publicationTasks.filter { !centralIDs.contains($0.id) }
            if filtered.count != publicationRecords[index].publicationTasks.count {
                publicationRecords[index].publicationTasks = filtered
                changedSet.insert(.publicationRecords)
            }
        }
        for index in teachingCourses.indices {
            let filtered = teachingCourses[index].tasks.filter { !centralIDs.contains($0.id) }
            if filtered.count != teachingCourses[index].tasks.count {
                teachingCourses[index].tasks = filtered
                changedSet.insert(.teachingCourses)
            }
        }
        for index in teachingAssignments.indices {
            let filtered = teachingAssignments[index].tasks.filter { !centralIDs.contains($0.id) }
            if filtered.count != teachingAssignments[index].tasks.count {
                teachingAssignments[index].tasks = filtered
                changedSet.insert(.teachingAssignments)
            }
        }
        for index in doctoralCandidates.indices {
            let filtered = doctoralCandidates[index].tasks.filter { !centralIDs.contains($0.id) }
            if filtered.count != doctoralCandidates[index].tasks.count {
                doctoralCandidates[index].tasks = filtered
                changedSet.insert(.doctoralCandidates)
            }
        }
        for index in cvConferenceContributions.indices {
            let filtered = cvConferenceContributions[index].tasks.filter { !centralIDs.contains($0.id) }
            if filtered.count != cvConferenceContributions[index].tasks.count {
                cvConferenceContributions[index].tasks = filtered
                changedSet.insert(.cvConferenceContributions)
            }
        }
        let remainingTeachingWorkspaceTasks = (metadata.teachingWorkspaceTasks ?? [])
            .filter { !centralIDs.contains($0.id) }
        if remainingTeachingWorkspaceTasks.count != (metadata.teachingWorkspaceTasks ?? []).count {
            var updated = editableMetadataSnapshot
            updated.teachingWorkspaceTasks = remainingTeachingWorkspaceTasks
            metadata = Self.sanitizedMetadata(updated)
            changedSet.insert(.metadata)
        }
        guard !changedSet.isEmpty else { return }
        do {
            try persist(changedSet, includeBackup: false)
            loadError = nil
        } catch {
            loadError = error.localizedDescription
        }
    }

