    private func normalizedDefaultProjectFundingTasks(
        collaboratorNames: [String],
        projectStatus: ProjectLifecycleStatus,
        projectTasks: [ProjectTaskItem],
        suppressedSeedProjectTaskComments _: [String]
    ) -> [ProjectTaskItem] {
        let legacyComments = [
            "Inform chief/Tessa administrator about newly granted funds",
            "Informera chef/Tessaadministratör om nya beviljade medel",
            "Inform controller about newly granted funds",
            "Informera controller om nya beviljade medel",
            "Inform accounting officer about newly granted funds",
            "Informera redovisningsekonom om nya beviljade medel",
        ]
        let mergedComments = [
            "Inform chief/Tessa administrator, controller and accounting officer about newly granted funds",
            "Informera chef/Tessaadministratör, controller och redovisningsekonom om nya beviljade medel",
        ]
        let legacyCommentKeys = Set(legacyComments.compactMap(normalizedProjectTaskCommentKey))
        let mergedCommentKeys = Set(mergedComments.compactMap(normalizedProjectTaskCommentKey))

        let currentUserKeys = currentUserPresentedNameKeys()
        let leaderName = collaboratorNames.first?.nonEmpty ?? ""
        let isOwnProject = currentUserKeys.contains(normalizedPersonLookupName(leaderName))
        let isEligibleOwnProject = isOwnProject && (projectStatus == .planned || projectStatus == .ongoing)

        var normalizedTasks: [ProjectTaskItem] = []
        var hasMergedSeedTask = false

        for task in projectTasks {
            guard task.reminder == .newFundsReceived,
                  let key = normalizedProjectTaskCommentKey(task.comment) else {
                normalizedTasks.append(task)
                continue
            }

            if legacyCommentKeys.contains(key) {
                continue
            }

            if mergedCommentKeys.contains(key) {
                guard isEligibleOwnProject else { continue }
                guard !hasMergedSeedTask else { continue }
                hasMergedSeedTask = true
                normalizedTasks.append(task)
                continue
            }

            normalizedTasks.append(task)
        }

        return normalizedTasks
    }

