    func ensureLegacyNonPeerReviewedPublicationsMigrated() {
        let existingKeys = Set(publicationRecords.map(migrationKey(for:)))
        var seenKeys = existingKeys
        var retainedEntries: [CVOtherPublicationEntry] = []
        var nextNumber = (publicationRecords.compactMap { Int($0.number) }.max() ?? 0) + 1
        var didChange = false
        var didChangeJournals = false

        for entry in cvOtherPublications {
            guard shouldMigrateLegacyOtherPublication(entry) else {
                retainedEntries.append(entry)
                continue
            }

            let title = entry.localizedTitle(language: .english).nonEmpty
                ?? entry.localizedTitle(language: .swedish).nonEmpty
                ?? ""
            let journalName = entry.localizedOutlet(language: .english).nonEmpty
                ?? entry.localizedOutlet(language: .swedish).nonEmpty
                ?? ""

            guard !title.isEmpty, !journalName.isEmpty else {
                retainedEntries.append(entry)
                continue
            }

            let candidateRecord = PublicationRecord(
                number: String(nextNumber),
                title: title,
                journal: journalName,
                status: PublicationStatus.published.rawValue,
                doi: entry.doi,
                year: publicationMigrationYear(from: entry.date),
                publicationType: "Original",
                isPeerReviewed: false,
                authorNames: migratedAuthorNames(from: entry.authors)
            )
            let key = migrationKey(for: candidateRecord)

            if publicationJournal(named: journalName) == nil {
                publicationJournals.append(
                    PublicationJournal(
                        name: journalName,
                        abbreviatedName: journalName,
                        issnLTWAAbbreviatedName: PublicationLTWA.shortName(for: journalName)
                    )
                )
                didChangeJournals = true
            }

            if seenKeys.contains(key) {
                didChange = true
                continue
            }

            publicationRecords.append(candidateRecord)
            seenKeys.insert(key)
            nextNumber += 1
            didChange = true
        }

        guard didChange || didChangeJournals else { return }

        cvOtherPublications = retainedEntries

        do {
            refreshPublicationRecordsOnly()
            refreshCVOtherPublicationsOnly()
            try persist([.publicationRecords, .publicationJournals, .cvOtherPublications], includeBackup: false)
            loadError = nil
        } catch {
            loadError = error.localizedDescription
        }
    }

    func autosaveCVConferenceContribution(_ updated: CVConferenceContribution) {
        guard let index = cvConferenceContributions.firstIndex(where: { $0.id == updated.id }) else { return }
        let previous = cvConferenceContributions[index]
        do {
            let normalized = try normalizedCVConferenceContributionForPersistence(
                canonicalizedConferenceContribution(updated),
                previous: previous
            )
            guard normalized != previous else { return }
            let affectedSet: PersistenceSet = [.cvConferenceContributions]
            let previousStates = try persistedBaselineDocumentStates(for: affectedSet)
            pendingEmptyCVConferenceContributionIDs.remove(updated.id)
            cvConferenceContributions[index] = normalized
            refreshCVConferenceContributionsOnly()
            try enqueueAutosavePersistence(
                affectedSet,
                actionName: language.text("Edit conference contribution", "Redigera konferensbidrag"),
                previousStates: previousStates
            )
        } catch {
            cvConferenceContributions[index] = previous
            refreshCVConferenceContributionsOnly()
            persistenceStatus.isSaving = false
            loadError = error.localizedDescription
        }
    }

