    private func normalizedCVMediaAppearanceForPersistence(
        _ updated: CVMediaAppearance,
        previous: CVMediaAppearance
    ) throws -> CVMediaAppearance {
        var normalized = updated
        normalized.normalize()
        synchronizedMediaAppearanceAuthorID(&normalized)
        try synchronizeCVMediaAppearancePDFAttachmentForPersistence(&normalized, previous: previous)
        return normalized
    }

    private func normalizedCVConferenceContributionForPersistence(
        _ updated: CVConferenceContribution,
        previous: CVConferenceContribution
    ) throws -> CVConferenceContribution {
        var normalized = updated
        normalized.normalize()
        try synchronizeCVConferenceContributionPDFAttachmentForPersistence(&normalized, previous: previous)
        return normalized
    }

    private func synchronizeCVConferenceContributionPDFAttachmentForPersistence(
        _ contribution: inout CVConferenceContribution,
        previous: CVConferenceContribution
    ) throws {
        let hasAttachment = contribution.pdfFilename?.trimmedOrNil != nil
            || contribution.pdfPath?.trimmedOrNil != nil
        if !hasAttachment {
            contribution.pdfFilename = nil
            contribution.pdfPath = nil
            if previous.pdfFilename?.trimmedOrNil != nil || previous.pdfPath?.trimmedOrNil != nil {
                try Self.removeManagedCVConferenceContributionPDFIfPresent(forContributionID: contribution.id)
            }
            return
        }

        _ = try Self.canonicalizeCVConferenceContributionPDFAttachment(for: &contribution)
    }

    private func synchronizeCVMediaAppearancePDFAttachmentForPersistence(
        _ appearance: inout CVMediaAppearance,
        previous: CVMediaAppearance
    ) throws {
        let hasAttachment = appearance.pdfFilename?.trimmedOrNil != nil
            || appearance.pdfPath?.trimmedOrNil != nil
        if !hasAttachment {
            appearance.pdfFilename = nil
            appearance.pdfPath = nil
            if previous.pdfFilename?.trimmedOrNil != nil || previous.pdfPath?.trimmedOrNil != nil {
                try Self.removeManagedCVMediaAppearancePDFIfPresent(forMediaAppearanceID: appearance.id)
            }
            return
        }

        _ = try Self.canonicalizeCVMediaAppearancePDFAttachment(for: &appearance)
    }

    private func synchronizeCVReviewCertificatePDFAttachmentForPersistence(
        _ entry: inout CVReviewEntry,
        previous: CVReviewEntry
    ) throws {
        let hasAttachment = entry.certificateFilename?.trimmedOrNil != nil
            || entry.certificatePath?.trimmedOrNil != nil
            || entry.certificatePDFData?.isEmpty == false
        if !hasAttachment {
            entry.certificateFilename = nil
            entry.certificatePath = nil
            entry.certificatePDFData = nil
            if previous.certificateFilename?.trimmedOrNil != nil
                || previous.certificatePath?.trimmedOrNil != nil
                || previous.certificatePDFData?.isEmpty == false {
                try Self.removeManagedCVReviewCertificatePDFIfPresent(forReviewEntryID: entry.id)
            }
            return
        }

        _ = try Self.canonicalizeCVReviewCertificatePDFAttachment(for: &entry)
    }

