    func deleteCVConferenceContribution(id: String) {
        performUndoableChange(
            actionName: language.text("Archive conference contribution", "Arkivera konferensbidrag"),
            successMessage: language.text("Archived conference contribution.", "Arkiverade konferensbidrag."),
            failureMessage: language.text("Could not archive conference contribution.", "Kunde inte arkivera konferensbidrag."),
            scope: .cv
        ) {
            if let contribution = cvConferenceContributions.first(where: { $0.id == id }) {
                let title = contribution.localizedTitle(language: language).nonEmpty ?? contribution.displayTitle
                try archiveDeletion(
                    kind: "cv_conference_contribution",
                    title: title,
                    payload: contribution,
                    relatedDocumentStates: try archivedRelatedStatesForCVConferenceContributionDeletion()
                )
            }
            pendingEmptyCVConferenceContributionIDs.remove(id)
            cvConferenceContributions.removeAll { $0.id == id }
            // Round 11: the PDF stays on disk so Undo and the archive can
            // bring the record back with its file.
        }
    }

