    func deleteCVReviewEntry(id: String) {
        performUndoableChange(
            actionName: language.text("Archive review", "Arkivera sakkunniguppdrag"),
            successMessage: language.text("Archived review.", "Arkiverade sakkunniguppdrag."),
            failureMessage: language.text("Could not archive review.", "Kunde inte arkivera sakkunniguppdrag."),
            scope: .cv
        ) {
            if var review = cvReviewEntries.first(where: { $0.id == id }) {
                // Re-embed the certificate into the archived payload so the
                // archive stays self-contained after the managed file is
                // removed below; a later restore re-extracts it.
                if review.certificatePDFData == nil,
                   let resolvedURL = Self.resolveCVReviewCertificatePDFURL(
                       reviewEntryID: review.id,
                       certificatePath: review.certificatePath,
                       certificateFilename: review.certificateFilename
                   ),
                   let pdfData = try? Data(contentsOf: resolvedURL),
                   !pdfData.isEmpty {
                    review.certificatePDFData = pdfData
                }
                try archiveDeletion(
                    kind: "cv_review_entry",
                    title: review.displayTitle,
                    payload: review,
                    relatedDocumentStates: try archivedRelatedStatesForCVReviewEntryDeletion()
                )
            }
            pendingEmptyCVReviewEntryIDs.remove(id)
            cvReviewEntries.removeAll { $0.id == id }
            // Round 11: the certificate stays on disk so Undo can bring the
            // record back with its file (the archive keeps its own copy).
        }
    }

