    func saveTeachingRoleOptions(_ options: [TeachingRoleOption]) {
        let previousRoleIDs = Set(teachingRoleOptions.map(\.id))
        let normalizedOptions = Self.normalizedTeachingRoleOptions(options, language: language)
        let removedRoleIDs = previousRoleIDs.subtracting(normalizedOptions.map(\.id))

        performUndoableChange(
            actionName: language.text("Edit teaching roles", "Redigera undervisningsroller"),
            successMessage: language.text("Saved teaching roles.", "Sparade undervisningsroller."),
            failureMessage: language.text("Could not save teaching roles.", "Kunde inte spara undervisningsroller."),
            scope: .all
        ) {
            var updated = editableMetadataSnapshot
            updated.teachingRoleOptions = normalizedOptions
            metadata = updated

            guard !removedRoleIDs.isEmpty else { return }
            for index in teachingCourses.indices {
                teachingCourses[index].defaultRoles.removeAll { removedRoleIDs.contains($0.rawValue) }
            }
            for index in teachingAssignments.indices {
                teachingAssignments[index].roles.removeAll { removedRoleIDs.contains($0.rawValue) }
            }
        }
    }

