    func missingFieldIssues(includeHidden: Bool = false) -> [MissingFieldIssue] {
        if let cachedMissingFieldIssues {
            return includeHidden ? cachedMissingFieldIssues : visibleDataQualityWarnings(cachedMissingFieldIssues)
        }
        let issues = dataQualityMissingFieldIssues()
        cachedMissingFieldIssues = issues
        if saveValidationBaseline == nil {
            saveValidationBaseline = Self.criticalValueKeys(in: visibleDataQualityWarnings(issues))
        }
        if saveValidationLinkBaseline == nil {
            saveValidationLinkBaseline = Self.linkAndTimeKeys(in: visibleDataQualityWarnings(dataQualityLinkAndTimeIssues(forSaveCheck: true)))
        }
        return includeHidden ? issues : visibleDataQualityWarnings(issues)
    }

    // MARK: - F19: check after saving

    nonisolated static func criticalValueKeys(in issues: [MissingFieldIssue]) -> Set<String> {
        var keys: Set<String> = []
        for issue in issues {
            for field in issue.missingFields where isCriticalDataQualityField(field) {
                keys.insert("\(issue.id)|\(field)")
            }
        }
        return keys
    }

    nonisolated static func linkAndTimeKeys(in issues: [IntegrityIssue]) -> Set<String> {
        Set(issues.map { "\($0.id)|\($0.subtitle)" })
    }

    /// F19: shortly after a save, look for wrong values that were not there
    /// before (an end date before its start date, an invalid e-mail address or
    /// DOI) and say so. The save itself is never stopped: these are the Data
    /// view's own checks, shown where the change was made.
    private func scheduleSaveValidation() {
        saveValidationWorkItem?.cancel()
        let workItem = DispatchWorkItem { [weak self] in
            Task { @MainActor [weak self] in
                self?.runSaveValidation()
            }
        }
        saveValidationWorkItem = workItem
        DispatchQueue.main.asyncAfter(deadline: .now() + 1.5, execute: workItem)
    }

    func runSaveValidation() {
        saveValidationWorkItem?.cancel()
        saveValidationWorkItem = nil
        let startedAt = CFAbsoluteTimeGetCurrent()
        // Which part is slow: the missing-field list (rebuilt after any data
        // change, cached=no) or the link and time check (always run).
        let missingFieldsWereCached = cachedMissingFieldIssues != nil
        var missingFieldsMs = 0.0
        var linksMs = 0.0
        defer {
            appendPerformanceDiagnosticIfSlow(
                {
                    String(
                        format: "save-validation missing_ms=%.2f missing_cached=%@ links_ms=%.2f total_ms=%.2f",
                        missingFieldsMs,
                        missingFieldsWereCached ? "yes" : "no",
                        linksMs,
                        $0
                    )
                },
                startedAt: startedAt
            )
        }
        let hadBaseline = saveValidationBaseline != nil
        let hadLinkBaseline = saveValidationLinkBaseline != nil
        let issues = missingFieldIssues()
        missingFieldsMs = (CFAbsoluteTimeGetCurrent() - startedAt) * 1000
        let current = Self.criticalValueKeys(in: issues)
        let previous = hadBaseline ? (saveValidationBaseline ?? []) : current
        saveValidationBaseline = current
        let introduced = current.subtracting(previous)

        // Broken links and times in the wrong order come from the Data view's
        // integrity list; only their own, cheap pass is run here.
        let linksStartedAt = CFAbsoluteTimeGetCurrent()
        let linkIssues = visibleDataQualityWarnings(dataQualityLinkAndTimeIssues(forSaveCheck: true))
        linksMs = (CFAbsoluteTimeGetCurrent() - linksStartedAt) * 1000
        let currentLinks = Self.linkAndTimeKeys(in: linkIssues)
        let previousLinks = hadLinkBaseline ? (saveValidationLinkBaseline ?? []) : currentLinks
        saveValidationLinkBaseline = currentLinks
        let introducedLinks = currentLinks.subtracting(previousLinks)
        guard !introduced.isEmpty || !introducedLinks.isEmpty else { return }

        var lines: [String] = []
        for issue in issues {
            let fields = issue.missingFields.filter { introduced.contains("\(issue.id)|\($0)") }
            guard !fields.isEmpty else { continue }
            lines.append("\(issue.title): \(fields.joined(separator: ", "))")
        }
        for issue in linkIssues where introducedLinks.contains("\(issue.id)|\(issue.subtitle)") {
            lines.append("\(issue.title): \(issue.subtitle)")
        }
        guard !lines.isEmpty else { return }
        let shown = lines.prefix(2).joined(separator: " · ")
        let more = lines.count > 2 ? language.text(" (and \(lines.count - 2) more)", " (och \(lines.count - 2) till)") : ""
        notice = StoreNotice(
            message: language.text("Saved, but check: ", "Sparat, men kontrollera: ") + shown + more,
            tone: .info
        )
    }

    func integrityIssues(includeHidden: Bool = false) -> [IntegrityIssue] {
        if let cachedIntegrityIssues {
            return includeHidden ? cachedIntegrityIssues : visibleDataQualityWarnings(cachedIntegrityIssues)
        }
        // F24: overdue tasks are reminders (shown in the calendar), not integrity findings.
        let overduePrefix = language.text("Overdue", "Försenad")
        let issues = dataQualityIntegrityIssues().filter { !$0.subtitle.hasPrefix(overduePrefix) }
        cachedIntegrityIssues = issues
        return includeHidden ? issues : visibleDataQualityWarnings(issues)
    }

    func duplicateIssues(includeHidden: Bool = false) -> [DuplicateIssue] {
        if let cachedDuplicateIssues {
            return includeHidden ? cachedDuplicateIssues : visibleDataQualityWarnings(cachedDuplicateIssues)
        }
        let issues = dataQualityDuplicateIssues()
        cachedDuplicateIssues = issues
        return includeHidden ? issues : visibleDataQualityWarnings(issues)
    }

    func dataQualityWarningKey(for issue: MissingFieldIssue) -> String {
        [
            "data-quality-warning:v1",
            "missing",
            issue.entityKind.rawValue,
            Self.duplicateWarningKeyComponent(issue.recordID),
            Self.duplicateWarningKeyComponent(issue.id),
        ].joined(separator: "|")
    }

    /// Round 12: the key a missing-field warning is hidden under from now on.
    /// It includes how many fields are missing, so a new problem on the same
    /// record (one more missing field) shows again instead of staying hidden.
    /// Warnings hidden earlier (the key above) stay hidden as before.
    func dataQualityWarningPreciseKey(for issue: MissingFieldIssue) -> String {
        [
            "data-quality-warning:v2",
            "missing",
            issue.entityKind.rawValue,
            Self.duplicateWarningKeyComponent(issue.recordID),
            Self.duplicateWarningKeyComponent(issue.id),
            "\(issue.missingFields.count)",
        ].joined(separator: "|")
    }

    func dataQualityWarningKey(for issue: DuplicateIssue) -> String? {
        duplicateWarningSuppressionKey(
            groupKind: issue.groupKind,
            normalizedKey: issue.normalizedKey,
            recordIDs: issue.entries.map(\.recordID)
        )
    }

    func dataQualityWarningKey(for issue: IntegrityIssue) -> String {
        [
            "data-quality-warning:v1",
            "integrity",
            issue.kind.rawValue,
            Self.duplicateWarningKeyComponent(issue.recordID),
            Self.duplicateWarningKeyComponent(issue.id),
        ].joined(separator: "|")
    }

