    func duplicateWarningSuppressionKey(
        groupKind: DuplicateIssue.GroupKind,
        normalizedKey: String,
        recordIDs: [String]
    ) -> String? {
        guard let key = normalizedKey.trimmedOrNil else { return nil }
        let normalizedRecordIDs = Self.normalizedDuplicateWarningRecordIDs(recordIDs)
        guard !normalizedRecordIDs.isEmpty else { return nil }

        let recordKey = normalizedRecordIDs
            .map(Self.duplicateWarningKeyComponent)
            .joined()
        return [
            "duplicate-warning:v1",
            groupKind.rawValue,
            "key:\(Self.duplicateWarningKeyComponent(key))",
            "records:\(recordKey)",
        ].joined(separator: "|")
    }

    func isDuplicateWarningSuppressed(
        groupKind: DuplicateIssue.GroupKind,
        normalizedKey: String,
        recordIDs: [String]
    ) -> Bool {
        guard
            let suppressionKey = duplicateWarningSuppressionKey(
                groupKind: groupKind,
                normalizedKey: normalizedKey,
                recordIDs: recordIDs
            )
        else {
            return false
        }
        return isDataQualityWarningHidden(key: suppressionKey)
    }

