    @discardableResult
    func ignoreDuplicateWarning(
        groupKind: DuplicateIssue.GroupKind,
        normalizedKey: String,
        recordIDs: [String]
    ) -> Bool {
        guard
            let suppressionKey = duplicateWarningSuppressionKey(
                groupKind: groupKind,
                normalizedKey: normalizedKey,
                recordIDs: recordIDs
            ),
            !isDataQualityWarningHidden(key: suppressionKey)
        else {
            return false
        }

        return hideDataQualityWarning(key: suppressionKey)
    }

    private func visibleDataQualityWarnings(_ issues: [MissingFieldIssue]) -> [MissingFieldIssue] {
        issues.filter { !isDataQualityWarningHidden($0) }
    }

    private func visibleDataQualityWarnings(_ issues: [DuplicateIssue]) -> [DuplicateIssue] {
        issues.filter { !isDataQualityWarningHidden($0) }
    }

    private func visibleDataQualityWarnings(_ issues: [IntegrityIssue]) -> [IntegrityIssue] {
        issues.filter { !isDataQualityWarningHidden($0) }
    }

    private func isDataQualityWarningHidden(key: String) -> Bool {
        hiddenDataQualityWarningKeySet.contains(key)
    }

    /// The Data view asks this once per row on every redraw (hundreds of
    /// rows). It used to build a fully sanitized metadata copy (sorting the
    /// hidden keys, normalizing every task) and hash all keys for each
    /// question, which made one redraw of the Data view take 300-600 ms.
    /// The raw key lists are now compared with the ones the cached set was
    /// built from; an unchanged list shares its storage, so the check is
    /// constant time. The set is the same one the sanitized snapshot gave:
    /// trimmed hidden keys plus trimmed legacy duplicate keys.
    private var hiddenDataQualityWarningKeySet: Set<String> {
        // Read the two fields only; copying the whole metadata per row was
        // part of the cost.
        let readsPending = pendingMetadataSnapshot != nil
        let hiddenKeys = readsPending
            ? pendingMetadataSnapshot?.hiddenDataQualityWarningKeys
            : metadata.hiddenDataQualityWarningKeys
        let ignoredKeys = readsPending
            ? pendingMetadataSnapshot?.ignoredDuplicateWarningKeys
            : metadata.ignoredDuplicateWarningKeys
        if let cachedHiddenDataQualityWarningKeySet,
           let cachedSource = cachedHiddenDataQualityWarningKeySetSource,
           cachedSource.hidden == hiddenKeys,
           cachedSource.ignored == ignoredKeys {
            return cachedHiddenDataQualityWarningKeySet
        }
        let keySet = Self.combinedHiddenDataQualityWarningKeys(hidden: hiddenKeys, ignored: ignoredKeys)
        cachedHiddenDataQualityWarningKeySet = keySet
        cachedHiddenDataQualityWarningKeySetSource = (hiddenKeys, ignoredKeys)
        return keySet
    }

    /// Same keys `DataSourceMetadata.migrateLegacyFields()` leaves in the two
    /// lists, as one set.
    nonisolated static func combinedHiddenDataQualityWarningKeys(hidden: [String]?, ignored: [String]?) -> Set<String> {
        Set((hidden ?? []).compactMap(\.trimmedOrNil))
            .union((ignored ?? []).compactMap(\.trimmedOrNil))
    }

    @discardableResult
    private func hideDataQualityWarning(key: String) -> Bool {
        guard key.trimmedOrNil != nil, !hiddenDataQualityWarningKeySet.contains(key) else { return false }
        return setDataQualityWarningHidden(key: key, hidden: true)
    }

    @discardableResult
    private func showDataQualityWarning(key: String) -> Bool {
        guard key.trimmedOrNil != nil, hiddenDataQualityWarningKeySet.contains(key) else { return false }
        return setDataQualityWarningHidden(key: key, hidden: false)
    }

    /// Hiding or showing one warning used to write the whole metadata
    /// (all ~1,800 calendar meetings included: 115 ms encoding plus 40-60 ms
    /// writing) on the main thread for every click. It now takes the same
    /// queued background write as the other workspace preferences; undo,
    /// the history entry and the notice are unchanged.
    @discardableResult
    private func setDataQualityWarningHidden(key: String, hidden: Bool) -> Bool {
        let startedAt = CFAbsoluteTimeGetCurrent()
        let actionName = hidden
            ? language.text("Hide data quality warning", "Dölj datakvalitetsvarning")
            : language.text("Show data quality warning", "Visa datakvalitetsvarning")
        let previous = editableMetadataSnapshot
        var updated = previous
        var hiddenKeys = Set(updated.hiddenDataQualityWarningKeys ?? [])
        var legacyDuplicateKeys = Set(updated.ignoredDuplicateWarningKeys ?? [])
        if hidden {
            hiddenKeys.insert(key)
        } else {
            hiddenKeys.remove(key)
            legacyDuplicateKeys.remove(key)
        }
        updated.hiddenDataQualityWarningKeys = hiddenKeys.isEmpty ? nil : hiddenKeys.sorted()
        updated.ignoredDuplicateWarningKeys = legacyDuplicateKeys.isEmpty ? nil : legacyDuplicateKeys.sorted()
        let sanitizedUpdated = Self.sanitizedMetadata(updated)
        guard sanitizedUpdated != previous else {
            appendPerformanceDiagnostic("metadata-undoable-noop action=\(actionName) reason=unchanged-metadata")
            loadError = nil
            return false
        }
        loadError = nil
        persistMetadataSilently(sanitizedUpdated, undoActionName: actionName)
        // The only failure that leaves the change unapplied is an
        // unsupported storage schema: the new keys were then never published.
        guard (pendingMetadataSnapshot ?? metadata).hiddenDataQualityWarningKeys
                == sanitizedUpdated.hiddenDataQualityWarningKeys else {
            notice = StoreNotice(
                message: hidden
                    ? language.text("Could not hide data quality warning.", "Kunde inte dölja datakvalitetsvarning.")
                    : language.text("Could not show data quality warning.", "Kunde inte visa datakvalitetsvarning."),
                tone: .error
            )
            return false
        }
        notice = StoreNotice(
            message: hidden
                ? language.text("Hidden data quality warning.", "Dolde datakvalitetsvarning.")
                : language.text("Showing data quality warning again.", "Visar datakvalitetsvarning igen."),
            tone: .success
        )
        appendPerformanceDiagnostic(
            String(
                format: "data-quality-warning-visibility hidden=%@ main_ms=%.2f hidden_keys=%ld",
                hidden ? "yes" : "no",
                (CFAbsoluteTimeGetCurrent() - startedAt) * 1000,
                hiddenKeys.count
            )
        )
        return true
    }

    /// Number of hidden data quality warnings of every kind (missing
    /// fields, duplicates, integrity, translations, names, activities).
    var hiddenDataQualityWarningTotalCount: Int {
        hiddenDataQualityWarningKeySet.count
    }

    /// Shows every hidden warning again in one step, including those hidden
    /// in older versions where one hidden warning covered a whole record.
    /// Can be undone with Ångra.
    @discardableResult
    func showAllHiddenDataQualityWarnings() -> Bool {
        let previous = editableMetadataSnapshot
        let count = Self.combinedHiddenDataQualityWarningKeys(
            hidden: previous.hiddenDataQualityWarningKeys,
            ignored: previous.ignoredDuplicateWarningKeys
        ).count
        guard count > 0 else { return false }
        var updated = previous
        updated.hiddenDataQualityWarningKeys = nil
        updated.ignoredDuplicateWarningKeys = nil
        let sanitizedUpdated = Self.sanitizedMetadata(updated)
        loadError = nil
        persistMetadataSilently(
            sanitizedUpdated,
            undoActionName: language.text("Show all hidden warnings", "Visa alla dolda varningar")
        )
        guard (pendingMetadataSnapshot ?? metadata).hiddenDataQualityWarningKeys == nil else {
            notice = StoreNotice(
                message: language.text("Could not show the hidden warnings.", "Kunde inte visa de dolda varningarna."),
                tone: .error
            )
            return false
        }
        notice = StoreNotice(
            message: language.text(
                "Showing \(count) hidden warnings again.",
                "Visar \(count) dolda varningar igen."
            ),
            tone: .success
        )
        return true
    }

    private static func normalizedDuplicateWarningRecordIDs(_ recordIDs: [String]) -> [String] {
        Set(recordIDs.compactMap(\.trimmedOrNil)).sorted()
    }

    private static func duplicateWarningKeyComponent(_ value: String) -> String {
        "\(value.utf8.count):\(value)"
    }

    func supportsDuplicateMerge(for kind: DuplicateIssue.GroupKind) -> Bool {
        switch kind {
        case .researchers, .journals, .funders, .managers, .projects, .publications:
            return true
        }
    }

    @discardableResult
    func mergeDuplicateRecords(
        groupKind: DuplicateIssue.GroupKind,
        canonicalRecordID: String,
        duplicateRecordIDs: [String],
        lockedRecordsConfirmed: Bool = false
    ) -> Bool {
        guard let canonicalID = canonicalRecordID.trimmedOrNil else { return false }
        let duplicateIDs = Array(
            NSOrderedSet(
                array: duplicateRecordIDs
                    .compactMap(\.trimmedOrNil)
                    .filter { $0 != canonicalID }
            )
        ) as? [String] ?? []
        guard !duplicateIDs.isEmpty else { return false }

        // Round 11: a merge rewrites names in the records that point to the
        // duplicate. Locked records among them are listed and the merge
        // waits for an explicit yes.
        if !lockedRecordsConfirmed {
            let locked = lockedRecordsRewrittenByMerge(groupKind: groupKind, duplicateIDs: Set(duplicateIDs))
            if !locked.isEmpty {
                // After the merge sheet has closed, so the question can show.
                DispatchQueue.main.asyncAfter(deadline: .now() + 0.3) { [weak self] in
                    guard let self else { return }
                    self.requestImpactConfirmation(
                        title: self.language.text("Merge and change locked records?", "Slå ihop och ändra låsta poster?"),
                        message: self.language.text(
                            "These locked records point to the duplicate. Their link and written name will change to the record you keep.",
                            "De här låsta posterna pekar på dubbletten. Deras koppling och skrivna namn ändras till posten du behåller."
                        ),
                        details: locked,
                        confirmTitle: self.language.text("Merge anyway", "Slå ihop ändå")
                    ) { [weak self] in
                        _ = self?.mergeDuplicateRecords(
                            groupKind: groupKind,
                            canonicalRecordID: canonicalID,
                            duplicateRecordIDs: duplicateIDs,
                            lockedRecordsConfirmed: true
                        )
                    }
                }
                return true
            }
        }

        let actionName = language.text("Merge duplicates", "Slå ihop dubletter")
        // Round 13: the merge saves everything, metadata included, so a
        // queued metadata write is taken in first (see performUndoableChange).
        promotePendingMetadataSnapshotIfNeeded()
        let previousSnapshot = currentSnapshot()
        let previousArchivedRecords: [ArchivedRecordEnvelope]
        do {
            previousArchivedRecords = try loadArchivedRecords()
        } catch {
            loadError = error.localizedDescription
            notice = StoreNotice(
                message: language.text("Could not read the archive.", "Kunde inte läsa arkivet."),
                tone: .error
            )
            return false
        }

        do {
            try performDuplicateMerge(
                groupKind: groupKind,
                canonicalID: canonicalID,
                duplicateIDs: Set(duplicateIDs)
            )
            refreshState(for: .all)
            try persistScope(.all)
            registerArchiveUndo(snapshot: previousSnapshot, archivedRecords: previousArchivedRecords, actionName: actionName)
            appendRecentRecordRevision(actionName: actionName)
            notice = StoreNotice(
                message: language.text(
                    "Merged duplicates and archived the replaced records.",
                    "Slog ihop dubletter och arkiverade ersatta poster."
                ),
                tone: .success
            )
            loadError = nil
            return true
        } catch {
            restoreSnapshotWithoutUndo(previousSnapshot)
            let primaryError = error
            handlePersistenceRollback(
                primaryError: primaryError,
                context: "Duplicate merge"
            ) {
                try saveArchivedRecords(previousArchivedRecords)
            }
            persistenceStatus.isSaving = false
            notice = StoreNotice(
                message: language.text("Could not merge duplicates.", "Kunde inte slå ihop dubletter."),
                tone: .error
            )
            return false
        }
    }

    /// Round 11: the locked records whose link or written name a merge of
    /// these duplicates would change, as lines for the confirmation.
    func lockedRecordsRewrittenByMerge(groupKind: DuplicateIssue.GroupKind, duplicateIDs: Set<String>) -> [String] {
        let grant = language.text("Grant call or grant", "Utlysning eller anslag")
        let publication = language.text("Publication", "Publikation")
        let project = language.text("Project", "Projekt")
        let doctoral = language.text("Doctoral candidate", "Doktorand")
        var lines: [String] = []
        switch groupKind {
        case .funders, .managers:
            for application in applications where application.isEditingLocked
                && (duplicateIDs.contains(application.organizationID ?? "") || duplicateIDs.contains(application.applicationManagerID ?? "")) {
                lines.append("\(grant): \(application.displayTitle)")
            }
            for candidate in doctoralCandidates where candidate.isEditingLocked && duplicateIDs.contains(candidate.institutionID ?? "") {
                lines.append("\(doctoral): \(candidate.candidateName)")
            }
        case .projects:
            for application in applications where application.isEditingLocked && duplicateIDs.contains(application.projectID ?? "") {
                lines.append("\(grant): \(application.displayTitle)")
            }
            for record in publicationRecords where record.isEditingLocked && duplicateIDs.contains(record.projectID ?? "") {
                lines.append("\(publication): \(record.title)")
            }
            for candidate in doctoralCandidates where candidate.isEditingLocked && duplicateIDs.contains(candidate.linkedProjectID ?? "") {
                lines.append("\(doctoral): \(candidate.candidateName)")
            }
        case .researchers:
            let variantKeys = Set(publicationAuthors
                .filter { duplicateIDs.contains($0.id) }
                .flatMap { self.authorNameVariants(for: $0) }
                .map { self.normalizedPersonLookupName($0) })
            func named(_ name: String) -> Bool { variantKeys.contains(self.normalizedPersonLookupName(name)) }
            for record in publicationRecords where record.isEditingLocked
                && (record.authorIDs.contains(where: duplicateIDs.contains) || record.authorNames.contains(where: named)) {
                lines.append("\(publication): \(record.title)")
            }
            for application in applications where application.isEditingLocked
                && (application.coApplicantAuthorIDs.contains(where: duplicateIDs.contains) || application.coApplicants.contains(where: named)) {
                lines.append("\(grant): \(application.displayTitle)")
            }
            for item in projects where item.isEditingLocked
                && (item.collaboratorAuthorIDs.contains(where: duplicateIDs.contains) || item.collaboratorNames.contains(where: named)) {
                lines.append("\(project): \(item.nameSv.nonEmpty ?? item.nameEn)")
            }
            for candidate in doctoralCandidates where candidate.isEditingLocked
                && (duplicateIDs.contains(candidate.candidateAuthorID ?? "") || named(candidate.candidateName)
                    || candidate.supervisors.contains(where: { duplicateIDs.contains($0.authorID ?? "") || named($0.name) })) {
                lines.append("\(doctoral): \(candidate.candidateName)")
            }
        case .journals:
            for record in publicationRecords where record.isEditingLocked && duplicateIDs.contains(record.journalID ?? "") {
                lines.append("\(publication): \(record.title)")
            }
        case .publications:
            break
        }
        return lines
    }

    private func performDuplicateMerge(
        groupKind: DuplicateIssue.GroupKind,
        canonicalID: String,
        duplicateIDs: Set<String>
    ) throws {
        switch groupKind {
        case .researchers:
            try mergeDuplicateResearchers(canonicalID: canonicalID, duplicateIDs: duplicateIDs)
        case .journals:
            try mergeDuplicateJournals(canonicalID: canonicalID, duplicateIDs: duplicateIDs)
        case .funders, .managers:
            try mergeDuplicateOrganizations(canonicalID: canonicalID, duplicateIDs: duplicateIDs)
        case .projects:
            try mergeDuplicateProjects(canonicalID: canonicalID, duplicateIDs: duplicateIDs)
        case .publications:
            try mergeDuplicatePublications(canonicalID: canonicalID, duplicateIDs: duplicateIDs)
        }
    }

    private func mergeDuplicateResearchers(canonicalID: String, duplicateIDs: Set<String>) throws {
        guard let canonical = publicationAuthors.first(where: { $0.id == canonicalID }) else {
            throw duplicateMergeError(language.text("The selected researcher could not be found.", "Den valda forskaren kunde inte hittas."))
        }
        let duplicates = publicationAuthors.filter { duplicateIDs.contains($0.id) }
        guard !duplicates.isEmpty else {
            throw duplicateMergeError(language.text("No duplicate researchers were found.", "Inga dubbla forskare hittades."))
        }
        let relatedStates = try archivedRelatedStatesForPublicationAuthorDeletion()

        for duplicate in duplicates {
            let variants = authorNameVariants(for: duplicate)
            propagateAuthorRename(from: variants, to: canonical.name)
            moveAuthorIDReferences(from: duplicate.id, oldVariants: variants, to: canonical)
            replaceTaskParticipantReferences(from: variants, to: canonical.name)
            migrateRememberedSelectionID(from: duplicate.id, to: canonical.id, destinations: [.people])
        }

        publicationAuthors.removeAll { duplicateIDs.contains($0.id) }
        for duplicate in duplicates {
            try archiveDeletion(
                kind: "publication_author",
                title: duplicate.name.nonEmpty ?? duplicate.displayName,
                payload: duplicate,
                relatedDocumentStates: relatedStates
            )
        }
    }

    private func mergeDuplicateJournals(canonicalID: String, duplicateIDs: Set<String>) throws {
        guard let canonical = publicationJournals.first(where: { $0.id == canonicalID }) else {
            throw duplicateMergeError(language.text("The selected journal could not be found.", "Den valda tidskriften kunde inte hittas."))
        }
        let duplicates = publicationJournals.filter { duplicateIDs.contains($0.id) }
        guard !duplicates.isEmpty else {
            throw duplicateMergeError(language.text("No duplicate journals were found.", "Inga dubbla tidskrifter hittades."))
        }
        let relatedStates = try archivedRelatedStatesForPublicationJournalDeletion()

        for duplicate in duplicates {
            // "Alla kopplingar via id": everything that points to the
            // duplicate, whatever its text says, points to the kept journal
            // (first, so that the rename below also tidies their dated steps).
            for recordIndex in publicationRecords.indices {
                if publicationRecords[recordIndex].journalID == duplicate.id {
                    publicationRecords[recordIndex].journalID = canonical.id
                    publicationRecords[recordIndex].journal = canonical.name
                }
                for attemptIndex in publicationRecords[recordIndex].previousAttempts.indices
                where publicationRecords[recordIndex].previousAttempts[attemptIndex].journalID == duplicate.id {
                    publicationRecords[recordIndex].previousAttempts[attemptIndex].journalID = canonical.id
                    publicationRecords[recordIndex].previousAttempts[attemptIndex].journal = canonical.name
                }
            }
            for reviewIndex in cvReviewEntries.indices where cvReviewEntries[reviewIndex].journalID == duplicate.id {
                cvReviewEntries[reviewIndex].journalID = canonical.id
                cvReviewEntries[reviewIndex].journalName = canonical.name
            }
            propagateJournalRename(from: duplicate.name, to: canonical)
            for contributionIndex in cvConferenceContributions.indices where cvConferenceContributions[contributionIndex].journalID == duplicate.id {
                cvConferenceContributions[contributionIndex].journalID = canonical.id
                cvConferenceContributions[contributionIndex].journalName = canonical.name
                cvConferenceContributions[contributionIndex] = canonicalizedConferenceContribution(cvConferenceContributions[contributionIndex])
            }
            migrateRememberedSelectionID(from: duplicate.id, to: canonical.id, destinations: [.journals])
        }

        publicationJournals.removeAll { duplicateIDs.contains($0.id) }
        for duplicate in duplicates {
            try archiveDeletion(
                kind: "publication_journal",
                title: duplicate.name.nonEmpty ?? duplicate.id,
                payload: duplicate,
                relatedDocumentStates: relatedStates
            )
        }
    }

    private func mergeDuplicateOrganizations(canonicalID: String, duplicateIDs: Set<String>) throws {
        guard let canonical = organizations.first(where: { $0.id == canonicalID }) else {
            throw duplicateMergeError(language.text("The selected organization could not be found.", "Den valda organisationen kunde inte hittas."))
        }
        let duplicates = organizations.filter { duplicateIDs.contains($0.id) }
        guard !duplicates.isEmpty else {
            throw duplicateMergeError(language.text("No duplicate organizations were found.", "Inga dubbla organisationer hittades."))
        }
        let relatedStates = try archivedRelatedStatesForOrganizationDeletion()

        // Round 11: the duplicate's congresses move to the organization that
        // is kept (first, so contributions, travel and tasks linked to them
        // keep their congress), and so do its contact persons.
        var kept = canonical
        if let canonicalIndex = organizations.firstIndex(where: { $0.id == canonicalID }) {
            var keptCongressIDs = Set(organizations[canonicalIndex].congresses.map(\.id))
            var keptContactIDs = Set(organizations[canonicalIndex].employerContacts.map(\.id))
            for duplicate in duplicates {
                for congress in duplicate.congresses where !keptCongressIDs.contains(congress.id) {
                    organizations[canonicalIndex].congresses.append(congress)
                    keptCongressIDs.insert(congress.id)
                }
                for contact in duplicate.employerContacts where !keptContactIDs.contains(contact.id) {
                    organizations[canonicalIndex].employerContacts.append(contact)
                    keptContactIDs.insert(contact.id)
                }
            }
            kept = organizations[canonicalIndex]
        }

        for duplicate in duplicates {
            replaceOrganizationReferences(from: duplicate, to: kept)
            replaceOrganizationSettingReferences(from: duplicate.id, to: canonicalID)
            migrateRememberedSelectionID(from: duplicate.id, to: canonical.id, destinations: [.organizations])
        }

        // F21: the duplicate's units move to the organization that is kept,
        // so rows that pointed into the duplicate's tree still find their unit.
        if let canonicalIndex = organizations.firstIndex(where: { $0.id == canonicalID }) {
            var keptUnitIDs = Set(organizations[canonicalIndex].units.map(\.id))
            for duplicate in duplicates {
                for unit in duplicate.units where !keptUnitIDs.contains(unit.id) {
                    organizations[canonicalIndex].units.append(unit)
                    keptUnitIDs.insert(unit.id)
                }
            }
        }

        organizations.removeAll { duplicateIDs.contains($0.id) }
        managers = derivedManagers(from: organizations)
        for duplicate in duplicates {
            try archiveDeletion(
                kind: "organization",
                title: duplicate.nameSv.nonEmpty ?? duplicate.id,
                payload: duplicate,
                relatedDocumentStates: relatedStates
            )
        }
    }

    private func mergeDuplicateProjects(canonicalID: String, duplicateIDs: Set<String>) throws {
        guard let canonical = projects.first(where: { $0.id == canonicalID }) else {
            throw duplicateMergeError(language.text("The selected project could not be found.", "Det valda projektet kunde inte hittas."))
        }
        let duplicates = projects.filter { duplicateIDs.contains($0.id) }
        guard !duplicates.isEmpty else {
            throw duplicateMergeError(language.text("No duplicate projects were found.", "Inga dubbla projekt hittades."))
        }
        let relatedStates = try archivedRelatedStatesForProjectDeletion()

        for duplicate in duplicates {
            replaceProjectReferences(from: duplicate, to: canonical)
            migrateRememberedSelectionID(from: duplicate.id, to: canonical.id, destinations: [.projects])
        }

        projects.removeAll { duplicateIDs.contains($0.id) }
        for duplicate in duplicates {
            try archiveDeletion(
                kind: "project",
                title: duplicate.nameSv.nonEmpty ?? duplicate.id,
                payload: duplicate,
                relatedDocumentStates: relatedStates
            )
        }
    }

    private func mergeDuplicatePublications(canonicalID: String, duplicateIDs: Set<String>) throws {
        guard let canonical = publicationRecords.first(where: { $0.id == canonicalID }) else {
            throw duplicateMergeError(language.text("The selected publication could not be found.", "Den valda publikationen kunde inte hittas."))
        }
        let duplicates = publicationRecords.filter { duplicateIDs.contains($0.id) }
        guard !duplicates.isEmpty else {
            throw duplicateMergeError(language.text("No duplicate publications were found.", "Inga dubbla publikationer hittades."))
        }
        let relatedStates = try archivedRelatedStatesForPublicationDeletion()

        for duplicate in duplicates {
            replacePublicationReferences(from: duplicate.id, to: canonical.id)
            migrateRememberedSelectionID(from: duplicate.id, to: canonical.id, destinations: [.publications])
        }

        publicationRecords.removeAll { duplicateIDs.contains($0.id) }
        for duplicate in duplicates {
            try archiveDeletion(
                kind: "publication_record",
                title: duplicate.title.nonEmpty ?? duplicate.id,
                payload: duplicate,
                relatedDocumentStates: relatedStates
            )
        }
    }

    private func moveAuthorIDReferences(from duplicateID: String, oldVariants: Set<String>, to canonical: PublicationAuthor) {
        for assignmentIndex in teachingAssignments.indices where teachingAssignments[assignmentIndex].authorID == duplicateID {
            teachingAssignments[assignmentIndex].authorID = canonical.id
        }
        for candidateIndex in doctoralCandidates.indices {
            if doctoralCandidates[candidateIndex].candidateAuthorID == duplicateID ||
                oldVariants.contains(doctoralCandidates[candidateIndex].candidateName) {
                doctoralCandidates[candidateIndex].candidateAuthorID = canonical.id
                doctoralCandidates[candidateIndex].candidateName = canonical.name
            }
            for supervisorIndex in doctoralCandidates[candidateIndex].supervisors.indices {
                let supervisor = doctoralCandidates[candidateIndex].supervisors[supervisorIndex]
                if supervisor.authorID == duplicateID || oldVariants.contains(supervisor.name) {
                    doctoralCandidates[candidateIndex].supervisors[supervisorIndex].authorID = canonical.id
                    doctoralCandidates[candidateIndex].supervisors[supervisorIndex].name = canonical.name
                }
            }
            doctoralCandidates[candidateIndex].normalize()
        }
        for appearanceIndex in cvMediaAppearances.indices {
            if cvMediaAppearances[appearanceIndex].authorID == duplicateID {
                cvMediaAppearances[appearanceIndex].authorID = canonical.id
            }
            cvMediaAppearances[appearanceIndex].authorIDs = cvMediaAppearances[appearanceIndex].authorIDs.map {
                $0 == duplicateID ? canonical.id : $0
            }
            cvMediaAppearances[appearanceIndex].normalize()
        }
        for reviewIndex in cvReviewEntries.indices where cvReviewEntries[reviewIndex].authorID == duplicateID {
            cvReviewEntries[reviewIndex].authorID = canonical.id
        }
        // Round 11: links the merge used to leave pointing at the removed
        // person (students, conference contributors, congress participants
        // and the user's own person).
        for assignmentIndex in teachingAssignments.indices where teachingAssignments[assignmentIndex].studentAuthorID == duplicateID {
            teachingAssignments[assignmentIndex].studentAuthorID = canonical.id
        }
        for contributionIndex in cvConferenceContributions.indices {
            if cvConferenceContributions[contributionIndex].contributorAuthorIDs.contains(duplicateID) {
                cvConferenceContributions[contributionIndex].contributorAuthorIDs = uniquedNonEmptyStrings(
                    cvConferenceContributions[contributionIndex].contributorAuthorIDs.map { $0 == duplicateID ? canonical.id : $0 }
                )
            }
            if cvConferenceContributions[contributionIndex].presentedByAuthorID == duplicateID {
                cvConferenceContributions[contributionIndex].presentedByAuthorID = canonical.id
            }
        }
        for organizationIndex in organizations.indices {
            for congressIndex in organizations[organizationIndex].congresses.indices {
                let congress = organizations[organizationIndex].congresses[congressIndex]
                if congress.participantAuthorIDs.contains(duplicateID) {
                    organizations[organizationIndex].congresses[congressIndex].participantAuthorIDs = uniquedNonEmptyStrings(
                        congress.participantAuthorIDs.map { $0 == duplicateID ? canonical.id : $0 }
                    )
                }
                if congress.participantNames.contains(where: { oldVariants.contains($0) }) {
                    organizations[organizationIndex].congresses[congressIndex].participantNames = uniquedNonEmptyStrings(
                        congress.participantNames.map { oldVariants.contains($0) ? canonical.name : $0 }
                    )
                }
            }
        }
        if metadata.currentUserAuthorID == duplicateID {
            var updatedMetadata = editableMetadataSnapshot
            updatedMetadata.currentUserAuthorID = canonical.id
            metadata = updatedMetadata
        }
        replacePersonAuthorIDLinks(from: duplicateID, to: canonical.id)
    }

    /// F13b: moves one researcher's id to another in every list of people kept
    /// by name and id (co-applicants, project members, publication authors,
    /// task and meeting participants), or removes it when there is no
    /// replacement. The names are not touched here.
    private func replacePersonAuthorIDLinks(from oldID: String, to newID: String?) {
        func replaced(_ ids: [String]) -> [String] {
            uniquedNonEmptyStrings(ids.compactMap { $0 == oldID ? newID : $0 })
        }
        for index in applications.indices where applications[index].coApplicantAuthorIDs.contains(oldID) {
            applications[index].coApplicantAuthorIDs = replaced(applications[index].coApplicantAuthorIDs)
        }
        for index in projects.indices {
            if projects[index].collaboratorAuthorIDs.contains(oldID) {
                projects[index].collaboratorAuthorIDs = replaced(projects[index].collaboratorAuthorIDs)
            }
            for taskIndex in projects[index].projectTasks.indices
            where projects[index].projectTasks[taskIndex].participantAuthorIDs.contains(oldID) {
                projects[index].projectTasks[taskIndex].participantAuthorIDs =
                    replaced(projects[index].projectTasks[taskIndex].participantAuthorIDs)
            }
        }
        for index in organizations.indices {
            for taskIndex in organizations[index].projectTasks.indices
            where organizations[index].projectTasks[taskIndex].participantAuthorIDs.contains(oldID) {
                organizations[index].projectTasks[taskIndex].participantAuthorIDs =
                    replaced(organizations[index].projectTasks[taskIndex].participantAuthorIDs)
            }
        }
        for index in publicationRecords.indices {
            if publicationRecords[index].authorIDs.contains(oldID) {
                publicationRecords[index].authorIDs = replaced(publicationRecords[index].authorIDs)
            }
            if publicationRecords[index].correspondingAuthorID == oldID {
                publicationRecords[index].correspondingAuthorID = newID
            }
            for taskIndex in publicationRecords[index].publicationTasks.indices
            where publicationRecords[index].publicationTasks[taskIndex].participantAuthorIDs.contains(oldID) {
                publicationRecords[index].publicationTasks[taskIndex].participantAuthorIDs =
                    replaced(publicationRecords[index].publicationTasks[taskIndex].participantAuthorIDs)
            }
        }
        for index in cvConferenceContributions.indices {
            for taskIndex in cvConferenceContributions[index].tasks.indices
            where cvConferenceContributions[index].tasks[taskIndex].participantAuthorIDs.contains(oldID) {
                cvConferenceContributions[index].tasks[taskIndex].participantAuthorIDs =
                    replaced(cvConferenceContributions[index].tasks[taskIndex].participantAuthorIDs)
            }
        }

        var updatedMetadata = editableMetadataSnapshot
        var didChangeMetadata = false
        if var tasks = updatedMetadata.taskItems {
            for taskIndex in tasks.indices where tasks[taskIndex].participantAuthorIDs.contains(oldID) {
                tasks[taskIndex].participantAuthorIDs = replaced(tasks[taskIndex].participantAuthorIDs)
                didChangeMetadata = true
            }
            updatedMetadata.taskItems = tasks
        }
        if var tasks = updatedMetadata.teachingWorkspaceTasks {
            for taskIndex in tasks.indices where tasks[taskIndex].participantAuthorIDs.contains(oldID) {
                tasks[taskIndex].participantAuthorIDs = replaced(tasks[taskIndex].participantAuthorIDs)
                didChangeMetadata = true
            }
            updatedMetadata.teachingWorkspaceTasks = tasks
        }
        if var meetings = updatedMetadata.calendarMeetingRecords {
            for meetingIndex in meetings.indices where meetings[meetingIndex].participantAuthorIDs.contains(oldID) {
                meetings[meetingIndex].participantAuthorIDs = replaced(meetings[meetingIndex].participantAuthorIDs)
                didChangeMetadata = true
            }
            updatedMetadata.calendarMeetingRecords = meetings
        }
        if didChangeMetadata {
            metadata = updatedMetadata
        }
    }

    private func replaceOrganizationReferences(from duplicate: OrganizationRecord, to canonical: OrganizationRecord) {
        let names = Set([duplicate.nameSv, duplicate.nameEn].compactMap(\.trimmedOrNil))
        // "Alla kopplingar via id": a row that points to the duplicate moves
        // with it; the written name only counts for a row without a link, so
        // a row linked to some other organization is never moved by its text.
        func pointsToDuplicate(_ rowID: String?, _ rowName: String?) -> Bool {
            if let rowID = rowID?.trimmedOrNil {
                return rowID == duplicate.id
            }
            return names.contains(rowName ?? "")
        }
        for applicationIndex in applications.indices {
            if pointsToDuplicate(applications[applicationIndex].organizationID, applications[applicationIndex].organization) {
                applications[applicationIndex].organizationID = canonical.id
                applications[applicationIndex].organization = canonical.nameSv
            }
            if pointsToDuplicate(applications[applicationIndex].applicationManagerID, applications[applicationIndex].applicationManager) {
                applications[applicationIndex].applicationManagerID = canonical.id
                applications[applicationIndex].applicationManager = canonical.nameSv
            }
        }
        for courseIndex in teachingCourses.indices where pointsToDuplicate(teachingCourses[courseIndex].institutionID, teachingCourses[courseIndex].institution) {
            teachingCourses[courseIndex].institutionID = canonical.id
            teachingCourses[courseIndex].institution = canonical.nameSv
        }
        for componentIndex in teachingComponents.indices where pointsToDuplicate(teachingComponents[componentIndex].institutionID, teachingComponents[componentIndex].institution) {
            teachingComponents[componentIndex].institutionID = canonical.id
            teachingComponents[componentIndex].institution = canonical.nameSv
        }
        for reviewIndex in cvReviewEntries.indices where cvReviewEntries[reviewIndex].organizationID == duplicate.id {
            cvReviewEntries[reviewIndex].organizationID = canonical.id
        }
        for projectIndex in projects.indices {
            for principalIndex in projects[projectIndex].principalOrganizations.indices
            where projects[projectIndex].principalOrganizations[principalIndex].organizationID == duplicate.id {
                projects[projectIndex].principalOrganizations[principalIndex].organizationID = canonical.id
            }
        }
        for candidateIndex in doctoralCandidates.indices where pointsToDuplicate(doctoralCandidates[candidateIndex].institutionID, doctoralCandidates[candidateIndex].institution) {
            doctoralCandidates[candidateIndex].institutionID = canonical.id
            doctoralCandidates[candidateIndex].institution = canonical.nameSv
            doctoralCandidates[candidateIndex].normalize()
        }
        for authorIndex in publicationAuthors.indices {
            // F21: rows that point to the duplicate by id point to the kept organization.
            for affiliationIndex in publicationAuthors[authorIndex].affiliations.indices where publicationAuthors[authorIndex].affiliations[affiliationIndex].organizationID == duplicate.id {
                publicationAuthors[authorIndex].affiliations[affiliationIndex].organizationID = canonical.id
            }
            for employmentIndex in publicationAuthors[authorIndex].employments.indices where publicationAuthors[authorIndex].employments[employmentIndex].organizationID == duplicate.id {
                publicationAuthors[authorIndex].employments[employmentIndex].organizationID = canonical.id
            }
            for educationIndex in publicationAuthors[authorIndex].educationEntries.indices where publicationAuthors[authorIndex].educationEntries[educationIndex].organizationID == duplicate.id {
                publicationAuthors[authorIndex].educationEntries[educationIndex].organizationID = canonical.id
            }
            for affiliationIndex in publicationAuthors[authorIndex].affiliations.indices
            where pointsToDuplicate(publicationAuthors[authorIndex].affiliations[affiliationIndex].organizationID, publicationAuthors[authorIndex].affiliations[affiliationIndex].organization)
                || (publicationAuthors[authorIndex].affiliations[affiliationIndex].organizationID == canonical.id
                    && names.contains(publicationAuthors[authorIndex].affiliations[affiliationIndex].organization)) {
                publicationAuthors[authorIndex].affiliations[affiliationIndex].organization = canonical.nameSv
            }
            for employmentIndex in publicationAuthors[authorIndex].employments.indices
            where pointsToDuplicate(publicationAuthors[authorIndex].employments[employmentIndex].organizationID, publicationAuthors[authorIndex].employments[employmentIndex].organization)
                || (publicationAuthors[authorIndex].employments[employmentIndex].organizationID == canonical.id
                    && names.contains(publicationAuthors[authorIndex].employments[employmentIndex].organization)) {
                publicationAuthors[authorIndex].employments[employmentIndex].organization = canonical.nameSv
            }
            for educationIndex in publicationAuthors[authorIndex].educationEntries.indices
            where pointsToDuplicate(publicationAuthors[authorIndex].educationEntries[educationIndex].organizationID, publicationAuthors[authorIndex].educationEntries[educationIndex].organization)
                || (publicationAuthors[authorIndex].educationEntries[educationIndex].organizationID == canonical.id
                    && names.contains(publicationAuthors[authorIndex].educationEntries[educationIndex].organization)) {
                publicationAuthors[authorIndex].educationEntries[educationIndex].organization = canonical.nameSv
            }
            publicationAuthors[authorIndex].normalize()
        }
        for contributionIndex in cvConferenceContributions.indices where cvConferenceContributions[contributionIndex].congressOrganizationID == duplicate.id {
            cvConferenceContributions[contributionIndex].congressOrganizationID = canonical.id
            if let congressID = cvConferenceContributions[contributionIndex].congressID,
               !canonical.congresses.contains(where: { $0.id == congressID }) {
                cvConferenceContributions[contributionIndex].congressID = nil
                cvConferenceContributions[contributionIndex].congressLink = ""
            }
            cvConferenceContributions[contributionIndex] = canonicalizedConferenceContribution(cvConferenceContributions[contributionIndex])
        }
        replaceMetadataOrganizationReferences(from: duplicate.id, to: canonical.id)
    }

    private func replaceProjectReferences(from duplicate: ProjectRecord, to canonical: ProjectRecord) {
        let names = Set([duplicate.nameSv, duplicate.nameEn].compactMap(\.trimmedOrNil))
        // "Alla kopplingar via id": a row that points to the duplicate moves
        // with it; the written name only counts for a row without a link.
        func pointsToDuplicate(_ rowID: String?, _ rowName: String?) -> Bool {
            if let rowID = rowID?.trimmedOrNil {
                return rowID == duplicate.id
            }
            return names.contains(rowName ?? "")
        }
        for applicationIndex in applications.indices where pointsToDuplicate(applications[applicationIndex].projectID, applications[applicationIndex].projectType) {
            applications[applicationIndex].projectID = canonical.id
            applications[applicationIndex].projectType = canonical.nameSv
        }
        for publicationIndex in publicationRecords.indices where pointsToDuplicate(publicationRecords[publicationIndex].projectID, publicationRecords[publicationIndex].projectName) {
            publicationRecords[publicationIndex].projectID = canonical.id
            publicationRecords[publicationIndex].projectName = canonical.nameSv
            publicationRecords[publicationIndex].normalize()
        }
        for candidateIndex in doctoralCandidates.indices {
            if doctoralCandidates[candidateIndex].linkedProjectID == duplicate.id ||
                names.contains(doctoralCandidates[candidateIndex].doctoralProjectName) {
                doctoralCandidates[candidateIndex].linkedProjectID = canonical.id
                if names.contains(doctoralCandidates[candidateIndex].doctoralProjectName) {
                    doctoralCandidates[candidateIndex].doctoralProjectName = canonical.nameSv
                }
                doctoralCandidates[candidateIndex].normalize()
            }
        }
        for contributionIndex in cvConferenceContributions.indices {
            let contribution = cvConferenceContributions[contributionIndex]
            let movesWithDuplicate = contribution.projectID?.trimmedOrNil.map { $0 == duplicate.id }
                ?? (names.contains(contribution.projectNameSv) || names.contains(contribution.projectNameEn))
            if movesWithDuplicate {
                cvConferenceContributions[contributionIndex].projectID = canonical.id
                cvConferenceContributions[contributionIndex].projectNameSv = canonical.nameSv
                cvConferenceContributions[contributionIndex].projectNameEn = canonical.nameEn.nonEmpty ?? canonical.nameSv
            }
            cvConferenceContributions[contributionIndex] = canonicalizedConferenceContribution(cvConferenceContributions[contributionIndex])
        }
        for appearanceIndex in cvMediaAppearances.indices {
            cvMediaAppearances[appearanceIndex].projectIDs = cvMediaAppearances[appearanceIndex].projectIDs.map {
                $0 == duplicate.id ? canonical.id : $0
            }
            cvMediaAppearances[appearanceIndex].normalize()
        }
        replaceTaskProjectReferences(from: duplicate.id, to: canonical.id)
        replaceMetadataProjectReferences(from: duplicate.id, to: canonical.id)
    }

    private func replacePublicationReferences(from duplicateID: String, to canonicalID: String) {
        for candidateIndex in doctoralCandidates.indices {
            let replaced = doctoralCandidates[candidateIndex].linkedPublicationIDs.map {
                $0 == duplicateID ? canonicalID : $0
            }
            doctoralCandidates[candidateIndex].linkedPublicationIDs = uniquedNonEmptyStrings(replaced)
            doctoralCandidates[candidateIndex].normalize()
        }
        for appearanceIndex in cvMediaAppearances.indices {
            cvMediaAppearances[appearanceIndex].publicationIDs = cvMediaAppearances[appearanceIndex].publicationIDs.map {
                $0 == duplicateID ? canonicalID : $0
            }
            cvMediaAppearances[appearanceIndex].normalize()
        }
        replaceTaskPublicationReferences(from: duplicateID, to: canonicalID)
        replaceMetadataPublicationReferences(from: duplicateID, to: canonicalID)
    }

    private func replaceTaskParticipantReferences(from oldVariants: Set<String>, to newName: String) {
        for organizationIndex in organizations.indices {
            replaceTaskParticipantNames(&organizations[organizationIndex].projectTasks, from: oldVariants, to: newName)
        }
        for projectIndex in projects.indices {
            replaceTaskParticipantNames(&projects[projectIndex].projectTasks, from: oldVariants, to: newName)
        }
        for publicationIndex in publicationRecords.indices {
            replaceTaskParticipantNames(&publicationRecords[publicationIndex].publicationTasks, from: oldVariants, to: newName)
        }
        for contributionIndex in cvConferenceContributions.indices {
            replaceTaskParticipantNames(&cvConferenceContributions[contributionIndex].tasks, from: oldVariants, to: newName)
        }
        var updatedMetadata = editableMetadataSnapshot
        if var tasks = updatedMetadata.teachingWorkspaceTasks {
            replaceTaskParticipantNames(&tasks, from: oldVariants, to: newName)
            updatedMetadata.teachingWorkspaceTasks = tasks
            metadata = updatedMetadata
        }
    }

    private func replaceTaskParticipantNames(_ tasks: inout [PublicationTaskItem], from oldVariants: Set<String>, to newName: String) {
        for taskIndex in tasks.indices {
            tasks[taskIndex].participantNames = uniquedNonEmptyStrings(tasks[taskIndex].participantNames.map {
                oldVariants.contains($0) ? newName : $0
            })
            tasks[taskIndex].normalize()
        }
    }

    private func replaceTaskParticipantNames(_ tasks: inout [ProjectTaskItem], from oldVariants: Set<String>, to newName: String) {
        for taskIndex in tasks.indices {
            tasks[taskIndex].participantNames = uniquedNonEmptyStrings(tasks[taskIndex].participantNames.map {
                oldVariants.contains($0) ? newName : $0
            })
            tasks[taskIndex].normalize()
        }
    }

    private func replaceTaskProjectReferences(from duplicateID: String, to canonicalID: String) {
        for publicationIndex in publicationRecords.indices {
            replaceTaskProjectReferences(&publicationRecords[publicationIndex].publicationTasks, from: duplicateID, to: canonicalID)
        }
        for contributionIndex in cvConferenceContributions.indices {
            replaceTaskProjectReferences(&cvConferenceContributions[contributionIndex].tasks, from: duplicateID, to: canonicalID)
        }
    }

    private func replaceTaskProjectReferences(_ tasks: inout [PublicationTaskItem], from duplicateID: String, to canonicalID: String) {
        for taskIndex in tasks.indices where tasks[taskIndex].projectID == duplicateID {
            tasks[taskIndex].projectID = canonicalID
            tasks[taskIndex].normalize()
        }
    }

    private func replaceTaskPublicationReferences(from duplicateID: String, to canonicalID: String) {
        for organizationIndex in organizations.indices {
            replaceTaskPublicationReferences(&organizations[organizationIndex].projectTasks, from: duplicateID, to: canonicalID)
        }
        for projectIndex in projects.indices {
            replaceTaskPublicationReferences(&projects[projectIndex].projectTasks, from: duplicateID, to: canonicalID)
        }
        for publicationIndex in publicationRecords.indices {
            replaceTaskPublicationReferences(&publicationRecords[publicationIndex].publicationTasks, from: duplicateID, to: canonicalID)
        }
        for contributionIndex in cvConferenceContributions.indices {
            replaceTaskPublicationReferences(&cvConferenceContributions[contributionIndex].tasks, from: duplicateID, to: canonicalID)
        }
    }

    private func replaceTaskPublicationReferences(_ tasks: inout [PublicationTaskItem], from duplicateID: String, to canonicalID: String) {
        for taskIndex in tasks.indices where tasks[taskIndex].publicationID == duplicateID {
            tasks[taskIndex].publicationID = canonicalID
            tasks[taskIndex].normalize()
        }
    }

    private func replaceTaskPublicationReferences(_ tasks: inout [ProjectTaskItem], from duplicateID: String, to canonicalID: String) {
        for taskIndex in tasks.indices where tasks[taskIndex].publicationID == duplicateID {
            tasks[taskIndex].publicationID = canonicalID
            tasks[taskIndex].normalize()
        }
    }

    /// Round 11: other organizations' settings that name the duplicate (a
    /// funder's "Prioriterad förvaltare" and its OH exceptions per fund
    /// manager) name the organization that is kept.
    private func replaceOrganizationSettingReferences(from duplicateID: String, to canonicalID: String) {
        for index in organizations.indices {
            if organizations[index].preferredFundManagerID == duplicateID {
                organizations[index].preferredFundManagerID = canonicalID
            }
            if let exceptions = organizations[index].overheadRuleExceptions,
               exceptions.contains(where: { $0.managerOrganizationID == duplicateID }) {
                // One exception per fund manager: one already set for the
                // kept organization wins over the duplicate's.
                let own = exceptions.filter { $0.managerOrganizationID != duplicateID }
                let hasOwn = own.contains { $0.managerOrganizationID == canonicalID }
                let moved = hasOwn ? [] : exceptions
                    .filter { $0.managerOrganizationID == duplicateID }
                    .prefix(1)
                    .map { exception -> FunderOverheadRuleException in
                        var exception = exception
                        exception.managerOrganizationID = canonicalID
                        return exception
                    }
                organizations[index].overheadRuleExceptions = own + moved
            }
        }
    }

    /// Round 11: a central task's links to the duplicate (and to congresses
    /// under it) point to the record that is kept.
    private func replaceCentralTaskLinks(
        in metadata: inout DataSourceMetadata,
        kind: TaskLinkKind,
        from duplicateID: String,
        to canonicalID: String,
        includingOwner: Bool = false
    ) {
        guard var tasks = metadata.taskItems else { return }
        for taskIndex in tasks.indices {
            var links = tasks[taskIndex].links
            var changed = false
            for linkIndex in links.indices {
                if links[linkIndex].kind == kind, links[linkIndex].targetID == duplicateID {
                    links[linkIndex].targetID = canonicalID
                    changed = true
                }
                if includingOwner, links[linkIndex].ownerID == duplicateID {
                    links[linkIndex].ownerID = canonicalID
                    changed = true
                }
            }
            guard changed else { continue }
            var seen = Set<String>()
            tasks[taskIndex].links = links.filter { seen.insert($0.id).inserted }
        }
        metadata.taskItems = tasks
    }

    private func replaceMetadataOrganizationReferences(from duplicateID: String, to canonicalID: String) {
        var updatedMetadata = editableMetadataSnapshot
        // Round 11: travel and stays linked to the duplicate's congresses,
        // central tasks and the remembered selection follow as well.
        if var travel = updatedMetadata.calendarTravelRecords {
            for index in travel.indices where travel[index].congressOrganizationID == duplicateID {
                travel[index].congressOrganizationID = canonicalID
            }
            updatedMetadata.calendarTravelRecords = travel
        }
        if var stays = updatedMetadata.calendarAccommodationRecords {
            for index in stays.indices where stays[index].congressOrganizationID == duplicateID {
                stays[index].congressOrganizationID = canonicalID
            }
            updatedMetadata.calendarAccommodationRecords = stays
        }
        replaceCentralTaskLinks(in: &updatedMetadata, kind: .organization, from: duplicateID, to: canonicalID, includingOwner: true)
        if updatedMetadata.lastSelectedOrganizationID == duplicateID {
            updatedMetadata.lastSelectedOrganizationID = canonicalID
        }
        if updatedMetadata.lastSelectedManagerID == duplicateID {
            updatedMetadata.lastSelectedManagerID = canonicalID
        }
        if var meetings = updatedMetadata.calendarMeetingRecords {
            for meetingIndex in meetings.indices {
                meetings[meetingIndex].organizationIDs = uniquedNonEmptyStrings(meetings[meetingIndex].organizationIDs.map {
                    $0 == duplicateID ? canonicalID : $0
                })
                if meetings[meetingIndex].organizationID == duplicateID {
                    meetings[meetingIndex].organizationID = canonicalID
                }
                meetings[meetingIndex].normalize()
            }
            updatedMetadata.calendarMeetingRecords = meetings
        }
        metadata = updatedMetadata
    }

    private func replaceMetadataProjectReferences(from duplicateID: String, to canonicalID: String) {
        var updatedMetadata = editableMetadataSnapshot
        replaceCentralTaskLinks(in: &updatedMetadata, kind: .project, from: duplicateID, to: canonicalID)
        if var tasks = updatedMetadata.teachingWorkspaceTasks {
            replaceTaskProjectReferences(&tasks, from: duplicateID, to: canonicalID)
            updatedMetadata.teachingWorkspaceTasks = tasks
        }
        if var meetings = updatedMetadata.calendarMeetingRecords {
            for meetingIndex in meetings.indices {
                let projectIDs = meetings[meetingIndex].projectIDs.map {
                    $0 == duplicateID ? canonicalID : $0
                }
                meetings[meetingIndex].projectIDs = uniquedNonEmptyStrings(projectIDs)
                if meetings[meetingIndex].projectID == duplicateID {
                    meetings[meetingIndex].projectID = canonicalID
                }
                meetings[meetingIndex].normalize()
            }
            updatedMetadata.calendarMeetingRecords = meetings
        }
        metadata = updatedMetadata
    }

    private func replaceMetadataPublicationReferences(from duplicateID: String, to canonicalID: String) {
        var updatedMetadata = editableMetadataSnapshot
        replaceCentralTaskLinks(in: &updatedMetadata, kind: .publication, from: duplicateID, to: canonicalID)
        if var tasks = updatedMetadata.teachingWorkspaceTasks {
            replaceTaskPublicationReferences(&tasks, from: duplicateID, to: canonicalID)
            updatedMetadata.teachingWorkspaceTasks = tasks
        }
        if var meetings = updatedMetadata.calendarMeetingRecords {
            for meetingIndex in meetings.indices {
                meetings[meetingIndex].publicationIDs = uniquedNonEmptyStrings(meetings[meetingIndex].publicationIDs.map {
                    $0 == duplicateID ? canonicalID : $0
                })
                meetings[meetingIndex].normalize()
            }
            updatedMetadata.calendarMeetingRecords = meetings
        }
        metadata = updatedMetadata
    }

    private func uniquedNonEmptyStrings(_ values: [String]) -> [String] {
        let compact = values.compactMap(\.trimmedOrNil)
        return Array(NSOrderedSet(array: compact)) as? [String] ?? compact
    }

    private func duplicateMergeError(_ message: String) -> NSError {
        NSError(
            domain: "FootprintDuplicateMerge",
            code: 1,
            userInfo: [NSLocalizedDescriptionKey: message]
        )
    }

