    func dataQualityIssueCount() -> Int {
        if let cachedDataQualityIssueCount {
            return cachedDataQualityIssueCount
        }
        let count = duplicateIssues().count + integrityIssues().count
        cachedDataQualityIssueCount = count
        lastKnownDataQualityIssueCount = count
        return count
    }

    func cachedDataQualityIssueCountForNavigation() -> Int {
        if let cachedDataQualityIssueCount {
            return cachedDataQualityIssueCount
        }
        if let cachedDuplicateIssues, let cachedIntegrityIssues {
            let count =
                visibleDataQualityWarnings(cachedDuplicateIssues).count
                + visibleDataQualityWarnings(cachedIntegrityIssues).count
            lastKnownDataQualityIssueCount = count
            return count
        }
        return lastKnownDataQualityIssueCount
    }

