        items.append(
            DataQualitySummaryItem(
                title: language.text("Archived records", "Arkiverade poster"),
                count: archivedRecordSummaries().count
            )
        )

        return items
    }

    struct SQLiteDiagnosticsPrefetch {
        let health: SQLiteStorageHealthSummary?
        let runtimeSettings: SQLiteRuntimeSettingsSummary?
        let queryPlans: [SQLiteQueryPlanObservation]
        let integrity: RelationalSQLiteIntegritySummary?
        let tableCounts: [String: Int]
        let indexCount: Int
        let containsAppSettings: Bool
        let containsCongresses: Bool
        let containsRelationalCore: Bool
    }

    /// The expensive SQLite probes behind the data-quality "structure" view
    /// (among them integrity_check/quick_check PRAGMAs that walk the whole
    /// database file) computed on a fresh read connection so they can run off
    /// the main thread. dataStructureDiagnostics() consumes the result.
    nonisolated static func prefetchSQLiteDiagnostics() -> SQLiteDiagnosticsPrefetch {
        let probeStore = FileManager.default.fileExists(atPath: databaseURL.path)
            ? try? SQLiteDocumentStore(url: databaseURL)
            : nil
        return SQLiteDiagnosticsPrefetch(
            health: probeStore.flatMap { try? $0.storageHealthSummary() },
            runtimeSettings: probeStore.flatMap { try? $0.runtimeSettingsSummary() },
            queryPlans: probeStore.flatMap { try? $0.relationalQueryPlanObservations() } ?? [],
            integrity: probeStore.flatMap { try? $0.relationalIntegritySummary() },
            tableCounts: probeStore.flatMap { try? $0.relationalTableCounts() } ?? [:],
            indexCount: probeStore.flatMap { try? $0.relationalIndexCount() } ?? 0,
            containsAppSettings: probeStore.flatMap { try? $0.containsDocument(named: "app_settings") } ?? false,
            containsCongresses: probeStore.flatMap { try? $0.containsDocument(named: "congresses") } ?? false,
            containsRelationalCore: probeStore.flatMap { try? $0.containsDocument(named: "relational_core") } ?? false
        )
    }

    func refreshSQLiteDiagnosticsPrefetch() async {
        let prefetch = await Task.detached(priority: .userInitiated) {
            Self.prefetchSQLiteDiagnostics()
        }.value
        prefetchedSQLiteDiagnostics = prefetch
    }

    func dataStructureDiagnostics() -> [DataStructureDiagnosticItem] {
        if let cachedDataStructureDiagnostics, !hasPendingMetadataPersistence {
            return cachedDataStructureDiagnostics
        }
        let startedAt = CFAbsoluteTimeGetCurrent()
        var shouldCacheResult = !hasPendingMetadataPersistence
        let metrics = relationshipMetrics()
        let firstClassCongressCount = Self.storedCongressRecords(from: organizations).count
        // Prefetched off the main thread by the data-quality workspace and the
        // cache prewarm; the live-connection fallback keeps direct callers
        // (tests, first paint before any prefetch) working unchanged.
        let prefetch = prefetchedSQLiteDiagnostics
        let appSettingsExists = prefetch?.containsAppSettings
            ?? ((try? sqliteStore?.containsDocument(named: "app_settings")) ?? false)
        let congressDocumentExists = prefetch?.containsCongresses
            ?? ((try? sqliteStore?.containsDocument(named: "congresses")) ?? false)
        let relationalDocumentExists = prefetch?.containsRelationalCore
            ?? ((try? sqliteStore?.containsDocument(named: "relational_core")) ?? false)
        let relationalSQLiteCounts = prefetch?.tableCounts
            ?? ((try? sqliteStore?.relationalTableCounts()) ?? [:])
        let populatedRelationalSQLiteTableCount = relationalSQLiteCounts.filter { $0.value > 0 }.count
        let relationalSQLiteIndexCount = prefetch?.indexCount
            ?? ((try? sqliteStore?.relationalIndexCount()) ?? 0)
        let sqliteStorageHealth = prefetch?.health ?? (try? sqliteStore?.storageHealthSummary())
        let sqliteRuntimeSettings = prefetch?.runtimeSettings ?? (try? sqliteStore?.runtimeSettingsSummary())
        let sqliteQueryPlans = prefetch?.queryPlans
            ?? ((try? sqliteStore?.relationalQueryPlanObservations()) ?? [])
        let sqliteQueryPlanFullScanCount = sqliteQueryPlans.filter(\.usesFullTableScan).count
        let relationalSQLiteIntegrity = prefetch?.integrity
            ?? (try? sqliteStore?.relationalIntegritySummary())
            ?? RelationalSQLiteIntegritySummary(checkedReferenceCount: 0, brokenReferenceCount: 0, duplicateIdentityCount: 0)
        let modernIDCount = modernFirstClassIDCount()
        let legacyIDCount = legacyFirstClassIDCount()
        let sqliteApplicationProbe = cachedSQLitePrimaryApplicationProbe()
        let sqliteProjectProbe = cachedSQLitePrimaryProjectProbe()
        let sqlitePublicationAuthorProbe = cachedSQLitePrimaryPublicationAuthorProbe()
        let sqlitePublicationProbe = cachedSQLitePrimaryPublicationProbe()
        let sqliteCoreRegistersIsPrimary = sqliteApplicationProbe.isPrimary
            && sqliteProjectProbe.isPrimary
            && sqlitePublicationAuthorProbe.isPrimary
            && sqlitePublicationProbe.isPrimary
        let sqliteCoreRegistersTone: DataStructureDiagnosticItem.Tone = sqliteCoreRegistersIsPrimary
            ? .ok
            : (hasPendingMetadataPersistence ? .warning : .critical)
        let sqliteCoreRegistersValue = sqliteCoreRegistersIsPrimary
            ? language.text("Active", "Aktiv")
            : (hasPendingMetadataPersistence ? language.text("Syncing", "Synkar") : language.text("Unavailable", "Otillgänglig"))
        let sqliteCongressProbe = cachedSQLitePrimaryCongressProbe()
        let sqliteCongressTone: DataStructureDiagnosticItem.Tone = sqliteCongressProbe.isPrimary
            ? .ok
            : (hasPendingMetadataPersistence ? .warning : .critical)
        let sqliteCongressValue = sqliteCongressProbe.isPrimary
            ? language.text("Active", "Aktiv")
            : (hasPendingMetadataPersistence ? language.text("Syncing", "Synkar") : language.text("Unavailable", "Otillgänglig"))
        let sqliteTravelProbe = cachedSQLitePrimaryCalendarTravelProbe()
        let sqliteAccommodationProbe = cachedSQLitePrimaryCalendarAccommodationProbe()
        let sqliteCalendarPlanningIsPrimary = sqliteTravelProbe.isPrimary && sqliteAccommodationProbe.isPrimary
        let sqliteCalendarPlanningTone: DataStructureDiagnosticItem.Tone = sqliteCalendarPlanningIsPrimary
            ? .ok
            : (hasPendingMetadataPersistence ? .warning : .critical)
        let sqliteCalendarPlanningValue = sqliteCalendarPlanningIsPrimary
            ? language.text("Active", "Aktiv")
            : (hasPendingMetadataPersistence ? language.text("Syncing", "Synkar") : language.text("Unavailable", "Otillgänglig"))
        let storageReadiness = Self.storageReadinessSnapshot()
        let activeStorageUsesSQLite = sqliteStore != nil
        let startupStorageReady = activeStorageUsesSQLite && storageReadiness.isSQLiteComplete
        let startupStorageMissingValue = storageReadiness.missingRequiredSQLiteDocuments.isEmpty
            ? language.text("None", "Inga")
            : storageReadiness.missingRequiredSQLiteDocuments.prefix(4).joined(separator: ", ")
                + (storageReadiness.missingRequiredSQLiteDocuments.count > 4 ? " ..." : "")
        let startupStorageDetails = [
            DataStructureDiagnosticItem.Detail(
                id: "sqlite-documents",
                title: language.text("SQLite documents", "SQLite-dokument"),
                value: "\(storageReadiness.sqliteDocumentCount)"
            ),
            DataStructureDiagnosticItem.Detail(
                id: "missing-required",
                title: language.text("Missing required", "Saknas kravdokument"),
                value: startupStorageMissingValue
            ),
            DataStructureDiagnosticItem.Detail(
                id: "startup-marker",
                title: language.text("Startup marker", "Startmarkör"),
                value: storageReadiness.hasCurrentStartupMaintenanceMarker ? language.text("Current", "Aktuell") : language.text("Pending", "Väntar")
            ),
            DataStructureDiagnosticItem.Detail(
                id: "backups",
                title: language.text("Backups", "Backuper"),
                value: "\(storageReadiness.backupCount)"
            ),
        ]
        let activeStorageDetails = [
            DataStructureDiagnosticItem.Detail(
                id: "database",
                title: language.text("Database", "Databas"),
                value: Self.configuredDatabaseFileName
            ),
        ]
        let backupCount = (try? backupSnapshots().count) ?? 0
        let sqliteStorageIsHealthy = sqliteStorageHealth?.integrityCheck.isPassed == true
            && sqliteStorageHealth?.quickCheck.isPassed == true
            && sqliteStorageHealth?.foreignKeyCheck.isPassed == true
        let sqliteStorageHasConfirmedFailure = sqliteStorageHealth.map {
            $0.integrityCheck.isConfirmedFailure
                || $0.quickCheck.isConfirmedFailure
                || $0.foreignKeyCheck.isConfirmedFailure
        } ?? false
        if sqliteStorageHealth == nil
            || sqliteStorageHealth?.integrityCheck.isUnavailable == true
            || sqliteStorageHealth?.quickCheck.isUnavailable == true
            || sqliteStorageHealth?.foreignKeyCheck.isUnavailable == true {
            shouldCacheResult = false
        }
        let databaseLockReady = activeStorageUsesSQLite
            && startupStorageReady
            && legacyIDCount == 0
            && relationalSQLiteIndexCount > 0
            && relationalSQLiteIntegrity.checkedReferenceCount > 0
            && relationalSQLiteIntegrity.brokenReferenceCount == 0
            && relationalSQLiteIntegrity.duplicateIdentityCount == 0
            && sqliteStorageIsHealthy
            && (sqliteStorageHealth?.searchIndexCount ?? 0) > 0
            && sqliteCoreRegistersIsPrimary
            && sqliteCongressProbe.isPrimary
            && sqliteCalendarPlanningIsPrimary
        let yes = language.text("Yes", "Ja")
        let no = language.text("No", "Nej")
        func yesNo(_ condition: Bool) -> String { condition ? yes : no }
        let databaseLockDetails = [
            DataStructureDiagnosticItem.Detail(
                id: "contract",
                title: language.text("Contract", "Kontrakt"),
                value: FootprintStorageContract.version
            ),
            DataStructureDiagnosticItem.Detail(
                id: "canonical-store",
                title: language.text("Canonical store", "Kanonisk lagring"),
                value: FootprintStorageContract.canonicalStore
            ),
            DataStructureDiagnosticItem.Detail(
                id: "sqlite-only",
                title: language.text("SQLite only", "Endast SQLite"),
                value: yesNo(activeStorageUsesSQLite && startupStorageReady)
            ),
            DataStructureDiagnosticItem.Detail(
                id: "uuid-ids",
                title: language.text("UUID IDs", "UUID-ID:n"),
                value: yesNo(legacyIDCount == 0)
            ),
            DataStructureDiagnosticItem.Detail(
                id: "relational-indexes",
                title: language.text("Relational indexes", "Relationsindex"),
                value: yesNo(
                    relationalSQLiteIndexCount > 0
                        && relationalSQLiteIntegrity.checkedReferenceCount > 0
                        && relationalSQLiteIntegrity.brokenReferenceCount == 0
                        && relationalSQLiteIntegrity.duplicateIdentityCount == 0
                )
            ),
            DataStructureDiagnosticItem.Detail(
                id: "sqlite-health",
                title: language.text("SQLite health", "SQLite-hälsa"),
                value: sqliteStorageIsHealthy
                    ? yes
                    : (sqliteStorageHasConfirmedFailure
                        ? no
                        : language.text("Unavailable", "Otillgänglig"))
            ),
            DataStructureDiagnosticItem.Detail(
                id: "search-index",
                title: language.text("Search index", "Sökindex"),
                value: "\(sqliteStorageHealth?.searchIndexCount ?? 0)"
            ),
            DataStructureDiagnosticItem.Detail(
                id: "query-plans",
                title: language.text("Query plans", "Frågeplaner"),
                value: sqliteQueryPlans.isEmpty
                    ? language.text("Pending", "Väntar")
                    : "\(sqliteQueryPlans.count - sqliteQueryPlanFullScanCount)/\(sqliteQueryPlans.count)"
            ),
            DataStructureDiagnosticItem.Detail(
                id: "backup-restore",
                title: language.text("Backup/restore", "Backup/återställning"),
                value: FootprintStorageContract.backupFormat
            ),
        ]

        func item(
            _ id: String,
            _ title: String,
            _ value: String,
            _ detail: String,
            _ tone: DataStructureDiagnosticItem.Tone,
            details: [DataStructureDiagnosticItem.Detail] = []
        ) -> DataStructureDiagnosticItem {
            DataStructureDiagnosticItem(id: id, title: title, value: value, detail: detail, tone: tone, details: details)
        }

        let relationalSQLiteDetails = relationalSQLiteCounts
            .sorted { $0.key.localizedStandardCompare($1.key) == .orderedAscending }
            .map {
                DataStructureDiagnosticItem.Detail(
                    id: $0.key,
                    title: $0.key.replacingOccurrences(of: "rel_", with: ""),
                    value: "\($0.value)"
                )
            }
        let relationalSQLiteIndexDetails = [
            DataStructureDiagnosticItem.Detail(
                id: "reference-checks",
                title: language.text("Reference checks", "Referenskontroller"),
                value: "\(relationalSQLiteIntegrity.checkedReferenceCount)"
            ),
            DataStructureDiagnosticItem.Detail(
                id: "broken-references",
                title: language.text("Broken links", "Trasiga länkar"),
                value: "\(relationalSQLiteIntegrity.brokenReferenceCount)"
            ),
            DataStructureDiagnosticItem.Detail(
                id: "duplicate-identities",
                title: language.text("Duplicate identities", "Dubbla identiteter"),
                value: "\(relationalSQLiteIntegrity.duplicateIdentityCount)"
            ),
            DataStructureDiagnosticItem.Detail(
