        func sqliteHealthValue(_ outcome: SQLiteHealthCheckOutcome?) -> String {
            guard let outcome else { return language.text("Unknown", "Okänt") }
            switch outcome {
            case .passed:
                return yes
            case .failed:
                return no
            case let .unavailable(message):
                return language.text("Unavailable", "Otillgänglig") + ": " + message
            }
        }
        let sqliteStorageHealthDetails = [
            DataStructureDiagnosticItem.Detail(
                id: "checked-at",
                title: language.text("Checked", "Kontrollerad"),
                value: sqliteStorageHealth.map { ISO8601DateFormatter().string(from: $0.checkedAt) }
                    ?? language.text("Unknown", "Okänt")
            ),
            DataStructureDiagnosticItem.Detail(
                id: "integrity-check",
                title: "integrity_check",
                value: sqliteHealthValue(sqliteStorageHealth?.integrityCheck)
            ),
            DataStructureDiagnosticItem.Detail(
                id: "quick-check",
                title: "quick_check",
                value: sqliteHealthValue(sqliteStorageHealth?.quickCheck)
            ),
            DataStructureDiagnosticItem.Detail(
                id: "foreign-key-check",
                title: "foreign_key_check",
                value: sqliteStorageHealth.map { health in
                    switch health.foreignKeyCheck {
                    case .passed:
                        return "0"
                    case let .failed(violations):
                        return "\(violations.count)"
                    case let .unavailable(message):
                        return language.text("Unavailable", "Otillgänglig") + ": " + message
                    }
                } ?? language.text("Unknown", "Okänt")
            ),
            DataStructureDiagnosticItem.Detail(
                id: "used-bytes",
