    /// A finished write changes the database file, not the records: the
    /// change itself already bumped dataQualityCacheGeneration when the
    /// records were set. Bumping it again here made the Data view reload
    /// every list a second time about half a second after each save, which
    /// is what made editing in the Data view slow. The storage figures are
    /// still recomputed the next time they are read.
    private func invalidateStorageStructureDiagnosticsAfterWrite() {
        cachedDataStructureDiagnostics = nil
        prefetchedSQLiteDiagnostics = nil
        invalidateSQLitePrimaryReadCaches()
    }

    func scheduleDataQualityCachePrewarm(reason: String, delay: TimeInterval = 8.0) {
        dataQualityPrewarmTask?.cancel()
        let generation = dataQualityCacheGeneration
        dataQualityPrewarmTask = Task { [weak self] in
            try? await Task.sleep(nanoseconds: UInt64(max(delay, 0) * 1_000_000_000))
            guard !Task.isCancelled else { return }
            await MainActor.run {
                guard let self, generation == self.dataQualityCacheGeneration else { return }
                self.appendPerformanceDiagnostic("data-quality-prewarm-start reason=\(reason)")
            }
            let phases: [(String, @MainActor (GrantDataStore) -> Int)] = [
                ("missingFields", { $0.missingFieldIssues(includeHidden: true).count }),
                ("duplicates", { $0.duplicateIssues(includeHidden: true).count }),
                ("integrity", { $0.integrityIssues(includeHidden: true).count }),
                ("structure", { $0.dataStructureDiagnostics().count }),
                ("archive", { $0.archivedRecordSummaries().count }),
            ]
            for (phase, work) in phases {
                try? await Task.sleep(nanoseconds: 120_000_000)
                guard !Task.isCancelled else { return }
                if phase == "structure" {
                    // The PRAGMA-heavy SQLite probes run on a detached task;
                    // only the item assembly below touches the main actor.
                    await self?.refreshSQLiteDiagnosticsPrefetch()
                    guard !Task.isCancelled else { return }
                }
                await MainActor.run {
                    guard let self, generation == self.dataQualityCacheGeneration else { return }
                    let startedAt = self.beginMainThreadActivity("data-quality-prewarm-\(phase)")
                    let count = work(self)
                    self.endMainThreadActivity("data-quality-prewarm-\(phase)", startedAt: startedAt)
                    self.appendPerformanceDiagnosticIfSlow(
                        { duration in
                            String(
                                format: "data-quality-prewarm phase=%@ count=%ld total_ms=%.2f",
                                phase,
                                count,
                                duration
                            )
                        },
                        startedAt: startedAt,
                        thresholdMs: 40
                    )
                }
            }
            await MainActor.run {
                guard let self, generation == self.dataQualityCacheGeneration else { return }
                self.dataQualityPrewarmTask = nil
                self.appendPerformanceDiagnostic("data-quality-prewarm-finished reason=\(reason)")
            }
        }
    }

    /// Gives visible navigation and selection work precedence over optional
    /// cache warming. Pending work is not discarded; it is rescheduled after a
    /// short quiet period and remains generation-checked.
    func prioritizeUserInteraction() {
        if deferredFullPublicationIndexWorkItem != nil {
            scheduleDeferredFullPublicationIndexRefresh(
                reason: "interaction-quiet-period",
                delay: 3.0
            )
        }
        if pendingPublicationIndexRefreshRequest != nil {
            pendingPublicationIndexRefreshWorkItem?.cancel()
            schedulePendingPublicationIndexRefresh(after: 2.0)
        }
        if dataQualityPrewarmTask != nil {
            scheduleDataQualityCachePrewarm(
                reason: "interaction-quiet-period",
                delay: 8.0
            )
        }
    }

    private func invalidateDataQualityCaches() {
        dataQualityPrewarmTask?.cancel()
        dataQualityPrewarmTask = nil
        cachedMissingFieldIssues = nil
        cachedTranslationIssues = nil
        cachedUnlinkedPersonNames = nil
        cachedIntegrityIssues = nil
        cachedDuplicateIssues = nil
        cachedArchivedRecordSummaries = nil
        invalidateStorageStructureDiagnostics()
        invalidateDataQualityIssueCountCache()
    }

