    @discardableResult
    func flushPendingMetadataPersistenceIfNeeded() -> Bool {
        if let rawValue = lastSelectedTabOverride {
            pendingLastSelectedTabPersistenceWorkItem?.cancel()
            pendingLastSelectedTabPersistenceWorkItem = nil
            persistRememberedLastSelectedTab(rawValue)
        }
        pendingMetadataPersistenceWorkItem?.cancel()
        pendingMetadataPersistenceWorkItem = nil
        drainMetadataPersistenceQueue()
        guard let snapshot = pendingMetadataSnapshot else {
            pendingMetadataPersistenceInvalidatesStorageDiagnostics = false
            return true
        }
        let shouldInvalidateStorageDiagnostics = pendingMetadataPersistenceInvalidatesStorageDiagnostics
        pendingMetadataPersistenceGeneration += 1

        persistenceStatus.isSaving = true
        metadata = snapshot

        do {
            try requireSupportedStorageSchema()
            let writeResult = try metadataPersistenceQueue.sync {
                try Self.writeMetadataSnapshot(
                    snapshot,
                    databaseURL: Self.databaseURL
                )
            }
            pendingMetadataSnapshot = nil
            pendingMetadataPersistenceInvalidatesStorageDiagnostics = false
            persistenceStatus.isSaving = false
            persistenceStatus.lastSavedAt = Date()
            if !writeResult.dataByStorageKey.isEmpty {
                for (storageKey, data) in writeResult.dataByStorageKey {
                    persistedDocumentCache[storageKey] = data
                }
            }
            if shouldInvalidateStorageDiagnostics, writeResult.didWrite {
                invalidateStorageStructureDiagnosticsAfterWrite()
            }
            if writeResult.didWrite {
                enqueuePeriodicBackupSnapshotIfNeeded(now: Date())
            }
            return true
        } catch {
            pendingMetadataPersistenceInvalidatesStorageDiagnostics = false
            loadError = error.localizedDescription
            persistenceStatus.isSaving = false
            return false
        }
    }

    @discardableResult
    func flushAllPendingPersistenceIfNeeded(timeout: TimeInterval = 10) -> Bool {
        guard flushPendingMetadataPersistenceIfNeeded() else { return false }
        return flushPendingPersistenceIfNeeded(timeout: timeout)
    }

    private func englishFundingSourceName(for canonicalName: String) -> String {
        let englishName = organizationLabel(for: canonicalName, language: .english).trimmingCharacters(in: .whitespacesAndNewlines)
        if englishName.lowercased().hasPrefix("the ") {
            return "the " + englishName.dropFirst(4)
        }
        return "the \(englishName)"
    }

    private func approvedEthicsCaseNumbers(for project: ProjectRecord?) -> [String] {
        guard let project else { return [] }
        return ([project.ethicsBaseApplication] + project.ethicsAmendments)
            .filter { $0.grantedOn.trimmedOrNil != nil }
            .compactMap { $0.caseNumber.trimmedOrNil }
    }

    private func naturalLanguageList(_ items: [String], conjunction: String) -> String {
        switch items.count {
        case 0:
            return ""
        case 1:
            return items[0]
        case 2:
            return "\(items[0]) \(conjunction) \(items[1])"
        default:
            return "\(items.dropLast().joined(separator: ", ")), \(conjunction) \(items.last ?? "")"
        }
    }

    private func fundingStatementPartText(_ text: String) -> String {
        let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return trimmed }
        if trimmed.lowercased().hasPrefix("the ") {
            return "the " + trimmed.dropFirst(4)
        }
        return trimmed
    }

    /// `name` is empty for the ordinary "add researcher" button; the Data
    /// view's "Names to link" passes the written name (F13c).
    func addPublicationAuthor(name: String = "") -> String {
        let newAuthor = PublicationAuthor(
            name: name,
            affiliations: [PublicationAffiliation(isPrimary: true)]
        )

        // "The first researcher becomes me": when no valid CV profile is
        // chosen yet, store one in the same undoable change. A lone existing
        // author is already the implicit profile (see currentUserAuthor()),
        // so that author is pinned instead of switching to the new one.
        promotePendingMetadataSnapshotIfNeeded()
        let storedCurrentUserID = metadata.currentUserAuthorID?.trimmedOrNil
        let needsCurrentUser = storedCurrentUserID.map { publicationAuthor(id: $0) == nil } ?? true
        let currentUserIDToStore: String?
        if !needsCurrentUser {
            currentUserIDToStore = nil
        } else if publicationAuthors.count == 1, let implicitCurrentUserID = publicationAuthors.first?.id {
            currentUserIDToStore = implicitCurrentUserID
        } else {
            currentUserIDToStore = newAuthor.id
        }

        let didAdd = performUndoableChange(
            actionName: language.text("Add author", "Lägg till författare"),
            successMessage: language.text("Added author.", "Lade till författare."),
            failureMessage: language.text("Could not add author.", "Kunde inte lägga till författare."),
            scope: currentUserIDToStore == nil ? .publicationAuthors : .publicationAuthorsAndCurrentUser
        ) {
            publicationAuthors.append(newAuthor)
            if let currentUserIDToStore {
                var updated = self.editableMetadataSnapshot
                updated.currentUserAuthorID = currentUserIDToStore
                metadata = updated
            }
        }
        if didAdd, currentUserIDToStore != nil {
            rebuildApplicationRowSnapshots()
            rebuildPublicationAuthorRowSnapshots()
            markProjectViewCacheDirty()
        }
        return newAuthor.id
    }

    func savePublicationAuthor(_ updated: PublicationAuthor, previousName: String?, completePendingSelection: Bool = false) {
        var normalized = updated
        normalized.normalize()
        let didRename = previousName.map { $0 != normalized.name } ?? false
        let refreshScope: ChangeRefreshScope = didRename
            ? .publicationAuthorRename
            : (completePendingSelection ? .all : .publicationAuthors)

        performUndoableChange(
            actionName: language.text("Edit author", "Redigera författare"),
            successMessage: language.text("Saved author changes.", "Sparade ändringar för författare."),
            failureMessage: language.text("Could not save author changes.", "Kunde inte spara ändringar för författare."),
            scope: refreshScope
        ) {
            guard let index = publicationAuthors.firstIndex(where: { $0.id == updated.id }) else { return }
            let previousAuthor = publicationAuthors[index]
            if didRename {
                preserveAuthorNamesAfterRename(of: &normalized, previousAuthor: previousAuthor)
            }
            publicationAuthors[index] = normalized
            if completePendingSelection {
                finalizePendingSelectionIfNeeded(for: .author, entityID: normalized.id, canonicalValue: normalized.name)
            }
        }
    }

    /// On rename, the author's previous full name becomes a former name
    /// (used until today) and other names they answered to stay as spelling
    /// variants, so records written with the old name still find the person.
    private func preserveAuthorNamesAfterRename(
        of author: inout PublicationAuthor,
        previousAuthor: PublicationAuthor
    ) {
        let preservedNames = preservedAuthorNameVariantsAfterRename(from: previousAuthor, to: author.name)
        let previousFullName = [previousAuthor.firstName.nonEmpty, previousAuthor.lastName.nonEmpty]
            .compactMap { $0 }
            .joined(separator: " ")
        let previousFullNameKey = normalizedPersonLookupName(previousFullName)
        if !previousFullNameKey.isEmpty,
           preservedNames.contains(where: { normalizedPersonLookupName($0) == previousFullNameKey }) {
            author.markFormerName(
                firstName: previousAuthor.firstName,
                lastName: previousAuthor.lastName,
                usedUntil: DateParsers.isoDay.string(from: Date())
            )
        }
        author.addNameVariants(preservedNames)
        author.normalize()
    }

    struct AuthorNameVariantReference: Identifiable, Hashable {
        enum Kind: String {
            case publication
            case conferenceContribution
            case project
            case congress
            case doctoralCandidate
            case application
        }

        let kind: Kind
        let recordID: String
        let title: String
        let isProtected: Bool
        let protectionLabel: String?

        var id: String { "\(kind.rawValue)|\(recordID)" }
    }

    /// Records that still store the given variant spelling as a literal
    /// name and would lose their author link if the variant were removed.
    func authorNameVariantRemovalImpact(
        authorID: String,
        variant: PublicationAuthorNameVariant
    ) -> [AuthorNameVariantReference] {
        guard let author = publicationAuthors.first(where: { $0.id == authorID }) else { return [] }
        let variantKey = normalizedPersonLookupName(variant.displayName)
        guard !variantKey.isEmpty else { return [] }

        // Keys the author still answers to once this variant row is gone.
        // A duplicate spelling in another row keeps the key alive, in which
        // case removal is harmless.
        var remainingKeys = Set([normalizedPersonLookupName(author.name)])
        var didSkipOneMatchingRow = false
        for row in author.nameVariantRows {
            let key = normalizedPersonLookupName(row.displayName)
            if key == variantKey, !didSkipOneMatchingRow {
                didSkipOneMatchingRow = true
                continue
            }
            remainingKeys.insert(key)
        }
        guard !remainingKeys.contains(variantKey) else { return [] }

        func matches(_ storedName: String) -> Bool {
            normalizedPersonLookupName(storedName) == variantKey
        }

        var references: [AuthorNameVariantReference] = []

        for publication in publicationRecords where publication.authorNames.contains(where: matches) {
            let isPublished = publication.status.trimmingCharacters(in: .whitespacesAndNewlines)
                == PublicationStatus.published.rawValue
            let isLocked = publication.isEditingLocked
            references.append(AuthorNameVariantReference(
                kind: .publication,
                recordID: publication.id,
                title: publication.title,
                isProtected: isPublished || isLocked,
                protectionLabel: protectionLabel(isPublished: isPublished, isLocked: isLocked)
            ))
        }

        for contribution in cvConferenceContributions
        where contribution.contributorNames.contains(where: matches) || matches(contribution.presentedBy) {
            let isPublished = isPublishedConferenceContribution(contribution)
            references.append(AuthorNameVariantReference(
                kind: .conferenceContribution,
                recordID: contribution.id,
                title: contribution.displayTitle,
                isProtected: isPublished,
                protectionLabel: protectionLabel(isPublished: isPublished, isLocked: false)
            ))
        }

        for project in projects where project.collaboratorNames.contains(where: matches) {
            references.append(AuthorNameVariantReference(
                kind: .project,
                recordID: project.id,
                title: project.nameSv.nonEmpty ?? project.nameEn,
                isProtected: project.isEditingLocked,
                protectionLabel: protectionLabel(isPublished: false, isLocked: project.isEditingLocked)
            ))
        }

        for organization in organizations {
            for congress in organization.congresses where congress.participantNames.contains(where: matches) {
                references.append(AuthorNameVariantReference(
                    kind: .congress,
                    recordID: congress.id,
                    title: congress.title.nonEmpty ?? organization.nameSv,
                    isProtected: congress.isEditingLocked,
                    protectionLabel: protectionLabel(isPublished: false, isLocked: congress.isEditingLocked)
                ))
            }
        }

        // Round 11: grant records are rewritten too (their applicants), so a
        // locked one is listed before anything changes.
        for application in applications where application.coApplicants.contains(where: matches) {
            references.append(AuthorNameVariantReference(
                kind: .application,
                recordID: application.id,
                title: application.displayTitle,
                isProtected: application.isEditingLocked,
                protectionLabel: protectionLabel(isPublished: false, isLocked: application.isEditingLocked)
            ))
        }

        for candidate in doctoralCandidates
        where (matches(candidate.candidateName)
            && (candidate.candidateAuthorID == nil || candidate.candidateAuthorID == authorID))
            || candidate.supervisors.contains(where: { matches($0.name) && ($0.authorID == nil || $0.authorID == authorID) }) {
            references.append(AuthorNameVariantReference(
                kind: .doctoralCandidate,
                recordID: candidate.id,
                title: candidate.candidateName,
                isProtected: candidate.isEditingLocked,
                protectionLabel: protectionLabel(isPublished: false, isLocked: candidate.isEditingLocked)
            ))
        }

        return references
    }

    private func protectionLabel(isPublished: Bool, isLocked: Bool) -> String? {
        switch (isPublished, isLocked) {
        case (true, true):
            return language.text("published and locked", "publicerad och låst")
        case (true, false):
            return language.text("published", "publicerad")
        case (false, true):
            return language.text("locked", "låst")
        case (false, false):
            return nil
        }
    }

    /// Removes a name variant and rewrites every record that still stores
    /// the old spelling to the author's current name, so links survive.
    /// If protected (published/locked) records are affected, an explicit
    /// confirmation listing them is required first.
    func removeAuthorNameVariantRewritingReferences(
        authorID: String,
        variant: PublicationAuthorNameVariant
    ) {
        guard let author = publicationAuthors.first(where: { $0.id == authorID }) else { return }
        let references = authorNameVariantRemovalImpact(authorID: authorID, variant: variant)
        let newName = author.name
        let variantKey = normalizedPersonLookupName(variant.displayName)
        let variantDisplayName = variant.displayName

        let performRemoval: () -> Void = { [weak self] in
            guard let self else { return }
            self.performAuthorNameVariantRemoval(
                authorID: authorID,
                variantKey: variantKey,
                newName: newName
            )
        }

        let protectedReferences = references.filter(\.isProtected)
        guard !protectedReferences.isEmpty else {
            performRemoval()
            return
        }

        requestImpactConfirmation(
            title: language.text(
                "Rename in protected records?",
                "Byt namn i skyddade poster?"
            ),
            message: language.text(
                "The name \"\(variantDisplayName)\" is still used by published or locked records. They will be updated to \"\(newName)\" so their links remain intact.",
                "Namnet ”\(variantDisplayName)” används fortfarande av publicerade eller låsta poster. De uppdateras till ”\(newName)” så att kopplingarna behålls."
            ),
            details: protectedReferences.map { reference in
                let kindLabel = authorReferenceKindLabel(reference.kind)
                let suffix = reference.protectionLabel.map { " (\($0))" } ?? ""
                return "\(kindLabel): \(reference.title)\(suffix)"
            },
            confirmTitle: language.text(
                "Update names and remove variant",
                "Uppdatera namnen och ta bort varianten"
            ),
            action: performRemoval
        )
    }

    /// Number of records that still write the author's name the way the
    /// given variant (a former name or other spelling) spells it.
    func authorNameVariantUsageCount(authorID: String, variant: PublicationAuthorNameVariant) -> Int {
        let variantKey = normalizedPersonLookupName(variant.displayName)
        guard !variantKey.isEmpty else { return 0 }
        func matches(_ storedName: String) -> Bool {
            normalizedPersonLookupName(storedName) == variantKey
        }
        var count = 0
        count += publicationRecords.filter {
            $0.authorNames.contains(where: matches) || $0.correspondingAuthorName.map(matches) == true
        }.count
        count += cvConferenceContributions.filter {
            $0.contributorNames.contains(where: matches) || matches($0.presentedBy)
        }.count
        count += projects.filter {
            $0.collaboratorNames.contains(where: matches)
                || $0.projectTasks.contains { $0.participantNames.contains(where: matches) }
        }.count
        count += organizations.reduce(0) { total, organization in
            total + organization.congresses.filter { $0.participantNames.contains(where: matches) }.count
        }
        count += doctoralCandidates.filter { candidate in
            (matches(candidate.candidateName)
                && (candidate.candidateAuthorID == nil || candidate.candidateAuthorID == authorID))
                || candidate.supervisors.contains {
                    matches($0.name) && ($0.authorID == nil || $0.authorID == authorID)
                }
        }.count
        count += applications.filter { $0.coApplicants.contains(where: matches) }.count
        count += teachingAssignments.filter { matches($0.studentName) }.count
        count += calendarMeetingRecords.filter { $0.participantNames.contains(where: matches) }.count
        count += taskItems.filter { $0.participantNames.contains(where: matches) }.count
        return count
    }

    /// Writes the author's current name in every record that still uses the
    /// given former name or spelling, and then removes that name from the
    /// researcher card. Asks for confirmation first and can be undone.
    func replaceAuthorNameVariantWithCurrentName(
        authorID: String,
        variant: PublicationAuthorNameVariant
    ) {
        guard let author = publicationAuthors.first(where: { $0.id == authorID }) else { return }
        let variantKey = normalizedPersonLookupName(variant.displayName)
        guard !variantKey.isEmpty else { return }
        let newName = author.name
        let variantDisplayName = variant.displayName
        let count = authorNameVariantUsageCount(authorID: authorID, variant: variant)
        guard count > 0 else {
            // Nothing to rewrite: only the name on the researcher card goes.
            performAuthorNameVariantRemoval(authorID: authorID, variantKey: variantKey, newName: newName)
            return
        }
        let protectedTitles = authorNameVariantRemovalImpact(authorID: authorID, variant: variant)
            .filter(\.isProtected)
            .map { reference in
                let suffix = reference.protectionLabel.map { " (\($0))" } ?? ""
                return "\(authorReferenceKindLabel(reference.kind)): \(reference.title)\(suffix)"
            }
        requestImpactConfirmation(
            title: language.text("Replace with the current name?", "Ersätt med aktuellt namn?"),
            message: language.text(
                "\(count) records write the name as \"\(variantDisplayName)\". They will be changed to \"\(newName)\", and \"\(variantDisplayName)\" is removed from the researcher card. You can undo this.",
                "\(count) poster skriver namnet som ”\(variantDisplayName)”. De ändras till ”\(newName)”, och ”\(variantDisplayName)” tas bort från forskarkortet. Det går att ångra."
            ),
            details: protectedTitles,
            confirmTitle: language.text("Replace in \(count) records", "Ersätt i \(count) poster"),
            action: { [weak self] in
                self?.performAuthorNameVariantRemoval(
                    authorID: authorID,
                    variantKey: variantKey,
                    newName: newName
                )
            }
        )
    }

    private func authorReferenceKindLabel(_ kind: AuthorNameVariantReference.Kind) -> String {
        switch kind {
        case .publication:
            return language.text("Publication", "Publikation")
        case .conferenceContribution:
            return language.text("Conference contribution", "Konferensbidrag")
        case .project:
            return language.text("Project", "Projekt")
        case .congress:
            return language.text("Congress", "Kongress")
        case .doctoralCandidate:
            return language.text("Doctoral candidate", "Doktorand")
        case .application:
            return language.text("Grant call or grant", "Utlysning eller anslag")
        }
    }

    private func performAuthorNameVariantRemoval(
        authorID: String,
        variantKey: String,
        newName: String,
        removesVariant: Bool = true
    ) {
        func matches(_ storedName: String) -> Bool {
            normalizedPersonLookupName(storedName) == variantKey
        }

        func rewritten(_ names: [String]) -> [String] {
            var seenKeys = Set<String>()
            return names.compactMap { name in
                let resolved = matches(name) ? newName : name
                let key = normalizedPersonLookupName(resolved)
                guard seenKeys.insert(key).inserted else { return nil }
                return resolved
            }
        }

        performUndoableChange(
            actionName: removesVariant
                ? language.text("Remove name variant", "Ta bort namnvariant")
                : language.text("Replace with current name", "Ersätt med aktuellt namn"),
            successMessage: removesVariant
                ? language.text(
                    "Removed the name variant and updated linked records.",
                    "Tog bort namnvarianten och uppdaterade kopplade poster."
                )
                : language.text(
                    "The records now use the current name.",
                    "Posterna använder nu det aktuella namnet."
                ),
            failureMessage: removesVariant
                ? language.text(
                    "Could not remove the name variant.",
                    "Kunde inte ta bort namnvarianten."
                )
                : language.text(
                    "Could not update the records.",
                    "Kunde inte uppdatera posterna."
                ),
            scope: .all
        ) {
            for index in publicationRecords.indices
            where publicationRecords[index].authorNames.contains(where: matches) {
                publicationRecords[index].authorNames = rewritten(publicationRecords[index].authorNames)
            }
            for index in publicationRecords.indices
            where publicationRecords[index].correspondingAuthorName.map(matches) == true {
                publicationRecords[index].correspondingAuthorName = newName
            }
            for candidateIndex in doctoralCandidates.indices {
                for supervisorIndex in doctoralCandidates[candidateIndex].supervisors.indices
                where matches(doctoralCandidates[candidateIndex].supervisors[supervisorIndex].name)
                    && (doctoralCandidates[candidateIndex].supervisors[supervisorIndex].authorID == nil
                        || doctoralCandidates[candidateIndex].supervisors[supervisorIndex].authorID == authorID) {
                    doctoralCandidates[candidateIndex].supervisors[supervisorIndex].name = newName
                }
            }
            for index in cvConferenceContributions.indices {
                if cvConferenceContributions[index].contributorNames.contains(where: matches) {
                    cvConferenceContributions[index].contributorNames =
                        rewritten(cvConferenceContributions[index].contributorNames)
                }
                if matches(cvConferenceContributions[index].presentedBy) {
                    cvConferenceContributions[index].presentedBy = newName
                }
            }
            for index in projects.indices
            where projects[index].collaboratorNames.contains(where: matches) {
                projects[index].collaboratorNames = rewritten(projects[index].collaboratorNames)
            }
            for organizationIndex in organizations.indices {
                for congressIndex in organizations[organizationIndex].congresses.indices
                where organizations[organizationIndex].congresses[congressIndex].participantNames.contains(where: matches) {
                    organizations[organizationIndex].congresses[congressIndex].participantNames =
                        rewritten(organizations[organizationIndex].congresses[congressIndex].participantNames)
                }
            }
            for index in doctoralCandidates.indices
            where matches(doctoralCandidates[index].candidateName)
                && (doctoralCandidates[index].candidateAuthorID == nil
                    || doctoralCandidates[index].candidateAuthorID == authorID) {
                doctoralCandidates[index].candidateName = newName
            }
            // F16a: the former name is also replaced where people are still stored by name.
            for index in applications.indices
            where applications[index].coApplicants.contains(where: matches) {
                applications[index].coApplicants = rewritten(applications[index].coApplicants)
            }
            for index in teachingAssignments.indices where matches(teachingAssignments[index].studentName) {
                teachingAssignments[index].studentName = newName
            }
            for projectIndex in projects.indices {
                for taskIndex in projects[projectIndex].projectTasks.indices
                where projects[projectIndex].projectTasks[taskIndex].participantNames.contains(where: matches) {
                    projects[projectIndex].projectTasks[taskIndex].participantNames =
                        rewritten(projects[projectIndex].projectTasks[taskIndex].participantNames)
                }
            }
            var updatedMetadata = editableMetadataSnapshot
            var didChangeMetadata = false
            if var meetings = updatedMetadata.calendarMeetingRecords {
                for meetingIndex in meetings.indices
                where meetings[meetingIndex].participantNames.contains(where: matches) {
                    meetings[meetingIndex].participantNames = rewritten(meetings[meetingIndex].participantNames)
                    didChangeMetadata = true
                }
                updatedMetadata.calendarMeetingRecords = meetings
            }
            if var tasks = updatedMetadata.taskItems {
                for taskIndex in tasks.indices
                where tasks[taskIndex].participantNames.contains(where: matches) {
                    tasks[taskIndex].participantNames = rewritten(tasks[taskIndex].participantNames)
                    didChangeMetadata = true
                }
                updatedMetadata.taskItems = tasks
            }
            if didChangeMetadata {
                metadata = updatedMetadata
            }

            if removesVariant, let authorIndex = publicationAuthors.firstIndex(where: { $0.id == authorID }) {
                var didRemoveOneRow = false
                publicationAuthors[authorIndex].nameVariantRows =
                    publicationAuthors[authorIndex].nameVariantRows.filter { row in
                        if normalizedPersonLookupName(row.displayName) == variantKey, !didRemoveOneRow {
                            didRemoveOneRow = true
                            return false
                        }
                        return true
                    }
            }
        }
    }

    func autosavePublicationAuthor(_ updated: PublicationAuthor, previousName: String?, completePendingSelection: Bool = false) {
        guard let index = publicationAuthors.firstIndex(where: { $0.id == updated.id }) else { return }
        let previousAuthors = publicationAuthors
        let previousRecords = publicationRecords
        let previousApplications = applications
        let previousProjects = projects
        let previousAssignments = teachingAssignments
        let previousDoctoralCandidates = doctoralCandidates
        let previousConferenceContributions = cvConferenceContributions

        do {
            var normalized = updated
            normalized.normalize()
            let didRename = previousName.map { $0 != normalized.name } ?? false
            let pendingSelectionAffectedSet: PersistenceSet = completePendingSelection
                ? pendingSelectionPersistenceSet(for: .author, entityID: normalized.id)
                : []
            guard didRename || publicationAuthors[index] != normalized else {
                if !pendingSelectionAffectedSet.isEmpty {
                    let previousStates = try persistedBaselineDocumentStates(for: pendingSelectionAffectedSet)
                    finalizePendingSelectionIfNeeded(for: .author, entityID: normalized.id, canonicalValue: normalized.name)
                    try enqueueAutosavePersistence(
                        pendingSelectionAffectedSet,
                        actionName: language.text("Edit author", "Redigera författare"),
                        previousStates: previousStates
                    )
                }
                return
            }
            if didRename {
                var affectedSet: PersistenceSet = [.publicationAuthors]
                affectedSet.formUnion(pendingSelectionAffectedSet)
                let previousStates = try persistedBaselineDocumentStates(for: affectedSet)
                let previousAuthor = publicationAuthors[index]
                preserveAuthorNamesAfterRename(of: &normalized, previousAuthor: previousAuthor)
                publicationAuthors[index] = normalized
                refreshPublicationAuthorsOnly()
                refreshApplicationsState()
                refreshTeachingAssignmentsOnly()
                refreshDoctoralCandidatesOnly()
                refreshPublicationRecords()
                try enqueueAutosavePersistence(
                    affectedSet,
                    actionName: language.text("Edit author", "Redigera författare"),
                    previousStates: previousStates
                )
            } else {
                var affectedSet: PersistenceSet = [.publicationAuthors]
                affectedSet.formUnion(pendingSelectionAffectedSet)
                let previousStates = try persistedBaselineDocumentStates(for: affectedSet)
                publicationAuthors[index] = normalized
                refreshPublicationAuthorsOnly()
                try enqueueAutosavePersistence(
                    affectedSet,
                    actionName: language.text("Edit author", "Redigera författare"),
                    previousStates: previousStates
                )
            }
            if completePendingSelection {
                finalizePendingSelectionIfNeeded(for: .author, entityID: normalized.id, canonicalValue: normalized.name)
            }
            loadError = nil
        } catch {
            publicationAuthors = previousAuthors
            publicationRecords = previousRecords
            applications = previousApplications
            projects = previousProjects
            teachingAssignments = previousAssignments
            doctoralCandidates = previousDoctoralCandidates
            cvConferenceContributions = previousConferenceContributions
            refreshPublicationAuthorsOnly()
            refreshApplicationsState()
            refreshTeachingAssignmentsOnly()
            refreshDoctoralCandidatesOnly()
            refreshPublicationRecords()
            persistenceStatus.isSaving = false
            loadError = error.localizedDescription
        }
    }

    /// Round 16: true when deleting this researcher shows the linked-object
    /// warning, so the view does not ask a second time.
    func publicationAuthorDeletionShowsImpactWarning(id: String) -> Bool {
        deletionImpactDetailsForPublicationAuthor(id: id).contains { !$0.isEmpty }
    }

    func deletePublicationAuthor(id: String) {
        let details = deletionImpactDetailsForPublicationAuthor(id: id)
        if requestDeletionConfirmationIfNeeded(
            title: language.text("Delete researcher?", "Ta bort forskare?"),
            details: details,
            action: { [weak self] in self?.deletePublicationAuthorConfirmed(id: id) }
        ) {
            return
        }
        deletePublicationAuthorConfirmed(id: id)
    }

    private func deletePublicationAuthorConfirmed(id: String) {
        performUndoableChange(
            actionName: language.text("Archive researcher", "Arkivera forskare"),
            successMessage: language.text("Archived researcher.", "Arkiverade forskare."),
            failureMessage: language.text("Could not archive researcher.", "Kunde inte arkivera forskare."),
            scope: .all
        ) {
            if let author = publicationAuthors.first(where: { $0.id == id }) {
                try archiveDeletion(
                    kind: "publication_author",
                    title: author.name,
                    payload: author,
                    relatedDocumentStates: try archivedRelatedStatesForPublicationAuthorDeletion()
                )
            }
            let deletedAuthor = publicationAuthors.first(where: { $0.id == id })
            publicationAuthors.removeAll { $0.id == id }
            if metadata.currentUserAuthorID == id {
                var updatedMetadata = editableMetadataSnapshot
                updatedMetadata.currentUserAuthorID = nil
                metadata = updatedMetadata
            }
            guard let deletedAuthor else { return }
            let deletedVariants = authorNameVariants(for: deletedAuthor)
            for recordIndex in publicationRecords.indices {
                publicationRecords[recordIndex].authorNames.removeAll { deletedVariants.contains($0) }
            }
            for applicationIndex in applications.indices {
                applications[applicationIndex].coApplicants.removeAll { deletedVariants.contains($0) }
            }
            for projectIndex in projects.indices {
                projects[projectIndex].collaboratorNames.removeAll { deletedVariants.contains($0) }
            }
            for assignmentIndex in teachingAssignments.indices where deletedVariants.contains(teachingAssignments[assignmentIndex].studentName) {
                teachingAssignments[assignmentIndex].studentName = ""
            }
            for candidateIndex in doctoralCandidates.indices {
                if doctoralCandidates[candidateIndex].candidateAuthorID == id ||
                    deletedVariants.contains(doctoralCandidates[candidateIndex].candidateName) {
                    doctoralCandidates[candidateIndex].candidateAuthorID = nil
                    if deletedVariants.contains(doctoralCandidates[candidateIndex].candidateName) {
                        doctoralCandidates[candidateIndex].candidateName = ""
                    }
                }
                for supervisorIndex in doctoralCandidates[candidateIndex].supervisors.indices.reversed() {
                    let supervisor = doctoralCandidates[candidateIndex].supervisors[supervisorIndex]
                    if supervisor.authorID == id || deletedVariants.contains(supervisor.name) {
                        doctoralCandidates[candidateIndex].supervisors.remove(at: supervisorIndex)
                    }
                }
            }
            for contributionIndex in cvConferenceContributions.indices {
                if deletedVariants.contains(cvConferenceContributions[contributionIndex].presentedBy) {
                    cvConferenceContributions[contributionIndex].presentedBy = ""
                }
                if cvConferenceContributions[contributionIndex].presentedByAuthorID == id {
                    cvConferenceContributions[contributionIndex].presentedByAuthorID = nil
                }
                cvConferenceContributions[contributionIndex].contributorNames.removeAll { deletedVariants.contains($0) }
                cvConferenceContributions[contributionIndex].contributorAuthorIDs.removeAll { $0 == id }
            }
            for organizationIndex in organizations.indices {
                for congressIndex in organizations[organizationIndex].congresses.indices {
                    organizations[organizationIndex].congresses[congressIndex].participantAuthorIDs.removeAll { $0 == id }
                }
            }
            // F13b: the deleted researcher's id also leaves every list kept by name and id.
            replacePersonAuthorIDLinks(from: id, to: nil)
        }
    }

    func addPublication() -> String {
        let nextNumber = (publicationRecords.compactMap { Int($0.number) }.max() ?? 0) + 1
        // No default project: a new record must start unlinked, not silently
        // attached to whichever project happens to sort first.
        let record = PublicationRecord(
            number: String(nextNumber),
            projectName: nil,
            title: language.text("New publication", "Ny publikation"),
            status: PublicationStatus.inPreparation.rawValue
        )

        performUndoableChange(
            actionName: language.text("Add publication", "Lägg till publikation"),
            successMessage: language.text("Added publication.", "Lade till publikation."),
            failureMessage: language.text("Could not add publication.", "Kunde inte lägga till publikation."),
            scope: .publicationRecords
        ) {
            publicationRecords.insert(record, at: 0)
        }
        return record.id
    }

    func savePublication(_ updated: PublicationRecord, silently: Bool = false) {
        if silently {
            do {
                guard let index = publicationRecords.firstIndex(where: { $0.id == updated.id }) else { return }
                let previous = publicationRecords[index]
                let normalized = try normalizedPublicationForPersistence(updated, previous: previous)
                publicationRecords[index] = normalized
                refreshPublicationRecordCaches(afterUpdating: normalized, previous: previous)
                try persistScope(.publicationRecords)
                if let updatedProjects = projectsByApplyingPublicationEventTasks(projects, publication: normalized, previousPublication: previous) {
                    projects = updatedProjects
                    refreshProjectIndexesAndCaches()
                    try persistScope(.projects)
                }
                loadError = nil
            } catch {
                loadError = error.localizedDescription
                notice = StoreNotice(message: language.text("Could not save publication changes.", "Kunde inte spara ändringar i publikationen."), tone: .error)
            }
            return
        }

        // Round 12: project tasks waiting for this publication follow in the
        // same step (and are saved with it).
        let eventProjects: [ProjectRecord]? = {
            guard let index = publicationRecords.firstIndex(where: { $0.id == updated.id }) else { return nil }
            let previous = publicationRecords[index]
            var candidate = updated
            candidate.normalize()
            return projectsByApplyingPublicationEventTasks(projects, publication: candidate, previousPublication: previous)
        }()
        performUndoableChange(
            actionName: language.text("Edit publication", "Redigera publikation"),
            successMessage: language.text("Saved publication changes.", "Sparade ändringar i publikationen."),
            failureMessage: language.text("Could not save publication changes.", "Kunde inte spara ändringar i publikationen."),
            scope: eventProjects == nil ? .publicationRecords : .all
        ) {
            guard let index = publicationRecords.firstIndex(where: { $0.id == updated.id }) else { return }
            let previous = publicationRecords[index]
            let normalized = try normalizedPublicationForPersistence(updated, previous: previous)
            publicationRecords[index] = normalized
            if let eventProjects {
                projects = eventProjects
                refreshProjectIndexesAndCaches()
            }
        }
    }

    func autosavePublication(_ updated: PublicationRecord) {
        guard let index = publicationRecords.firstIndex(where: { $0.id == updated.id }) else { return }
        let previousRecords = publicationRecords
        let previousAuthors = publicationAuthors

        let previousProjects = projects
        do {
            let previous = publicationRecords[index]
            let normalized = try normalizedPublicationForPersistence(updated, previous: previous)
            guard normalized != previous else { return }
            let updatedProjects = projectsByApplyingPublicationEventTasks(projects, publication: normalized, previousPublication: previous)
            let affectedSet: PersistenceSet = updatedProjects == nil ? [.publicationRecords] : [.publicationRecords, .projects]
            let previousStates = try persistedBaselineDocumentStates(for: affectedSet)
            publicationRecords[index] = normalized
            if let updatedProjects {
                projects = updatedProjects
                refreshProjectIndexesAndCaches()
            }
            refreshPublicationRecordCaches(afterUpdating: normalized, previous: previous)
            try enqueueAutosavePersistence(
                affectedSet,
                actionName: language.text("Edit publication", "Redigera publikation"),
                previousStates: previousStates
            )
        } catch {
            publicationRecords = previousRecords
            publicationAuthors = previousAuthors
            projects = previousProjects
            refreshProjectIndexesAndCaches()
            refreshPublicationRecordCaches(projectCacheBehavior: .markDirty)
            persistenceStatus.isSaving = false
            loadError = error.localizedDescription
        }
    }

    func addPublicationJournals(_ journalIDs: [String], toPublicationID publicationID: String) {
        guard var publication = publicationRecords.first(where: { $0.id == publicationID }),
              PublicationStatus.fromStored(publication.statusLabel) != .published else { return }

        var rows = derivedSubmissionRows(for: publication).filter { !$0.isEmpty }
        var existingJournalIDs = Set(rows.compactMap { linkedJournal(ofSubmissionJournalName: $0.journal, in: publication)?.id })
        var existingFallbackNames = Set(
            rows.compactMap { $0.trimmedJournal.nonEmpty }.map {
                $0.folding(options: [.diacriticInsensitive, .caseInsensitive], locale: .current)
            }
        )
        var selectedJournalIDs = Set<String>()

        for journalID in journalIDs {
            guard selectedJournalIDs.insert(journalID).inserted,
                  let journal = publicationJournal(id: journalID) else { continue }
            let fallbackName = journal.name.folding(
                options: [.diacriticInsensitive, .caseInsensitive],
                locale: .current
            )
            guard !existingJournalIDs.contains(journal.id),
                  !existingFallbackNames.contains(fallbackName) else { continue }

            rows.append(PublicationSubmissionEditorRow(journal: journal.name))
            existingJournalIDs.insert(journal.id)
            existingFallbackNames.insert(fallbackName)
        }

        let nextTimeline = rows.flatMap(\.persistedStatusEntries)
        guard nextTimeline != publication.statusTimeline else { return }
        publication.statusTimeline = nextTimeline
        savePublication(publication)
    }

    private func normalizedPublicationForPersistence(
        _ updated: PublicationRecord,
        previous: PublicationRecord
    ) throws -> PublicationRecord {
        var normalized = updated
        normalized.normalize()
        try synchronizePublicationPDFAttachmentForPersistence(&normalized, previous: previous)
        return derivePublicationFields(for: normalized, previous: previous)
    }

    private func synchronizePublicationPDFAttachmentForPersistence(
        _ publication: inout PublicationRecord,
        previous: PublicationRecord
    ) throws {
        let hasAttachment = publication.finalPDFFilename?.trimmedOrNil != nil
            || publication.finalPDFPath?.trimmedOrNil != nil
        if !hasAttachment {
            publication.finalPDFFilename = nil
            publication.finalPDFPath = nil
            if previous.finalPDFFilename?.trimmedOrNil != nil || previous.finalPDFPath?.trimmedOrNil != nil {
                try Self.removeManagedPublicationPDFIfPresent(forPublicationID: publication.id)
            }
            return
        }

        _ = try Self.canonicalizePublicationPDFAttachment(for: &publication)
    }

    func deletePublication(id: String) {
        performUndoableChange(
            actionName: language.text("Archive publication", "Arkivera publikation"),
            successMessage: language.text("Archived publication.", "Arkiverade publikation."),
            failureMessage: language.text("Could not archive publication.", "Kunde inte arkivera publikation."),
            scope: .publicationRecords
        ) {
            if let publication = publicationRecords.first(where: { $0.id == id }) {
                try archiveDeletion(
                    kind: "publication_record",
                    title: publication.title.nonEmpty ?? publication.id,
                    payload: publication,
                    relatedDocumentStates: try archivedRelatedStatesForPublicationDeletion()
                )
            }
            publicationRecords.removeAll { $0.id == id }
            // Round 11: the PDF stays on disk so Undo and the archive can
            // bring the record back with its file.
        }
    }

    func addPublicationJournal() -> String {
        let journal = PublicationJournal(name: language.text("New journal", "Ny tidskrift"))
        performUndoableChange(
            actionName: language.text("Add journal", "Lägg till tidskrift"),
            successMessage: language.text("Added journal.", "Lade till tidskrift."),
            failureMessage: language.text("Could not add journal.", "Kunde inte lägga till tidskrift."),
            scope: .publicationJournals
        ) {
            publicationJournals.append(journal)
        }
        return journal.id
    }

    func savePublicationJournal(_ updated: PublicationJournal, previousName: String?, completePendingSelection: Bool = false) {
        performUndoableChange(
            actionName: language.text("Edit journal", "Redigera tidskrift"),
            successMessage: language.text("Saved journal changes.", "Sparade ändringar i tidskriften."),
            failureMessage: language.text("Could not save journal changes.", "Kunde inte spara ändringar i tidskriften."),
            scope: .publicationJournalReferences
        ) {
            guard let index = publicationJournals.firstIndex(where: { $0.id == updated.id }) else { return }
            var normalized = updated
            normalized.normalize()
            publicationJournals[index] = normalized
            if let previousName, previousName != normalized.name {
                propagateJournalRename(from: previousName, to: normalized)
            }
            if completePendingSelection {
                finalizePendingSelectionIfNeeded(for: .journal, entityID: normalized.id, canonicalValue: normalized.name)
            }
        }
    }

    func autosavePublicationJournal(_ updated: PublicationJournal, previousName: String?, completePendingSelection: Bool = false) {
        guard let index = publicationJournals.firstIndex(where: { $0.id == updated.id }) else { return }
        let previousJournals = publicationJournals
        let previousRecords = publicationRecords
        let previousConferenceContributions = cvConferenceContributions
        let previousReviewEntries = cvReviewEntries

        do {
            var normalized = updated
            normalized.normalize()
            let didRename = previousName.map { $0 != normalized.name } ?? false
            let pendingSelectionAffectedSet: PersistenceSet = completePendingSelection
                ? pendingSelectionPersistenceSet(for: .journal, entityID: normalized.id)
                : []
            guard didRename || publicationJournals[index] != normalized else {
                if !pendingSelectionAffectedSet.isEmpty {
                    let previousStates = try persistedBaselineDocumentStates(for: pendingSelectionAffectedSet)
                    finalizePendingSelectionIfNeeded(for: .journal, entityID: normalized.id, canonicalValue: normalized.name)
                    try enqueueAutosavePersistence(
                        pendingSelectionAffectedSet,
                        actionName: language.text("Edit journal", "Redigera tidskrift"),
                        previousStates: previousStates
                    )
                }
                return
            }
            var affectedSet: PersistenceSet = didRename ? [.publicationJournals, .publicationRecords, .cvConferenceContributions, .cvReviewEntries] : [.publicationJournals]
            affectedSet.formUnion(pendingSelectionAffectedSet)
            let previousStates = try persistedBaselineDocumentStates(for: affectedSet)
            publicationJournals[index] = normalized
            if didRename, let previousName {
                propagateJournalRename(from: previousName, to: normalized)
                refreshPublicationJournalsState(projectCacheBehavior: .skip)
            } else {
                refreshPublicationJournalAutosaveState(updatedJournalID: normalized.id)
            }
            try enqueueAutosavePersistence(
                affectedSet,
                actionName: language.text("Edit journal", "Redigera tidskrift"),
                previousStates: previousStates
            )
            if completePendingSelection {
                finalizePendingSelectionIfNeeded(for: .journal, entityID: normalized.id, canonicalValue: normalized.name)
            }
            loadError = nil
        } catch {
            publicationJournals = previousJournals
            publicationRecords = previousRecords
            cvConferenceContributions = previousConferenceContributions
            cvReviewEntries = previousReviewEntries
            refreshPublicationJournalsState(projectCacheBehavior: .skip)
            persistenceStatus.isSaving = false
            loadError = error.localizedDescription
        }
    }

    /// Round 16: true when deleting this journal shows the linked-object
    /// warning, so the view does not ask a second time.
    func publicationJournalDeletionShowsImpactWarning(id: String) -> Bool {
        let name = publicationJournals.first(where: { $0.id == id })?.name
        return deletionImpactDetailsForPublicationJournal(id: id, name: name).contains { !$0.isEmpty }
    }

    func deletePublicationJournal(id: String) {
        let deletedName = publicationJournals.first(where: { $0.id == id })?.name
        let details = deletionImpactDetailsForPublicationJournal(id: id, name: deletedName)
        if requestDeletionConfirmationIfNeeded(
            title: language.text("Delete journal?", "Ta bort tidskrift?"),
            details: details,
            action: { [weak self] in self?.deletePublicationJournalConfirmed(id: id) }
        ) {
            return
        }
        deletePublicationJournalConfirmed(id: id)
    }

    private func deletePublicationJournalConfirmed(id: String) {
        performUndoableChange(
            actionName: language.text("Archive journal", "Arkivera tidskrift"),
            successMessage: language.text("Archived journal.", "Arkiverade tidskrift."),
            failureMessage: language.text("Could not archive journal.", "Kunde inte arkivera tidskrift."),
            scope: .publicationJournalReferences
        ) {
            if let journal = publicationJournals.first(where: { $0.id == id }) {
                try archiveDeletion(
                    kind: "publication_journal",
                    title: journal.name,
                    payload: journal,
                    relatedDocumentStates: try archivedRelatedStatesForPublicationJournalDeletion()
                )
            }
            let deletedName = publicationJournals.first(where: { $0.id == id })?.name
            publicationJournals.removeAll { $0.id == id }
            guard let deletedName else { return }
            for recordIndex in publicationRecords.indices
            where publicationRecords[recordIndex].journalID == id || publicationRecords[recordIndex].journal == deletedName {
                publicationRecords[recordIndex].journalID = nil
                publicationRecords[recordIndex].journal = ""
            }
            for contributionIndex in cvConferenceContributions.indices {
                if cvConferenceContributions[contributionIndex].journalID == id ||
                    cvConferenceContributions[contributionIndex].journalName == deletedName {
                    cvConferenceContributions[contributionIndex].journalID = nil
                    cvConferenceContributions[contributionIndex].journalName = ""
                }
            }
            for reviewIndex in cvReviewEntries.indices
            where cvReviewEntries[reviewIndex].journalID == id || cvReviewEntries[reviewIndex].journalName == deletedName {
                cvReviewEntries[reviewIndex].journalID = nil
                cvReviewEntries[reviewIndex].journalName = ""
            }
        }
    }

    @discardableResult
    func repairStoredReferenceIntegrity() -> Bool {
        var didChange = false
        let canonicalOrganizationLookup = organizations.reduce(into: [String: String]()) { partialResult, option in
            for candidate in [option.nameSv, option.nameEn] {
                let key = normalizedPersonLookupName(candidate)
                guard !key.isEmpty, partialResult[key] == nil else { continue }
                partialResult[key] = option.nameSv
            }
        }
        let canonicalManagerLookup = managers.reduce(into: [String: String]()) { partialResult, option in
            for candidate in [option.nameSv, option.nameEn] {
                let key = normalizedPersonLookupName(candidate)
                guard !key.isEmpty, partialResult[key] == nil else { continue }
                partialResult[key] = option.nameSv
            }
        }
        let canonicalProjectLookup = projects.reduce(into: [String: String]()) { partialResult, option in
            for candidate in [option.nameSv, option.nameEn] {
                let key = normalizedPersonLookupName(candidate)
                guard !key.isEmpty, partialResult[key] == nil else { continue }
                partialResult[key] = option.nameSv
            }
        }
        let canonicalAuthorLookup = publicationAuthors.reduce(into: [String: String]()) { partialResult, author in
            let variants = [
                author.name,
                author.displayName,
                [author.firstName.nonEmpty, author.lastName.nonEmpty].compactMap { $0 }.joined(separator: " ")
            ]
            for candidate in variants {
                let key = normalizedPersonLookupName(candidate)
                guard !key.isEmpty, partialResult[key] == nil else { continue }
                partialResult[key] = author.name
            }
        }
        let canonicalJournalLookup = publicationJournals.reduce(into: [String: String]()) { partialResult, journal in
            for candidate in [journal.name, journal.abbreviatedName, journal.resolvedISSNLTWAAbbreviatedName] {
                let key = Self.normalizedPublicationJournalLookupKey(candidate)
                guard !key.isEmpty, partialResult[key] == nil else { continue }
                partialResult[key] = journal.name
            }
        }

        // "Alla kopplingar via id": a row that points to a record gets that
        // record's name; only rows without a link are tidied by name.
        for index in applications.indices {
            var repaired = applications[index]
            if let idOrganization = organization(id: repaired.organizationID) {
                if repaired.organization != idOrganization.nameSv {
                    repaired.organization = idOrganization.nameSv
                }
            } else {
                let organizationKey = normalizedPersonLookupName(repaired.organization)
                if let canonicalOrganization = canonicalOrganizationLookup[organizationKey],
                   canonicalOrganization != repaired.organization {
                    repaired.organization = canonicalOrganization
                }
            }
            if let idManager = manager(id: repaired.applicationManagerID) {
                if repaired.applicationManager != idManager.nameSv {
                    repaired.applicationManager = idManager.nameSv
                }
            } else if let managerName = repaired.applicationManager?.trimmedOrNil,
               let canonicalManager = canonicalManagerLookup[normalizedPersonLookupName(managerName)],
               canonicalManager != managerName {
                repaired.applicationManager = canonicalManager
            }
            if let idProject = project(id: repaired.projectID) {
                if repaired.projectType != idProject.nameSv {
                    repaired.projectType = idProject.nameSv
                }
            } else if let projectName = repaired.projectType?.trimmedOrNil,
               let canonicalProject = canonicalProjectLookup[normalizedPersonLookupName(projectName)],
               canonicalProject != projectName {
                repaired.projectType = canonicalProject
            }
            repaired.coApplicants = repaired.coApplicants.map { contributor in
                canonicalAuthorLookup[normalizedPersonLookupName(contributor)] ?? contributor
            }
            repaired.refreshDerivedValues()
            if repaired != applications[index] {
                applications[index] = repaired
                didChange = true
            }
        }

        for index in publicationRecords.indices {
            var repaired = publicationRecords[index]
            repaired.authorNames = repaired.authorNames.map { authorName in
                canonicalAuthorLookup[normalizedPersonLookupName(authorName)] ?? authorName
            }
            if let idJournal = publicationJournal(id: repaired.journalID) {
                if repaired.journal != idJournal.name {
                    repaired.journal = idJournal.name
                }
            } else if let resolvedJournal = canonicalJournalLookup[Self.normalizedPublicationJournalLookupKey(repaired.journal)] {
                repaired.journal = resolvedJournal
            }
            if let idProject = project(id: repaired.projectID) {
                if repaired.projectName != idProject.nameSv {
                    repaired.projectName = idProject.nameSv
                }
            } else if let projectName = repaired.projectName?.trimmedOrNil,
               let canonicalProject = canonicalProjectLookup[normalizedPersonLookupName(projectName)] {
                repaired.projectName = canonicalProject
            }
            repaired.normalize()
            if repaired != publicationRecords[index] {
                publicationRecords[index] = repaired
                didChange = true
            }
        }

        for index in cvConferenceContributions.indices {
            var repaired = cvConferenceContributions[index]
            let canonicalPresentedBy = publicationAuthor(
                matchingPresentedName: repaired.presentedBy,
                includeNameVariants: false
            )?.name
            if let canonicalPresentedBy, canonicalPresentedBy != repaired.presentedBy {
                repaired.presentedBy = canonicalPresentedBy
            }
            repaired.contributorNames = repaired.contributorNames.map { contributor in
                publicationAuthor(
                    matchingPresentedName: contributor,
                    includeNameVariants: false
                )?.name ?? contributor
            }

            if let idProject = project(id: repaired.projectID) {
                let idProjectNameEn = idProject.nameEn.nonEmpty ?? idProject.nameSv
                if repaired.projectNameSv != idProject.nameSv || repaired.projectNameEn != idProjectNameEn {
                    repaired.projectNameSv = idProject.nameSv
                    repaired.projectNameEn = idProjectNameEn
                }
            } else if let projectName = repaired.projectName.nonEmpty,
               let canonicalProject = canonicalProjectLookup[normalizedPersonLookupName(projectName)] {
                repaired.projectNameSv = canonicalProject
                repaired.projectNameEn = canonicalProject
            }

            if let resolvedJournal = publicationJournal(id: repaired.journalID) ?? publicationJournal(named: repaired.journalName) {
                if repaired.journalID != resolvedJournal.id {
                    repaired.journalID = resolvedJournal.id
                }
                if repaired.journalName != resolvedJournal.name {
                    repaired.journalName = resolvedJournal.name
                }
            }

            synchronizedConferenceContributionAuthorIDs(&repaired)
            repaired.normalize()
            if repaired != cvConferenceContributions[index] {
                cvConferenceContributions[index] = repaired
                didChange = true
            }
        }

        for organizationIndex in organizations.indices {
            var congresses = organizations[organizationIndex].congresses
            for congressIndex in congresses.indices {
                synchronizedCongressParticipantAuthorIDs(&congresses[congressIndex])
            }
            congresses = persistedOrganizationCongresses(from: congresses)
            if congresses != organizations[organizationIndex].congresses {
                organizations[organizationIndex].congresses = congresses
                didChange = true
            }
        }

        for index in cvReviewEntries.indices {
            var repaired = cvReviewEntries[index]
            // "Alla kopplingar via id": the linked journal's name first.
            if repaired.journalName.trimmedOrNil != nil,
               let resolvedJournal = linkedJournal(of: repaired),
               repaired.journalName != resolvedJournal.name {
                repaired.journalName = resolvedJournal.name
            }
            repaired.normalize()
            if repaired != cvReviewEntries[index] {
                cvReviewEntries[index] = repaired
                didChange = true
            }
        }

        for index in teachingAssignments.indices {
            var repaired = teachingAssignments[index]
            if repaired.activityID == nil,
               let matched = teachingComponent(named: repaired.activityName) {
                repaired.activityID = matched.id
                repaired.activityName = matched.nameSv
            }
            repaired.normalize()
            if repaired != teachingAssignments[index] {
                teachingAssignments[index] = repaired
                didChange = true
            }
        }

        return didChange
    }

    @discardableResult
    func migrateRecordsIfNeeded(extractInlineReviewCertificates: Bool = true) -> Bool {
        var didChange = false
        didChange = ensureMetadataSchemaState() || didChange
        rebuildPublicationAuthorLookupCaches()
        didChange = ensureRelationalAuthorIDs() || didChange
        // F13b runs before the application pass below, which keeps the same
        // co-applicant ids in step, so that the change is seen and saved.
        didChange = !migratePersonReferencesToIDsForF13b().isEmpty || didChange
        for index in applications.indices {
            applications[index].refreshDerivedValues()
            applications[index] = synchronizedApplicationRelations(applications[index])
        }
        // Once, for records from before the step was tied to saving: it used
        // to run on every launch and every Undo and put back a "new funds
        // received" task the user had deleted. Saving an application that
        // becomes granted still adds it (save and autosave).
        didChange = runRound7MigrationOnce(
            key: "round14-new-funds-tasks-once",
            details: "\"New funds received\" project tasks are added once for granted applications; afterwards only when an application becomes granted, so a deleted task is not recreated."
        ) {
            ensureGrantedApplicationNewFundsReceivedProjectTasks()
        } || didChange
        for index in organizations.indices {
            let derivedCategory = derivedOrganizationCategory(
                city: organizations[index].city,
                country: organizations[index].country,
                fallback: organizations[index].category
            )
            if organizations[index].category != derivedCategory {
                organizations[index].category = derivedCategory
                didChange = true
            }
            let normalizedCongresses = normalizedOrganizationCongresses(organizations[index].congresses)
            if organizations[index].congresses != normalizedCongresses {
                organizations[index].congresses = normalizedCongresses
                didChange = true
            }
        }
        // User decision: the roles ticked on an organization are what count.
        // The app no longer removes "Employer" from organizations by name here.
        didChange = migrateHomeOrganizationSettingsIfNeeded() || didChange
            // Once: on every launch and Undo it put the user back on a
            // congress they had removed themselves from. Linking a trip or
            // stay to a congress in the calendar still marks attendance.
            didChange = runRound7MigrationOnce(
                key: "round14-congress-participation-once",
                details: "Congresses linked from calendar travel or stays are marked as attended once; afterwards only when the link is made in the calendar."
            ) {
                ensureCalendarLinkedRecordsMarkCongressParticipation()
            } || didChange
            didChange = ensureCongressPlanRowsMirroredInCalendar() || didChange
            didChange = removeCalendarOwnedCongressPlanningRows() || didChange
        refreshOptionListsFromApplications(preserveCustomLists: true)
        sortApplications()
        refreshTeachingState()
        refreshCVState()
        didChange = repairAttachmentStorageIfNeeded() || didChange
        didChange = !migrateTeachingCatalogForRound2c().isEmpty || didChange
        didChange = !migrateNameReferencesToIDsForF13().isEmpty || didChange
        didChange = runRound7OneTimeDataMigrations() || didChange
        didChange = runRound8OneTimeDataMigrations() || didChange
        didChange = runRound10OneTimeDataMigrations() || didChange
        didChange = runRound11OneTimeDataMigrations() || didChange
        didChange = normalizeConferenceContributionsForRound1() || didChange
        didChange = clearPlaceholderProjectNames() || didChange
        didChange = ensureManagedPublicationPDFAttachmentsStored() || didChange
        didChange = ensureManagedCVMediaAppearancePDFAttachmentsStored() || didChange
        didChange = ensureManagedCVConferenceContributionPDFAttachmentsStored() || didChange
        // Gated because the bootstrap corruption-recovery path migrates
        // BEFORE the attachment restore transaction; extracting there would
        // let the transaction wipe the freshly written files after the
        // records were persisted with the inline data cleared.
        if extractInlineReviewCertificates {
            didChange = ensureManagedCVReviewCertificatePDFsStored() || didChange
        }
        refreshPublicationRecords()
        return didChange
    }

    private func ensureGrantedApplicationNewFundsReceivedProjectTasks() -> Bool {
        var updatedProjects = projects
        var didChange = false

        for application in applications where application.isGranted {
            guard let nextProjects = projectsByApplyingNewFundsReceivedTasks(
                updatedProjects,
                application: application,
                previousApplication: application
            ) else {
                continue
            }
            updatedProjects = nextProjects
            didChange = true
        }

        guard didChange else { return false }
        projects = updatedProjects
        refreshProjectIndexesAndCaches()
        return true
    }

    private static func modernRecordID(_ rawID: String) -> String? {
        guard let trimmed = rawID.trimmedOrNil,
              let uuid = UUID(uuidString: trimmed) else {
            return nil
        }
        return uuid.uuidString
    }

    private func firstClassIDInventory() -> [String] {
        var ids: [String] = []
        ids.append(contentsOf: applications.map(\.id))
        ids.append(contentsOf: organizations.map(\.id))
        ids.append(contentsOf: projects.map(\.id))
        ids.append(contentsOf: publicationAuthors.map(\.id))
        ids.append(contentsOf: publicationJournals.map(\.id))
        ids.append(contentsOf: publicationRecords.map(\.id))
        ids.append(contentsOf: teachingCourses.map(\.id))
        ids.append(contentsOf: teachingComponents.map(\.id))
        ids.append(contentsOf: teachingFormats.map(\.id))
        ids.append(contentsOf: teachingAssignments.map(\.id))
        ids.append(contentsOf: doctoralCandidates.map(\.id))
        ids.append(contentsOf: cvConferenceContributions.map(\.id))
        ids.append(contentsOf: cvMediaAppearances.map(\.id))
        ids.append(contentsOf: cvReviewEntries.map(\.id))
        ids.append(contentsOf: cvOtherPublications.map(\.id))
        ids.append(contentsOf: (metadata.salarySources ?? []).map(\.id))
        ids.append(contentsOf: (metadata.salaryCoveragePeriods ?? []).map(\.id))
        ids.append(contentsOf: (metadata.calendarTravelRecords ?? []).map(\.id))
        ids.append(contentsOf: (metadata.calendarAccommodationRecords ?? []).map(\.id))
        ids.append(contentsOf: (metadata.calendarMeetingRecords ?? []).map(\.id))
        ids.append(contentsOf: (metadata.calendarVerticalNoteRecords ?? []).map(\.id))
        for organization in organizations {
            for congress in persistedOrganizationCongresses(from: organization.congresses) {
                ids.append(congress.id)
                ids.append(contentsOf: congress.travelFlights.map(\.id))
                ids.append(contentsOf: congress.travelHotels.map(\.id))
            }
        }
        return ids
    }

    private func modernFirstClassIDCount() -> Int {
        firstClassIDInventory().filter { Self.modernRecordID($0) != nil }.count
    }

    private func legacyFirstClassIDCount() -> Int {
        firstClassIDInventory().filter {
            $0.trimmedOrNil != nil && Self.modernRecordID($0) == nil
        }.count
    }

    private func ensureRelationalAuthorIDs() -> Bool {
        guard !publicationAuthors.isEmpty else { return false }
        var didChange = false

        for organizationIndex in organizations.indices {
            var congresses = organizations[organizationIndex].congresses
            for congressIndex in congresses.indices {
                let original = congresses[congressIndex]
                synchronizedCongressParticipantAuthorIDs(&congresses[congressIndex])
                if congresses[congressIndex] != original {
                    didChange = true
                }
            }
            let persisted = persistedOrganizationCongresses(from: congresses)
            if persisted != organizations[organizationIndex].congresses {
                organizations[organizationIndex].congresses = persisted
                didChange = true
            }
        }

        for index in cvConferenceContributions.indices {
            var contribution = cvConferenceContributions[index]
            let original = contribution
            synchronizedConferenceContributionAuthorIDs(&contribution)
            contribution.normalize()
            if contribution != original {
                cvConferenceContributions[index] = contribution
                didChange = true
            }
        }

        for index in cvMediaAppearances.indices {
            var appearance = cvMediaAppearances[index]
            let original = appearance
            synchronizedMediaAppearanceAuthorID(&appearance)
            appearance.normalize()
            if appearance != original {
                cvMediaAppearances[index] = appearance
                didChange = true
            }
        }

        return didChange
    }

    @discardableResult
    private func ensureMetadataSchemaState() -> Bool {
        var updated = metadata
        let original = updated
        let appliedAt = ISO8601DateFormatter().string(from: Date())
        var log = updated.migrationLog ?? []
        var existingKeys = Set(log.map(\.key))

        func appendMigration(_ key: String, _ details: String) {
            guard existingKeys.insert(key).inserted else { return }
            log.append(
                DataSchemaMigrationLogEntry(
                    id: key,
                    key: key,
                    appliedAt: appliedAt,
                    details: details
                )
            )
        }

        if (updated.schemaVersion ?? 0) < DataSourceMetadata.currentSchemaVersion {
            updated.schemaVersion = DataSourceMetadata.currentSchemaVersion
        }
        appendMigration(
            "schema-v1-document-store",
            "Initial document-based persistence layout."
        )
        appendMigration(
            "schema-v2-calendar-documents",
            "Calendar records are stored as separate SQLite documents with shared metadata for schema and maintenance state."
        )
        appendMigration(
            "schema-v3-congress-mirror",
            "Congresses are exported as top-level records and cross-checked against organization-linked congress data."
        )
        appendMigration(
            "schema-v4-relational-core",
            "Stable ID-based relation mirrors are exported for congresses, conference contributions, and calendar links."
        )
        appendMigration(
            "schema-v5-calendar-owned-congress-planning",
            "Calendar travel and accommodation records are the canonical source for congress travel planning; congress records keep participant and congress metadata only."
        )
        appendMigration(
            "schema-v6-first-class-congresses-and-settings",
            "Congresses and app settings are persisted as first-class top-level documents with metadata reserved for shared schema state."
        )
        appendMigration(
            "schema-v7-relational-sqlite-core",
            "SQLite stores first-class relational tables for core entities and ID-based relationships alongside canonical SQLite documents."
        )
        appendMigration(
            "schema-v8-relational-sqlite-indexes",
            "Relational SQLite tables are indexed for stable ID lookups and kept in sync during metadata and calendar writes."
        )
        appendMigration(
            "schema-v9-modern-first-class-ids",
            "First-class records use UUID identifiers, with legacy ID aliases retained for lookup and migration."
        )
        appendMigration(
            "schema-v10-canonical-uuid-case",
            "UUID identifiers and stored references are canonicalized to the same string form before relational SQLite indexes are rebuilt."
        )
        appendMigration(
            "schema-v11-sqlite-search-health-and-attachments",
            "SQLite adds materialized search rows, expanded relational indexes, stricter health checks, and attachment manifests for backup verification."
        )
        appendMigration(
            "schema-v12-central-tasks",
            "Tasks are migrated idempotently to one first-class collection with typed workspace links; legacy task arrays remain readable during the compatibility transition."
        )
        appendMigration(
            "schema-v13-managed-review-certificates",
            "Review certificate PDFs move from inline JSON data to managed files under Review Certificate PDFs; older builds open migrated databases read-only."
        )

        updated.migrationLog = log
        updated = Self.sanitizedMetadata(updated)
        guard updated != original else { return false }
        metadata = updated
        return true
    }

    @discardableResult
    private func ensureCalendarLinkedRecordsMarkCongressParticipation() -> Bool {
        var didChange = false

        func organizationIndex(for id: String) -> Int? {
            organizations.firstIndex(where: { $0.id == id })
        }

        for travel in calendarTravelRecords {
            guard let organizationID = travel.congressOrganizationID.trimmedOrNil,
                  let congressID = travel.congressID.trimmedOrNil,
                  let organizationIndex = organizationIndex(for: organizationID),
                  let congressIndex = organizations[organizationIndex].congresses.firstIndex(where: { $0.id == congressID }) else {
                continue
            }
            var congress = organizations[organizationIndex].congresses[congressIndex]
            let original = congress
            _ = markCongressAttendingForLinkedCalendarRecord(&congress)

            guard congress != original else { continue }
            organizations[organizationIndex].congresses[congressIndex] = congress
            organizations[organizationIndex].congresses = persistedOrganizationCongresses(from: organizations[organizationIndex].congresses)
            didChange = true
        }

        for accommodation in calendarAccommodationRecords {
            guard let organizationID = accommodation.congressOrganizationID.trimmedOrNil,
                  let congressID = accommodation.congressID.trimmedOrNil,
                  let organizationIndex = organizationIndex(for: organizationID),
                  let congressIndex = organizations[organizationIndex].congresses.firstIndex(where: { $0.id == congressID }) else {
                continue
            }
            var congress = organizations[organizationIndex].congresses[congressIndex]
            let original = congress
            _ = markCongressAttendingForLinkedCalendarRecord(&congress)

            guard congress != original else { continue }
            organizations[organizationIndex].congresses[congressIndex] = congress
            organizations[organizationIndex].congresses = persistedOrganizationCongresses(from: organizations[organizationIndex].congresses)
            didChange = true
        }

        return didChange
    }

