    func syncCalendarTravelWithCongressPlan(previous: CalendarTravelRecord?, current: CalendarTravelRecord) {
        var normalizedCurrent = current
        normalizedCurrent.normalize()

        guard let currentLink = congressPlanLink(for: normalizedCurrent) else { return }
        // Only when the trip is newly linked to this congress: saving the
        // same trip again must not put back a user who removed themselves.
        if let previousLink = congressPlanLink(for: previous),
           previousLink.organizationID == currentLink.organizationID,
           previousLink.congressID == currentLink.congressID {
            return
        }
        markCongressAsAttendingIfNeeded(
            organizationID: currentLink.organizationID,
            congressID: currentLink.congressID
        )
    }

    func removeCalendarTravelFromCongressPlan(_ travel: CalendarTravelRecord) {
        var normalized = travel
        normalized.normalize()
        guard congressPlanLink(for: normalized) != nil else { return }
        // Calendar travel records are the source of truth; removing or
        // unlinking the calendar record is enough for congress planning.
    }

    func markCongressAsAttendingIfNeeded(organizationID: String, congressID: String) {
        guard let organizationID = organizationID.trimmedOrNil,
              let congressID = congressID.trimmedOrNil,
              let organization = organization(id: organizationID) else { return }
        var congresses = organization.congresses
        guard let congressIndex = congresses.firstIndex(where: { $0.id == congressID }) else { return }
        guard markCongressAttendingForLinkedCalendarRecord(&congresses[congressIndex]) else { return }
        autosaveOrganization(
            id: organization.id,
            nameSv: organization.nameSv,
            nameEn: organization.nameEn,
            addressLine: organization.addressLine,
            postalCode: organization.postalCode,
            city: organization.city,
            country: organization.country,
            category: organization.category,
            roles: organization.roles,
            note: organization.note,
            websiteURL: organization.websiteURL,
            phoneNumber: organization.phoneNumber,
            organizationNumber: organization.organizationNumber,
            vatNumber: organization.vatNumber,
            employerContacts: organization.employerContacts,
            flag: organization.flag,
            membershipFrom: organization.membershipFrom,
            membershipTo: organization.membershipTo,
            congresses: persistedOrganizationCongresses(from: congresses),
            projectTasks: organization.projectTasks,
            salaryCalculator: organization.salaryCalculator
        )
    }

    private func congressPlanLink(for travel: CalendarTravelRecord?) -> (organizationID: String, congressID: String)? {
        guard let travel,
              let organizationID = travel.congressOrganizationID.trimmedOrNil,
              let congressID = travel.congressID.trimmedOrNil else {
            return nil
        }
        return (organizationID, congressID)
    }

    private func calendarTravelRecord(
        from flight: OrganizationCongressFlight,
        organizationID: String,
        congressID: String,
        preserving existing: CalendarTravelRecord? = nil
    ) -> CalendarTravelRecord? {
        var normalized = flight
        normalized.normalize()
        guard !normalized.isEmpty else { return nil }

        var record = CalendarTravelRecord(
            id: normalized.id,
            date: normalized.fromDate,
            arrivalDate: normalized.toDate,
            departureTime: normalized.fromTime,
            fromCity: normalized.fromCity,
            fromCountry: normalized.fromCountry,
            arrivalTime: normalized.toTime,
            toCity: normalized.toCity,
            toCountry: normalized.toCountry,
            mode: normalized.mode,
            congressOrganizationID: organizationID,
            congressID: congressID,
            reference: existing?.reference ?? ""
        )
        record.normalize()
        return record.isEmpty ? nil : record
    }

    private func calendarAccommodationRecord(
        from hotel: OrganizationCongressHotel,
        congress: OrganizationCongress,
        organizationID: String,
        preserving existing: CalendarAccommodationRecord? = nil
    ) -> CalendarAccommodationRecord? {
        var normalized = hotel
        normalized.normalize()
        guard !normalized.isEmpty else { return nil }

        var record = CalendarAccommodationRecord(
            id: normalized.id,
            hotelName: normalized.hotelName,
            checkInDate: normalized.fromDate,
            checkInTime: normalized.fromTime,
            checkOutDate: normalized.toDate,
            checkOutTime: normalized.toTime,
            city: congress.city,
            country: congress.country,
            congressOrganizationID: organizationID,
            congressID: congress.id,
            reference: existing?.reference ?? ""
        )
        record.normalize()
        return record.isEmpty ? nil : record
    }

    private func metadataByMirroringCongressPlanRowsIntoCalendar(
        _ sourceMetadata: DataSourceMetadata,
        organizations sourceOrganizations: [OrganizationRecord]
    ) -> (metadata: DataSourceMetadata, didChange: Bool) {
        var updated = sourceMetadata
        var didChange = false
        var travelRecords = (updated.calendarTravelRecords ?? []).map {
            var record = $0
            record.normalize()
            return record
        }
        .filter { !$0.isEmpty }
        var accommodationRecords = (updated.calendarAccommodationRecords ?? []).map {
            var record = $0
            record.normalize()
            return record
        }
        .filter { !$0.isEmpty }
        var travelIndexByID = Dictionary(firstWinsKeysWithValues: travelRecords.enumerated().map { ($0.element.id, $0.offset) })
        var accommodationIndexByID = Dictionary(firstWinsKeysWithValues: accommodationRecords.enumerated().map { ($0.element.id, $0.offset) })

        for organization in sourceOrganizations {
            for congress in persistedOrganizationCongresses(from: organization.congresses) {
                for flight in persistedOrganizationCongressFlights(from: congress.travelFlights) {
                    let existing = travelIndexByID[flight.id].map { travelRecords[$0] }
                    guard let mirrored = calendarTravelRecord(
                        from: flight,
                        organizationID: organization.id,
                        congressID: congress.id,
                        preserving: existing
                    ) else { continue }
                    if let index = travelIndexByID[mirrored.id] {
                        if travelRecords[index] != mirrored {
                            travelRecords[index] = mirrored
                            didChange = true
                        }
                    } else {
                        travelRecords.append(mirrored)
                        travelIndexByID[mirrored.id] = travelRecords.count - 1
                        didChange = true
                    }
                }

                for hotel in persistedOrganizationCongressHotels(from: congress.travelHotels) {
                    let existing = accommodationIndexByID[hotel.id].map { accommodationRecords[$0] }
                    guard let mirrored = calendarAccommodationRecord(
                        from: hotel,
                        congress: congress,
                        organizationID: organization.id,
                        preserving: existing
                    ) else { continue }
                    if let index = accommodationIndexByID[mirrored.id] {
                        if accommodationRecords[index] != mirrored {
                            accommodationRecords[index] = mirrored
                            didChange = true
                        }
                    } else {
                        accommodationRecords.append(mirrored)
                        accommodationIndexByID[mirrored.id] = accommodationRecords.count - 1
                        didChange = true
                    }
                }
            }
        }

        travelRecords.sort {
            let leftDate = DateParsers.isoDay.date(from: $0.date) ?? .distantFuture
            let rightDate = DateParsers.isoDay.date(from: $1.date) ?? .distantFuture
            if leftDate != rightDate {
                return leftDate < rightDate
            }
            if $0.departureTime != $1.departureTime {
                return $0.departureTime.localizedStandardCompare($1.departureTime) == .orderedAscending
            }
            return $0.id < $1.id
        }
        accommodationRecords.sort(by: calendarAccommodationSort)
        if updated.calendarTravelRecords != travelRecords {
            updated.calendarTravelRecords = travelRecords
            didChange = true
        }
        if updated.calendarAccommodationRecords != accommodationRecords {
            updated.calendarAccommodationRecords = accommodationRecords
            didChange = true
        }
        return (Self.sanitizedMetadata(updated), didChange)
    }

    @discardableResult
    private func ensureCongressPlanRowsMirroredInCalendar() -> Bool {
        let result = metadataByMirroringCongressPlanRowsIntoCalendar(metadata, organizations: organizations)
        guard result.didChange else { return false }
        metadata = result.metadata
        return true
    }

    @discardableResult
    private func markCongressAttendingForLinkedCalendarRecord(_ congress: inout OrganizationCongress) -> Bool {
        let original = congress
        if let currentUser = currentUserAuthor() {
            let currentUserNames = [currentUser.displayName, currentUser.name]
                .compactMap(\.trimmedOrNil)
            let existingKeys = Set(congress.participantNames.map(normalizedPersonLookupName).filter { !$0.isEmpty })
            if let displayName = currentUserNames.first,
               currentUserNames.map(normalizedPersonLookupName).allSatisfy({ !existingKeys.contains($0) }) {
                congress.participantNames.append(displayName)
            }
            if !congress.participantAuthorIDs.contains(currentUser.id) {
                congress.participantAuthorIDs.append(currentUser.id)
            }
        }
        congress.participantNames = Array(NSOrderedSet(array: congress.participantNames.compactMap(\.trimmedOrNil))) as? [String] ?? congress.participantNames.compactMap(\.trimmedOrNil)
        congress.participantAuthorIDs = Array(NSOrderedSet(array: congress.participantAuthorIDs.compactMap(\.trimmedOrNil))) as? [String] ?? congress.participantAuthorIDs.compactMap(\.trimmedOrNil)
        return congress != original
    }

    private func ensureManagedPublicationPDFAttachmentsStored() -> Bool {
