    private func sortApplications() {
        applications.sort {
            ($0.applicationDate ?? $0.closeDate ?? .distantPast) > ($1.applicationDate ?? $1.closeDate ?? .distantPast)
        }
    }

    private func refreshApplicationsState() {
        for index in applications.indices {
            applications[index].refreshDerivedValues()
            applications[index] = synchronizedApplicationRelations(applications[index])
        }
        refreshOptionListsFromApplications(preserveCustomLists: true)
        sortApplications()
        refreshPublicationIndexes(mode: .crossReferencesOnly, projectCacheBehavior: .markDirty)
        rebuildOrganizationRowSnapshots()
    }

    private func refreshApplicationsState(
        afterUpdating updated: GrantApplication,
        previous: GrantApplication,
        at index: Int
    ) {
        let plan = applicationRefreshPlan(afterUpdating: updated, previous: previous)
        appendPerformanceDiagnostic(
            "dirty-graph entity=application id=\(updated.id) optionLists=\(plan.refreshOptionLists ? "yes" : "no") crossrefs=\(plan.refreshPublicationIndexes ? "yes" : "no") projectCache=\(plan.markProjectViewCacheDirty ? "yes" : "no")"
        )
        applications[index].refreshDerivedValues()
        applications[index] = synchronizedApplicationRelations(applications[index])
        sortApplications()

        if plan.refreshOptionLists {
            refreshOptionListsFromApplications(preserveCustomLists: true)
        } else {
            refreshOrganizationLookupCaches()
            rebuildApplicationRowSnapshots()
            if plan.markProjectViewCacheDirty {
                markProjectViewCacheDirty()
            }
        }

        if plan.refreshPublicationIndexes {
            let projectCacheBehavior: ProjectCacheRefreshBehavior = plan.markProjectViewCacheDirty ? .markDirty : .skip
            if plan.refreshPublicationIndexesImmediately {
                refreshPublicationIndexesImmediately(
                    mode: .crossReferencesOnly,
                    projectCacheBehavior: projectCacheBehavior
                )
            } else {
                refreshPublicationIndexes(
                    mode: .crossReferencesOnly,
                    projectCacheBehavior: projectCacheBehavior
                )
            }
        }

        rebuildOrganizationRowSnapshots()
    }

    private func applicationRefreshPlan(
        afterUpdating updated: GrantApplication,
        previous: GrantApplication
    ) -> (
        refreshOptionLists: Bool,
        refreshPublicationIndexes: Bool,
        markProjectViewCacheDirty: Bool,
        refreshPublicationIndexesImmediately: Bool
    ) {
        let refreshOptionLists =
            applicationOptionListSignature(for: updated)
            != applicationOptionListSignature(for: previous)
        let refreshPublicationIndexes =
            applicationCrossReferenceSignature(for: updated)
            != applicationCrossReferenceSignature(for: previous)
        let markProjectViewCacheDirty =
            Self.projectViewRelevantSignature(for: updated)
            != Self.projectViewRelevantSignature(for: previous)
        let refreshPublicationIndexesImmediately =
            updated.isNotAppliedStatus != previous.isNotAppliedStatus

        return (
            refreshOptionLists: refreshOptionLists,
            refreshPublicationIndexes: refreshPublicationIndexes,
            markProjectViewCacheDirty: markProjectViewCacheDirty,
            refreshPublicationIndexesImmediately: refreshPublicationIndexesImmediately
        )
    }

    private func applicationOptionListSignature(for application: GrantApplication) -> Int {
        var hasher = Hasher()
        hasher.combine(application.organization.trimmedOrNil)
        hasher.combine(application.applicationManager?.trimmedOrNil)
        hasher.combine(application.projectType?.trimmedOrNil)
        return hasher.finalize()
    }

    private func applicationCrossReferenceSignature(for application: GrantApplication) -> Int {
        var hasher = Hasher()
        hasher.combine(application.resultLabel.trimmedOrNil)
        hasher.combine(application.organization.trimmedOrNil)
        hasher.combine(application.applicationManager?.trimmedOrNil)
        hasher.combine(application.projectType?.trimmedOrNil)
        // "Alla kopplingar via id": a changed link refreshes the indexes too.
        hasher.combine(application.organizationID?.trimmedOrNil)
        hasher.combine(application.applicationManagerID?.trimmedOrNil)
        hasher.combine(application.projectID?.trimmedOrNil)
        hasher.combine(application.grantedAmountValue ?? 0)
        let coApplicants = application.coApplicants
            .compactMap(\.trimmedOrNil)
            .sorted { $0.localizedStandardCompare($1) == .orderedAscending }
        hasher.combine(coApplicants)
        hasher.combine(application.coApplicantAuthorIDs.sorted())
        return hasher.finalize()
    }

    private func refreshOrganizationsState() {
        for index in applications.indices {
            applications[index].refreshDerivedValues()
            applications[index] = synchronizedApplicationRelations(applications[index])
        }
        sortApplications()
        managers = derivedManagers(from: organizations)
        refreshPublicationIndexes(mode: .crossReferencesOnly, projectCacheBehavior: .markDirty)
        rebuildOrganizationRowSnapshots()
        refreshTeachingCoursesOnly()
    }

    private func refreshOrganizationLookupCaches() {
        applicationByID = applications.reduce(into: [:]) { $0[$1.id] = $1 }
        organizationByID = organizations.reduce(into: [:]) { $0[$1.id] = $1 }
        organizationByName = organizations.reduce(into: [:]) { $0[$1.nameSv] = $1 }
        managerByID = managers.reduce(into: [:]) { $0[$1.id] = $1 }
        managerByName = managers.reduce(into: [:]) { $0[$1.nameSv] = $1 }

        var organizationApplicationIDs: [String: [String]] = [:]
        var managerApplicationIDs: [String: [String]] = [:]

        // "Alla kopplingar via id": filed under the organization the
        // application points to (its Swedish name), the written text only
        // for applications without a link.
        for application in applications {
            if let organizationName = linkedOrganizationKey(for: application) {
                organizationApplicationIDs[organizationName, default: []].append(application.id)
            }
            if let managerName = linkedManagerKey(for: application) {
                managerApplicationIDs[managerName, default: []].append(application.id)
            }
        }

        applicationIDsByOrganizationName = organizationApplicationIDs
        applicationIDsByManagerName = managerApplicationIDs
    }

    /// Fills a missing English term from the Swedish one ("Termin 6" becomes
    /// "Semester 6"). Names are never overwritten; the user's own English
    /// translations are stored with each course, component and format.
    private func fillMissingTeachingTermTranslations() {
        let termSettings = workflowDefaultSettings
        for index in teachingCourses.indices {
            let trimmedSwedishTerm = teachingCourses[index].termSv.trimmingCharacters(in: .whitespacesAndNewlines)
            if teachingCourses[index].termEn.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                if let translated = termSettings.translatedTeachingTerm(fromSwedish: trimmedSwedishTerm) {
                    teachingCourses[index].termEn = translated
                } else {
                    teachingCourses[index].termEn = teachingCourses[index].termSv
                }
            }
        }
    }

    private func simplifyTeachingAssignmentForCurrentModel(_ assignment: inout TeachingAssignment) {
        assignment.normalize()
        if assignment.activityID == nil,
           let matched = teachingComponent(named: assignment.activityName) {
            assignment.activityID = matched.id
            assignment.activityName = matched.nameSv
        } else if let matched = teachingComponent(id: assignment.activityID) {
            assignment.activityName = matched.nameSv
        }

        let context = teachingCourses.first(where: { $0.id == assignment.contextID })
        if assignment.programName.nonEmpty == nil {
            assignment.programName = context?.programSv.nonEmpty ?? context?.programEn ?? ""
        }

        if let matched = teachingComponent(for: assignment) {
            assignment.activityID = matched.id
            assignment.activityName = matched.nameSv
            if assignment.participantForm == nil {
                assignment.participantForm = matched.participantForm ?? effectiveTeachingParticipantForm(assignment)
            }
            if assignment.activityTypeName.nonEmpty == nil {
                assignment.activityTypeName = matched.activityTypeName.nonEmpty ?? effectiveTeachingActivityTypeName(assignment)
            }
        } else {
            if assignment.participantForm == nil {
                assignment.participantForm = effectiveTeachingParticipantForm(assignment)
            }
            if assignment.activityTypeName.isEmpty {
                assignment.activityTypeName = effectiveTeachingActivityTypeName(assignment)
            }
        }

        assignment.kind = inferredTeachingAssignmentKind(
            assignment: assignment,
            context: context
        )
        assignment.reportCategory = inferredTeachingReportCategory(
            assignment: assignment,
            context: context
        )
        synchronizeTeachingAssignmentReferences(&assignment)
        assignment.normalize()
    }

    private func refreshTeachingState() {
        fillMissingTeachingTermTranslations()
        for index in teachingCourses.indices {
            teachingCourses[index].normalize()
            teachingCourses[index] = synchronizedTeachingCourseRelations(teachingCourses[index])
        }
        applyProgrammeNamesToLinkedCourses()
        teachingCourses.sort {
            let left = $0.localizedName(language: language).nonEmpty ?? ""
            let right = $1.localizedName(language: language).nonEmpty ?? ""
            if left != right {
                return left.localizedStandardCompare(right) == .orderedAscending
            }
            return ($0.courseCode.nonEmpty ?? "").localizedStandardCompare($1.courseCode.nonEmpty ?? "") == .orderedAscending
        }

        for index in teachingComponents.indices {
            teachingComponents[index].normalize()
        }
        for index in teachingComponents.indices {
            if teachingComponents[index].activityTypeName.nonEmpty == nil || teachingComponents[index].participantForm == nil {
                let name = teachingComponents[index].name
                let matchingAssignments = teachingAssignments.filter { $0.activityName == name || $0.componentName == name }
                if teachingComponents[index].activityTypeName.nonEmpty == nil {
                    let inferredType = matchingAssignments
                        .compactMap { $0.activityTypeName.nonEmpty }
                        .mostCommonLocalizedValue()
                    teachingComponents[index].activityTypeName = inferredType ?? ""
                }
                if teachingComponents[index].participantForm == nil {
                    teachingComponents[index].participantForm = matchingAssignments
                        .compactMap(\.participantForm)
                        .mostCommonTeachingCategory()
                        ?? matchingAssignments
                        .compactMap { assignment in
                            let activityType = assignment.activityTypeName
                            return teachingFormats.first(where: {
                                $0.nameSv == activityType || $0.nameEn == activityType || $0.name == activityType
                            })?.category
                        }
                        .mostCommonTeachingCategory()
                }
            }
        }
        for index in teachingFormats.indices {
            teachingFormats[index].normalize()
        }
        teachingFormats.sort { localizedTeachingFormatName($0.name).localizedStandardCompare(localizedTeachingFormatName($1.name)) == .orderedAscending }

        for index in teachingComponents.indices {
            teachingComponents[index] = synchronizedTeachingComponentRelations(teachingComponents[index])
        }
        teachingComponents.sort { $0.name.localizedStandardCompare($1.name) == .orderedAscending }

        for index in teachingAssignments.indices {
            simplifyTeachingAssignmentForCurrentModel(&teachingAssignments[index])
            synchronizedTeachingAssignmentAuthorID(&teachingAssignments[index])
        }
        teachingAssignments.sort { lhs, rhs in
            let leftDate = DateParsers.isoDay.date(from: teachingAssignmentFirstDate(lhs)) ?? .distantPast
            let rightDate = DateParsers.isoDay.date(from: teachingAssignmentFirstDate(rhs)) ?? .distantPast
            if leftDate != rightDate {
                return leftDate < rightDate
            }
            let leftName = teachingCourses.first(where: { $0.id == lhs.contextID })?.name ?? ""
            let rightName = teachingCourses.first(where: { $0.id == rhs.contextID })?.name ?? ""
            return leftName.localizedStandardCompare(rightName) == .orderedAscending
        }
        refreshDoctoralCandidatesOnly()
    }

