    func persist(
        _ set: PersistenceSet,
        includeBackup: Bool = true,
        preEncodedStates: [PersistedDocumentState]? = nil
    ) throws {
        flushPendingPersistenceIfNeeded()
        try requireSupportedStorageSchema()
        synchronousPersistCount &+= 1
        let startedAt = Date()
        persistenceStatus.isSaving = true
        defer { persistenceStatus.isSaving = false }
        try Self.ensureStorageDirectory()
        let encodeStartedAt = CFAbsoluteTimeGetCurrent()
        // performUndoableChange already encoded the post-change state for
        // its no-op check; re-using those bytes removes one of the three
        // whole-collection encodes every edit action used to pay.
        let documents: [EncodedPersistenceDocument]
        if let preEncodedStates {
            documents = preEncodedStates.map {
                EncodedPersistenceDocument(storageKey: $0.storageKey, data: $0.data)
            }
        } else {
            documents = try encodedPersistenceDocuments(for: set)
        }
        let encodeDuration = (CFAbsoluteTimeGetCurrent() - encodeStartedAt) * 1000
        let changedDocuments = documents.filter { persistedDocumentCache[$0.storageKey] != $0.data }
        let writeStartedAt = CFAbsoluteTimeGetCurrent()
        if !changedDocuments.isEmpty {
            try writePersistedDocumentStates(
                changedDocuments.map { PersistedDocumentState(storageKey: $0.storageKey, data: $0.data) }
            )
        }
        let writeDuration = (CFAbsoluteTimeGetCurrent() - writeStartedAt) * 1000
        let backupStartedAt = CFAbsoluteTimeGetCurrent()
        if includeBackup, !changedDocuments.isEmpty {
            enqueuePeriodicBackupSnapshotIfNeeded(now: startedAt)
        }
        let backupDuration = (CFAbsoluteTimeGetCurrent() - backupStartedAt) * 1000
        persistenceStatus.lastSavedAt = startedAt
        // Footprint-export: läsbar kopia av data och bilagor till footprint_export.
        exportToFootprintExportAfterWrite(changedDocuments.map { (key: $0.storageKey, data: $0.data) })
        appendPerformanceDiagnostic(
            String(
                format: "persist scope=%@ changed=%ld encode_ms=%.2f write_ms=%.2f backup_ms=%.2f total_ms=%.2f",
                persistenceScopeLabel(for: set),
                changedDocuments.count,
                encodeDuration,
                writeDuration,
                includeBackup ? backupDuration : 0,
                (Date().timeIntervalSince(startedAt) * 1000)
            )
        )
    }

    private func persistenceScopeLabel(for set: PersistenceSet) -> String {
        var labels: [String] = []
        if set.contains(.applications) { labels.append("applications") }
        if set.contains(.metadata) { labels.append("metadata") }
        if set.contains(.appSettings) { labels.append("appSettings") }
        if set.contains(.organizations) { labels.append("organizations") }
        if set.contains(.projects) { labels.append("projects") }
        if set.contains(.teachingCourses) { labels.append("teachingCourses") }
        if set.contains(.teachingComponents) { labels.append("teachingComponents") }
        if set.contains(.teachingFormats) { labels.append("teachingFormats") }
        if set.contains(.teachingAssignments) { labels.append("teachingAssignments") }
        if set.contains(.doctoralCandidates) { labels.append("doctoralCandidates") }
        if set.contains(.cvPersonalResume) { labels.append("cvPersonalResume") }
        if set.contains(.cvConferenceContributions) { labels.append("cvConferenceContributions") }
        if set.contains(.cvMediaAppearances) { labels.append("cvMediaAppearances") }
        if set.contains(.cvReviewEntries) { labels.append("cvReviewEntries") }
        if set.contains(.cvOtherPublications) { labels.append("cvOtherPublications") }
        if set.contains(.publicationAuthors) { labels.append("publicationAuthors") }
        if set.contains(.publicationJournals) { labels.append("publicationJournals") }
        if set.contains(.publicationRecords) { labels.append("publicationRecords") }
        if set.contains(.calendarTravelRecords) { labels.append("calendarTravelRecords") }
        if set.contains(.calendarAccommodationRecords) { labels.append("calendarAccommodationRecords") }
        if set.contains(.calendarMeetingRecords) { labels.append("calendarMeetingRecords") }
        if set.contains(.calendarVerticalNoteRecords) { labels.append("calendarVerticalNoteRecords") }
        if set.contains(.congresses) { labels.append("congresses") }
        if set.contains(.relationalCore) { labels.append("relationalCore") }
        return labels.isEmpty ? "none" : labels.joined(separator: "+")
    }

    func persistenceSet(for scope: ChangeRefreshScope) -> PersistenceSet {
        switch scope {
        case .all:
            return .allCoreData
        case .applications:
            return [.applications, .organizations, .projects]
        case .organizations:
            return [.applications, .organizations, .teachingCourses, .teachingComponents]
        case .organizationTree:
            return [.applications, .organizations, .teachingCourses, .teachingComponents, .publicationAuthors]
        case .projects:
            return [.applications, .projects, .publicationRecords, .cvConferenceContributions, .doctoralCandidates]
        case .teaching:
            return [.teachingCourses, .teachingComponents, .teachingFormats, .teachingAssignments, .doctoralCandidates]
        case .cv:
            return [.cvPersonalResume, .cvConferenceContributions, .cvMediaAppearances, .cvReviewEntries, .cvOtherPublications]
        case .publications:
            return [.applications, .projects, .publicationAuthors, .publicationJournals, .publicationRecords]
        case .publicationAuthors:
            return [.publicationAuthors]
        case .publicationAuthorsAndCurrentUser:
            return [.publicationAuthors, .metadata]
        case .publicationAuthorRename:
            return [.publicationAuthors, .publicationRecords, .applications, .projects, .teachingAssignments, .doctoralCandidates, .cvConferenceContributions]
        case .publicationJournals:
            return [.publicationJournals, .publicationRecords]
        case .publicationJournalReferences:
            return [.publicationJournals, .publicationRecords, .cvConferenceContributions, .cvReviewEntries]
        case .publicationRecords:
            return [.publicationRecords]
        case .calendar:
            return [
                .metadata,
                .calendarTravelRecords,
                .calendarAccommodationRecords,
                .calendarMeetingRecords,
                .organizations,
                .projects,
                .publicationRecords,
            ]
        case .calendarRecords:
            return [
                .metadata,
                .calendarTravelRecords,
                .calendarAccommodationRecords,
                .calendarMeetingRecords,
            ]
        }
    }

    func persistScope(_ scope: ChangeRefreshScope) throws {
        try persist(persistenceSet(for: scope))
    }

    private func persistMetadataOnly() throws {
        try persist([.metadata], includeBackup: true)
    }

    @discardableResult
    private func performUndoableChange(
        actionName: String,
        successMessage: String,
        failureMessage: String,
        scope: ChangeRefreshScope = .all,
        change: () throws -> Void
    ) -> Bool {
        let startedAt = CFAbsoluteTimeGetCurrent()
        defer {
            appendPerformanceDiagnosticIfSlow(
                { String(format: "undoable-change action=%@ total_ms=%.2f", actionName, $0) },
                startedAt: startedAt
            )
        }
        let affectedSet = persistenceSet(for: scope)
        // Round 13: a queued metadata write (calendar, tasks, settings) is
        // taken into this change when the change saves metadata; otherwise
        // the change would save the older metadata and its own metadata
        // edits (for example re-pointed travel after a merge) would be lost.
        if affectedSet.contains(.metadata) {
            promotePendingMetadataSnapshotIfNeeded()
        }
        let previous = currentSnapshot()
        let previousStates = try? persistedBaselineDocumentStates(for: affectedSet)
        let outerArchiveEnvelopeIDs = archiveEnvelopeIDsAddedInCurrentChange
        archiveEnvelopeIDsAddedInCurrentChange = []
        defer {
            let addedHere = archiveEnvelopeIDsAddedInCurrentChange ?? []
            archiveEnvelopeIDsAddedInCurrentChange = outerArchiveEnvelopeIDs.map { $0 + addedHere }
        }
        do {
            try change()
            refreshState(for: scope)
            let currentStates = try? currentPersistedDocumentStates(for: affectedSet)
            if let previousStates, let currentStates, currentStates == previousStates {
                appendPerformanceDiagnostic(
                    "undoable-noop action=\(actionName) scope=\(persistenceScopeLabel(for: affectedSet)) reason=unchanged-states"
                )
                loadError = nil
                return true
            }
            try persist(affectedSet, preEncodedStates: currentStates)
            let archivedHere = Set(archiveEnvelopeIDsAddedInCurrentChange ?? [])
            if outerArchiveEnvelopeIDs == nil, !archivedHere.isEmpty,
               let archivedNow = try? loadArchivedRecords() {
                // Undo brings the record back and takes it out of the
                // archive again; Redo puts it back in both.
                registerArchiveUndo(
                    snapshot: previous,
                    archivedRecords: archivedNow.filter { !archivedHere.contains($0.id) },
                    actionName: actionName
                )
            } else {
                registerUndo(snapshot: previous, actionName: actionName)
            }
            appendRecentRecordRevision(actionName: actionName)
            notice = StoreNotice(message: successMessage, tone: .success)
            loadError = nil
            scheduleSaveValidation()
            return true
        } catch {
            restoreSnapshotWithoutUndo(previous)
            // The change did not happen, so neither did its archive entries.
            let archivedHere = Set(archiveEnvelopeIDsAddedInCurrentChange ?? [])
            if !archivedHere.isEmpty, let archivedNow = try? loadArchivedRecords() {
                try? saveArchivedRecords(archivedNow.filter { !archivedHere.contains($0.id) })
                archiveEnvelopeIDsAddedInCurrentChange = []
            }
            persistenceStatus.isSaving = false
            loadError = error.localizedDescription
            notice = StoreNotice(message: failureMessage, tone: .error)
            return false
        }
    }

    /// Deletes calendar-owned and calendar-linked records as one canonical
    /// store transaction. A single snapshot undo restores every affected
    /// collection, including legacy host task lists.
    @discardableResult
    func deleteCalendarEvent(source: CalendarWorkspaceEventSource) -> Bool {
        switch source {
        case .meeting, .travel, .accommodation, .teachingTask:
            // Meetings, travel, accommodation and central tasks live entirely
            // inside metadata; see deleteCalendarOwnedRecord for why they no
            // longer go through the whole-store transaction below.
            return deleteCalendarOwnedRecord(source: source)
        default:
            break
        }
        // A just-edited metadata task may still be queued. Promote it before
        // taking the undo baseline so the queued pre-delete snapshot cannot
        // make this transaction look like a no-op or overwrite the deletion.
        promotePendingMetadataSnapshotIfNeeded()
        let recordExists: Bool
        switch source {
        case let .teachingTask(id):
            recordExists = taskItems.contains { $0.id == id }
                || teachingWorkspaceTasks.contains { $0.id == id }
        case let .organizationTask(ownerID, taskID):
            recordExists = organizations
                .first(where: { $0.id == ownerID })?
                .projectTasks
                .contains(where: { $0.id == taskID }) == true
        case let .projectTask(ownerID, taskID):
            recordExists = projects
                .first(where: { $0.id == ownerID })?
                .projectTasks
                .contains(where: { $0.id == taskID }) == true
        case let .publicationTask(ownerID, taskID):
            recordExists = publicationRecords
                .first(where: { $0.id == ownerID })?
                .publicationTasks
                .contains(where: { $0.id == taskID }) == true
        default:
            recordExists = false
        }
        guard recordExists else { return false }

        // Task deletions may mutate a host collection (organizations,
        // projects, publications), so they keep the calendar-wide scope.
        // Meetings, travel and accommodation returned above.
        let refreshScope: ChangeRefreshScope = .calendar

        return performUndoableChange(
            actionName: language.text("Delete calendar event", "Ta bort kalenderhändelse"),
            successMessage: language.text(
                "Deleted the calendar event. You can undo this action.",
                "Kalenderhändelsen togs bort. Du kan ångra åtgärden."
            ),
            failureMessage: language.text(
                "Could not delete the calendar event.",
                "Kunde inte ta bort kalenderhändelsen."
            ),
            scope: refreshScope
        ) {
            switch source {
            case let .teachingTask(id):
                var updated = metadata
                if taskItems.contains(where: { $0.id == id }) {
                    updated.taskItems = taskItems.filter { $0.id != id }
                } else {
                    updated.teachingWorkspaceTasks = teachingWorkspaceTasks.filter { $0.id != id }
                }
                metadata = Self.sanitizedMetadata(updated)
            case let .organizationTask(ownerID, taskID):
                guard let index = organizations.firstIndex(where: { $0.id == ownerID }) else { return }
                organizations[index].projectTasks.removeAll { $0.id == taskID }
            case let .projectTask(ownerID, taskID):
                guard let index = projects.firstIndex(where: { $0.id == ownerID }) else { return }
                projects[index].projectTasks.removeAll { $0.id == taskID }
            case let .publicationTask(ownerID, taskID):
                guard let index = publicationRecords.firstIndex(where: { $0.id == ownerID }) else { return }
                publicationRecords[index].publicationTasks.removeAll { $0.id == taskID }
            default:
                return
            }
        }
    }

    /// Deletes one meeting, travel, accommodation or central task record.
    ///
    /// These records live only inside metadata, so the deletion is a metadata
    /// change and takes the same path as editing one in the calendar: the
    /// record disappears from memory at once, the undo step holds only the
    /// previous metadata, and the write happens on the metadata queue, off the
    /// main thread, where only the calendar documents and the calendar part of
    /// the relational tables are rewritten.
    ///
    /// Previously each deletion went through performUndoableChange, which on
    /// the main thread took a whole-store undo snapshot, encoded metadata,
    /// app settings, the three calendar documents and both relational
    /// snapshots (rebuilt from every application, project, author and
    /// publication), parsed those documents again for the write guards,
    /// decoded metadata and the relational snapshot once more in the SQLite
    /// write and finally scheduled the F19 data-quality check. Undo restored
    /// the whole store and rewrote every document. With ~1,800 meetings that
    /// made every deletion visibly slow.
    ///
    /// The F19 check is not scheduled: removing a record cannot introduce a
    /// new wrong value, and the next real edit compares against the same
    /// baseline as before.
    private func deleteCalendarOwnedRecord(source: CalendarWorkspaceEventSource) -> Bool {
        let startedAt = CFAbsoluteTimeGetCurrent()
        defer {
            appendPerformanceDiagnosticIfSlow(
                { String(format: "calendar-delete total_ms=%.2f", $0) },
                startedAt: startedAt
            )
        }
        // A just-edited task may still be queued; promote it so the undo
        // baseline is the task as the user last saw it.
        promotePendingMetadataSnapshotIfNeeded()
        let previous = editableMetadataSnapshot
        var updated = previous
        // F44: the record the calendar can update on its own after the
        // deletion; a legacy teaching task is part of every source rebuild.
        var singleRecordSource: CalendarWorkspaceEventSource? = source
        switch source {
        case let .meeting(id):
            let records = previous.calendarMeetingRecords ?? []
            guard records.contains(where: { $0.id == id }) else { return false }
            updated.calendarMeetingRecords = records.filter { $0.id != id }
        case let .travel(id):
            let records = previous.calendarTravelRecords ?? []
            guard records.contains(where: { $0.id == id }) else { return false }
            updated.calendarTravelRecords = records.filter { $0.id != id }
        case let .accommodation(id):
            let records = previous.calendarAccommodationRecords ?? []
            guard records.contains(where: { $0.id == id }) else { return false }
            updated.calendarAccommodationRecords = records.filter { $0.id != id }
        case let .teachingTask(id):
            let central = previous.taskItems ?? []
            let teaching = previous.teachingWorkspaceTasks ?? []
            if central.contains(where: { $0.id == id }) {
                updated.taskItems = central.filter { $0.id != id }
            } else if teaching.contains(where: { $0.id == id }) {
                updated.teachingWorkspaceTasks = teaching.filter { $0.id != id }
                singleRecordSource = nil
            } else {
                return false
            }
        default:
            return false
        }
        updated = Self.sanitizedMetadata(updated)
        guard updated != previous else { return false }

        // The same preconditions persistMetadataSilently checks, tested first
        // so a refused write never leaves the record removed in memory only.
        let failureMessage = language.text(
            "Could not delete the calendar event.",
            "Kunde inte ta bort kalenderhändelsen."
        )
        do {
            try requireSupportedStorageSchema()
        } catch {
            loadError = error.localizedDescription
            notice = StoreNotice(message: failureMessage, tone: .error)
            return false
        }
        guard sqliteStore != nil else {
            loadError = language.text(
                "SQLite storage is required for metadata persistence.",
                "SQLite-lagring krävs för att spara metadata."
            )
            notice = StoreNotice(message: failureMessage, tone: .error)
            return false
        }

        let actionName = language.text("Delete calendar event", "Ta bort kalenderhändelse")
        registerMetadataUndo(
            previousMetadata: previous,
            currentMetadata: updated,
            actionName: actionName
        )
        let beforePersist = CFAbsoluteTimeGetCurrent()
        persistMetadataSilently(updated)
        let afterPersist = CFAbsoluteTimeGetCurrent()
        // F44: tell the calendar which record went, so it updates that one
        // record instead of rebuilding every source (the metadata change
        // alone only says "something changed").
        if let singleRecordSource {
            publishCalendarContentUpdate(source: singleRecordSource, pulses: false)
        }
        appendCalendarChangeDiagnosticIfSlow(
            phase: "delete",
            startedAt: startedAt,
            details: String(
                format: "prepare_ms=%.2f persist_ms=%.2f publish_update_ms=%.2f",
                (beforePersist - startedAt) * 1000,
                (afterPersist - beforePersist) * 1000,
                (CFAbsoluteTimeGetCurrent() - afterPersist) * 1000
            )
        )
        appendRecentRecordRevision(actionName: actionName)
        loadError = nil
        notice = StoreNotice(
            message: language.text(
                "Deleted the calendar event. You can undo this action.",
                "Kalenderhändelsen togs bort. Du kan ångra åtgärden."
            ),
            tone: .success
        )
        return true
    }

    private func applicationIndex(for application: GrantApplication, selectionID: String?) -> Int? {
        if let selectionID,
           selectionID.hasPrefix(Self.applicationSelectionScopePrefix),
           let scopedIndex = applications.firstIndex(where: { Self.scopedApplicationSelectionID(for: $0) == selectionID }) {
            return scopedIndex
        }
        return applications.firstIndex(where: { $0.id == application.id })
    }

    func refreshState(for scope: ChangeRefreshScope) {
        switch scope {
        case .all:
            migrateRecordsIfNeeded()
        case .applications:
            refreshApplicationsState()
        case .organizations:
            refreshOrganizationsState()
        case .projects:
            refreshProjectIndexesAndCaches()
            refreshPublicationRecordsOnly()
            refreshDoctoralCandidatesOnly()
        case .teaching:
            refreshTeachingState()
        case .cv:
            refreshCVState()
        case .publications:
            refreshPublicationRecords()
        case .publicationAuthors, .publicationAuthorsAndCurrentUser:
            refreshPublicationAuthorsOnly()
        case .publicationAuthorRename:
            refreshPublicationRecords()
        case .publicationJournals:
            refreshPublicationJournalsState(projectCacheBehavior: .skip)
        case .publicationJournalReferences:
            refreshPublicationJournalsState(projectCacheBehavior: .skip)
            refreshCVState()
        case .publicationRecords:
            refreshPublicationRecordsOnly()
        case .calendar:
            refreshOrganizationsState()
            refreshProjectIndexesAndCaches()
            refreshPublicationRecordsOnly()
        case .calendarRecords:
            // The metadata didSet already bumped calendarContentGeneration and
            // dropped the linked-event, normalized-meeting and known-category
            // caches. Nothing outside metadata reads these records, so there is
            // no other derived state to rebuild.
            break
        case .organizationTree:
            refreshOrganizationsState()
            refreshPublicationAuthorsOnly()
        }
    }

    func confirmDeletionImpactWarning() {
        let action = pendingDeletionAction
        pendingDeletionAction = nil
        deletionImpactWarning = nil
        action?()
    }

    func cancelDeletionImpactWarning() {
        pendingDeletionAction = nil
        deletionImpactWarning = nil
    }

    /// Round 11 (user decision 2026-09-30): the Delete key never removes a
    /// record straight away. It asks first, and a locked record is left
    /// alone. `delete` is the same removal as the record's own delete
    /// button, so a record linked elsewhere still gets that warning too.
    func requestKeyboardDeletion(recordTitle: String, isLocked: Bool, delete: @escaping () -> Void) {
        guard !isLocked else {
            notice = StoreNotice(
                message: language.text(
                    "The record is locked and was not deleted. Unlock it first.",
                    "Posten är låst och togs inte bort. Lås upp den först."
                ),
                tone: .info
            )
            return
        }
        let title = recordTitle.trimmedOrNil ?? language.text("the selected record", "den valda posten")
        requestImpactConfirmation(
            title: language.text("Delete \u{201C}\(title)\u{201D}?", "Ta bort \u{201D}\(title)\u{201D}?"),
            message: language.text(
                "You can undo with Cmd+Z.",
                "Du kan ångra med Cmd+Z."
            ),
            details: [],
            confirmTitle: language.text("Delete", "Ta bort")
        ) { [weak self] in
            // After this dialog has closed, so a warning about links can open.
            self?.confirmedKeyboardDeletion = delete
            DispatchQueue.main.async { [weak self] in
                let action = self?.confirmedKeyboardDeletion
                self?.confirmedKeyboardDeletion = nil
                action?()
            }
        }
    }

    /// Presents the app-wide impact confirmation dialog with a custom
    /// message and confirm title; `action` runs only after the user
    /// confirms. Used for operations that rewrite protected records.
    func requestImpactConfirmation(
        title: String,
        message: String,
        details: [String],
        confirmTitle: String,
        action: @escaping () -> Void
    ) {
        deletionImpactWarning = DeletionImpactWarning(
            title: title,
            message: message,
            details: details,
            confirmTitle: confirmTitle
        )
        pendingDeletionAction = action
    }

    private func requestDeletionConfirmationIfNeeded(
        title: String,
        details: [String],
        action: @escaping () -> Void
    ) -> Bool {
        let filteredDetails = details.filter { !$0.isEmpty }
        guard !filteredDetails.isEmpty else { return false }
        deletionImpactWarning = DeletionImpactWarning(
            title: title,
            message: language.text(
                "This object is linked elsewhere. Deleting it will also clear those links.",
                "Det här objektet är kopplat på andra ställen. Om du tar bort det kommer även de kopplingarna att rensas."
            ),
            details: filteredDetails,
            confirmTitle: language.text("Delete anyway", "Ta bort ändå")
        )
        pendingDeletionAction = action
        return true
    }

    private func deletionImpactLine(_ count: Int, english: String, swedish: String) -> String? {
        guard count > 0 else { return nil }
        return "\(count) " + language.text(english, swedish)
    }

    @discardableResult
    private func performUndoableMetadataChange(
        actionName: String,
        successMessage: String,
        failureMessage: String,
        change: () throws -> Void
    ) -> Bool {
        promotePendingMetadataSnapshotIfNeeded()
        let previousMetadata = metadata
        do {
            try change()
            guard metadata != previousMetadata else {
                appendPerformanceDiagnostic("metadata-undoable-noop action=\(actionName) reason=unchanged-metadata")
                loadError = nil
                return false
            }
            try persistMetadataOnly()
            registerMetadataUndo(previousMetadata: previousMetadata, actionName: actionName)
            appendRecentRecordRevision(
                actionName: actionName,
                title: language.text("App settings and workspace state", "Appinställningar och arbetsytans läge"),
                subtitle: language.text("Metadata", "Metadata")
            )
            notice = StoreNotice(message: successMessage, tone: .success)
            loadError = nil
            return true
        } catch {
            metadata = previousMetadata
            persistenceStatus.isSaving = false
            loadError = error.localizedDescription
            notice = StoreNotice(message: failureMessage, tone: .error)
            return false
        }
    }

