    private func appendRecentRecordRevision(
        actionName: String,
        destination: AppRoute.Destination? = nil,
        recordID: String? = nil,
        title overrideTitle: String? = nil,
        subtitle overrideSubtitle: String? = nil
    ) {
        let resolvedDestination = destination ?? route?.destination ?? inferredDestinationFromLastSelectedTab()
        let resolvedRecordID = recordID ?? route?.recordID ?? resolvedDestination.flatMap(lastSelectedRecordID(for:))
        let resolvedTitle = overrideTitle ?? resolvedDestination.flatMap { destination in
            recordTitle(for: destination, id: resolvedRecordID)
        } ?? actionName
        let resolvedSubtitle = overrideSubtitle ?? resolvedDestination.map(localizedDestinationName(_:)) ?? ""
        let entry = RecordRevisionEntry(
            id: UUID().uuidString,
            timestamp: Date(),
            actionName: actionName,
            title: resolvedTitle,
            subtitle: resolvedSubtitle,
            destination: resolvedDestination,
            recordID: resolvedRecordID
        )
        recentRecordRevisionsCache.insert(entry, at: 0)
        if recentRecordRevisionsCache.count > Self.maxRecentRecordRevisions {
            recentRecordRevisionsCache.removeLast(recentRecordRevisionsCache.count - Self.maxRecentRecordRevisions)
        }
    }

