    private func recordTitle(for destination: AppRoute.Destination, id: String?) -> String? {
        guard let id else { return nil }
        switch destination {
        case .applications:
            return application(id: id).map { displayTitle(for: $0, language: language) }
        case .congresses:
            return congressTitle(for: id)
        case .cv:
            if let conference = cvConferenceContributions.first(where: { $0.id == id }) {
                return conference.localizedTitle(language: language).nonEmpty ?? conference.displayTitle
            }
            if let media = cvMediaAppearances.first(where: { $0.id == id }) {
                return media.localizedTitle(language: language).nonEmpty ?? media.displayTitle
            }
            if let review = cvReviewEntries.first(where: { $0.id == id }) {
                return review.displayTitle
            }
            if let other = cvOtherPublications.first(where: { $0.id == id }) {
                return other.localizedTitle(language: language).nonEmpty ?? other.displayTitle
            }
            return nil
        case .expertAssignments:
            let reviewID = id.hasPrefix("\(CVItemKind.review.rawValue):")
                ? String(id.dropFirst("\(CVItemKind.review.rawValue):".count))
                : id
            return cvReviewEntries.first(where: { $0.id == reviewID })?.displayTitle
        case .publications:
            return publication(id: id)?.title.nonEmpty ?? publication(id: id)?.number
        case .projects:
            return project(id: id).map(localizedOptionDisplayName)
        case .teaching:
            if let assignment = teachingAssignments.first(where: { $0.id == id }) {
                return assignment.activityName.nonEmpty ?? assignment.comment.nonEmpty ?? id
            }
            if let course = teachingCourses.first(where: { $0.id == id }) {
                return course.localizedName(language: language)
            }
            return nil
        case .doctoralCandidates:
            return doctoralCandidates.first(where: { $0.id == id })?.candidateName.nonEmpty
        case .organizations:
            return organization(id: id).map(localizedOptionDisplayName)
        case .people:
            return publicationAuthor(id: id)?.displayName
        case .journals:
            return publicationJournal(id: id)?.name
        }
    }

    private func congressTitle(for routeRecordID: String) -> String? {
        let token = routeRecordID.hasPrefix("organizationCongress:")
            ? String(routeRecordID.dropFirst("organizationCongress:".count))
            : routeRecordID
        let parts = token.split(separator: ":", maxSplits: 1).map(String.init)
        guard parts.count == 2 else { return nil }
        let organizationID = parts[0]
        let congressID = parts[1]
        return organizations
            .first(where: { $0.id == organizationID })?
            .congresses
            .first(where: { $0.id == congressID })?
            .title
            .nonEmpty
    }

    private func registerDocumentUndo(
        undoStates: [PersistedDocumentState],
        redoStates: [PersistedDocumentState],
        actionName: String,
        revealTarget: UndoRevealTarget?
    ) {
        guard !undoStates.isEmpty else { return }
        // Undo/redo closures retain full encoded documents; step N's redo
        // payload is byte-identical to step N+1's undo payload, and unchanged
        // documents repeat across steps. Interning identical payloads shares
        // one buffer instead of retaining up to 2 × 20 × document size.
        let undoStates = internedUndoStates(undoStates)
        let redoStates = internedUndoStates(redoStates)
        registerUndoStep(actionName: actionName) {
            undoManager.registerUndo(withTarget: self) { target in
                target.restoreDocumentStates(undoStates, redoStates: redoStates, actionName: actionName, revealTarget: revealTarget)
            }
        }
    }

    private static let undoStateInternPoolLimit = 128

    private func internedUndoStates(_ states: [PersistedDocumentState]) -> [PersistedDocumentState] {
        states.map { state in
            if let canonical = undoStateInternPool[state.data] {
                return PersistedDocumentState(storageKey: state.storageKey, data: canonical)
            }
            undoStateInternPool[state.data] = state.data
            undoStateInternOrder.append(state.data)
            if undoStateInternOrder.count > Self.undoStateInternPoolLimit {
                let evicted = undoStateInternOrder.removeFirst()
                undoStateInternPool[evicted] = nil
            }
            return state
        }
    }

    private func registerUndoStep(actionName: String, registration: () -> Void) {
        undoManager.beginUndoGrouping()
        registration()
        undoManager.setActionName(actionName)
        undoManager.endUndoGrouping()
        undoStateGeneration += 1
    }

    private func undoRedoNoticeMessage(actionName: String) -> String {
        let action = undoRedoNoticeActionDescription(actionName)
        if undoManager.isRedoing {
            return language.text("Redid \(action).", "Gjorde om \(action).")
        }
        return language.text("Undid \(action).", "Ångrade \(action).")
    }

    private func undoRedoFailureMessage(actionName: String) -> String {
        let action = undoRedoNoticeActionDescription(actionName)
        if undoManager.isRedoing {
            return language.text("Could not redo \(action).", "Kunde inte göra om \(action).")
        }
        return language.text("Could not undo \(action).", "Kunde inte ångra \(action).")
    }

    private func undoRedoNoticeActionDescription(_ actionName: String) -> String {
        let fallback = language.text("the latest change", "senaste ändringen")
        guard let trimmed = actionName.trimmedOrNil else { return fallback }
        guard language == .swedish else { return trimmed }

        let replacements: [(prefix: String, replacement: String)] = [
            ("Redigera ", "redigering av "),
            ("Lägg till ", "tillägg av "),
            ("Ta bort ", "borttagning av "),
            ("Ta bort ", "borttagning av "),
            ("Arkivera ", "arkivering av "),
            ("Återställ ", "återställning av "),
            ("Byt ", "ändring av ")
        ]
        for replacement in replacements where trimmed.hasPrefix(replacement.prefix) {
            let suffix = String(trimmed.dropFirst(replacement.prefix.count))
            return replacement.replacement + suffix
        }
        guard let first = trimmed.first else { return fallback }
        return first.lowercased() + trimmed.dropFirst()
    }

    private func revealUndoRedoTarget(_ target: UndoRevealTarget?, actionName: String) {
        guard let target else { return }
        undoRevealRequest = UndoRevealRequest(
            target: target,
            actionName: actionName,
            isRedo: undoManager.isRedoing
        )
        switch target.destination {
        case let .route(route):
            self.route = route
        case let .calendar(dayString, eventSource):
            guard let date = DateParsers.isoDay.date(from: dayString) else {
                revealCalendarWorkspace()
                return
            }
            revealCalendarWorkspace(on: date, eventSource: eventSource)
        }
    }

    private func currentRouteUndoRevealTarget() -> UndoRevealTarget? {
        route.map { UndoRevealTarget(destination: .route($0)) }
    }

    private func lastSelectedUndoRevealTarget() -> UndoRevealTarget? {
        guard let destination = inferredDestinationFromLastSelectedTab(),
              let recordID = lastSelectedRecordID(for: destination) else { return nil }
        return UndoRevealTarget(destination: .route(AppRoute(recordID: recordID, destination: destination)))
    }

    private func snapshotUndoRevealTarget(from current: Snapshot, to target: Snapshot, actionName: String) -> UndoRevealTarget? {
        if actionName.localizedCaseInsensitiveContains("congress")
            || actionName.localizedCaseInsensitiveContains("kongress"),
           let congressTarget = changedOrganizationCongressTarget(from: current.organizations, to: target.organizations) {
            return congressTarget
        }
        if let change = changedRecordChange(from: current.applications, to: target.applications) {
            return UndoRevealTarget(
                destination: .route(AppRoute(recordID: change.id, destination: .applications)),
                fieldKey: changedApplicationFieldKey(from: change.current, to: change.target)
            )
        }
        if let change = changedRecordChange(from: current.projects, to: target.projects) {
            return UndoRevealTarget(
                destination: .route(AppRoute(recordID: change.id, destination: .projects)),
                fieldKey: changedProjectFieldKey(from: change.current, to: change.target)
            )
        }
        if let id = changedRecordID(from: current.teachingAssignments, to: target.teachingAssignments) {
            return UndoRevealTarget(destination: .route(AppRoute(recordID: id, destination: .teaching)))
        }
        if let id = changedRecordID(from: current.doctoralCandidates, to: target.doctoralCandidates) {
            return UndoRevealTarget(destination: .route(AppRoute(recordID: id, destination: .doctoralCandidates)))
        }
        if let change = changedRecordChange(from: current.publicationRecords, to: target.publicationRecords) {
            return UndoRevealTarget(
                destination: .route(AppRoute(recordID: change.id, destination: .publications)),
                fieldKey: changedPublicationFieldKey(from: change.current, to: change.target)
            )
        }
        if let change = changedRecordChange(from: current.publicationAuthors, to: target.publicationAuthors) {
            return UndoRevealTarget(
                destination: .route(AppRoute(recordID: change.id, destination: .people)),
                fieldKey: changedPublicationAuthorFieldKey(from: change.current, to: change.target)
            )
        }
        if let id = changedRecordID(from: current.publicationJournals, to: target.publicationJournals) {
            return UndoRevealTarget(destination: .route(AppRoute(recordID: id, destination: .journals)))
        }
        if let id = changedRecordID(from: current.organizations, to: target.organizations) {
            return UndoRevealTarget(destination: .route(AppRoute(recordID: id, destination: .organizations)))
        }
        if let id = changedRecordID(from: current.cvConferenceContributions, to: target.cvConferenceContributions) {
            return UndoRevealTarget(destination: .route(AppRoute(recordID: "conferenceContribution:\(id)", destination: .cv)))
        }
        if let id = changedRecordID(from: current.cvMediaAppearances, to: target.cvMediaAppearances) {
            return UndoRevealTarget(destination: .route(AppRoute(recordID: "mediaAppearance:\(id)", destination: .cv)))
        }
        if let id = changedRecordID(from: current.cvReviewEntries, to: target.cvReviewEntries) {
            return UndoRevealTarget(destination: .route(AppRoute(recordID: "review:\(id)", destination: .expertAssignments)))
        }
        if let id = changedRecordID(from: current.cvOtherPublications, to: target.cvOtherPublications) {
            return UndoRevealTarget(destination: .route(AppRoute(recordID: "otherPublication:\(id)", destination: .cv)))
        }
        return metadataUndoRevealTarget(from: current.metadata, to: target.metadata)
    }

    private func documentUndoRevealTarget(
        previousStates: [PersistedDocumentState],
        currentStates: [PersistedDocumentState],
        actionName: String
    ) -> UndoRevealTarget? {
        let previous = documentStateDataByKey(previousStates)
        let current = documentStateDataByKey(currentStates)

        if actionName.localizedCaseInsensitiveContains("congress")
            || actionName.localizedCaseInsensitiveContains("kongress"),
           let currentOrganizations = decodedDocumentRecords([OrganizationRecord].self, key: "organizations", from: current),
           let previousOrganizations = decodedDocumentRecords([OrganizationRecord].self, key: "organizations", from: previous),
           let congressTarget = changedOrganizationCongressTarget(from: currentOrganizations, to: previousOrganizations) {
            return congressTarget
        }
        if let change = changedDocumentRecordChange(GrantApplication.self, key: "applications", current: current, target: previous) {
            return UndoRevealTarget(
                destination: .route(AppRoute(recordID: change.id, destination: .applications)),
                fieldKey: changedApplicationFieldKey(from: change.current, to: change.target)
            )
        }
        if let change = changedDocumentRecordChange(ProjectRecord.self, key: "projects", current: current, target: previous) {
            return UndoRevealTarget(
                destination: .route(AppRoute(recordID: change.id, destination: .projects)),
                fieldKey: changedProjectFieldKey(from: change.current, to: change.target)
            )
        }
        if let id = changedDocumentRecordID(TeachingAssignment.self, key: "teaching_assignments", current: current, target: previous) {
            return UndoRevealTarget(destination: .route(AppRoute(recordID: id, destination: .teaching)))
        }
        if let id = changedDocumentRecordID(DoctoralCandidateRecord.self, key: "doctoral_candidates", current: current, target: previous) {
            return UndoRevealTarget(destination: .route(AppRoute(recordID: id, destination: .doctoralCandidates)))
        }
        if let change = changedDocumentRecordChange(PublicationRecord.self, key: "publication_records", current: current, target: previous) {
            return UndoRevealTarget(
                destination: .route(AppRoute(recordID: change.id, destination: .publications)),
                fieldKey: changedPublicationFieldKey(from: change.current, to: change.target)
            )
        }
        if let change = changedDocumentRecordChange(PublicationAuthor.self, key: "publication_authors", current: current, target: previous) {
            return UndoRevealTarget(
                destination: .route(AppRoute(recordID: change.id, destination: .people)),
                fieldKey: changedPublicationAuthorFieldKey(from: change.current, to: change.target)
            )
        }
        if let id = changedDocumentRecordID(PublicationJournal.self, key: "publication_journals", current: current, target: previous) {
            return UndoRevealTarget(destination: .route(AppRoute(recordID: id, destination: .journals)))
        }
        if let id = changedDocumentRecordID(OrganizationRecord.self, key: "organizations", current: current, target: previous) {
            return UndoRevealTarget(destination: .route(AppRoute(recordID: id, destination: .organizations)))
        }
        if let id = changedDocumentRecordID(CVConferenceContribution.self, key: "cv_conference_contributions", current: current, target: previous) {
            return UndoRevealTarget(destination: .route(AppRoute(recordID: "conferenceContribution:\(id)", destination: .cv)))
        }
        if let id = changedDocumentRecordID(CVMediaAppearance.self, key: "cv_media_appearances", current: current, target: previous) {
            return UndoRevealTarget(destination: .route(AppRoute(recordID: "mediaAppearance:\(id)", destination: .cv)))
        }
        if let id = changedDocumentRecordID(CVReviewEntry.self, key: "cv_review_entries", current: current, target: previous) {
            return UndoRevealTarget(destination: .route(AppRoute(recordID: "review:\(id)", destination: .expertAssignments)))
        }
        if let id = changedDocumentRecordID(CVOtherPublicationEntry.self, key: "cv_other_publications", current: current, target: previous) {
            return UndoRevealTarget(destination: .route(AppRoute(recordID: "otherPublication:\(id)", destination: .cv)))
        }
        if let change = changedDocumentRecordChange(CalendarMeetingRecord.self, key: "calendar_meeting_records", current: current, target: previous) {
            let record = change.target ?? change.current
            return calendarUndoRevealTarget(dayString: record?.date, source: .meeting(change.id))
        }
        if let change = changedDocumentRecordChange(CalendarTravelRecord.self, key: "calendar_travel_records", current: current, target: previous) {
            let record = change.target ?? change.current
            return calendarUndoRevealTarget(dayString: record?.date.nonEmpty ?? record?.arrivalDate, source: .travel(change.id))
        }
        if let change = changedDocumentRecordChange(CalendarAccommodationRecord.self, key: "calendar_accommodation_records", current: current, target: previous) {
            let record = change.target ?? change.current
            return calendarUndoRevealTarget(dayString: record?.checkInDate.nonEmpty ?? record?.checkOutDate, source: .accommodation(change.id))
        }
        if let currentMetadata = decodedDocument(DataSourceMetadata.self, key: "metadata", from: current),
           let previousMetadata = decodedDocument(DataSourceMetadata.self, key: "metadata", from: previous),
           let metadataTarget = metadataUndoRevealTarget(from: currentMetadata, to: previousMetadata) {
            return metadataTarget
        }
        return nil
    }

    private func metadataUndoRevealTarget(from current: DataSourceMetadata, to target: DataSourceMetadata) -> UndoRevealTarget? {
        // Equal lists have no single changed record; checking that first
        // skips building two ~1,800-entry dictionaries for every settings
        // or hidden-warning change that does not touch the calendar.
        if current.calendarMeetingRecords != target.calendarMeetingRecords,
           let change = changedRecordChange(from: current.calendarMeetingRecords ?? [], to: target.calendarMeetingRecords ?? []) {
            let record = change.target ?? change.current
            return calendarUndoRevealTarget(dayString: record?.date, source: .meeting(change.id))
        }
        if let change = changedRecordChange(from: current.calendarTravelRecords ?? [], to: target.calendarTravelRecords ?? []) {
            let record = change.target ?? change.current
            return calendarUndoRevealTarget(dayString: record?.date.nonEmpty ?? record?.arrivalDate, source: .travel(change.id))
        }
        if let change = changedRecordChange(from: current.calendarAccommodationRecords ?? [], to: target.calendarAccommodationRecords ?? []) {
            let record = change.target ?? change.current
            return calendarUndoRevealTarget(dayString: record?.checkInDate.nonEmpty ?? record?.checkOutDate, source: .accommodation(change.id))
        }
        if let change = changedRecordChange(from: current.teachingWorkspaceTasks ?? [], to: target.teachingWorkspaceTasks ?? []) {
            let record = change.target ?? change.current
            return calendarUndoRevealTarget(dayString: record?.deadline, source: .teachingTask(taskID: change.id))
        }
        return nil
    }

    private func changedDocumentRecordID<Record: Identifiable & Codable & Equatable>(
        _ type: Record.Type,
        key: String,
        current: [String: Data],
        target: [String: Data]
    ) -> String? where Record.ID == String {
        changedDocumentRecordChange(type, key: key, current: current, target: target)?.id
    }

    private func changedDocumentRecordChange<Record: Identifiable & Codable & Equatable>(
        _ type: Record.Type,
        key: String,
        current: [String: Data],
        target: [String: Data]
    ) -> (id: String, current: Record?, target: Record?)? where Record.ID == String {
        guard let currentRecords = decodedDocumentRecords([Record].self, key: key, from: current),
              let targetRecords = decodedDocumentRecords([Record].self, key: key, from: target) else {
            return nil
        }
        return changedRecordChange(from: currentRecords, to: targetRecords)
    }

    private func decodedDocumentRecords<Record: Decodable>(
        _ type: [Record].Type,
        key: String,
        from states: [String: Data]
    ) -> [Record]? {
        decodedDocument(type, key: key, from: states)
    }

    private func decodedDocument<Document: Decodable>(
        _ type: Document.Type,
        key: String,
        from states: [String: Data]
    ) -> Document? {
        guard let data = states[key] else { return nil }
        return try? JSONDecoder().decode(type, from: data)
    }

    private func documentStateDataByKey(_ states: [PersistedDocumentState]) -> [String: Data] {
        var result: [String: Data] = [:]
        for state in states {
            result[state.storageKey] = state.data
        }
        return result
    }

    private func calendarUndoRevealTarget(dayString: String?, source: CalendarWorkspaceEventSource) -> UndoRevealTarget? {
        guard let dayString = dayString?.trimmedOrNil else { return nil }
        return UndoRevealTarget(destination: .calendar(dayString: dayString, eventSource: source))
    }

    private func changedOrganizationCongressTarget(from current: [OrganizationRecord], to target: [OrganizationRecord]) -> UndoRevealTarget? {
        let currentByID = recordsByID(current)
        let targetByID = recordsByID(target)
        let organizationIDs = Set(currentByID.keys).union(targetByID.keys)

        for organizationID in organizationIDs.sorted() {
            let currentCongresses = currentByID[organizationID]?.congresses ?? []
            let targetCongresses = targetByID[organizationID]?.congresses ?? []
            if let change = changedRecordChange(from: currentCongresses, to: targetCongresses) {
                return UndoRevealTarget(
                    destination: .route(
                        AppRoute(
                            recordID: "organizationCongress:\(organizationID):\(change.id)",
                            destination: .congresses
                        )
                    ),
                    fieldKey: changedOrganizationCongressFieldKey(from: change.current, to: change.target)
                )
            }
        }
        return nil
    }

    private func changedOrganizationCongressFieldKey(
        from current: OrganizationCongress?,
        to target: OrganizationCongress?
    ) -> String? {
        guard let current, let target else { return nil }
        if current.title != target.title { return "title" }
        if current.from != target.from || current.fromUncertain != target.fromUncertain { return "from" }
        if current.to != target.to || current.toUncertain != target.toUncertain { return "to" }
        if current.abstractSubmissionDeadline != target.abstractSubmissionDeadline
            || current.abstractSubmissionDeadlineUncertain != target.abstractSubmissionDeadlineUncertain {
            return "abstractSubmissionDeadline"
        }
        if current.lateAbstractSubmissionDeadline != target.lateAbstractSubmissionDeadline
            || current.lateAbstractSubmissionDeadlineUncertain != target.lateAbstractSubmissionDeadlineUncertain {
            return "lateAbstractSubmissionDeadline"
        }
        if current.venue != target.venue { return "venue" }
        if current.city != target.city { return "city" }
        if current.country != target.country { return "country" }
        if current.link != target.link { return "link" }
        if current.participantNames != target.participantNames
            || current.participantAuthorIDs != target.participantAuthorIDs {
            return "participants"
        }
        if current.fundingApplicationIDs != target.fundingApplicationIDs
            || current.congressFeeSEK != target.congressFeeSEK {
            return "funding"
        }
        if current.travelFlights != target.travelFlights
            || current.travelHotels != target.travelHotels
            || current.hotelName != target.hotelName
            || current.hotelFrom != target.hotelFrom
            || current.hotelFromTime != target.hotelFromTime
            || current.hotelTo != target.hotelTo
            || current.hotelToTime != target.hotelToTime {
            return "travel"
        }
        if current.tasks != target.tasks { return "tasks" }
        if current.isHiddenOnMap != target.isHiddenOnMap { return "map" }
        return nil
    }

