    private func changedRecordID<Record: Identifiable & Equatable>(
        from current: [Record],
        to target: [Record]
    ) -> String? where Record.ID == String {
        changedRecordChange(from: current, to: target)?.id
    }

    private func changedRecordChange<Record: Identifiable & Equatable>(
        from current: [Record],
        to target: [Record]
    ) -> (id: String, current: Record?, target: Record?)? where Record.ID == String {
        let currentByID = recordsByID(current)
        let targetByID = recordsByID(target)
        let changed = Set(currentByID.keys)
            .union(targetByID.keys)
            .filter { currentByID[$0] != targetByID[$0] }
            .sorted()
        guard changed.count == 1, let id = changed.first else { return nil }
        return (id, currentByID[id], targetByID[id])
    }

    private func recordsByID<Record: Identifiable>(_ records: [Record]) -> [String: Record] where Record.ID == String {
        var result: [String: Record] = [:]
        for record in records {
            result[record.id] = record
        }
        return result
    }

    private func restoreDocumentStates(
        _ undoStates: [PersistedDocumentState],
        redoStates: [PersistedDocumentState],
        actionName: String,
        revealTarget: UndoRevealTarget?
    ) {
        let startedAt = CFAbsoluteTimeGetCurrent()
        do {
            try applyPersistedDocumentStatesToMemory(undoStates)
            queueDeferredPersistence(undoStates, scopeLabel: "undo-redo", force: true)
            registerDocumentUndo(undoStates: redoStates, redoStates: undoStates, actionName: actionName, revealTarget: revealTarget)
            notice = StoreNotice(message: undoRedoNoticeMessage(actionName: actionName), tone: .info)
            revealUndoRedoTarget(revealTarget, actionName: actionName)
            loadError = nil
            appendPerformanceDiagnosticIfSlow(
                { duration in
                    String(format: "undo-restore action=%@ documents=%ld apply_and_reveal_ms=%.2f", actionName, undoStates.count, duration)
                },
                startedAt: startedAt,
                thresholdMs: 8
            )
        } catch {
            try? applyPersistedDocumentStatesToMemory(redoStates)
            queueDeferredPersistence(redoStates, scopeLabel: "undo-redo-rollback", force: true)
            loadError = error.localizedDescription
            notice = StoreNotice(message: undoRedoFailureMessage(actionName: actionName), tone: .error)
        }
    }

    private func registerAutosaveUndo(
        actionName: String,
        previousStates: [PersistedDocumentState],
        for set: PersistenceSet
    ) {
        guard let currentStates = try? currentPersistedDocumentStates(for: set),
              currentStates != previousStates else {
            return
        }
        registerAutosaveUndo(
            actionName: actionName,
            previousStates: previousStates,
            currentStates: currentStates
        )
    }

    private func registerAutosaveUndo(
        actionName: String,
        previousStates: [PersistedDocumentState],
        currentStates: [PersistedDocumentState]
    ) {
        guard currentStates != previousStates else { return }
        registerDocumentUndo(
            undoStates: previousStates,
            redoStates: currentStates,
            actionName: actionName,
            revealTarget: autosaveUndoRevealTarget(
                actionName: actionName,
                previousStates: previousStates,
                currentStates: currentStates
            )
        )
        appendRecentRecordRevision(actionName: actionName)
    }

    private func autosaveUndoRevealTarget(
        actionName: String,
        previousStates: [PersistedDocumentState],
        currentStates: [PersistedDocumentState]
    ) -> UndoRevealTarget? {
        let routeTarget = currentRouteUndoRevealTarget()
        let documentTarget = documentUndoRevealTarget(
            previousStates: previousStates,
            currentStates: currentStates,
            actionName: actionName
        )
        if actionNameNeedsDocumentUndoReveal(actionName) {
            return documentTarget
                ?? routeTarget
                ?? lastSelectedUndoRevealTarget()
        }
        if let documentTarget {
            return documentTarget
        }
        return routeTarget ?? lastSelectedUndoRevealTarget()
    }

    private func actionNameNeedsDocumentUndoReveal(_ actionName: String) -> Bool {
        let lowercased = actionName.lowercased()
        return lowercased.contains("congress")
            || lowercased.contains("kongress")
            || lowercased.contains("calendar")
            || lowercased.contains("kalender")
    }

    private func clearAutosaveError() {
        if let message = lastAutosaveErrorMessage, loadError == message {
            loadError = nil
        }
        lastAutosaveErrorMessage = nil
    }

    private func enqueueAutosavePersistence(
        _ affectedSet: PersistenceSet,
        actionName: String,
        previousStates: [PersistedDocumentState]
    ) throws {
        try requireSupportedStorageSchema()
        let currentStates = try currentPersistedDocumentStates(for: affectedSet)
        let scopeLabel = persistenceScopeLabel(for: affectedSet)
        guard currentStates != previousStates else {
            appendPerformanceDiagnostic("autosave-noop scope=\(scopeLabel) reason=unchanged-states")
            clearAutosaveError()
            return
        }
        registerAutosaveUndo(
            actionName: actionName,
            previousStates: previousStates,
            currentStates: currentStates
        )
        queueDeferredPersistence(currentStates, scopeLabel: scopeLabel)
        clearAutosaveError()
        scheduleSaveValidation()
    }

    func registerUndo(snapshot: Snapshot, actionName: String, revealTarget: UndoRevealTarget? = nil) {
        let resolvedRevealTarget = revealTarget
            ?? snapshotUndoRevealTarget(from: currentSnapshot(), to: snapshot, actionName: actionName)
            ?? currentRouteUndoRevealTarget()
            ?? lastSelectedUndoRevealTarget()
        registerUndoStep(actionName: actionName) {
            undoManager.registerUndo(withTarget: self) { target in
                target.restoreSnapshot(snapshot, actionName: actionName, revealTarget: resolvedRevealTarget)
            }
        }
    }

    func registerArchiveUndo(snapshot: Snapshot, archivedRecords: [ArchivedRecordEnvelope], actionName: String, revealTarget: UndoRevealTarget? = nil) {
        let resolvedRevealTarget = revealTarget
            ?? snapshotUndoRevealTarget(from: currentSnapshot(), to: snapshot, actionName: actionName)
            ?? currentRouteUndoRevealTarget()
            ?? lastSelectedUndoRevealTarget()
        registerUndoStep(actionName: actionName) {
            undoManager.registerUndo(withTarget: self) { target in
                target.restoreSnapshotAndArchivedRecords(snapshot, archivedRecords: archivedRecords, actionName: actionName, revealTarget: resolvedRevealTarget)
            }
        }
    }

    private func registerMetadataUndo(
        previousMetadata: DataSourceMetadata,
        currentMetadata: DataSourceMetadata? = nil,
        actionName: String,
        revealTarget: UndoRevealTarget? = nil
    ) {
        let resolvedCurrentMetadata = currentMetadata ?? editableMetadataSnapshot
        let resolvedRevealTarget = revealTarget
            ?? metadataUndoRevealTarget(from: resolvedCurrentMetadata, to: previousMetadata)
            ?? currentRouteUndoRevealTarget()
            ?? lastSelectedUndoRevealTarget()
        registerUndoStep(actionName: actionName) {
            undoManager.registerUndo(withTarget: self) { target in
                target.restoreMetadata(previousMetadata, actionName: actionName, revealTarget: resolvedRevealTarget)
            }
        }
    }

    private func restoreSnapshot(_ snapshot: Snapshot, actionName: String, revealTarget: UndoRevealTarget?) {
        let current = currentSnapshot()
        restoreSnapshotWithoutUndo(snapshot)
        migrateRecordsIfNeeded()

        do {
            try persistAll()
            registerUndo(snapshot: current, actionName: actionName, revealTarget: revealTarget)
            notice = StoreNotice(message: undoRedoNoticeMessage(actionName: actionName), tone: .info)
            revealUndoRedoTarget(revealTarget, actionName: actionName)
            loadError = nil
        } catch {
            restoreSnapshotWithoutUndo(current)
            loadError = error.localizedDescription
            notice = StoreNotice(message: undoRedoFailureMessage(actionName: actionName), tone: .error)
        }
    }

    private func restoreMetadata(_ previousMetadata: DataSourceMetadata, actionName: String, revealTarget: UndoRevealTarget?) {
        promotePendingMetadataSnapshotIfNeeded()
        let currentMetadata = metadata
        lastSelectedTabOverride = nil
        lastSelectionOverrides.removeAll()
        metadata = previousMetadata

        do {
            try persistMetadataOnly()
            registerMetadataUndo(previousMetadata: currentMetadata, actionName: actionName, revealTarget: revealTarget)
            notice = StoreNotice(message: undoRedoNoticeMessage(actionName: actionName), tone: .info)
            revealUndoRedoTarget(revealTarget, actionName: actionName)
            loadError = nil
        } catch {
            metadata = currentMetadata
            loadError = error.localizedDescription
            notice = StoreNotice(message: undoRedoFailureMessage(actionName: actionName), tone: .error)
        }
    }

    private func restoreSnapshotAndArchivedRecords(_ snapshot: Snapshot, archivedRecords: [ArchivedRecordEnvelope], actionName: String, revealTarget: UndoRevealTarget?) {
        let current = currentSnapshot()
        let currentArchived: [ArchivedRecordEnvelope]
        do {
            currentArchived = try loadArchivedRecords()
        } catch {
            loadError = error.localizedDescription
            notice = StoreNotice(message: undoRedoFailureMessage(actionName: actionName), tone: .error)
            return
        }
        restoreSnapshotWithoutUndo(snapshot)
        migrateRecordsIfNeeded()

        do {
            // The archive is written first. If it fails, nothing has been
            // saved yet and the rollback below matches the disk. The other
            // way round, a failed archive write left the database with the
            // undone state while the screen showed the old one.
            try saveArchivedRecords(archivedRecords)
            try persist(.allCoreData, includeBackup: false)
            enqueuePeriodicBackupSnapshotIfNeeded(now: Date())
            registerArchiveUndo(snapshot: current, archivedRecords: currentArchived, actionName: actionName, revealTarget: revealTarget)
            notice = StoreNotice(message: undoRedoNoticeMessage(actionName: actionName), tone: .info)
            revealUndoRedoTarget(revealTarget, actionName: actionName)
            loadError = nil
        } catch {
            restoreSnapshotWithoutUndo(current)
            let primaryError = error
            handlePersistenceRollback(
                primaryError: primaryError,
                context: "Undo/redo"
            ) {
                try saveArchivedRecords(currentArchived)
            }
            notice = StoreNotice(message: undoRedoFailureMessage(actionName: actionName), tone: .error)
        }
    }

    func restoreSnapshotWithoutUndo(_ snapshot: Snapshot) {
        // A queued metadata write (a calendar or settings edit) is cancelled
        // below. Its content is part of the snapshot, so it is written again
        // at the end; before, a failed save elsewhere silently lost it.
        let droppedQueuedMetadataWrite = pendingMetadataSnapshot != nil
        pendingMetadataPersistenceWorkItem?.cancel()
        pendingMetadataPersistenceWorkItem = nil
        drainMetadataPersistenceQueue()
        if pendingMetadataSnapshot != nil {
            forgetMetadataQueueDocumentCache()
        }
        pendingMetadataSnapshot = nil
        pendingMetadataPersistenceInvalidatesStorageDiagnostics = false
        pendingMetadataPersistenceGeneration += 1
        pendingSelectionReturn = nil
        lastSelectedTabOverride = nil
        lastSelectionOverrides.removeAll()
        route = nil
        applications = snapshot.applications
        metadata = Self.sanitizedMetadata(snapshot.metadata)
        organizations = snapshot.organizations
        managers = derivedManagers(from: snapshot.organizations)
        projects = snapshot.projects
        teachingCourses = snapshot.teachingCourses
        teachingComponents = snapshot.teachingComponents
        teachingFormats = snapshot.teachingFormats
        teachingAssignments = snapshot.teachingAssignments
        doctoralCandidates = snapshot.doctoralCandidates
        cvPersonalResume = snapshot.cvPersonalResume
        cvConferenceContributions = snapshot.cvConferenceContributions
        cvMediaAppearances = snapshot.cvMediaAppearances
        cvReviewEntries = snapshot.cvReviewEntries
        cvOtherPublications = snapshot.cvOtherPublications
        publicationAuthors = snapshot.publicationAuthors
        publicationJournals = snapshot.publicationJournals
        publicationRecords = snapshot.publicationRecords
        pendingEmptyCVConferenceContributionIDs.formIntersection(Set(cvConferenceContributions.map(\.id)))
        pendingEmptyCVMediaAppearanceIDs.formIntersection(Set(cvMediaAppearances.map(\.id)))
        pendingEmptyCVReviewEntryIDs.formIntersection(Set(cvReviewEntries.map(\.id)))
        pendingEmptyCVOtherPublicationIDs.formIntersection(Set(cvOtherPublications.map(\.id)))
        refreshPublicationIndexes(mode: .crossReferencesOnly, projectCacheBehavior: .markDirty)
        scheduleDeferredFullPublicationIndexRefresh(reason: "restore-snapshot")
        scheduleDataQualityCachePrewarm(reason: "restore-snapshot")
        if droppedQueuedMetadataWrite {
            persistMetadataSilently(metadata, publishStatusUpdates: false)
        }
    }

    func persistMetadataSilently(
        _ updated: DataSourceMetadata,
        publishImmediately: Bool = true,
        publishStatusUpdates: Bool = true,
        includeBackup: Bool = true,
        undoActionName: String? = nil,
        invalidateStorageDiagnosticsOnWrite: Bool = true
    ) {
        do {
            try requireSupportedStorageSchema()
        } catch {
            loadError = error.localizedDescription
            persistenceStatus.isSaving = false
            return
        }
        // No synchronous drain here: the serial metadata queue already orders
        // writes, and every completion is generation-guarded, so an in-flight
        // older write can neither interleave nor clobber the caches. The
        // drain made every edit wait out the previous write on the main
        // thread (up to the full write duration on rapid consecutive edits).
        // F44: timing of the main-thread part, logged when slow.
        let persistStartedAt = CFAbsoluteTimeGetCurrent()
        let previousMetadata = editableMetadataSnapshot
        let updated = Self.sanitizedMetadata(updated)
        let afterSanitize = CFAbsoluteTimeGetCurrent()
        if let undoActionName, updated != previousMetadata {
            registerMetadataUndo(
                previousMetadata: previousMetadata,
                currentMetadata: updated,
                actionName: undoActionName
            )
            appendRecentRecordRevision(
                actionName: undoActionName,
                title: language.text("App settings and workspace state", "Appinställningar och arbetsytans läge"),
                subtitle: language.text("Metadata", "Metadata")
            )
        }
        let afterUndo = CFAbsoluteTimeGetCurrent()
        if publishImmediately {
            metadata = updated
        }
        let afterPublish = CFAbsoluteTimeGetCurrent()
        appendCalendarChangeDiagnosticIfSlow(
            phase: "metadata-persist-main",
            startedAt: persistStartedAt,
            details: String(
                format: "sanitize_ms=%.2f undo_ms=%.2f publish_ms=%.2f",
                (afterSanitize - persistStartedAt) * 1000,
                (afterUndo - afterSanitize) * 1000,
                (afterPublish - afterUndo) * 1000
            )
        )
        if publishStatusUpdates {
            persistenceStatus.isSaving = true
        }
        let shouldInvalidateStorageDiagnostics = invalidateStorageDiagnosticsOnWrite
            || pendingMetadataPersistenceInvalidatesStorageDiagnostics
        pendingMetadataPersistenceWorkItem?.cancel()
        let snapshot = updated
        pendingMetadataSnapshot = snapshot
        pendingMetadataPersistenceInvalidatesStorageDiagnostics = shouldInvalidateStorageDiagnostics
        pendingMetadataPersistenceGeneration += 1
        let generation = pendingMetadataPersistenceGeneration
        guard sqliteStore != nil else {
            loadError = language.text(
                "SQLite storage is required for metadata persistence.",
                "SQLite-lagring krävs för att spara metadata."
            )
            persistenceStatus.isSaving = false
            return
        }
        let databaseURL = Self.databaseURL
        let workItem = DispatchWorkItem { [metadataPersistenceQueue] in
            guard generation == self.pendingMetadataPersistenceGeneration else { return }
            metadataPersistenceQueue.async {
                do {
                    let writeResult = try Self.writeMetadataSnapshot(
                        snapshot,
                        databaseURL: databaseURL
                    )
                    DispatchQueue.main.async {
                        guard generation == self.pendingMetadataPersistenceGeneration else { return }
                        let completionStartedAt = CFAbsoluteTimeGetCurrent()
                        self.pendingMetadataPersistenceWorkItem = nil
                        self.pendingMetadataSnapshot = nil
                        self.pendingMetadataPersistenceInvalidatesStorageDiagnostics = false
                        self.metadataPersistenceRetryCount = 0
                        if publishStatusUpdates {
                            self.persistenceStatus.isSaving = false
                            self.persistenceStatus.lastSavedAt = Date()
                        }
                        if !writeResult.dataByStorageKey.isEmpty {
                            for (storageKey, data) in writeResult.dataByStorageKey {
                                self.persistedDocumentCache[storageKey] = data
                            }
                            self.exportToFootprintExportAfterWrite(writeResult.dataByStorageKey.map { (key: $0.key, data: $0.value) })
                        }
                        let afterExport = CFAbsoluteTimeGetCurrent()
                        if shouldInvalidateStorageDiagnostics, writeResult.didWrite {
                            self.invalidateStorageStructureDiagnosticsAfterWrite()
                        }
                        // F44: skip the backup round when a verified backup
                        // younger than 15 minutes is already known; it would
                        // not make a new one (see the helper for details).
                        let backupStartedAt = CFAbsoluteTimeGetCurrent()
                        var backupLabel = "no"
                        if includeBackup, writeResult.didWrite {
                            let backupNow = Date()
                            if self.hasRecentVerifiedPeriodicBackupInMemory(now: backupNow) {
                                backupLabel = "recent"
                            } else {
                                backupLabel = "enqueued"
                                self.enqueuePeriodicBackupSnapshotIfNeeded(
                                    now: backupNow,
                                    updatesPersistenceStatus: publishStatusUpdates
                                )
                            }
                        }
                        let afterBackup = CFAbsoluteTimeGetCurrent()
                        self.appendCalendarChangeDiagnosticIfSlow(
                            phase: "metadata-persist-complete",
                            startedAt: completionStartedAt,
                            details: String(
                                format: "export_ms=%.2f backup=%@ backup_ms=%.2f",
                                (afterExport - completionStartedAt) * 1000,
                                backupLabel,
                                (afterBackup - backupStartedAt) * 1000
                            )
                        )
                    }
                } catch {
                    DispatchQueue.main.async {
                        guard generation == self.pendingMetadataPersistenceGeneration else { return }
                        self.pendingMetadataPersistenceWorkItem = nil
                        self.loadError = error.localizedDescription
                        self.metadataPersistenceRetryCount += 1
                        let shouldRetry = self.metadataPersistenceRetryCount <= 3
                        self.persistenceStatus.isSaving = shouldRetry || !publishStatusUpdates
                        if shouldRetry {
                            DispatchQueue.main.asyncAfter(deadline: .now() + 1) {
                                guard generation == self.pendingMetadataPersistenceGeneration,
                                      self.pendingMetadataSnapshot == snapshot else { return }
                                self.persistMetadataSilently(
                                    snapshot,
                                    publishImmediately: false,
                                    publishStatusUpdates: publishStatusUpdates,
                                    includeBackup: includeBackup,
                                    invalidateStorageDiagnosticsOnWrite: shouldInvalidateStorageDiagnostics
                                )
                            }
                        }
                    }
                    return
                }
            }
        }
        pendingMetadataPersistenceWorkItem = workItem
        let persistenceDelay = publishStatusUpdates
            ? Self.interactiveMetadataPersistenceDelay
            : Self.quietMetadataPersistenceDelay
        appendPerformanceDiagnostic(
            String(
                format: "metadata-persist-deferred quiet=%@ delay_s=%.2f backup=%@ diagnostics=%@",
                publishStatusUpdates ? "no" : "yes",
                persistenceDelay,
                includeBackup ? "yes" : "no",
                shouldInvalidateStorageDiagnostics ? "yes" : "no"
            )
        )
        DispatchQueue.main.asyncAfter(deadline: .now() + persistenceDelay, execute: workItem)
    }

    /// A queued metadata write may already have reached the database while
    /// its main-queue completion, the only place that refreshes
    /// persistedDocumentCache for these keys, is about to be dropped by a
    /// generation bump. The cache would then still hold the pre-edit bytes,
    /// and a following persist() restoring exactly those bytes (an undo of a
    /// calendar deletion, say) would skip the write and leave the edit on
    /// disk. Forgetting the entries makes that persist write them; the only
    /// cost is a possibly redundant write.
    private func forgetMetadataQueueDocumentCache() {
        for key in Self.metadataDerivedStorageKeys {
            persistedDocumentCache[key] = nil
        }
        persistedDocumentCache["relational_core"] = nil
        persistedDocumentCache["relational_sqlite_snapshot"] = nil
    }

    var editableMetadataSnapshot: DataSourceMetadata {
        Self.sanitizedMetadata(pendingMetadataSnapshot ?? metadata)
    }

    private func promotePendingMetadataSnapshotIfNeeded() {
        guard let snapshot = pendingMetadataSnapshot else { return }
        pendingMetadataPersistenceWorkItem?.cancel()
        pendingMetadataPersistenceWorkItem = nil
        drainMetadataPersistenceQueue()
        forgetMetadataQueueDocumentCache()
        pendingMetadataPersistenceGeneration += 1
        pendingMetadataSnapshot = nil
        pendingMetadataPersistenceInvalidatesStorageDiagnostics = false
        metadata = Self.sanitizedMetadata(snapshot)
    }

    nonisolated static func sanitizedMetadata(_ metadata: DataSourceMetadata) -> DataSourceMetadata {
        var metadata = metadata
        metadata.migrateLegacyFields()
        return metadata
    }

    nonisolated private static func normalizedTeachingRoleOptions(
        _ options: [TeachingRoleOption],
        language: AppLanguage
    ) -> [TeachingRoleOption] {
        var combined = options
        if combined.isEmpty {
            combined = TeachingRoleOption.builtInOptions
        }

        var normalized: [TeachingRoleOption] = []
        var seenIDs = Set<String>()
        for option in combined {
            var current = option
            current.normalize()
            guard current.id.nonEmpty != nil else { continue }
            guard seenIDs.insert(current.id).inserted else { continue }
            if current.nameSv.nonEmpty == nil || current.nameEn.nonEmpty == nil,
               let builtIn = TeachingRoleOption.builtInOptions.first(where: { $0.id == current.id }) {
                if current.nameSv.nonEmpty == nil {
                    current.nameSv = builtIn.nameSv
                }
                if current.nameEn.nonEmpty == nil {
                    current.nameEn = builtIn.nameEn
                }
            }
            normalized.append(current)
        }

        return normalized.sorted {
            $0.localizedName(language: language).localizedStandardCompare($1.localizedName(language: language)) == .orderedAscending
        }
    }

