    nonisolated private static func writeMetadataSnapshot(
        _ snapshot: DataSourceMetadata,
        databaseURL: URL
    ) throws -> (didWrite: Bool, dataByStorageKey: [String: Data]) {
        let encoder = makePersistenceEncoder()
        let data = try encoder.encode(snapshot)
        let sqliteStore = try SQLiteDocumentStore(url: databaseURL)
        let persistedMetadataData = try sqliteStore.loadData(named: "metadata")
        if persistedMetadataData == data {
            return (false, [:])
        }

        let previousMetadata = try persistedMetadataData.map {
            try JSONDecoder().decode(DataSourceMetadata.self, from: $0)
        }
        var documents: [(String, Data)] = [
            ("metadata", data),
            ("app_settings", try encoder.encode(AppSettingsSnapshot(metadata: snapshot))),
        ]
        var calendarSnapshot: RelationalSQLiteSnapshot?
        let relationalCalendarChanged = previousMetadata.map {
            metadataRelationalCalendarFieldsDiffer($0, snapshot)
        } ?? true
        if relationalCalendarChanged {
            documents.append(contentsOf: [
                ("calendar_travel_records", try encoder.encode(snapshot.calendarTravelRecords ?? [])),
                ("calendar_accommodation_records", try encoder.encode(snapshot.calendarAccommodationRecords ?? [])),
                ("calendar_meeting_records", try encoder.encode(snapshot.calendarMeetingRecords ?? [])),
            ])
            calendarSnapshot = relationalSQLiteSnapshot(
                generatedAt: Date(timeIntervalSince1970: 0),
                applications: [],
                metadata: snapshot,
                organizations: [],
                projects: [],
                publicationAuthors: [],
                publicationRecords: [],
                cvConferenceContributions: []
            )
        }

        let writtenDocuments = try sqliteStore.saveMetadataBatch(
            documents,
            calendarSnapshot: calendarSnapshot
        )
        return (true, Dictionary(writtenDocuments, uniquingKeysWith: { _, latest in latest }))
    }

    nonisolated private static func metadataRelationalCalendarFieldsDiffer(
        _ lhs: DataSourceMetadata,
        _ rhs: DataSourceMetadata
    ) -> Bool {
        lhs.calendarTravelRecords != rhs.calendarTravelRecords
            || lhs.calendarAccommodationRecords != rhs.calendarAccommodationRecords
            || lhs.calendarMeetingRecords != rhs.calendarMeetingRecords
    }

    nonisolated static func makePersistenceEncoder() -> JSONEncoder {
        let encoder = JSONEncoder()
        if prettyPrintedPersistenceJSON {
            encoder.outputFormatting = [.prettyPrinted, .sortedKeys, .withoutEscapingSlashes]
        } else {
            encoder.outputFormatting = [.withoutEscapingSlashes]
        }
        return encoder
    }

    nonisolated private static func trimDiagnosticsFileIfNeeded(at url: URL, maximumBytes: Int) {
        guard
            let attributes = try? FileManager.default.attributesOfItem(atPath: url.path),
            let fileSize = attributes[.size] as? NSNumber,
            fileSize.intValue > maximumBytes,
            let data = try? Data(contentsOf: url)
        else {
            return
        }

        let retained = Data(data.suffix(maximumBytes / 2))
        try? retained.write(to: url, options: .atomic)
    }

    private func deferredPersistenceDocuments(from states: [PersistedDocumentState]) -> [DocumentPersistenceWorker.Document] {
        states.compactMap { state in
            DocumentPersistenceWorker.Document(
                storageKey: state.storageKey,
                data: state.data
            )
        }
    }

    private func queueDeferredPersistence(
        _ states: [PersistedDocumentState],
        scopeLabel: String,
        force: Bool = false
    ) {
        guard !hasUnsupportedStorageSchema,
              !storageWritesBlockedByUnverifiedRollback,
              !storageWritesBlockedByLoadFailure else {
            if storageWritesBlockedByLoadFailure {
                loadError = "Storage writes are blocked because the existing database could not be loaded."
            } else if storageWritesBlockedByUnverifiedRollback {
                loadError = "Storage writes are blocked because a rollback could not be verified."
            } else {
                loadError = UnsupportedStorageSchemaError(
                    storedVersion: metadata.schemaVersion ?? DataSourceMetadata.currentSchemaVersion + 1
                ).localizedDescription
            }
            persistenceStatus.isSaving = false
            return
        }
        let changedStates = states.filter { state in
            if force {
                return true
            }
            if let pending = pendingDeferredPersistedStatesByKey[state.storageKey] {
                return pending.data != state.data
            }
            return persistedDocumentCache[state.storageKey] != state.data
        }
        guard !changedStates.isEmpty else {
            appendPerformanceDiagnostic("persist-deferred-noop scope=\(scopeLabel) reason=unchanged-cache")
            return
        }

        for state in changedStates {
            pendingDeferredPersistedStatesByKey[state.storageKey] = state
        }
        pendingDeferredPersistenceScopeLabels.insert(scopeLabel)
        persistenceStatus.isSaving = true

        pendingDeferredPersistenceWorkItem?.cancel()
        let workItem = DispatchWorkItem { [weak self] in
            Task { @MainActor [weak self] in
                self?.startDeferredPersistenceWriteIfNeeded()
            }
        }
        pendingDeferredPersistenceWorkItem = workItem
        DispatchQueue.main.asyncAfter(
            deadline: .now() + Self.deferredPersistenceCoalesceInterval,
            execute: workItem
        )
    }

    private func startDeferredPersistenceWriteIfNeeded(scopeLabelOverride: String? = nil) {
        guard !pendingDeferredPersistedStatesByKey.isEmpty else { return }

        pendingDeferredPersistenceWorkItem?.cancel()
        pendingDeferredPersistenceWorkItem = nil

        let states = pendingDeferredPersistedStatesByKey.values.sorted { $0.storageKey < $1.storageKey }
        let scopeLabel = scopeLabelOverride ?? pendingDeferredPersistenceScopeLabels.sorted().joined(separator: "+")
        let documents = deferredPersistenceDocuments(from: states)
        let databaseURL = sqliteStore == nil ? nil : Self.databaseURL
        let startedAt = Date()
        let persistenceGroup = deferredPersistenceGroup

        for state in states {
            inFlightDeferredPersistedStatesByKey[state.storageKey] = state
        }
        pendingDeferredPersistedStatesByKey.removeAll()
        pendingDeferredPersistenceScopeLabels.removeAll()

        persistenceGroup.enter()
        deferredPersistenceQueue.async { [weak self, documents, states, databaseURL, startedAt, scopeLabel] in
            let writeStartedAt = CFAbsoluteTimeGetCurrent()
            do {
                try DocumentPersistenceWorker.write(documents, databaseURL: databaseURL)
                if Self.verifyPersistenceWrites {
                    try DocumentPersistenceWorker.verify(documents, databaseURL: databaseURL)
                }
                let writeDuration = (CFAbsoluteTimeGetCurrent() - writeStartedAt) * 1000
                DispatchQueue.main.async { [weak self] in
                    guard let self else { return }
                    self.completeDeferredPersistenceSuccess(
                        states: states,
                        scopeLabel: scopeLabel.isEmpty ? "deferred" : scopeLabel,
                        startedAt: startedAt,
                        writeDuration: writeDuration
                    )
                }
            } catch {
                let writeDuration = (CFAbsoluteTimeGetCurrent() - writeStartedAt) * 1000
                DispatchQueue.main.async { [weak self] in
                    guard let self else { return }
                    self.completeDeferredPersistenceFailure(
                        error,
                        states: states,
                        scopeLabel: scopeLabel.isEmpty ? "deferred" : scopeLabel,
                        startedAt: startedAt,
                        writeDuration: writeDuration
                    )
                }
            }
            persistenceGroup.leave()
        }
    }

    /// Footprint-export efter varje lyckad skrivning, oavsett sparväg (direkt, autosparning, metadata).
    /// Första skrivningen efter start exporterar alla dokument, därefter bara de som ändrats.
    /// Bilagor (PDF:er m.m.) speglas från appens lagringsmapp vid varje export.
    func exportToFootprintExportAfterWrite(_ documents: [(key: String, data: Data)]) {
        let writer = FootprintExportWriter.shared
        guard writer.isEnabled else { return }
        let storageDirectory = Self.databaseURL.deletingLastPathComponent()
        if writer.needsFullExport,
           let allDocuments = try? encodedPersistenceDocuments(for: .allCoreData) {
            writer.export(allDocuments.map { (key: $0.storageKey, data: $0.data) }, full: true, storageDirectory: storageDirectory)
        } else if !documents.isEmpty {
            writer.export(documents, full: false, storageDirectory: storageDirectory)
        }
    }

    private func completeDeferredPersistenceSuccess(
        states: [PersistedDocumentState],
        scopeLabel: String,
        startedAt: Date,
        writeDuration: Double
    ) {
        let hasActiveWrites = deferredPersistenceGroup.wait(timeout: .now()) != .success
        for state in states {
            deferredPersistenceRetryCountByKey[state.storageKey] = nil
            // Round 13: only a write that is still the newest for its document
            // updates the cache. If a newer version was written in between
            // (for example by an undoable change), the cache keeps that one;
            // otherwise a later Undo to these bytes would look already saved.
            if inFlightDeferredPersistedStatesByKey[state.storageKey]?.data == state.data {
                persistedDocumentCache[state.storageKey] = state.data
                inFlightDeferredPersistedStatesByKey[state.storageKey] = nil
            }
        }
        persistenceStatus.isSaving = !pendingDeferredPersistedStatesByKey.isEmpty || hasActiveWrites
        persistenceStatus.lastSavedAt = Date()
        clearAutosaveError()
        invalidateStorageStructureDiagnosticsAfterWrite()
        exportToFootprintExportAfterWrite(states.map { (key: $0.storageKey, data: $0.data) })
        appendPerformanceDiagnostic(
            String(
                format: "persist-deferred scope=%@ changed=%ld write_ms=%.2f total_ms=%.2f",
                scopeLabel,
                states.count,
                writeDuration,
                Date().timeIntervalSince(startedAt) * 1000
            )
        )
    }

    private func completeDeferredPersistenceFailure(
        _ error: Error,
        states: [PersistedDocumentState],
        scopeLabel: String,
        startedAt: Date,
        writeDuration: Double
    ) {
        let hasActiveWrites = deferredPersistenceGroup.wait(timeout: .now()) != .success
        var shouldScheduleRetry = false
        for state in states {
            // A newer edit already queued for this key always wins.
            if pendingDeferredPersistedStatesByKey[state.storageKey] == nil {
                pendingDeferredPersistedStatesByKey[state.storageKey] = state
            }
            let retryCount = (deferredPersistenceRetryCountByKey[state.storageKey] ?? 0) + 1
            deferredPersistenceRetryCountByKey[state.storageKey] = retryCount
            shouldScheduleRetry = shouldScheduleRetry || retryCount <= 3
        }
        pendingDeferredPersistenceScopeLabels.insert(scopeLabel)
        if shouldScheduleRetry, pendingDeferredPersistenceWorkItem == nil {
            let workItem = DispatchWorkItem { [weak self] in
                Task { @MainActor [weak self] in
                    self?.startDeferredPersistenceWriteIfNeeded(scopeLabelOverride: "retry")
                }
            }
            pendingDeferredPersistenceWorkItem = workItem
            DispatchQueue.main.asyncAfter(deadline: .now() + 1, execute: workItem)
        }
        persistenceStatus.isSaving = !pendingDeferredPersistedStatesByKey.isEmpty || hasActiveWrites
        loadError = error.localizedDescription
        lastAutosaveErrorMessage = error.localizedDescription
        appendPerformanceDiagnostic(
            String(
                format: "persist-deferred-failed scope=%@ write_ms=%.2f total_ms=%.2f",
                scopeLabel,
                writeDuration,
                Date().timeIntervalSince(startedAt) * 1000
            )
        )
    }

    @discardableResult
    func flushPendingPersistenceIfNeeded(timeout: TimeInterval = 10) -> Bool {
        if pendingDeferredPersistenceWorkItem != nil || !pendingDeferredPersistedStatesByKey.isEmpty {
            startDeferredPersistenceWriteIfNeeded(scopeLabelOverride: "flush")
        }
        let didFinish = deferredPersistenceGroup.wait(timeout: .now() + timeout) == .success
        if !didFinish {
            loadError = language.text(
                "Pending save did not finish in time.",
                "Väntande sparning blev inte klar i tid."
            )
        }
        return didFinish
    }

    /// Starts any pending deferred document write immediately without waiting
    /// for it. Deactivation uses this: the synchronous flush froze the app for
    /// the full write duration on every cmd-tab, and the app keeps running so
    /// the write completes on its queue moments later anyway.
    func expeditePendingPersistence() {
        if pendingDeferredPersistenceWorkItem != nil || !pendingDeferredPersistedStatesByKey.isEmpty {
            startDeferredPersistenceWriteIfNeeded(scopeLabelOverride: "expedite")
        }
    }

    /// Runs the scheduled metadata write now instead of after its coalescing
    /// delay, without blocking the caller: the scheduled body itself hops to
    /// the metadata persistence queue. The delayed copy is cancelled; if a
    /// newer edit superseded this one, the body's generation guard no-ops.
    func expeditePendingMetadataPersistence() {
        guard pendingMetadataSnapshot != nil,
              let workItem = pendingMetadataPersistenceWorkItem else { return }
        workItem.perform()
        workItem.cancel()
    }

    func recordPeriodicBackupCompletion(at date: Date) {
        persistenceStatus.lastBackupAt = date
    }

    private func encodedPersistenceDocuments(for set: PersistenceSet) throws -> [EncodedPersistenceDocument] {
        let encoder = Self.makePersistenceEncoder()
        var documents: [EncodedPersistenceDocument] = []
        if set.contains(.applications) {
            documents.append(EncodedPersistenceDocument(storageKey: "applications", data: try encoder.encode(applications)))
        }
        if set.contains(.metadata) {
            documents.append(EncodedPersistenceDocument(storageKey: "metadata", data: try encoder.encode(editableMetadataSnapshot)))
        }
        if set.contains(.metadata) || set.contains(.appSettings) {
            documents.append(EncodedPersistenceDocument(storageKey: "app_settings", data: try encoder.encode(AppSettingsSnapshot(metadata: editableMetadataSnapshot))))
        }
        if set.contains(.metadata) || set.contains(.calendarTravelRecords) {
            documents.append(EncodedPersistenceDocument(storageKey: "calendar_travel_records", data: try encoder.encode(calendarTravelRecords)))
        }
        if set.contains(.metadata) || set.contains(.calendarAccommodationRecords) {
            documents.append(EncodedPersistenceDocument(storageKey: "calendar_accommodation_records", data: try encoder.encode(calendarAccommodationRecords)))
        }
        if set.contains(.metadata) || set.contains(.calendarMeetingRecords) {
            documents.append(EncodedPersistenceDocument(storageKey: "calendar_meeting_records", data: try encoder.encode(calendarMeetingRecords)))
        }
        if set.contains(.organizations) {
            documents.append(EncodedPersistenceDocument(storageKey: "organizations", data: try encoder.encode(organizations)))
        }
        if set.contains(.organizations) || set.contains(.congresses) {
            documents.append(EncodedPersistenceDocument(storageKey: "congresses", data: try encoder.encode(Self.storedCongressRecords(from: organizations))))
        }
        if set.contains(.projects) {
            documents.append(EncodedPersistenceDocument(storageKey: "projects", data: try encoder.encode(projects)))
        }
        if set.contains(.teachingCourses) {
            documents.append(EncodedPersistenceDocument(storageKey: "teaching_courses", data: try encoder.encode(teachingCourses)))
        }
        if set.contains(.teachingComponents) {
            documents.append(EncodedPersistenceDocument(storageKey: "teaching_components", data: try encoder.encode(teachingComponents)))
        }
        if set.contains(.teachingFormats) {
            documents.append(EncodedPersistenceDocument(storageKey: "teaching_formats", data: try encoder.encode(teachingFormats)))
        }
        if set.contains(.teachingAssignments) {
            documents.append(EncodedPersistenceDocument(storageKey: "teaching_assignments", data: try encoder.encode(teachingAssignments)))
        }
        if set.contains(.doctoralCandidates) {
            documents.append(EncodedPersistenceDocument(storageKey: "doctoral_candidates", data: try encoder.encode(doctoralCandidates)))
        }
        if set.contains(.cvPersonalResume) {
            documents.append(EncodedPersistenceDocument(storageKey: "cv_personal_resume", data: try encoder.encode(cvPersonalResume)))
        }
        if set.contains(.cvConferenceContributions) {
            documents.append(EncodedPersistenceDocument(storageKey: "cv_conference_contributions", data: try encoder.encode(cvConferenceContributions)))
        }
        if set.contains(.cvMediaAppearances) {
            documents.append(EncodedPersistenceDocument(storageKey: "cv_media_appearances", data: try encoder.encode(cvMediaAppearances)))
        }
        if set.contains(.cvReviewEntries) {
            documents.append(EncodedPersistenceDocument(storageKey: "cv_review_entries", data: try encoder.encode(cvReviewEntries)))
        }
        if set.contains(.cvOtherPublications) {
            documents.append(EncodedPersistenceDocument(storageKey: "cv_other_publications", data: try encoder.encode(cvOtherPublications)))
        }
        if set.contains(.publicationAuthors) {
            documents.append(EncodedPersistenceDocument(storageKey: "publication_authors", data: try encoder.encode(publicationAuthors)))
        }
        if set.contains(.publicationJournals) {
            documents.append(EncodedPersistenceDocument(storageKey: "publication_journals", data: try encoder.encode(publicationJournals)))
        }
        if set.contains(.publicationRecords) {
            documents.append(EncodedPersistenceDocument(storageKey: "publication_records", data: try encoder.encode(publicationRecords)))
        }
        if set.contains(.relationalCore)
            || set.contains(.metadata)
            || set.contains(.organizations)
            || set.contains(.congresses)
            || set.contains(.cvConferenceContributions)
            || set.contains(.applications)
            || set.contains(.projects)
            || set.contains(.publicationAuthors)
            || set.contains(.publicationRecords)
            || set.contains(.calendarTravelRecords)
            || set.contains(.calendarAccommodationRecords)
            || set.contains(.calendarMeetingRecords) {
            documents.append(EncodedPersistenceDocument(storageKey: "relational_core", data: try encoder.encode(relationalCoreSnapshot(generatedAt: Date(timeIntervalSince1970: 0)))))
            documents.append(EncodedPersistenceDocument(storageKey: "relational_sqlite_snapshot", data: try encoder.encode(relationalSQLiteSnapshot(generatedAt: Date(timeIntervalSince1970: 0)))))
        }
        return documents
    }

    func encodedSQLiteDocuments(for set: PersistenceSet) throws -> [(String, Data)] {
        try encodedPersistenceDocuments(for: set).map { ($0.storageKey, $0.data) }
    }

    /// The storage keys encodedPersistenceDocuments(for:) would produce for
    /// the same set. Pinned to it by a stability test so the lists cannot
    /// drift apart.
    nonisolated static func persistenceStorageKeys(for set: PersistenceSet) -> [String] {
        var keys: [String] = []
        if set.contains(.applications) { keys.append("applications") }
        if set.contains(.metadata) { keys.append("metadata") }
        if set.contains(.metadata) || set.contains(.appSettings) { keys.append("app_settings") }
        if set.contains(.metadata) || set.contains(.calendarTravelRecords) { keys.append("calendar_travel_records") }
        if set.contains(.metadata) || set.contains(.calendarAccommodationRecords) { keys.append("calendar_accommodation_records") }
        if set.contains(.metadata) || set.contains(.calendarMeetingRecords) { keys.append("calendar_meeting_records") }
        if set.contains(.organizations) { keys.append("organizations") }
        if set.contains(.organizations) || set.contains(.congresses) { keys.append("congresses") }
        if set.contains(.projects) { keys.append("projects") }
        if set.contains(.teachingCourses) { keys.append("teaching_courses") }
        if set.contains(.teachingComponents) { keys.append("teaching_components") }
        if set.contains(.teachingFormats) { keys.append("teaching_formats") }
        if set.contains(.teachingAssignments) { keys.append("teaching_assignments") }
        if set.contains(.doctoralCandidates) { keys.append("doctoral_candidates") }
        if set.contains(.cvPersonalResume) { keys.append("cv_personal_resume") }
        if set.contains(.cvConferenceContributions) { keys.append("cv_conference_contributions") }
        if set.contains(.cvMediaAppearances) { keys.append("cv_media_appearances") }
        if set.contains(.cvReviewEntries) { keys.append("cv_review_entries") }
        if set.contains(.cvOtherPublications) { keys.append("cv_other_publications") }
        if set.contains(.publicationAuthors) { keys.append("publication_authors") }
        if set.contains(.publicationJournals) { keys.append("publication_journals") }
        if set.contains(.publicationRecords) { keys.append("publication_records") }
        let relationalTriggers: PersistenceSet = [
            .relationalCore, .metadata, .organizations, .congresses,
            .cvConferenceContributions, .applications, .projects,
            .publicationAuthors, .publicationRecords,
            .calendarTravelRecords, .calendarAccommodationRecords, .calendarMeetingRecords,
        ]
        if !set.isDisjoint(with: relationalTriggers) {
            keys.append("relational_core")
            keys.append("relational_sqlite_snapshot")
        }
        return keys
    }

    /// Storage keys whose persisted bytes are produced by the silent metadata
    /// queue (writeMetadataSnapshot); while a metadata write is pending, the
    /// document cache still holds the pre-edit bytes for these keys.
    nonisolated static let metadataDerivedStorageKeys: Set<String> = [
        "metadata", "app_settings",
        "calendar_travel_records", "calendar_accommodation_records", "calendar_meeting_records",
    ]

    /// Pre-change undo baseline. At the start of every edit path the
    /// in-memory state matches the bytes of the last persist (or the queued
    /// deferred write), so those bytes are reused instead of paying a second
    /// whole-collection encode per action; any key without cached bytes falls
    /// back to a fresh encode. Keys served by the silent metadata queue cannot
    /// use the cache while a metadata write is pending: the cache lags the
    /// in-memory state until that write completes, and a baseline taken from
    /// it would make a later undo silently revert the pending edit as well.
    func persistedBaselineDocumentStates(for set: PersistenceSet) throws -> [PersistedDocumentState] {
        let keys = Self.persistenceStorageKeys(for: set)
        var states: [PersistedDocumentState] = []
        states.reserveCapacity(keys.count)
        for key in keys {
            if pendingMetadataSnapshot != nil, Self.metadataDerivedStorageKeys.contains(key) {
                return try currentPersistedDocumentStates(for: set)
            }
            let cached = pendingDeferredPersistedStatesByKey[key]?.data
                ?? inFlightDeferredPersistedStatesByKey[key]?.data
                ?? persistedDocumentCache[key]
            guard let data = cached else {
                return try currentPersistedDocumentStates(for: set)
            }
            states.append(PersistedDocumentState(storageKey: key, data: data))
        }
        return states
    }

    private func currentPersistedDocumentStates(for set: PersistenceSet) throws -> [PersistedDocumentState] {
        let startedAt = CFAbsoluteTimeGetCurrent()
        let states = try encodedPersistenceDocuments(for: set).map { PersistedDocumentState(storageKey: $0.storageKey, data: $0.data) }
        appendPerformanceDiagnosticIfSlow(
            { duration in
                String(
                    format: "persist-state-encode scope=%@ documents=%ld encode_ms=%.2f",
                    persistenceScopeLabel(for: set),
                    states.count,
                    duration
                )
            },
            startedAt: startedAt,
            thresholdMs: 10
        )
        return states
    }

    private func writePersistedDocumentStates(_ states: [PersistedDocumentState]) throws {
        guard sqliteStore != nil else {
            throw NSError(domain: "Footprint", code: 60, userInfo: [
                NSLocalizedDescriptionKey: "SQLite storage is required for active persistence.",
            ])
        }
        flushPendingPersistenceIfNeeded()
        let documents = deferredPersistenceDocuments(from: states)
        try DocumentPersistenceWorker.write(documents, databaseURL: Self.databaseURL)
        for state in states {
            persistedDocumentCache[state.storageKey] = state.data
            // Round 13: a background write of an older version that reports
            // back later must not put its bytes back in the cache.
            inFlightDeferredPersistedStatesByKey[state.storageKey] = nil
        }
        if Self.verifyPersistenceWrites {
            try DocumentPersistenceWorker.verify(documents, databaseURL: Self.databaseURL)
        }
        invalidateStorageStructureDiagnosticsAfterWrite()
    }

    private func refreshState(forDocumentKeys keys: Set<String>) {
        let applicationKeys: Set<String> = ["applications", "organizations", "congresses", "projects"]
        let calendarKeys: Set<String> = ["calendar_travel_records", "calendar_accommodation_records", "calendar_meeting_records", "calendar_vertical_note_records"]
        let teachingKeys: Set<String> = ["teaching_courses", "teaching_components", "teaching_formats", "teaching_assignments", "doctoral_candidates"]
        let cvKeys: Set<String> = ["cv_personal_resume", "cv_conference_contributions", "cv_media_appearances", "cv_review_entries", "cv_other_publications"]
        let publicationKeys: Set<String> = ["publication_authors", "publication_journals", "publication_records"]

        if !keys.isDisjoint(with: applicationKeys) || !keys.isDisjoint(with: calendarKeys) {
            refreshApplicationsState()
        }
        if !keys.isDisjoint(with: teachingKeys) {
            refreshTeachingState()
        }
        if !keys.isDisjoint(with: cvKeys) {
            refreshCVState()
        }
        if !keys.isDisjoint(with: publicationKeys) {
            if keys == ["publication_authors"] {
                refreshPublicationAuthorsOnly()
            } else if keys == ["publication_journals"] {
                refreshPublicationJournalsState(projectCacheBehavior: .skip)
            } else if keys == ["publication_records"] {
                refreshPublicationRecordsOnly()
            } else {
                refreshPublicationRecords()
            }
        }
    }

    private func applyPersistedDocumentStatesToMemory(_ states: [PersistedDocumentState]) throws {
        let decoder = JSONDecoder()
        let keys = Set(states.map(\.storageKey))
        var storedCongressesToMerge: [StoredCongressRecord]?

        if keys.contains("metadata") {
            pendingMetadataPersistenceWorkItem?.cancel()
            pendingMetadataPersistenceWorkItem = nil
            drainMetadataPersistenceQueue()
            pendingMetadataSnapshot = nil
            pendingMetadataPersistenceInvalidatesStorageDiagnostics = false
            pendingMetadataPersistenceGeneration += 1
            lastSelectedTabOverride = nil
            lastSelectionOverrides.removeAll()
        }

        for state in states {
            switch state.storageKey {
            case "applications":
                applications = try decoder.decode([GrantApplication].self, from: state.data)
            case "metadata":
                metadata = Self.sanitizedMetadata(try decoder.decode(DataSourceMetadata.self, from: state.data))
            case "app_settings":
                metadata = Self.metadataByApplyingAppSettings(
                    metadata,
                    settings: try decoder.decode(AppSettingsSnapshot.self, from: state.data)
                )
            case "calendar_travel_records":
                metadata.calendarTravelRecords = try decoder.decode([CalendarTravelRecord].self, from: state.data)
            case "calendar_accommodation_records":
                metadata.calendarAccommodationRecords = try decoder.decode([CalendarAccommodationRecord].self, from: state.data)
            case "calendar_meeting_records":
                metadata.calendarMeetingRecords = try decoder.decode([CalendarMeetingRecord].self, from: state.data)
            case "calendar_vertical_note_records":
                metadata.calendarVerticalNoteRecords = try decoder.decode([CalendarVerticalNoteRecord].self, from: state.data)
            case "organizations":
                organizations = try decodeOrganizationsForState(from: state.data)
            case "congresses":
                storedCongressesToMerge = try decoder.decode([StoredCongressRecord].self, from: state.data)
            case "projects":
                projects = try decodeProjectsForState(from: state.data)
            case "teaching_courses":
                teachingCourses = try decoder.decode([TeachingCourse].self, from: state.data)
            case "teaching_components":
                teachingComponents = try decoder.decode([TeachingComponent].self, from: state.data)
            case "teaching_formats":
                teachingFormats = try decoder.decode([TeachingFormatOption].self, from: state.data)
            case "teaching_assignments":
                teachingAssignments = try decoder.decode([TeachingAssignment].self, from: state.data)
            case "doctoral_candidates":
                doctoralCandidates = try decoder.decode([DoctoralCandidateRecord].self, from: state.data)
            case "cv_personal_resume":
                cvPersonalResume = try decoder.decode(CVPersonalResume.self, from: state.data)
            case "cv_conference_contributions":
                cvConferenceContributions = try decoder.decode([CVConferenceContribution].self, from: state.data)
            case "cv_media_appearances":
                cvMediaAppearances = try decoder.decode([CVMediaAppearance].self, from: state.data)
            case "cv_review_entries":
                cvReviewEntries = try decoder.decode([CVReviewEntry].self, from: state.data)
            case "cv_other_publications":
                cvOtherPublications = try decoder.decode([CVOtherPublicationEntry].self, from: state.data)
            case "publication_authors":
                publicationAuthors = try decoder.decode([PublicationAuthor].self, from: state.data)
            case "publication_journals":
                publicationJournals = try decoder.decode([PublicationJournal].self, from: state.data)
            case "publication_records":
                publicationRecords = try decoder.decode([PublicationRecord].self, from: state.data)
            default:
                break
            }
        }
        if let storedCongressesToMerge {
            organizations = Self.organizationsByMergingStoredCongressRecords(storedCongressesToMerge, into: organizations)
        }
        metadata = Self.sanitizedMetadata(metadata)

        refreshState(forDocumentKeys: keys)
    }

    func rebuildPersistedDocumentCacheForAllCoreData() throws {
        persistedDocumentCache = Dictionary(
            firstWinsKeysWithValues: try encodedPersistenceDocuments(for: .allCoreData).map { ($0.storageKey, $0.data) }
        )
    }

    func stopPersistenceSaving() {
        persistenceStatus.isSaving = false
    }

    private func archiveDeletion<T: Encodable>(
        kind: String,
        title: String,
        payload: T,
        relatedDocumentStates: [PersistedDocumentState] = []
    ) throws {
        let encoder = JSONEncoder()
        encoder.outputFormatting = [.prettyPrinted, .sortedKeys, .withoutEscapingSlashes]
        let archivedPayload = try encoder.encode(payload)

        var archivedRecords = try loadArchivedRecords()
        let envelopeID = UUID().uuidString

        archivedRecords.insert(
            ArchivedRecordEnvelope(
                id: envelopeID,
                kind: kind,
                title: title,
                deletedAt: GrantParsing.timestampNow(),
                payload: archivedPayload,
                relatedDocumentStates: relatedDocumentStates.isEmpty ? nil : relatedDocumentStates.map {
                    ArchivedDocumentState(storageKey: $0.storageKey, data: $0.data)
                }
            ),
            at: 0
        )

        try saveArchivedRecords(archivedRecords)
        archiveEnvelopeIDsAddedInCurrentChange?.append(envelopeID)
    }

    private func mergedPersistedDocumentStates(_ groups: [[PersistedDocumentState]]) -> [PersistedDocumentState] {
        var merged: [String: PersistedDocumentState] = [:]
        for group in groups {
            for state in group {
                merged[state.storageKey] = state
            }
        }
        return merged.values.sorted { $0.storageKey < $1.storageKey }
    }

