    func loadArchivedRecords() throws -> [ArchivedRecordEnvelope] {
        guard let sqliteStore else {
            throw NSError(domain: "Footprint", code: 55, userInfo: [
                NSLocalizedDescriptionKey: "SQLite storage is required for archived records.",
            ])
        }
        return try sqliteStore.load([ArchivedRecordEnvelope].self, named: "archived_records") ?? []
    }

    func saveArchivedRecords(_ archivedRecords: [ArchivedRecordEnvelope]) throws {
        try requireSupportedStorageSchema()
        try Self.ensureStorageDirectory()
        guard let sqliteStore else {
            throw NSError(domain: "Footprint", code: 56, userInfo: [
                NSLocalizedDescriptionKey: "SQLite storage is required for archived records.",
            ])
        }
        try sqliteStore.save(archivedRecords, named: "archived_records")
        invalidateDataQualityCaches()
    }

    func loadReceivedGrantsData() throws -> Data? {
        guard let sqliteStore else {
            throw NSError(domain: "Footprint", code: 57, userInfo: [
                NSLocalizedDescriptionKey: "SQLite storage is required for received grant data.",
            ])
        }
        return try sqliteStore.loadData(named: "received_grants")
    }

