    private func normalizedDuplicateLookup(_ value: String) -> String {
        value
            .folding(options: [.diacriticInsensitive, .caseInsensitive], locale: .current)
            .replacingOccurrences(of: #"\s+"#, with: " ", options: .regularExpression)
            .trimmingCharacters(in: .whitespacesAndNewlines)
            .lowercased()
    }

    func restoreArchivedEnvelope(_ envelope: ArchivedRecordEnvelope) throws -> ChangeRefreshScope {
        // envelope.relatedDocumentStates holds whole-collection snapshots
        // captured at deletion time. They are deliberately NOT replayed:
        // doing so reverted every same-kind record to that moment - erasing
        // records created since and undoing later edits. The per-record
        // upsert below is the restore; the snapshots remain in the archive
        // payload for forensics only.
        switch envelope.kind {
        case "retired-calendar-vertical-note":
            let note = try JSONDecoder().decode(CalendarVerticalNoteRecord.self, from: envelope.payload)
            var notes = metadata.calendarVerticalNoteRecords ?? []
            if let index = notes.firstIndex(where: { $0.id == note.id }) {
                notes[index] = note
            } else {
                notes.append(note)
            }
            metadata.calendarVerticalNoteRecords = notes
            return .all
        case "application":
            var application = try JSONDecoder().decode(GrantApplication.self, from: envelope.payload)
            application.refreshDerivedValues()
            if let index = applications.firstIndex(where: { $0.id == application.id }) {
                applications[index] = application
            } else {
                applications.insert(application, at: 0)
            }
            return .applications
        case "organization", "manager":
            let organization = try JSONDecoder().decode(OrganizationRecord.self, from: envelope.payload)
            if let index = organizations.firstIndex(where: { $0.id == organization.id }) {
                organizations[index] = organization
            } else {
                organizations.append(organization)
            }
            return .organizations
        case "project":
            var project = try JSONDecoder().decode(ProjectRecord.self, from: envelope.payload)
            project.isArchived = false
            if let index = projects.firstIndex(where: { $0.id == project.id }) {
                projects[index] = project
            } else {
                projects.append(project)
            }
            return .projects
        case "teaching_course":
            let course = try JSONDecoder().decode(TeachingCourse.self, from: envelope.payload)
            if let index = teachingCourses.firstIndex(where: { $0.id == course.id }) {
                teachingCourses[index] = course
            } else {
                teachingCourses.append(course)
            }
            return .teaching
        case "teaching_component":
            let component = try JSONDecoder().decode(TeachingComponent.self, from: envelope.payload)
            if let index = teachingComponents.firstIndex(where: { $0.id == component.id }) {
                teachingComponents[index] = component
            } else {
                teachingComponents.append(component)
            }
            return .teaching
        case "teaching_format":
            let format = try JSONDecoder().decode(TeachingFormatOption.self, from: envelope.payload)
            if let index = teachingFormats.firstIndex(where: { $0.id == format.id }) {
                teachingFormats[index] = format
            } else {
                teachingFormats.append(format)
            }
            return .teaching
        case "teaching_assignment":
            let assignment = try JSONDecoder().decode(TeachingAssignment.self, from: envelope.payload)
            if let index = teachingAssignments.firstIndex(where: { $0.id == assignment.id }) {
                teachingAssignments[index] = assignment
            } else {
                teachingAssignments.append(assignment)
            }
            return .teaching
        case "doctoral_candidate":
            let candidate = try JSONDecoder().decode(DoctoralCandidateRecord.self, from: envelope.payload)
            if let index = doctoralCandidates.firstIndex(where: { $0.id == candidate.id }) {
                doctoralCandidates[index] = candidate
            } else {
                doctoralCandidates.append(candidate)
            }
            return .teaching
        case "publication_author":
            let author = try JSONDecoder().decode(PublicationAuthor.self, from: envelope.payload)
            if let index = publicationAuthors.firstIndex(where: { $0.id == author.id }) {
                publicationAuthors[index] = author
            } else {
                publicationAuthors.append(author)
            }
            return .publications
        case "publication_journal":
            let journal = try JSONDecoder().decode(PublicationJournal.self, from: envelope.payload)
            if let index = publicationJournals.firstIndex(where: { $0.id == journal.id }) {
                publicationJournals[index] = journal
            } else {
                publicationJournals.append(journal)
            }
            return .publications
        case "publication_record":
            let record = try JSONDecoder().decode(PublicationRecord.self, from: envelope.payload)
            if let index = publicationRecords.firstIndex(where: { $0.id == record.id }) {
                publicationRecords[index] = record
            } else {
                publicationRecords.append(record)
            }
            return .publicationRecords
        case "cv_conference_contribution":
            let contribution = try JSONDecoder().decode(CVConferenceContribution.self, from: envelope.payload)
            if let index = cvConferenceContributions.firstIndex(where: { $0.id == contribution.id }) {
                cvConferenceContributions[index] = contribution
            } else {
                cvConferenceContributions.append(contribution)
            }
            return .cv
        case "cv_media_appearance":
            let media = try JSONDecoder().decode(CVMediaAppearance.self, from: envelope.payload)
            if let index = cvMediaAppearances.firstIndex(where: { $0.id == media.id }) {
                cvMediaAppearances[index] = media
            } else {
                cvMediaAppearances.append(media)
            }
            return .cv
        case "cv_review_entry":
            let review = try JSONDecoder().decode(CVReviewEntry.self, from: envelope.payload)
            if let index = cvReviewEntries.firstIndex(where: { $0.id == review.id }) {
                cvReviewEntries[index] = review
            } else {
                cvReviewEntries.append(review)
            }
            return .cv
        case "cv_other_publication":
            let other = try JSONDecoder().decode(CVOtherPublicationEntry.self, from: envelope.payload)
            if let index = cvOtherPublications.firstIndex(where: { $0.id == other.id }) {
                cvOtherPublications[index] = other
            } else {
                cvOtherPublications.append(other)
            }
            return .cv
        default:
            throw NSError(domain: "Footprint.Archive", code: 1, userInfo: [
                NSLocalizedDescriptionKey: language.text("Unknown archived record type.", "Okänd arkivtyp.")
            ])
        }
    }

    func refreshOptionListsFromApplications(preserveCustomLists: Bool) {
        synchronizeOrganizationsAndManagers(preserveCustomLists: preserveCustomLists)

        // "Alla kopplingar via id": an application that points to a project
        // stands for that project, so an old written name never becomes a
        // project of its own.
        let projectNames = Set(applications.compactMap { linkedProjectKey(for: $0) })
        projects = preserveCustomLists
            ? mergeLocalizedOptions(existing: projects, canonicalNames: projectNames)
            : projectNames.sorted { $0.localizedStandardCompare($1) == .orderedAscending }.map {
                ProjectRecord(id: StableRecordID.legacy(prefix: "project", name: $0), nameSv: $0, nameEn: $0, isArchived: false)
            }
    }

    private func synchronizeOrganizationsAndManagers(preserveCustomLists: Bool) {
        // "Alla kopplingar via id": the organizations the applications point
        // to; only written names without a link can add an organization.
        let funderNames = Set(applications.compactMap { linkedOrganizationKey(for: $0) })
        let managerNames = Set(applications.compactMap { application in
            organization(id: application.applicationManagerID)?.nameSv.nonEmpty
                ?? linkedManagerKey(for: application)
        })
            .union(managers.compactMap(\.nameSv.nonEmpty))

        organizations = preserveCustomLists
            ? mergeOrganizations(existing: organizations, legacyManagers: managers, canonicalFunders: funderNames, canonicalManagers: managerNames)
            : mergedOrganizationsFromScratch(canonicalFunders: funderNames, canonicalManagers: managerNames)

        managers = derivedManagers(from: organizations)
    }

    private func mergeOrganizations(
        existing: [OrganizationRecord],
        legacyManagers: [ManagerOption],
        canonicalFunders: Set<String>,
        canonicalManagers: Set<String>
    ) -> [OrganizationRecord] {
        var mergedByName: [String: OrganizationRecord] = [:]

        for option in existing {
            guard let name = option.nameSv.nonEmpty else { continue }
            var normalized = option
            normalized.category = derivedOrganizationCategory(
                city: normalized.city,
                country: normalized.country,
                fallback: normalized.category
            )
            normalized.note = normalized.note?.trimmedOrNil
            normalized.roles = normalizedRoles(from: normalized.roles)
            mergedByName[name] = normalized
        }

        // User decision: an organization only gets the role its use in an
        // application requires (fund manager / grant provider); other roles
        // are ticked by hand. Nothing is guessed from the name (F40).

        for manager in legacyManagers {
            guard let name = manager.nameSv.nonEmpty else { continue }
            var option = mergedByName[name] ?? OrganizationRecord(id: manager.id, nameSv: name, nameEn: manager.nameEn.nonEmpty ?? name)
            option.nameEn = option.nameEn.nonEmpty ?? manager.nameEn.nonEmpty ?? name
            option.note = option.note?.trimmedOrNil ?? manager.reason?.trimmedOrNil
            option.salaryCalculator = option.salaryCalculator ?? manager.salaryCalculator
            option.category = derivedOrganizationCategory(city: option.city, country: option.country, fallback: option.category)
            option.roles = normalizedRoles(from: Array(Set(option.roles).union([.fundManager])))
            mergedByName[name] = option
        }

        for name in canonicalFunders {
            var option = mergedByName[name] ?? OrganizationRecord(id: StableRecordID.legacy(prefix: "organization", name: name), nameSv: name, nameEn: name)
            option.category = derivedOrganizationCategory(city: option.city, country: option.country, fallback: option.category)
            option.roles = normalizedRoles(from: Array(Set(option.roles).union([.grantProvider])))
            mergedByName[name] = option
        }

        for name in canonicalManagers {
            var option = mergedByName[name] ?? OrganizationRecord(id: StableRecordID.legacy(prefix: "organization", name: name), nameSv: name, nameEn: name)
            option.category = derivedOrganizationCategory(city: option.city, country: option.country, fallback: option.category)
            option.roles = normalizedRoles(from: Array(Set(option.roles).union([.fundManager])))
            mergedByName[name] = option
        }

        return mergedByName.values
            .filter { $0.nameSv.nonEmpty != nil }
            .sorted { $0.nameSv.localizedStandardCompare($1.nameSv) == .orderedAscending }
    }

    private func mergedOrganizationsFromScratch(
        canonicalFunders: Set<String>,
        canonicalManagers: Set<String>
    ) -> [OrganizationRecord] {
        let names = canonicalFunders.union(canonicalManagers)
        return names
            .sorted { $0.localizedStandardCompare($1) == .orderedAscending }
            .map { name in
                let roles = inferredOrganizationRoles(
                    isGrantProvider: canonicalFunders.contains(name),
                    isFundManager: canonicalManagers.contains(name)
                )
                return OrganizationRecord(
                    id: StableRecordID.legacy(prefix: "organization", name: name),
                    nameSv: name,
                    nameEn: name,
                    category: nil,
                    roles: roles,
                    isArchived: false
                )
            }
    }

    /// The roles in the app's fixed order. No roles are added or removed
    /// because of an organization's name; the roles ticked on it count.
    private func normalizedRoles(from roles: [OrganizationRole]) -> [OrganizationRole] {
        let values = Set(roles)
        return OrganizationRole.allCases.filter(values.contains)
    }

    /// F40: a new organization from an application only gets the role the
    /// application gives it; other roles are ticked by hand.
    private func inferredOrganizationRoles(isGrantProvider: Bool, isFundManager: Bool) -> [OrganizationRole] {
        var roles: [OrganizationRole] = []
        if isGrantProvider {
            roles.append(.grantProvider)
        }
        if isFundManager {
            roles.append(.fundManager)
        }
        return normalizedRoles(from: roles)
    }

    private func derivedManagers(from organizations: [OrganizationRecord]) -> [ManagerOption] {
        organizations
            .filter { $0.roles.contains(.fundManager) }
            .map {
                ManagerOption(
                    id: $0.id,
                    nameSv: $0.nameSv,
                    nameEn: $0.nameEn,
                    reason: $0.note?.trimmedOrNil,
                    salaryCalculator: $0.salaryCalculator
                )
            }
            .sorted { $0.nameSv.localizedStandardCompare($1.nameSv) == .orderedAscending }
    }

    private func mergeLocalizedOptions(existing: [ProjectRecord], canonicalNames: Set<String>) -> [ProjectRecord] {
        let existingByName = Dictionary(firstWinsKeysWithValues: existing.map { ($0.nameSv, $0) })
        let merged = Set(existing.map(\.nameSv)).union(canonicalNames)
        return merged
            .compactMap { name in
                existingByName[name] ?? ProjectRecord(id: StableRecordID.legacy(prefix: "project", name: name), nameSv: name, nameEn: name, isArchived: false)
            }
            .filter { $0.nameSv.nonEmpty != nil }
            .sorted { $0.nameSv.localizedStandardCompare($1.nameSv) == .orderedAscending }
    }

    private func mergeManagerOptions(existing: [ManagerOption], canonicalNames: Set<String>) -> [ManagerOption] {
        let existingByName = Dictionary(firstWinsKeysWithValues: existing.map { ($0.nameSv, $0) })
        let merged = Set(existing.map(\.nameSv)).union(canonicalNames)
        return merged
            .compactMap { name in
                existingByName[name] ?? ManagerOption(id: StableRecordID.legacy(prefix: "manager", name: name), nameSv: name, nameEn: name, reason: nil)
            }
            .filter { $0.nameSv.nonEmpty != nil }
            .sorted { $0.nameSv.localizedStandardCompare($1.nameSv) == .orderedAscending }
    }

    private func uniqueOption(
        baseSv: String,
        baseEn: String,
        within list: [OrganizationRecord],
        city: String = "",
        country: String = "",
        category: String? = nil,
        roles: [OrganizationRole] = [],
        note: String? = nil,
        websiteURL: String = "",
        phoneNumber: String = "",
        flag: String = "",
        membershipFrom: String = "",
        membershipTo: String = "",
        congresses: [OrganizationCongress] = [],
        salaryCalculator: ManagerSalaryCalculator? = nil
    ) -> OrganizationRecord {
        var candidateSv = baseSv
        var candidateEn = baseEn
        var counter = 2
        let existing = Set(list.map(\.nameSv))

        while existing.contains(candidateSv) {
            candidateSv = "\(baseSv) \(counter)"
            candidateEn = "\(baseEn) \(counter)"
            counter += 1
        }

        return OrganizationRecord(
            nameSv: candidateSv,
            nameEn: candidateEn,
            city: city,
            country: country,
            category: category,
            roles: normalizedRoles(from: roles),
            note: note?.trimmedOrNil,
            websiteURL: websiteURL,
            phoneNumber: phoneNumber,
            flag: flag,
            membershipFrom: membershipFrom,
            membershipTo: membershipTo,
            congresses: congresses,
            salaryCalculator: salaryCalculator,
            projectTasks: [],
            isArchived: false
        )
    }

    private func uniqueOption(
        baseSv: String,
        baseEn: String,
        within list: [ProjectRecord]
    ) -> ProjectRecord {
        var candidateSv = baseSv
        var candidateEn = baseEn
        var counter = 2
        let existing = Set(list.map(\.nameSv))

        while existing.contains(candidateSv) {
            candidateSv = "\(baseSv) \(counter)"
            candidateEn = "\(baseEn) \(counter)"
            counter += 1
        }

        return ProjectRecord(nameSv: candidateSv, nameEn: candidateEn, isArchived: false)
    }

    private func uniqueManager(baseSv: String, baseEn: String, within list: [ManagerOption]) -> ManagerOption {
        var candidateSv = baseSv
        var candidateEn = baseEn
        var counter = 2
        let existing = Set(list.map(\.nameSv))

        while existing.contains(candidateSv) {
            candidateSv = "\(baseSv) \(counter)"
            candidateEn = "\(baseEn) \(counter)"
            counter += 1
        }

        return ManagerOption(nameSv: candidateSv, nameEn: candidateEn, reason: nil, salaryCalculator: nil)
    }

    private func normalizedOption(
        nameSv: String,
        nameEn: String,
        addressLine: String = "",
        postalCode: String = "",
        city: String = "",
        country: String = "",
        category: String? = nil,
        collaboratorNames: [String] = [],
        roles: [OrganizationRole] = [],
        note: String? = nil,
        websiteURL: String = "",
        phoneNumber: String = "",
        organizationNumber: String = "",
        vatNumber: String = "",
        employerContacts: [OrganizationEmployerContact] = [],
        flag: String = "",
        membershipFrom: String = "",
        membershipTo: String = "",
        congresses: [OrganizationCongress] = [],
        salaryCalculator: ManagerSalaryCalculator? = nil,
        projectTasks: [ProjectTaskItem] = [],
        fallback: String,
        excluding excludedValue: String,
        within list: [OrganizationRecord],
        isArchived: Bool = false
    ) -> OrganizationRecord {
        let trimmedSv = nameSv.trimmedOrNil ?? fallback
        let trimmedEn = nameEn.trimmedOrNil ?? trimmedSv
        let trimmedAddressLine = addressLine.trimmedOrNil ?? ""
        let trimmedPostalCode = postalCode.trimmedOrNil ?? ""
        let trimmedCity = city.trimmedOrNil ?? ""
        let trimmedCountry = country.trimmedOrNil ?? ""
        let derivedCategory = derivedOrganizationCategory(city: city, country: country, fallback: category)
        _ = collaboratorNames
        let trimmedNote = note?.trimmedOrNil
        let trimmedWebsiteURL = websiteURL.trimmedOrNil ?? ""
        let trimmedPhoneNumber = phoneNumber.trimmedOrNil ?? ""
        let trimmedOrganizationNumber = organizationNumber.trimmedOrNil ?? ""
        let trimmedVATNumber = vatNumber.trimmedOrNil ?? ""
        let normalizedEmployerContacts = employerContacts
            .map {
                OrganizationEmployerContact(
                    id: $0.id,
                    role: $0.role.trimmingCharacters(in: .whitespacesAndNewlines),
                    firstName: $0.firstName.trimmingCharacters(in: .whitespacesAndNewlines),
                    lastName: $0.lastName.trimmingCharacters(in: .whitespacesAndNewlines),
                    phone: $0.phone.trimmingCharacters(in: .whitespacesAndNewlines),
                    email: $0.email.trimmingCharacters(in: .whitespacesAndNewlines)
                )
            }
            .filter { !$0.isEmpty }
        let trimmedFlag = flag.trimmingCharacters(in: .whitespacesAndNewlines)
        let resolvedFlag = trimmedFlag.isEmpty
            ? (Self.flagEmoji(forCountryName: Self.canonicalCountryNameForDiagnostics(trimmedCountry)) ?? "")
            : trimmedFlag
        let trimmedMembershipFrom = membershipFrom.trimmedOrNil ?? ""
        let trimmedMembershipTo = membershipTo.trimmedOrNil ?? ""
        let normalizedCongresses = normalizedOrganizationCongresses(congresses)
        let resolvedRoles = normalizedRoles(from: roles)
        let existing = Set(list.map(\.nameSv)).subtracting([excludedValue])
        if !existing.contains(trimmedSv) {
            return OrganizationRecord(
                nameSv: trimmedSv,
                nameEn: trimmedEn,
                addressLine: trimmedAddressLine,
                postalCode: trimmedPostalCode,
                city: trimmedCity,
                country: trimmedCountry,
                category: derivedCategory,
                roles: resolvedRoles,
                note: trimmedNote,
                websiteURL: trimmedWebsiteURL,
                phoneNumber: trimmedPhoneNumber,
                organizationNumber: trimmedOrganizationNumber,
                vatNumber: trimmedVATNumber,
                employerContacts: normalizedEmployerContacts,
                flag: resolvedFlag,
                membershipFrom: trimmedMembershipFrom,
                membershipTo: trimmedMembershipTo,
                congresses: normalizedCongresses,
                salaryCalculator: salaryCalculator,
                projectTasks: projectTasks,
                isArchived: isArchived
            )
        }

        var counter = 2
        var candidateSv = "\(trimmedSv) \(counter)"
        while existing.contains(candidateSv) {
            counter += 1
            candidateSv = "\(trimmedSv) \(counter)"
        }
        return OrganizationRecord(
            nameSv: candidateSv,
            nameEn: trimmedEn,
            addressLine: trimmedAddressLine,
            postalCode: trimmedPostalCode,
            city: trimmedCity,
            country: trimmedCountry,
            category: derivedCategory,
            roles: normalizedRoles(from: roles),
            note: trimmedNote,
            websiteURL: trimmedWebsiteURL,
            phoneNumber: trimmedPhoneNumber,
            organizationNumber: trimmedOrganizationNumber,
            vatNumber: trimmedVATNumber,
            employerContacts: normalizedEmployerContacts,
            flag: resolvedFlag,
            membershipFrom: trimmedMembershipFrom,
            membershipTo: trimmedMembershipTo,
            congresses: normalizedCongresses,
            salaryCalculator: salaryCalculator,
            projectTasks: projectTasks,
            isArchived: isArchived
        )
    }

    private func normalizedOption(
        id: String = UUID().uuidString,
        nameSv: String,
        nameEn: String,
        fullNameSv: String = "",
        fullNameEn: String = "",
        collaboratorNames: [String] = [],
        collaboratorAuthorIDs: [String] = [],
        note: String? = nil,
        websiteURL: String = "",
        projectStatus: ProjectLifecycleStatus = .ongoing,
        hasDataCollection: Bool = false,
        ethicsBaseApplication: ProjectEthicsApplication = ProjectEthicsApplication(),
        ethicsAmendments: [ProjectEthicsApplication] = [],
        ethicsLink: String? = nil,
        clinicalTrialRegistrations: [ProjectClinicalTrialRegistration] = [],
        principalOrganizations: [ProjectPrincipalOrganization] = [],
        dataCollections: [ProjectDataCollection] = [],
        projectTasks: [ProjectTaskItem] = [],
        suppressedSeedProjectTaskComments: [String] = [],
        fallback: String,
        excluding excludedValue: String,
        within list: [ProjectRecord],
        isArchived: Bool = false,
        isEditingLocked: Bool = false,
        dismissedOngoingPromptKeys: [String]? = nil
    ) -> ProjectRecord {
        let trimmedSv = nameSv.trimmedOrNil ?? fallback
        let trimmedEn = nameEn.trimmedOrNil ?? trimmedSv
        let trimmedFullNameSv = fullNameSv.trimmedOrNil ?? ""
        let trimmedFullNameEn = fullNameEn.trimmedOrNil ?? ""
        let trimmedCollaborators = Array(NSOrderedSet(array: collaboratorNames.compactMap(\.trimmedOrNil))) as? [String] ?? []
        let trimmedNote = note?.trimmedOrNil
        let trimmedWebsiteURL = websiteURL.trimmedOrNil ?? ""
        let normalizedPrincipalOrganizations = principalOrganizations.compactMap { principal -> ProjectPrincipalOrganization? in
            var copy = principal
            copy.normalize()
            return copy.isEmpty ? nil : copy
        }
        let normalizedSuppressedSeedProjectTaskComments = Array(
            NSOrderedSet(array: suppressedSeedProjectTaskComments.compactMap { normalizedProjectTaskCommentKey($0) })
        ) as? [String] ?? []
        let existing = Set(list.map(\.nameSv)).subtracting([excludedValue])
        let resolvedSv: String
        if existing.contains(trimmedSv) {
            var counter = 2
            var candidateSv = "\(trimmedSv) \(counter)"
            while existing.contains(candidateSv) {
                counter += 1
                candidateSv = "\(trimmedSv) \(counter)"
            }
            resolvedSv = candidateSv
        } else {
            resolvedSv = trimmedSv
        }
        var linkedProjectTasks = projectTasks
        synchronizeTaskParticipantAuthorIDs(&linkedProjectTasks)

        return ProjectRecord(
            id: id,
            nameSv: resolvedSv,
            nameEn: trimmedEn,
            fullNameSv: trimmedFullNameSv,
            fullNameEn: trimmedFullNameEn,
            collaboratorNames: trimmedCollaborators,
            collaboratorAuthorIDs: synchronizedPersonAuthorIDs(existingIDs: collaboratorAuthorIDs, names: trimmedCollaborators),
            note: trimmedNote,
            websiteURL: trimmedWebsiteURL,
            projectStatus: isArchived ? .completed : projectStatus,
            hasDataCollection: hasDataCollection,
            ethicsBaseApplication: ethicsBaseApplication,
            ethicsAmendments: ethicsAmendments,
            ethicsLink: ethicsLink?.trimmedOrNil,
            clinicalTrialRegistrations: clinicalTrialRegistrations,
            principalOrganizations: normalizedPrincipalOrganizations,
            dataCollections: dataCollections.filter { !$0.isEmpty },
            projectTasks: linkedProjectTasks,
            suppressedSeedProjectTaskComments: normalizedSuppressedSeedProjectTaskComments,
            isArchived: isArchived,
            isEditingLocked: isEditingLocked,
            dismissedOngoingPromptKeys: dismissedOngoingPromptKeys
        )
    }

    private func normalizedOrganizationCongresses(_ congresses: [OrganizationCongress]) -> [OrganizationCongress] {
        persistedOrganizationCongresses(from: congresses)
    }

    private func organizationCongressSortOrder(_ lhs: OrganizationCongress, _ rhs: OrganizationCongress) -> Bool {
        func primaryDate(for congress: OrganizationCongress) -> Date? {
            [
                congress.from,
                congress.to,
                congress.abstractSubmissionDeadline,
                congress.lateAbstractSubmissionDeadline
            ]
            .compactMap { DateParsers.isoDay.date(from: $0) }
            .first
        }

        let leftDate = primaryDate(for: lhs)
        let rightDate = primaryDate(for: rhs)
        switch (leftDate, rightDate) {
        case let (left?, right?):
            if left != right {
                return left < right
            }
        case (.some, nil):
            return true
        case (nil, .some):
            return false
        case (nil, nil):
            break
        }

        let leftTitle = lhs.title.trimmingCharacters(in: .whitespacesAndNewlines)
        let rightTitle = rhs.title.trimmingCharacters(in: .whitespacesAndNewlines)
        let comparison = leftTitle.localizedStandardCompare(rightTitle)
        if comparison != .orderedSame {
            return comparison == .orderedAscending
        }
        return lhs.id < rhs.id
    }

    private func resolvedSuppressedSeedProjectTaskComments(
        previous: ProjectRecord,
        updatedTasks: [ProjectTaskItem]
    ) -> [String] {
        let updatedKeys = Set(updatedTasks.compactMap { normalizedProjectTaskCommentKey($0.comment) })
        let previousKeys = Set(previous.projectTasks.compactMap { normalizedProjectTaskCommentKey($0.comment) })
        var suppressedKeys = Set(previous.suppressedSeedProjectTaskComments.compactMap(normalizedProjectTaskCommentKey))
        suppressedKeys.formUnion(previousKeys.subtracting(updatedKeys))
        suppressedKeys.subtract(updatedKeys)
        return suppressedKeys.sorted()
    }

    private func normalizedProjectTaskCommentKey(_ value: String?) -> String? {
        value?
            .trimmingCharacters(in: .whitespacesAndNewlines)
            .nonEmpty?
            .folding(options: [.caseInsensitive, .diacriticInsensitive], locale: .current)
    }

    private func inferredOrganizationCategory(for organizationName: String) -> String? { nil }

    private func normalizedManager(
        nameSv: String,
        nameEn: String,
        reason: String?,
        salaryCalculator: ManagerSalaryCalculator?,
        fallback: String,
        excluding excludedValue: String,
        within list: [ManagerOption]
    ) -> ManagerOption {
        let trimmedSv = nameSv.trimmedOrNil ?? fallback
        let trimmedEn = nameEn.trimmedOrNil ?? trimmedSv
        let trimmedReason = reason?.trimmedOrNil
        let existing = Set(list.map(\.nameSv)).subtracting([excludedValue])
        if !existing.contains(trimmedSv) {
            return ManagerOption(nameSv: trimmedSv, nameEn: trimmedEn, reason: trimmedReason, salaryCalculator: salaryCalculator)
        }

        var counter = 2
        var candidateSv = "\(trimmedSv) \(counter)"
        while existing.contains(candidateSv) {
            counter += 1
            candidateSv = "\(trimmedSv) \(counter)"
        }
        return ManagerOption(nameSv: candidateSv, nameEn: trimmedEn, reason: trimmedReason, salaryCalculator: salaryCalculator)
    }

    func refreshPublicationRecords() {
        refreshPublicationRecords(normalizeLoadedCollections: true, deferExpensiveRefreshWork: true)
    }

    private func refreshPublicationRecords(
        normalizeLoadedCollections: Bool,
        deferExpensiveRefreshWork: Bool
    ) {
        if normalizeLoadedCollections {
            for index in publicationAuthors.indices {
                publicationAuthors[index].normalize()
            }

            for index in publicationJournals.indices {
                publicationJournals[index].normalize()
            }
        }
        sortPublicationAuthors()

        // Same whale as the round-6 application loop: with the presented-name
        // cache still empty right after load, every author resolution in the
        // derive loop below falls back to a full authors × name-variants
        // scan. Build the lookup caches once up front in that case.
        if publicationAuthorByPresentedName.isEmpty, !publicationAuthors.isEmpty {
            rebuildPublicationAuthorLookupCaches()
        }

        let deriveStartedAt = CFAbsoluteTimeGetCurrent()
        for index in publicationRecords.indices {
            publicationRecords[index].normalize()
            if publicationRecords[index].status.trimmingCharacters(in: .whitespacesAndNewlines) == PublicationStatus.planned.rawValue {
                publicationRecords[index].status = PublicationStatus.inPreparation.rawValue
            }
            publicationRecords[index] = derivePublicationFields(for: publicationRecords[index], previous: publicationRecords[index])
        }
        let summariesStartedAt = CFAbsoluteTimeGetCurrent()
        updatePublicationAuthorContributionSummaries()
        let sortStartedAt = CFAbsoluteTimeGetCurrent()
        sortPublicationJournalsIfNeeded()
        sortPublicationRecords()
        appendPerformanceDiagnosticIfSlow(
            { duration in
                String(
                    format: "publication-records-refresh derive_ms=%.1f summaries_ms=%.1f sort_ms=%.1f total_ms=%.1f",
                    (summariesStartedAt - deriveStartedAt) * 1000,
                    (sortStartedAt - summariesStartedAt) * 1000,
                    (CFAbsoluteTimeGetCurrent() - sortStartedAt) * 1000,
                    duration
                )
            },
            startedAt: deriveStartedAt,
            thresholdMs: 40
        )
        if deferExpensiveRefreshWork {
            refreshPublicationIndexes(mode: .crossReferencesOnly, projectCacheBehavior: .markDirty)
            scheduleDeferredFullPublicationIndexRefresh(reason: "publication-records-refresh")
            scheduleDataQualityCachePrewarm(reason: "publication-records-refresh")
        } else {
            refreshPublicationIndexes(mode: .full, projectCacheBehavior: .markDirty)
            appendPerformanceDiagnostic("publication-bootstrap-refresh mode=single-full")
        }
    }

    private func refreshPublicationRecordsOnly() {
        for index in publicationRecords.indices {
            publicationRecords[index].normalize()
            if publicationRecords[index].status.trimmingCharacters(in: .whitespacesAndNewlines) == PublicationStatus.planned.rawValue {
                publicationRecords[index].status = PublicationStatus.inPreparation.rawValue
            }
            publicationRecords[index] = derivePublicationFields(for: publicationRecords[index], previous: publicationRecords[index])
        }
        refreshPublicationRecordCaches(projectCacheBehavior: .markDirty)
    }

    private func refreshPublicationAuthorsOnly() {
        for index in publicationAuthors.indices {
            publicationAuthors[index].normalize()
        }
        sortPublicationAuthors()
        rebuildPublicationAuthorLookupCaches()
        publicationAuthorOptionNames = publicationAuthorAutocompleteOptionNames()
        rebuildPublicationAuthorRowSnapshots()
    }

    private func rebuildPublicationAuthorLookupCaches() {
        publicationAuthorByID = publicationAuthors.reduce(into: [:]) { $0[$1.id] = $1 }
        publicationAuthorByName = publicationAuthors.reduce(into: [:]) { $0[$1.name] = $1 }
        publicationAuthorByPresentedName = publicationAuthors.reduce(into: [:]) { partialResult, author in
            for candidate in author.presentedNameCandidates {
                let key = normalizedPersonLookupName(candidate)
                if !key.isEmpty, partialResult[key] == nil {
                    partialResult[key] = author
                }
            }
        }
        publicationAuthorPresentedNameMissCache.removeAll(keepingCapacity: true)
        cachedUnlinkedPersonNames = nil
    }

    private func publicationAuthorAutocompleteOptionNames() -> [String] {
        var seenKeys = Set<String>()
        var options: [String] = []

        func append(_ candidate: String) {
            guard let trimmed = candidate.trimmedOrNil else { return }
            let key = normalizedPersonLookupName(trimmed)
            guard !key.isEmpty, seenKeys.insert(key).inserted else { return }
            options.append(trimmed)
        }

        for author in publicationAuthors {
            append(author.name)
        }
        for author in publicationAuthors {
            for variant in author.nameVariants {
                append(variant)
            }
        }
        return options
    }

    private func sortPublicationAuthors() {
        let currentAuthorID = currentUserAuthor()?.id
        publicationAuthors.sort {
            let lhsIsCurrent = $0.id == currentAuthorID
            let rhsIsCurrent = $1.id == currentAuthorID
            if lhsIsCurrent != rhsIsCurrent {
                return lhsIsCurrent && !rhsIsCurrent
            }
            return $0.sortName.localizedStandardCompare($1.sortName) == .orderedAscending
        }
    }

    private func sortPublicationJournalsIfNeeded() {
        let isAlreadySorted = zip(publicationJournals, publicationJournals.dropFirst()).allSatisfy {
            $0.name.localizedStandardCompare($1.name) != .orderedDescending
        }
        guard !isAlreadySorted else { return }
        publicationJournals.sort { $0.name.localizedStandardCompare($1.name) == .orderedAscending }
    }

    private func refreshPublicationJournalsState(projectCacheBehavior: ProjectCacheRefreshBehavior) {
        sortPublicationJournalsIfNeeded()
        refreshPublicationDerivedIndexes(projectCacheBehavior: projectCacheBehavior)
    }

    private func refreshPublicationJournalAutosaveState(updatedJournalID: String) {
        sortPublicationJournalsIfNeeded()
        refreshPublicationDerivedIndexes(projectCacheBehavior: .skip, mode: .crossReferencesOnly)
        refreshPublicationJournalRowSnapshot(for: updatedJournalID)
    }

    private func refreshPublicationRecordCaches(projectCacheBehavior: ProjectCacheRefreshBehavior) {
        updatePublicationAuthorContributionSummaries()
        sortPublicationRecords()
        refreshPublicationDerivedIndexes(projectCacheBehavior: projectCacheBehavior)
    }

    private func refreshPublicationRecordCaches(afterUpdating updated: PublicationRecord, previous: PublicationRecord) {
        updatePublicationAuthorContributionSummaries(forAuthorNames: Set(previous.authorNames + updated.authorNames))
        sortPublicationRecords()
        // Autosave ticks pay only the cross-reference pass; the full pass
        // (support caches, linked entries, org rows) rides the existing
        // deferred refresh so typing in the publication editor never
        // waits on it.
        refreshPublicationDerivedIndexes(
            projectCacheBehavior: publicationProjectCacheRefreshBehavior(afterUpdating: updated, previous: previous),
            mode: .crossReferencesOnly
        )
        // Keep the editor's own submission rows fresh without a full pass.
        publicationSubmissionRowsByID[updated.id] = derivedSubmissionRows(for: updated)
        scheduleDeferredFullPublicationIndexRefresh(reason: "publication-autosave")
    }

    private func updatePublicationAuthorContributionSummaries() {
        let startedAt = CFAbsoluteTimeGetCurrent()
        let titleReferencesByAuthorKey = publicationTitleReferencesByAuthorKey()
        for index in publicationAuthors.indices {
            let variants = authorNameVariants(for: publicationAuthors[index])
            let variantKeys = Set(variants.map(normalizedPersonLookupName).filter { !$0.isEmpty })
            let references = variantKeys.reduce(into: Set<PublicationTitleReference>()) { partialResult, key in
                partialResult.formUnion(titleReferencesByAuthorKey[key] ?? [])
            }
            let counts = Dictionary(grouping: references, by: \.title).mapValues(\.count)
            publicationAuthors[index].publications = counts.keys.sorted { $0.localizedStandardCompare($1) == .orderedAscending }.map {
                PublicationAuthorContribution(title: $0, count: counts[$0] ?? 0)
            }
        }
        appendPerformanceDiagnosticIfSlow(
            { duration in
                String(
                    format: "publication-author-contributions mode=full authors=%ld publications=%ld total_ms=%.2f",
                    publicationAuthors.count,
                    publicationRecords.count,
                    duration
                )
            },
            startedAt: startedAt,
            thresholdMs: 10
        )
    }

    private func updatePublicationAuthorContributionSummaries(forAuthorNames names: Set<String>) {
        guard !names.isEmpty else { return }
        let trimmedNames = Set(names.compactMap(\.trimmedOrNil))
        guard !trimmedNames.isEmpty else { return }
        let startedAt = CFAbsoluteTimeGetCurrent()
        let titleReferencesByAuthorKey = publicationTitleReferencesByAuthorKey()
        let touchedNameKeys = Set(trimmedNames.map(normalizedPersonLookupName).filter { !$0.isEmpty })

        for index in publicationAuthors.indices {
            let variants = authorNameVariants(for: publicationAuthors[index])
            let variantKeys = Set(variants.map(normalizedPersonLookupName).filter { !$0.isEmpty })
            guard !touchedNameKeys.isDisjoint(with: variantKeys) else { continue }

            let references = variantKeys.reduce(into: Set<PublicationTitleReference>()) { partialResult, key in
                partialResult.formUnion(titleReferencesByAuthorKey[key] ?? [])
            }
            let counts = Dictionary(grouping: references, by: \.title).mapValues(\.count)
            publicationAuthors[index].publications = counts.keys.sorted { $0.localizedStandardCompare($1) == .orderedAscending }.map {
                PublicationAuthorContribution(title: $0, count: counts[$0] ?? 0)
            }
        }
        appendPerformanceDiagnosticIfSlow(
            { duration in
                String(
                    format: "publication-author-contributions mode=partial touched=%ld authors=%ld publications=%ld total_ms=%.2f",
                    touchedNameKeys.count,
                    publicationAuthors.count,
                    publicationRecords.count,
                    duration
                )
            },
            startedAt: startedAt,
            thresholdMs: 8
        )
    }

    private func publicationTitleReferencesByAuthorKey() -> [String: Set<PublicationTitleReference>] {
        publicationRecords.reduce(into: [:]) { partialResult, record in
            let reference = PublicationTitleReference(recordID: record.id, title: record.title)
            let authorKeys = Set(record.authorNames.map(normalizedPersonLookupName).filter { !$0.isEmpty })
            for key in authorKeys {
                partialResult[key, default: []].insert(reference)
            }
        }
    }

    private func sortPublicationRecords() {
        publicationRecords.sort {
            if $0.sortYear == $1.sortYear {
                return $0.title.localizedStandardCompare($1.title) == .orderedAscending
            }
            return $0.sortYear > $1.sortYear
        }
    }

    private func rebuildLocalizedRowSnapshots() {
        let startedAt = CFAbsoluteTimeGetCurrent()
        rebuildApplicationRowSnapshots()
        let afterApplications = CFAbsoluteTimeGetCurrent()
        rebuildPublicationAuthorRowSnapshots()
        let afterAuthors = CFAbsoluteTimeGetCurrent()
        rebuildPublicationJournalRowSnapshots()
        let afterJournals = CFAbsoluteTimeGetCurrent()
        rebuildProjectRowSnapshots()
        let afterProjects = CFAbsoluteTimeGetCurrent()
        rebuildOrganizationRowSnapshots()
        let finishedAt = CFAbsoluteTimeGetCurrent()
        let totalDuration = (finishedAt - startedAt) * 1000
        if totalDuration > 25 {
            appendPerformanceDiagnostic(
                String(
                    format: "row-snapshots-rebuild total_ms=%.2f applications_ms=%.2f authors_ms=%.2f journals_ms=%.2f projects_ms=%.2f organizations_ms=%.2f",
                    totalDuration,
                    (afterApplications - startedAt) * 1000,
                    (afterAuthors - afterApplications) * 1000,
                    (afterJournals - afterAuthors) * 1000,
                    (afterProjects - afterJournals) * 1000,
                    (finishedAt - afterProjects) * 1000
                )
            )
        }
    }

    private func rebuildApplicationRowSnapshots() {
        let startedAt = CFAbsoluteTimeGetCurrent()
        let language = language
        let calendar = Calendar.current
        let today = calendar.startOfDay(for: Date())
        let passedUnansweredText = language.text("Answer", "Svara")
        let snapshots = applications.map { application -> ApplicationRowSnapshot in
            let organizationLabel = organizationLabel(for: application, language: language)
            let grantNameLabel = localizedGrantName(for: application, language: language)
            let projectDisplayLabel = self.projectLabel(for: application, language: language) ?? ""
            let currentUserIsFirstApplicant = isCurrentUserFirstApplicant(application)
            let isFullySpent = isEffectivelyFullySpent(application)
            let searchBlob = [
                organizationLabel,
                grantNameLabel,
                application.grantCategory,
                application.resultLabel,
                // Round 16: the status names in both languages are searchable.
                ApplicationStatusCanonical.searchLabels(for: application.resultLabel).joined(separator: " "),
                projectDisplayLabel,
                application.applicationManager,
                application.managerReason,
                application.applicationTitle,
                application.coApplicants.joined(separator: " "),
                application.applicantCriteria,
                application.projectCriteria,
                application.maxAmount,
                application.appliedCaseNumber,
                application.employmentPercentage,
                application.employmentMonths,
                application.approximateAmount,
                application.receivedProjectNumber,
                application.receivedDisplayName,
                application.receivedPEOE,
                application.receivedConsumedAmount,
                application.receivedConsumptionPeriods.map(\.amount).joined(separator: " ")
            ]
            .compactMap { $0?.trimmingCharacters(in: .whitespacesAndNewlines).nonEmpty }
            .joined(separator: " ")

            let closeText = {
                if let closesOn = application.closesOn,
                   let date = DateParsers.isoDay.date(from: closesOn) {
                    let closeDay = calendar.startOfDay(for: date)
                    guard closeDay >= today else {
                        // Passed but still "Att söka": the answer is missing.
                        return application.isToApplyStatus ? passedUnansweredText : ""
                    }
                    let days = calendar.dateComponents([.day], from: today, to: closeDay).day ?? 0
                    let base = String(days)
                    guard application.closesOnUncertain else { return base }
                    return "\(base) *"
                }
                let base = application.closesOn ?? ""
                guard application.closesOnUncertain, !base.isEmpty else { return base }
                return "\(base) *"
            }()

            let isBeforeOpening: Bool = {
                guard let opens = application.opensOn.flatMap(DateParsers.isoDay.date(from:)) else { return false }
                let opensDay = calendar.startOfDay(for: opens)
                return opensDay > today
            }()

            return ApplicationRowSnapshot(
                id: application.id,
                selectionID: applicationSelectionID(for: application),
                organizationLabel: organizationLabel,
                grantNameLabel: grantNameLabel,
                closesText: closeText,
                closeDate: application.closeDate,
                closesOnUncertain: application.closesOnUncertain,
                projectLabel: projectDisplayLabel,
                projectID: application.projectID,
                projectName: application.projectType,
                appliedCaseNumber: application.appliedCaseNumber ?? "",
                maximumAmountText: formattedGrantAmountWithSEKApproximation(application.preferredBudgetAmountValue, for: application),
                resultLabel: application.resultLabel,
                isGranted: application.isGranted,
                isFullySpent: isFullySpent,
                isToApplyStatus: application.isToApplyStatus,
                isBeforeOpening: isBeforeOpening,
                isCurrentUserFirstApplicant: currentUserIsFirstApplicant,
                applicationYear: Int(application.statsYear) ?? Calendar.current.component(.year, from: Date()),
                budgetAmount: grantStatisticsAmountInSEK(for: application, amount: application.preferredBudgetAmountValue),
                sortOrganization: organizationLabel,
                sortGrantName: grantNameLabel,
                sortClosesOn: application.sortClosesOn,
                sortProject: projectDisplayLabel,
                sortAppliedCaseNumber: application.sortAppliedCaseNumber,
                sortMaximumAmount: grantStatisticsAmountInSEK(for: application, amount: application.preferredBudgetAmountValue),
                normalizedSearchBlob: normalizedSearchFilterText(searchBlob),
                isEditingLocked: application.isEditingLocked
            )
        }

        if snapshots != applicationRowSnapshotsCache {
            applicationRowSnapshotsCache = snapshots
            applicationRowSnapshotGeneration &+= 1
        }
        appendPerformanceDiagnosticIfSlow(
            { duration in
                String(format: "application-row-snapshots rows=%ld total_ms=%.2f", applications.count, duration)
            },
            startedAt: startedAt,
            thresholdMs: 8
        )
    }

    private func rebuildPublicationAuthorRowSnapshots() {
        let startedAt = CFAbsoluteTimeGetCurrent()
        let currentAuthorID = currentUserAuthor()?.id
        let targetLanguage = language
        let homeCountry = homeCountryName
        let snapshots = publicationAuthors.map { author -> PublicationAuthorRowSnapshot in
            let primaryOrganization = author.primaryAffiliation?.localizedOrganization(language: targetLanguage) ?? ""
            let affiliationOrganizations = author.affiliations
                .compactMap { $0.localizedOrganization(language: targetLanguage).nonEmpty }
                .uniqued()
                .sorted { $0.localizedStandardCompare($1) == .orderedAscending }
            let primaryCountry = author.primaryCountry.trimmedOrNil ?? ""
            let affiliationSearchTerms = author.affiliations.flatMap { affiliation in
                [
                    affiliation.localizedOrganization(language: targetLanguage),
                    affiliation.organizationSv,
                    affiliation.organizationEn,
                    affiliation.localizedDepartment(language: targetLanguage),
                    affiliation.departmentSv,
                    affiliation.departmentEn,
                    affiliation.city,
                    affiliation.country,
                    affiliation.email
                ]
                .compactMap(\.nonEmpty)
            }
            let searchBlob = ([
                author.name,
                author.displaySubtitle,
                author.nameVariants.joined(separator: " "),
                primaryOrganization,
                primaryCountry,
                author.localizedTitle(language: targetLanguage),
                author.localizedPosition(language: targetLanguage),
                author.localizedDegree(language: targetLanguage)
            ] + affiliationSearchTerms)
            .compactMap(\.nonEmpty)
            .joined(separator: " ")
            return PublicationAuthorRowSnapshot(
                id: author.id,
                sortName: author.sortName,
                sortOrganization: normalizedSearchFilterText(primaryOrganization),
                displayName: author.displayName,
                displaySubtitle: author.displaySubtitle,
                primaryOrganization: primaryOrganization,
                affiliationOrganizations: affiliationOrganizations,
                primaryCountry: primaryCountry,
                countryFlags: author.affiliations.compactMap { affiliation in
                    let canonical = Self.canonicalCountryNameForDiagnostics(affiliation.country)
                    guard canonical.caseInsensitiveCompare(homeCountry) != .orderedSame else { return nil }
                    return Self.flagEmoji(forCountryName: canonical)
                }
                .uniqued(),
                isCurrentUser: author.id == currentAuthorID,
                projectCount: projectCount(forAuthorID: author.id),
                grantCount: grantCount(forAuthorID: author.id),
                publicationCount: author.publicationCount,
                disseminationCount: disseminationCount(forAuthorID: author.id),
                expertAssignmentCount: expertAssignmentCount(forAuthorID: author.id),
                teachingCount: teachingCount(forAuthorID: author.id),
                normalizedSearchBlob: normalizedSearchFilterText(searchBlob),
                missingORCID: author.orcid.trimmedOrNil == nil,
                missingEmail: author.primaryAffiliation?.email.trimmedOrNil == nil,
                missingPrimaryOrganization: author.primaryAffiliation?.organization.trimmedOrNil == nil,
                missingPrimaryCountry: author.primaryAffiliation?.country.trimmedOrNil == nil,
                missingTitle: author.title.trimmedOrNil == nil
            )
        }

        if snapshots != publicationAuthorRowSnapshotsCache {
            publicationAuthorRowSnapshotsCache = snapshots
            publicationAuthorRowSnapshotGeneration &+= 1
        }
        appendPerformanceDiagnosticIfSlow(
            { duration in
                String(format: "publication-author-row-snapshots rows=%ld total_ms=%.2f", publicationAuthors.count, duration)
            },
            startedAt: startedAt,
            thresholdMs: 8
        )
    }

    private func rebuildPublicationJournalRowSnapshots() {
        let startedAt = beginMainThreadActivity("journal-row-snapshots-sync")
        let snapshots = Self.publicationJournalRowSnapshots(
            journals: publicationJournals,
            derivedMetricsByID: journalDerivedMetricsByIDCache,
            acceptanceStatsByName: journalAcceptanceStatsByNameCache
        )

        if snapshots != publicationJournalRowSnapshotsCache {
            publicationJournalRowSnapshotsCache = snapshots
            publicationJournalRowSnapshotGeneration &+= 1
        }
        publicationJournalRowSnapshotsAreStale = false
        publicationJournalRowSnapshotTask?.cancel()
        publicationJournalRowSnapshotTask = nil
        endMainThreadActivity("journal-row-snapshots-sync", startedAt: startedAt)
        appendPerformanceDiagnosticIfSlow(
            { duration in
                String(format: "publication-journal-row-snapshots rows=%ld total_ms=%.2f", publicationJournals.count, duration)
            },
            startedAt: startedAt,
            thresholdMs: 8
        )
    }

    private func refreshPublicationJournalRowSnapshot(for journalID: String) {
        guard !publicationJournalRowSnapshotsAreStale,
              publicationJournalRowSnapshotsCache.count == publicationJournals.count,
              let journal = publicationJournals.first(where: { $0.id == journalID }),
              let snapshotIndex = publicationJournalRowSnapshotsCache.firstIndex(where: { $0.id == journalID }) else {
            rebuildPublicationJournalRowSnapshots()
            return
        }

        let startedAt = CFAbsoluteTimeGetCurrent()
        let snapshot = Self.publicationJournalRowSnapshot(
            for: journal,
            derivedMetricsByID: journalDerivedMetricsByIDCache,
            acceptanceStatsByName: journalAcceptanceStatsByNameCache
        )
        guard publicationJournalRowSnapshotsCache[snapshotIndex] != snapshot else {
            appendPerformanceDiagnosticIfSlow(
                { duration in
                    String(format: "publication-journal-row-snapshot mode=incremental changed=no total_ms=%.2f", duration)
                },
                startedAt: startedAt,
                thresholdMs: 8
            )
            return
        }
        publicationJournalRowSnapshotsCache[snapshotIndex] = snapshot
        publicationJournalRowSnapshotGeneration &+= 1
        appendPerformanceDiagnosticIfSlow(
            { duration in
                String(format: "publication-journal-row-snapshot mode=incremental changed=yes total_ms=%.2f", duration)
            },
            startedAt: startedAt,
            thresholdMs: 8
        )
    }

    nonisolated private static func publicationJournalRowSnapshots(
        journals: [PublicationJournal],
        derivedMetricsByID: [String: PublicationJournalDerivedMetrics],
        acceptanceStatsByName: [String: JournalAcceptanceStats]
    ) -> [PublicationJournalRowSnapshot] {
        journals.map { journal in
            publicationJournalRowSnapshot(
                for: journal,
                derivedMetricsByID: derivedMetricsByID,
                acceptanceStatsByName: acceptanceStatsByName
            )
        }
    }

    nonisolated private static func publicationJournalRowSnapshot(
        for journal: PublicationJournal,
        derivedMetricsByID: [String: PublicationJournalDerivedMetrics],
        acceptanceStatsByName: [String: JournalAcceptanceStats]
    ) -> PublicationJournalRowSnapshot {
        let mergedCategory = mergedJournalFilterCategory(journal.category)
        let mergedSubcategory = mergedJournalFilterCategory(journal.subcategory)
        let categories = ([mergedCategory, mergedSubcategory] + journal.categories.compactMap(mergedJournalFilterCategory))
            .compactMap { $0?.trimmedOrNil }
            .uniqued()
        let subtitle = categories.prefix(2).joined(separator: " · ")
        // List filtering must not synthesize LTWA abbreviations for all 3,000+
        // journals. That fallback is intentionally reserved for the editor and
        // exports; stored abbreviations already cover searchable journal data.
        let searchableAbbreviation = journal.issnLTWAAbbreviatedName.trimmedOrNil
            ?? journal.abbreviatedName.trimmedOrNil
        let filterSearchBlob = [
            journal.name,
            journal.abbreviatedName,
            searchableAbbreviation,
            journal.category,
            journal.subcategory,
            mergedCategory,
            mergedSubcategory,
            categories.joined(separator: " "),
        ]
        .compactMap { $0?.trimmedOrNil }
        .joined(separator: " ")
        let extendedFilterSearchBlob = [
            filterSearchBlob,
            journal.publisher,
            journal.journalURL,
        ]
        .compactMap { $0?.trimmedOrNil }
        .joined(separator: " ")
        let derivedMetrics = derivedMetricsByID[journal.id]
        let latestImpactFactorMetric = derivedMetrics?.latestImpactFactorMetric
            ?? journal.preferredMetric(for: [.clarivateScieJIF, .clarivateEsciJIF], publicationYear: nil)
        let latestNorwegianMetric = derivedMetrics?.latestNorwegianMetric
            ?? journal.preferredMetric(for: [.norwegianList], publicationYear: nil)
        let stats = acceptanceStatsByName[journal.name] ?? JournalAcceptanceStats()
        return PublicationJournalRowSnapshot(
            id: journal.id,
            name: journal.name,
            subtitle: subtitle,
            categories: categories,
            categorySet: Set(categories),
            filterSearchBlob: filterSearchBlob,
            normalizedFilterSearchBlob: normalizedSearchFilterText(filterSearchBlob),
            extendedFilterSearchBlob: extendedFilterSearchBlob,
            normalizedExtendedFilterSearchBlob: normalizedSearchFilterText(extendedFilterSearchBlob),
            latestImpactFactorValue: derivedMetrics?.latestImpactFactorValue ?? journal.latestImpactFactorValue,
            latestNorwegianLevelValue: derivedMetrics?.latestNorwegianLevelValue ?? journal.latestNorwegianLevelValue,
            hasPreviousSubmission: stats.submittedCount > 0,
            hasPreviousPublication: stats.publishedCount > 0,
            jifMetric: latestImpactFactorMetric,
            norwegianMetric: latestNorwegianMetric,
            acceptanceText: stats.displayText,
            acceptanceSortValue: stats.sortValue
        )
    }

    private func invalidatePublicationJournalRowSnapshots() {
        publicationJournalRowSnapshotsAreStale = true
        publicationJournalRowSnapshotGeneration &+= 1
        publicationJournalRowSnapshotBuildToken &+= 1
        publicationJournalRowSnapshotTask?.cancel()
        publicationJournalRowSnapshotTask = nil
    }

    private func rebuildProjectRowSnapshots() {
        let startedAt = CFAbsoluteTimeGetCurrent()
        let homeCountry = homeCountryName
        let snapshots = projects.map { project -> ProjectRowSnapshot in
            let title = localizedOptionDisplayName(project)
            let collaboratorNames = project.collaboratorNames.compactMap { $0.trimmedOrNil }
            let leaderName = project.collaboratorNames.first?.trimmedOrNil ?? ""
            let flags = Array(NSOrderedSet(array: collaboratorNames.compactMap { authorName in
                guard let author = publicationAuthor(named: authorName) else { return nil }
                let primaryCountry = Self.canonicalCountryNameForDiagnostics(author.primaryCountry)
                guard primaryCountry.caseInsensitiveCompare(homeCountry) != .orderedSame else { return nil }
                return Self.flagEmoji(forCountryName: primaryCountry)
            })) as? [String] ?? []
            let isLedByCurrentUser = isCurrentUserProjectLeader(project)
            let hasRemainingGrantedFunds = applications.contains { application in
                applicationBelongs(application, to: project)
                    && application.isGranted
                    && (effectiveRemainingGrantedAmountValue(for: application) ?? 0) > 0
            }
            let hasActiveTasks = project.projectTasks.contains { !$0.isEmpty && !$0.isCompleted }
            let hasProgress = AppStatusTones.projectHasOwnProgress(project)
                || applications.contains { $0.isGranted && applicationBelongs($0, to: project) }
            return ProjectRowSnapshot(
                id: project.id,
                title: title,
                sortTitle: project.nameSv,
                leaderName: leaderName,
                sortLeaderName: leaderName,
                collaboratorNames: collaboratorNames,
                collaboratorFlags: flags,
                applicationCount: projectApplicationCount(forProjectName: project.nameSv),
                grantedAmount: projectGrantedAmount(forProjectName: project.nameSv),
                hasRemainingGrantedFunds: hasRemainingGrantedFunds,
                publishedPublicationCount: projectPublishedPublicationCount(forProjectName: project.nameSv),
                status: project.projectStatus,
                hasDataCollection: project.hasDataCollection,
                hasActiveTasks: hasActiveTasks,
                isLedByCurrentUser: isLedByCurrentUser,
                statusTone: AppStatusTones.project(status: project.projectStatus, hasProgress: hasProgress),
                isEditingLocked: project.isEditingLocked
            )
        }

        if snapshots != projectRowSnapshotsCache {
            projectRowSnapshotsCache = snapshots
            projectRowSnapshotGeneration &+= 1
        }
        appendPerformanceDiagnosticIfSlow(
            { duration in
                String(format: "project-row-snapshots rows=%ld total_ms=%.2f", projects.count, duration)
            },
            startedAt: startedAt,
            thresholdMs: 8
        )
    }

    private func rebuildOrganizationRowSnapshots() {
        let startedAt = CFAbsoluteTimeGetCurrent()
        // "Alla kopplingar via id": which organizations teaching and
        // researcher rows point to, by id first and by name for rows
        // without a link.
        let linkedTeachingInstitutionIDs = Set(
            teachingCourses.compactMap { linkedInstitution(of: $0)?.id }
            + teachingComponents.compactMap { linkedInstitution(of: $0)?.id }
        )
        var linkedAuthorOrganizationIDs = Set<String>()
        for author in publicationAuthors {
            let rows: [(String?, String)] = author.affiliations.map { ($0.organizationID, $0.organization) }
                + author.employments.map { ($0.organizationID, $0.organization) }
                + author.educationEntries.map { ($0.organizationID, $0.organization) }
            for (rowID, rowName) in rows {
                if let organizationID = linkedOrganization(id: rowID, name: rowName)?.id {
                    linkedAuthorOrganizationIDs.insert(organizationID)
                }
            }
        }
        let linkedCongressOrganizationIDs = Set(cvConferenceContributions.compactMap(\.congressOrganizationID))
        let (directApplicationSummaries, managedApplicationSummaries) = organizationApplicationSummaries(for: applications)
        let afterIndexes = CFAbsoluteTimeGetCurrent()

        let snapshots = organizations.map { organization -> OrganizationRowSnapshot in
            let directSummary = directApplicationSummaries[organization.id] ?? OrganizationApplicationSummary()
            let managedSummary = managedApplicationSummaries[organization.id] ?? OrganizationApplicationSummary()
            let isManager = isManagerOrganization(organization)
            let counts = isManager ? managedSummary : directSummary
            let hasLinkedRecords =
                directSummary.submitted > 0
                || managedSummary.submitted > 0
                || linkedTeachingInstitutionIDs.contains(organization.id)
                || linkedAuthorOrganizationIDs.contains(organization.id)
                || linkedCongressOrganizationIDs.contains(organization.id)
            return OrganizationRowSnapshot(
                id: organization.id,
                displayName: localizedOptionDisplayName(organization),
                sortName: organization.nameSv,
                flag: organization.flag.trimmingCharacters(in: .whitespacesAndNewlines),
                icons: organizationCategoryIcons(for: organization),
                category: organization.category ?? "",
                roles: organization.roles,
                roleSummary: organization.roles.map(localizedOrganizationRole).joined(separator: " • "),
                applicationCount: counts.submitted,
                waitingCount: counts.waiting,
                grantedCount: counts.granted,
                rejectedCount: counts.rejected,
                withdrawnCount: counts.withdrawn,
                hasLinkedRecords: hasLinkedRecords,
                isGrantProvider: organization.roles.contains(.grantProvider),
                isStewardshipOrganization: isStewardshipOrganization(organization),
                isManagerOrganization: isManager
            )
        }

        if snapshots != organizationRowSnapshotsCache {
            organizationRowSnapshotsCache = snapshots
            organizationRowSnapshotGeneration &+= 1
        }
        appendPerformanceDiagnosticIfSlow(
            { duration in
                String(
                    format: "organization-row-snapshots rows=%ld index_ms=%.2f map_ms=%.2f total_ms=%.2f",
                    organizations.count,
                    (afterIndexes - startedAt) * 1000,
                    (CFAbsoluteTimeGetCurrent() - afterIndexes) * 1000,
                    duration
                )
            },
            startedAt: startedAt,
            thresholdMs: 8
        )
    }

    private func forceOrganizationRowSnapshotGenerationIfNeeded(congressesChanged: Bool) {
        guard congressesChanged else { return }
        organizationRowSnapshotGeneration &+= 1
    }

    /// "Alla kopplingar via id": the grant counts per organization, keyed by
    /// the id of the organization each application points to (grant provider
    /// and fund manager); the written name only for applications without a
    /// link.
    private func organizationApplicationSummaries(
        for applications: [GrantApplication]
    ) -> (
        direct: [String: OrganizationApplicationSummary],
        managed: [String: OrganizationApplicationSummary]
    ) {
        var direct: [String: OrganizationApplicationSummary] = [:]
        var managed: [String: OrganizationApplicationSummary] = [:]
        for application in applications {
            if let organizationID = linkedFunder(of: application)?.id {
                direct[organizationID, default: OrganizationApplicationSummary()].include(application)
            }
            if let managerID = linkedFundManager(of: application)?.id {
                managed[managerID, default: OrganizationApplicationSummary()].include(application)
            }
        }
        return (direct, managed)
    }

    nonisolated private static func canonicalCountryNameForDiagnostics(_ raw: String) -> String {
        GrantParsing.canonicalCountryName(raw)
    }

    nonisolated private static func flagEmoji(forCountryName countryName: String) -> String? {
        let trimmed = GrantParsing.canonicalCountryName(countryName).trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return nil }
        if trimmed.caseInsensitiveCompare("Somaliland") == .orderedSame {
            return "🏴"
        }
        let explicitCodes: [String: String] = [
            "Sweden": "SE", "United Kingdom": "GB", "Norway": "NO", "Denmark": "DK",
            "Finland": "FI", "Germany": "DE", "France": "FR", "Netherlands": "NL",
            "Belgium": "BE", "Switzerland": "CH", "Austria": "AT", "Italy": "IT",
            "Spain": "ES", "Australia": "AU", "United States": "US"
        ]
        let regionCode =
            explicitCodes[trimmed]
            ?? GrantParsing.countryRegions.first(where: {
                let english = Locale(identifier: "en_US").localizedString(forRegionCode: $0.identifier)
                let swedish = Locale(identifier: "sv_SE").localizedString(forRegionCode: $0.identifier)
                return english == trimmed || swedish == trimmed
            })?.identifier
        guard let regionCode else { return nil }
        return regionCode.unicodeScalars
            .compactMap { UnicodeScalar(127397 + $0.value) }
            .map(String.init)
            .joined()
    }

    private func refreshPublicationIndexes(
        mode: PublicationIndexRefreshMode = .full,
        projectCacheBehavior: ProjectCacheRefreshBehavior = .markDirty
    ) {
        if mode == .full {
            deferredFullPublicationIndexWorkItem?.cancel()
            deferredFullPublicationIndexWorkItem = nil
        }
        requestPublicationIndexRefresh(
            PublicationIndexRefreshRequest(
                mode: mode,
                projectCacheBehavior: projectCacheBehavior
            )
        )
    }

    private func refreshPublicationIndexesImmediately(
        mode: PublicationIndexRefreshMode,
        projectCacheBehavior: ProjectCacheRefreshBehavior
    ) {
        pendingPublicationIndexRefreshWorkItem?.cancel()
        pendingPublicationIndexRefreshWorkItem = nil
        pendingPublicationIndexRefreshRequest = nil

        publicationIndexRefreshInProgress = true
        defer {
            publicationIndexRefreshInProgress = false
            lastPublicationIndexRefreshCompletedAt = CFAbsoluteTimeGetCurrent()
        }

        refreshPublicationIndexesInternal(
            mode: mode,
            projectCacheBehavior: projectCacheBehavior
        )
    }

    private func scheduleDeferredFullPublicationIndexRefresh(
        reason: String,
        delay: TimeInterval = 0.85,
        projectCacheBehavior: ProjectCacheRefreshBehavior = .skip
    ) {
        deferredFullPublicationIndexWorkItem?.cancel()
        let workItem = DispatchWorkItem { [weak self] in
            guard let self else { return }
            self.deferredFullPublicationIndexWorkItem = nil
            self.appendPerformanceDiagnostic("publication-index-refresh-deferred reason=\(reason)")
            self.refreshPublicationIndexes(mode: .full, projectCacheBehavior: projectCacheBehavior)
        }
        deferredFullPublicationIndexWorkItem = workItem
        DispatchQueue.main.asyncAfter(deadline: .now() + delay, execute: workItem)
    }

    private func requestPublicationIndexRefresh(_ request: PublicationIndexRefreshRequest) {
        if publicationIndexRefreshInProgress {
            mergePendingPublicationIndexRefreshRequest(request)
            return
        }

        let now = CFAbsoluteTimeGetCurrent()
        let elapsed = now - lastPublicationIndexRefreshCompletedAt
        if elapsed < Self.publicationIndexRefreshCoalesceInterval {
            mergePendingPublicationIndexRefreshRequest(request)
            schedulePendingPublicationIndexRefresh(after: Self.publicationIndexRefreshCoalesceInterval - elapsed)
            return
        }

        publicationIndexRefreshInProgress = true
        defer {
            publicationIndexRefreshInProgress = false
            lastPublicationIndexRefreshCompletedAt = CFAbsoluteTimeGetCurrent()
            flushPendingPublicationIndexRefreshIfNeeded()
        }

        refreshPublicationIndexesInternal(
            mode: request.mode,
            projectCacheBehavior: request.projectCacheBehavior
        )
    }

    private func mergePendingPublicationIndexRefreshRequest(_ request: PublicationIndexRefreshRequest) {
        if var pending = pendingPublicationIndexRefreshRequest {
            pending.merge(with: request)
            pendingPublicationIndexRefreshRequest = pending
        } else {
            pendingPublicationIndexRefreshRequest = request
        }
    }

    private func schedulePendingPublicationIndexRefresh(after delay: CFAbsoluteTime) {
        let clampedDelay = max(0.01, delay)
        pendingPublicationIndexRefreshWorkItem?.cancel()
        let workItem = DispatchWorkItem { [weak self] in
            guard let self else { return }
            self.pendingPublicationIndexRefreshWorkItem = nil
            self.flushPendingPublicationIndexRefreshIfNeeded()
        }
        pendingPublicationIndexRefreshWorkItem = workItem
        DispatchQueue.main.asyncAfter(deadline: .now() + clampedDelay, execute: workItem)
    }

    private func flushPendingPublicationIndexRefreshIfNeeded() {
        pendingPublicationIndexRefreshWorkItem?.cancel()
        pendingPublicationIndexRefreshWorkItem = nil
        guard let pending = pendingPublicationIndexRefreshRequest else { return }
        pendingPublicationIndexRefreshRequest = nil
        requestPublicationIndexRefresh(pending)
    }

    private func makeResearcherProjectRelation(
        authorID: String?,
        authorName: String,
        projectName: String,
        kind: ResearcherProjectRelationKind,
        sourceID: String,
        sourceTitle: String
    ) -> ResearcherProjectRelation? {
        guard let resolvedAuthorName = authorName.trimmedOrNil,
              let resolvedProjectName = projectName.trimmedOrNil else {
            return nil
        }
        let project = project(named: resolvedProjectName)
        let relationKey = [
            kind.rawValue,
            authorID?.trimmedOrNil ?? normalizedPersonLookupName(resolvedAuthorName),
            project?.id ?? resolvedProjectName,
            sourceID
        ]
        .joined(separator: "|")
        return ResearcherProjectRelation(
            id: relationKey,
            authorID: authorID?.trimmedOrNil,
            authorName: canonicalAssociationAuthorName(for: resolvedAuthorName) ?? resolvedAuthorName,
            projectID: project?.id,
            projectName: resolvedProjectName,
            kind: kind,
            sourceID: sourceID,
            sourceTitle: sourceTitle.trimmedOrNil ?? resolvedProjectName
        )
    }

    private func appendResearcherProjectRelation(
        _ relation: ResearcherProjectRelation?,
        byName: inout [String: [ResearcherProjectRelation]],
        byID: inout [String: [ResearcherProjectRelation]]
    ) {
        guard let relation else { return }
        let nameKey = canonicalAssociationAuthorName(for: relation.authorName) ?? relation.authorName
        byName[nameKey, default: []].append(relation)
        if let authorID = relation.authorID?.trimmedOrNil {
            byID[authorID, default: []].append(relation)
        }
    }

    private func sortedUniqueResearcherProjectRelations(
        _ relations: [ResearcherProjectRelation]
    ) -> [ResearcherProjectRelation] {
        Dictionary(relations.map { ($0.id, $0) }, uniquingKeysWith: { first, _ in first })
            .values
            .sorted { lhs, rhs in
                if lhs.projectName != rhs.projectName {
                    return lhs.projectName.localizedStandardCompare(rhs.projectName) == .orderedAscending
                }
                if lhs.countsAsResearchProject != rhs.countsAsResearchProject {
                    return lhs.countsAsResearchProject && !rhs.countsAsResearchProject
                }
                if lhs.kind.rawValue != rhs.kind.rawValue {
                    return lhs.kind.rawValue < rhs.kind.rawValue
                }
                return lhs.sourceTitle.localizedStandardCompare(rhs.sourceTitle) == .orderedAscending
            }
    }

    private func refreshPublicationIndexesInternal(
        mode: PublicationIndexRefreshMode = .full,
        projectCacheBehavior: ProjectCacheRefreshBehavior = .markDirty
    ) {
        let activityLabel = mode == .full ? "publication-index-full" : "publication-index-crossrefs"
        let startedAt = beginMainThreadActivity(activityLabel)
        applicationByID = applications.reduce(into: [:]) { $0[$1.id] = $1 }
        organizationByID = organizations.reduce(into: [:]) { $0[$1.id] = $1 }
        organizationByName = organizations.reduce(into: [:]) { $0[$1.nameSv] = $1 }
        managerByID = managers.reduce(into: [:]) { $0[$1.id] = $1 }
        managerByName = managers.reduce(into: [:]) { $0[$1.nameSv] = $1 }
        projectByName = projects.reduce(into: [:]) { $0[$1.nameSv] = $1 }
        projectByID = projects.reduce(into: [:]) { $0[$1.id] = $1 }
        // rebuildPublicationAuthorLookupCaches runs inside
        // refreshPublicationDerivedIndexes below; it used to run here too,
        // doubling the 141-author normalization pass. On the very first pass
        // after load the presented-name cache is still empty, which made every
        // manager/co-applicant resolution in the application loop below fall
        // back to a full authors × name-variants scan - the dominant cost of
        // the launch index build. Build it once up front in that case.
        if publicationAuthorByPresentedName.isEmpty, !publicationAuthors.isEmpty {
            rebuildPublicationAuthorLookupCaches()
        }

        var projectApplicationIDs: [String: [String]] = [:]
        var organizationApplicationIDs: [String: [String]] = [:]
        var managerApplicationIDs: [String: [String]] = [:]
        var personApplicationIDSets: [String: Set<String>] = [:]
        var personApplicationIDSetsByID: [String: Set<String>] = [:]
        var applicationRelationsByPersonName: [String: [ResearcherProjectRelation]] = [:]
        var applicationRelationsByPersonID: [String: [ResearcherProjectRelation]] = [:]
        var applicationCountsByProject: [String: Int] = [:]
        var grantedAmountsByProject: [String: Double] = [:]

        for application in applications where !application.isNotAppliedStatus {
            // "Alla kopplingar via id": the project, grant provider and fund
            // manager the application points to decide where it is filed.
            let projectName = linkedProjectKey(for: application)
            let applicationTitle = application.grantName.trimmedOrNil
                ?? application.localizedGrantName(language: .swedish).trimmedOrNil
                ?? projectName
                ?? application.organization
            if let projectName {
                projectApplicationIDs[projectName, default: []].append(application.id)
                applicationCountsByProject[projectName, default: 0] += 1
                grantedAmountsByProject[projectName, default: 0] += grantStatisticsAmountInSEK(for: application, amount: application.grantedAmountValue)
            }
            if let organizationName = linkedOrganizationKey(for: application) {
                organizationApplicationIDs[organizationName, default: []].append(application.id)
            }
            if let managerName = application.applicationManager?.trimmedOrNil {
                managerApplicationIDs[linkedManagerKey(for: application) ?? managerName, default: []].append(application.id)
                personApplicationIDSets[managerName, default: []].insert(application.id)
                let managerID = publicationAuthorID(forPresentedName: managerName)
                if let managerID {
                    personApplicationIDSetsByID[managerID, default: []].insert(application.id)
                }
                if let projectName {
                    appendResearcherProjectRelation(
                        makeResearcherProjectRelation(
                            authorID: managerID,
                            authorName: managerName,
                            projectName: projectName,
                            kind: .applicationManager,
                            sourceID: application.id,
                            sourceTitle: applicationTitle
                        ),
                        byName: &applicationRelationsByPersonName,
                        byID: &applicationRelationsByPersonID
                    )
                }
            }
            // F13b: the co-applicants' id links count first; a name without a
            // stored id is still resolved by name.
            for personID in application.coApplicantAuthorIDs {
                personApplicationIDSetsByID[personID, default: []].insert(application.id)
            }
            for personName in application.coApplicants.compactMap(\.trimmedOrNil) {
                personApplicationIDSets[personName, default: []].insert(application.id)
                let personID = publicationAuthorID(forPresentedName: personName)
                if let personID {
                    personApplicationIDSetsByID[personID, default: []].insert(application.id)
                }
                if let projectName {
                    appendResearcherProjectRelation(
                        makeResearcherProjectRelation(
                            authorID: personID,
                            authorName: personName,
                            projectName: projectName,
                            kind: .applicationCoApplicant,
                            sourceID: application.id,
                            sourceTitle: applicationTitle
                        ),
                        byName: &applicationRelationsByPersonName,
                        byID: &applicationRelationsByPersonID
                    )
                }
            }
        }

        applicationIDsByProjectName = projectApplicationIDs
        applicationIDsByOrganizationName = organizationApplicationIDs
        applicationIDsByManagerName = managerApplicationIDs
        applicationIDsByPersonName = personApplicationIDSets.mapValues { Array($0) }
        applicationIDsByPersonID = personApplicationIDSetsByID.mapValues { Array($0) }
        applicationProjectNamesByPersonName = [:]
        applicationProjectNamesByPersonID = [:]
        applicationProjectRelationsByAuthorName = applicationRelationsByPersonName.mapValues(sortedUniqueResearcherProjectRelations)
        applicationProjectRelationsByAuthorID = applicationRelationsByPersonID.mapValues(sortedUniqueResearcherProjectRelations)
        projectApplicationCountByName = applicationCountsByProject
        projectGrantedAmountByName = grantedAmountsByProject
        grantCountByAuthorName = personApplicationIDSets.mapValues(\.count)
        grantCountByAuthorID = personApplicationIDSetsByID.mapValues(\.count)
        rebuildApplicationRowSnapshots()

        refreshPublicationDerivedIndexes(
            projectCacheBehavior: projectCacheBehavior,
            mode: mode
        )
        endMainThreadActivity(activityLabel, startedAt: startedAt)
        let duration = (CFAbsoluteTimeGetCurrent() - startedAt) * 1000
        if duration > 40 {
            appendPerformanceDiagnostic(
                String(
                    format: "publication-index-refresh mode=%@ total_ms=%.2f applications=%ld authors=%ld journals=%ld publications=%ld projects=%ld",
                    mode == .full ? "full" : "crossrefs",
                    duration,
                    applications.count,
                    publicationAuthors.count,
                    publicationJournals.count,
                    publicationRecords.count,
                    projects.count
                )
            )
        }
    }

    private func publicationProjectCacheRefreshBehavior(
        afterUpdating updated: PublicationRecord,
        previous: PublicationRecord
    ) -> ProjectCacheRefreshBehavior {
        let oldProjectName = previous.projectName?.trimmedOrNil
        let newProjectName = updated.projectName?.trimmedOrNil
        let touchesProjectAssociation = oldProjectName != newProjectName
            || previous.projectID?.trimmedOrNil != updated.projectID?.trimmedOrNil
        let touchesProjectPublicationPresentation =
            previous.title != updated.title
            || previous.statusLabel != updated.statusLabel
            || previous.year != updated.year
            || previous.statusTimeline != updated.statusTimeline
            || previous.statusDate != updated.statusDate

        if touchesProjectAssociation || ((oldProjectName != nil || newProjectName != nil) && touchesProjectPublicationPresentation) {
            return .schedule
        }
        return .skip
    }

    struct JournalLookupCacheBuild {
        let byName: [String: PublicationJournal]
        let byNormalizedName: [String: PublicationJournal]
        let byNormalizedISSN: [String: PublicationJournal]
        let derivedMetricsByID: [String: PublicationJournalDerivedMetrics]
        let rankingSignature: Int
    }

    nonisolated static func builtJournalLookupCaches(journals: [PublicationJournal]) -> JournalLookupCacheBuild {
        let byName = journals.reduce(into: [String: PublicationJournal]()) { $0[$1.name] = $1 }
        let byNormalizedName = journals.reduce(into: [String: PublicationJournal]()) { partialResult, journal in
            for candidate in [journal.name, journal.abbreviatedName, journal.issnLTWAAbbreviatedName] {
                let key = Self.normalizedPublicationJournalLookupKey(candidate)
                if !key.isEmpty, partialResult[key] == nil {
                    partialResult[key] = journal
                }
            }
        }
        let byNormalizedISSN = journals.reduce(into: [String: PublicationJournal]()) { partialResult, journal in
            for key in [journal.issn, journal.eissn].map(Self.normalizedPublicationJournalISSNKey) where !key.isEmpty {
                if partialResult[key] == nil {
                    partialResult[key] = journal
                }
            }
        }
        var rankingHasher = Hasher()
        rankingHasher.combine(journals.count)
        let derivedMetricsByID = journals.reduce(into: [String: PublicationJournalDerivedMetrics]()) { partialResult, journal in
            let latestImpactFactorMetric = journal.preferredMetric(for: [.clarivateScieJIF, .clarivateEsciJIF], publicationYear: nil)
            let latestNorwegianMetric = journal.preferredMetric(for: [.norwegianList], publicationYear: nil)
            partialResult[journal.id] = PublicationJournalDerivedMetrics(
                latestImpactFactorMetric: latestImpactFactorMetric,
                latestImpactFactorValue: latestImpactFactorMetric.flatMap { Double($0.value.replacingOccurrences(of: ",", with: ".")) } ?? 0,
                latestNorwegianMetric: latestNorwegianMetric,
                latestNorwegianLevelValue: latestNorwegianMetric.map { PublicationJournal.norwegianRankValue(for: $0.value) } ?? PublicationJournal.norwegianRankValue(for: journal.norwegianLevel)
            )
            rankingHasher.combine(journal.id)
            rankingHasher.combine(journal.norwegianLevel)
            rankingHasher.combine(journal.rankingRows.count)
            for row in journal.rankingRows {
                rankingHasher.combine(row.kind.rawValue)
                rankingHasher.combine(row.category ?? "")
                rankingHasher.combine(row.yearlyMetrics.count)
                for metric in row.yearlyMetrics {
                    rankingHasher.combine(metric.year)
                    rankingHasher.combine(metric.value)
                }
            }
        }
        return JournalLookupCacheBuild(
            byName: byName,
            byNormalizedName: byNormalizedName,
            byNormalizedISSN: byNormalizedISSN,
            derivedMetricsByID: derivedMetricsByID,
            rankingSignature: rankingHasher.finalize()
        )
    }

    private func installJournalLookupCaches(_ build: JournalLookupCacheBuild) {
        publicationJournalByName = build.byName
        publicationJournalByNormalizedName = build.byNormalizedName
        publicationJournalByNormalizedISSN = build.byNormalizedISSN
        journalDerivedMetricsByIDCache = build.derivedMetricsByID
        if lastPublicationJournalRankingSignature != build.rankingSignature {
            lastPublicationJournalRankingSignature = build.rankingSignature
            publicationJournalRankingGeneration &+= 1
        }
    }

    /// Bootstrap runs the ~1.6 s journal lookup/metric pass on a detached task
    /// so the first window appears without waiting for it. On completion the
    /// caches are installed under a generation guard and a full index refresh
    /// runs; a scheduled full refresh remains as the synchronous fallback.
    func beginBootstrapJournalLookupCacheBuild() {
        let journals = publicationJournals
        let generation = publicationJournalsIndexGeneration
        scheduleDeferredFullPublicationIndexRefresh(
            reason: "bootstrap-journal-cache-fallback",
            delay: 3.0
        )
        Task.detached(priority: .userInitiated) { [weak self] in
            let build = Self.builtJournalLookupCaches(journals: journals)
            await MainActor.run {
                guard let self else { return }
                guard generation == self.publicationJournalsIndexGeneration,
                      self.journalLookupCachesBuiltGeneration != generation else {
                    return
                }
                self.journalLookupCachesBuiltGeneration = generation
                self.installJournalLookupCaches(build)
                self.appendPerformanceDiagnostic("journal-lookup-cache-async-build installed=true")
                self.refreshPublicationIndexes(mode: .full, projectCacheBehavior: .skip)
                // The full refresh above covers everything the scheduled
                // fallback would redo; without this cancel the fallback fired
                // ~2.5 s after launch and repeated the whole ~200 ms full
                // index pass on the main thread for nothing.
                self.deferredFullPublicationIndexWorkItem?.cancel()
                self.deferredFullPublicationIndexWorkItem = nil
            }
        }
    }

    /// The ~8 MB publication_journals document dominates the undo-baseline
    /// fallback encode: the persisted-bytes cache is seeded lazily by the
    /// first write, so the first journal edit of a session paid a ~110 ms
    /// main-thread encode twice (baseline + write). Encode it once off-main
    /// at launch and seed the cache; the generation guard and the
    /// pending/in-flight checks discard the bytes if any edit raced the
    /// prewarm, so a stale baseline can never be installed.
    func beginBootstrapPersistedJournalCachePrewarm() {
        guard persistedDocumentCache["publication_journals"] == nil else { return }
        let journals = publicationJournals
        let generation = publicationJournalsIndexGeneration
        Task.detached(priority: .utility) { [weak self] in
            let encoder = Self.makePersistenceEncoder()
            guard let data = try? encoder.encode(journals) else { return }
            await MainActor.run {
                guard let self else { return }
                guard generation == self.publicationJournalsIndexGeneration,
                      self.persistedDocumentCache["publication_journals"] == nil,
                      self.pendingDeferredPersistedStatesByKey["publication_journals"] == nil,
                      self.inFlightDeferredPersistedStatesByKey["publication_journals"] == nil else { return }
                self.persistedDocumentCache["publication_journals"] = data
                self.appendPerformanceDiagnostic("journal-persisted-cache-prewarm installed=true")
            }
        }
    }

    private func refreshPublicationDerivedIndexes(
        projectCacheBehavior: ProjectCacheRefreshBehavior,
        mode: PublicationIndexRefreshMode = .full
    ) {
        publicationByID = publicationRecords.reduce(into: [:]) { $0[$1.id] = $1 }
        publicationJournalByID = publicationJournals.reduce(into: [:]) { $0[$1.id] = $1 }
        rebuildPublicationAuthorLookupCaches()
        // The name/ISSN lookup maps and derived metrics depend only on the
        // journals collection; skip the ~3,092-journal normalization and
        // metric pass when journals did not change since the last build.
        if journalLookupCachesBuiltGeneration != publicationJournalsIndexGeneration {
            if journalLookupBuildDeferredForBootstrap {
                // Consumed exactly once, by the bootstrap crossrefs refresh:
                // beginBootstrapJournalLookupCacheBuild() runs the same pure
                // pass on a detached task so the first window is not blocked
                // behind it. Every later refresh builds synchronously again.
                journalLookupBuildDeferredForBootstrap = false
            } else {
                journalLookupCachesBuiltGeneration = publicationJournalsIndexGeneration
                installJournalLookupCaches(Self.builtJournalLookupCaches(journals: publicationJournals))
            }
        }
        switch mode {
        case .full:
            refreshPublicationSupportCaches()
        case .crossReferencesOnly:
            refreshLightweightPublicationSupportCaches()
        }

        var projectPublicationIDs: [String: [String]] = [:]
        var authorPublicationIDs: [String: [String]] = [:]
        var authorPublicationIDsByID: [String: Set<String>] = [:]
        var publishedCountsByProject: [String: Int] = [:]
        var acceptanceCounts: [String: JournalAcceptanceStats] = [:]
        var linkedEntries: [String: [JournalLinkedPublicationEntry]] = [:]
        var linkedEntriesByJournalID: [String: [JournalLinkedPublicationEntry]] = [:]
        var authorProjectNames = applicationProjectNamesByPersonName
        var authorProjectNamesByID = applicationProjectNamesByPersonID
        var relationByAuthorName = applicationProjectRelationsByAuthorName
        var relationByAuthorID = applicationProjectRelationsByAuthorID
        var seenSubmissionKeys = Set<String>()
        var seenPublishedKeys = Set<String>()
        var seenLinkedEntryKeys = Set<String>()

        for publication in publicationRecords {
            // "Alla kopplingar via id": the project the publication points to.
            let publicationProjectName = linkedProjectKey(for: publication)
            if let projectName = publicationProjectName {
                projectPublicationIDs[projectName, default: []].append(publication.id)
                if publication.isPublished && publication.isPeerReviewed {
                    publishedCountsByProject[projectName, default: 0] += 1
                }
            }
            // F13b / "Alla kopplingar via id": the stored author links count
            // first; a written name without a link is still resolved by name.
            for authorID in publication.authorIDs.compactMap(\.trimmedOrNil) {
                authorPublicationIDsByID[authorID, default: []].insert(publication.id)
                if let projectName = publicationProjectName {
                    authorProjectNamesByID[authorID, default: []].insert(projectName)
                }
            }
            for authorName in publication.authorNames.compactMap(\.trimmedOrNil) {
                authorPublicationIDs[authorName, default: []].append(publication.id)
                let resolvedAuthorID = publicationAuthorID(forPresentedName: authorName)
                if let authorID = resolvedAuthorID {
                    authorPublicationIDsByID[authorID, default: []].insert(publication.id)
                }
                if let projectName = publicationProjectName {
                    authorProjectNames[authorName, default: []].insert(projectName)
                    if let authorID = resolvedAuthorID {
                        authorProjectNamesByID[authorID, default: []].insert(projectName)
                    }
                    appendResearcherProjectRelation(
                        makeResearcherProjectRelation(
                            authorID: resolvedAuthorID,
                            authorName: authorName,
                            projectName: projectName,
                            kind: .publicationAuthor,
                            sourceID: publication.id,
                            sourceTitle: publication.title
                        ),
                        byName: &relationByAuthorName,
                        byID: &relationByAuthorID
                    )
                }
            }

            if mode == .full {
                for row in publicationSubmissionRowsByID[publication.id] ?? derivedSubmissionRows(for: publication) {
                    let journalName = row.journal.trimmingCharacters(in: .whitespacesAndNewlines)
                    guard !journalName.isEmpty else { continue }
                    // "Alla kopplingar via id": the journal the publication
                    // points to decides where the row is counted; the
                    // written name only for rows that point to no journal.
                    let rowJournal = linkedJournal(ofSubmissionJournalName: journalName, in: publication)
                    let journalKey = rowJournal?.name.trimmedOrNil ?? journalName

                    let rowKey = [
                        publication.id,
                        journalName,
                        row.submittedDate ?? "",
                        row.rejectedDate ?? "",
                        row.acceptedDate ?? "",
                        row.publishedDate ?? "",
                    ].joined(separator: "|")

                    if seenSubmissionKeys.insert(rowKey).inserted, row.latestStatus != nil {
                        acceptanceCounts[journalKey, default: JournalAcceptanceStats()].submittedCount += 1
                    }
                    if row.publishedDate?.nonEmpty != nil, seenPublishedKeys.insert(rowKey).inserted {
                        acceptanceCounts[journalKey, default: JournalAcceptanceStats()].publishedCount += 1
                    }

                    guard let resolvedStatus = row.latestStatus,
                          let resolvedDate = row.date(for: resolvedStatus)?.trimmedOrNil else {
                        continue
                    }

                    let entryKey = [publication.id, resolvedStatus.rawValue, resolvedDate, journalName].joined(separator: "|")
                    guard seenLinkedEntryKeys.insert(entryKey).inserted else { continue }

                    let linkedEntry = JournalLinkedPublicationEntry(
                        id: entryKey,
                        publicationID: publication.id,
                        title: publication.title,
                        status: resolvedStatus,
                        dateText: resolvedDate
                    )
                    linkedEntries[journalKey, default: []].append(linkedEntry)
                    if let rowJournal {
                        linkedEntriesByJournalID[rowJournal.id, default: []].append(linkedEntry)
                    }
                }
            }
        }

        for project in projects {
            guard let projectName = project.nameSv.trimmedOrNil else { continue }
            // F13b / "Alla kopplingar via id": the members' stored links count
            // first; names without a link are still resolved by name below.
            for collaboratorID in project.collaboratorAuthorIDs.compactMap(\.trimmedOrNil) {
                authorProjectNamesByID[collaboratorID, default: []].insert(projectName)
            }
            for collaboratorName in project.collaboratorNames.compactMap(\.trimmedOrNil) {
                let canonicalCollaboratorName = publicationAuthor(named: collaboratorName)?.name
                    ?? publicationAuthor(matchingPresentedName: collaboratorName)?.name
                    ?? collaboratorName
                authorProjectNames[canonicalCollaboratorName, default: []].insert(projectName)
                if let collaboratorID = publicationAuthorID(forPresentedName: collaboratorName) {
                    authorProjectNamesByID[collaboratorID, default: []].insert(projectName)
                }
                appendResearcherProjectRelation(
                    makeResearcherProjectRelation(
                        authorID: publicationAuthorID(forPresentedName: collaboratorName),
                        authorName: canonicalCollaboratorName,
                        projectName: projectName,
                        kind: .explicitProjectCollaborator,
                        sourceID: project.id,
                        sourceTitle: projectName
                    ),
                    byName: &relationByAuthorName,
                    byID: &relationByAuthorID
                )
            }
        }

        publicationIDsByProjectName = projectPublicationIDs
        publicationIDsByAuthorName = authorPublicationIDs
        publicationIDsByAuthorID = authorPublicationIDsByID.mapValues { Array($0) }
        projectPublishedPublicationCountByName = publishedCountsByProject
        projectCountByAuthorName = authorProjectNames.mapValues(\.count)
        projectNamesByAuthorName = authorProjectNames.mapValues { names in
            names.sorted { $0.localizedStandardCompare($1) == .orderedAscending }
        }
        projectCountByAuthorID = authorProjectNamesByID.mapValues(\.count)
        projectNamesByAuthorID = authorProjectNamesByID.mapValues { names in
            names.sorted { $0.localizedStandardCompare($1) == .orderedAscending }
        }
        researcherProjectRelationsByAuthorName = relationByAuthorName.mapValues(sortedUniqueResearcherProjectRelations)
        researcherProjectRelationsByAuthorID = relationByAuthorID.mapValues(sortedUniqueResearcherProjectRelations)
        if mode == .full {
            let acceptanceStatsChanged = journalAcceptanceStatsByNameCache != acceptanceCounts
            journalAcceptanceStatsByNameCache = acceptanceCounts
            journalLinkedEntriesByName = linkedEntries.mapValues { entries in
                entries.sorted { lhs, rhs in
                    if lhs.priorityRank != rhs.priorityRank {
                        return lhs.priorityRank < rhs.priorityRank
                    }
                    if lhs.sortDate != rhs.sortDate {
                        return lhs.sortDate > rhs.sortDate
                    }
                    return lhs.title.localizedStandardCompare(rhs.title) == .orderedAscending
                }
            }
            // "Alla kopplingar via id": a journal's publications are the rows
            // that point to it.
            journalLinkedEntriesByIDCache = linkedEntriesByJournalID.mapValues { journalEntries in
                let entries = journalEntries
                    .reduce(into: [String: JournalLinkedPublicationEntry]()) { result, entry in
                        if result[entry.id] == nil {
                            result[entry.id] = entry
                        }
                    }
                    .map(\.value)
                return entries.sorted { lhs, rhs in
                    if lhs.priorityRank != rhs.priorityRank {
                        return lhs.priorityRank < rhs.priorityRank
                    }
                    if lhs.sortDate != rhs.sortDate {
                        return lhs.sortDate > rhs.sortDate
                    }
                    return lhs.title.localizedStandardCompare(rhs.title) == .orderedAscending
                }
            }
            // Only invalidate the 3,092-row snapshot cache when its actual
            // inputs moved; unconditional invalidation kept re-running the
            // async rebuild just to conclude nothing changed.
            if acceptanceStatsChanged
                || journalRowSnapshotsBuiltJournalsGeneration != publicationJournalsIndexGeneration
                || journalRowSnapshotsBuiltRankingGeneration != publicationJournalRankingGeneration {
                journalRowSnapshotsBuiltJournalsGeneration = publicationJournalsIndexGeneration
                journalRowSnapshotsBuiltRankingGeneration = publicationJournalRankingGeneration
                invalidatePublicationJournalRowSnapshots()
            }
        }
        rebuildPublicationAuthorRowSnapshots()
        rebuildProjectRowSnapshots()
        if mode == .full {
            rebuildOrganizationRowSnapshots()
        }
        switch projectCacheBehavior {
        case .schedule:
            scheduleProjectViewCacheRebuild()
        case .markDirty:
            markProjectViewCacheDirty()
        case .skip:
            break
        }
    }

    private func refreshPublicationSupportCaches() {
        refreshLightweightPublicationSupportCaches()
        refreshResearcherSupplementalCaches()
        publicationSubmissionRowsByID = publicationRecords.reduce(into: [:]) { partialResult, publication in
            partialResult[publication.id] = derivedSubmissionRows(for: publication)
        }
        refreshPublishedConferenceContributionCaches()
    }

    private func refreshLightweightPublicationSupportCaches() {
        publicationAuthorOptionNames = publicationAuthorAutocompleteOptionNames()

        // Production journals are maintained in display order. Keep support
        // for unsorted programmatic/test inputs without paying O(n log n) on
        // every normal launch — and skip the ~3,091 locale comparisons
        // entirely when journals did not change.
        if journalOptionNamesBuiltGeneration != publicationJournalsIndexGeneration {
            journalOptionNamesBuiltGeneration = publicationJournalsIndexGeneration
            let journalNames = publicationJournals.map(\.name)
            let journalNamesAreSorted = zip(journalNames, journalNames.dropFirst()).allSatisfy {
                $0.localizedStandardCompare($1) != .orderedDescending
            }
            publicationJournalOptionNames = journalNamesAreSorted
                ? journalNames
                : journalNames.sorted { $0.localizedStandardCompare($1) == .orderedAscending }
        }

        rebuildGrantedApplicationsByProjectCache()
    }

    private func refreshPublishedConferenceContributionCaches() {
        var conferenceContributionsByJournalName: [String: [CVConferenceContribution]] = [:]
        var conferenceContributionsByAuthorID: [String: [CVConferenceContribution]] = [:]
        var conferenceContributionsByProjectID: [String: [CVConferenceContribution]] = [:]
        // "Alla kopplingar via id": contributions that point to a journal are
        // filed under that journal only.
        var contributionsByLinkedJournalID: [String: [String: CVConferenceContribution]] = [:]
        var journalLinkedContributionIDs = Set<String>()
        for contribution in cvConferenceContributions where isPublishedConferenceContribution(contribution) {
            if let contributionJournal = linkedJournal(of: contribution) {
                contributionsByLinkedJournalID[contributionJournal.id, default: [:]][contribution.id] = contribution
                journalLinkedContributionIDs.insert(contribution.id)
            }
            var candidateNames = Set<String>()
            var authorIDs = Set<String>()
            var projectIDs = Set<String>()
            if let journalID = contribution.journalID,
               let journal = publicationJournal(id: journalID) {
                if let name = journal.name.trimmedOrNil {
                    candidateNames.insert(name)
                }
                if let abbreviatedName = journal.abbreviatedName.trimmedOrNil {
                    candidateNames.insert(abbreviatedName)
                }
                if let ltwaAbbreviatedName = journal.issnLTWAAbbreviatedName.trimmedOrNil {
                    candidateNames.insert(ltwaAbbreviatedName)
                }
            }
            if let contributionJournalName = contribution.journalName.trimmedOrNil {
                candidateNames.insert(contributionJournalName)
            }
            if let presentedByID = contribution.presentedByAuthorID?.trimmedOrNil ?? publicationAuthor(matchingPresentedName: contribution.presentedBy)?.id {
                authorIDs.insert(presentedByID)
            }
            authorIDs.formUnion(contribution.contributorAuthorIDs.compactMap(\.trimmedOrNil))
            for contributor in contribution.contributorNames {
                if let contributorID = publicationAuthor(matchingPresentedName: contributor)?.id {
                    authorIDs.insert(contributorID)
                }
            }
            if let projectID = linkedProject(of: contribution)?.id {
                projectIDs.insert(projectID)
            }

            for candidate in candidateNames {
                let key = Self.normalizedPublicationJournalLookupKey(candidate)
                conferenceContributionsByJournalName[key, default: []].append(contribution)
            }
            for authorID in authorIDs {
                conferenceContributionsByAuthorID[authorID, default: []].append(contribution)
            }
            for projectID in projectIDs {
                conferenceContributionsByProjectID[projectID, default: []].append(contribution)
            }
        }
        publishedConferenceContributionsByJournalNameCache = conferenceContributionsByJournalName.mapValues { entries in
            entries.sorted(by: conferenceContributionSortOrder)
        }
        publishedConferenceContributionsByAuthorIDCache = conferenceContributionsByAuthorID.mapValues { entries in
            entries.sorted(by: conferenceContributionSortOrder)
        }
        publishedConferenceContributionsByProjectIDCache = conferenceContributionsByProjectID.mapValues { entries in
            entries.sorted(by: conferenceContributionSortOrder)
        }
        // Inverted from a scan of all 3,092 journals (× 3 key
        // normalizations each) to a scan of the handful of name keys that
        // actually carry contributions; the sole consumer falls back to []
        // for journals without entries.
        var contributionsByJournalID = contributionsByLinkedJournalID
        for (key, entries) in publishedConferenceContributionsByJournalNameCache {
            guard let journal = publicationJournalByNormalizedName[key] else { continue }
            for entry in entries where !journalLinkedContributionIDs.contains(entry.id)
                && contributionsByJournalID[journal.id]?[entry.id] == nil {
                contributionsByJournalID[journal.id, default: [:]][entry.id] = entry
            }
        }
        publishedConferenceContributionsByJournalIDCache = contributionsByJournalID.mapValues { entriesByID in
            entriesByID.values.sorted(by: conferenceContributionSortOrder)
        }
    }

    private func rebuildGrantedApplicationsByProjectCache() {
        grantedApplicationsByProjectName = Dictionary(
            grouping: applications.compactMap { application -> (String, GrantApplication)? in
                guard application.isGranted,
                      let projectName = linkedProjectKey(for: application) else { return nil }
                return (projectName, application)
            },
            by: \.0
        ).mapValues { entries in
            entries
                .map(\.1)
                .sorted {
                    let lhsDate = $0.decisionDate ?? $0.applicationDate ?? .distantPast
                    let rhsDate = $1.decisionDate ?? $1.applicationDate ?? .distantPast
                    if lhsDate != rhsDate {
                        return lhsDate > rhsDate
                    }
                    return displayTitle(for: $0, language: language).localizedStandardCompare(displayTitle(for: $1, language: language)) == .orderedAscending
                }
        }
    }

    private func refreshProjectIndexesAndCaches() {
        projectByName = projects.reduce(into: [:]) { $0[$1.nameSv] = $1 }
        projectByID = projects.reduce(into: [:]) { $0[$1.id] = $1 }
        rebuildProjectRowSnapshots()
        scheduleProjectViewCacheRebuild()
    }

    private func markProjectViewCacheDirty() {
        isProjectViewCacheDirty = true
        resolvedProjectViewDataByLanguage.removeAll(keepingCapacity: true)
        projectViewCacheTask?.cancel()
        projectViewCacheTask = nil
        pendingProjectViewCacheSnapshotSignature = nil
    }

    private func ensureProjectViewCachesCurrent() {
        guard isProjectViewCacheDirty || projectViewCachesByLanguage.isEmpty else { return }

        projectViewCacheTask?.cancel()
        projectViewCacheTask = nil

        let snapshotSignature = Self.projectViewCacheSnapshotSignature(
            applications: applications,
            publications: publicationRecords,
            organizations: organizations,
            projects: projects
        )
        let startedAt = CFAbsoluteTimeGetCurrent()
        let caches = Self.buildProjectViewCaches(
            applications: applications,
            publications: publicationRecords,
            organizations: organizations,
            projects: projects,
            ownedApplicationIDs: Set(applications.lazy.filter { self.isCurrentUserFirstApplicant($0) }.map(\.id)),
            effectiveFullySpentDates: effectiveProjectTimelineFullySpentDates(for: applications),
            effectiveRemainingAmounts: effectiveProjectTimelineRemainingAmounts(for: applications)
        )
        let duration = (CFAbsoluteTimeGetCurrent() - startedAt) * 1000
        projectViewCachesByLanguage = caches
        // The per-project resolved memo must die with the cache it resolved
        // from, or projectViewData keeps serving the pre-rebuild association
        // (a linked publication stayed invisible in its project forever).
        resolvedProjectViewDataByLanguage.removeAll(keepingCapacity: true)
        projectViewCacheGeneration &+= 1
        isProjectViewCacheDirty = false
        lastProjectViewCacheSnapshotSignature = snapshotSignature
        recordCacheProfile(
            scope: "projects",
            cacheName: "project-view-sync",
            itemCount: caches.values.reduce(0) { $0 + $1.count },
            startedAt: startedAt
        )
        appendPerformanceDiagnostic(
            String(
                format: "project-cache sync_ms=%.2f projects=%ld applications=%ld publications=%ld",
                duration,
                projects.count,
                applications.count,
                publicationRecords.count
            )
        )
    }

    private func scheduleProjectViewCacheRebuild() {
        guard projectViewCacheTask == nil else { return }
        let applicationsSnapshot = applications
        let publicationsSnapshot = publicationRecords
        let organizationsSnapshot = organizations
        let projectsSnapshot = projects
        let ownedApplicationIDsSnapshot = Set(
            applicationsSnapshot.lazy.filter { self.isCurrentUserFirstApplicant($0) }.map(\.id)
        )
        let effectiveFullySpentDatesSnapshot = effectiveProjectTimelineFullySpentDates(for: applicationsSnapshot)
        let effectiveRemainingAmountsSnapshot = effectiveProjectTimelineRemainingAmounts(for: applicationsSnapshot)
        let snapshotSignature = Self.projectViewCacheSnapshotSignature(
            applications: applicationsSnapshot,
            publications: publicationsSnapshot,
            organizations: organizationsSnapshot,
            projects: projectsSnapshot
        )

        if lastProjectViewCacheSnapshotSignature == snapshotSignature, !projectViewCachesByLanguage.isEmpty {
            isProjectViewCacheDirty = false
            return
        }
        if pendingProjectViewCacheSnapshotSignature == snapshotSignature, projectViewCacheTask != nil {
            return
        }

        isProjectViewCacheDirty = true
        projectViewCacheTask?.cancel()
        pendingProjectViewCacheSnapshotSignature = snapshotSignature
        projectViewCacheTask = Task.detached(priority: .utility) { [weak self] in
            let shouldDebounce = !(await MainActor.run { [weak self] in
                guard let self else { return true }
                return self.projectViewCachesByLanguage.isEmpty
            })
            if shouldDebounce {
                try? await Task.sleep(nanoseconds: 250_000_000)
            }
            guard !Task.isCancelled else { return }
            let startedAt = CFAbsoluteTimeGetCurrent()
            let caches = Self.buildProjectViewCaches(
                applications: applicationsSnapshot,
                publications: publicationsSnapshot,
                organizations: organizationsSnapshot,
                projects: projectsSnapshot,
                ownedApplicationIDs: ownedApplicationIDsSnapshot,
                effectiveFullySpentDates: effectiveFullySpentDatesSnapshot,
                effectiveRemainingAmounts: effectiveRemainingAmountsSnapshot
            )
            let duration = (CFAbsoluteTimeGetCurrent() - startedAt) * 1000
            guard !Task.isCancelled else { return }
            await MainActor.run {
                guard let self else { return }
                self.projectViewCachesByLanguage = caches
                // See ensureProjectViewCachesCurrent: the resolved memo must
                // be invalidated whenever the cache it resolved from is
                // replaced.
                self.resolvedProjectViewDataByLanguage.removeAll(keepingCapacity: true)
                self.projectViewCacheGeneration &+= 1
                self.isProjectViewCacheDirty = false
                self.lastProjectViewCacheSnapshotSignature = snapshotSignature
                if self.pendingProjectViewCacheSnapshotSignature == snapshotSignature {
                    self.pendingProjectViewCacheSnapshotSignature = nil
                }
                self.projectViewCacheTask = nil
                self.recordCacheProfile(
                    scope: "projects",
                    cacheName: "project-view-async",
                    itemCount: caches.values.reduce(0) { $0 + $1.count },
                    startedAt: startedAt
                )
                self.appendPerformanceDiagnostic(
                    String(
                        format: "project-cache rebuild_ms=%.2f projects=%ld applications=%ld publications=%ld",
                        duration,
                        projectsSnapshot.count,
                        applicationsSnapshot.count,
                        publicationsSnapshot.count
                    )
                )
            }
        }
    }

    nonisolated private static func buildProjectViewCaches(
        applications: [GrantApplication],
        publications: [PublicationRecord],
        organizations: [OrganizationRecord],
        projects: [ProjectRecord],
        ownedApplicationIDs: Set<String>,
        effectiveFullySpentDates: [String: Date],
        effectiveRemainingAmounts: [String: Double]
    ) -> [String: [String: ProjectViewCache]] {
        // "Alla kopplingar via id": a record is filed under the project its
        // id points to; the written project name only for records without one.
        let projectNameByID = projects.reduce(into: [String: String]()) { $0[$1.id] = $1.nameSv }
        func projectKey(id: String?, name: String?) -> String? {
            if let id = id?.trimmedOrNil, let linkedName = projectNameByID[id]?.trimmedOrNil {
                return linkedName
            }
            return name?.trimmedOrNil
        }
        let groupedApplications = Dictionary(grouping: applications.compactMap { application -> (String, GrantApplication)? in
            guard !application.isNotAppliedStatus else { return nil }
            guard let projectName = projectKey(id: application.projectID, name: application.projectType) else { return nil }
            return (projectName, application)
        }, by: \.0)
        .mapValues { $0.map(\.1) }

        let groupedPublications = Dictionary(grouping: publications.compactMap { publication -> (String, PublicationRecord)? in
            guard let projectName = projectKey(id: publication.projectID, name: publication.projectName) else { return nil }
            return (projectName, publication)
        }, by: \.0)
        .mapValues { $0.map(\.1) }

        let projectLookup = projects.reduce(into: [:]) { $0[$1.nameSv] = $1 }

        let projectNames = Set(projects.map(\.nameSv))
            .union(groupedApplications.keys)
            .union(groupedPublications.keys)

        let duplicateApplicationIDs = Set(
            Dictionary(grouping: applications, by: \.id)
                .compactMap { key, records in records.count > 1 ? key : nil }
        )

        var organizationLabelsByLanguage: [String: [String: String]] = [:]
        for language in AppLanguage.allCases {
            organizationLabelsByLanguage[language.rawValue] = organizations.reduce(into: [:]) { partialResult, organization in
                let label = language == .swedish
                    ? organization.nameSv
                    : (organization.nameEn.nonEmpty ?? organization.nameSv)
                partialResult[organization.nameSv] = label
                // "Alla kopplingar via id": also findable by the organization's id.
                partialResult[Self.organizationLabelIDKeyPrefix + organization.id] = label
            }
        }

        var cachesByLanguage: [String: [String: ProjectViewCache]] = [:]
        for language in AppLanguage.allCases {
            let organizationLabels = organizationLabelsByLanguage[language.rawValue] ?? [:]
            var languageCaches: [String: ProjectViewCache] = [:]
            for projectName in projectNames {
                let projectApplications = groupedApplications[projectName] ?? []
                let projectPublications = groupedPublications[projectName] ?? []
                let project = projectLookup[projectName]
                let applicationTitlesByID = Dictionary(firstWinsKeysWithValues: projectApplications.map { application in
                    (
                        application.id,
                        displayTitle(for: application, organizationLabels: organizationLabels, language: language)
                    )
                })
                languageCaches[projectName] = buildProjectViewCache(
                    project: project,
                    applications: projectApplications,
                    publications: projectPublications,
                    applicationTitlesByID: applicationTitlesByID,
                    organizationLabels: organizationLabels,
                    language: language,
                    duplicateApplicationIDs: duplicateApplicationIDs,
                    ownedApplicationIDs: ownedApplicationIDs,
                    effectiveFullySpentDates: effectiveFullySpentDates,
                    effectiveRemainingAmounts: effectiveRemainingAmounts
                )
            }
            cachesByLanguage[language.rawValue] = languageCaches
        }

        return cachesByLanguage
    }

    nonisolated private static func projectViewCacheSnapshotSignature(
        applications: [GrantApplication],
        publications: [PublicationRecord],
        organizations: [OrganizationRecord],
        projects: [ProjectRecord]
    ) -> Int {
        var hasher = Hasher()
        hasher.combine(applications.count)
        hasher.combine(publications.count)
        hasher.combine(organizations.count)
        hasher.combine(projects.count)

        for application in applications {
            hasher.combine(projectViewRelevantSignature(for: application))
        }
        for publication in publications {
            hasher.combine(projectViewRelevantSignature(for: publication))
        }
        for organization in organizations {
            hasher.combine(projectViewRelevantSignature(for: organization))
        }
        for project in projects {
            hasher.combine(projectViewRelevantProjectSignature(for: project))
        }

        return hasher.finalize()
    }

    nonisolated private static func projectViewRelevantSignature(for application: GrantApplication) -> Int {
        var hasher = Hasher()
        hasher.combine(application.id)
        hasher.combine(application.organization)
        hasher.combine(application.organizationID)
        hasher.combine(application.grantName)
        hasher.combine(application.projectType)
        hasher.combine(application.projectID)
        hasher.combine(application.resultLabel)
        hasher.combine(application.currency)
        hasher.combine(application.applicationDate)
        hasher.combine(application.decisionDate)
        hasher.combine(application.decisionExpectedDate)
        hasher.combine(application.firstDispositionDate)
        hasher.combine(application.lastDispositionDate)
        hasher.combine(application.receivedUsageFrom)
        hasher.combine(application.receivedUsageTo)
        hasher.combine(application.grantedAmount)
        hasher.combine(application.appliedAmount)
        hasher.combine(application.receivedConsumptionPeriods)
        hasher.combine(application.decisionExpectedOnUncertain)
        hasher.combine(application.firstDispositionOnUncertain)
        hasher.combine(application.lastDispositionOnUncertain)
        hasher.combine(application.receivedUsageFromUncertain)
        hasher.combine(application.receivedUsageToUncertain)
        return hasher.finalize()
    }

    nonisolated private static func projectViewRelevantSignature(for publication: PublicationRecord) -> Int {
        var hasher = Hasher()
        hasher.combine(publication.id)
        hasher.combine(publication.projectName)
        hasher.combine(publication.projectID)
        hasher.combine(publication.title)
        hasher.combine(publication.statusLabel)
        hasher.combine(publication.statusTimeline)
        hasher.combine(publication.year)
        hasher.combine(publication.statusDate)
        hasher.combine(publication.currentSubmissionDate)
        return hasher.finalize()
    }

    nonisolated private static func projectViewRelevantSignature(for organization: OrganizationRecord) -> Int {
        var hasher = Hasher()
        hasher.combine(organization.id)
        hasher.combine(organization.nameSv)
        hasher.combine(organization.nameEn)
        return hasher.finalize()
    }

    nonisolated private static func projectViewRelevantProjectSignature(for project: ProjectRecord) -> Int {
        var hasher = Hasher()
        hasher.combine(project.id)
        hasher.combine(project.nameSv)
        hasher.combine(project.nameEn)
        hasher.combine(project.collaboratorNames)
        hasher.combine(project.hasDataCollection)
        hasher.combine(project.ethicsBaseApplication)
        hasher.combine(project.ethicsAmendments)
        hasher.combine(project.principalOrganizations)
        hasher.combine(project.dataCollections)
        return hasher.finalize()
    }

    nonisolated private static func buildProjectViewCache(
        project: ProjectRecord?,
        applications: [GrantApplication],
        publications: [PublicationRecord],
        applicationTitlesByID: [String: String],
        organizationLabels: [String: String],
        language: AppLanguage,
        duplicateApplicationIDs: Set<String>,
        ownedApplicationIDs: Set<String>,
        effectiveFullySpentDates: [String: Date],
        effectiveRemainingAmounts: [String: Double]
    ) -> ProjectViewCache {
        let grantedApplications = applications
            .filter(\.isGranted)
            .sorted {
                let left = $0.lastDispositionDate ?? $0.receivedUsageTo.flatMap { DateParsers.isoDay.date(from: $0) } ?? .distantFuture
                let right = $1.lastDispositionDate ?? $1.receivedUsageTo.flatMap { DateParsers.isoDay.date(from: $0) } ?? .distantFuture
                return left < right
            }

        let awaitingDecisionApplications = applications
            .filter { $0.resultLabel.trimmingCharacters(in: .whitespacesAndNewlines) == "Väntar svar" }
            .sorted {
                let leftDate = $0.decisionExpectedDate ?? .distantFuture
                let rightDate = $1.decisionExpectedDate ?? .distantFuture
                if leftDate != rightDate {
                    return leftDate < rightDate
                }
                return (applicationTitlesByID[$0.id] ?? "").localizedStandardCompare(applicationTitlesByID[$1.id] ?? "") == .orderedAscending
            }

        // Round 17: "Avslagna" lists declined applications only.
        let rejectedApplications = applications
            .filter { AppStatusTones.isDeclined(resultLabel: $0.resultLabel) }
            .sorted {
                let leftDate = $0.applicationDate ?? .distantPast
                let rightDate = $1.applicationDate ?? .distantPast
                if leftDate != rightDate {
                    return leftDate > rightDate
                }
                return (applicationTitlesByID[$0.id] ?? "").localizedStandardCompare(applicationTitlesByID[$1.id] ?? "") == .orderedAscending
            }

        let projectApplicationsForList = applications
            .sorted {
                let leftStatus = $0.resultLabel.trimmingCharacters(in: .whitespacesAndNewlines)
                let rightStatus = $1.resultLabel.trimmingCharacters(in: .whitespacesAndNewlines)
                let leftPriority = projectApplicationStatusPriority(leftStatus)
                let rightPriority = projectApplicationStatusPriority(rightStatus)
                if leftPriority != rightPriority {
                    return leftPriority < rightPriority
                }
                let leftDate = $0.applicationDate ?? .distantPast
                let rightDate = $1.applicationDate ?? .distantPast
                if leftDate != rightDate {
                    return leftDate > rightDate
                }
                return (applicationTitlesByID[$0.id] ?? "").localizedStandardCompare(applicationTitlesByID[$1.id] ?? "") == .orderedAscending
            }

        let orderedTimelineApplications = applications.filter {
            $0.isGranted || $0.resultLabel.trimmingCharacters(in: .whitespacesAndNewlines) == "Väntar svar"
        }
        .sorted {
            if $0.isGranted != $1.isGranted {
                return $0.isGranted && !$1.isGranted
            }
            let lhsRange = grantTimelineDateRange(for: $0)
            let rhsRange = grantTimelineDateRange(for: $1)
            switch (lhsRange, rhsRange) {
            case let (.some(lhsRange), .some(rhsRange)):
                if lhsRange.end == rhsRange.end {
                    return lhsRange.start < rhsRange.start
                }
                return lhsRange.end < rhsRange.end
            case (.some, .none):
                return true
            case (.none, .some):
                return false
            case (.none, .none):
                return (applicationTitlesByID[$0.id] ?? "").localizedStandardCompare(applicationTitlesByID[$1.id] ?? "") == .orderedAscending
            }
        }

        let timelineSnapshot = buildProjectTimelineSnapshot(
            project: project,
            orderedTimelineApplications: orderedTimelineApplications,
            publications: publications,
            organizationLabels: organizationLabels,
            language: language,
            duplicateApplicationIDs: duplicateApplicationIDs,
            effectiveFullySpentDatesByApplicationID: effectiveFullySpentDates,
            effectiveRemainingAmountsByApplicationID: effectiveRemainingAmounts
        )
        let ownedTimelineSnapshot = buildProjectTimelineSnapshot(
            project: project,
            orderedTimelineApplications: orderedTimelineApplications.filter {
                ownedApplicationIDs.contains($0.id)
            },
            publications: publications,
            organizationLabels: organizationLabels,
            language: language,
            duplicateApplicationIDs: duplicateApplicationIDs,
            effectiveFullySpentDatesByApplicationID: effectiveFullySpentDates,
            effectiveRemainingAmountsByApplicationID: effectiveRemainingAmounts
        )

        return ProjectViewCache(
            relatedApplicationIDs: applications.map(\.id),
            relatedPublicationIDs: publications.map(\.id),
            grantedApplicationIDs: grantedApplications.map(\.id),
            awaitingDecisionApplicationIDs: awaitingDecisionApplications.map(\.id),
            rejectedApplicationIDs: rejectedApplications.map(\.id),
            projectApplicationsForListIDs: projectApplicationsForList.map(\.id),
            projectPublicationIDs: publications.sorted(by: projectPublicationSortOrder).map(\.id),
            orderedTimelineApplicationIDs: orderedTimelineApplications.map(\.id),
            timelineSnapshot: timelineSnapshot,
            ownedTimelineSnapshot: ownedTimelineSnapshot
        )
    }

    private func effectiveProjectTimelineFullySpentDates(
        for applications: [GrantApplication]
    ) -> [String: Date] {
        Dictionary(
            firstWinsKeysWithValues: applications.compactMap { application -> (String, Date)? in
                guard isEffectivelyFullySpent(application),
                      !application.isFullySpent,
                      let lastDispositionDate = application.lastDispositionDate else { return nil }
                return (application.id, lastDispositionDate)
            }
        )
    }

    private func effectiveProjectTimelineRemainingAmounts(
        for applications: [GrantApplication]
    ) -> [String: Double] {
        Dictionary(
            firstWinsKeysWithValues: applications.compactMap { application -> (String, Double)? in
                guard let remaining = effectiveRemainingGrantedAmountValue(for: application) else { return nil }
                return (application.id, remaining)
            }
        )
    }

    nonisolated static func buildOrganizationTimelineSnapshot(
        organization: OrganizationRecord,
        selectedRoles: Set<OrganizationRole>? = nil,
        congresses: [OrganizationCongress]? = nil,
        salaryCalculator: ManagerSalaryCalculator? = nil,
        funderApplications: [GrantApplication],
        managedApplications: [GrantApplication],
        currentUserAuthor: PublicationAuthor?,
        language: AppLanguage,
        hidePastEvents: Bool = false,
        hideRejectedGrants: Bool = false,
        referenceDate: Date = Date(),
        effectiveFullySpentDatesByApplicationID: [String: Date] = [:]
    ) -> OrganizationTimelineSnapshot {
        let roles = selectedRoles ?? Set(organization.roles)
        let effectiveCongresses = congresses ?? organization.congresses
        let effectiveSalaryCalculator = salaryCalculator ?? organization.salaryCalculator
        let hiddenBefore = hidePastEvents ? Calendar.current.startOfDay(for: referenceDate) : nil
        var groups: [OrganizationTimelineSnapshot.Group] = []

        if roles.contains(.employer),
           let group = organizationTimelineGroup(
            id: "employer",
            title: language.text("Employer: Employment", "Arbetsgivare: Anställning"),
            bars: organizationTimelineVisibleBars(
                organizationTimelineEmploymentBars(
                    organization: organization,
                    currentUserAuthor: currentUserAuthor,
                    salaryCalculator: effectiveSalaryCalculator,
                    language: language,
                    referenceDate: referenceDate
                ),
                hiddenBefore: hiddenBefore
            ),
            packsNonOverlappingBars: true
           ) {
            groups.append(group)
        }

        if roles.contains(.association),
           let group = organizationTimelineGroup(
            id: "association",
            title: language.text("Congresses", "Kongresser"),
            bars: organizationTimelineVisibleBars(
                effectiveCongresses.compactMap { congress in
                    organizationTimelineCongressBar(congress: congress, language: language)
                },
                hiddenBefore: hiddenBefore
            ),
            packsNonOverlappingBars: true
           ) {
            groups.append(group)
        }

        if roles.contains(.grantProvider),
           let group = organizationTimelineGroup(
            id: "grantProvider",
            title: language.text("Grant provider: Grants", "Anslagsgivare: Anslag"),
            bars: organizationTimelineVisibleBars(
                organizationTimelineGrantBars(
                    applications: funderApplications,
                    role: .grantProvider,
                    hideRejectedGrants: hideRejectedGrants,
                    effectiveFullySpentDatesByApplicationID: effectiveFullySpentDatesByApplicationID,
                    language: language
                ),
                hiddenBefore: hiddenBefore
            ),
            packsNonOverlappingBars: true,
            requiresMatchingPackingKey: true
           ) {
            groups.append(group)
        }

        if roles.contains(.fundManager),
           let group = organizationTimelineGroup(
            id: "fundManager",
            title: language.text("Fund manager: Grants", "Medelsförvaltare: Anslag"),
            bars: organizationTimelineVisibleBars(
                organizationTimelineGrantBars(
                    applications: managedApplications,
                    role: .fundManager,
                    hideRejectedGrants: hideRejectedGrants,
                    effectiveFullySpentDatesByApplicationID: effectiveFullySpentDatesByApplicationID,
                    language: language
                ),
                hiddenBefore: hiddenBefore
            ),
            packsNonOverlappingBars: true,
            requiresMatchingPackingKey: true
           ) {
            groups.append(group)
        }

        let allBars = groups.flatMap { $0.bars }
        let allYears = allBars.flatMap {
            [
                Calendar.current.component(.year, from: $0.packingStart),
                Calendar.current.component(.year, from: $0.packingEnd)
            ]
        }
        let currentYear = Calendar.current.component(.year, from: referenceDate)
        let minYear = min(allYears.min() ?? currentYear, currentYear - 1)
        let maxYear = max(allYears.max() ?? currentYear, currentYear + 1)
        let years = allYears.isEmpty ? [] : Array(minYear...maxYear)

        return OrganizationTimelineSnapshot(years: years, groups: groups)
    }

    nonisolated private static func organizationTimelineGroup(
        id: String,
        title: String,
        bars: [OrganizationTimelineSnapshot.Bar],
        packsNonOverlappingBars: Bool = false,
        requiresMatchingPackingKey: Bool = false
    ) -> OrganizationTimelineSnapshot.Group? {
        let sortedBars = bars.sorted {
            if $0.packingStart != $1.packingStart {
                return $0.packingStart < $1.packingStart
            }
            if $0.start != $1.start {
                return $0.start < $1.start
            }
            if $0.packingEnd != $1.packingEnd {
                return $0.packingEnd < $1.packingEnd
            }
            return $0.title.localizedStandardCompare($1.title) == .orderedAscending
        }
        guard !sortedBars.isEmpty else { return nil }
        return OrganizationTimelineSnapshot.Group(
            id: id,
            title: title,
            rows: packsNonOverlappingBars
                ? organizationTimelinePackedRows(
                    from: sortedBars,
                    requiresMatchingPackingKey: requiresMatchingPackingKey
                )
                : sortedBars.map { [$0] }
        )
    }

    nonisolated private static func organizationTimelinePackedRows(
        from sortedBars: [OrganizationTimelineSnapshot.Bar],
        requiresMatchingPackingKey: Bool = false
    ) -> [[OrganizationTimelineSnapshot.Bar]] {
        var rows: [[OrganizationTimelineSnapshot.Bar]] = []
        var rowEndDates: [Date] = []

        for bar in sortedBars {
            if let rowIndex = rowEndDates.indices.first(where: { index in
                guard rowEndDates[index] < bar.packingStart else { return false }
                guard requiresMatchingPackingKey else { return true }
                guard let key = bar.rowPackingKey else { return false }
                return rows[index].first?.rowPackingKey == key
            }) {
                rows[rowIndex].append(bar)
                rowEndDates[rowIndex] = max(rowEndDates[rowIndex], bar.packingEnd)
            } else {
                rows.append([bar])
                rowEndDates.append(bar.packingEnd)
            }
        }

        return rows
    }

    nonisolated private static func organizationTimelineVisibleBars(
        _ bars: [OrganizationTimelineSnapshot.Bar],
        hiddenBefore: Date?
    ) -> [OrganizationTimelineSnapshot.Bar] {
        guard let hiddenBefore else { return bars }
        return bars.compactMap { bar in
            guard bar.end >= hiddenBefore else { return nil }
            let visibleMarkers = bar.markers.filter { $0.date >= hiddenBefore }
            return OrganizationTimelineSnapshot.Bar(
                id: bar.id,
                applicationID: bar.applicationID,
                start: bar.start,
                end: bar.end,
                title: bar.title,
                hoverText: bar.hoverText,
                kind: bar.kind,
                rowPackingKey: bar.rowPackingKey,
                hasUncertainOutline: bar.hasUncertainOutline,
                fullySpentDate: bar.fullySpentDate,
                markers: visibleMarkers
            )
        }
    }

    nonisolated private static func organizationTimelineCongressBar(
        congress: OrganizationCongress,
        language: AppLanguage
    ) -> OrganizationTimelineSnapshot.Bar? {
        let parsedFrom = organizationTimelineDate(congress.from)
        let parsedTo = organizationTimelineDate(congress.to)
        guard let start = parsedFrom ?? parsedTo else { return nil }
        let end = parsedTo ?? parsedFrom ?? start
        let range = start <= end ? (start, end) : (end, start)
        let title = congress.title.nonEmpty ?? language.text("Congress", "Kongress")
        let location = organizationTimelineCongressLocation(congress)
        let dateRangeText = organizationTimelineCompactDateRangeText(start: range.0, end: range.1, language: language)
        let timelineTitle = ([location ?? title, dateRangeText] as [String?])
            .compactMap { $0?.nonEmpty }
            .joined(separator: ", ")
            .nonEmpty
            ?? "\(title), \(dateRangeText)"
        let markers = organizationTimelineCongressDeadlineMarkers(
            congress: congress,
            congressTitle: title,
            location: location,
            language: language
        )
        var hoverLines = [
            language.text("Congress", "Kongress"),
            title,
            timelineTitle
        ]
        if let location = location.nonEmpty {
            hoverLines.append(location)
        }
        if let abstractDeadline = organizationTimelineDate(congress.abstractSubmissionDeadline) {
            hoverLines.append("\(language.text("Abstract deadline", "Abstractfrist")): \(DateParsers.isoDay.string(from: abstractDeadline))")
        }
        if let lateDeadline = organizationTimelineDate(congress.lateAbstractSubmissionDeadline) {
            hoverLines.append("\(language.text("Late abstract deadline", "Sen abstractfrist")): \(DateParsers.isoDay.string(from: lateDeadline))")
        }

        return OrganizationTimelineSnapshot.Bar(
            id: "congress-\(congress.id)",
            applicationID: nil,
            start: range.0,
            end: range.1,
            title: timelineTitle,
            hoverText: hoverLines.joined(separator: "\n"),
            kind: .congress,
            rowPackingKey: nil,
            hasUncertainOutline: congress.fromUncertain || congress.toUncertain,
            markers: markers
        )
    }

    nonisolated private static func organizationTimelineCongressLocation(_ congress: OrganizationCongress) -> String? {
        [congress.city.nonEmpty, congress.country.nonEmpty]
            .compactMap { $0 }
            .joined(separator: ", ")
            .nonEmpty
    }

    nonisolated private static func organizationTimelineCongressDeadlineMarkers(
        congress: OrganizationCongress,
        congressTitle: String,
        location: String?,
        language: AppLanguage
    ) -> [OrganizationTimelineSnapshot.Marker] {
        var markers: [OrganizationTimelineSnapshot.Marker] = []

        if let date = organizationTimelineDate(congress.abstractSubmissionDeadline) {
            markers.append(
                organizationTimelineCongressDeadlineMarker(
                    id: "congress-\(congress.id)-abstract-deadline",
                    date: date,
                    title: language.text("Abstract deadline", "Abstractfrist"),
                    congressTitle: congressTitle,
                    location: location,
                    kind: .congressAbstractDeadline,
                    hasUncertainOutline: congress.abstractSubmissionDeadlineUncertain,
                    language: language
                )
            )
        }

        if let date = organizationTimelineDate(congress.lateAbstractSubmissionDeadline) {
            markers.append(
                organizationTimelineCongressDeadlineMarker(
                    id: "congress-\(congress.id)-late-abstract-deadline",
                    date: date,
                    title: language.text("Late abstract deadline", "Sen abstractfrist"),
                    congressTitle: congressTitle,
                    location: location,
                    kind: .congressLateAbstractDeadline,
                    hasUncertainOutline: congress.lateAbstractSubmissionDeadlineUncertain,
                    language: language
                )
            )
        }

        return markers.sorted { $0.date < $1.date }
    }

    nonisolated private static func organizationTimelineCongressDeadlineMarker(
        id: String,
        date: Date,
        title: String,
        congressTitle: String,
        location: String?,
        kind: OrganizationTimelineSnapshot.MarkerKind,
        hasUncertainOutline: Bool,
        language: AppLanguage
    ) -> OrganizationTimelineSnapshot.Marker {
        let dateText = organizationTimelineCompactDateText(date, includesYear: true, language: language)
        let hoverLines = ([title, congressTitle, location, dateText] as [String?])
            .compactMap { $0?.nonEmpty }
        return OrganizationTimelineSnapshot.Marker(
            id: id,
            date: date,
            title: title,
            hoverText: hoverLines.joined(separator: "\n"),
            kind: kind,
            hasUncertainOutline: hasUncertainOutline
        )
    }

    nonisolated private static func organizationTimelineGrantBars(
        applications: [GrantApplication],
        role: OrganizationRole,
        hideRejectedGrants: Bool,
        effectiveFullySpentDatesByApplicationID: [String: Date],
        language: AppLanguage
    ) -> [OrganizationTimelineSnapshot.Bar] {
        applications.compactMap { application -> OrganizationTimelineSnapshot.Bar? in
            guard let status = organizationTimelineGrantStatus(for: application),
                  let range = organizationTimelineGrantDateRange(for: application, status: status) else { return nil }
            if hideRejectedGrants, status == .rejected || status == .withdrawn {
                return nil
            }
            let rolePrefix = role == .fundManager ? "managed" : "funder"
            let kind: OrganizationTimelineSnapshot.BarKind = role == .fundManager
                ? .fundManagerGrant(status)
                : .grantProviderGrant(status)
            let roleLabel = role == .fundManager
                ? language.text("Fund manager", "Medelsförvaltare")
                : language.text("Grant provider", "Anslagsgivare")
            let localizedGrantTitle = application.localizedGrantName(language: language).nonEmpty
            let grantTitle = localizedGrantTitle ?? language.text("Untitled grant", "Namnlöst anslag")
            let projectTitle = application.projectType?.nonEmpty
            let grantProviderTitle = application.organization.nonEmpty
            let amount = organizationTimelineGrantAmountText(for: application, status: status, language: language)
            let title = ([projectTitle, grantProviderTitle, amount] as [String?])
                .compactMap { $0?.nonEmpty }
                .joined(separator: " · ")
                .nonEmpty
                ?? grantTitle
            let hoverLines = ([roleLabel, projectTitle, grantProviderTitle, grantTitle, amount] as [String?])
                .compactMap { $0?.nonEmpty }
                + [organizationTimelineDateRangeText(start: range.start, end: range.end, language: language)]

            return OrganizationTimelineSnapshot.Bar(
                id: "\(rolePrefix)-grant-\(application.id)",
                applicationID: application.id,
                start: range.start,
                end: range.end,
                title: title,
                hoverText: hoverLines.joined(separator: "\n"),
                kind: kind,
                rowPackingKey: organizationTimelineGrantRowPackingKey(
                    for: application,
                    role: role,
                    localizedGrantTitle: localizedGrantTitle
                ),
                hasUncertainOutline: organizationTimelineGrantHasUncertainOutline(application, status: status),
                fullySpentDate: status == .granted
                    ? (effectiveFullySpentDatesByApplicationID[application.id] ?? projectTimelineFullySpentDate(for: application))
                    : nil
            )
        }
    }

    nonisolated private static func organizationTimelineGrantRowPackingKey(
        for application: GrantApplication,
        role: OrganizationRole,
        localizedGrantTitle: String?
    ) -> String {
        switch role {
        case .grantProvider:
            if let key = organizationTimelineNormalizedPackingKey(localizedGrantTitle) {
                return "grant-name:\(key)"
            }
            return "grant-id:\(application.id)"
        case .fundManager:
            if let organizationID = application.organizationID?.nonEmpty {
                return "provider-id:\(organizationID)"
            }
            if let key = organizationTimelineNormalizedPackingKey(application.organization.nonEmpty) {
                return "provider-name:\(key)"
            }
            return "provider-application:\(application.id)"
        case .association, .company, .employer, .institution:
            return "application:\(application.id)"
        }
    }

    nonisolated private static func organizationTimelineNormalizedPackingKey(_ value: String?) -> String? {
        guard let value else { return nil }
        return PublicationDerivation.normalizedName(value).nonEmpty
    }

    nonisolated private static func organizationTimelineEmploymentBars(
        organization: OrganizationRecord,
        currentUserAuthor: PublicationAuthor?,
        salaryCalculator: ManagerSalaryCalculator?,
        language: AppLanguage,
        referenceDate: Date
    ) -> [OrganizationTimelineSnapshot.Bar] {
        let salaryRanges = (salaryCalculator?.monthlySalaryPeriods ?? []).compactMap { period -> (id: String, value: String, start: Date, end: Date?)? in
            let parsedFrom = organizationTimelineDate(period.from)
            let parsedTo = organizationTimelineDate(period.to)
            guard let start = parsedFrom ?? parsedTo else { return nil }
            return (period.id, period.value, start, parsedTo)
        }

        let employmentRanges = (currentUserAuthor?.employments ?? [])
            .filter { organizationTimelineEmployment($0, matches: organization) }
            .compactMap { employment -> (id: String, title: String, start: Date, end: Date?)? in
                let parsedFrom = organizationTimelineDate(employment.from)
                let parsedTo = organizationTimelineDate(employment.to)
                guard let start = parsedFrom ?? parsedTo else { return nil }
                return (employment.id, employment.localizedTitle(language: language), start, parsedTo)
            }

        if employmentRanges.isEmpty {
            return salaryRanges.compactMap { salary in
                let visualEnd = salary.end ?? organizationTimelineOngoingEndDate(from: salary.start, referenceDate: referenceDate)
                let salaryText = organizationTimelineSalaryText(salary.value, language: language)
                let dateRangeText = organizationTimelineDateRangeText(start: salary.start, end: salary.end, language: language)
                let title = [
                    salaryText,
                    dateRangeText
                ]
                .compactMap { $0.nonEmpty }
                .joined(separator: " · ")
                return OrganizationTimelineSnapshot.Bar(
                    id: "salary-\(salary.id)",
                    applicationID: nil,
                    start: min(salary.start, visualEnd),
                    end: max(salary.start, visualEnd),
                    title: title,
                    hoverText: [
                        language.text("Employer: salary period", "Arbetsgivare: löneperiod"),
                        title
                    ].joined(separator: "\n"),
                    kind: .employment,
                    rowPackingKey: nil,
                    hasUncertainOutline: false
                )
            }
        }

        var bars: [OrganizationTimelineSnapshot.Bar] = []
        for employment in employmentRanges {
            let overlappingSalaryBars = salaryRanges.compactMap { salary -> OrganizationTimelineSnapshot.Bar? in
                let overlapStart = max(employment.start, salary.start)
                let overlapEnd = [employment.end, salary.end].compactMap { $0 }.min()
                    ?? organizationTimelineOngoingEndDate(from: overlapStart, referenceDate: referenceDate)
                guard overlapStart <= overlapEnd else { return nil }
                let salaryText = organizationTimelineSalaryText(salary.value, language: language)
                let dateRangeText = organizationTimelineDateRangeText(
                    start: overlapStart,
                    end: salary.end == nil && employment.end == nil ? nil : overlapEnd,
                    language: language
                )
                let title = [
                    employment.title.nonEmpty,
                    salaryText,
                    dateRangeText
                ]
                .compactMap { $0 }
                .joined(separator: " · ")
                return OrganizationTimelineSnapshot.Bar(
                    id: "employment-\(employment.id)-salary-\(salary.id)",
                    applicationID: nil,
                    start: overlapStart,
                    end: overlapEnd,
                    title: title,
                    hoverText: [
                        language.text("Employer: employment and salary", "Arbetsgivare: anställning och lön"),
                        title
                    ].joined(separator: "\n"),
                    kind: .employment,
                    rowPackingKey: nil,
                    hasUncertainOutline: false
                )
            }

            if overlappingSalaryBars.isEmpty {
                let visualEnd = employment.end ?? organizationTimelineOngoingEndDate(from: employment.start, referenceDate: referenceDate)
                let dateRangeText = organizationTimelineDateRangeText(start: employment.start, end: employment.end, language: language)
                let title = [
                    employment.title.nonEmpty,
                    dateRangeText
                ]
                .compactMap { $0 }
                .joined(separator: " · ")
                bars.append(
                    OrganizationTimelineSnapshot.Bar(
                        id: "employment-\(employment.id)",
                        applicationID: nil,
                        start: min(employment.start, visualEnd),
                        end: max(employment.start, visualEnd),
                        title: title,
                        hoverText: [
                            language.text("Employer: employment", "Arbetsgivare: anställning"),
                            title
                        ].joined(separator: "\n"),
                        kind: .employment,
                        rowPackingKey: nil,
                        hasUncertainOutline: false
                    )
                )
            } else {
                bars.append(contentsOf: overlappingSalaryBars)
            }
        }
        return bars
    }

    nonisolated private static func organizationTimelineOngoingEndDate(
        from start: Date,
        referenceDate: Date
    ) -> Date {
        let calendar = Calendar.current
        let baseDate = max(calendar.startOfDay(for: start), calendar.startOfDay(for: referenceDate))
        let baseYear = calendar.component(.year, from: baseDate)
        return calendar.date(from: DateComponents(year: baseYear + 1, month: 12, day: 31)) ?? baseDate
    }

    nonisolated private static func organizationTimelineEmployment(
        _ employment: PublicationAuthorEmployment,
        matches organization: OrganizationRecord
    ) -> Bool {
        // "Alla kopplingar via id": a linked employment belongs to the
        // organization it points to; only unlinked rows are matched by name.
        if let employmentOrganizationID = employment.organizationID?.trimmedOrNil {
            return employmentOrganizationID == organization.id
        }
        let organizationNames = [
            organization.nameSv,
            organization.nameEn
        ]
        .compactMap { $0.nonEmpty }
        .map(PublicationDerivation.normalizedName)

        let employmentNames = [
            employment.organizationSv,
            employment.organizationEn,
            employment.organization
        ]
        .compactMap { $0.nonEmpty }
        .map(PublicationDerivation.normalizedName)

        return !Set(organizationNames).isDisjoint(with: Set(employmentNames))
    }

    nonisolated private static func organizationTimelineGrantStatus(
        for application: GrantApplication
    ) -> OrganizationTimelineSnapshot.GrantStatus? {
        let status = application.resultLabel.trimmingCharacters(in: .whitespacesAndNewlines)
        if application.isGranted {
            return .granted
        }
        if status == "Väntar svar" {
            return .waiting
        }
        if status == "Avslag" {
            return .rejected
        }
        // Round 17: withdrawn is grey, not red.
        if status == "Tillbakadragen" {
            return .withdrawn
        }
        if application.isToApplyStatus {
            return .toApply
        }
        return nil
    }

    nonisolated private static func organizationTimelineGrantDateRange(
        for application: GrantApplication,
        status: OrganizationTimelineSnapshot.GrantStatus
    ) -> (start: Date, end: Date)? {
        let startDate: Date?
        let endDate: Date?
        switch status {
        case .granted:
            startDate = application.firstDispositionDate
                ?? application.receivedUsageFrom.flatMap { organizationTimelineDate($0) }
                ?? application.grantedDate
                ?? application.decisionDate
                ?? application.applicationDate
            endDate = application.lastDispositionDate
                ?? application.receivedUsageTo.flatMap { organizationTimelineDate($0) }
                ?? application.grantedDate
                ?? application.decisionDate
                ?? startDate
        case .waiting:
            startDate = application.applicationDate ?? application.openDate ?? application.closeDate
            endDate = application.decisionExpectedDate ?? application.closeDate ?? application.applicationDate ?? startDate
        case .rejected, .withdrawn:
            let decision = application.deniedDate ?? application.withdrawnDate ?? application.decisionDate
            startDate = application.applicationDate ?? application.openDate ?? application.closeDate ?? decision
            endDate = decision ?? application.decisionExpectedDate ?? startDate
        case .toApply:
            startDate = application.openDate ?? application.closeDate ?? application.decisionExpectedDate
            endDate = application.closeDate ?? application.decisionExpectedDate ?? application.openDate ?? startDate
        }
        guard let start = startDate ?? endDate else { return nil }
        let end = endDate ?? start
        return start <= end ? (start, end) : (end, start)
    }

    nonisolated private static func organizationTimelineGrantAmountText(
        for application: GrantApplication,
        status: OrganizationTimelineSnapshot.GrantStatus,
        language: AppLanguage
    ) -> String? {
        let amount: Double?
        switch status {
        case .granted:
            amount = application.grantedAmountValue ?? application.appliedAmountValue
        case .rejected, .withdrawn, .waiting:
            amount = application.appliedAmountValue ?? application.preferredBudgetAmountValue
        case .toApply:
            amount = application.preferredBudgetAmountValue
        }
        guard let amount else { return nil }
        return CurrencyFormatter.format(amount, code: application.currency, language: language)
    }

    nonisolated private static func organizationTimelineGrantHasUncertainOutline(
        _ application: GrantApplication,
        status: OrganizationTimelineSnapshot.GrantStatus
    ) -> Bool {
        switch status {
        case .granted:
            return application.grantedOnUncertain
                || application.firstDispositionOnUncertain
                || application.lastDispositionOnUncertain
                || application.receivedUsageFromUncertain
                || application.receivedUsageToUncertain
        case .waiting:
            return application.appliedOnUncertain
                || application.decisionExpectedOnUncertain
                || application.firstDispositionOnUncertain
                || application.lastDispositionOnUncertain
        case .rejected, .withdrawn:
            return application.appliedOnUncertain
                || application.deniedOnUncertain
                || application.withdrawnOnUncertain
                || application.decisionOnUncertain
        case .toApply:
            return application.opensOnUncertain
                || application.closesOnUncertain
                || application.decisionExpectedOnUncertain
        }
    }

    nonisolated private static func organizationTimelineDate(_ value: String?) -> Date? {
        guard let value = value?.trimmedOrNil else { return nil }
        return DateParsers.isoDay.date(from: DateParsers.canonicalizedDayInput(value))
    }

    nonisolated private static func organizationTimelineDateRangeText(
        start: Date,
        end: Date?,
        language: AppLanguage
    ) -> String {
        let startText = DateParsers.isoDay.string(from: start)
        guard let end else {
            return "\(startText) - \(language.text("ongoing", "pågående"))"
        }
        return "\(startText) - \(DateParsers.isoDay.string(from: end))"
    }

    nonisolated private static func organizationTimelineDateRangeText(
        start: Date,
        end: Date,
        language: AppLanguage
    ) -> String {
        organizationTimelineDateRangeText(start: start, end: Optional(end), language: language)
    }

    nonisolated private static func organizationTimelineCompactDateRangeText(
        start: Date,
        end: Date,
        language: AppLanguage
    ) -> String {
        let calendar = Calendar.current
        let startComponents = calendar.dateComponents([.day, .month, .year], from: start)
        let endComponents = calendar.dateComponents([.day, .month, .year], from: end)
        guard let startDay = startComponents.day,
              let startMonth = startComponents.month,
              let startYear = startComponents.year,
              let endDay = endComponents.day,
              let endMonth = endComponents.month,
              let endYear = endComponents.year else {
            return organizationTimelineDateRangeText(start: start, end: end, language: language)
        }

        if startDay == endDay && startMonth == endMonth && startYear == endYear {
            return organizationTimelineCompactDateText(start, includesYear: true, language: language)
        }

        if startMonth == endMonth && startYear == endYear {
            return "\(startDay)-\(endDay) \(organizationTimelineMonthName(startMonth, language: language)) \(startYear)"
        }

        if startYear == endYear {
            return "\(startDay) \(organizationTimelineMonthName(startMonth, language: language))-\(endDay) \(organizationTimelineMonthName(endMonth, language: language)) \(startYear)"
        }

        return [
            organizationTimelineCompactDateText(start, includesYear: true, language: language),
            organizationTimelineCompactDateText(end, includesYear: true, language: language)
        ].joined(separator: "-")
    }

    nonisolated private static func organizationTimelineCompactDateText(
        _ date: Date,
        includesYear: Bool,
        language: AppLanguage
    ) -> String {
        let components = Calendar.current.dateComponents([.day, .month, .year], from: date)
        guard let day = components.day,
              let month = components.month,
              let year = components.year else {
            return DateParsers.isoDay.string(from: date)
        }
        let base = "\(day) \(organizationTimelineMonthName(month, language: language))"
        return includesYear ? "\(base) \(year)" : base
    }

    nonisolated private static func organizationTimelineMonthName(
        _ month: Int,
        language: AppLanguage
    ) -> String {
        let swedish = [
            "januari", "februari", "mars", "april", "maj", "juni",
            "juli", "augusti", "september", "oktober", "november", "december"
        ]
        let english = [
            "January", "February", "March", "April", "May", "June",
            "July", "August", "September", "October", "November", "December"
        ]
        let names = language == .swedish ? swedish : english
        guard names.indices.contains(month - 1) else { return "" }
        return names[month - 1]
    }

    nonisolated private static func organizationTimelineSalaryText(
        _ rawValue: String,
        language: AppLanguage
    ) -> String? {
        guard let trimmed = rawValue.trimmedOrNil else { return nil }
        let amount = GrantParsing.numericValue(from: trimmed)
            .map { CurrencyFormatter.format($0, code: "SEK", language: language) }
            ?? trimmed
        return "\(amount)/\(language.text("month", "mån"))"
    }

    nonisolated static func buildProjectTimelineSnapshot(
        project: ProjectRecord?,
        orderedTimelineApplications: [GrantApplication],
        publications: [PublicationRecord],
        organizationLabels: [String: String],
        language: AppLanguage,
        duplicateApplicationIDs: Set<String> = [],
        effectiveFullySpentDatesByApplicationID: [String: Date] = [:],
        effectiveRemainingAmountsByApplicationID: [String: Double] = [:]
    ) -> ProjectTimelineSnapshot {
        let grantBars = orderedTimelineApplications.compactMap { application -> ProjectTimelineSnapshot.GrantBar? in
            // Status and dates are parsed from text, so each is read once per bar.
            let isGranted = application.isGranted
            let dispositionFrom = application.firstDispositionDate ?? application.receivedUsageFrom.flatMap { DateParsers.isoDay.date(from: $0) }
            let dispositionTo = application.lastDispositionDate ?? application.receivedUsageTo.flatMap { DateParsers.isoDay.date(from: $0) }
            let decisionDate = isGranted ? application.decisionDate : nil
            let decisionExpectedDate = isGranted ? nil : application.decisionExpectedDate
            let applicationDate = application.applicationDate
            let plannedStartDate = dispositionFrom
            let plannedEndDate = dispositionTo ?? plannedStartDate
            let startDate = isGranted
                ? (plannedStartDate ?? decisionDate ?? applicationDate)
                : (plannedStartDate ?? applicationDate)
            let endDate = isGranted
                ? (plannedEndDate ?? decisionDate ?? applicationDate)
                : (plannedEndDate ?? decisionExpectedDate ?? applicationDate)
            guard let start = startDate ?? endDate else { return nil }
            let end = endDate ?? start
            let range = start <= end ? (start, end) : (end, start)
            let selectionID = duplicateApplicationIDs.contains(application.id)
                ? scopedApplicationSelectionID(for: application)
                : application.id
            let barText = projectTimelineBarText(
                for: application,
                organizationLabels: organizationLabels,
                effectiveRemainingAmount: effectiveRemainingAmountsByApplicationID[application.id],
                isGranted: isGranted,
                language: language
            )
            return ProjectTimelineSnapshot.GrantBar(
                applicationID: application.id,
                selectionID: selectionID,
                start: range.0,
                end: range.1,
                isGranted: isGranted,
                fullySpentDate: effectiveFullySpentDatesByApplicationID[application.id]
                    ?? projectTimelineFullySpentDate(for: application, isGranted: isGranted),
                decisionMarkerDate: isGranted ? decisionDate : decisionExpectedDate,
                hasUncertainOutline: !isGranted && (
                    application.decisionExpectedOnUncertain
                        || application.firstDispositionOnUncertain
                        || application.lastDispositionOnUncertain
                        || application.receivedUsageFromUncertain
                        || application.receivedUsageToUncertain
                ),
                barText: barText,
                hoverText: projectTimelineHoverText(
                    baseText: barText,
                    isGranted: isGranted,
                    decisionExpectedDate: decisionExpectedDate,
                    fromDate: dispositionFrom,
                    toDate: dispositionTo,
                    language: language
                )
            )
        }

        let ethicsApplications = project.map { [$0.ethicsBaseApplication] + $0.ethicsAmendments } ?? []
        let ethicsRows = stackAuxiliaryBars(
            ethicsApplications
                .filter { !$0.isEmpty }
                .compactMap { application in
                    let start = application.appliedOn.nonEmpty.flatMap(DateParsers.isoDay.date(from:))
                        ?? application.grantedOn.nonEmpty.flatMap(DateParsers.isoDay.date(from:))
                    let end = application.grantedOn.nonEmpty.flatMap(DateParsers.isoDay.date(from:))
                        ?? application.appliedOn.nonEmpty.flatMap(DateParsers.isoDay.date(from:))
                    guard let start, let end else { return nil }
                    return ProjectTimelineSnapshot.AuxiliaryBar(
                        id: application.id,
                        start: min(start, end),
                        end: max(start, end),
                        title: application.caseNumber.nonEmpty ?? language.text("Ethics", "Etik"),
                        kind: .ethics
                    )
                }
        )

        let dataCollectionRows = stackAuxiliaryBars(
            (project?.hasDataCollection == true ? project?.dataCollections ?? [] : [])
                .filter { !$0.isEmpty }
                .compactMap { dataCollection in
                    let parsedFrom = dataCollection.from.nonEmpty.flatMap(DateParsers.isoDay.date(from:))
                    let parsedTo = dataCollection.to.nonEmpty.flatMap(DateParsers.isoDay.date(from:))
                    let start = parsedFrom ?? parsedTo
                    let end = parsedTo
                        ?? parsedFrom.map { max($0, Date()) }
                        ?? parsedFrom
                    guard let start, let end else { return nil }
                    return ProjectTimelineSnapshot.AuxiliaryBar(
                        id: dataCollection.id,
                        start: min(start, end),
                        end: max(start, end),
                        title: language.text("Data collection", "Datainsamling"),
                        kind: .dataCollection
                    )
                }
        )

        let publicationMarkers = publications
            .compactMap { publication -> ProjectTimelineSnapshot.PublicationMarker? in
                guard let date = publishedDate(for: publication) else { return nil }
                let title = publication.title.nonEmpty ?? language.text("Publication", "Publikation")
                let year = Calendar.current.component(.year, from: date)
                let hoverText = "\(title) (\(year))"
                return ProjectTimelineSnapshot.PublicationMarker(
                    publicationID: publication.id,
                    date: date,
                    title: title,
                    hoverText: hoverText
                )
            }
            .sorted {
                if $0.date != $1.date {
                    return $0.date < $1.date
                }
                return $0.title.localizedStandardCompare($1.title) == .orderedAscending
            }

        let allYears = grantBars.flatMap { [Calendar.current.component(.year, from: $0.start), Calendar.current.component(.year, from: $0.end)] }
            + ethicsRows.flatMap { row in row.flatMap { [Calendar.current.component(.year, from: $0.start), Calendar.current.component(.year, from: $0.end)] } }
            + dataCollectionRows.flatMap { row in row.flatMap { [Calendar.current.component(.year, from: $0.start), Calendar.current.component(.year, from: $0.end)] } }
            + publicationMarkers.map { Calendar.current.component(.year, from: $0.date) }
        let currentYear = Calendar.current.component(.year, from: Date())
        let minYear = min(allYears.min() ?? currentYear, currentYear - 1)
        let maxYear = max(allYears.max() ?? currentYear, currentYear + 1)
        let years = allYears.isEmpty ? [] : Array(minYear...maxYear)

        return ProjectTimelineSnapshot(
            years: years,
            grantBars: grantBars,
            ethicsRows: ethicsRows,
            dataCollectionRows: dataCollectionRows,
            publicationMarkers: publicationMarkers
        )
    }

    nonisolated private static func stackAuxiliaryBars(
        _ bars: [ProjectTimelineSnapshot.AuxiliaryBar]
    ) -> [[ProjectTimelineSnapshot.AuxiliaryBar]] {
        let sortedBars = bars.sorted {
            if $0.start == $1.start {
                return $0.end < $1.end
            }
            return $0.start < $1.start
        }

        var rows: [[ProjectTimelineSnapshot.AuxiliaryBar]] = []
        var rowEndDates: [Date] = []
        for bar in sortedBars {
            if let rowIndex = rowEndDates.firstIndex(where: { $0 <= bar.start }) {
                rows[rowIndex].append(bar)
                rowEndDates[rowIndex] = bar.end
            } else {
                rows.append([bar])
                rowEndDates.append(bar.end)
            }
        }
        return rows
    }

    nonisolated private static func projectTimelineBarText(
        for application: GrantApplication,
        organizationLabels: [String: String],
        effectiveRemainingAmount: Double? = nil,
        isGranted: Bool,
        language: AppLanguage
    ) -> String {
        let organization = Self.organizationLabel(for: application, in: organizationLabels)?.trimmingCharacters(in: .whitespacesAndNewlines).nonEmpty
            ?? application.organization.nonEmpty
            ?? ""
        let amount = CurrencyFormatter.format(isGranted ? application.grantedAmountValue : application.appliedAmountValue, code: application.currency, language: language)
        if isGranted {
            let remaining = CurrencyFormatter.format(effectiveRemainingAmount ?? application.remainingGrantedAmountValue, code: application.currency, language: language)
            return "\(organization), \(amount), \(remaining) \(language.text("left", "kvar"))"
        }
        return "\(organization), \(amount)"
    }

    nonisolated private static func projectTimelineHoverText(
        baseText: String,
        isGranted: Bool,
        decisionExpectedDate: Date?,
        fromDate: Date?,
        toDate: Date?,
        language: AppLanguage
    ) -> String {
        if isGranted {
            if let fromDate, let toDate {
                return "\(baseText)\n\(language.text("Disposition period", "Disponeringstid")): \(DateParsers.isoDay.string(from: fromDate)) - \(DateParsers.isoDay.string(from: toDate))"
            }
            if let fromDate {
                return "\(baseText)\n\(language.text("Disposition starts", "Disponering startar")): \(DateParsers.isoDay.string(from: fromDate))"
            }
            if let toDate {
                return "\(baseText)\n\(language.text("Disposition ends", "Disponering slutar")): \(DateParsers.isoDay.string(from: toDate))"
            }
            return baseText
        }

        var details: [String] = [baseText]
        if let decisionExpectedDate {
            details.append("\(language.text("Decision expected", "Besked väntas")): \(DateParsers.isoDay.string(from: decisionExpectedDate))")
        }
        if let fromDate, let toDate {
            details.append("\(language.text("Disposition period", "Disponeringstid")): \(DateParsers.isoDay.string(from: fromDate)) - \(DateParsers.isoDay.string(from: toDate))")
        } else if let fromDate {
            details.append("\(language.text("Disposition starts", "Disponering startar")): \(DateParsers.isoDay.string(from: fromDate))")
        } else if let toDate {
            details.append("\(language.text("Disposition ends", "Disponering slutar")): \(DateParsers.isoDay.string(from: toDate))")
        }
        return details.joined(separator: "\n")
    }

    nonisolated private static func projectTimelineFullySpentDate(
        for application: GrantApplication,
        isGranted: Bool? = nil
    ) -> Date? {
        guard isGranted ?? application.isGranted,
              let granted = application.grantedAmountValue,
              granted > 0 else {
            return nil
        }

        let datedPeriods = application.receivedConsumptionPeriods.compactMap { period -> (date: Date, amount: Double)? in
            guard let amount = period.amountValue, amount > 0 else { return nil }
            let date = period.to.nonEmpty.flatMap(DateParsers.isoDay.date(from:))
                ?? period.from.nonEmpty.flatMap(DateParsers.isoDay.date(from:))
            guard let date else { return nil }
            return (date, amount)
        }
        .sorted { lhs, rhs in
            if lhs.date == rhs.date {
                return lhs.amount < rhs.amount
            }
            return lhs.date < rhs.date
        }

        guard !datedPeriods.isEmpty else { return nil }

        var cumulative = 0.0
        for period in datedPeriods {
            cumulative += period.amount
            if cumulative >= granted - 0.5 {
                return period.date
            }
        }
        return nil
    }

    /// "Alla kopplingar via id": the key an organization's label is also
    /// stored under in the label tables of the project caches, so that an
    /// application's grant provider is found by id first.
    nonisolated static let organizationLabelIDKeyPrefix = "\u{1F}organization-id:"

    /// The grant provider's label for an application from a label table: by
    /// the application's organization id first, by its written name second.
    nonisolated static func organizationLabel(for application: GrantApplication, in labels: [String: String]) -> String? {
        if let id = application.organizationID?.trimmedOrNil,
           let label = labels[organizationLabelIDKeyPrefix + id] {
            return label
        }
        return labels[application.organization]
    }

    nonisolated private static func displayTitle(
        for application: GrantApplication,
        organizationLabels: [String: String],
        language: AppLanguage
    ) -> String {
        let organizationName = Self.organizationLabel(for: application, in: organizationLabels)?.trimmingCharacters(in: .whitespacesAndNewlines).nonEmpty
        let grantName = application.grantName.nonEmpty

        switch (organizationName, grantName) {
        case let (.some(organization), .some(grant)):
            return "\(organization), \(grant)"
        case let (.some(organization), nil):
            return organization
        case let (nil, .some(grant)):
            return grant
        default:
            return language.text("Untitled grant", "Namnlöst anslag")
        }
    }

    nonisolated private static func projectApplicationStatusPriority(_ status: String) -> Int {
        switch status {
        case "", "Att söka":
            return 0
        case "Väntar svar":
            return 1
        case "Beviljat":
            return 2
        case "Tillbakadragen":
            return 3
        case "Avslag":
            return 4
        case "Ej sökt":
            return 5
        default:
            return 6
        }
    }

    nonisolated private static func projectPublicationSortOrder(_ lhs: PublicationRecord, _ rhs: PublicationRecord) -> Bool {
        let leftStatus = PublicationStatus.fromStored(lhs.statusLabel)
        let rightStatus = PublicationStatus.fromStored(rhs.statusLabel)
        let leftBucket = projectPublicationStatusBucket(for: leftStatus)
        let rightBucket = projectPublicationStatusBucket(for: rightStatus)

        if leftBucket != rightBucket {
            return leftBucket < rightBucket
        }

        switch leftBucket {
        case 0:
            return lhs.title.localizedStandardCompare(rhs.title) == .orderedAscending
        case 1:
            let leftDate = firstSubmittedDate(for: lhs) ?? .distantPast
            let rightDate = firstSubmittedDate(for: rhs) ?? .distantPast
            if leftDate != rightDate {
                return leftDate > rightDate
            }
            return lhs.title.localizedStandardCompare(rhs.title) == .orderedAscending
        default:
            let leftDate = publishedDate(for: lhs) ?? .distantPast
            let rightDate = publishedDate(for: rhs) ?? .distantPast
            if leftDate != rightDate {
                return leftDate > rightDate
            }
            return lhs.title.localizedStandardCompare(rhs.title) == .orderedAscending
        }
    }

    nonisolated private static func projectPublicationStatusBucket(for status: PublicationStatus) -> Int {
        switch status {
        case .inPreparation:
            return 0
        case .submitted:
            return 1
        default:
            return 2
        }
    }

    nonisolated private static func firstSubmittedDate(for publication: PublicationRecord) -> Date? {
        publication.statusTimeline
            .filter { PublicationStatus.fromStored($0.status).isSubmittedFamily }
            .compactMap { $0.date.flatMap(DateParsers.isoDay.date(from:)) }
            .min()
    }

    nonisolated private static func publishedDate(for publication: PublicationRecord) -> Date? {
        publication.statusTimeline
            .filter { PublicationStatus.fromStored($0.status) == .published }
            .compactMap { $0.date.flatMap(DateParsers.isoDay.date(from:)) }
            .max()
    }

    nonisolated private static func grantTimelineDateRange(for application: GrantApplication) -> (start: Date, end: Date)? {
        if application.isGranted {
            guard
                let start = application.firstDispositionDate ?? application.receivedUsageFrom.flatMap({ DateParsers.isoDay.date(from: $0) }),
                let end = application.lastDispositionDate ?? application.receivedUsageTo.flatMap({ DateParsers.isoDay.date(from: $0) })
            else {
                return nil
            }
            return (min(start, end), max(start, end))
        }

        guard
            let start = application.firstDispositionDate ?? application.receivedUsageFrom.flatMap({ DateParsers.isoDay.date(from: $0) }),
            let end = application.lastDispositionDate ?? application.receivedUsageTo.flatMap({ DateParsers.isoDay.date(from: $0) })
        else {
            return nil
        }

        return (min(start, end), max(start, end))
    }

    func normalizedPersonLookupName(_ value: String) -> String {
        collapsingWhitespaceRuns(
            value.folding(options: [.diacriticInsensitive, .caseInsensitive], locale: .current)
        )
    }

    nonisolated private static func canonicalPublicationJournalLookupName(_ value: String) -> String {
        switch value.trimmingCharacters(in: .whitespacesAndNewlines) {
        case "Ateriosclerosis, Thrombosis, and Vascular Biology":
            return "Arteriosclerosis, Thrombosis, and Vascular Biology"
        default:
            return value.trimmingCharacters(in: .whitespacesAndNewlines)
        }
    }

    nonisolated static func normalizedPublicationJournalLookupKey(_ value: String) -> String {
        collapsingWhitespaceRuns(
            canonicalPublicationJournalLookupName(value)
                .folding(options: [.diacriticInsensitive, .caseInsensitive], locale: .current)
        )
    }

    nonisolated static func normalizedPublicationJournalISSNKey(_ value: String) -> String {
        value
            .uppercased()
            .replacingOccurrences(of: "-", with: "")
            .replacingOccurrences(of: " ", with: "")
            .trimmingCharacters(in: .whitespacesAndNewlines)
    }

    private func localizedOptionDisplayName<T: LocalizedNamedRecord>(_ option: T) -> String {
        language == .swedish ? (option.nameSv.nonEmpty ?? option.nameEn) : (option.nameEn.nonEmpty ?? option.nameSv)
    }

    private func organizationCategoryIcons(for option: OrganizationRecord) -> [String] {
        var icons: [String] = []

        if option.roles.contains(.grantProvider) {
            icons.append("banknote.fill")
        }
        if option.roles.contains(.fundManager) || option.roles.contains(.employer) {
            icons.append("briefcase.fill")
        }
        if option.roles.contains(.institution) {
            icons.append("graduationcap.fill")
        }
        if option.roles.contains(.association) {
            icons.append("person.3.fill")
        }
        if option.roles.contains(.company) {
