    private func records<T>(for key: String?, idsByKey: [String: [String]], lookup: [String: T]) -> [T] {
        guard let normalized = key?.trimmedOrNil,
              let ids = idsByKey[normalized] else { return [] }
        return ids.compactMap { lookup[$0] }
    }

    private func records<T: Identifiable>(for ids: [String], in records: [T]) -> [T] where T.ID == String {
        let recordsByID = Dictionary(grouping: records, by: \.id)
        var offsetsByID: [String: Int] = [:]
        var resolved: [T] = []
        resolved.reserveCapacity(min(ids.count, records.count))
        for id in ids {
            let offset = offsetsByID[id, default: 0]
            guard let matches = recordsByID[id], offset < matches.count else { continue }
            resolved.append(matches[offset])
            offsetsByID[id] = offset + 1
        }
        return resolved
    }

    private func applicationMatchesProjectName(_ application: GrantApplication, _ projectName: String) -> Bool {
        guard let normalizedName = projectName.trimmedOrNil else { return false }
        let targetProject = project(named: normalizedName)
        // "Alla kopplingar via id": an application that points to a project
        // belongs to that project only, whatever its text says.
        if let applicationProject = linkedProject(of: application) {
            return applicationProject.id == targetProject?.id
        }
        var candidateNames = Set([normalizedName])
        if let targetProject {
            candidateNames.insert(targetProject.nameSv)
            if let nameEn = targetProject.nameEn.trimmedOrNil {
                candidateNames.insert(nameEn)
            }
        }
        if let applicationProjectName = application.projectType?.trimmedOrNil,
           candidateNames.contains(applicationProjectName) {
            return true
        }
        return false
    }

    /// F13: a publication's journal, and the journals of earlier attempts, by id.
    private func synchronizePublicationJournalIDs(_ record: inout PublicationRecord) {
        // "Alla kopplingar via id": the stored id decides; the written name
        // only moves the link when it names another journal, and an empty
        // name clears it.
        func journalID(for name: String, linkedID: String?) -> String? {
            Self.idFirstLinkedRecord(
                id: linkedID,
                name: name,
                byID: { publicationJournal(id: $0) },
                byName: { publicationJournal(named: $0) },
                recordID: { $0.id },
                recordNames: { [$0.name, $0.abbreviatedName, $0.issnLTWAAbbreviatedName, $0.issn, $0.eissn] }
            )?.id
        }
        record.journalID = journalID(for: record.journal, linkedID: record.journalID)
        for attemptIndex in record.previousAttempts.indices {
            let attempt = record.previousAttempts[attemptIndex]
            record.previousAttempts[attemptIndex].journalID = journalID(for: attempt.journal, linkedID: attempt.journalID)
        }
    }

    /// F13b: the people in a publication, and in its tasks, by id. The names
    /// stay as display text.
    private func synchronizePublicationPersonAuthorIDs(_ record: inout PublicationRecord) {
        record.authorIDs = synchronizedPersonAuthorIDs(existingIDs: record.authorIDs, names: record.authorNames)
        if let correspondingAuthorName = record.correspondingAuthorName?.trimmedOrNil {
            if let authorID = publicationAuthorID(forPresentedName: correspondingAuthorName) {
                record.correspondingAuthorID = authorID
            } else if !publicationAuthors.isEmpty {
                record.correspondingAuthorID = nil
            }
        } else {
            record.correspondingAuthorID = nil
        }
        synchronizeTaskParticipantAuthorIDs(&record.publicationTasks)
    }

    /// F13b: task participants by id (older task lists kept on their records).
    func synchronizeTaskParticipantAuthorIDs(_ tasks: inout [PublicationTaskItem]) {
        for taskIndex in tasks.indices {
            tasks[taskIndex].participantAuthorIDs = synchronizedPersonAuthorIDs(
                existingIDs: tasks[taskIndex].participantAuthorIDs,
                names: tasks[taskIndex].participantNames
            )
        }
    }

    /// F13b: task participants by id (older task lists kept on their records).
    func synchronizeTaskParticipantAuthorIDs(_ tasks: inout [ProjectTaskItem]) {
        for taskIndex in tasks.indices {
            tasks[taskIndex].participantAuthorIDs = synchronizedPersonAuthorIDs(
                existingIDs: tasks[taskIndex].participantAuthorIDs,
                names: tasks[taskIndex].participantNames
            )
        }
    }

    /// F13b: participants of the shared tasks by id.
    func synchronizeTaskParticipantAuthorIDs(_ tasks: inout [TaskItem]) {
        for taskIndex in tasks.indices {
            tasks[taskIndex].participantAuthorIDs = synchronizedPersonAuthorIDs(
                existingIDs: tasks[taskIndex].participantAuthorIDs,
                names: tasks[taskIndex].participantNames
            )
        }
    }

    /// F13b: meeting participants by id.
    func synchronizeMeetingParticipantAuthorIDs(_ meetings: inout [CalendarMeetingRecord]) {
        for meetingIndex in meetings.indices {
            meetings[meetingIndex].participantAuthorIDs = synchronizedPersonAuthorIDs(
                existingIDs: meetings[meetingIndex].participantAuthorIDs,
                names: meetings[meetingIndex].participantNames
            )
        }
    }

    private func derivePublicationFields(for record: PublicationRecord, previous: PublicationRecord) -> PublicationRecord {
        var updated = record
        updated.authorNames = updated.authorNames.map { name in
            publicationAuthor(
                matchingPresentedName: name,
                includeNameVariants: false
            )?.name ?? name
        }
        updated.authorNames = Array(NSOrderedSet(array: updated.authorNames.compactMap(\.trimmedOrNil))) as? [String] ?? updated.authorNames
        let projectNameChanged = updated.projectName?.trimmedOrNil != previous.projectName?.trimmedOrNil
        let canonicalProject = projectNameChanged
            ? (project(named: updated.projectName) ?? project(id: updated.projectID))
            : resolvedProject(id: updated.projectID, name: updated.projectName)
        if let canonicalProject {
            updated.projectID = canonicalProject.id
            updated.projectName = canonicalProject.nameSv
        } else {
            updated.projectID = nil
        }

        // F13: the journal by id. The written name decides which journal (it may
        // be an abbreviation or ISSN, so it is not rewritten); a rename reaches
        // the record through propagateJournalRename.
        synchronizePublicationJournalIDs(&updated)
        // F13b: authors, corresponding author and task participants by id.
        synchronizePublicationPersonAuthorIDs(&updated)

        let currentStatus = PublicationStatus.fromStored(updated.statusLabel)
        let previousStatus = PublicationStatus.fromStored(previous.statusLabel)

        if currentStatus.isSubmittedFamily && updated.currentSubmissionDate == nil {
            updated.currentSubmissionDate = updated.statusDate ?? previous.currentSubmissionDate
        }

        if currentStatus == .rejected, previousStatus.isSubmittedFamily, previousStatus != .rejected {
            let attempt = PublicationAttempt(
                journal: updated.journal,
                journalID: updated.journalID,
                submittedOn: updated.currentSubmissionDate ?? previous.currentSubmissionDate ?? previous.statusDate,
                rejectedOn: updated.statusDate
            )
            if !updated.previousAttempts.contains(where: { $0.dedupeKey == attempt.dedupeKey }) {
                updated.previousAttempts.append(attempt)
            }
            updated.currentSubmissionDate = nil
        }

        let linkedAuthors = updated.authorNames.compactMap { publicationAuthor(matchingPresentedName: $0) }
        updated.position = PublicationDerivation.position(
            for: updated.authorNames,
            currentUserNames: currentUserPresentedNames(),
            sharedFirstAuthorship: updated.sharedFirstAuthorship,
            sharedLastAuthorship: updated.sharedLastAuthorship
        )
        updated.independence = PublicationDerivation.independence(
            for: updated.authorNames,
            formerSupervisorNames: currentUserFormerSupervisorNames()
        )
        updated.geography = PublicationDerivation.geography(for: linkedAuthors, homeCountry: homeCountryName)

        let referenceDate = updated.statusDate.flatMap { DateParsers.isoDay.date(from: $0) }
            ?? updated.year.nonEmpty.flatMap { DateParsers.isoDay.date(from: "\($0)-01-01") }
        updated.phdStage = PublicationDerivation.phdStage(
            for: referenceDate,
            phdDate: currentUserDoctoralCompletionDate()
        )

        if let journal = linkedJournal(of: updated) {
            updated.journal = journal.name
            let snapshot = journal.rankingSnapshot(for: updated.yearValue)
            let jifMetric = journal.preferredMetric(for: [.clarivateScieJIF, .clarivateEsciJIF], publicationYear: updated.yearValue)
            if let norwegian = snapshot.norwegian.nonEmpty {
                updated.norwegianCurrent = norwegian
            }
            if let sjr = snapshot.sjr.nonEmpty {
                updated.sjrCurrent = sjr
            }
            if let quartile = jifMetric?.quartile.nonEmpty {
                updated.jifQuartileCurrent = quartile
            }
            if let jif = snapshot.jif.nonEmpty {
                updated.jifCurrent = snapshot.uncertain
                    ? "\(jif) (\(language.text("uncertain", "osäkert")))"
                    : jif
            }
        }

        return updated
    }

