    private static func isPendingStatus(_ value: String?) -> Bool {
        guard let trimmed = value?.trimmedOrNil else { return true }
        return trimmed == "Väntar svar" || trimmed == "Att söka"
    }

    private func shouldMigrateLegacyOtherPublication(_ entry: CVOtherPublicationEntry) -> Bool {
        if entry.isDoctoralThesis {
            return false
        }

        let categories = [
            entry.localizedCategory(language: .swedish),
            entry.localizedCategory(language: .english),
        ]
        .map {
            $0
                .folding(options: [.diacriticInsensitive, .caseInsensitive], locale: Locale(identifier: "sv_SE"))
                .trimmingCharacters(in: .whitespacesAndNewlines)
        }

        if categories.contains(where: { $0 == "ovrigt" || $0 == "other" }) {
            return false
        }

        return entry.localizedTitle(language: .english).nonEmpty != nil
            || entry.localizedTitle(language: .swedish).nonEmpty != nil
    }

    private func migratedAuthorNames(from raw: String) -> [String] {
        raw
            .split(whereSeparator: { $0 == "," || $0 == ";" })
            .map { String($0).trimmingCharacters(in: .whitespacesAndNewlines) }
            .filter { !$0.isEmpty }
    }

    private func publicationMigrationYear(from raw: String) -> String {
        let trimmed = raw.trimmingCharacters(in: .whitespacesAndNewlines)
        guard trimmed.count >= 4 else { return "" }
        let prefix = String(trimmed.prefix(4))
        return Int(prefix) == nil ? "" : prefix
    }

    private func migrationKey(for entry: CVOtherPublicationEntry) -> String? {
        let title = entry.localizedTitle(language: .english).nonEmpty
            ?? entry.localizedTitle(language: .swedish).nonEmpty
        let journal = entry.localizedOutlet(language: .english).nonEmpty
            ?? entry.localizedOutlet(language: .swedish).nonEmpty
        guard let title, let journal else { return nil }

        let normalizedTitle = title
            .folding(options: [.diacriticInsensitive, .caseInsensitive], locale: .current)
            .trimmingCharacters(in: .whitespacesAndNewlines)
        let normalizedJournal = journal
            .folding(options: [.diacriticInsensitive, .caseInsensitive], locale: .current)
            .trimmingCharacters(in: .whitespacesAndNewlines)
        let normalizedDOI = normalizedDOI(entry.doi)
        if !normalizedDOI.isEmpty {
            return "doi:\(normalizedDOI.lowercased())"
        }
        return [
            normalizedTitle.lowercased(),
            normalizedJournal.lowercased(),
            publicationMigrationYear(from: entry.date),
        ]
        .joined(separator: "|")
    }

    private func migrationKey(for publication: PublicationRecord) -> String {
        let normalizedTitle = publication.title
            .folding(options: [.diacriticInsensitive, .caseInsensitive], locale: .current)
            .trimmingCharacters(in: .whitespacesAndNewlines)
        let normalizedJournal = publication.journal
            .folding(options: [.diacriticInsensitive, .caseInsensitive], locale: .current)
            .trimmingCharacters(in: .whitespacesAndNewlines)
        let normalizedDOI = normalizedDOI(publication.doi)
        if !normalizedDOI.isEmpty {
            return "doi:\(normalizedDOI.lowercased())"
        }
        return [normalizedTitle.lowercased(), normalizedJournal.lowercased(), publication.year.trimmingCharacters(in: .whitespacesAndNewlines)]
            .joined(separator: "|")
    }

    private func doctoralCandidateMergeKey(for candidate: DoctoralCandidateRecord) -> String {
        if let authorID = candidate.candidateAuthorID?.trimmedOrNil {
            return authorID
        }
        return PublicationDerivation.normalizedName(candidate.candidateName)
    }

    nonisolated static func decode<T: Decodable>(_ type: T.Type, from url: URL) throws -> T {
        let data = try Data(contentsOf: url)
        return try JSONDecoder().decode(type, from: data)
    }

    private func decodeOrganizationsForState(from data: Data) throws -> [OrganizationRecord] {
        try JSONDecoder().decode([OrganizationRecord].self, from: data)
    }

    private func decodeProjectsForState(from data: Data) throws -> [ProjectRecord] {
        try JSONDecoder().decode([ProjectRecord].self, from: data)
    }

    nonisolated static func loadRequiredOrganizationRecords(from sqliteStore: SQLiteDocumentStore) throws -> [OrganizationRecord] {
        if let records = try sqliteStore.load([OrganizationRecord].self, named: "organizations") {
