    nonisolated static func encode<T: Encodable>(_ value: T, to url: URL) throws {
        let encoder = makePersistenceEncoder()
        let data = try encoder.encode(value)
        try data.write(to: url, options: .atomic)
    }

    func hasSQLiteStoredData() throws -> Bool {
        guard let sqliteStore else { return false }
        return try sqliteStore.containsDocument(named: "applications")
    }
}

private extension Sequence where Element == String {
    func mostCommonLocalizedValue() -> String? {
        var counts: [String: Int] = [:]
        for value in self {
            counts[value, default: 0] += 1
        }
        return counts.max { lhs, rhs in
            if lhs.value != rhs.value { return lhs.value < rhs.value }
            return lhs.key.localizedStandardCompare(rhs.key) == .orderedDescending
        }?.key
    }
}

private extension Sequence where Element == TeachingAssignmentCategory {
    func mostCommonTeachingCategory() -> TeachingAssignmentCategory? {
        var counts: [TeachingAssignmentCategory: Int] = [:]
        for value in self {
            counts[value, default: 0] += 1
        }
        return counts.max { lhs, rhs in lhs.value < rhs.value }?.key
    }
}

enum CurrencyFormatter {
    private static let decimal: NumberFormatter = {
        let formatter = NumberFormatter()
        formatter.numberStyle = .decimal
        formatter.maximumFractionDigits = 0
        formatter.minimumFractionDigits = 0
        formatter.groupingSeparator = " "
        formatter.usesGroupingSeparator = true
        formatter.locale = Locale(identifier: "en_US_POSIX")
        return formatter
    }()

    /// Round 16: a missing amount shows a dash instead of "N/A". With a
    /// language, Swedish kronor are written "kr" in Swedish and "SEK" in
    /// English (see `AmountFormatter`); without one the code is kept as is.
    static func format(_ value: Double?, code: String? = "SEK", language: AppLanguage? = nil) -> String {
        guard let value else { return AmountFormatter.missing }
        let amount = decimal.string(from: NSNumber(value: value)) ?? String(Int(value))
        if let code = code?.trimmedOrNil {
            if let language {
                return "\(amount) \(AmountFormatter.unit(forCurrencyCode: code, language: language))"
            }
            return "\(amount) \(code)"
        }
        return amount
    }
}


// MARK: - Round 1 migrations (must live in this file: the record arrays have private setters)

extension GrantDataStore {
    /// F2/F3 migration: derived status and author strings for every stored contribution.
    func normalizeConferenceContributionsForRound1() -> Bool {
        var didChange = false
        for index in cvConferenceContributions.indices {
            var contribution = cvConferenceContributions[index]
            contribution.normalize()
            if contribution != cvConferenceContributions[index] {
                cvConferenceContributions[index] = contribution
                didChange = true
            }
        }
        return didChange
    }

    /// F9 migration: "New project" is replaced by the Swedish name so that the
    /// missing translation is flagged instead of a placeholder being shown.
    func clearPlaceholderProjectNames() -> Bool {
        var didChange = false
        for index in projects.indices
        where projects[index].nameEn.hasPrefix("New project") && !projects[index].nameSv.hasPrefix("Nytt projekt") {
            projects[index].nameEn = projects[index].nameSv
            didChange = true
        }
        return didChange
    }
}

// MARK: - F4/F7 teaching catalogue migration
// Lives in this file because teachingCourses has a private setter.

extension GrantDataStore {
    /// F13 migration: fill the id next to every reference that was stored by
    /// name only, wherever the name matches exactly one record. Names are never
    /// removed or changed, and no record is added or removed; if a count
    /// changes the migration is undone. Running it again changes nothing.
    /// Returns a Swedish report, empty when nothing changed.
    @discardableResult
    func migrateNameReferencesToIDsForF13() -> [String] {
        let previousAssignments = teachingAssignments
        let previousComponents = teachingComponents
        let previousPublications = publicationRecords
        let previousReviews = cvReviewEntries
        let previousContributions = cvConferenceContributions

        for index in teachingComponents.indices {
            teachingComponents[index] = synchronizedTeachingComponentRelations(teachingComponents[index])
        }
        for index in teachingAssignments.indices {
            synchronizeTeachingAssignmentReferences(&teachingAssignments[index])
        }
        for index in publicationRecords.indices {
            synchronizePublicationJournalIDs(&publicationRecords[index])
        }
        for index in cvReviewEntries.indices {
            cvReviewEntries[index] = canonicalizedReviewEntry(cvReviewEntries[index])
        }
        for index in cvConferenceContributions.indices {
            cvConferenceContributions[index] = canonicalizedConferenceContribution(cvConferenceContributions[index])
        }

        guard teachingAssignments.count == previousAssignments.count,
              teachingComponents.count == previousComponents.count,
              publicationRecords.count == previousPublications.count,
              cvReviewEntries.count == previousReviews.count,
              cvConferenceContributions.count == previousContributions.count else {
            teachingAssignments = previousAssignments
            teachingComponents = previousComponents
            publicationRecords = previousPublications
            cvReviewEntries = previousReviews
            cvConferenceContributions = previousContributions
            return []
        }
        guard teachingAssignments != previousAssignments
            || teachingComponents != previousComponents
            || publicationRecords != previousPublications
            || cvReviewEntries != previousReviews
            || cvConferenceContributions != previousContributions else {
            return []
        }

        func line(_ label: String, linked: Int, of total: Int) -> String {
            "\(label): \(linked) av \(total) kopplade med id"
        }
        let formatNamed = teachingAssignments.filter { $0.activityTypeName.nonEmpty != nil }
        let studentNamed = teachingAssignments.filter { $0.studentName.nonEmpty != nil }
        let componentsWithOrganization = teachingComponents.filter { $0.institution.nonEmpty != nil }
        let componentsWithFormat = teachingComponents.filter { $0.activityTypeName.nonEmpty != nil }
        let publicationsWithJournal = publicationRecords.filter { $0.journal.nonEmpty != nil }
        let journalReviews = cvReviewEntries.filter { $0.journalName.nonEmpty != nil }
        let organizationReviews = cvReviewEntries.filter { $0.organizationName.nonEmpty != nil }
        let contributionsWithProject = cvConferenceContributions.filter { $0.projectName.nonEmpty != nil }
        return [
            line("Uppdrag, format", linked: formatNamed.filter { $0.activityTypeID != nil }.count, of: formatNamed.count),
            line("Uppdrag, student", linked: studentNamed.filter { $0.studentAuthorID != nil }.count, of: studentNamed.count),
            line("Moment, organisation", linked: componentsWithOrganization.filter { $0.institutionID != nil }.count, of: componentsWithOrganization.count),
            line("Moment, format", linked: componentsWithFormat.filter { $0.activityTypeID != nil }.count, of: componentsWithFormat.count),
            line("Publikationer, tidskrift", linked: publicationsWithJournal.filter { $0.journalID != nil }.count, of: publicationsWithJournal.count),
            line("Granskningar, tidskrift", linked: journalReviews.filter { $0.journalID != nil }.count, of: journalReviews.count),
            line("Granskningar, organisation", linked: organizationReviews.filter { $0.organizationID != nil }.count, of: organizationReviews.count),
            line("Konferensbidrag, projekt", linked: contributionsWithProject.filter { $0.projectID != nil }.count, of: contributionsWithProject.count),
        ]
    }

    /// F13b migration: fill the id list next to every list of people that was
    /// stored by name only (co-applicants, project members, publication
    /// authors and corresponding author, task and meeting participants),
    /// wherever a name matches a researcher. Names are never removed or
    /// changed, and no record is added or removed; if a count or a name
    /// changes the migration is undone. Running it again changes nothing.
    /// Returns a Swedish report, empty when nothing changed.
    @discardableResult
    func migratePersonReferencesToIDsForF13b() -> [String] {
        guard !publicationAuthors.isEmpty else { return [] }
        let previousApplications = applications
        let previousProjects = projects
        let previousPublications = publicationRecords
        let baselineMetadata = editableMetadataSnapshot

        for index in applications.indices {
            let ids = synchronizedPersonAuthorIDs(
                existingIDs: applications[index].coApplicantAuthorIDs,
                names: applications[index].coApplicants
            )
            if applications[index].coApplicantAuthorIDs != ids {
                applications[index].coApplicantAuthorIDs = ids
            }
        }
        for index in projects.indices {
            var project = projects[index]
            project.collaboratorAuthorIDs = synchronizedPersonAuthorIDs(
                existingIDs: project.collaboratorAuthorIDs,
                names: project.collaboratorNames
            )
            synchronizeTaskParticipantAuthorIDs(&project.projectTasks)
            if project != projects[index] {
                projects[index] = project
            }
        }
        for index in publicationRecords.indices {
            var record = publicationRecords[index]
            synchronizePublicationPersonAuthorIDs(&record)
            if record != publicationRecords[index] {
                publicationRecords[index] = record
            }
        }
        var updatedMetadata = baselineMetadata
        if var tasks = updatedMetadata.taskItems {
            synchronizeTaskParticipantAuthorIDs(&tasks)
            updatedMetadata.taskItems = tasks
        }
        if var tasks = updatedMetadata.teachingWorkspaceTasks {
            synchronizeTaskParticipantAuthorIDs(&tasks)
            updatedMetadata.teachingWorkspaceTasks = tasks
        }
        if var meetings = updatedMetadata.calendarMeetingRecords {
            synchronizeMeetingParticipantAuthorIDs(&meetings)
            updatedMetadata.calendarMeetingRecords = meetings
        }
        let didChangeMetadata = updatedMetadata != baselineMetadata

        let currentTasks = updatedMetadata.taskItems ?? []
        let previousTasks = baselineMetadata.taskItems ?? []
        let currentTeachingTasks = updatedMetadata.teachingWorkspaceTasks ?? []
        let previousTeachingTasks = baselineMetadata.teachingWorkspaceTasks ?? []
        let currentMeetings = updatedMetadata.calendarMeetingRecords ?? []
        let previousMeetings = baselineMetadata.calendarMeetingRecords ?? []
        let countsAndNamesKept = applications.count == previousApplications.count
            && projects.count == previousProjects.count
            && publicationRecords.count == previousPublications.count
            && currentTasks.count == previousTasks.count
            && currentTeachingTasks.count == previousTeachingTasks.count
            && currentMeetings.count == previousMeetings.count
            && applications.map(\.coApplicants) == previousApplications.map(\.coApplicants)
            && projects.map(\.collaboratorNames) == previousProjects.map(\.collaboratorNames)
            && publicationRecords.map(\.authorNames) == previousPublications.map(\.authorNames)
            && publicationRecords.map(\.correspondingAuthorName) == previousPublications.map(\.correspondingAuthorName)
            && currentTasks.map(\.participantNames) == previousTasks.map(\.participantNames)
            && currentTeachingTasks.map(\.participantNames) == previousTeachingTasks.map(\.participantNames)
            && currentMeetings.map(\.participantNames) == previousMeetings.map(\.participantNames)
        guard countsAndNamesKept else {
            applications = previousApplications
            projects = previousProjects
            publicationRecords = previousPublications
            return []
        }
        guard applications != previousApplications
            || projects != previousProjects
            || publicationRecords != previousPublications
            || didChangeMetadata else {
            return []
        }
        if didChangeMetadata {
            metadata = updatedMetadata
        }

        func line(_ label: String, linked: Int, of total: Int) -> String {
            "\(label): \(linked) av \(total) kopplade med id"
        }
        func namedCount(_ lists: [[String]]) -> Int {
            lists.reduce(0) { $0 + $1.compactMap(\.trimmedOrNil).count }
        }
        func linkedCount(_ lists: [[String]]) -> Int {
            lists.reduce(0) { $0 + $1.count }
        }
        let projectTasks = projects.flatMap(\.projectTasks)
        let publicationTasks = publicationRecords.flatMap(\.publicationTasks)
        let correspondingNamed = publicationRecords.filter { $0.correspondingAuthorName?.trimmedOrNil != nil }
        return [
            line("Ansökningar, sökande", linked: linkedCount(applications.map(\.coApplicantAuthorIDs)), of: namedCount(applications.map(\.coApplicants))),
            line("Projekt, medarbetare", linked: linkedCount(projects.map(\.collaboratorAuthorIDs)), of: namedCount(projects.map(\.collaboratorNames))),
            line("Projekt, uppgiftsdeltagare", linked: linkedCount(projectTasks.map(\.participantAuthorIDs)), of: namedCount(projectTasks.map(\.participantNames))),
            line("Publikationer, författare", linked: linkedCount(publicationRecords.map(\.authorIDs)), of: namedCount(publicationRecords.map(\.authorNames))),
            line("Publikationer, korresponderande författare", linked: correspondingNamed.filter { $0.correspondingAuthorID != nil }.count, of: correspondingNamed.count),
            line("Publikationer, uppgiftsdeltagare", linked: linkedCount(publicationTasks.map(\.participantAuthorIDs)), of: namedCount(publicationTasks.map(\.participantNames))),
            line("Uppgifter, deltagare", linked: linkedCount(currentTasks.map(\.participantAuthorIDs)), of: namedCount(currentTasks.map(\.participantNames))),
            line("Undervisningsuppgifter, deltagare", linked: linkedCount(currentTeachingTasks.map(\.participantAuthorIDs)), of: namedCount(currentTeachingTasks.map(\.participantNames))),
            line("Möten, deltagare", linked: linkedCount(currentMeetings.map(\.participantAuthorIDs)), of: namedCount(currentMeetings.map(\.participantNames))),
        ]
    }

    /// Links every course to its programme row by id, and gives the two renamed
    /// LiU course codes their historical validity. Runs once at startup.
    @discardableResult
    func migrateTeachingCatalogForRound2c() -> [String] {
        var report: [String] = []
        var courses = teachingCourses
        guard !courses.isEmpty else { return report }

        let programmes = courses.filter { $0.contextType == .programTrack }
        func programmeID(swedish: String, english: String) -> String? {
            let sv = PublicationDerivation.normalizedName(swedish)
            let en = PublicationDerivation.normalizedName(english)
            return programmes.first(where: {
                let psv = PublicationDerivation.normalizedName($0.programSv)
                let pen = PublicationDerivation.normalizedName($0.programEn)
                return (!sv.isEmpty && (psv == sv || pen == sv))
                    || (!en.isEmpty && (psv == en || pen == en))
            })?.id
        }

        var linked = 0
        for index in courses.indices where courses[index].contextType != .programTrack {
            guard courses[index].programID == nil else { continue }
            if let id = programmeID(swedish: courses[index].programSv, english: courses[index].programEn) {
                courses[index].programID = id
                linked += 1
            }
        }
        if linked > 0 { report.append("Kurser kopplade till sitt program: \(linked)") }

        // The stored code is the current one; the previous code is added with
        // validity through 2025 so assignments before 2026 show the right code.
        let renamed: [(current: String, previous: String)] = [
            ("8LA100", "8LAA10"),
            ("8LA110", "8LAA11")
        ]
        for index in courses.indices {
            let current = courses[index].courseCode.trimmingCharacters(in: .whitespacesAndNewlines)
            guard let rename = renamed.first(where: { $0.current == current }) else { continue }
            guard !courses[index].courseCodes.contains(where: { $0.code == rename.previous }) else { continue }
            // Round 11: only a course without its own code history gets one
            // (nothing, or just the current code without dates). A list the
            // user has edited is never replaced; this runs at every start.
            guard courses[index].courseCodes.allSatisfy({
                $0.code.trimmingCharacters(in: .whitespacesAndNewlines) == rename.current
                    && $0.validFrom.trimmedOrNil == nil
                    && $0.validTo.trimmedOrNil == nil
            }) else { continue }
            courses[index].courseCodes = [
                TeachingCourseCodeEntry(code: rename.previous, validTo: "2025-12-31"),
                TeachingCourseCodeEntry(code: rename.current, validFrom: "2026-01-01")
            ]
            report.append("\(courses[index].nameSv.nonEmpty ?? current): \(rename.previous) till 2025, \(rename.current) från 2026")
        }

        guard !report.isEmpty else { return report }
        for index in courses.indices { courses[index].normalize() }
        // A migration must never lose a record.
        guard courses.count == teachingCourses.count else { return [] }
        teachingCourses = courses
        return report
    }
}

extension GrantDataStore {
    /// F4/F6: a course linked to a programme takes its programme name from that
    /// programme row. Derived on every teaching refresh, so a renamed programme
    /// cannot leave stale names behind in courses, lists or exports.
    private func applyProgrammeNamesToLinkedCourses() {
        var names: [String: (sv: String, en: String)] = [:]
        for course in teachingCourses where course.contextType == .programTrack {
            names[course.id] = (course.programSv, course.programEn)
        }
        guard !names.isEmpty else { return }
        for index in teachingCourses.indices {
            guard teachingCourses[index].contextType != .programTrack,
                  let id = teachingCourses[index].programID,
                  let programme = names[id] else { continue }
            if teachingCourses[index].programSv != programme.sv {
                teachingCourses[index].programSv = programme.sv
            }
            if teachingCourses[index].programEn != programme.en {
                teachingCourses[index].programEn = programme.en
            }
        }
    }
}

// MARK: - F21 organization id repair
// Lives in this file because the collections it rewrites have private setters.

extension GrantDataStore {
    /// True when the id is not a UUID (the same test as the Data view's
    /// "Äldre ID:n" count). Empty ids are not counted.
    nonisolated static func isLegacyOrganizationID(_ id: String) -> Bool {
        guard let trimmed = id.trimmedOrNil else { return false }
        return UUID(uuidString: trimmed) == nil
    }

    /// F21 repair: some organizations were created with ids made from the
    /// name ("organization-university-of-sydney").
    /// Every organization whose id is not a UUID gets a new UUID, and every
    /// stored reference to the old id follows: applications (funder and fund
    /// manager), project principal organizations, teaching courses and
    /// components, doctoral candidates, the researchers' affiliations,
    /// employments and education, conference contributions, calendar travel,
    /// accommodation and meetings, task links, remembered selections, hidden
    /// warnings and hidden calendar events. Each old id is kept as an id alias.
    /// No record is added or removed and no text is changed. Organizations
    /// that already have a UUID are not touched, so running it again changes
    /// nothing. Returns the old → new ids (empty when nothing changed).
    @discardableResult
    func repairLegacyOrganizationIDs() -> [String: String] {
        var mapping: [String: String] = [:]
        var usedIDs = Set(organizations.map(\.id))
        for organization in organizations where Self.isLegacyOrganizationID(organization.id) {
            guard mapping[organization.id] == nil else { continue }
            var newID = UUID().uuidString
            while usedIDs.contains(newID) {
                newID = UUID().uuidString
            }
            usedIDs.insert(newID)
            mapping[organization.id] = newID
        }
        guard !mapping.isEmpty else { return [:] }

        let organizationCountBefore = organizations.count
        func mappedID(_ id: String) -> String {
            mapping[id] ?? id
        }
        func mappedOptionalID(_ id: String?) -> String? {
            guard let id else { return nil }
            return mapping[id] ?? id
        }
        func mappedIDs(_ ids: [String]) -> [String] {
            ids.map { mapping[$0] ?? $0 }
        }

        for index in organizations.indices {
            organizations[index].id = mappedID(organizations[index].id)
        }
        for index in applications.indices {
            applications[index].organizationID = mappedOptionalID(applications[index].organizationID)
            applications[index].applicationManagerID = mappedOptionalID(applications[index].applicationManagerID)
        }
        for index in projects.indices {
            for principalIndex in projects[index].principalOrganizations.indices {
                projects[index].principalOrganizations[principalIndex].organizationID =
                    mappedOptionalID(projects[index].principalOrganizations[principalIndex].organizationID)
            }
        }
        for index in teachingCourses.indices {
            teachingCourses[index].institutionID = mappedOptionalID(teachingCourses[index].institutionID)
        }
        for index in teachingComponents.indices {
            teachingComponents[index].institutionID = mappedOptionalID(teachingComponents[index].institutionID)
        }
        for index in doctoralCandidates.indices {
            doctoralCandidates[index].institutionID = mappedOptionalID(doctoralCandidates[index].institutionID)
        }
        for index in publicationAuthors.indices {
            for rowIndex in publicationAuthors[index].affiliations.indices {
                publicationAuthors[index].affiliations[rowIndex].organizationID =
                    mappedOptionalID(publicationAuthors[index].affiliations[rowIndex].organizationID)
            }
            for rowIndex in publicationAuthors[index].employments.indices {
                publicationAuthors[index].employments[rowIndex].organizationID =
                    mappedOptionalID(publicationAuthors[index].employments[rowIndex].organizationID)
            }
            for rowIndex in publicationAuthors[index].educationEntries.indices {
                publicationAuthors[index].educationEntries[rowIndex].organizationID =
                    mappedOptionalID(publicationAuthors[index].educationEntries[rowIndex].organizationID)
            }
        }
        for index in cvConferenceContributions.indices {
            cvConferenceContributions[index].congressOrganizationID =
                mappedOptionalID(cvConferenceContributions[index].congressOrganizationID)
        }
        // "Alla kopplingar via id": review assignments point to organizations too.
        for index in cvReviewEntries.indices {
            cvReviewEntries[index].organizationID = mappedOptionalID(cvReviewEntries[index].organizationID)
        }

        var updatedMetadata = editableMetadataSnapshot
        if var travel = updatedMetadata.calendarTravelRecords {
            for index in travel.indices {
                travel[index].congressOrganizationID = mappedID(travel[index].congressOrganizationID)
            }
            updatedMetadata.calendarTravelRecords = travel
        }
        if var accommodation = updatedMetadata.calendarAccommodationRecords {
            for index in accommodation.indices {
                accommodation[index].congressOrganizationID = mappedID(accommodation[index].congressOrganizationID)
            }
            updatedMetadata.calendarAccommodationRecords = accommodation
        }
        if var meetings = updatedMetadata.calendarMeetingRecords {
            for index in meetings.indices {
                meetings[index].organizationIDs = mappedIDs(meetings[index].organizationIDs)
                meetings[index].organizationID = mappedOptionalID(meetings[index].organizationID)
            }
            updatedMetadata.calendarMeetingRecords = meetings
        }
        if var tasks = updatedMetadata.taskItems {
            for taskIndex in tasks.indices {
                for linkIndex in tasks[taskIndex].links.indices {
                    if tasks[taskIndex].links[linkIndex].kind == .organization {
                        tasks[taskIndex].links[linkIndex].targetID = mappedID(tasks[taskIndex].links[linkIndex].targetID)
                    }
                    // The owner of a nested link (a congress) is its organization.
                    tasks[taskIndex].links[linkIndex].ownerID = mappedOptionalID(tasks[taskIndex].links[linkIndex].ownerID)
                }
            }
            updatedMetadata.taskItems = tasks
        }
        updatedMetadata.lastSelectedOrganizationID = mappedOptionalID(updatedMetadata.lastSelectedOrganizationID)
        updatedMetadata.lastSelectedManagerID = mappedOptionalID(updatedMetadata.lastSelectedManagerID)

        // Longest old id first, so an id that begins with another old id is
        // replaced as a whole before the shorter one is looked for.
        let orderedMapping: [(old: String, new: String)] = mapping
            .map { (old: $0.key, new: $0.value) }
            .sorted { lhs, rhs in
                lhs.old.utf8.count != rhs.old.utf8.count
                    ? lhs.old.utf8.count > rhs.old.utf8.count
                    : lhs.old < rhs.old
            }
        if let keys = updatedMetadata.hiddenDataQualityWarningKeys {
            updatedMetadata.hiddenDataQualityWarningKeys = keys.map {
                Self.warningKeyRewritingOrganizationIDs($0, orderedMapping: orderedMapping)
            }
        }
        if let keys = updatedMetadata.ignoredDuplicateWarningKeys {
            updatedMetadata.ignoredDuplicateWarningKeys = keys.map {
                Self.warningKeyRewritingOrganizationIDs($0, orderedMapping: orderedMapping)
            }
        }
        // Hidden calendar events and task badges are keyed "kind:orgID:…".
        func colonKeyRewritten(_ key: String) -> String {
            key.components(separatedBy: ":").map { mapping[$0] ?? $0 }.joined(separator: ":")
        }
        if let keys = updatedMetadata.calendarHiddenAutomaticEventKeys {
            updatedMetadata.calendarHiddenAutomaticEventKeys = keys.map { colonKeyRewritten($0) }
        }
        if let keys = updatedMetadata.calendarHiddenTaskBadgeIDs {
            updatedMetadata.calendarHiddenTaskBadgeIDs = keys.map { colonKeyRewritten($0) }
        }

        let migratedAt = ISO8601DateFormatter().string(from: Date())
        var aliases = updatedMetadata.idAliases ?? []
        for index in aliases.indices where aliases[index].entityType == "organization" {
            aliases[index].newID = mappedID(aliases[index].newID)
        }
        for (oldID, newID) in mapping.sorted(by: { $0.key < $1.key }) {
            aliases.append(IDAliasRecord(entityType: "organization", oldID: oldID, newID: newID, migratedAt: migratedAt))
        }
        updatedMetadata.idAliases = aliases
        metadata = Self.sanitizedMetadata(updatedMetadata)

        for (oldID, newID) in mapping {
            if lastSelectionOverrides[.organizations] == oldID {
                lastSelectionOverrides[.organizations] = newID
            }
            if let currentRoute = route,
               currentRoute.destination == .organizations,
               currentRoute.recordID == oldID {
                route = AppRoute(recordID: newID, destination: currentRoute.destination)
            }
        }

        assert(organizations.count == organizationCountBefore, "the repair never adds or removes an organization")
        // Fund managers and the id lookups first, so the application refresh
        // below finds the organizations and fund managers by their new ids.
        managers = derivedManagers(from: organizations)
        refreshOrganizationLookupCaches()
        refreshOrganizationsState()
        refreshOrganizationLookupCaches()
        invalidateSQLitePrimaryCongressReadCache()
        return mapping
    }

    /// Rewrites old organization ids inside a hidden data-quality or
    /// duplicate warning key. Those keys hold ids as length-prefixed parts
    /// ("33:organization-…"), so each rewritten part gets its new length, and
    /// the record ids of a duplicate key are sorted again, as the key is
    /// built. A key without an old id comes back unchanged.
    nonisolated static func warningKeyRewritingOrganizationIDs(
        _ key: String,
        orderedMapping: [(old: String, new: String)]
    ) -> String {
        guard orderedMapping.contains(where: { key.contains($0.old) }) else { return key }
        func replaced(_ text: String) -> String {
            var result = text
            for pair in orderedMapping where result.contains(pair.old) {
                result = result.replacingOccurrences(of: pair.old, with: pair.new)
            }
            return result
        }

        // A part is either plain text or a length-prefixed value.
        var parts: [(isPrefixed: Bool, text: String)] = []
        let bytes = Array(key.utf8)
        let colon = UInt8(ascii: ":")
        let bar = UInt8(ascii: "|")
        let zero = UInt8(ascii: "0")
        let nine = UInt8(ascii: "9")
        let keyMarker = Array("key:".utf8)
        let recordsMarker = Array("records:".utf8)
        var literal: [UInt8] = []
        var index = 0
        var atPartStart = true
        while index < bytes.count {
            if atPartStart {
                var digitEnd = index
                while digitEnd < bytes.count, digitEnd - index < 6, bytes[digitEnd] >= zero, bytes[digitEnd] <= nine {
                    digitEnd += 1
                }
                if digitEnd > index, digitEnd < bytes.count, bytes[digitEnd] == colon,
                   let length = Int(String(decoding: bytes[index..<digitEnd], as: UTF8.self)),
                   digitEnd + 1 + length <= bytes.count {
                    let valueStart = digitEnd + 1
                    if !literal.isEmpty {
                        parts.append((isPrefixed: false, text: String(decoding: literal, as: UTF8.self)))
                        literal = []
                    }
                    parts.append((isPrefixed: true, text: String(decoding: bytes[valueStart..<(valueStart + length)], as: UTF8.self)))
                    index = valueStart + length
                    atPartStart = true
                    continue
                }
            }
            let byte = bytes[index]
            literal.append(byte)
            index += 1
            // A new part starts after "|" and after "key:" or "records:".
            atPartStart = byte == bar
                || Array(literal.suffix(keyMarker.count)) == keyMarker
                || Array(literal.suffix(recordsMarker.count)) == recordsMarker
        }
        if !literal.isEmpty {
            parts.append((isPrefixed: false, text: String(decoding: literal, as: UTF8.self)))
        }

        var rewritten = parts.map { (isPrefixed: $0.isPrefixed, text: replaced($0.text)) }
        if key.hasPrefix("duplicate-warning:v1|"),
           let recordsIndex = rewritten.lastIndex(where: { !$0.isPrefixed && $0.text.hasSuffix("records:") }),
           recordsIndex + 1 < rewritten.count,
           rewritten[(recordsIndex + 1)...].allSatisfy({ $0.isPrefixed }) {
            let recordIDs = Set(rewritten[(recordsIndex + 1)...].map { $0.text }).sorted()
            rewritten.removeSubrange((recordsIndex + 1)...)
            rewritten.append(contentsOf: recordIDs.map { (isPrefixed: true, text: $0) })
        }
        return rewritten
            .map { $0.isPrefixed ? "\($0.text.utf8.count):\($0.text)" : $0.text }
            .joined()
    }
}

// MARK: - Round 7: official organization names and salary colours
// Lives in this file because publicationAuthors, cvReviewEntries and metadata
// have private setters.

extension GrantDataStore {
    /// Round 7: writes the linked organization's and unit's official names
    /// into every linked affiliation, employment and education row (see
    /// `OrganizationTree.applyingOfficialNames`). Not undoable; used when the
    /// app starts and by the snapshot trial run. Rows without a link keep
    /// their text. Running it again changes nothing. If a researcher or a row
    /// would be lost, nothing is changed.
    @discardableResult
    func applyOfficialOrganizationNamesToResearcherRows() -> OfficialOrganizationNameReport {
        let result = OrganizationTree.applyingOfficialNames(to: publicationAuthors, organizations: organizations)
        guard !result.report.isEmpty else { return result.report }
        guard result.authors.count == publicationAuthors.count,
              zip(result.authors, publicationAuthors).allSatisfy({ updated, previous in
                  updated.id == previous.id
                      && updated.affiliations.count == previous.affiliations.count
                      && updated.employments.count == previous.employments.count
                      && updated.educationEntries.count == previous.educationEntries.count
              }) else {
            return OfficialOrganizationNameReport()
        }
        publicationAuthors = result.authors
        refreshPublicationAuthorsOnly()
        return result.report
    }

    /// Round 7: the start-up step. When linked rows show another spelling
    /// than their organization or unit (for example after a row was linked
    /// to a unit, or after a row's text was edited), a safety backup is
    /// made and the official names are written and saved. Nothing happens
    /// when every linked row already shows the official names.
    func applyOfficialOrganizationNamesAtLaunch() {
        let preview = OrganizationTree.applyingOfficialNames(to: publicationAuthors, organizations: organizations)
        guard !preview.report.isEmpty else {
            appendStartupDiagnostic("bootstrap:officialOrganizationNames unchanged")
            return
        }
        let previousAuthors = publicationAuthors
        do {
            try createForcedBackupSnapshot(prefix: "pre-official-organization-names")
            let report = applyOfficialOrganizationNamesToResearcherRows()
            guard !report.isEmpty else { return }
            try persist(.publicationAuthors)
            appendStartupDiagnostic(
                "bootstrap:officialOrganizationNames affiliations=\(report.affiliations) employments=\(report.employments) education=\(report.educationEntries)"
            )
        } catch {
            if publicationAuthors != previousAuthors {
                publicationAuthors = previousAuthors
                refreshPublicationAuthorsOnly()
            }
            appendStartupDiagnostic("bootstrap:officialOrganizationNames failed error=\(error.localizedDescription)")
        }
    }

    /// Round 7: the one-time data changes, each run once per database and
    /// then recorded in the migration log (so a later edit by the user is
    /// never overwritten). Called from `migrateRecordsIfNeeded()`. Returns
    /// true when anything changed.
    @discardableResult
    func runRound7OneTimeDataMigrations() -> Bool {
        var didChange = false
        didChange = runRound7MigrationOnce(
            key: "round7-salary-source-colors",
            details: "Salary sources store their colour and their Swedish and English names instead of relying on built-in names."
        ) {
            migrateSalarySourceColorsForRound7()
        } || didChange
        didChange = runRound7MigrationOnce(
            key: "round7-clinical-teaching-checkbox",
            details: "Courses that the organization-name word rule placed under clinical teaching get the checkbox Klinisk undervisning ticked."
        ) {
            migrateClinicalTeachingCheckboxForRound7()
        } || didChange
        return didChange
    }

    /// Round 7, one-time migration (user decision): clinical teaching is a
    /// checkbox on the course instead of a word in the organization name.
    /// Ticks the checkbox for every course that the word rule (the words in
    /// Settings, "region" by default) placed under "Klinisk undervisning", so
    /// no course moves. Returns true when a course changed.
    @discardableResult
    func migrateClinicalTeachingCheckboxForRound7() -> Bool {
        let settings = workflowDefaultSettings
        var courses = teachingCourses
        var ticked = 0
        for index in courses.indices where courses[index].resolvesToClinicalTeachingByInstitutionWord(settings: settings) {
            courses[index].isClinicalTeaching = true
            ticked += 1
        }
        // A migration must never lose a record.
        guard ticked > 0, courses.count == teachingCourses.count else { return false }
        teachingCourses = courses
        appendStartupDiagnostic("migration:clinicalTeachingCheckbox ticked=\(ticked)")
        return true
    }

    private func runRound7MigrationOnce(key: String, details: String, _ body: () -> Bool) -> Bool {
        guard !(metadata.migrationLog ?? []).contains(where: { $0.key == key }) else { return false }
        _ = body()
        var updated = editableMetadataSnapshot
        var entries = updated.migrationLog ?? []
        entries.append(
            DataSchemaMigrationLogEntry(
                id: key,
                key: key,
                appliedAt: ISO8601DateFormatter().string(from: Date()),
                details: details
            )
        )
        updated.migrationLog = entries
        metadata = updated
        return true
    }

    /// Round 7, one-time migration: every salary source gets the colour it
    /// was drawn with until now and the built-in Swedish/English names it
    /// was shown with (see `SalarySource.migratedForStoredColorsAndNames`),
    /// so nothing changes on screen. Returns true when a source changed.
    @discardableResult
    func migrateSalarySourceColorsForRound7() -> Bool {
        let baseline = editableMetadataSnapshot
        guard let sources = baseline.salarySources else { return false }
        let migrated = SalarySource.migratedForStoredColorsAndNames(sources)
        guard migrated.count == sources.count, migrated != sources else { return false }
        var updated = baseline
        updated.salarySources = migrated
        metadata = updated
        return true
    }
}

// MARK: - Round 8: OH rule per funder
// Lives in this file because organizations and managers have private setters.

extension GrantDataStore {
    /// Round 8: the one-time data changes, run once per database and then
    /// recorded in the migration log (same pattern as round 7). Called from
    /// `migrateRecordsIfNeeded()`. Returns true when anything changed.
    @discardableResult
    func runRound8OneTimeDataMigrations() -> Bool {
        let clearedCheckbox = runRound7MigrationOnce(
            key: "round8-funder-max-overhead",
            details: "The old no-overhead checkbox on salary calculators is cleared; no cap is guessed. The checkbox is no longer stored."
        ) {
            migrateLegacyOverheadCheckboxToFunderCapForRound8()
        }
        let movedMaxOverhead = runRound7MigrationOnce(
            key: "round8-funder-overhead-rule",
            details: "Max OH (%) on grant providers becomes the OH rule: a value gives \"at most value %\", 0 gives \"no OH\". Max OH is no longer stored."
        ) {
            migrateFunderMaxOverheadToOverheadRuleForRound8()
        }
        return clearedCheckbox || movedMaxOverhead
    }

    /// Round 8, one-time migration (user decision): the earlier grant
    /// provider setting "Max OH (%)" becomes the "OH-regel": a value gives
    /// "Högst value %", 0 gives "Ingen OH", no value gives nothing (the fund
    /// manager's full OH). A rule already set is kept. The old value is then
    /// cleared so it is no longer stored. No organization is chosen by name.
    /// Returns true when an organization changed; running it again changes
    /// nothing.
    @discardableResult
    func migrateFunderMaxOverheadToOverheadRuleForRound8() -> Bool {
        var updated = organizations
        var moved = 0
        for index in updated.indices {
            guard let legacy = updated[index].legacyMaxOverheadPercent else { continue }
            if updated[index].overheadRule == nil {
                updated[index].overheadRule = FunderOverheadRule.migrated(fromLegacyMaxOverheadPercent: legacy)
            }
            updated[index].legacyMaxOverheadPercent = nil
            moved += 1
        }
        // A migration must never lose a record.
        guard moved > 0, updated.count == organizations.count else { return false }
        organizations = updated
        managers = derivedManagers(from: organizations)
        refreshOrganizationLookupCaches()
        rebuildOrganizationRowSnapshots()
        appendStartupDiagnostic("migration:funderOverheadRule moved=\(moved)")
        return true
    }

    /// Round 8, one-time migration (user decision): the old checkbox that
    /// left overhead out of an organization's salary calculator is replaced
    /// by the grant provider setting "OH-regel". The checkbox never said
    /// which funder it meant, so no rule is guessed; it is only cleared
    /// (older data still decodes, but it is no longer written). No
    /// organization is chosen by name. Returns true when an organization
    /// changed; running it again changes nothing.
    @discardableResult
    func migrateLegacyOverheadCheckboxToFunderCapForRound8() -> Bool {
        var updated = organizations
        var cleared = 0
        for index in updated.indices {
            guard var calculator = updated[index].salaryCalculator, calculator.legacyExcludesOverhead else { continue }
            // The old checkbox sat on an employer's salary calculator and never
            // said which funder it meant, so no cap is guessed: the user sets
            // the OH rule on the funder.
            calculator.legacyExcludesOverhead = false
            updated[index].salaryCalculator = calculator
            cleared += 1
        }
        // A migration must never lose a record.
        guard cleared > 0, updated.count == organizations.count else { return false }
        organizations = updated
        managers = derivedManagers(from: organizations)
        refreshOrganizationLookupCaches()
        rebuildOrganizationRowSnapshots()
        appendStartupDiagnostic("migration:funderMaxOverhead cleared=\(cleared)")
        return true
    }
}

// MARK: - Round 10: OH numbers copied into records
// Lives in this file because organizations and applications have private setters.

extension GrantDataStore {
    /// Round 10: the one-time data changes, run once per database and then
    /// recorded in the migration log. Called from `migrateRecordsIfNeeded()`.
    /// Returns true when anything changed.
    @discardableResult
    func runRound10OneTimeDataMigrations() -> Bool {
        let filledManagers = runRound7MigrationOnce(
            key: "round10-manager-overhead",
            details: "Fund managers without \"OH som tas ut\" get this year's OH from their own salary calculator. Nothing else changes."
        ) {
            migrateManagerOverheadPercentForRound10()
        }
        let records = runRound7MigrationOnce(
            key: "round10-record-overhead",
            details: "Unlocked records with the status \"Att söka\" or \"Ej sökt\" get copies of the funder's and the fund manager's OH numbers. Locked records and records already applied for are not changed."
        ) {
            migrateRecordOverheadDefaultsForRound10()
        }
        return filledManagers || records
    }

    /// Round 10, one-time (user decision 2026-09-29): a fund manager whose
    /// "OH som tas ut" is empty gets the OH of its own salary calculator for
    /// today, when it has one. A value already set is kept. No organization
    /// is chosen by name. Running it again changes nothing.
    @discardableResult
    func migrateManagerOverheadPercentForRound10(on date: Date = Date()) -> Bool {
        var updated = organizations
        var filled = 0
        for index in updated.indices where updated[index].roles.contains(.fundManager) {
            guard updated[index].managerOverheadPercent == nil,
                  let percent = updated[index].employerSalaryCalculator?.overheadPercent(on: date) else { continue }
            updated[index].managerOverheadPercent = min(100, max(0, percent))
            filled += 1
        }
        // A migration must never lose a record.
        guard filled > 0, updated.count == organizations.count else { return false }
        organizations = updated
        managers = derivedManagers(from: organizations)
        refreshOrganizationLookupCaches()
        rebuildOrganizationRowSnapshots()
        appendStartupDiagnostic("migration:managerOverheadPercent filled=\(filled)")
        return true
    }

    /// Round 10, one-time (user decision 2026-09-29): only records that are
    /// unlocked and not yet applied for ("Att söka", "Ej sökt") get copies of
    /// the funder's and the fund manager's OH numbers, as a new record would.
    /// Locked records and records already applied for ("Väntar svar",
    /// decided) are left exactly as they are; their new fields stay empty.
    /// Running it again changes nothing.
    @discardableResult
    func migrateRecordOverheadDefaultsForRound10() -> Bool {
        var updated = applications
        var filled = 0
        for index in updated.indices {
            let record = updated[index]
            // The status as shown (derived from the dates), not the stored text.
            guard !record.isEditingLocked,
                  record.isNotYetApplied,
                  record.funderMaxOverheadPercent == nil,
                  record.managerOverheadPercent == nil else { continue }
            let manager = linkedFundManager(of: record).flatMap { organization(id: $0.id) }
            let defaults = GrantOverheadDefaults.resolved(funder: linkedFunder(of: record), manager: manager)
            guard defaults.funderMaxPercent != nil || defaults.managerPercent != nil else { continue }
            updated[index].applyOverheadDefaults(defaults)
            filled += 1
        }
        // A migration must never lose a record.
        guard filled > 0, updated.count == applications.count else { return false }
        applications = updated
        appendStartupDiagnostic("migration:recordOverheadDefaults filled=\(filled)")
        return true
    }
}

// MARK: - Round 11: data safety
// Lives in this file because organizations and applications have private setters.

extension GrantDataStore {
    /// Round 11: the one-time data changes, run once per database and then
    /// recorded in the migration log. Called from `migrateRecordsIfNeeded()`.
    /// Returns true when anything changed.
    @discardableResult
    func runRound11OneTimeDataMigrations() -> Bool {
        runRound7MigrationOnce(
            key: "round11-hidden-salary-calculators",
            details: "Salary calculators on organizations not marked as employer are removed. They were never shown, and their numbers leaked into OH suggestions. Employers keep theirs."
        ) {
            removeHiddenSalaryCalculatorsForRound11()
        }
    }

    /// Round 11, one-time (user decision 2026-09-30): a salary calculator is
    /// only shown for an organization marked as employer. Calculators left on
    /// other organizations are removed. The organization chosen as the
    /// application salary calculator in Settings keeps its calculator. No
    /// organization is chosen by name. Running it again changes nothing.
    @discardableResult
    func removeHiddenSalaryCalculatorsForRound11() -> Bool {
        var updated = organizations
        var removed = 0
        for index in updated.indices {
            let organization = updated[index]
            guard organization.salaryCalculator != nil,
                  !organization.roles.contains(.employer),
                  !organization.usesAsApplicationSalaryCalculator else { continue }
            updated[index].salaryCalculator = nil
            removed += 1
        }
        // A migration must never lose a record.
        guard removed > 0, updated.count == organizations.count else { return false }
        organizations = updated
        managers = derivedManagers(from: organizations)
        refreshOrganizationLookupCaches()
        rebuildOrganizationRowSnapshots()
        appendStartupDiagnostic("migration:hiddenSalaryCalculators removed=\(removed)")
        return true
    }
}
